# ============================================================
# STEP TIMING (printed right after each step finishes - no summary)
# ============================================================

def format_duration(seconds):
    if seconds >= 60:
        minutes, rest = divmod(seconds, 60)
        return f"{int(minutes)}m {rest:04.1f}s"
    return f"{seconds:.1f}s"


def record_timing(label, seconds, level=0):
    """Print '[   6.1s] Latitude' in the terminal the moment a step finishes."""
    print(f"{'  ' * level}[{format_duration(float(seconds)):>8}] {label}")


def lap_timer(level, measure=False):
    """lap('label') prints the time since the previous lap (or since creation). S405: measure - every lap also
    says what its time was made of (work_split_note)."""
    last = [time.perf_counter(), time.thread_time(), time.process_time()]

    def lap(label):
        now = time.perf_counter()
        record_timing(label, now - last[0], level)
        note = (work_split_note(last[0], last[1], last[2], now) if measure
                else ocr_step_note(last[0], now))          # S400: what the step waited for in the OCR
        if note:
            print(f"{'  ' * (level + 1)}{note}")
        last[:] = [time.perf_counter(), time.thread_time(), time.process_time()]
    return lap


@contextmanager
def timed(label, level=0, measure=False):
    """S405: measure - the step also says what its time was made of (work_split_note)."""
    started, cpu, process_cpu = time.perf_counter(), time.thread_time(), time.process_time()
    try:
        yield
    finally:
        ended = time.perf_counter()
        record_timing(label, ended - started, level)
        note = (work_split_note(started, cpu, process_cpu, ended) if measure
                else ocr_step_note(started, ended))        # S400: what the step waited for in the OCR
        if note:
            print(f"{'  ' * (level + 1)}{note}")


def work_split_note(started, cpu_started, process_cpu_started, ended):
    """S405 (measuring only): a step's time split into its OCR (per OCR process: reading, waiting behind other
    calls, sending the pictures), its own work (this thread's processor time) and the rest - waiting for other
    threads or locks (Python runs one thread at a time); plus how much processor time the program's other
    threads used meanwhile, so the rest can be told apart: busy other threads = it waited for its turn."""
    wall = ended - started
    own = time.thread_time() - cpu_started
    others = max(0.0, time.process_time() - process_cpu_started - own)
    me = ocr_thread_mark()
    with OCR_LEDGER_LOCK:
        calls = [c for c in OCR_LEDGER if c["thread"] == me and started <= c["sent"] and c["back"] <= ended + 1e-6]
    ocr = sum(c["back"] - c["sent"] for c in calls)
    parts = []
    for role in ("easy", "paddle"):
        mine = [c for c in calls if c["role"] == role]
        if mine:
            moving = sum(max(0.0, c["back"] - c["sent"] - c["queued"] - c["run"]) for c in mine)
            parts.append(f"{OCR_ROLE_NAMES[role]} {len(mine)}: {sum(c['run'] for c in mine):.2f} reading, "
                         f"{sum(c['queued'] for c in mine):.2f} waiting, {moving:.2f} sending")
    rest = max(0.0, wall - ocr - own)
    return (f"WORK SPLIT: {wall:.2f} s = OCR {ocr:.2f} s" + (f" ({'; '.join(parts)})" if parts else "")
            + f" + its own work {own:.2f} s + waiting for other threads / locks {rest:.2f} s "
            f"(the program's other threads used {others:.2f} s of processor meanwhile) (S405)")


# Time spent inside one step, split by the kind of work (S1). The OCR / language-model /
# word-list functions add their own time here; read_notes_line clears it before an
# English correction pass (or the language-model step) and prints the split after it.
WORK_TIMES = {}                     # bucket -> [seconds, how many]
WORK_BUCKETS = [
    ("word_fast", "word pictures - 4 quick reads"),
    ("word_full", "word pictures - full read set ('Fast OCR uncertain')"),
    ("letter", "letter crops - 4 reads each"),
    ("lm", "language model sentence scores"),
    ("wordlist", "English word-list searches"),
]


def add_work_time(bucket, seconds, count=1):
    entry = WORK_TIMES.setdefault(bucket, [0.0, 0])
    entry[0] += seconds
    entry[1] += count


def print_work_breakdown(total_seconds, level):
    """'inside:' lines under a step's time: each kind of work with how many and how
    long, then the rest (candidate scoring, letter splitting, geometry, logic). Only
    for steps of 0.5 s or more, so quick steps keep a short log."""
    if total_seconds < 0.5:
        return
    counted = 0.0
    for bucket, label in WORK_BUCKETS:
        seconds, count = WORK_TIMES.get(bucket, (0.0, 0))
        if count:
            counted += seconds
            record_timing(f"inside: {label} ({count})", seconds, level)
    record_timing("inside: everything else (candidate scoring, letter splitting, geometry, logic)",
                  max(0.0, total_seconds - counted), level)


# ------------------------------------------------------------
# S46: console output in chunks (no log file - S69)
# ------------------------------------------------------------
# The terminal on Windows is slow at drawing many small pieces of text, and this
# program prints thousands of lines. Everything printed (stdout and stderr, in the
# order it was printed) is collected and sent to the terminal in chunks - at the
# latest every LOG_FLUSH_SECONDS, so the terminal still follows the run.
# S69: all of the program's own output (OCR reads, decisions, timings, summaries)
# is shown; only the OCR libraries' own notices are left out (TERMINAL_NOISE).
# Text printed by their C++ code (the 'W1002 ... gpu_resources' style lines) does
# not go through Python and still appears.
LOG_FLUSH_SECONDS = 0.2
LOG_FLUSH_BYTES = 16384
TERMINAL_NOISE = re.compile(          # library notices, not the program's output
    r"Warning|warnings\.warn|Loading weights|ccache|Using cached files|Model files already exist"
    r"|Creating model|\[transformers\]|UNEXPECTED|^Key\s+\||^-+\+-"
    r"|HTTP Request: \w+ https://huggingface\.co/")   # S144: the language model's update checks
# S144: the web requests the Hugging Face library makes to check the language model is up
# to date are logged at INFO level by 'httpx' - shown once PaddleOCR turns INFO logging on.
# Only those routine request lines are kept out; a warning or error from them still shows.
logging.getLogger("httpx").setLevel(logging.WARNING)


class BufferedConsole:
    """Stands in for sys.stdout / sys.stderr: collects text and writes it to the
    terminal in chunks (by size, by time, and on flush()), leaving out the
    libraries' notices."""

    def __init__(self, console, lock, shared):
        self.console = console
        self.lock = lock
        self.shared = shared              # {"pending": [], "size": int, "last": float, "chunks": int, "seconds": float}
        self.encoding = getattr(console, "encoding", "utf-8")
        self.errors = getattr(console, "errors", "replace")
        self.partial = {}                 # thread -> start of a line not finished yet

    def for_terminal(self, text):
        """Whole lines only, without the libraries' notices."""
        thread = threading.get_ident()
        lines = (self.partial.pop(thread, "") + text).split("\n")
        if lines[-1]:
            self.partial[thread] = lines[-1]
        keep = [line.split("\r")[-1] for line in lines[:-1]]        # progress bars redraw with \r
        return "".join(line + "\n" for line in keep if not TERMINAL_NOISE.search(line))

    def write(self, text):
        if not text:
            return 0
        given = len(text)
        captures = OUTPUT_CAPTURES.get(threading.get_ident())
        if captures:                            # S70: held back, printed (or not) afterwards
            captures[-1].append(text)
            return given
        with self.lock:
            text = self.for_terminal(text)
            if not text:
                return given
            self.shared["pending"].append((self.console, text))
            self.shared["size"] += len(text)
            if (self.shared["size"] >= LOG_FLUSH_BYTES
                    or time.perf_counter() - self.shared["last"] >= LOG_FLUSH_SECONDS):
                self._send()
        return given

    def _send(self):
        """Write what is waiting to the terminal (caller holds the lock)."""
        pending = self.shared["pending"]
        if not pending:
            self.shared["last"] = time.perf_counter()
            return
        started = time.perf_counter()
        # neighbouring pieces for the same stream go out as one write
        stream, chunk = pending[0][0], []
        for target, text in pending:
            if target is not stream:
                self._out(stream, "".join(chunk))
                stream, chunk = target, []
            chunk.append(text)
        self._out(stream, "".join(chunk))
        self.shared["pending"] = []
        self.shared["size"] = 0
        self.shared["last"] = time.perf_counter()
        self.shared["seconds"] += self.shared["last"] - started

    def _out(self, stream, text):
        if not text:
            return
        try:
            stream.write(text)
            stream.flush()
        except Exception:
            pass
        self.shared["chunks"] += 1

    def flush(self):
        with self.lock:
            self._send()

    def isatty(self):
        try:
            return self.console.isatty()
        except Exception:
            return False

    def fileno(self):
        return self.console.fileno()

    def __getattr__(self, name):
        return getattr(self.console, name)


CONSOLE_STATE = {"shared": None}
OUTPUT_CAPTURES = {}                  # thread -> stack of text lists held back (S70)
NOTES_LINE_CONTEXT = {"line": 0}      # which Notes line is being read (S70)
PRINTED_WORD_BLOCKS = {}              # (Notes line, word) -> its printed checks, without fast-read notes
REPEAT_IGNORED = re.compile(r"^\s*(FAST OCR consensus accepted|STRONG FAST OCR|BATCH OCR CHECK"
                            r"|crop \d+ \(\d+x\d+ px\), version |picture \d+ \(\d+x\d+ px\): together )")  # S72/S59


def printed_once(units, word_of):
    """S70: yields the English-correction units one by one, holding back what each
    prints. A word whose printed checks are exactly what the same word printed in this
    Notes line's earlier pass (fast-read and batch-check notes aside) gets one line
    instead of the whole repeat."""
    thread = threading.get_ident()
    for unit in units:
        stack = OUTPUT_CAPTURES.setdefault(thread, [])
        stack.append([])
        try:
            yield unit
        finally:
            text = "".join(stack.pop() if stack else [])
            if not stack:
                OUTPUT_CAPTURES.pop(thread, None)
            key = (NOTES_LINE_CONTEXT["line"], word_of(unit))
            compared = "\n".join(line for line in text.split("\n") if not REPEAT_IGNORED.search(line))
            if compared.strip() and PRINTED_WORD_BLOCKS.get(key) == compared:
                print(f"\n{word_of(unit)}: the same reads, checks and result as printed above for it - "
                      f"not printed again ({text.count(chr(10))} lines)")
            else:
                PRINTED_WORD_BLOCKS[key] = compared
                if text:
                    sys.stdout.write(text)


def start_buffered_console():
    """Installs BufferedConsole for stdout and stderr and starts a small background
    timer that sends waiting text out every LOG_FLUSH_SECONDS (so a line printed just
    before a long GPU step still shows straight away)."""
    import atexit
    lock = threading.RLock()
    shared = {"pending": [], "size": 0, "last": time.perf_counter(), "chunks": 0, "seconds": 0.0}
    CONSOLE_STATE["shared"] = shared
    out = BufferedConsole(sys.stdout, lock, shared)
    err = BufferedConsole(sys.stderr, lock, shared)
    sys.stdout, sys.stderr = out, err

    def ticker():
        while True:
            time.sleep(LOG_FLUSH_SECONDS)
            try:
                with lock:
                    if shared["pending"] and time.perf_counter() - shared["last"] >= LOG_FLUSH_SECONDS:
                        out._send()
            except Exception:
                pass

    threading.Thread(target=ticker, daemon=True).start()
    atexit.register(out.flush)


def print_console_stats():
    """After a document is ready: how the terminal output went out."""
    shared = CONSOLE_STATE.get("shared")
    if shared:
        print(f"TERMINAL: output sent in {shared['chunks']} chunk(s), {shared['seconds']:.1f} s spent writing it")
    try:
        sys.stdout.flush()
    except Exception:
        pass


