# =========================
# TEXT FUNCTIONS
# =========================

def normalize(text):

    return " ".join(
        text.split()
    ).strip().lower()


def get_lines(page):

    words = page.get_text("words")

    grouped = {}

    for word in words:

        x0, y0, x1, y1, text, block_no, line_no, word_no = word

        key = (
            block_no,
            line_no
        )

        if key not in grouped:
            grouped[key] = []

        grouped[key].append(word)

    lines = []

    for key, line_words in grouped.items():

        # Sort words left to right
        line_words.sort(
            key=lambda w: w[0]
        )

        text = " ".join(
            w[4]
            for w in line_words
        )

        x0 = min(w[0] for w in line_words)
        y0 = min(w[1] for w in line_words)
        x1 = max(w[2] for w in line_words)
        y1 = max(w[3] for w in line_words)

        lines.append({
            "text": text.strip(),
            "x0": x0,
            "y0": y0,
            "x1": x1,
            "y1": y1,
        })

    # Top to bottom, then left to right
    lines.sort(
        key=lambda line: (
            line["y0"],
            line["x0"]
        )
    )

    return lines


def find_heading(lines, heading):

    target = normalize(heading)

    for line in lines:

        if normalize(line["text"]) == target:
            return line

    return None


def extend_value_lines(lines, first_line):
    """A wrapped answer: the lines straight below the first one that start at the
    same left edge with no gap between them are joined into one value."""
    merged = dict(first_line)
    height = max(1.0, first_line["y1"] - first_line["y0"])
    while True:
        following = [
            line for line in lines
            if abs(line["x0"] - merged["x0"]) <= 3
            and 0 <= line["y0"] - merged["y1"] <= height * 0.8
        ]
        if not following:
            return merged
        nxt = min(following, key=lambda line: line["y0"])
        merged = {
            **merged,
            "text": f"{merged['text']} {nxt['text']}".strip(),
            "x1": max(merged["x1"], nxt["x1"]),
            "y1": nxt["y1"],
        }


def find_value_below(lines, heading_line):

    candidates = []

    heading_center_x = (
        heading_line["x0"]
        + heading_line["x1"]
    ) / 2

    heading_width = (
        heading_line["x1"]
        - heading_line["x0"]
    )

    for line in lines:

        # Must be underneath heading
        if line["y0"] <= heading_line["y1"]:
            continue

        vertical_distance = (
            line["y0"]
            - heading_line["y1"]
        )

        # Ignore anything too far below
        if vertical_distance > MAX_VERTICAL_DISTANCE:
            continue

        line_center_x = (
            line["x0"]
            + line["x1"]
        ) / 2

        allowed_left = heading_line["x0"] - HORIZONTAL_PADDING
        allowed_right = heading_line["x1"] + HORIZONTAL_PADDING

        overlaps_heading = (
            line["x1"] >= allowed_left
            and
            line["x0"] <= allowed_right
        )

        center_close = (
            abs(line_center_x - heading_center_x)
            <= max(heading_width, 100)
        )

        if overlaps_heading or center_close:

            candidates.append(
                (
                    vertical_distance,
                    abs(line_center_x - heading_center_x),
                    line
                )
            )

    if not candidates:
        return None

    candidates.sort(
        key=lambda item: (
            item[0],
            item[1]
        )
    )

    return candidates[0][2]


# =========================
# STYLE / COLOR HELPERS
# (used for Additional Notes + section detection)
# =========================

def int_to_rgb(color_int):

    return (
        (color_int >> 16) & 255,
        (color_int >> 8) & 255,
        color_int & 255,
    )


def is_blue_text(rgb):
    # Section header text is dark blue (e.g. #1B4F72).
    r, g, b = rgb
    return b >= 90 and (b - r) >= 40 and b >= g


def is_gray_text(rgb):
    # Field labels ("Additional Notes", "Is pipe exposed...?") are gray.
    r, g, b = rgb
    return (max(rgb) - min(rgb)) <= 20 and 90 <= r <= 200


def _page_memo(page):
    """dataC: what was already worked out for this page while its document is open (the document is
    never changed while it is read) - kept on the open document itself, so it goes when the document
    goes and a document opened again starts fresh."""
    document = page.parent
    memo = getattr(document, "_dataC_page_memo", None)
    if memo is None:
        memo = {}
        try:
            document._dataC_page_memo = memo
        except Exception:
            return {}
    return memo.setdefault(page.number, {})


def page_drawings(page):
    """dataC: page.get_drawings() once per page of an open document (read-only use everywhere)."""
    memo = _page_memo(page)
    drawings = memo.get("drawings")
    if drawings is None:
        drawings = memo["drawings"] = page.get_drawings()
    return drawings


def page_display_list(page):
    """dataC: the page's display list (what page.get_pixmap makes and throws away on every call) once per
    page of an open document - each clip rendered from it is the same picture page.get_pixmap gives."""
    memo = _page_memo(page)
    display_list = memo.get("display_list")
    if display_list is None:
        display_list = memo["display_list"] = page.get_displaylist(annots=True)
    return display_list


def page_text_dict(page):
    """dataC: page.get_text("dict") once per page of an open document (read-only use)."""
    memo = _page_memo(page)
    data = memo.get("dict")
    if data is None:
        data = memo["dict"] = page.get_text("dict")
    return data


def is_form_hint_text(rgb):
    """dataC (accuracy fix A1): the 6000 form's own green hint lines ('Complete Section D', 'Class Location is
    not applicable for liquids', 'Note: ERF less than 1 ...') - dark green, never a filled-in value."""
    r, g, b = rgb
    return g >= 60 and g - r >= 40 and g - b >= 20


def get_styled_lines(page):
    """
    Like get_lines(), but also records text color and boldness,
    which get_text("words") does not provide.
    """

    data = page_text_dict(page)

    lines = []

    for block in data["blocks"]:

        # 0 = text block (1 = image)
        if block.get("type") != 0:
            continue

        for line in block["lines"]:

            spans = [s for s in line["spans"] if s["text"].strip()]

            if not spans:
                continue

            text = " ".join("".join(s["text"] for s in spans).split())

            # Dominant color = color covering the most characters
            color_counts = Counter()
            for s in spans:
                color_counts[s["color"]] += len(s["text"].strip())
            main_color = color_counts.most_common(1)[0][0]

            bold = any(
                (s["flags"] & 16) or ("bold" in s["font"].lower())
                for s in spans
            )

            x0, y0, x1, y1 = line["bbox"]

            lines.append({
                "text": text,
                "x0": x0,
                "y0": y0,
                "x1": x1,
                "y1": y1,
                "rgb": int_to_rgb(main_color),
                "bold": bold,
            })

    lines.sort(key=lambda l: (round(l["y0"], 1), l["x0"]))

    return lines


def get_gray_bars(page):
    """
    Finds the light-gray filled bars that section headers sit on.
    """

    bars = []

    for drawing in page_drawings(page):

        fill = drawing.get("fill")

        if not fill:
            continue

        r, g, b = fill[:3]

        is_light_gray = (
            (max(r, g, b) - min(r, g, b)) <= 0.05
            and 0.80 <= r <= 0.97
        )

        rect = drawing["rect"]

        is_bar_shaped = (
            rect.width > page.rect.width * 0.3
            and rect.height < 60
        )

        if is_light_gray and is_bar_shaped:
            bars.append(rect)

    return bars


def get_page_shapes(page):
    """
    Returns the bounding rectangles of every drawn shape on the page
    (box borders, lines, header bars), skipping pure white backgrounds.
    """

    shapes = []

    for drawing in page_drawings(page):

        fill = drawing.get("fill")
        stroke = drawing.get("color")

        # A white fill with no border is just a background, not an edge
        is_white_fill_only = (
            fill is not None
            and min(fill[:3]) >= 0.98
            and stroke is None
        )

        if is_white_fill_only:
            continue

        shapes.append(drawing["rect"])

    return shapes


def find_box_bottom(shapes, ref_line, page_height):
    """
    Finds where the section box around ref_line ends.

    Looks for the nearest edge below the line that spans across it:
      - the bottom of a box/border that contains the line
        (the rounded section border), or
      - the top of any line/bar drawn below it
        (a separator line or the next section's header bar).
    """

    bottom = page_height

    for rect in shapes:

        spans_line = (
            rect.x0 <= ref_line["x0"] + 5
            and rect.x1 >= ref_line["x1"] - 5
        )

        if not spans_line:
            continue

        # Shape entirely below the line -> its top edge is a boundary
        if rect.y0 >= ref_line["y1"] - 1:
            bottom = min(bottom, rect.y0)

        # Shape wraps around the line -> its bottom edge is a boundary
        elif rect.y0 <= ref_line["y0"] and rect.y1 >= ref_line["y1"]:
            bottom = min(bottom, rect.y1)

    return bottom


def identify_section_header(line, gray_bars):
    """
    Returns (letter, title) if this line is a section header, else None.

    A line must match the "X. Title" text pattern, AND have at least
    one of these visual signals:
        - dark blue text
        - bold text
        - sits on a light gray header bar
    So it works even if the color is different in some PDFs.
    """

    text = line["text"]

    match = SECTION_HEADER_PATTERN.match(text)

    if not match or len(text) > 80:
        return None

    signals = 0

    if is_blue_text(line["rgb"]):
        signals += 1

    if line["bold"]:
        signals += 1

    center_x = (line["x0"] + line["x1"]) / 2
    center_y = (line["y0"] + line["y1"]) / 2

    on_gray_bar = any(
        bar.x0 <= center_x <= bar.x1 and bar.y0 <= center_y <= bar.y1
        for bar in gray_bars
    )

    if on_gray_bar:
        signals += 1

    if signals == 0:
        return None

    return match.group(1), match.group(2).strip()


def identify_plain_heading(line, gray_bars):
    """S420: a heading without a letter ('Form Review', 'Corrosion Calculations') - a short line that is not
    'X. Title', sits on a light gray header bar and is blue or bold. It ends the lettered section before it."""
    text = line["text"].strip()
    if not text or len(text) > 80 or SECTION_HEADER_PATTERN.match(text):
        return False
    if not (is_blue_text(line["rgb"]) or line["bold"]):
        return False
    center_x, center_y = (line["x0"] + line["x1"]) / 2, (line["y0"] + line["y1"]) / 2
    return any(bar.x0 <= center_x <= bar.x1 and bar.y0 <= center_y <= bar.y1 for bar in gray_bars)


# =========================
# SCREENSHOT FUNCTION
# =========================

def make_screenshot(page, heading_line, value_line):

    # Make screenshot wide enough to include both
    # the heading and extracted value.

    left = min(
        heading_line["x0"],
        value_line["x0"]
    ) - SCREENSHOT_LEFT_RIGHT_PADDING

    right = max(
        heading_line["x1"],
        value_line["x1"]
    ) + SCREENSHOT_LEFT_RIGHT_PADDING

    top = heading_line["y0"] - SCREENSHOT_TOP_PADDING
    bottom = value_line["y1"] + SCREENSHOT_BOTTOM_PADDING

    # Prevent crop from going outside PDF page
    left = max(0, left)
    top = max(0, top)
    right = min(page.rect.width, right)
    bottom = min(page.rect.height, bottom)

    clip = fitz.Rect(left, top, right, bottom)

    matrix = fitz.Matrix(
        SCREENSHOT_ZOOM,
        SCREENSHOT_ZOOM
    )

    # dataC: rendered from the page's display list made once (page_display_list) - page.get_pixmap made a new
    # one for every screenshot
    pix = page_display_list(page).get_pixmap(
        matrix=matrix,
        colorspace=fitz.csRGB,
        alpha=False,
        clip=clip
    )

    # Convert screenshot directly into PNG data.
    # No temporary image file needed.
    return pix.tobytes("png")


# =========================
# EXTRACT EVERYTHING
# =========================

def extract_fields(pdf_path):

    document = fitz.open(pdf_path)
    try:
        return extract_fields_from_document(document)
    finally:
        document.close()


def extract_fields_from_document(document):
    """dataC: extract_fields on a document that is already open (read_6000_document opens it once)."""

    results = {
        field: {
            "value": None,
            "image": None,
            "value_box": None,            # S175: where the value is on its page (PDF points)
            "page": None
        }
        for field in FIELDS
    }

    for page_number, page in enumerate(document, start=1):

        lines = get_lines(page)

        for field in FIELDS:

            # Already found
            if results[field]["value"] is not None:
                continue

            heading = find_heading(lines, field)

            if heading is None:
                continue

            value_line = find_value_below(lines, heading)

            if value_line is None:
                continue

            if field in MULTILINE_FIELDS:
                value_line = extend_value_lines(lines, value_line)

            results[field]["value"] = value_line["text"]
            results[field]["image"] = make_screenshot(page, heading, value_line)
            results[field]["value_box"] = (value_line["x0"], value_line["y0"], value_line["x1"], value_line["y1"])
            results[field]["page"] = page_number

    return results


# =========================
# EXTRACT ADDITIONAL NOTES
# =========================

def load_document_lines(document, with_shapes=True):
    """
    Flattens all lines from all pages into one ordered list (with color,
    boldness, page number and section-header info), so anything that
    spills onto the next page is still captured. Also returns the drawn
    shapes of every page - only when with_shapes is True (the Additional
    Notes need them to find where a section box ends; the defect sections
    do not, so they get None and the shapes are not loaded).
    """

    all_lines = []
    page_shapes = [] if with_shapes else None

    for page_index, page in enumerate(document):

        if with_shapes:
            page_shapes.append(get_page_shapes(page))

        gray_bars = get_gray_bars(page)
        page_height = page.rect.height

        for line in get_styled_lines(page):

            line["page_index"] = page_index
            line["page_height"] = page_height
            line["section"] = identify_section_header(line, gray_bars)
            line["plain_heading"] = line["section"] is None and identify_plain_heading(line, gray_bars)   # S420

            all_lines.append(line)

    return all_lines, page_shapes


def extract_additional_notes(pdf_path):
    """
    Finds every "Additional Notes" label, figures out which section
    (A, B, F...) it belongs to, and grabs all the text underneath it
    until the section ends. Sections with empty notes are skipped.
    """

    document = fitz.open(pdf_path)
    try:
        return extract_additional_notes_from_document(document)
    finally:
        document.close()


def extract_additional_notes_from_document(document):
    """dataC: extract_additional_notes on a document that is already open."""

    all_lines, page_shapes = load_document_lines(document)

    notes_label = normalize(NOTES_LABEL)

    results = []
    current_section = None
    i = 0

    while i < len(all_lines):

        line = all_lines[i]

        # Track which section we're in
        if line["section"] is not None:
            current_section = line["section"]
            i += 1
            continue

        if normalize(line["text"]) != notes_label:
            i += 1
            continue

        # ---- Found an "Additional Notes" label ----
        label = line
        collected = []

        prev_bottom = label["y1"]
        prev_page = label["page_index"]

        # Bottom border of the section box on the label's page
        box_bottom = find_box_bottom(
            page_shapes[label["page_index"]],
            label,
            label["page_height"]
        )

        j = i + 1

        while j < len(all_lines):

            nxt = all_lines[j]

            # Next section started -> notes are done
            if nxt["section"] is not None:
                break

            # Notes continued onto a new page -> find that page's box bottom
            if nxt["page_index"] != prev_page:
                box_bottom = find_box_bottom(
                    page_shapes[nxt["page_index"]],
                    nxt,
                    nxt["page_height"]
                )

            # Past the bottom border of the section box -> done
            if nxt["y0"] >= box_bottom:
                break

            # Another Additional Notes label -> done
            if normalize(nxt["text"]) == notes_label:
                break

            # Skip page headers/footers
            in_margin = (
                nxt["y0"] < PAGE_TOP_MARGIN
                or nxt["y1"] > nxt["page_height"] - PAGE_BOTTOM_MARGIN
            )

            if in_margin:
                j += 1
                continue

            # Skip anything sitting to the left of the notes column
            if nxt["x1"] < label["x0"] - HORIZONTAL_PADDING:
                j += 1
                continue

            # Big vertical gap on the same page -> left the section box
            if (
                nxt["page_index"] == prev_page
                and nxt["y0"] - prev_bottom > MAX_NOTE_LINE_GAP
            ):
                break

            # Gray text = another field label, not note content
            if is_gray_text(nxt["rgb"]):
                break

            collected.append(nxt)
            prev_bottom = nxt["y1"]
            prev_page = nxt["page_index"]

            j += 1

        # Nothing under the label -> skip this section
        if collected:

            if current_section is not None:
                letter, title = current_section
            else:
                letter, title = "?", "Unknown Section"

            note_text = "\n".join(l["text"] for l in collected)

            # Screenshot: label + note lines on the label's page
            same_page = [
                l for l in collected
                if l["page_index"] == label["page_index"]
            ]

            image = None

            if same_page:
                box = {
                    "x0": min(l["x0"] for l in same_page),
                    "y0": min(l["y0"] for l in same_page),
                    "x1": max(l["x1"] for l in same_page),
                    "y1": max(l["y1"] for l in same_page),
                }
                image = make_screenshot(
                    document[label["page_index"]],
                    label,
                    box
                )

            results.append({
                "letter": letter,
                "title": title,
                "value": note_text,
                "image": image,
                "value_box": (box["x0"], box["y0"], box["x1"], box["y1"]) if same_page else None,      # S175
                "page": label["page_index"] + 1,
            })

        i = j

    return results


# =========================
# DEFECT SECTIONS (C - G)
# =========================

CHECK_GLYPHS = set("\u2713\u2714\u2611\u2612\u2715\u2716\u2717\u2718")


def rect_center(rect):

    return fitz.Point(
        (rect.x0 + rect.x1) / 2,
        (rect.y0 + rect.y1) / 2
    )


def blue_pixel_share(page, rect):
    """
    Renders a small area and returns the fraction of pixels that are blue.
    """

    pix = page_display_list(page).get_pixmap(          # dataC: the page's display list made once
        matrix=fitz.Matrix(3, 3),
        colorspace=fitz.csRGB,
        alpha=False,
        clip=rect
    )

    total = pix.width * pix.height

    if total == 0:
        return 0

    rgb = np.frombuffer(pix.samples, dtype=np.uint8).reshape(-1, 3).astype(np.int16)
    blue = int(np.count_nonzero((rgb[:, 2] >= 150) & (rgb[:, 2] - rgb[:, 0] >= 60)))

    return blue / total


def is_blue_fill(fill):

    if not fill:
        return False

    r, g, b = fill[:3]

    return b >= 0.5 and (b - r) >= 0.25


def is_checkbox_checked(page, na_line):
    """
    Decides whether the N/A checkbox to the left of na_line is ticked.

    Several independent signals, so it does not rely on color alone:
      1. The box is filled blue
      2. A smaller shape (the tick mark) is drawn inside the box
      3. A tick character (check glyph) is printed in the box
      4. An image (tick icon) sits in the box
    Any one of these = checked.

    Returns (checked, list_of_reasons).
    """

    height = na_line["y1"] - na_line["y0"]

    # Area just left of the "N/A" text where the box sits
    region = fitz.Rect(
        na_line["x0"] - max(25, height * 2.5),
        na_line["y0"] - height * 0.6,
        na_line["x0"] + 1,
        na_line["y1"] + height * 0.6,
    )

    reasons = []

    shapes = []

    for drawing in page_drawings(page):

        rect = drawing["rect"]

        # Must be inside the region and small, box-like
        if not region.contains(rect_center(rect)):
            continue

        if rect.width > 30 or rect.height > 30:
            continue

        shapes.append(drawing)

    if shapes:

        # The checkbox itself = largest shape in the region
        box = max(shapes, key=lambda d: d["rect"].width * d["rect"].height)
        box_area = box["rect"].width * box["rect"].height

        # Signal 1: blue fill
        if any(is_blue_fill(d.get("fill")) for d in shapes):
            reasons.append("blue box")

        # Signal 2: tick mark drawn inside the box.
        # A tick is diagonal, so it has real width AND height, and
        # it sits in the middle of the box (not on a border edge).
        box_rect = box["rect"]

        inner = fitz.Rect(
            box_rect.x0 + box_rect.width * 0.15,
            box_rect.y0 + box_rect.height * 0.15,
            box_rect.x1 - box_rect.width * 0.15,
            box_rect.y1 - box_rect.height * 0.15,
        )

        for d in shapes:

            if d is box or box_area == 0:
                continue

            r = d["rect"]
            area = r.width * r.height

            is_diagonal_shape = (
                r.width >= box_rect.width * 0.3
                and r.height >= box_rect.height * 0.3
            )

            if (
                area < box_area * 0.6
                and is_diagonal_shape
                and inner.contains(rect_center(r))
            ):
                reasons.append("tick mark drawn")
                break

    # Signal 3: check glyph in text (in the box area, or at the
    # very start of the N/A line itself)
    if na_line["text"][:1] in CHECK_GLYPHS:
        reasons.append("tick character")

    for word in page.get_text("words", clip=region):
        if any(ch in CHECK_GLYPHS for ch in word[4]):
            reasons.append("tick character")
            break

    # Signal 4: box drawn as an image. Checked and unchecked boxes can
    # BOTH be images, so only count it if the image is mostly blue.
    for info in page.get_image_info():
        img_rect = fitz.Rect(info["bbox"])
        if region.contains(rect_center(img_rect)) and img_rect.width <= 30:
            if blue_pixel_share(page, img_rect) >= 0.15:
                reasons.append("blue tick image")
            break

    reasons = list(dict.fromkeys(reasons))

    return (len(reasons) > 0), reasons


def collect_value_below(label, section_lines):
    """
    Finds the black value text under a gray label, left-aligned with it.
    Supports multi-line values. Returns list of lines (may be empty).
    """

    same_page = [
        l for l in section_lines
        if l["page_index"] == label["page_index"]
    ]

    # Value lines: not gray labels, not blue headers, not the form's green hints ('Complete Section D' under
    # 'Type Of Metal Loss' - printed by the form, not filled in; dataC accuracy fix A1)
    candidates = [
        l for l in same_page
        if not is_gray_text(l["rgb"])
        and not is_blue_text(l["rgb"])
        and not is_form_hint_text(l["rgb"])
        and not l["text"].upper().startswith("N/A")
        and abs(l["x0"] - label["x0"]) <= LABEL_VALUE_X_TOLERANCE
        and l["y0"] > label["y0"] + 1
    ]

    candidates.sort(key=lambda l: l["y0"])

    if not candidates:
        return []

    first = candidates[0]

    if first["y0"] - label["y1"] > MAX_LABEL_VALUE_GAP:
        return []

    # Next gray label in the same column = end of this value
    next_label_y = min(
        (
            l["y0"] for l in same_page
            if is_gray_text(l["rgb"])
            and l is not label
            and l["y0"] > label["y0"] + 1
            and abs(l["x0"] - label["x0"]) <= LABEL_VALUE_X_TOLERANCE
        ),
        default=float("inf")
    )

    collected = [first]

    for l in candidates[1:]:

        if l["y0"] >= next_label_y:
            break

        # Continuation line must follow closely
        if l["y0"] - collected[-1]["y1"] > 10:
            break

        collected.append(l)

    if first["y0"] >= next_label_y:
        return []

    return collected


def measurement_group(label_text):
    """
    The word(s) in front of Depth/Length/Width, e.g.
    "Dent Depth (mils)" -> "Dent", "Gouge Width (in)" -> "Gouge".
    Returns "" if there's nothing in front.
    """

    text = label_text.strip()
    lower = text.lower()

    for keyword in PRIORITY_KEYWORDS[1:]:  # skip "anomaly type"

        position = lower.find(keyword)

        if position != -1:
            return text[:position].strip()

    return ""


def priority_rank(label_text):

    text = normalize(label_text)

    for rank, keyword in enumerate(PRIORITY_KEYWORDS):
        if keyword in text:
            return rank

    return len(PRIORITY_KEYWORDS)


def extract_defect_sections(pdf_path, section_notes=None):
    """
    For each defect section (C-G): checks the N/A box.
    Closed (checked) sections are just reported as N/A.
    Open sections get Anomaly Type, Depth, Length, Width first,
    then every other filled-in field.
    section_notes: the Additional Notes already read (read_6000_form passes
    them, so they are not read a second time); None = read them here.
    """

    if section_notes is None:
        section_notes = extract_additional_notes(pdf_path)

    document = fitz.open(pdf_path)
    try:
        return extract_defect_sections_from_document(document, section_notes)
    finally:
        document.close()


def extract_defect_sections_from_document(document, section_notes):
    """dataC: extract_defect_sections on a document that is already open (section_notes already read)."""

    all_lines, _no_shapes = load_document_lines(document, with_shapes=False)

    # Split lines into sections using the headers
    sections = []
    current = None

    for line in all_lines:

        if line["section"] is not None:

            current = {
                "letter": line["section"][0],
                "title": line["section"][1],
                "header": line,
                "lines": [],
            }

            sections.append(current)
            continue

        if current is None:
            continue

        # S420: a heading without a letter at the lettered headings' left edge ('Form Review', 'Corrosion
        # Calculations' after G) ends the section - its values are not the section's. (A centred page title
        # is not at that edge, so a section going on over a page break keeps going.)
        if line.get("plain_heading") and abs(line["x0"] - current["header"]["x0"]) <= LABEL_VALUE_X_TOLERANCE:
            print(f"6000 FORM: Section {current['letter']} ends at '{line['text'].strip()}' (page "
                  f"{line['page_index'] + 1}) - a heading without a letter (S420)")
            current = None
            continue

        in_margin = (
            line["y0"] < PAGE_TOP_MARGIN
            or line["y1"] > line["page_height"] - PAGE_BOTTOM_MARGIN
        )

        if not in_margin:
            current["lines"].append(line)

    results = []

    for section in sections:

        if section["letter"] not in DEFECT_SECTIONS:
            continue

        lines = section["lines"]

        # ---- N/A checkbox ----
        # Prefer the full "N/A (If N/A, remainder...)" line,
        # fall back to any line starting with N/A
        na_line = next(
            (l for l in lines if "if n/a" in normalize(l["text"])),
            None
        ) or next(
            (l for l in lines if normalize(l["text"]).lstrip("\u2713\u2714\u2611\u2610 ").startswith("n/a")),
            None
        )

        checked = False
        reasons = []

        if na_line is not None:
            checked, reasons = is_checkbox_checked(
                document[na_line["page_index"]],
                na_line
            )

        entry = {
            "letter": section["letter"],
            "title": section["title"],
            "page": section["header"]["page_index"] + 1,
            "closed": True,
            "checkbox_checked": checked,
            "reasons": reasons,
            "na_found": na_line is not None,
            "fields": [],
            "anomalies": [],
            "other_fields": [],
        }

        results.append(entry)

        # ---- Read every label/value pair in the section ----
        fields = []
        previous_label = ""                       # S420: the printed label just above (filled in or not)

        for order, label in enumerate(lines):

            if not is_gray_text(label["rgb"]):
                continue

            # Additional Notes are already handled separately
            if normalize(label["text"]) == normalize(NOTES_LABEL):
                continue

            label_above, previous_label = previous_label, label["text"]

            value_lines = collect_value_below(label, lines)

            # Blank field -> skip
            if not value_lines:
                continue

            value_text = "\n".join(l["text"] for l in value_lines)

            box = {
                "x0": min(l["x0"] for l in value_lines),
                "y0": min(l["y0"] for l in value_lines),
                "x1": max(l["x1"] for l in value_lines),
                "y1": max(l["y1"] for l in value_lines),
            }

            fields.append({
                "label": label["text"],
                "value": value_text,
                "image": make_screenshot(
                    document[label["page_index"]],
                    label,
                    box
                ),
                "value_box": (box["x0"], box["y0"], box["x1"], box["y1"]),                      # S175
                "page": label["page_index"] + 1,
                "rank": priority_rank(label["text"]),
                "order": order,
            })
            # S420: a question's answer ('Does the Metal Loss interact with long seam? (If so, what is the
            # maximum depth?)' - Yes) is not a Depth / Length / Width, and the depth asked for under the long
            # seam question is the depth where it meets the seam, not the anomaly's depth - both are other details
            if "?" in label["text"]:
                fields[-1]["rank"] = len(PRIORITY_KEYWORDS)
            elif re.search(r"long\s*seam", label_above, re.IGNORECASE) and fields[-1]["rank"] < len(PRIORITY_KEYWORDS):
                fields[-1]["rank"], fields[-1]["long_seam"] = len(PRIORITY_KEYWORDS), True

        entry["fields"] = fields

        # ---- Open or closed is decided by the text ----
        # A section is OPEN if any Anomaly Type / Depth / Length / Width
        # label has a value under it. The checkbox is only a cross-check.
        defect_fields = [
            f for f in fields
            if f["rank"] < len(PRIORITY_KEYWORDS)
        ]

        entry["closed"] = len(defect_fields) == 0

        if entry["closed"]:
            continue

        # ---- Group into anomalies ----
        # Each "Anomaly Type" label starts a new anomaly. The Depth /
        # Length / Width fields after it (reading order) belong to it,
        # so multiple anomalies in one section are kept apart.
        anomalies = []

        for f in fields:  # fields are already in reading order

            if f["rank"] == 0:
                anomalies.append({"type": f["value"], "fields": [f]})

            elif f["rank"] < len(PRIORITY_KEYWORDS):

                # Depth/Length/Width with no Anomaly Type above it
                if not anomalies:
                    anomalies.append({"type": None, "fields": []})

                anomalies[-1]["fields"].append(f)

            else:
                entry["other_fields"].append(f)

        # Inside each anomaly: Anomaly Type first, then grouped by what
        # is being measured (all Dent fields, then all Gouge fields...),
        # each group as Depth, Length, Width. Groups keep the order they
        # appear in on the PDF.
        for anomaly in anomalies:

            group_order = {}

            for f in sorted(anomaly["fields"], key=lambda f: f["order"]):
                f["group"] = measurement_group(f["label"])
                if f["rank"] > 0 and f["group"] not in group_order:
                    group_order[f["group"]] = len(group_order)

            anomaly["fields"].sort(
                key=lambda f: (
                    0 if f["rank"] == 0 else 1,
                    group_order.get(f["group"], 0),
                    f["rank"],
                    f["order"],
                )
            )

        entry["anomalies"] = anomalies

        # Add this section's Additional Notes (if any) at the end of
        # Other details. Uses the same notes reader as the notes block,
        # so it stops at the section border the same way.
        for note in section_notes:

            if note["letter"] != section["letter"]:
                continue

            entry["other_fields"].append({
                "label": NOTES_LABEL,
                "value": note["value"],
                "image": note["image"],
                "page": note["page"],
                "rank": len(PRIORITY_KEYWORDS),
                "order": float("inf"),
                "group": "",
            })

    return results


def defect_status_text(defect):

    name = f"{defect['letter']}. {defect['title']}"

    if defect["closed"]:
        return f"{name}:  CLOSED (no Anomaly Type / Depth / Length / Width values)"

    count = len(defect["anomalies"])
    word = "anomaly" if count == 1 else "anomalies"

    return f"{name}:  OPEN — {count} {word} found"


def checkbox_warning(defect):
    """
    Flags when the N/A checkbox disagrees with what the text says,
    so you know to double-check that section by eye.
    """

    if not defect["na_found"]:
        return None

    if defect["closed"] and not defect["checkbox_checked"]:
        return "   ⚠ N/A box does not look checked, but no defect values were found"

    if not defect["closed"] and defect["checkbox_checked"]:
        return "   ⚠ N/A box looks checked, but defect values were found"

    return None


# =========================
# DISPLAY WINDOW
# =========================

# =========================
# CONFIRM / CORRECT CONTROLS
# =========================

GREEN = "#1e7b34"
ORANGE = "#c77700"
BORDER_GRAY = "#9a9a9a"

# Every value shown in the window registers itself here so the
# Finish button can collect the final values.
CONFIRM_STATE = {
    "checks": [],
    "on_change": None,
    "refreshers": [],      # sections that rebuild themselves when a value is typed
}


def notify_value_changed(update_counter):
    """Called whenever a correction box changes: counter + every live section."""
    update_counter()
    for refresh in list(CONFIRM_STATE.get("refreshers") or []):
        try:
            refresh()
        except Exception as exc:
            print("Live refresh failed:", exc)


# S73: several documents at once - every value's key starts with its document's name
# ("100553.07: Dig Latitude (A)"), so two Dig Packets never share a correction box.
# CHECK_SCOPE["prefix"] is the name of the document whose values are being built now.
CHECK_SCOPE = {"prefix": ""}


LIVE_VALUE_INDEX = {"stamp": None, "by_key": {}}     # S235: correction boxes by key


def live_value(key, fallback):
    """The value the window currently uses for this key: the typed correction if
    there is one, otherwise Python's value. Unknown key -> fallback. S235: looked up in
    an index of the boxes by key (made again whenever the list of boxes changes) instead
    of a walk through every box - the end table asks this thousands of times."""
    checks = CONFIRM_STATE["checks"]
    stamp = (id(checks), len(checks), id(checks[-1]) if checks else None)
    if LIVE_VALUE_INDEX["stamp"] != stamp:
        by_key = {}
        for check in checks:
            by_key.setdefault(check.key, check)          # the first box of a key, as the walk found
        LIVE_VALUE_INDEX.update(stamp=stamp, by_key=by_key)
    check = LIVE_VALUE_INDEX["by_key"].get(key)
    return check.final_value if check is not None else fallback


class ValueCheck:
    """
    The correction box for one value.

    Every value is accepted as Python read it, UNLESS something is
    typed in its box — then the typed text is used instead.
    """

    def __init__(self, key, value, page):

        key = CHECK_SCOPE["prefix"] + key          # S73: the document the value belongs to

        # Make key unique if the same name appears twice
        existing = {c.key for c in CONFIRM_STATE["checks"]}
        base, n = key, 2
        while key in existing:
            key = f"{base} ({n})"
            n += 1

        self.key = key
        self.original = value
        self.page = page

        self.text_widget = None
        self.status_label = None
        self.border_frame = None

        CONFIRM_STATE["checks"].append(self)

    # ---------- widgets ----------

    def correction_row(self, parent, width_chars):

        wrapper = ttk.Frame(parent)

        ttk.Label(
            wrapper,
            text="Correction (leave blank if correct):"
        ).pack(anchor="w")

        multi_line = self.original is not None and "\n" in self.original

        if multi_line:
            self.text_widget = tk.Text(
                wrapper,
                height=min(6, self.original.count("\n") + 2),
                width=width_chars,
                font=("Segoe UI", 10),
                wrap="word"
            )
        else:
            self.text_widget = ttk.Entry(
                wrapper,
                width=width_chars,
                font=("Segoe UI", 10)
            )

        self.text_widget.pack()
        self.text_widget.bind("<KeyRelease>", lambda event: self._refresh())

        self.status_label = tk.Label(
            wrapper,
            font=("Segoe UI", 9, "bold")
        )
        self.status_label.pack(pady=(3, 0))

        self._refresh()

        return wrapper

    # ---------- behaviour ----------

    def typed_text(self):

        if self.text_widget is None:
            return ""

        if isinstance(self.text_widget, tk.Text):
            return self.text_widget.get("1.0", "end-1c").strip()

        return self.text_widget.get().strip()

    def _refresh(self):

        if self.corrected:
            text = f"Using typed value: {self.typed_text()}"
            color = ORANGE
        else:
            text = "Using Python's value"
            color = GREEN

        if self.status_label is not None:
            self.status_label.config(text=text, fg=color)

        if self.border_frame is not None:
            self.border_frame.config(
                highlightbackground=ORANGE if self.corrected else BORDER_GRAY,
                highlightcolor=ORANGE if self.corrected else BORDER_GRAY,
                highlightthickness=2 if self.corrected else 1
            )

        if CONFIRM_STATE["on_change"]:
            CONFIRM_STATE["on_change"]()

    # ---------- results ----------

    @property
    def corrected(self):
        return bool(self.typed_text())

    @property
    def final_value(self):
        return self.typed_text() if self.corrected else self.original

    @property
    def source(self):
        return "typed" if self.corrected else "python"


def build_value_widgets(container, title, image_data, value_text, page,
                        image_references, key, title_size, wrap):
    """
    Shared layout for both the full-width blocks and the small cards.
    """

    check = ValueCheck(key or title, value_text, page)

    ttk.Label(
        container,
        text=title,
        font=("Segoe UI", title_size, "bold")
    ).pack(pady=(0, 6))

    image_width = wrap

    if image_data is not None:

        photo = make_tk_photo(image_data)            # also kept for 'Copy whole tab'

        # Keep reference or tkinter deletes the image
        image_references.append(photo)
        image_width = max(wrap, photo.width())

        ttk.Label(container, image=photo).pack(pady=4)

    else:

        ttk.Label(
            container,
            text="[No screenshot available]"
        ).pack(pady=4)

    shown = "NOT FOUND" if value_text is None else value_text

    # Multi-line values (notes) go on their own lines under "Python read:"
    if "\n" in shown:
        display_text = f"Python read:\n{shown}"
    else:
        display_text = f"Python read:  {shown}"

    ttk.Label(
        container,
        text=display_text,
        font=("Segoe UI", title_size, "bold"),
        justify="left",
        wraplength=image_width
    ).pack(pady=(6, 2))

    if page is not None:
        ttk.Label(container, text=f"Page {page}").pack()

    # Typing box: anything typed here replaces Python's value
    width_chars = max(20, min(60, image_width // 9))
    check.correction_row(container, width_chars).pack(pady=(8, 0))

    return check


def add_result_block(parent, title, image_data, value_text, page,
                     image_references, key=None, warnings=None):

    section = ttk.Frame(parent)
    section.pack(fill="x", padx=20, pady=15)

    build_value_widgets(
        section, title, image_data, value_text, page,
        image_references, key, title_size=12, wrap=800
    )

    # Orange "check this by eye" lines shown on the block (e.g. mid-line '*')
    for warning in warnings or []:
        tk.Label(
            section, text=warning, fg=ORANGE,
            font=("Segoe UI", 10, "bold"), wraplength=800, justify="center",
        ).pack(pady=(6, 0))

    ttk.Separator(section, orient="horizontal").pack(fill="x", pady=(15, 0))


CARD_PADDING = 8


def make_card(parent, title, image_data, value_text, page,
              image_references, key=None):
    """
    One bordered box: tick + field name, screenshot, what Python read,
    page, and the correction box. Border turns orange if corrected.
    """

    card = tk.Frame(
        parent,
        highlightbackground=BORDER_GRAY,
        highlightcolor=BORDER_GRAY,
        highlightthickness=1,
        padx=8,
        pady=8
    )

    check = build_value_widgets(
        card, title, image_data, value_text, page,
        image_references, key, title_size=11, wrap=250
    )

    check.border_frame = card
    check._refresh()

    return card


class WrapGrid:
    """
    Lays cards out in columns, side by side. When the window is too
    narrow for all of them, the extra cards wrap onto the next row.
    Re-arranges itself whenever the window is resized.
    """

    def __init__(self, parent):

        self.frame = ttk.Frame(parent)
        self.frame.pack(fill="x", padx=20, pady=5)

        self.cards = []
        self.columns = None

        self.frame.bind("<Configure>", self._on_resize)

    def add(self, card):

        self.cards.append(card)
        self._layout(force=True)

    def _column_count(self):

        width = self.frame.winfo_width()

        if width <= 1:
            # Not drawn yet -> use the window width as a first guess
            width = self.frame.winfo_toplevel().winfo_width()
        if width <= 1:
            width = 900

        widest = max(
            (c.winfo_reqwidth() for c in self.cards),
            default=1
        ) + 2 * CARD_PADDING

        return max(1, min(len(self.cards), width // widest))

    def _layout(self, force=False):

        if not self.cards:
            return

        self.frame.update_idletasks()

        columns = self._column_count()

        if columns == self.columns and not force:
            return

        # Clear old column weights
        if self.columns:
            for col in range(self.columns):
                self.frame.columnconfigure(col, weight=0)

        self.columns = columns

        for index, card in enumerate(self.cards):
            card.grid(
                row=index // columns,
                column=index % columns,
                padx=CARD_PADDING,
                pady=CARD_PADDING,
                sticky="n"
            )

        # Spread columns evenly across the width
        for col in range(columns):
            self.frame.columnconfigure(col, weight=1)

    def _on_resize(self, event):

        self._layout()


def print_final_values(final_values):

    print()
    print("=" * 60)
    print("FINAL VALUES")
    print("=" * 60)

    for item in final_values:

        value = item["value"] if item["value"] is not None else "(blank)"
        tag = "  [typed correction]" if item["source"] == "typed" else ""

        value_lines = str(value).split("\n")
        print(f"{item['name']}: {value_lines[0]}{tag}")

        for extra in value_lines[1:]:
            print(f"    {extra}")

    # Google Maps link(s) from the FINAL Dig coordinates (typed corrections included)
    dig_coordinates = [
        (item["name"], item["value"]) for item in final_values
        if str(item["name"]).startswith("Dig Latitude") or str(item["name"]).startswith("Dig Longitude")
    ]
    for label, lat, lon in pair_latitudes_with_longitudes(dig_coordinates):
        link = google_maps_link(lat, lon)
        name = f"Google Maps {label}".strip()
        print(f"{name}: {link if link else '(no valid coordinates)'}")

    print("=" * 60)


def show_results(pdf_path, results, notes, defects, dig, host, tab_prefix="", form_prefix="", dig_prefix=""):
    """Builds the tabs of one 6000 form and/or one Dig Packet (and their comparison
    tabs) into the documents window (`host`: its tab maker and picture list). Called
    for every document group whenever a document is added or removed. S73: tab_prefix
    goes in front of every tab name when several documents are in; form_prefix /
    dig_prefix in front of every value key of the 6000 form / the Dig Packet."""
    _window_started = time.perf_counter()
    tab_inners = []          # (tab title, inner frame) - used for the TAB HEIGHT print
    DISPLAY_PAGE_MAP.clear()
    DISPLAY_PAGE_MAP.update((dig or {}).get("page_map") or {})   # this packet's page-1 pictures
    CHECK_SCOPE["prefix"] = form_prefix

    def add_scroll_tab(title):
        inner = host.add_scroll_tab(tab_prefix + title)
        tab_inners.append((tab_prefix + title, inner))
        return inner

    main_tab_name = ("6000 form + Dig Packet" if (pdf_path is not None and dig is not None)
                     else ("6000 form" if pdf_path is not None else "Dig Packet"))
    scroll_frame = add_scroll_tab(main_tab_name)

    # Keeps every window image alive (used by the 6000 AND Dig sections)
    image_references = host.image_references

    # 6000 form sections are skipped in Dig-Packet-only mode (pdf_path=None)
    if pdf_path is not None:

        # =========================
        # PDF NAME
        # =========================

        ttk.Label(
            scroll_frame,
            text="PDF:",
            font=("Segoe UI", 10, "bold")
        ).pack(pady=(15, 2))

        ttk.Label(
            scroll_frame,
            text=os.path.basename(pdf_path)
        ).pack(pady=(0, 15))


        # =========================
        # EACH FIELD
        # =========================

        for field in FIELDS:

            result = results[field]

            add_result_block(
                scroll_frame,
                field,
                result["image"],
                result["value"],
                result["page"],
                image_references
            )

        # =========================
        # ADDITIONAL NOTES
        # =========================

        for note in notes:

            add_result_block(
                scroll_frame,
                f"Additional Notes — Section {note['letter']}. {note['title']}",
                note["image"],
                note["value"],
                note["page"],
                image_references,
                key=f"{note['letter']}. Additional Notes"
            )

        # =========================
        # DEFECT SECTIONS (C - G)
        # =========================

        ttk.Label(
            scroll_frame,
            text="DEFECT SECTIONS",
            font=("Segoe UI", 14, "bold")
        ).pack(pady=(25, 5))

        for defect in defects:
            tk.Label(
                scroll_frame,
                text=defect_status_text(defect),
                fg="gray" if defect["closed"] else "#b00020",
                font=("Segoe UI", 11, "bold")
            ).pack(pady=2)

            warning = checkbox_warning(defect)
            if warning:
                tk.Label(
                    scroll_frame,
                    text=warning,
                    fg="#c77700",
                    font=("Segoe UI", 9)
                ).pack()

        # For each anomaly: one COLUMN per measurement group (Dent, Gouge...)
        # with its Depth / Length / Width stacked going down, e.g.
        #
        #     Dent                 Gouge
        #     Dent Depth           Gouge Depth
        #     Dent Length          Gouge Length
        #     Dent Width           Gouge Width
        #
        # If there are more columns than fit across the window,
        # the extra columns wrap underneath.

        for defect in defects:

            if defect["closed"]:
                continue

            tk.Label(
                scroll_frame,
                text=f"Section {defect['letter']}. {defect['title']}",
                fg="#b00020",
                font=("Segoe UI", 14, "bold")
            ).pack(pady=(25, 0))

            # Clock position fields get pulled out of "Other details" and
            # shown to the right of the Anomaly Type they belong to.
            clock_fields = [
                f for f in defect["other_fields"]
                if "clock" in normalize(f["label"])
            ]

            used_clock = []

            # Where each anomaly starts in reading order, so a clock position
            # goes with the anomaly it sits under on the PDF.
            anomaly_starts = [
                min(f["order"] for f in a["fields"])
                for a in defect["anomalies"]
            ]

            for number, anomaly in enumerate(defect["anomalies"], start=1):

                tk.Label(
                    scroll_frame,
                    text=f"Anomaly {number}: {anomaly['type'] or '(no Anomaly Type given)'}",
                    font=("Segoe UI", 13, "bold")
                ).pack(pady=(15, 0))

                start = anomaly_starts[number - 1]
                end = (
                    anomaly_starts[number]
                    if number < len(anomaly_starts)
                    else float("inf")
                )

                my_clock = [
                    f for f in clock_fields
                    if f not in used_clock
                    and (start <= f["order"] < end or number == 1 and f["order"] < start)
                ]

                used_clock.extend(my_clock)

                # Anomaly Type, then Clock position to its right
                type_fields = [f for f in anomaly["fields"] if f["rank"] == 0] + my_clock

                if type_fields:

                    type_grid = WrapGrid(scroll_frame)

                    for field in type_fields:
                        type_grid.add(make_card(
                            type_grid.frame,
                            field["label"],
                            field["image"],
                            field["value"],
                            field["page"],
                            image_references,
                            key=f"{defect['letter']}. Anomaly {number} — {field['label']}"
                        ))

                # Split the rest into groups (fields are already sorted
                # Dent Depth, Dent Length, Dent Width, Gouge Depth, ...)
                groups = []

                for field in anomaly["fields"]:

                    if field["rank"] == 0:
                        continue

                    group = field.get("group", "")

                    if not groups or groups[-1][0] != group:
                        groups.append((group, []))

                    groups[-1][1].append(field)

                if groups:

                    columns_grid = WrapGrid(scroll_frame)

                    for group, group_fields in groups:

                        column = ttk.Frame(columns_grid.frame)

                        ttk.Label(
                            column,
                            text=group or "Measurements",
                            font=("Segoe UI", 12, "bold", "underline")
                        ).pack(pady=(0, 6))

                        for field in group_fields:
                            make_card(
                                column,
                                field["label"],
                                field["image"],
                                field["value"],
                                field["page"],
                                image_references,
                                key=f"{defect['letter']}. Anomaly {number} — {field['label']}"
                            ).pack(fill="x", pady=4)

                        columns_grid.add(column)

            # Everything else in the section (clock position, weld
            # questions, Additional Notes...) side by side underneath
            remaining_fields = [
                f for f in defect["other_fields"]
                if f not in used_clock
            ]

            if remaining_fields:

                ttk.Label(
                    scroll_frame,
                    text=f"Other details — Section {defect['letter']}",
                    font=("Segoe UI", 12, "bold", "underline")
                ).pack(pady=(15, 0))

                other_grid = WrapGrid(scroll_frame)

                for field in remaining_fields:
                    other_grid.add(make_card(
                        other_grid.frame,
                        field["label"],
                        field["image"],
                        field["value"],
                        field["page"],
                        image_references,
                        key=f"{defect['letter']}. {field['label']}"
                    ))

            ttk.Separator(scroll_frame, orient="horizontal").pack(
                fill="x", padx=20, pady=(20, 0)
            )

    # =========================
    # DIG PACKET SECTION
    # =========================

    with timed(f"Window: {main_tab_name} tab", 1):
        CHECK_SCOPE["prefix"] = dig_prefix
        add_dig_packet_section(scroll_frame, dig, image_references)

    # S297: no Warnings tab per document - one Warnings tab for every document (DocumentsWindow)

    # =========================
    # DIG PACKET TABLE PAGES - own tabs (a few coloured rows per tab)
    # =========================

    if page1_snip_step_fields(dig):
        with timed("Window: Page 1 snip steps tab", 1):
            add_snip_steps_section(add_scroll_tab("Page 1 snip steps"), dig, image_references)

    if dig is not None and DISPLAY_PAGE_MAP.get("steps"):
        with timed("Window: Page 1 full page tab", 1):
            add_page1_full_section(add_scroll_tab("Page 1 full page"), image_references)

    # S216: every coloured / white row group in ONE tab per Dig Packet, one part each
    table_groups = table_highlight_tab_groups(dig)
    early_count, stack = (host.take_early_table_tabs(dig.get("path"), [t for t, _p, _i, _k in table_groups],
                                                     dig_prefix, tab_prefix)
                          if dig is not None and table_groups else (0, None))
    if table_groups[early_count:] and stack is None:
        stack = host.add_stack_tab(tab_prefix + TABLE_ROWS_TAB)
    for title, table_page, items, kind in table_groups[early_count:]:
        with timed(f"Window: {TABLE_ROWS_TAB} tab - {title}", 1):
            if kind == "white":
                add_white_rows_section(stack.add(), table_page, items, image_references)
            else:
                add_table_highlights_section(stack.add(), table_page, items, image_references)

    # =========================
    # DIG PACKET WHEEL COUNTS - own tab (S228: the 6000 vs Dig Packet tab is gone - the
    # Verify tab's end table compares every document)
    # =========================

    if dig is not None and (dig or {}).get("results"):
        try:
            with timed("Window: Dig Packet wheel counts tab", 1):
                add_wheel_counts_section(add_scroll_tab("Dig Packet wheel counts"), results if pdf_path else {}, dig,
                                         form_prefix=form_prefix, dig_prefix=dig_prefix)
        except Exception as exc:
            print("Wheel counts tab failed:", exc)

    CHECK_SCOPE["prefix"] = ""
    # requested height of every tab (Windows can't draw one scroll area taller than ~32,767 px)
    with timed("Window: lay out every tab", 1):
        host.root.update_idletasks()
    for tab_title, tab_inner in tab_inners:
        print(f"TAB HEIGHT: {tab_title}: {tab_inner.winfo_reqheight()} px (Windows limit ~32,767 px)")
    record_timing("Build window (all tabs and pictures)", time.perf_counter() - _window_started)


