# ============================================================
# LAZY GENERAL ENGLISH CANDIDATE SOURCE
# ============================================================
# Candidate words are pulled only when a word actually needs correction and
# each query result is cached.

GENERAL_ENGLISH_QUERY_CACHE = {}
_ENGLISH_WORDS_BY_LENGTH = {"limit": None, "by_length": {}}
_ENGLISH_WORDS_LOCK = threading.Lock()


def _english_words_of_length(length):
    """dataC: the upper-case letters-only words of this length among the first ENGLISH_WORD_SCAN_LIMIT
    entries of wordfreq's English list, in list order (built once per limit)."""
    with _ENGLISH_WORDS_LOCK:
        if _ENGLISH_WORDS_BY_LENGTH["limit"] != ENGLISH_WORD_SCAN_LIMIT:
            by_length = {}
            letters_only = re.compile(r"[A-Z]+")
            scanned = 0
            for raw_word in iter_wordlist("en"):
                scanned += 1
                if scanned > ENGLISH_WORD_SCAN_LIMIT:
                    break
                word = str(raw_word).upper()
                if letters_only.fullmatch(word):
                    by_length.setdefault(len(word), []).append(word)
            _ENGLISH_WORDS_BY_LENGTH.update(limit=ENGLISH_WORD_SCAN_LIMIT, by_length=by_length)
        return _ENGLISH_WORDS_BY_LENGTH["by_length"].get(length, ())


def _character_lock_cache_signature(character_profile):
    if not character_profile:
        return ()
    locked = character_profile.get("locked", {}) or {}
    return tuple(sorted(
        (int(position), str(character).upper())
        for position, character in locked.items()
    ))


def _mixed_pattern_cache_signature(mixed_pattern):
    if not mixed_pattern:
        return ""
    compact = re.sub(r"[^A-Z0-9?]", "", str(mixed_pattern).upper())
    return "".join(
        character if character.isalpha() else "?"
        for character in compact
    )


def lazy_english_words(
    length,
    character_profile=None,
    mixed_pattern=None,
    insertion_base=None,
    enforce_character_locks=False,
):
    """
    Return only English words that match the requested OCR constraints.
      mixed_pattern="S6AM"   -> only S?AM words
      insertion_base="WED"   -> only 4-letter words that reduce to WED by
                                deleting exactly one character
      character_profile locks -> only words compatible with those locks
    """
    try:
        requested_length = int(length)
    except Exception:
        return []
    if requested_length <= 0:
        return []

    mixed_signature = _mixed_pattern_cache_signature(mixed_pattern)
    insertion_base = (
        normalize_alpha_for_matching(insertion_base)
        if insertion_base else ""
    )
    lock_signature = (
        _character_lock_cache_signature(character_profile)
        if enforce_character_locks else ()
    )
    cache_key = (
        requested_length,
        mixed_signature,
        insertion_base,
        lock_signature,
        bool(enforce_character_locks),
    )
    if cache_key in GENERAL_ENGLISH_QUERY_CACHE:
        return list(GENERAL_ENGLISH_QUERY_CACHE[cache_key])

    search_started = time.perf_counter()
    output = []
    # dataC: the word list's first ENGLISH_WORD_SCAN_LIMIT words, upper-cased, letters-only, grouped by
    # length (in word-list order) are made once; each query then looks only at words of its length - the
    # same words in the same order as scanning the whole list each time
    for word in _english_words_of_length(requested_length):
        if mixed_signature:
            if len(mixed_signature) != len(word):
                continue
            if any(
                expected != "?" and expected != actual
                for expected, actual in zip(mixed_signature, word)
            ):
                continue
        if insertion_base:
            if len(word) != len(insertion_base) + 1:
                continue
            if not any(
                word[:remove_index] + word[remove_index + 1:] == insertion_base
                for remove_index in range(len(word))
            ):
                continue
        if (
            enforce_character_locks
            and not candidate_respects_character_locks(word, character_profile)
        ):
            continue
        output.append(word)

    GENERAL_ENGLISH_QUERY_CACHE[cache_key] = tuple(output)
    add_work_time("wordlist", time.perf_counter() - search_started)
    return list(output)


def is_general_english_word(word, minimum_zipf=2.3):
    word = normalize_alpha_for_matching(word)
    if not word:
        return False
    return zipf_frequency(word.lower(), "en") >= minimum_zipf


