@contextmanager
def held_output(store):
    """S116: what THIS thread prints is kept in `store` (a list) instead of going to the
    terminal; the caller prints it later, in the right place."""
    thread = threading.get_ident()
    stack = OUTPUT_CAPTURES.setdefault(thread, [])
    stack.append(store)
    try:
        yield
    finally:
        if stack:
            stack.pop()
        if not stack:
            OUTPUT_CAPTURES.pop(thread, None)


EARLY_TABLES = {}          # S125: pdf path -> {'results': ...} whose table rows are final (set by the reading thread)
OCR_ACTIVITY = {"busy": 0.0, "calls": 0}   # S128: seconds the reading has spent inside OCR calls (running total)
EARLY_TAB_OCR_SHARE = 0.5                  # S128: build an early tab only when the reading spent >= this share
                                           #       of the last moment waiting on OCR (the GPU), not on Python work


class OCRActivity:
    """S128: an OCR reader that keeps count of the time spent inside its calls, so the
    window can tell, moment by moment, whether the reading is waiting on the GPU (a
    good time to do window work alongside) or busy with its own Python work (a bad
    time - they would take turns). Calls go straight through; nothing else changes."""
    def __init__(self, reader):
        self._reader = reader

    def __getattr__(self, name):
        attribute = getattr(self._reader, name)
        if not callable(attribute):
            return attribute

        def timed_call(*args, **kwargs):
            started = time.perf_counter()
            try:
                result = attribute(*args, **kwargs)
                if hasattr(result, "__next__"):          # a generator does its work when read out
                    result = list(result)
                return result
            finally:
                OCR_ACTIVITY["busy"] += time.perf_counter() - started
                OCR_ACTIVITY["calls"] += 1
        return timed_call


def run_alongside(job, *args, **kwargs):
    """S116: start job(*args) on its own thread, its printing held back. Returns
    finish() -> the job's result (raising its error, if any) after printing what it
    printed. Used for CPU-only work (numpy / OpenCV) that really runs side by side with
    the OCR reads."""
    box = {"output": []}

    def work():
        with held_output(box["output"]):
            try:
                box["result"] = job(*args, **kwargs)
            except BaseException as exc:          # handed to the caller
                box["error"] = exc

    thread = threading.Thread(target=work, daemon=True)
    thread.start()

    def finish():
        thread.join()
        text = "".join(box["output"])
        if text:
            sys.stdout.write(text)
        if "error" in box:
            raise box["error"]
        return box.get("result")
    return finish


NOTES_DETECTOR_LOAD = {"thread": None, "error": None, "seconds": None}   # S133


# S155: big libraries that more than one loader imports. When two threads import the same
# large package at the same moment, one of them can get it half set up ("cannot import
# name 'AutoTokenizer'"). So each of these is imported through its own lock - one thread
# at a time; once it is in, the import is instant for everyone. Everything else still
# loads side by side. While the models load, the program watches for a library that one
# loader asks for while another loader is still in the middle of importing it - the
# situation that causes the clash - and reports any that is not on this list.
SHARED_LIBRARIES = {"torch": threading.Lock(), "transformers": threading.Lock()}
IMPORT_RECORD = {"active": False, "clashes": {}, "in_progress": {}, "local": threading.local(), "lock": threading.Lock()}


def import_shared(name, loader):
    """S155: import one of SHARED_LIBRARIES through its lock; returns the seconds waited
    for another thread (0 when it was free or already imported). A library that is not
    installed is skipped (the loader itself then reports what it is missing)."""
    import importlib
    started = time.perf_counter()
    with SHARED_LIBRARIES[name]:
        waited = time.perf_counter() - started
        IMPORT_RECORD["local"].loader = loader
        try:
            importlib.import_module(name)
        except ImportError:
            pass
    return waited


def start_import_record():
    """S155: from now on, every import made while the models load is noted per loader."""
    import builtins
    if IMPORT_RECORD["active"]:
        return
    IMPORT_RECORD.update({"active": True, "clashes": {}, "in_progress": {}})
    original = builtins.__import__

    def recording_import(name, globals=None, locals=None, fromlist=(), level=0):
        loader = getattr(IMPORT_RECORD["local"], "loader", None)
        if not (loader and IMPORT_RECORD["active"] and level == 0 and name):
            return original(name, globals, locals, fromlist, level)
        top = name.split(".")[0]
        mine = False
        with IMPORT_RECORD["lock"]:
            other = IMPORT_RECORD["in_progress"].get(top)
            if other and other != loader:              # another loader is still importing it right now
                IMPORT_RECORD["clashes"].setdefault(top, set()).update({other, loader})
            elif not other and top not in sys.modules:
                IMPORT_RECORD["in_progress"][top] = loader
                mine = True
        try:
            return original(name, globals, locals, fromlist, level)
        finally:
            if mine:
                with IMPORT_RECORD["lock"]:
                    IMPORT_RECORD["in_progress"].pop(top, None)

    IMPORT_RECORD["original"] = original
    builtins.__import__ = recording_import


def report_shared_libraries():
    """S155: once every loader is done - which big libraries were imported by more than
    one loader, and whether each of those is guarded."""
    import builtins
    if not IMPORT_RECORD["active"]:
        return
    IMPORT_RECORD["active"] = False
    if IMPORT_RECORD.get("original"):
        builtins.__import__ = IMPORT_RECORD["original"]
    clashes = IMPORT_RECORD["clashes"]
    if not clashes:
        print(f"SHARED LIBRARIES: {', '.join(SHARED_LIBRARIES)} imported one loader at a time - no library was asked "
              f"for by one loader while another was still importing it (S155)")
    else:
        shown = ", ".join(f"'{n}' ({', '.join(sorted(l))})" for n, l in sorted(clashes.items()))
        print(f"SHARED LIBRARIES: ⚠ asked for by one loader while another was still importing it: {shown} - "
              f"add {'it' if len(clashes) == 1 else 'them'} to SHARED_LIBRARIES (S155)")




class WaitingReader:
    """S152: stands in for the PaddleOCR text reader while it is still loading. Reading a
    Dig Packet starts as soon as EasyOCR is ready (the label search and the colour map
    need nothing else); the first call that needs PaddleOCR (the table pages) waits here
    until it is loaded - and says how long. If its load failed, that call fails with the
    load's error (the packet then shows it as failed)."""
    def __init__(self):
        self.ready = threading.Event()
        self.reader = None
        self.error = None
        self.waited_once = False

    def __getattr__(self, name):
        if not self.ready.is_set():
            started = time.perf_counter()
            print("OCR MODELS: this step needs PaddleOCR - waiting for it to finish loading (S152)")
            self.ready.wait()
            record_timing("Waited for PaddleOCR (the steps before it ran while it loaded - S152)",
                          time.perf_counter() - started, 1)
        if self.reader is None:
            raise RuntimeError(f"the PaddleOCR text reader did not load ({self.error})")
        return getattr(self.reader, name)


# ============================================================
# S350: THE OCR MODELS IN THEIR OWN PROCESS
# ============================================================
# EasyOCR, PaddleOCR (text reader + Notes detector) and the language model load and run in a second
# process that starts with the program and closes with it. The window's process then never imports
# PyTorch / Paddle: their long imports (mostly Python work that holds the GIL) no longer take turns with
# the window, the 6000 forms and the reading's own work. Every call goes over a pipe - the picture goes
# there, the read comes back - so the reads are the same as before (same models, same settings). What the
# OCR process prints comes back too and is printed here, in order. If the process cannot start (or stops
# before its models are ready), the models load in this process, the way they did before.

OCR_PROCESS_ON = True                # S350: False = the models load in the window's process (as before)
OCR_IN_CHILD = False                 # True only inside an OCR process
OCR_CHILD = {"role": None, "program_started": None}     # S368: inside an OCR process - which one, and when the
                                                        # window's program started (for the timings)


def ocr_process_state():
    """S350/S368: what the window's process keeps about one OCR process."""
    return {"process": None, "conn": None, "send_lock": threading.Lock(), "pending": {},
            "pending_lock": threading.Lock(), "next": 0, "ready": threading.Event(), "failed": None,
            "crashed": False, "stopped": None, "closing": False, "started_at": None, "waiting_said": False,
            "fallback_said": False}


# S368: two OCR processes - EasyOCR (with the language model) in one, PaddleOCR (text reader + Notes detector)
# in the other, so the two load truly side by side on two processor cores instead of taking turns
OCR_PROCESSES = {"easy": ocr_process_state(), "paddle": ocr_process_state()}
OCR_ROLE_OF = {"easy": "easy", "lm": "easy", "paddle": "paddle", "notes": "paddle", "mem": "easy"}
OCR_NOTES = {"started": False}       # S350: the Notes detector's load was asked for (window's process)


# ============================================================
# S400: OCR CALL LEDGER - every call to an OCR process is noted (who asked, how long it waited in the OCR
# process behind other calls, how long the model worked on it, how long the pictures took to go there and
# back). A step that waited on the OCR prints what it waited for (OCR_STEP_NOTE_MIN_S), and the end of the run
# prints how busy each OCR process was and for whom - measured, so nothing about the OCR has to be guessed.
# ============================================================
OCR_LEDGER = []                       # {role, kind, method, who, thread, sent, back, queued, run}
OCR_LEDGER_LOCK = threading.Lock()
OCR_STEP_NOTE_MIN_S = 0.3             # a step's OCR line is printed when it waited (or sent pictures) this long
OCR_ROLE_NAMES = {"easy": "EasyOCR", "paddle": "PaddleOCR"}
OCR_THREAD_MARK = threading.local()   # a number of its own per thread (a finished thread's id can come back)
OCR_THREAD_COUNT = [0]


def ocr_thread_mark():
    """S400: this thread's own number for the ledger."""
    mark = getattr(OCR_THREAD_MARK, "number", None)
    if mark is None:
        with OCR_LEDGER_LOCK:
            OCR_THREAD_COUNT[0] += 1
            mark = OCR_THREAD_MARK.number = OCR_THREAD_COUNT[0]
    return mark


def ocr_asker():
    """S400: who an OCR call is for, in plain words - from the thread that asks."""
    name = threading.current_thread().name
    if getattr(OCR_CALL, "priority", 0) == 1 or name == "photo-reader":
        return "10000-35 photos"
    if name == "labels-ahead":
        return "next Dig Packet's labels (ahead)"
    for part, said in (("heavy_worker", "Dig Packet reading"), ("light_worker", "6000 forms / quick reads"),
                       ("prefetch", "pages prepared ahead"), ("MainThread", "the window")):
        if part in name:
            return said
    return name


def ocr_ledger_add(state, kind, method, sent, box):
    """S400: one finished OCR call into the ledger (window's process)."""
    if box.get("run") is None:
        return
    role = next((r for r, st in OCR_PROCESSES.items() if st is state), "?")
    mark = ocr_thread_mark()
    with OCR_LEDGER_LOCK:
        OCR_LEDGER.append({"role": role, "kind": kind, "method": method, "who": ocr_asker(),
                           "thread": mark, "sent": sent, "back": box["back"],
                           "queued": box["queued"], "run": box["run"]})


def ocr_step_note(started, ended):
    """S400: what this thread's OCR calls between started and ended (perf_counter) were made of, per OCR
    process - reading, waiting behind other calls (and whose), sending the pictures. '' when it waited little."""
    me = ocr_thread_mark()
    with OCR_LEDGER_LOCK:
        calls = [c for c in OCR_LEDGER if c["thread"] == me and started <= c["sent"] and c["back"] <= ended + 1e-6]
        others = [c for c in OCR_LEDGER if c["thread"] != me and c["back"] >= started and c["back"] - c["run"] <= ended]
    if not calls:
        return ""
    parts, waited_any = [], False
    for role in ("easy", "paddle"):
        mine = [c for c in calls if c["role"] == role]
        if not mine:
            continue
        run = sum(c["run"] for c in mine)
        queued = sum(c["queued"] for c in mine)
        moving = sum(max(0.0, c["back"] - c["sent"] - c["queued"] - c["run"]) for c in mine)
        waited_any |= queued >= OCR_STEP_NOTE_MIN_S or moving >= OCR_STEP_NOTE_MIN_S
        behind = Counter()
        for c in mine:                                 # who the OCR process was working for while this call waited
            wait_from, wait_to = c["back"] - c["run"] - c["queued"], c["back"] - c["run"]
            for o in others:
                if o["role"] != role:
                    continue
                overlap = min(wait_to, o["back"]) - max(wait_from, o["back"] - o["run"])
                if overlap > 0:
                    behind[o["who"]] += overlap
        text = (f"{OCR_ROLE_NAMES[role]} {len(mine)} call(s): {run:.1f} s reading, {queued:.1f} s waiting its turn"
                + (" (behind " + ", ".join(f"{who} {sec:.1f} s" for who, sec in behind.most_common(3)) + ")"
                   if behind else "")
                + f", {moving:.1f} s sending pictures there and back")
        parts.append(text)
    if not waited_any:
        return ""
    return "OCR in this step - " + "; ".join(parts) + " (S400)"


def ocr_run_summary():
    """S400: the end of the run - how long each OCR process worked, and for whom."""
    with OCR_LEDGER_LOCK:
        calls = list(OCR_LEDGER)
    if not calls:
        return
    for role in ("easy", "paddle"):
        mine = [c for c in calls if c["role"] == role]
        if not mine:
            continue
        first = min(c["back"] - c["run"] for c in mine)
        last = max(c["back"] for c in mine)
        busy = Counter()
        waits = Counter()
        for c in mine:
            busy[c["who"]] += c["run"]
            waits[c["who"]] += c["queued"]
        print(f"OCR USE: {OCR_ROLE_NAMES[role]} - {len(mine)} call(s), {sum(busy.values()):.1f} s reading between "
              f"{first - PROGRAM_START:.1f} s and {last - PROGRAM_START:.1f} s after the start: "
              + "; ".join(f"{who} {sec:.1f} s reading ({waits[who]:.1f} s waiting its turn)"
                          for who, sec in busy.most_common()) + " (S400)")


OCR_CALL = threading.local()           # S364: .priority - 1 for the 10000-35 photos (after any Dig Packet call)

# S401: a Dig Packet's EasyOCR STRETCHES - its page-1 label search and its table headers' EasyOCR reads are
# EasyOCR calls one after another. A photo read that starts between two of them cannot be stopped, so the Dig
# Packet's next call waited for it (2.7 s on 100553.07). While a stretch runs, the photos' EasyOCR calls wait;
# EasyOCR is not left idle by it - the Dig Packet keeps it busy - and the photos' other work (Tesseract, their
# cells) goes on. Outside the stretches the photos fill EasyOCR's gaps as before.
EASY_STRETCH = {"active": [], "cond": threading.Condition()}
EASY_STRETCH_MAX_WAIT_S = 30           # a photo call never waits longer than this for a stretch


@contextmanager
def easy_stretch(what):
    """S401: a Dig Packet's run of EasyOCR calls - the photos' EasyOCR calls wait until it is over."""
    document = getattr(PROGRESS, "document", None) or {}
    name = f"{os.path.splitext(document.get('name') or 'the Dig Packet')[0]} ({what})"
    with EASY_STRETCH["cond"]:
        EASY_STRETCH["active"].append(name)
    try:
        yield
    finally:
        with EASY_STRETCH["cond"]:
            EASY_STRETCH["active"].remove(name)
            EASY_STRETCH["cond"].notify_all()


def easy_stretch_wait():
    """S401 (a photo's EasyOCR call): waits while a Dig Packet's EasyOCR stretch runs; says how long."""
    started, said = time.perf_counter(), None
    with EASY_STRETCH["cond"]:
        while EASY_STRETCH["active"] and time.perf_counter() - started < EASY_STRETCH_MAX_WAIT_S:
            said = EASY_STRETCH["active"][-1]
            EASY_STRETCH["cond"].wait(timeout=0.5)
    if said is not None:
        print(f"  10000-35 PHOTO: its EasyOCR read waited {time.perf_counter() - started:.1f} s while {said} "
              f"used EasyOCR (S401)")


class OCRPlainResult(dict):
    """S350: a PaddleOCR result as it comes back from the OCR process - its JSON ({'res': {...}}), read the
    same ways the code reads PaddleX's own results (result.json, or as a dict with 'res')."""
    @property
    def json(self):
        return self


class OCRProcessReader:
    """S350: stands in for a model that lives in the OCR process - the same calls, carried out there."""
    def __init__(self, kind):
        self.kind = kind

    def readtext(self, *args, **kwargs):
        return ocr_process_call(self.kind, "readtext", args, kwargs)

    def readtext_batched(self, *args, **kwargs):
        return ocr_process_call(self.kind, "readtext_batched", args, kwargs)

    def predict(self, *args, **kwargs):
        return [OCRPlainResult(result) for result in ocr_process_call(self.kind, "predict", args, kwargs)]


class OCRProcessOutput:
    """S350 (in the OCR process): what it prints goes to the window's process. What a call prints is sent
    back with its read (so it is printed by the thread that asked, where it belongs); what the loading
    threads print is sent line by line."""
    encoding = "utf-8"

    def __init__(self, conn, lock):
        self.conn, self.lock, self.pending, self.call_text = conn, lock, [], None
        self.main = threading.main_thread()
        self.original = sys.__stdout__

    def write(self, text):
        if not text:
            return 0
        if self.call_text is not None and threading.current_thread() is self.main:
            self.call_text.append(text)
            return len(text)
        with self.lock:
            self.pending.append(text)
            if "\n" in text:
                self._send()
        return len(text)

    def _send(self):
        if self.pending:
            text, self.pending = "".join(self.pending), []
            try:
                self.conn.send(("log", text))
            except Exception:
                pass

    def flush(self):
        with self.lock:
            self._send()

    def isatty(self):
        return False

    def fileno(self):
        if self.original is None:
            raise io.UnsupportedOperation("fileno")
        return self.original.fileno()


def ocr_plain_paddle(result):
    """S350 (in the OCR process): a PaddleX result -> a plain dict {'res': {...}} that can go over the pipe."""
    data = getattr(result, "json", None)
    if callable(data):
        data = data()
    if isinstance(data, str):
        data = json.loads(data)
    if not isinstance(data, dict):
        data = dict(result)
    data = dict(data) if "res" in data else {"res": dict(data)}
    if isinstance(data["res"], dict):                # pictures are not sent back - only the reads are used
        data["res"] = {key: value for key, value in data["res"].items() if "img" not in key}
    return data


def gpu_memory_here():
    """S414 (an OCR process): its GPU memory in MiB as its own library counts it - {'now', 'peak'} held, or
    None when it cannot say. The GPU driver's own share for each process (a few hundred MiB) is not in it."""
    mib = 1024 * 1024
    torch = sys.modules.get("torch")
    try:
        if torch is not None and torch.cuda.is_available() and torch.cuda.is_initialized():
            return {"now": torch.cuda.memory_reserved() / mib, "peak": torch.cuda.max_memory_reserved() / mib}
    except Exception:
        pass
    paddle = sys.modules.get("paddle")
    try:
        if paddle is not None and paddle.device.is_compiled_with_cuda():
            return {"now": paddle.device.cuda.memory_reserved() / mib,
                    "peak": paddle.device.cuda.max_memory_reserved() / mib}
    except Exception:
        pass
    return None


def ocr_process_serve(kind, method, args, kwargs):
    """S350 (in the OCR process): one call from the window's process, carried out on the models here."""
    if kind == "easy":
        return getattr(easy_reader, method)(*args, **kwargs)
    if kind == "paddle":
        if text_reader is None:                  # S368: the PaddleOCR process failed - loaded here instead
            load_paddle_here("the EasyOCR process (the PaddleOCR process failed)")
        return [ocr_plain_paddle(result) for result in getattr(text_reader, method)(*args, **kwargs)]
    if kind == "notes":
        if method == "start":
            start_notes_detector_load()
            return None
        wait_for_notes_detector()
        if method == "wait":
            return None
        return [ocr_plain_paddle(result) for result in getattr(notes_detector, method)(*args, **kwargs)]
    if kind == "lm":
        return _contextual_sentence_log_probability(*args)
    if kind == "mem":                                  # S414: this process's GPU memory
        return gpu_memory_here()
    raise ValueError(f"unknown OCR process call {kind}.{method}")


def ocr_process_main(conn, program_started, role):
    """S350: an OCR process - S368: role 'easy' loads EasyOCR (the language model later, when a Notes line
    needs it), role 'paddle' loads the PaddleOCR text reader (the Notes detector later, when asked). It says
    when its model is ready, then carries out the calls until the window's process closes."""
    global OCR_IN_CHILD
    OCR_IN_CHILD = True
    OCR_CHILD.update(role=role, program_started=program_started)
    lock = threading.Lock()
    output = OCRProcessOutput(conn, lock)
    sys.stdout = sys.stderr = output
    try:
        if role == "easy":
            load_easyocr_here()
        else:
            load_paddle_here("its own process")
        message = ("ready", None)
    except BaseException as exc:
        traceback.print_exc()
        message = ("failed", f"{type(exc).__name__}: {exc}")
    output.flush()
    with lock:
        conn.send(message)
    # S364: the calls are taken in by their own thread and carried out by priority - a Dig Packet's call (0)
    # before a 10000-35 photo's (1); a call already running finishes first
    import itertools
    requests, order = queue.PriorityQueue(), itertools.count()

    def take_in():
        while True:
            try:
                request = conn.recv()
            except (EOFError, OSError):
                requests.put((-1, 0, (("quit",), 0.0)))
                return
            if request[0] == "quit":
                requests.put((-1, 0, (request, 0.0)))
                return
            requests.put((request[6] if len(request) > 6 else 0, next(order), (request, time.perf_counter())))
    threading.Thread(target=take_in, name="ocr-calls-in", daemon=True).start()
    while True:
        _priority, _order, (request, received) = requests.get()
        if request[0] == "quit":
            output.flush()
            os._exit(0)
        _, number, kind, method, args, kwargs = request[:6]
        output.call_text = []
        started = time.perf_counter()
        queued = started - received                  # S400: how long it waited here for the calls before it
        try:
            value, ok = ocr_process_serve(kind, method, args, kwargs), True
        except BaseException as exc:
            traceback.print_exc()
            value, ok = f"{type(exc).__name__}: {exc}", False
        run = time.perf_counter() - started          # S400: how long the model worked on it
        text, output.call_text = "".join(output.call_text), None
        output.flush()
        try:
            with lock:
                conn.send(("result", number, ok, value, text, queued, run))
        except Exception as exc:
            with lock:
                conn.send(("result", number, False, f"its read could not be sent back ({type(exc).__name__}: "
                                                    f"{exc})", text, queued, run))


def ocr_process_used():
    """S350: True in the window's process once the EasyOCR process has its model ready (the readers then
    stand for the OCR processes' models)."""
    easy = OCR_PROCESSES["easy"]
    return not OCR_IN_CHILD and easy["process"] is not None and easy["ready"].is_set() and not easy["failed"]


COMPILED_COPY_LOCK = threading.Lock()     # S360: the OCR process and a PDF helper may start at the same moment


def spawn_from_compiled_copy():
    """S360: the OCR process and the PDF helper processes are new Pythons that load data.py first. Started
    the usual way, each one compiles all of data.py from its text again (about 4 s each, all at once). So
    they are told to load it by its module name instead: Python then uses its own compiled copy
    (__pycache__/data.cpython-312.pyc next to data.py), made here once whenever data.py is new or changed.
    It holds only the program, never anything read from a document."""
    with COMPILED_COPY_LOCK:
        _spawn_from_compiled_copy()


def _spawn_from_compiled_copy():
    main = sys.modules.get("__main__")
    path = getattr(main, "__file__", None)
    if main is None or getattr(main, "__spec__", None) is not None or not path:
        return                              # already started by module name (python -m data), or no file
    name = os.path.splitext(os.path.basename(path))[0]
    if not name.isidentifier():
        return
    import importlib.util
    import py_compile
    path = os.path.abspath(path)
    try:
        cached = importlib.util.cache_from_source(path)
        if not os.path.isfile(cached) or os.path.getmtime(cached) < os.path.getmtime(path):
            started = time.perf_counter()
            py_compile.compile(path, cfile=cached, doraise=True)
            print(f"COMPILED COPY: data.py is new or changed - compiled once ({time.perf_counter() - started:.1f} s) "
                  f"for the OCR process and the PDF helpers to share (S360)")
        main.__spec__ = importlib.util.spec_from_file_location(name, path)
    except Exception as exc:
        print(f"COMPILED COPY: could not be made ({type(exc).__name__}: {exc}) - each process compiles data.py "
              f"itself, as before (S360)")


def ocr_process_start(role):
    """S350: starts an OCR process (S368: role 'easy' or 'paddle') and the thread that takes in what it
    sends back."""
    import atexit
    import multiprocessing
    state = OCR_PROCESSES[role]
    spawn_from_compiled_copy()                                   # S360
    context = multiprocessing.get_context("spawn")
    mine, theirs = context.Pipe(duplex=True)
    program_started = time.time() - (time.perf_counter() - PROGRAM_START)
    process = context.Process(target=ocr_process_main, args=(theirs, program_started, role),
                              name=f"ocr-{role}", daemon=True)
    process.start()
    theirs.close()
    state.update(process=process, conn=mine, started_at=time.perf_counter())
    threading.Thread(target=ocr_process_receive, args=(mine, state, role), name=f"ocr-{role}-replies",
                     daemon=True).start()

    def close():
        state["closing"] = True
        try:
            with state["send_lock"]:
                mine.send(("quit",))
        except Exception:
            pass
    atexit.register(close)


def ocr_process_receive(conn, state, role):
    """S350: takes in everything an OCR process sends - printed text, 'model ready', reads."""
    while True:
        try:
            message = conn.recv()
        except (EOFError, OSError):
            reason = f"the {'EasyOCR' if role == 'easy' else 'PaddleOCR'} process stopped"
            exit_code = state["process"].exitcode if state["process"] is not None else None
            if exit_code not in (None, 0):
                reason += f" (exit code {exit_code})"
            state["stopped"] = reason
            if not state["ready"].is_set():
                state["failed"], state["crashed"] = reason, True
                state["ready"].set()
            with state["pending_lock"]:
                waiting = list(state["pending"].values())
                state["pending"].clear()
            for box in waiting:
                box.update(ok=False, value=reason, text="")
                box["event"].set()
            if not state["closing"]:
                print(f"OCR PROCESS: {reason} (S350)")
            return
        if message[0] == "log":
            sys.stdout.write(message[1])
        elif message[0] == "ready":
            state["ready"].set()
        elif message[0] == "failed":
            state["failed"] = message[1]
            state["ready"].set()
        elif message[0] == "result":
            _, number, ok, value, text = message[:5]
            queued, run = message[5:7] if len(message) >= 7 else (None, None)      # S400
            with state["pending_lock"]:
                box = state["pending"].pop(number, None)
            if box is not None:
                box.update(ok=ok, value=value, text=text, queued=queued, run=run, back=time.perf_counter())
                box["event"].set()


def ocr_process_call(kind, method, args=(), kwargs=None, _state=None):
    """S350: one call carried out in an OCR process; returns its result (what it printed is printed
    here first). Raises RuntimeError when the call failed there or the process has stopped. S368: EasyOCR and
    the language model go to the EasyOCR process, PaddleOCR and the Notes detector to the PaddleOCR process -
    waiting for it when it is still loading; if it failed, they go to the EasyOCR process (loaded there)."""
    if _state is None and OCR_ROLE_OF[kind] == "easy" and getattr(OCR_CALL, "priority", 0) >= 1:
        easy_stretch_wait()                                                                    # S401
    state = _state or OCR_PROCESSES[OCR_ROLE_OF[kind]]       # S414: _state - that process itself
    if _state is None and OCR_ROLE_OF[kind] == "paddle":
        if not state["ready"].is_set():
            started = time.perf_counter()
            if not state["waiting_said"]:
                state["waiting_said"] = True
                print("OCR MODELS: this step needs PaddleOCR - waiting for its process to finish loading (S368)")
            state["ready"].wait()
            record_timing("Waited for PaddleOCR (the steps before it ran while it loaded - S152/S368)",
                          time.perf_counter() - started, 1)
        if state["failed"]:
            if not state["fallback_said"]:
                state["fallback_said"] = True
                print(f"OCR MODELS: PaddleOCR's own process failed ({state['failed']}) - PaddleOCR is loaded "
                      f"in the EasyOCR process instead (S368)")
            state = OCR_PROCESSES["easy"]
    box = {"event": threading.Event()}
    with state["pending_lock"]:
        state["next"] += 1
        number = state["next"]
        state["pending"][number] = box
    if state["stopped"]:
        with state["pending_lock"]:
            state["pending"].pop(number, None)
        raise RuntimeError(state["stopped"])
    sent = time.perf_counter()                                                                 # S400
    try:
        with state["send_lock"]:
            state["conn"].send(("call", number, kind, method, tuple(args), dict(kwargs or {}),
                                      getattr(OCR_CALL, "priority", 0)))                       # S364
    except Exception as exc:
        with state["pending_lock"]:
            state["pending"].pop(number, None)
        raise RuntimeError(f"the OCR process could not be reached ({type(exc).__name__}: {exc})")
    box["event"].wait()
    ocr_ledger_add(state, kind, method, sent, box)                                            # S400
    if box.get("text"):
        sys.stdout.write(box["text"])
    if not box["ok"]:
        raise RuntimeError(f"OCR process: {box['value']}")
    return box["value"]


def ocr_process_load():
    """S350 (window's process): starts the OCR process (once) and waits until EasyOCR is ready there; the
    readers then stand for its models. False when it could not start or stopped before its models were
    ready (the models then load in this process, as before)."""
    global easy_reader, text_reader, dm_easy_reader, dm_paddle_reader
    easy, paddle = OCR_PROCESSES["easy"], OCR_PROCESSES["paddle"]
    if easy["process"] is None:
        try:
            ocr_process_start("easy")
        except Exception as exc:
            print(f"OCR PROCESS: could not be started ({type(exc).__name__}: {exc}) - the OCR models load in "
                  f"this process instead (S350)")
            easy["failed"] = str(exc)
            return False
        try:
            ocr_process_start("paddle")                                    # S368
        except Exception as exc:
            paddle.update(failed=f"could not be started ({type(exc).__name__}: {exc})", crashed=True)
            paddle["ready"].set()
        record_timing("Program start -> OCR processes started - EasyOCR and PaddleOCR load there, each in its own "
                      "(S350/S368)", easy["started_at"] - PROGRAM_START, 1)
    easy["ready"].wait()
    if easy["crashed"]:
        print(f"OCR PROCESS: {easy['failed']} before its model was ready - the OCR models load in this "
              f"process instead (S350)")
        if paddle["conn"] is not None:                 # S368: not needed then - the models all load here
            paddle["closing"] = True
            try:
                with paddle["send_lock"]:
                    paddle["conn"].send(("quit",))
            except Exception:
                pass
        return False
    if easy["failed"]:
        raise RuntimeError(easy["failed"])
    easy_reader = OCRActivity(OCRProcessReader("easy"))
    dm_easy_reader = easy_reader
    text_reader = OCRActivity(OCRProcessReader("paddle"))      # waits for PaddleOCR when needed (S152/S368)
    dm_paddle_reader = text_reader
    return True


def load_easyocr_here():
    """S368 (the EasyOCR process): PyTorch, then EasyOCR - alone in this process; PaddleOCR loads in its own
    process at the same time, on another processor core."""
    global easy_reader, dm_easy_reader
    record_timing("Program start -> EasyOCR loading starts in its own process (S368)",
                  time.time() - OCR_CHILD["program_started"], 1)
    started = time.perf_counter()
    import_shared("torch", "EasyOCR")
    record_timing("import torch - S154", time.perf_counter() - started, 1)
    started = time.perf_counter()
    import easyocr
    record_timing("import easyocr - S154", time.perf_counter() - started, 1)
    print("Loading EasyOCR on GPU...")
    started = time.perf_counter()
    reader = easyocr.Reader(["en"], gpu=True)
    record_timing("EasyOCR model set up on GPU - reading can start now (S152)", time.perf_counter() - started, 1)
    print(f"OCR MODELS: EasyOCR ready {time.time() - OCR_CHILD['program_started']:.1f} s after the program started "
          f"(S368)")
    easy_reader = OCRActivity(reader)                        # S128
    dm_easy_reader = easy_reader


PADDLE_SKIPPED_IMPORTS = ("modelscope.hub.errors",)    # S396: asked for by PaddleX at its start, never used here


def load_paddle_here(where):
    """S368: the PaddleOCR text reader, loaded in this process - its own process (no PyTorch there, so no
    DLL order to keep), or the EasyOCR process when its own one failed. Tried twice (S153)."""
    global text_reader, dm_paddle_reader
    # S359: PaddleOCR does not test its download sites on every start (its models are already on this PC; a
    # model that is not yet there is still downloaded). The language model's Hugging Face check is not touched.
    os.environ["PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK"] = "True"
    record_timing(f"Program start -> PaddleOCR loading starts in {where} (S368)",
                  time.time() - OCR_CHILD["program_started"], 1)
    # S396: PaddleX asks for ModelScope's error list at its start (paddlex/inference/utils/official_models.py,
    # in a try - it carries on without it); looking it up makes ModelScope load Hugging Face's transformers
    # library (about 5 s), which this reader never uses. It is marked "not there" while PaddleOCR loads, so that
    # lookup stops at once - then unmarked, so a download from ModelScope would still find it.
    skipped = [name for name in PADDLE_SKIPPED_IMPORTS if name not in sys.modules]
    had_transformers = "transformers" in sys.modules
    for name in skipped:
        sys.modules[name] = None
    try:
        for attempt in (1, 2):
            try:
                started = time.perf_counter()
                from paddleocr import TextRecognition
                record_timing("import paddleocr (with Paddle) - S154", time.perf_counter() - started, 1)
                started = time.perf_counter()
                reader = TextRecognition(model_name="PP-OCRv5_server_rec", device="gpu:0")
                record_timing("PaddleOCR text recognizer set up on GPU - S154", time.perf_counter() - started, 1)
                break
            except Exception as exc:
                if attempt == 2:
                    raise
                print(f"OCR MODELS: loading PaddleOCR failed ({exc}) - trying once more (S153)")
    finally:
        for name in skipped:
            if name in sys.modules and sys.modules[name] is None:
                del sys.modules[name]
    if skipped:
        print("PADDLEOCR START: ModelScope's error list skipped while PaddleOCR loaded - "
              + ("transformers was already loaded in this process" if had_transformers else
                 "transformers was loaded anyway by something else" if "transformers" in sys.modules else
                 "transformers not loaded (about 5 s saved)") + " (S396)")
    print(f"OCR MODELS: PaddleOCR ready {time.time() - OCR_CHILD['program_started']:.1f} s after the program "
          f"started ({where} - S368)")
    text_reader = OCRActivity(reader)                        # S128
    dm_paddle_reader = text_reader


def load_ocr_models():
    """S152: returns as soon as EasyOCR is ready - a Dig Packet can then start (the label
    search and the colour map need only EasyOCR / no OCR); the PaddleOCR text reader keeps
    loading on its own thread and the first step that needs it waits for it (WaitingReader).
    PyTorch is imported FIRST, on its own: on Windows its DLLs must be loaded before
    Paddle's - when Paddle's load first, PyTorch fails with 'WinError 127 ... shm.dll'.
    S153: EasyOCR and PaddleOCR then load at the same time; if PaddleOCR's load fails it is
    tried once more after EasyOCR. S154: every part is timed. S155: transformers is imported
    one loader at a time. S156: the language model loads after PaddleOCR is ready (it is
    only needed at the Notes); then the Notes detector (S133)."""
    global easy_reader, text_reader
    global dm_easy_reader, dm_paddle_reader

    if easy_reader is not None and text_reader is not None:
        return
    if OCR_PROCESS_ON and ocr_process_load():               # S350/S368: in their own processes
        return
    # S359: PaddleOCR does not test its download sites on every start (its models are already on this PC; a
    # model that is not yet there is still downloaded). The language model's Hugging Face check is not touched.
    os.environ["PADDLE_PDX_DISABLE_MODEL_SOURCE_CHECK"] = "True"

    began = time.perf_counter()
    record_timing("Program start -> OCR model loading starts (window, imports of the program itself) - S154",
                  began - PROGRAM_START, 1)
    print()
    print("Loading OCR models in the background - PyTorch first, then EasyOCR and PaddleOCR at the same time "
          "(S153); reading starts when EasyOCR is ready (S152)...")
    paddle_load = {"reader": None, "error": None, "import": None, "model": None, "waited": 0.0}
    start_import_record()                                      # S155

    # PyTorch first, alone: its DLLs before Paddle's (Windows DLL order - see above)
    started = time.perf_counter()
    IMPORT_RECORD["local"].loader = "EasyOCR"
    import_shared("torch", "EasyOCR")
    record_timing("import torch (PyTorch - first, before Paddle's DLLs) - S154", time.perf_counter() - started, 1)

    def load_paddle():
        try:
            started = time.perf_counter()
            IMPORT_RECORD["local"].loader = "PaddleOCR"
            paddle_load["waited"] = import_shared("transformers", "PaddleOCR")   # S155: shared with the language model
            IMPORT_RECORD["local"].loader = "PaddleOCR"
            from paddleocr import TextRecognition
            paddle_load["import"] = time.perf_counter() - started
            started = time.perf_counter()
            paddle_load["reader"] = TextRecognition(model_name="PP-OCRv5_server_rec", device="gpu:0")
            paddle_load["model"] = time.perf_counter() - started
        except Exception as exc:
            paddle_load["error"] = exc
        finally:
            IMPORT_RECORD["local"].loader = None

    waiting = WaitingReader()
    easy_ready = {}

    def paddle_thread():
        load_paddle()
        if paddle_load["error"] is not None:
            print(f"OCR MODELS: loading PaddleOCR next to EasyOCR failed ({paddle_load['error']}) - trying once more "
                  f"(S153)")
            paddle_load.update({"reader": None, "error": None, "import": None, "model": None, "waited": 0.0})
            load_paddle()
        if paddle_load["error"] is not None:
            waiting.error = paddle_load["error"]
            print(f"OCR MODELS: PaddleOCR could not be loaded ({paddle_load['error']})")
            waiting.ready.set()
            return
        record_timing("import paddleocr (with Paddle) - S154 - next to EasyOCR"
                      + (f" (of which {paddle_load['waited']:.1f} s waiting for a shared library - S155)"
                         if paddle_load["waited"] >= 0.05 else ""), paddle_load["import"], 1)
        record_timing("PaddleOCR text recognizer set up on GPU - next to EasyOCR", paddle_load["model"], 1)
        global dm_paddle_reader
        waiting.reader = OCRActivity(paddle_load["reader"])     # S128: the time spent in OCR is counted
        dm_paddle_reader = waiting.reader
        waiting.ready.set()
        done = time.perf_counter()
        easy_at = easy_ready.get("at", done)
        print(f"OCR MODELS: EasyOCR ready {easy_at - began:.1f} s after loading began, PaddleOCR "
              f"{done - began:.1f} s - reading started at EasyOCR's {easy_at - began:.1f} s (S152); one after the "
              f"other they would have taken about {(easy_at - began) + paddle_load['import'] + paddle_load['model']:.1f} s")
        # S159: the Notes detector and the language model are NOT started here - each starts
        # when it is least in the way of the reading: the Notes detector after the table
        # pages, the language model with the page-1 value lines (extract_dig_packet)


    threading.Thread(target=paddle_thread, name="paddle-text-reader-load", daemon=True).start()

    started = time.perf_counter()
    IMPORT_RECORD["local"].loader = "EasyOCR"
    import easyocr
    record_timing("import easyocr - S154", time.perf_counter() - started, 1)
    print("Loading EasyOCR on GPU...")
    started = time.perf_counter()
    reader = easyocr.Reader(["en"], gpu=True)
    IMPORT_RECORD["local"].loader = None                    # S155: this thread's later imports are not loading
    record_timing("EasyOCR model set up on GPU - reading can start now (S152)", time.perf_counter() - started, 1)
    easy_ready["at"] = time.perf_counter()

    easy_reader = OCRActivity(reader)                        # S128
    dm_easy_reader = easy_reader
    text_reader = waiting                                    # S152: waits for PaddleOCR on first use
    if waiting.ready.is_set() and waiting.reader is not None:
        dm_paddle_reader = waiting.reader
    else:
        dm_paddle_reader = waiting


def start_notes_detector_load():
    """S133: the PaddleOCR Notes detector loads on its own thread."""
    if ocr_process_used():                       # S350: it loads in the OCR process
        if not OCR_NOTES["started"]:
            OCR_NOTES["started"] = True
            ocr_process_call("notes", "start")
        return
    if NOTES_DETECTOR_LOAD["thread"] is not None or notes_detector is not None:
        return

    def work():
        global notes_detector
        started = time.perf_counter()
        try:
            from paddleocr import PaddleOCR
            print("Loading PaddleOCR Notes detector on GPU (while reading can already start - S133)...")
            detector = PaddleOCR(
                use_doc_orientation_classify=False,
                use_doc_unwarping=False,
                use_textline_orientation=False,
                text_recognition_model_name="PP-OCRv5_server_rec",
                device="gpu:0",
            )
            notes_detector = OCRActivity(detector)
            NOTES_DETECTOR_LOAD["seconds"] = time.perf_counter() - started
            record_timing("PaddleOCR Notes detector loaded on GPU (in the background - S133)",
                          NOTES_DETECTOR_LOAD["seconds"], 1)
        except Exception as exc:                  # reported when the Notes need it
            NOTES_DETECTOR_LOAD["error"] = exc
            traceback.print_exc()

    NOTES_DETECTOR_LOAD["thread"] = threading.Thread(target=work, name="notes-detector-load", daemon=True)
    NOTES_DETECTOR_LOAD["thread"].start()


def wait_for_notes_detector():
    """S133: the Notes step waits here for the Notes detector only when it is still
    loading (and says how long); if the background load failed, it is loaded here."""
    global notes_detector
    if ocr_process_used():                       # S350: it waits (and loads, if needed) in the OCR process
        if notes_detector is None:
            ocr_process_call("notes", "wait")
            notes_detector = OCRActivity(OCRProcessReader("notes"))
        return
    if notes_detector is not None:
        return
    if NOTES_DETECTOR_LOAD["thread"] is None:
        start_notes_detector_load()
    started = time.perf_counter()
    print("NOTES DETECTOR: still loading - the Notes step waits for it")
    NOTES_DETECTOR_LOAD["thread"].join()
    if notes_detector is None:
        # the background load failed (e.g. a clash with the reading running at the same
        # time): load it once more here, on the reading's own thread
        print(f"NOTES DETECTOR: the background load failed ({NOTES_DETECTOR_LOAD['error']}) - loading it here")
        from paddleocr import PaddleOCR
        notes_detector = OCRActivity(PaddleOCR(
            use_doc_orientation_classify=False,
            use_doc_unwarping=False,
            use_textline_orientation=False,
            text_recognition_model_name="PP-OCRv5_server_rec",
            device="gpu:0",
        ))
    record_timing("Waited for the Notes detector", time.perf_counter() - started, 1)


# ============================================================
# BASIC HELPERS
# ============================================================

def safe_float(value, default=0.0):
    try:
        return float(value)
    except Exception:
        return default


def clamp(value, minimum=0.0, maximum=1.0):
    return max(minimum, min(maximum, value))


def image_cache_key(image):
    image = image.convert("RGB")
    digest = hashlib.sha1()
    digest.update(str(image.size).encode("utf-8"))
    digest.update(image.tobytes())
    return digest.hexdigest()


def combine_images_horizontal(images, gap=6):
    if not images:
        return Image.new("RGB", (1, 1), "white")
    if len(images) == 1:
        return images[0].copy()
    height = max(image.height for image in images)
    width = sum(image.width for image in images) + gap * (len(images) - 1)
    output = Image.new("RGB", (width, height), "white")
    x = 0
    for image in images:
        output.paste(image, (x, 0))
        x += image.width + gap
    return output


def content_box(image):
    """(x0, y0, x1, y1) that trim_to_content crops to, or None when nothing is dark."""
    arr = np.array(ImageOps.grayscale(image))
    ys, xs = np.where(arr < 195)
    if len(xs) == 0:
        return None
    return (max(0, int(xs.min()) - 10), max(0, int(ys.min()) - 6),
            min(image.width, int(xs.max()) + 11), min(image.height, int(ys.max()) + 7))


def trim_to_content(image):
    box = content_box(image)
    if box is None:
        return image.copy()
    return image.crop(box)


def fit_image_width(image, maximum_width):
    if image.width <= maximum_width:
        return image.copy()
    ratio = maximum_width / image.width
    return image.resize((
        maximum_width,
        max(1, int(image.height * ratio)),
    ))


# ============================================================
# IMAGE VARIANTS
# ============================================================

def make_binary(image, threshold):
    gray = ImageOps.grayscale(image)
    gray = ImageEnhance.Contrast(gray).enhance(2.0)
    gray = gray.filter(ImageFilter.SHARPEN)
    arr = np.array(gray)
    output = np.full(arr.shape, 255, dtype=np.uint8)
    output[arr < threshold] = 0
    return Image.fromarray(output).convert("RGB")


def get_rgb_arrays(image):
    rgb = np.array(image.convert("RGB")).astype(np.int16)
    return rgb, rgb[:, :, 0], rgb[:, :, 1], rgb[:, :, 2]


def normalize_array_to_grayscale(values, invert=False):
    values = values.astype(np.float32)
    minimum = float(values.min())
    maximum = float(values.max())
    if maximum - minimum < 1e-6:
        normalized = np.full(values.shape, 255, dtype=np.uint8)
    else:
        normalized = (
            (values - minimum) / (maximum - minimum) * 255.0
        ).astype(np.uint8)
    if invert:
        normalized = 255 - normalized
    return Image.fromarray(normalized).convert("RGB")


def make_red_minus_green_image(image):
    rgb, r, g, b = get_rgb_arrays(image)
    return normalize_array_to_grayscale(r - g, invert=True)


def make_red_excess_image(image):
    rgb, r, g, b = get_rgb_arrays(image)
    return normalize_array_to_grayscale(r - (g + b) / 2.0, invert=True)


def make_saturation_image(image):
    arr = np.array(image.convert("HSV"))
    saturation = arr[:, :, 1]
    return Image.fromarray((255 - saturation).astype(np.uint8)).convert("RGB")


def make_red_mask_array(image, loose=False):
    """
    Mask of RED handwriting only. Also requires green and blue to be small
    relative to red, so orange paper does not fill the gaps between words.
    """
    rgb, r, g, b = get_rgb_arrays(image)
    r_f = r.astype(np.float32)
    g_f = g.astype(np.float32)
    b_f = b.astype(np.float32)
    red_minus_green = r_f - g_f
    red_minus_blue = r_f - b_f
    if loose:
        mask = (
            (r_f > 85)
            & (red_minus_green > 24)
            & (red_minus_blue > 24)
            & (g_f < r_f * 0.68)
            & (b_f < r_f * 0.68)
        )
    else:
        mask = (
            (r_f > 95)
            & (red_minus_green > 34)
            & (red_minus_blue > 34)
            & (g_f < r_f * 0.62)
            & (b_f < r_f * 0.62)
        )
    return mask.astype(np.uint8)


def dilate_mask(mask, radius=1):
    if radius <= 0:
        return mask.copy()
    padded = np.pad(mask, ((radius, radius), (radius, radius)), mode="constant")
    output = np.zeros_like(mask)
    size = radius * 2 + 1
    for dy in range(size):
        for dx in range(size):
            output = np.maximum(
                output,
                padded[dy:dy + mask.shape[0], dx:dx + mask.shape[1]],
            )
    return output


def make_red_mask_image(image, dilate=False, loose=False):
    mask = make_red_mask_array(image, loose=loose)
    if dilate:
        mask = dilate_mask(mask, radius=1)
    output = np.full(mask.shape, 255, dtype=np.uint8)
    output[mask > 0] = 0
    return Image.fromarray(output).convert("RGB")


def create_red_ocr_versions(image):
    return [
        ("RedMinusGreen", make_red_minus_green_image(image)),
        ("RedExcess", make_red_excess_image(image)),
        ("Saturation", make_saturation_image(image)),
        ("RedMask", make_red_mask_image(image, dilate=False, loose=False)),
        ("RedMaskDilated", make_red_mask_image(image, dilate=True, loose=False)),
        ("RedMaskLoose", make_red_mask_image(image, dilate=False, loose=True)),
        ("RedMaskLooseDilated", make_red_mask_image(image, dilate=True, loose=True)),
    ]


# ============================================================
# FIND DIG PACKET FROM WHEEL COUNT
# ============================================================


def wheel_count_mismatch_warning(dig_path, wheel_count):
    """
    Warning text when the Dig Packet file name names a DIFFERENT wheel count
    (e.g. "WC 254036.63 ... DIG 7.pdf" picked for a 5294.76 form).
    """
    name = os.path.basename(dig_path or "")
    match = re.search(r"\bWC\s*[-_#:]?\s*([0-9]+(?:\.[0-9]+)?)", name, re.IGNORECASE)
    if not match or not wheel_count:
        return None
    file_wc = match.group(1)
    form_wc = re.sub(r"[^0-9.]", "", str(wheel_count))
    try:
        same = wheel_same(file_wc, form_wc)                 # S438: exactly the same
    except ValueError:
        same = file_wc == form_wc
    if same:
        return None
    return (
        f"WARNING: WHEEL COUNT MISMATCH - the 6000 form is Wheel Count {wheel_count}, "
        f"but this Dig Packet's file name says WC {file_wc}. "
        "No Dig Packet with the form's Wheel Count was found, so the newest "
        '"Dig" file was used. These Dig values probably belong to a different dig.'
    )


# ============================================================
# PAGE RENDER
# ============================================================

def render_page(page, zoom):
    """The page as a picture. S365: made straight from the rendered pixels (no PNG in between) - the same
    pixels."""
    pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
    mode = {1: "L", 3: "RGB", 4: "RGBA"}[pix.n]
    return Image.frombytes(mode, [pix.width, pix.height], pix.samples).convert("RGB")


# ============================================================
# PRINTED LABEL OCR
# ============================================================

def clean_label_text(text):
    return re.sub(r"[^a-z]", "", text.lower())


LABEL_SEARCH_SCALE = 0.5      # S134: the label search first reads page 1 at this size


def get_easy_page_results(page_image, scale=1.0):
    """EasyOCR over page 1, to find the printed labels. S134: with scale < 1 a smaller
    copy is read (faster) and every box is put back in full-page coordinates."""
    print()
    print("Using EasyOCR to locate printed labels" + (f" (page at {scale:.0%} size first - S134)..."
                                                      if scale < 1 else "..."))
    picture = page_image if scale >= 1 else page_image.resize(
        (max(1, int(page_image.width * scale)), max(1, int(page_image.height * scale))), Image.LANCZOS)
    results = easy_reader.readtext(
        np.array(picture),
        detail=1,
        paragraph=False,
    )
    if scale >= 1:
        return results
    back = 1.0 / scale
    return [([[point[0] * back, point[1] * back] for point in result[0]],) + tuple(result[1:])
            for result in results]


def read_labels_in_box(page_image, box):
    """S138: EasyOCR on one full-size area of page 1; boxes put back in page coordinates."""
    x0, y0, x1, y1 = (int(max(0, v)) for v in box)
    x1, y1 = min(page_image.width, x1), min(page_image.height, y1)
    if x1 - x0 < 8 or y1 - y0 < 8:
        return []
    results = easy_reader.readtext(np.array(page_image.crop((x0, y0, x1, y1))), detail=1, paragraph=False)
    return [([[p[0] + x0, p[1] + y0] for p in r[0]],) + tuple(r[1:]) for r in results]


def read_labels_around(page_image, label):
    """S138: the full-size area around a label found on the half-size copy - its own row,
    from a little left of it to well past its end (so a '6.' in front or a word after it
    is read too, as the whole-page read would)."""
    h = max(8, int(label["y1"] - label["y0"]))
    return read_labels_in_box(page_image, (label["x0"] - 3 * h, label["y0"] - h, label["x1"] + 3 * h,
                                           label["y1"] + h))


def find_label(results, wanted_label):
    target = clean_label_text(wanted_label)
    alternatives = {
        "latitude": ["latitude", "latltude", "latitde", "lattude"],
        "longitude": ["longitude", "longltude", "longtude", "longitud"],
        "notes": ["notes", "note", "noles"],
    }
    allowed = alternatives.get(target, [target])

    for result in results:
        if len(result) < 2:
            continue
        bbox = result[0]
        text = result[1]
        confidence = safe_float(result[2]) if len(result) >= 3 else 0.0
        cleaned = clean_label_text(text)
        if cleaned in allowed or target in cleaned:
            xs = [point[0] for point in bbox]
            ys = [point[1] for point in bbox]
            print(f'{wanted_label} found as "{text}"')
            return {
                "text": text,
                "x0": int(min(xs)),
                "y0": int(min(ys)),
                "x1": int(max(xs)),
                "y1": int(max(ys)),
                "confidence": confidence,
            }

    print(f"{wanted_label}: NOT FOUND")
    return None


# ============================================================
# PADDLE TEXT RECOGNIZER
# ============================================================

BATCH_OCR = True                 # read several pictures per OCR call (same results, faster on the GPU)
PADDLE_BATCH_SIZE = 16
BATCH_SHAPE_TOLERANCE = 1.15     # pictures batched together differ in width/height ratio by <= 15%
# S32: batching is checked and switched off PER KIND of reading (page 1 values, Notes
# whole lines, Notes word pictures, letter crops, table cells, table headers, EasyOCR):
# the first batch of each kind in a run is also read one picture at a time (at most
# BATCH_CHECK_SAMPLE pictures of it); a difference switches batching off for THAT kind
# only, and the one-at-a-time reads are used. A batch call that fails outright still
# switches batching off everywhere (BATCH_OCR).
BATCH_CHECK_SAMPLE = 20
BATCH_CHECKED = set()            # kinds whose first batch has been checked this run
BATCH_OFF = set()                # kinds whose batch reads differed -> read one at a time


def _paddle_result_text(result):
    """(text, confidence) out of one PaddleX recognition result."""
    try:
        data = result.json
        if callable(data):
            data = data()
        if isinstance(data, str):
            data = json.loads(data)
        if isinstance(data, dict):
            res = data.get("res", data)
            return str(res.get("rec_text", "")), safe_float(res.get("rec_score", 0.0))
    except Exception:
        pass
    try:
        return str(result["rec_text"]), safe_float(result["rec_score"])
    except Exception:
        return "", 0.0


def _shape_groups(images, tolerance=BATCH_SHAPE_TOLERANCE, limit=PADDLE_BATCH_SIZE):
    """Indexes of the pictures, in groups of similar width/height ratio (so batching
    adds no extra padding that could change a read), at most `limit` per group."""
    order = sorted(range(len(images)), key=lambda i: images[i].width / max(1, images[i].height))
    groups, current, first_ratio = [], [], None
    for i in order:
        ratio = images[i].width / max(1, images[i].height)
        if current and (ratio > first_ratio * tolerance or len(current) >= limit):
            groups.append(current)
            current = []
        if not current:
            first_ratio = ratio
        current.append(i)
    if current:
        groups.append(current)
    return groups


def paddle_read_text_images(images, kind="other"):
    """PaddleOCR reads of several pictures - [(text, confidence)] in the same order.
    Pictures of similar shape are sent to the GPU together (one call per group)
    instead of one call each. The first batch of each KIND of reading in a run is
    also read one at a time (up to BATCH_CHECK_SAMPLE pictures) and the log says how
    many came out identical and, for any that did not, both reads; a difference
    switches batching off for that kind only. If a batch call fails, everything is
    read one at a time as before."""
    global BATCH_OCR
    images = list(images)
    if not images:
        return []
    if not BATCH_OCR or kind in BATCH_OFF or len(images) == 1:
        return [paddle_read_text_image(image) for image in images]
    out = [None] * len(images)
    try:
        for group in _shape_groups(images):
            arrays = [np.ascontiguousarray(np.array(images[i].convert("RGB"))[:, :, ::-1]) for i in group]
            results = list(text_reader.predict(input=arrays, batch_size=len(arrays)))
            if len(results) != len(arrays):
                raise ValueError(f"{len(results)} results for {len(arrays)} pictures")
            for i, result in zip(group, results):
                out[i] = _paddle_result_text(result)
    except Exception as exc:
        BATCH_OCR = False
        print(f"BATCH OCR: PaddleOCR batch reading failed ({exc}) - reading one picture at a time from now on")
        return [paddle_read_text_image(image) for image in images]
    if kind not in BATCH_CHECKED:
        BATCH_CHECKED.add(kind)
        checked = list(range(min(len(images), BATCH_CHECK_SAMPLE)))
        single = {i: paddle_read_text_image(images[i]) for i in checked}
        differ = [i for i in checked if batch_reads_differ(out[i], single[i])]
        junk = [i for i in checked if out[i][0] != single[i][0] and i not in differ]
        sample = (f"{len(checked)} of the {len(images)} pictures" if len(checked) < len(images)
                  else f"{len(images)} pictures")
        print(f"BATCH OCR CHECK (PaddleOCR, {kind}): {len(checked) - len(differ)} of {sample} read together "
              f"gave the same text as reading them one at a time"
              + (f" ({len(junk)} junk read(s) not counted)" if junk else "")
              + ("" if not differ else f" - batching switched OFF for {kind} only"))
        for i in differ:
            print(f"    picture {i + 1} ({images[i].width}x{images[i].height} px): together "
                  f"'{out[i][0]}' ({out[i][1]:.3f}) vs one at a time '{single[i][0]}' ({single[i][1]:.3f})")
        for i in junk:
            print(f"    picture {i + 1} ({images[i].width}x{images[i].height} px): together "
                  f"'{out[i][0]}' ({out[i][1]:.3f}) vs one at a time '{single[i][0]}' ({single[i][1]:.3f}) "
                  f"- both under {BATCH_JUNK_CONFIDENCE:.0%} confidence, nothing usable either way - not counted")
        if differ:
            BATCH_OFF.add(kind)
            return [single[i] if i in single else paddle_read_text_image(images[i]) for i in range(len(images))]
    return out


# S59: a batch check difference counts only when at least one of the two reads is a real
# read. Both under BATCH_JUNK_CONFIDENCE = nothing usable was on the picture either way
# (e.g. 'C' 0.065 vs '6' 0.065 on an empty letter crop) - not a reason to stop batching.
BATCH_JUNK_CONFIDENCE = 0.20


def batch_reads_differ(together, alone):
    """S59: True when a batched read and a one-at-a-time read really differ."""
    if together[0] == alone[0]:
        return False
    return max(float(together[1] or 0), float(alone[1] or 0)) >= BATCH_JUNK_CONFIDENCE


def easy_read_arrays(arrays, check_key="easy"):
    """EasyOCR detail reads of several same-size pictures - [results] in order. Sent
    together through EasyOCR's batch reader when they all have the same size; the
    first batch of a run is also read one at a time and compared in the log."""
    global BATCH_OCR
    arrays = list(arrays)
    if not arrays:
        return []
    def one(a):
        try:
            return easy_reader.readtext(a, detail=1, paragraph=False)
        except Exception:
            return []
    same_size = len({a.shape for a in arrays}) == 1
    if (not BATCH_OCR or check_key in BATCH_OFF or len(arrays) == 1 or not same_size
            or not hasattr(easy_reader, "readtext_batched")):
        return [one(a) for a in arrays]
    try:
        batched = easy_reader.readtext_batched(arrays, detail=1, paragraph=False)
        if len(batched) != len(arrays):
            raise ValueError("result count")
    except Exception as exc:
        print(f"BATCH OCR: EasyOCR batch reading failed ({exc}) - one picture at a time for this group")
        return [one(a) for a in arrays]
    if check_key not in BATCH_CHECKED:
        BATCH_CHECKED.add(check_key)
        single = [one(a) for a in arrays]
        text = lambda rs: " ".join(str(r[1]) for r in sorted(rs, key=lambda r: min(p[0] for p in r[0])))
        differ = [i for i, (a, b) in enumerate(zip(batched, single)) if text(a) != text(b)]
        print(f"BATCH OCR CHECK (EasyOCR{', padded to one size' if check_key == 'easy_padded' else ''}): "
              f"{len(arrays) - len(differ)} of {len(arrays)} batch reads identical to one-at-a-time reads"
              + ("" if not differ else " - EasyOCR batching switched OFF for the rest of this run"))
        for i in differ:
            print(f"    picture {i + 1}: together '{text(batched[i])}' vs one at a time '{text(single[i])}'")
        if differ:
            BATCH_OFF.add(check_key)
            return single
    return batched


SINGLE_READ = {"array": True, "checked": False}   # S12: one picture read straight from memory


def paddle_read_text_image(image):
    """PaddleOCR read of ONE picture -> (text, confidence). The picture is handed to
    PaddleOCR straight from memory (the same BGR pixel array the batch reads use)
    instead of being saved as a PNG file and read back. The FIRST single read of a run
    is also done the old way (temp PNG file) and compared in the log; any difference,
    or any error, switches back to the file way for the rest of the run."""
    if SINGLE_READ["array"]:
        try:
            array = np.ascontiguousarray(np.array(image.convert("RGB"))[:, :, ::-1])
            results = list(text_reader.predict(input=array, batch_size=1))
            from_memory = _paddle_result_text(results[0]) if results else ("", 0.0)
        except Exception as exc:
            SINGLE_READ["array"] = False
            print(f"SINGLE OCR READ: reading from memory failed ({exc}) - "
                  f"saving each picture as a file again for the rest of this run")
            return paddle_read_text_image_from_file(image)
        if not SINGLE_READ["checked"]:
            SINGLE_READ["checked"] = True
            from_file = paddle_read_text_image_from_file(image)
            same = from_file[0] == from_memory[0]
            print(f"SINGLE OCR READ CHECK: read from memory {from_memory[0]!r} vs from a PNG file "
                  f"{from_file[0]!r} -> " + ("identical" if same else
                                             "DIFFERENT - files used again for the rest of this run"))
            if not same:
                SINGLE_READ["array"] = False
                return from_file
        return from_memory
    return paddle_read_text_image_from_file(image)


def paddle_read_text_image_from_file(image):
    with tempfile.NamedTemporaryFile(suffix=".png", delete=False) as temp:
        temp_path = temp.name
    try:
        image.save(temp_path, "PNG")
        output = text_reader.predict(input=temp_path, batch_size=1)
        results = list(output)
        if not results:
            return "", 0.0
        result = results[0]
        try:
            data = result.json
            if callable(data):
                data = data()
            if isinstance(data, str):
                data = json.loads(data)
            if isinstance(data, dict):
                res = data.get("res", data)
                return (
                    str(res.get("rec_text", "")),
                    safe_float(res.get("rec_score", 0.0)),
                )
        except Exception:
            pass
        try:
            return str(result["rec_text"]), safe_float(result["rec_score"])
        except Exception:
            return "", 0.0
    finally:
        try:
            os.remove(temp_path)
        except OSError:
            pass


# ============================================================
# COORDINATE HELPERS
# ============================================================

def row_runs(row):
    """(starts, ends) of the True runs in one row (end = one past the run) - numpy, the
    same runs a left-to-right pixel loop finds."""
    edges = np.flatnonzero(np.diff(np.concatenate(([0], row.astype(np.int8), [0]))))
    return edges[0::2], edges[1::2]


def longest_run_per_row(mask):
    """Longest unbroken True run in each row (0 for a row with none) - all rows at once:
    the run edges of the whole picture are found in one go (each row padded with an
    empty pixel on both sides, so runs never join across rows)."""
    mask = np.asarray(mask, dtype=bool)
    out = np.zeros(mask.shape[0], dtype=np.int64)
    if mask.size == 0:
        return out
    padded = np.zeros((mask.shape[0], mask.shape[1] + 2), dtype=np.int8)
    padded[:, 1:-1] = mask
    rows, cols = np.nonzero(np.diff(padded, axis=1))
    # edges come row by row, left to right: start, end, start, end ...
    lengths = cols[1::2] - cols[0::2]
    np.maximum.at(out, rows[0::2], lengths)
    return out


def find_underline_y(image):
    gray = np.array(ImageOps.grayscale(image))
    dark = gray < 120
    height, width = dark.shape
    first = int(height * 0.45)
    if first >= height:
        return None
    longest = longest_run_per_row(dark[first:])
    best = int(longest.max()) if len(longest) else 0
    if best == 0:
        return None                                    # no dark pixel in those rows
    best_y = first + int(np.argmax(longest))           # the first row with the longest run
    if best > width * 0.30:
        return best_y
    return None


def remove_horizontal_lines(image):
    gray = np.array(ImageOps.grayscale(image))
    output = np.array(image).copy()
    dark = gray < 120
    height, width = dark.shape
    for y in np.flatnonzero(longest_run_per_row(dark) > width * 0.35):
        output[max(0, y - 3):min(height, y + 4), :] = 255
    return Image.fromarray(output)


def clean_coordinates(raw, field):
    """
    Return EVERY valid coordinate found in one OCR read, left to right.
    A nearby A/B/C-style marker is kept when OCR supplies one.
    """
    if raw is None:
        return []
    normalized = (
        str(raw)
        .replace(",", ".")
        .replace("—", "-")
        .replace("–", "-")
        .replace("−", "-")
    )
    compact = re.sub(r"\s+", "", normalized)

    if field == "Wheel Count":
        pattern = re.compile(r"\d{5,7}\.\d{2}")                  # e.g. 211444.80
    elif field == "Mile Post/Station":
        # e.g. 991+48 or 77+1957; a handwritten '+' read as t/T between digits counts as '+'
        compact = re.sub(r"(?<=\d)[tT](?=\d)", "+", compact)
        pattern = re.compile(r"\d{1,5}\+\d{2,4}(?:\.\d{1,2})?")
    elif field == "Latitude":
        pattern = re.compile(r"[+-]?\d{2}\.\d{5,12}")
    else:
        pattern = re.compile(r"[+-]?\d{2,3}\.\d{5,12}")

    output = []
    seen_values = set()
    for order_index, match in enumerate(pattern.finditer(compact)):
        candidate = match.group(0)
        if field in ("Latitude", "Longitude"):
            try:
                numeric = float(candidate)
            except ValueError:
                continue
            if field == "Latitude":
                if not (-90 <= numeric <= 90):
                    continue
            else:
                if not (-180 <= numeric <= 180):
                    continue
        if candidate in seen_values:
            continue
        seen_values.add(candidate)

        prefix = compact[max(0, match.start() - 8):match.start()]
        marker = None
        marker_match = re.search(
            r"(?:\(|\[)?([A-Z])(?:\)|\]|[:.)-])?$",
            prefix.upper(),
        )
        if marker_match:
            marker = marker_match.group(1)

        output.append({
            "value": candidate,
            "marker": marker,
            "order_index": order_index,
            "text_start": match.start(),
        })
    return output


def split_coordinate_row_into_physical_groups(image):
    """
    Split a handwritten coordinate row into physically separate left-to-right
    coordinate groups before OCR, so a second coordinate on a long row is not
    ignored by the recognizer.
    """
    rgb = np.array(image.convert("RGB"))
    if rgb.size == 0:
        return [{"image": image, "x0": 0, "x1": image.width, "source": "whole-row-fallback"}]

    r = rgb[:, :, 0].astype(np.int16)
    g = rgb[:, :, 1].astype(np.int16)
    b = rgb[:, :, 2].astype(np.int16)

    red_mask = ((r >= g + 18) & (r >= b + 18) & (r >= 70)).astype(np.uint8)
    kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (3, 3))
    red_mask = cv2.morphologyEx(red_mask, cv2.MORPH_CLOSE, kernel, iterations=1)

    active = red_mask.sum(axis=0) > 0
    runs = []
    start = None
    for x, is_active in enumerate(active):
        if is_active and start is None:
            start = x
        elif not is_active and start is not None:
            runs.append((start, x - 1))
            start = None
    if start is not None:
        runs.append((start, len(active) - 1))

    if not runs:
        return [{"image": image, "x0": 0, "x1": image.width, "source": "whole-row-fallback"}]

    normal_gap_limit = max(12, int(round(image.width * 0.028)))
    merged_runs = [list(runs[0])]
    for x0, x1 in runs[1:]:
        previous = merged_runs[-1]
        gap = x0 - previous[1] - 1
        if gap <= normal_gap_limit:
            previous[1] = x1
        else:
            merged_runs.append([x0, x1])

    substantial = []
    for x0, x1 in merged_runs:
        region_pixels = int(red_mask[:, x0:x1 + 1].sum())
        if (
            x1 - x0 + 1 >= max(35, int(image.width * 0.08))
            and region_pixels >= 255 * 60
        ):
            substantial.append([x0, x1])

    if len(substantial) < 2:
        candidate_gaps = []
        for left, right in zip(runs[:-1], runs[1:]):
            gap = right[0] - left[1] - 1
            if gap < max(20, int(image.width * 0.035)):
                continue
            split_x = (left[1] + right[0]) // 2
            left_ink = int(red_mask[:, :split_x].sum())
            right_ink = int(red_mask[:, split_x:].sum())
            if left_ink >= 255 * 120 and right_ink >= 255 * 120:
                candidate_gaps.append((gap, split_x))
        if candidate_gaps:
            candidate_gaps.sort(reverse=True)
            largest_gap, split_x = candidate_gaps[0]
            substantial = [
                [runs[0][0], split_x - 1],
                [split_x + 1, runs[-1][1]],
            ]

    if len(substantial) < 2:
        return [{"image": image, "x0": 0, "x1": image.width, "source": "whole-row"}]

    pad = max(8, int(round(image.width * 0.012)))
    output = []
    for group_index, (x0, x1) in enumerate(substantial, start=1):
        crop_x0 = max(0, x0 - pad)
        crop_x1 = min(image.width, x1 + pad + 1)
        output.append({
            "image": image.crop((crop_x0, 0, crop_x1, image.height)),
            "x0": crop_x0,
            "x1": crop_x1,
            "group_index": group_index,
            "source": "physical-group",
        })

    print()
    print("PHYSICAL COORDINATE ROW SEGMENTATION:", len(output), "group(s)")
    for group in output:
        print("  Group", group["group_index"], "x=", (group["x0"], group["x1"]))
    return output


COORDINATE_DUPLICATE_TOLERANCE = 2e-6   # degrees (~0.2 m): same handwritten number


def merge_near_duplicate_coordinates(items, tolerance=COORDINATE_DUPLICATE_TOLERANCE):
    """
    Readings closer than `tolerance` are the SAME handwritten coordinate read
    slightly differently (32.31071514 / 32.31071544 / 32.3107154). Keep the
    reading with the most votes and add the others' votes to it.
    """
    kept = []
    for item in sorted(items, key=lambda i: (i["vote_count"], i["average_confidence"]), reverse=True):
        try:
            value = float(item["value"])
        except (TypeError, ValueError):
            kept.append(item)
            continue
        twin = next((k for k in kept if abs(float(k["value"]) - value) <= tolerance), None)
        if twin is None:
            kept.append(dict(item, merged_readings=[item["value"]]))
            continue
        for count in ("vote_count", "whole_row_votes", "physical_votes"):
            twin[count] = twin.get(count, 0) + item.get(count, 0)
        twin["merged_readings"].append(item["value"])
        if not twin.get("marker") and item.get("marker"):
            twin["marker"] = item["marker"]
    for item in kept:
        if len(item.get("merged_readings", [])) > 1:
            print(f"  Merged near-identical readings into {item['value']}: {item['merged_readings'][1:]}")
    return kept


def merge_glued_marker_reads(items):
    """A read that is another accepted value with 1-2 extra DIGITS stuck on its start
    or end is the same handwritten value with a neighbouring mark glued on - e.g. the
    circled '(B)' read as '8': 8211448.73 = 8 + 211448.73, 991+4889 = 991+48 + 89.
    Its votes are added to the shorter value and it is dropped."""
    kept = list(items)
    for long_item in sorted(items, key=lambda i: -len(str(i["value"]))):
        long_value = str(long_item["value"])
        for short_item in kept:
            short_value = str(short_item["value"])
            if short_item is long_item or len(short_value) >= len(long_value):
                continue
            extra = None
            if long_value.endswith(short_value):
                extra = long_value[:-len(short_value)]
            elif long_value.startswith(short_value):
                extra = long_value[len(short_value):]
            if extra and extra.isdigit() and len(extra) <= 2:
                for count in ("vote_count", "whole_row_votes", "physical_votes"):
                    short_item[count] = short_item.get(count, 0) + long_item.get(count, 0)
                if not short_item.get("marker") and long_item.get("marker"):
                    short_item["marker"] = long_item["marker"]
                print(f"  Glued read {long_value} = {short_value} + extra '{extra}' "
                      f"(a neighbouring mark read as a digit) -> merged into {short_value}")
                kept = [k for k in kept if k is not long_item]
                break
    return kept


def relabel_coordinate_markers(items):
    """Markers must be unique and consecutive (A, B, C...) when there is more than one."""
    if len(items) < 2:
        return items
    markers = [item.get("marker") for item in items]
    expected = [chr(ord("A") + i) for i in range(len(items))]
    if markers != expected:
        for item, letter in zip(items, expected):
            item["marker"] = letter
    return items


EARLY_STOP_VERSIONS = ("Original", "130", "150", "170")   # S131: the first look (x1 and x2 of each = 8 reads)
EARLY_STOP_AGREE = 6                                       # S131: of those 8, at least this many must agree


# S151: what each page-1 line SHOULD say. The map notes and table rows (text first) give,
# per anomaly, its Wheel Count, Latitude, Longitude and Mile Post. Once one page-1 line
# is matched to them (Wheel Count first: exact numbers printed in the packet), (A), (B),
# ... are tied to their anomalies and every other line knows its expected values.
EXPECTED = {"rows": [], "by_field": {}, "from": None}
EXPECTED_FIELDS = ("Wheel Count", "Latitude", "Longitude", "Mile Post/Station")


def build_expected_rows(results):
    """S151: one record per anomaly printed in the packet: {field: value, 'where': ...}."""
    rows = []
    for map_page in results.get("Map Pages") or []:
        for note in map_page.get("notes", []):
            values = {k: v for k, v in _note_fields(note.get("value")).items() if v}
            if values.get("Wheel Count"):
                values["where"] = f"map note {note.get('index')} on map page {map_page.get('page_number')}"
                rows.append(values)
    for table_page in results.get("Table Highlights") or []:
        for item in table_page.get("items", []):
            odometer = re.sub(r"[^0-9.]", "", str(cmp_table_cell(item, r"odometer") or ""))
            if not odometer:
                continue
            row = next((r for r in rows if r.get("Wheel Count") == odometer), None)
            if row is None:
                row = {"Wheel Count": odometer,
                       "where": f"table page {table_page.get('page_number')} {item.get('title')}"}
                rows.append(row)
            for field, pattern in (("Latitude", r"latitude"), ("Longitude", r"longitude")):
                value = str(cmp_table_cell(item, pattern) or "").strip()
                if field not in row and re.fullmatch(r"-?\d+\.\d+", value):
                    row[field] = value
    EXPECTED.update({"rows": rows, "by_field": {}, "from": None})


def value_fits(read_value, expected):
    """S151: a read value fits an expected one when it is the same, or one character is
    wrong, missing or extra (look-alikes count as the same - S145)."""
    read_value, expected = str(read_value or ""), str(expected or "")
    if not read_value or not expected:
        return False
    return read_value == expected or (len(expected) >= 5 and _one_edit_apart(read_value, expected))


def match_bullets_to_rows(field, result):
    """S151: tie this line's values - (A), (B), ... in order - to the packet's anomaly
    records by this field. Every value must fit exactly one record (and no record twice).
    Then every other line's expected values are known. Returns True when it worked."""
    if EXPECTED["by_field"] or not EXPECTED["rows"]:
        return False
    items = (result or {}).get("items") or []
    if not items:
        return False
    chosen = []
    for item in items:
        fits = [row for row in EXPECTED["rows"] if field in row and value_fits(item.get("value"), row[field])
                and row not in chosen]
        exact = [row for row in fits if row[field] == item.get("value")]
        fits = exact or fits
        if len(fits) != 1:
            return False
        chosen.append(fits[0])
    EXPECTED["by_field"] = {f: [row.get(f) for row in chosen] for f in EXPECTED_FIELDS}
    EXPECTED["from"] = field
    shown = "; ".join(f"({item.get('marker') or chr(65 + i)}) = {row['where']}"
                      for i, (item, row) in enumerate(zip(items, chosen)))
    print(f"EXPECTED VALUES: the {field} line ties the bullets to the packet's anomalies ({shown}) - every "
          f"other page-1 line now knows what it should say: "
          + "; ".join(f"{f} {', '.join(str(v) for v in vals)}" for f, vals in EXPECTED["by_field"].items()
                      if f != field and any(vals)))
    return True


def apply_expected_values(field, result, final=False):
    """S151: a line's values checked against what it should say. A value that fits its
    expected value (one character off at most) becomes the expected value - with a blue
    note saying where it came from. One that clearly does not fit is left as read, with a
    warning: the handwriting may really differ from the printed data (e.g. a re-measured
    mile post) - that must show, not be overwritten."""
    expected = EXPECTED["by_field"].get(field)
    items = (result or {}).get("items") or []
    if not expected or not items or len(items) != len(expected) or not all(expected):
        return
    notes, warnings = [], []
    for item, want in zip(items, expected):
        have = str(item.get("value") or "")
        label = f"({item.get('marker')})" if item.get("marker") and len(items) > 1 else ""
        if have == want:
            continue
        if value_fits(have, want):
            item["value"] = want
            notes.append(f"{field} {label}: read {have} - the line's expected value is {want} (the bullet's anomaly, "
                         f"tied by the {EXPECTED['from']} line) and the read fits it")
            print(f"  EXPECTED {field} {label}: {have} -> {want} (fits, one character off at most)")
        elif final:
            warnings.append(f"⚠ {field} {label}: read {have}, but this bullet's anomaly says {want} - check the "
                            f"handwriting")
            print(f"EXPECTED {field} {label}: {have} still does not fit {want} after every check - warning")
        else:
            print(f"  EXPECTED {field} {label}: read {have} does not fit {want} - left as read for now (the map / "
                  f"table checks at the end may still settle it)")
    if len(items) == 1:
        result["value"] = items[0]["value"]
    if notes:
        result["note"] = "  ".join(([result["note"]] if result.get("note") else []) + notes)
    if warnings:
        result["warning"] = "  ".join(([result["warning"]] if result.get("warning") else []) + warnings)


def value_span_in_read(read, value, letter=None):
    """S158: where the value sits in a read - exactly (look-alikes), one character off
    (S145), or 'ends like it, about its length' (S145). A span or None."""
    read, value = str(read or ""), str(value or "")
    if not read or not value:
        return None
    return (re.search(lookalike_pattern(value), read) or (fuzzy_value_match(read, value) if len(value) >= 6 else None)
            or value_end_fits(read, value, letter))


def items_from_expected(field, result):
    """S158: the vote gave fewer values than this line's expected values (each read was off
    in a different place, so no single spelling got enough votes) - but when every
    expected value does appear in the reads (one character off at most), the line's
    values are the expected ones, in order, each placed where it appears in the reads.
    Then the line is cut into all its snips as usual. Returns True when it did that."""
    expected = EXPECTED["by_field"].get(field)
    items = (result or {}).get("items") or []
    reads = [re.sub(r"\s+", "", r) for r in (result or {}).get("raw_reads") or []]
    if not expected or not all(expected) or len(items) >= len(expected) or not reads:
        return False
    built = []
    for index, want in enumerate(expected):
        letter = chr(ord("A") + index)
        fractions = []
        for read in reads:
            span = value_span_in_read(read, want)
            if span is not None:
                fractions.append(span.start() / max(1, len(read)))
        if len(fractions) < 2:
            return False
        built.append({"value": want, "marker": letter, "position_fraction": sum(fractions) / len(fractions),
                      "vote_count": len(fractions), "whole_row_votes": len(fractions), "physical_votes": 0,
                      "average_confidence": 0.0, "from_expected": True})
    if any(b["position_fraction"] <= a["position_fraction"] for a, b in zip(built, built[1:])):
        return False
    result["items"] = built
    result["value"], result["marker"] = built[0]["value"], built[0]["marker"]
    print(f"  EXPECTED {field}: the vote gave {len(items)} value(s), but all {len(expected)} expected values are in "
          f"the reads (" + ", ".join(f"({b['marker']}) {b['value']} in {b['vote_count']} reads" for b in built)
          + ") - the line's values are the expected ones (S158)")
    return True


def early_stop_agrees(field, raws):
    """S131: True-ish (a short description) when the first reads of a page-1 line already
    settle it: at least EARLY_STOP_AGREE of them give the same number of values, every
    value position has the same value in at least EARLY_STOP_AGREE of them, that number
    fits the page's bullets (when known), and every value is one printed in this packet.
    Otherwise None - then all 30 pictures are read as before."""
    known = set((TEXT_FIRST.get("known") or {}).get(field) or [])
    if not known or not raws:
        return None
    parsed = [[item["value"] for item in clean_coordinates(raw, field)] for raw in raws]
    expected = EXPECTED["by_field"].get(field)
    if expected and all(expected):
        # S151: this line's values are known - the first reads only have to fit them
        same_count = [values for values in parsed if len(values) == len(expected)]
        if len(same_count) >= EARLY_STOP_AGREE:
            settled = []
            for position, want in enumerate(expected):
                votes = sum(1 for values in same_count if value_fits(values[position], want))
                if votes < EARLY_STOP_AGREE:
                    break
                settled.append(f"{want} ({votes}/{len(raws)}, expected)")
            else:
                return ", ".join(settled)
    counts = Counter(len(values) for values in parsed if values)
    if not counts:
        return None
    count, how_many = counts.most_common(1)[0]
    hint = PAGE1_BULLET_HINT["count"]
    if how_many < EARLY_STOP_AGREE or (hint and count != hint):
        return None
    same_count = [values for values in parsed if len(values) == count]
    settled = []
    for position in range(count):
        value, votes = Counter(values[position] for values in same_count).most_common(1)[0]
        if votes < EARLY_STOP_AGREE or value not in known:
            return None
        settled.append(f"{value} ({votes}/{len(raws)})")
    return ", ".join(settled)


def coordinate_consensus(image, field, allow_early_stop=True):
    """
    Multi-coordinate consensus from whole-row OCR plus physical left-to-right
    group OCR. Final values are merged across both paths.
    """
    physical_groups = split_coordinate_row_into_physical_groups(image)

    sources = [{"name": "WholeRow", "image": image, "group_index": None, "x0": 0}]
    if (
        len(physical_groups) > 1
        or physical_groups[0].get("source") == "physical-group"
    ):
        for group in physical_groups:
            sources.append({
                "name": "PhysicalGroup" + str(group.get("group_index", len(sources))),
                "image": group["image"],
                "group_index": group.get("group_index"),
                "x0": group.get("x0", 0),
            })

    attempts = []
    for source in sources:
        versions = [("Original", source["image"])]
        for threshold in [110, 120, 130, 140, 150, 160, 170, 180, 190]:
            versions.append((str(threshold), make_binary(source["image"], threshold)))

        jobs = [(version_name, scale, version.resize((version.width * scale, version.height * scale)))
                for version_name, version in versions for scale in [1, 2, 3]]
        # S131: a first look - 8 of the 30 pictures; when they already agree on every value
        # and every value is printed in this packet (text first), the other 22 are not read
        first = [i for i, (name, scale, _p) in enumerate(jobs)
                 if name in EARLY_STOP_VERSIONS and scale in (1, 2)]
        first_reads = paddle_read_text_images([jobs[i][2] for i in first], kind="page 1 values")
        stop = (allow_early_stop and len(sources) == 1
                and early_stop_agrees(field, [r for r, _c in first_reads]))
        if stop:
            jobs = [jobs[i] for i in first]
            reads = first_reads
            print(f"  EARLY STOP {field}: {len(first)} of 30 reads already agree on {stop} - every value is printed "
                  f"in this packet (map note / table) - the other {30 - len(first)} not read")
        else:
            rest = [i for i in range(len(jobs)) if i not in first]
            rest_reads = paddle_read_text_images([jobs[i][2] for i in rest], kind="page 1 values")
            by_index = dict(zip(first, first_reads))
            by_index.update(zip(rest, rest_reads))
            reads = [by_index[i] for i in range(len(jobs))]
        for (version_name, scale, _picture), (raw, confidence) in zip(jobs, reads):
                parsed = clean_coordinates(raw, field)
                for item in parsed:
                    if source["group_index"] is not None:
                        item["physical_group_index"] = source["group_index"]
                        item["absolute_text_start"] = source["x0"] + item["text_start"]
                    else:
                        item["physical_group_index"] = None
                        item["absolute_text_start"] = item["text_start"]
                attempts.append({
                    "source": source["name"],
                    "group_index": source["group_index"],
                    "version": version_name,
                    "scale": scale,
                    "raw": str(raw),
                    "confidence": confidence,
                    "values": parsed,
                })

    groups = defaultdict(list)
    for attempt_index, attempt in enumerate(attempts):
        for parsed in attempt["values"]:
            groups[parsed["value"]].append({
                **parsed,
                "attempt_index": attempt_index,
                "confidence": attempt["confidence"],
                "raw": attempt["raw"],
                "source": attempt["source"],
                "source_group_index": attempt["group_index"],
            })

    if not groups:
        return {
            "value": "",
            "vote_count": 0,
            "total_valid": 0,
            "average_confidence": 0.0,
            "items": [],
            "attempt_count": len(attempts),
            "whole_row_attempt_count": 30,
        }

    summaries = []
    for value, entries in groups.items():
        marker_votes = Counter(entry["marker"] for entry in entries if entry.get("marker"))
        marker = marker_votes.most_common(1)[0][0] if marker_votes else None

        physical_group_votes = Counter(
            entry["source_group_index"]
            for entry in entries
            if entry.get("source_group_index") is not None
        )
        physical_group_index = (
            physical_group_votes.most_common(1)[0][0]
            if physical_group_votes else None
        )

        summaries.append({
            "value": value,
            "marker": marker,
            "marker_read": bool(marker_votes),      # OCR saw a letter like (B) before it
            "vote_count": len(entries),
            "whole_row_votes": sum(1 for entry in entries if entry["source"] == "WholeRow"),
            "physical_votes": sum(1 for entry in entries if entry["source"] != "WholeRow"),
            "physical_group_index": physical_group_index,
            "average_confidence": sum(entry["confidence"] for entry in entries) / len(entries),
            "average_order": sum(
                (entry["physical_group_index"] - 1)
                if entry.get("physical_group_index") is not None
                else entry["order_index"]
                for entry in entries
            ) / len(entries),
            "average_text_start": sum(
                entry.get("absolute_text_start", entry["text_start"])
                for entry in entries
            ) / len(entries),
            # where the value starts in the row, 0..1 (whole-row reads only)
            "position_fraction": coordinate_position_fraction(entries),
        })

    accepted = [
        item for item in summaries
        if item["whole_row_votes"] >= 5 or item["physical_votes"] >= 6
    ]
    if not accepted:
        accepted = [max(
            summaries,
            key=lambda item: (item["vote_count"], item["average_confidence"]),
        )]

    def coordinate_order_key(item):
        marker = item.get("marker")
        if marker and marker.isalpha():
            return (0, ord(marker.upper()) - ord("A"), item["average_text_start"])
        if item.get("physical_group_index") is not None:
            return (1, item["physical_group_index"], item["average_text_start"])
        return (2, item["average_order"], item["average_text_start"])

    accepted = merge_near_duplicate_coordinates(accepted)
    accepted = merge_glued_marker_reads(accepted)
    if len(accepted) > 1 and all(item.get("position_fraction") is not None for item in accepted):
        # left to right as written on the page (a marker OCR'd on only some reads
        # must not put a value on the right in front of one on the left)
        accepted.sort(key=lambda item: item["position_fraction"])
    else:
        accepted.sort(key=coordinate_order_key)

    if len(accepted) > 1:
        used_markers = {item.get("marker") for item in accepted if item.get("marker")}
        for index, item in enumerate(accepted):
            if not item.get("marker"):
                proposed = chr(ord("A") + index)
                if proposed not in used_markers:
                    item["marker"] = proposed
                    used_markers.add(proposed)

    relabel_coordinate_markers(accepted)
    total_valid = sum(len(attempt["values"]) for attempt in attempts)
    for index, item in enumerate(accepted, start=1):
        item["index"] = index
        item["total_valid"] = total_valid

    winner = max(
        accepted,
        key=lambda item: (item["vote_count"], item["average_confidence"]),
    )

    print()
    print(f"{field} MULTI-COORDINATE CONSENSUS:")
    print(
        "  OCR attempts:", len(attempts),
        "| physical groups:", max(1, len(physical_groups)),
        "| accepted coordinate count:", len(accepted),
    )
    for item in accepted:
        marker_text = f'({item["marker"]}) ' if item.get("marker") else f'#{item["index"]} '
        print(
            " ", marker_text + item["value"],
            "| whole-row votes=", item["whole_row_votes"],
            "| physical votes=", item["physical_votes"],
            "| avg confidence=", round(item["average_confidence"], 3),
        )

    return {
        "value": winner["value"],
        "marker": winner.get("marker"),
        "vote_count": winner["vote_count"],
        "total_valid": total_valid,
        "average_confidence": winner["average_confidence"],
        "items": accepted,
        "attempt_count": len(attempts),
        "whole_row_attempt_count": 30,
        "physical_group_count": len(physical_groups),
        "raw_reads": [a["raw"] for a in attempts if a.get("source") == "WholeRow"],   # S158
    }


def coordinate_position_fraction(entries):
    """Average start of a coordinate as a fraction of the whole-row read length."""
    fractions = []
    for entry in entries:
        if entry.get("source") != "WholeRow":
            continue
        length = len(re.sub(r"\s+", "", str(entry.get("raw", ""))))
        if length:
            fractions.append(entry["text_start"] / length)
    return sum(fractions) / len(fractions) if fractions else None


PAGE_BACKGROUND = {"colour": None, "threshold": None}


def set_page_background(page_image):
    """The page's main background colour (the paper) and how far a pixel may be from
    it and still be paper. Colour = the most common colour (16-level bins) of the
    page; distance limit = the emptiest point between the paper's colours and the
    ink's (histogram valley between 40 and 120, clamped 55-90)."""
    arr = np.asarray(page_image.convert("RGB"))[::3, ::3].astype(np.int32).reshape(-1, 3)
    bins = arr // 16
    # most common 16-level colour bin, counted with one integer per pixel (bincount)
    # instead of sorting rows (np.unique axis=0) - the same bin, same tie-break order
    packed = bins[:, 0] * 256 + bins[:, 1] * 16 + bins[:, 2]
    top_key = int(np.bincount(packed, minlength=4096).argmax())
    colour = arr[packed == top_key].mean(axis=0)
    distance = np.sqrt(((arr - colour) ** 2).sum(axis=1))
    hist, edges = np.histogram(distance, bins=np.arange(40, 130, 10))
    threshold = float(np.clip(edges[int(hist.argmin())] + 5, 55, 90))
    PAGE_BACKGROUND["colour"] = colour
    PAGE_BACKGROUND["threshold"] = threshold
    PAGE_MAP.update({"page": None, "classes": None, "image": None, "steps": None, "black_white": None,
                     "piece_classes": None})                                   # built again for this page
    print(f"PAGE 1 BACKGROUND: rgb({colour[0]:.0f}, {colour[1]:.0f}, {colour[2]:.0f}) - pixels within "
          f"{threshold:.0f} of it -> white (paper)")


PAGE_MAP = {"page": None, "classes": None, "image": None, "steps": None, "piece_classes": None,
            "black_white": None}
DISPLAY_PAGE_MAP = {}       # S73: the page-1 pictures of the Dig Packet whose tabs are being built


def active_page_map():
    """S73: the window (main thread) works with the shown packet's own page-1 pictures
    (DISPLAY_PAGE_MAP); the reading threads with the packet being read (PAGE_MAP)."""
    return DISPLAY_PAGE_MAP if threading.current_thread() is threading.main_thread() else PAGE_MAP


def active_page_background():
    """S73: page-1 paper colour - of the shown packet in the window, of the packet being read otherwise."""
    if threading.current_thread() is threading.main_thread():
        return DISPLAY_PAGE_MAP.get("background") or {"colour": None, "threshold": None}
    return PAGE_BACKGROUND
MAP_PAPER, MAP_PRINTED, MAP_HANDWRITING = 0, 1, 2


# S103: stray marks. Step 2 of the colour map turns EVERY colour that is not paper into
# 'handwriting', so a speck of dirt or a scanner mark next to the writing became part of
# it (e.g. the olive mark after 'SHC 20-1' read as a '、'). Before that step, the page's
# handwriting colour is learned (the most common colour of the coloured ink on page 1 -
# red pen on these packets; another pen colour on another packet is learned the same
# way) and every separate mark is checked in its REAL colours. It is taken out (made
# paper, on the colour map and on page 1 itself) only when all of these hold:
#   - under STRAY_MAX_HANDWRITING_SHARE of its pixels are the handwriting colour
#   - it is not printed black (under half its pixels dark)
#   - it is small: at most STRAY_MAX_SIDE_FRACTION of the page width on each side and
#     STRAY_MAX_AREA pixels (smaller than a handwritten letter)
# A mark touching the handwriting is one mark with it, so its share of handwriting
# colour is high and it stays.
STRAY_MARK_REMOVAL = True
STRAY_MAX_HANDWRITING_SHARE = 0.20
STRAY_MAX_SIDE_FRACTION = 0.03
STRAY_MAX_AREA = 1500
HANDWRITING_HUE_TOLERANCE = 14        # OpenCV hue units (0-179)


def page_white(arr):
    """S397: True where all three colours are 255 - the same as (arr == 255).all(axis=2), one colour at a time
    (much quicker on a whole page)."""
    return (arr[:, :, 0] == 255) & (arr[:, :, 1] == 255) & (arr[:, :, 2] == 255)


def remove_stray_marks(page_image, original, arr, labels=None, white=None):
    """S103/S104: see above. The yardstick is the handwriting on the VALUE LINES - the
    marks right of each found label (Latitude, Longitude, Pipeline name, Wheel count,
    Mile post) and below Notes: their colour is learned there, and how much of each of
    those marks is that colour (its typical share). A mark elsewhere is stray when its
    share is under a quarter of that (and it is small, and not printed black). `arr` is
    the page after step 1 (paper white); stray marks are made white in it and painted
    paper-coloured on page_image. Returns how many. S397: white - page_white(arr), when already worked out;
    the marks taken out are made True in it too. The same marks as before, counted with less work."""
    if not STRAY_MARK_REMOVAL or PAGE_BACKGROUND["colour"] is None:
        return 0
    ink = ~(white if white is not None else page_white(arr))
    if np.count_nonzero(ink) < 500:
        return 0
    height_px, width_px = ink.shape
    value_lines = np.zeros_like(ink)
    for name, label in labels or []:
        if not label:
            continue
        h = max(1, int(label["y1"] - label["y0"]))
        if name == "Notes":
            box = (int(label["x0"]), int(label["y1"]), width_px, min(height_px, int(label["y1"] + 6 * h)))
        else:
            box = (int(label["x1"]), max(0, int(label["y0"] - 0.9 * h)), width_px,
                   min(height_px, int(label["y1"] + 0.6 * h)))
        value_lines[box[1]:box[3], box[0]:box[2]] = True
    hsv = cv2.cvtColor(original, cv2.COLOR_RGB2HSV)
    hue, saturation, value = hsv[:, :, 0].astype(np.int32), hsv[:, :, 1], hsv[:, :, 2]
    dark = (original[:, :, 0] < 110) & (original[:, :, 1] < 110) & (original[:, :, 2] < 110)      # S397
    coloured = ink & ~dark & (saturation >= 70) & (value >= 60)
    learn = coloured & value_lines if np.count_nonzero(coloured & value_lines) >= 200 else coloured
    if np.count_nonzero(learn) < 200:
        return 0
    histogram = np.bincount(hue[learn].ravel(), minlength=180).astype(float)
    smooth = sum(np.roll(histogram, k) for k in range(-4, 5))          # hue wraps round (red at 0 and 179)
    main_hue = int(np.argmax(smooth))
    distance = np.abs(hue - main_hue)
    distance = np.minimum(distance, 180 - distance)
    handwriting = ink & (distance <= HANDWRITING_HUE_TOLERANCE) & (saturation >= 60)
    count, labels_map, stats, _centres = cv2.connectedComponentsWithStats(ink.astype(np.uint8), connectivity=8)
    if count <= 1:
        return 0
    flat = labels_map.ravel()
    # S397: each mark's pixel counts - only the pixels that are set are counted (the same whole numbers)
    area = np.bincount(flat, minlength=count).astype(float)
    hand = np.bincount(flat[handwriting.ravel()], minlength=count).astype(float)
    darks = np.bincount(flat[dark.ravel()], minlength=count).astype(float)
    on_lines = np.bincount(flat[value_lines.ravel()], minlength=count).astype(float)
    # the yardstick: how much of each real handwriting mark on the value lines is its colour
    marks = np.arange(1, count)
    real = marks[(area[1:] >= 60) & (on_lines[1:] >= 0.5 * area[1:]) & (darks[1:] < 0.5 * area[1:])
                 & (hand[1:] >= 0.3 * area[1:])]
    measured = hand[real] / area[real]
    typical = float(np.median(measured)) if len(measured) >= 3 else 0.8
    limit = min(STRAY_MAX_HANDWRITING_SHARE, 0.25 * typical) if len(measured) < 3 else 0.25 * typical
    max_side = max(8, int(STRAY_MAX_SIDE_FRACTION * arr.shape[1]))
    small = ((area[1:] <= STRAY_MAX_AREA) & (stats[1:, cv2.CC_STAT_WIDTH] <= max_side)
             & (stats[1:, cv2.CC_STAT_HEIGHT] <= max_side))
    stray = [int(label) for label in marks[small & (hand[1:] < limit * area[1:]) & (darks[1:] < 0.5 * area[1:])]]
    yardstick = (f"handwriting on the value lines is {typical:.0%} its colour (hue {main_hue}, {len(measured)} "
                 f"marks measured) - limit {limit:.0%}, a quarter of that" if len(measured) >= 3 else
                 f"too few handwriting marks on the value lines to measure - limit {limit:.0%} (hue {main_hue})")
    if not stray:
        print(f"PAGE 1 STRAY MARKS: {yardstick}; none under it")
        return 0
    chosen = np.zeros(count, dtype=bool)                  # S397: looked up per pixel, not searched
    chosen[stray] = True
    mask = chosen[labels_map]
    arr[mask] = (255, 255, 255)
    if white is not None:
        white[mask] = True
    page_image.paste(tuple(int(c) for c in PAGE_BACKGROUND["colour"]), mask=Image.fromarray((mask * 255).astype(np.uint8)))
    big = sorted(stray, key=lambda l: -area[l])
    shown = "; ".join(f"{stats[l, cv2.CC_STAT_WIDTH]}x{stats[l, cv2.CC_STAT_HEIGHT]} px at "
                      f"x={stats[l, cv2.CC_STAT_LEFT]},y={stats[l, cv2.CC_STAT_TOP]} "
                      f"({hand[l] / max(1, area[l]):.0%} its colour)" for l in big[:5] if area[l] >= 20)
    print(f"PAGE 1 STRAY MARKS: {yardstick}; {len(stray)} small mark(s) under it taken out (made paper, on the "
          f"colour map and on page 1)" + (f": {shown}" if shown else " (all tiny specks)")
          + (f" and {len(big) - 5} more" if len(big) > 5 and shown else ""))
    return len(stray)

def build_page_colour_map(page_image, labels):
    """The whole of page 1 turned into three colours, made ONCE (not per line), in
    this order:
      1. the page's main background colour (PAGE_BACKGROUND, the paper) -> white;
         every other colour is left as it is
      2. everything that is not white -> red
      3. every name the reader searches for (Latitude, Longitude, Notes, Pipeline
         name, Wheel count/station, mile post/station) -> completely black: inside
         each found label's EasyOCR box, the label's letters - their black print
         (red, green and blue all under 110 on the page) together with everything
         red that is connected to it (the letters' soft edges, which step 2 made
         red) - so no red outline is left. Red pen in the box that is not part of a
         letter stays red.
    Every gap / edge decision of the page-1 snips then looks at the RED only."""
    colour = PAGE_BACKGROUND["colour"]
    if colour is None:
        return
    original = np.asarray(page_image.convert("RGB"))
    arr = original.copy()
    height, width = arr.shape[:2]
    steps = [("Page 1 - the regular page", page_image.convert("RGB"))]
    # 1. main background colour -> white (other colours stay as they are)
    # S397: one colour at a time, and the squared distance compared with the squared limit (no square root of
    # every pixel) - the same pixels
    squared = sum((original[:, :, k].astype(np.float64) - colour[k]) ** 2 for k in range(3))
    arr[squared < PAGE_BACKGROUND["threshold"] ** 2] = (255, 255, 255)
    white = page_white(arr)
    steps.append(("Step 1 - the main background colour (the paper) -> white; every other colour left as it is",
                  Image.fromarray(arr.copy())))
    # S103: small marks that are not the handwriting's colour (dirt, a scanner speck)
    # are taken out here - on the colour map AND on page 1 itself, so no read sees them
    removed = remove_stray_marks(page_image, original, arr, labels, white)
    if removed:
        steps.append((f"Step 1b - {removed} small mark(s) that are not the handwriting's colour -> paper "
                      f"(not handwriting: dirt, specks)", Image.fromarray(arr.copy())))
    # 2. not white -> red
    arr[~white] = (255, 0, 0)
    steps.append(("Step 2 - everything not white -> red", Image.fromarray(arr.copy())))
    # 3. searched names -> completely black (the letters + the red joined to them)
    pen = make_red_mask_array(page_image, loose=True) > 0
    names = []
    for name, label in labels:
        if not label:
            continue
        x0, y0 = max(0, int(label["x0"])), max(0, int(label["y0"]))
        x1, y1 = min(width, int(label["x1"])), min(height, int(label["y1"]))
        if x1 <= x0 or y1 <= y0:
            continue
        letters = (original[y0:y1, x0:x1] < 110).all(axis=2)          # the black print
        joinable = ~white[y0:y1, x0:x1] & ~pen[y0:y1, x0:x1]           # red here, not red pen
        count, parts = cv2.connectedComponents((joinable | letters).astype(np.uint8), connectivity=8)
        keep = np.unique(parts[letters & (parts > 0)])
        arr[y0:y1, x0:x1][np.isin(parts, keep) & (parts > 0)] = (0, 0, 0)
        names.append(name)
    black = (arr[:, :, 0] == 0) & (arr[:, :, 1] == 0) & (arr[:, :, 2] == 0)      # S397: one colour at a time
    classes = np.zeros((height, width), dtype=np.uint8)
    classes[black] = MAP_PRINTED
    classes[~white & ~black] = MAP_HANDWRITING
    steps.append((f"Step 3 - the searched names ({', '.join(names) or 'none found'}) -> completely black "
                  f"(the colour map the page-1 snips use)", Image.fromarray(arr)))
    # for the PIECE CHECKS only (is a mark cut at a piece's edge / where can an edge
    # jump to): the same map with the printed fill-in lines taken out - long straight
    # red runs (>= 12% of the page width) and 2 rows above / below them. The colour
    # map itself keeps the lines red (the circle rule needs them).
    red = (classes == MAP_HANDWRITING).astype(np.uint8)
    length = max(40, int(0.12 * width))
    lines = cv2.morphologyEx(red, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (length, 1)))
    lines = cv2.dilate(lines, cv2.getStructuringElement(cv2.MORPH_RECT, (1, 5))) > 0
    piece_classes = classes.copy()
    piece_classes[lines & (classes == MAP_HANDWRITING)] = MAP_PAPER
    # 4. everything red -> completely black: all ink black on white (the searched
    # names already are) - the black/white page the Notes reads also use
    black_white = arr.copy()
    black_white[classes == MAP_HANDWRITING] = (0, 0, 0)
    colour_map_image = steps[-1][1]
    steps.append(("Step 4 - everything red -> completely black (all ink black on white; also read for the Notes)",
                  Image.fromarray(black_white)))
    PAGE_MAP.update({"page": page_image, "classes": classes, "image": colour_map_image, "steps": steps,
                     "black_white": steps[-1][1],
                     "piece_classes": piece_classes})
    print(f"PAGE 1 COLOUR MAP: paper colour -> white, everything not white -> red, {len(names)} searched "
          f"names -> completely black ({', '.join(names) or 'none found'})")
    print(f"PAGE 1 PIECE CHECKS: fill-in lines (straight red runs >= {length} px) taken out for the piece edge "
          f"checks only - {int(np.count_nonzero(lines & (classes == MAP_HANDWRITING)))} px")


def page_crop(page, box):
    """page.crop(box) that remembers where it sits on the page, so handwriting_mask can
    take its pixels from the page-1 colour map (only for the page the map was made of)."""
    crop = page.crop(box)
    if active_page_map().get("page") is not None and page is active_page_map().get("page"):
        crop.page_offset = (int(box[0]), int(box[1]))
    return crop


def piece_ink_mask(page, box):
    """Handwriting in a page box for the PIECE CHECKS: the colour map's red without
    the printed fill-in lines (PAGE_MAP['piece_classes']). Without a map: the usual
    handwriting_mask of that crop."""
    x0, y0, x1, y1 = (int(v) for v in box)
    if PAGE_MAP.get("piece_classes") is not None and page is PAGE_MAP["page"]:
        return page_map_region((x0, y0), max(1, x1 - x0), max(1, y1 - y0),
                               PAGE_MAP["piece_classes"]) == MAP_HANDWRITING
    return handwriting_mask(page_crop(page, (x0, y0, x1, y1)))


def page_map_region(offset, width, height, classes=None):
    """The colour map's classes for a width x height area whose top-left is at page
    `offset` (parts outside the page = paper)."""
    classes = active_page_map().get("classes") if classes is None else classes
    out = np.zeros((height, width), dtype=np.uint8)
    ox, oy = offset
    x0, y0 = max(0, ox), max(0, oy)
    x1, y1 = min(classes.shape[1], ox + width), min(classes.shape[0], oy + height)
    if x1 > x0 and y1 > y0:
        out[y0 - oy:y1 - oy, x0 - ox:x1 - ox] = classes[y0:y1, x0:x1]
    return out


def page_binary(image, remove_lines=True):
    """Black/white copy: the paper colour -> white, EVERY other colour (red
    handwriting, black print) -> black. Returned as a mask (True = black/ink).
    Printed fill-in lines (long thin horizontal runs, >= 25% of the width and 40 px)
    are taken out, so they do not join marks or fill the gaps between them."""
    background = active_page_background()
    colour = background["colour"]
    arr = np.asarray(image.convert("RGB")).astype(np.int32)
    distance = np.sqrt(((arr - colour) ** 2).sum(axis=2))
    ink = (distance >= background["threshold"]).astype(np.uint8)
    if remove_lines and ink.shape[1] >= 20:
        length = max(40, int(0.25 * ink.shape[1]))
        lines = cv2.morphologyEx(ink, cv2.MORPH_OPEN, cv2.getStructuringElement(cv2.MORPH_RECT, (length, 1)))
        lines = cv2.dilate(lines, cv2.getStructuringElement(cv2.MORPH_RECT, (1, 5)))
        ink = ink & (1 - lines)
    return ink > 0


def handwriting_mask(image):
    """Where the handwriting is, for every gap / edge decision of the page-1 snips.
    A crop that knows where it sits on page 1 (page_crop / the line's OCR copy) takes
    the RED of the page-1 colour map (printed labels are black there, so they are not
    counted). Otherwise, when the page-1 background colour is known: the black/white
    copy of the crop (paper white, anything else black, printed lines taken out).
    Otherwise the Notes' red-ink mask (_ink_mask)."""
    offset = getattr(image, "page_offset", None)
    if offset is not None and active_page_map().get("classes") is not None:
        return page_map_region(offset, image.width, image.height) == MAP_HANDWRITING
    if active_page_background()["colour"] is not None:
        return page_binary(image)
    mask = _ink_mask(image)
    if mask is None:
        return np.zeros((image.height, image.width), dtype=bool)
    return mask > 0


# S166: a circled bullet is often read as a circled character ('④' for a circled A, whose
# look-alike digit is 4) - it is the bullet: read as its plain letter / digit
CIRCLED_CHARACTERS = str.maketrans({**{chr(0x2460 + i): str(i + 1) for i in range(9)}, "\u24ea": "0",
                                    **{chr(0x24B6 + i): chr(ord("A") + i) for i in range(26)},
                                    **{chr(0x24D0 + i): chr(ord("A") + i) for i in range(26)}})


def snip_read_compact(image, field):
    """PaddleOCR read of a snip (2x), squeezed the same way values are parsed."""
    big = image.resize((image.width * 2, image.height * 2))
    padded = Image.new("RGB", (big.width + 20, big.height + 20), (255, 255, 255))
    padded.paste(big.convert("RGB"), (10, 10))
    raw, _confidence = paddle_read_text_image(padded)
    text = str(raw).replace(",", ".").replace("—", "-").replace("–", "-").replace("−", "-")
    text = re.sub(r"\s+", "", text).translate(CIRCLED_CHARACTERS)    # S166: '④' (a circled A read as 4) -> '4'
    if field == "Mile Post/Station":
        text = re.sub(r"(?<=\d)[tT](?=\d)", "+", text)
    return text


def snip_split_parts(compact, value):
    """(what is before the value, what is after it) in a snip's read, or None when
    the value is not in it. A lost minus sign still counts as the value."""
    for wanted in (str(value), str(value).lstrip("+-")):
        index = compact.find(wanted)
        if index >= 0:
            return compact[:index], compact[index + len(wanted):]
    return None


WINDOW_LOOKS = {"looks": []}        # S123: the last window's reads (x, left read, right read)
PAGE1_BULLET_HINT = {"count": None}  # S115: bullets the page-1 lines read so far agree on (2+ lines)
BULLET_GAP_SEARCH_HEIGHTS = 4      # S110: look this many line heights either side of the measured cut
BULLET_GAP_MAX_TRIES = 12          # at most this many gap positions read


def printed_variants(field, value):
    """S113: the values printed in this packet (map notes, table - text first) that a
    page-1 read value may really be: the read itself first, then every printed value of
    the same kind that is close to it (difflib ratio >= 0.75, e.g. -93.9670368961 vs
    the printed -93.96703609)."""
    from difflib import SequenceMatcher
    value = str(value or "")
    out = [value] if value else []
    for printed in (TEXT_FIRST.get("known") or {}).get(field) or []:
        if printed != value and SequenceMatcher(None, value, printed).ratio() >= 0.75:
            out.append(printed)
    return out


def best_layout(read, field, item):
    """S113: the snip layout (S108) for the item's value or, when that does not fit, for
    a close printed value - whichever lines up best."""
    options = printed_variants(field, item.get("value"))
    if not options:
        return snip_layout(read, item.get("value"), item.get("marker"))
    return max((snip_layout(read, v, item.get("marker")) for v in options), key=layout_quality)


def measure_cut_window(image, inked, left_item, right_item, left_x0, cut, low, high, field, steps):
    """S112: the CUT WINDOW between two values - 'value, bullet, value'. The gaps in the
    ink around the cut are read as cuts (both sides, through look-alikes, S108/S109),
    nearest first, re-using reads the cut tries already made:
      left limit  = the first gap where the left snip holds its whole value with
                    nothing after it (cutting before it splits the left value)
      right limit = the last gap where the right snip still starts with its value
                    (cutting after it splits the right value / its bullet)
    Between the two is only the bullet. It stops reading as soon as both limits are
    sure (the gap next to each limit has been read and is on the other side).
    Returns {'left': x, 'right': x, 'bullet_cuts': [gaps whose right snip starts with
    its own bullet], 'gaps': [...]} or None when the reads cannot make a window."""
    height = image.height
    reach = BULLET_GAP_SEARCH_HEIGHTS * height
    gaps, run = [], None
    for x in range(max(low, int(cut - reach)), min(high, int(cut + reach))):
        if not inked[x]:
            run = x if run is None else run
        else:
            if run is not None and x - run >= 2:
                gaps.append(run + (x - run) // 2)
            run = None
    WINDOW_LOOKS["looks"] = []
    known = {t["cut"]: (t["left_read"], t["right_read"]) for t in steps}
    if cut in known and cut not in gaps and low < cut < high:
        gaps.append(int(cut))           # the cut the tries read is a position too (S114: its reads are re-used)
    if not gaps:
        return None
    gaps.sort()
    looks = {}

    def look(x):
        if x in looks:
            return looks[x]
        if x in known:
            left_read, right_read = known[x]
        else:
            left_snip = image.crop((left_x0, 0, x, height))
            right_snip = image.crop((x, 0, high + 4, height))
            left_read = snip_read_compact(left_snip, field)
            right_read = snip_read_compact(right_snip, field)
        left = best_layout(left_read, field, left_item)
        right = best_layout(right_read, field, right_item)
        left_done = bool(left["found"] or left["tail"]) and not left["extra_after"]
        right_start = bool(right["found"] or right["head"]) and not right["extra_before"]
        bullet_here = right_start and right["bullet"]
        if x not in known:
            steps.append({"cut": int(x), "left_read": left_read, "right_read": right_read})
        looks[x] = (left_done, right_start, bullet_here, left_read, right_read)
        WINDOW_LOOKS["looks"].append((int(x), left_read, right_read))
        return looks[x]

    def limits():
        seen = sorted(looks)
        done = [x for x in seen if looks[x][0]]
        start = [x for x in seen if looks[x][1]]
        left = min(done) if done else None
        right = max(start) if start else None
        left_sure = left is not None and (gaps.index(left) == 0 or gaps[gaps.index(left) - 1] in looks)
        right_sure = right is not None and (gaps.index(right) == len(gaps) - 1 or gaps[gaps.index(right) + 1] in looks)
        return left, right, left_sure, right_sure

    for x in sorted(gaps, key=lambda g: abs(g - cut))[:BULLET_GAP_MAX_TRIES]:
        look(x)
        left, right, left_sure, right_sure = limits()
        if left_sure and right_sure:
            break
    # make the limits sure: read the gap just outside each one if it was not read yet
    for _ in range(4):
        left, right, left_sure, right_sure = limits()
        if left is not None and not left_sure:
            look(gaps[gaps.index(left) - 1])
        elif right is not None and not right_sure:
            look(gaps[gaps.index(right) + 1])
        else:
            break
    left, right, _ls, _rs = limits()
    if left is None or right is None:
        return None
    if right < left:
        right = left                    # nothing between the two values: the cut is right there
    bullet_cuts = [x for x in sorted(looks) if looks[x][2] and left <= x <= right]
    return {"left": int(left), "right": int(right), "bullet_cuts": bullet_cuts, "gaps": gaps,
            "left_read": looks[left][3], "right_read": looks[right][4]}


def cut_in_window(window, image, right_item):
    """S112: where the cut goes inside its window: at the leftmost gap whose right snip
    starts with its own bullet (the circle's left edge stays with the bullet), else
    right after the left value (the left limit). Also says whether the ink between
    the limits passes the circle test. Returns (cut, why)."""
    if window["bullet_cuts"]:
        cut = window["bullet_cuts"][0]
        return cut, f"the right snip starts with its bullet from x={cut}"
    seen = ""
    if window["right"] > window["left"]:
        between = image.crop((window["left"], 0, window["right"], image.height))
        circle = circled_content_image({"image": between, "text": right_item.get("marker") or ""},
                                       line_height=image.height * 0.75, report=False)
        seen = (" (a circled bullet is in between)" if circle is not None
                else " (no circle recognised in between, but it must hold the bullet)")
    return window["left"], f"no read starts with the bullet - the cut goes right after the left value{seen}"


def read_guided_cut(read, item, x0, width, direction, current=None):
    """S158: a cut try's read says where things are in its snip (handwriting this size is
    about evenly spaced, so a position in the text is a position in the picture):
      direction 'left'  - the LEFT snip (from x0, `width` wide) holds its value and then
                          more: the cut goes just after where its value ends;
      direction 'right' - the RIGHT snip (from x0) holds a piece of the left value before
                          the next bullet: the cut goes just before that bullet.
    Returns the new cut, or None when the read does not show it clearly (then the normal
    small step is used)."""
    compact = re.sub(r"\s+", "", str(read or ""))
    if not compact or width <= 0:
        return None
    per_char = width / len(compact)
    if direction == "left":
        span = value_span_in_read(compact, item.get("value"))
        if span is None or span.end() >= len(compact):
            return None
        cut = int(x0 + per_char * span.end() + per_char * 0.3)
        return cut if current is None or cut < current else None
    letter = str(item.get("marker") or "").upper()
    shapes = set(LOOKALIKE_CLASSES.get(letter, letter) + letter) if letter else set()
    for position, character in enumerate(compact):
        if character in "([{" or character.upper() in shapes:
            if position == 0:
                return None
            return int(x0 + per_char * position - per_char * 0.3)
    return None


def verify_snip_cuts(image, items, cuts, field, step):
    """Each snip is read back: the left one must read as its value with nothing after
    it (no '(B' of the next value), the right one must start with its own bullet
    (e.g. '(B)') and hold none of the previous value. A cut that fails is moved in
    small steps (left or right, as the reads show) until both read right."""
    height = image.height
    for item in items:
        item.pop("cut_window", None)                   # S112: windows belong to this cut's pairs only
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        mask = (np.array(ImageOps.grayscale(image)) < 150).astype(np.uint8)
    inked = np.count_nonzero(mask, axis=0) > 0
    for index in range(1, len(items)):
        left_item, right_item = items[index - 1], items[index]
        low = cuts[index - 1] + 4
        high = (cuts[index + 1] if index + 1 < len(cuts) else image.width) - 4
        cut = cuts[index]
        tried = set()
        best = None
        steps = []                               # every cut tried and its reads (re-used by the window)
        for _attempt in range(16):
            if cut in tried or not (low < cut < high):
                break
            tried.add(cut)
            left_snip = image.crop((cuts[index - 1], 0, cut, height))
            right_snip = image.crop((cut, 0, high + 4, height))
            left_read = snip_read_compact(left_snip, field)
            right_read = snip_read_compact(right_snip, field)
            left_parts = snip_split_parts(left_read, left_item["value"])
            right_parts = snip_split_parts(right_read, right_item["value"])
            left_ok = left_parts is not None and left_parts[1].strip(".)]|") == ""
            right_before = right_parts[0] if right_parts else ""
            right_has_old = bool(re.search(r"\d{2}", right_before))           # piece of the previous value
            right_bullet = bool(re.search(r"[A-Za-z8]", right_before)) or not right_item.get("marker_read")
            right_ok = right_parts is not None and not right_has_old and right_bullet
            steps.append({"cut": int(cut), "left_read": left_read, "right_read": right_read})
            if left_ok and right_ok:
                best = cut
                break
            if left_parts is None or right_has_old:
                # cut went into the left value -> move right; S158: when the right read shows
                # where the next bullet starts, jump just before it instead of a small step
                cut = read_guided_cut(right_read, right_item, cut, high + 4 - cut, "right") or cut + step
            elif not left_ok or not right_bullet:
                # left snip still holds the next bullet -> move left; S158: to where the left
                # read shows its value ends
                cut = read_guided_cut(left_read, left_item, cuts[index - 1], cut - cuts[index - 1], "left",
                                      current=cut) or cut - step
            else:
                break
        # S112: the cut window - where this cut may and may not go, from the reads. The
        # cut the tries chose stays when it is inside the window and the reads there are
        # clean (left: value, nothing after; right: its bullet, then its value);
        # otherwise the cut goes where the window says (S110 / S111). S113: the reads
        # are also compared with close printed values. S114: when the accepted cut
        # already reads clean, the window is built from the tries' reads plus at most
        # the gap on each side of the cut.
        window = None
        clean = False
        if best is not None and right_item.get("marker"):
            chosen = [t for t in steps if t["cut"] == best]
            if chosen:
                left_look = best_layout(chosen[-1]["left_read"], field, left_item)
                right_look = best_layout(chosen[-1]["right_read"], field, right_item)
                clean = ((left_look["found"] or left_look["tail"]) and not left_look["extra_after"]
                         and right_look["bullet"] and not right_look["extra_before"])
        hint = PAGE1_BULLET_HINT["count"]
        if right_item.get("marker") and hint and len(items) > hint:
            # S115: more values than the page has bullets - the bullet count will drop
            # some and cut the line again; its window is measured then, not now
            if index == 1:
                print(f"  CUT WINDOW {field}: {len(items)} values but the other lines have {hint} bullets - "
                      f"window measured after the bullet count")
        elif right_item.get("marker") and clean:
            # S139: the accepted cut already reads clean on both sides (value | bullet +
            # value) - it is final: no window reads, no value-end tries; its window is the
            # cut itself, so the circles and piece checks keep it where it is
            window = {"left": int(best), "right": int(best), "final": True}
        elif right_item.get("marker"):
            window = measure_cut_window(image, inked, left_item, right_item, cuts[index - 1],
                                        best if best is not None else cuts[index], low, high, field, steps)
        letter = right_item.get("marker") or chr(ord("A") + index)
        pair = f"({chr(ord(letter) - 1)})|({letter})"
        if window is None:
            if right_item.get("marker") and not (hint and len(items) > hint):
                around = best if best is not None else cuts[index]
                nearest = sorted(WINDOW_LOOKS["looks"], key=lambda t: abs(t[0] - around))[:2]
                seen = "; ".join(f"x={x} left '{l}' right '{r}'" for x, l, r in nearest)
                print(f"  CUT WINDOW {field} {pair}: the reads cannot tell where the left value ends and the "
                      f"right one starts" + (f" (nearest: {seen})" if seen else " (no gaps in the ink to try)")
                      + " - " + ("the accepted cut kept" if best is not None else "measured cut kept"))
        else:
            right_item["cut_window"] = (window["left"], window["right"])
            if window.get("final"):
                chosen = [t for t in steps if t["cut"] == best]
                print(f"  CUT FINAL {field} {pair}: x={best} reads clean ('{chosen[-1]['left_read']}' | "
                      f"'{chosen[-1]['right_read']}') - kept as it is, no window or value-end reads (S139)")
            elif clean and window["left"] <= best <= window["right"]:
                print(f"  CUT WINDOW {field} {pair}: x={window['left']}-{window['right']} (left value ends at "
                      f"{window['left']}, right value starts by {window['right']}) - the accepted cut x={best} is "
                      f"inside it and reads cleanly, kept (window from the cut tries + the gap each side)")
            else:
                new_cut, why = cut_in_window(window, image, right_item)
                was = f"x={best}" if best is not None else "no accepted cut"
                print(f"  CUT WINDOW {field} {pair}: x={window['left']}-{window['right']} (left value ends at "
                      f"{window['left']} '{window['left_read']}', right value starts by {window['right']} "
                      f"'{window['right_read']}') - {why}; cut at x={new_cut} (was {was})")
                best = new_cut
                chosen = [t for t in steps if t["cut"] == best]
                left_read = chosen[-1]["left_read"] if chosen else ""
                right_read = chosen[-1]["right_read"] if chosen else ""
        # the left snip ends where its value ends: the FIRST ink-free gap after which
        # its read holds the whole value with nothing after it. Any ink between that
        # gap and the next value (e.g. the '(' of '(B)') then goes to the next snip.
        # S139: not for a cut that is already final.
        if best is not None and not (window and window.get("final")):
            gaps, run = [], None
            for x in range(cuts[index - 1] + 1, best + 1):
                if x < best and not inked[x]:
                    run = x if run is None else run
                else:
                    if run is not None and x - run >= 2:
                        gaps.append(run + (x - run) // 2)
                    run = None
            last_read = ""
            for x in gaps:
                left_snip = image.crop((cuts[index - 1], 0, x, height))
                left_read = snip_read_compact(left_snip, field)
                last_read = left_read
                parts = snip_split_parts(left_read, left_item["value"])
                if parts is None:
                    continue                          # value not complete yet
                if re.search(r"\d", parts[1]):
                    print(f"  VALUE END {field}: at x={x} the left snip reads '{left_read}' - digits after "
                          f"{left_item['value']}, the cut stays at {best}")
                    break
                right_snip = image.crop((x, 0, high + 4, height))
                right_read = snip_read_compact(right_snip, field)
                # the right side only has to hold nothing of the left value (its own
                # value was already read; a partial crop can misread it, e.g. 1 -> /)
                left_value = str(left_item["value"])
                right_ok = not any(right_read.startswith(left_value[-k:])
                                   for k in range(2, len(left_value) + 1))
                steps.append({"cut": int(x), "left_read": left_read, "right_read": right_read})
                if not right_ok:
                    print(f"  VALUE END {field}: at x={x} the right snip starts with the end of "
                          f"{left_value} "
                          f"('{right_read}'), the cut stays at {best}")
                inside = not right_item.get("cut_window") or x >= right_item["cut_window"][0]   # S112
                if right_ok and x < best and inside:
                    marker = f"({left_item['marker']}) " if left_item.get("marker") else ""
                    print(f"  SNIP CHECK {field}: {marker}{left_item['value']} ends "
                          f"at x={x} - cut moved there from {best} so the next bullet stays whole")
                    best = x
                break
            else:
                print(f"  VALUE END {field}: no gap after which the left snip reads exactly "
                      f"{left_item['value']} (last read '{last_read}') - the cut stays at {best}")
        right_item["snip_steps"] = {"measured": int(cuts[index]), "final": int(best if best is not None
                                                                            else cuts[index]),
                                    "steps": steps}
        if best is not None and best != cuts[index]:
            print(f"  SNIP CHECK {field}: cut {cuts[index]} -> {best} "
                  f"(left snip reads '{left_read}', right snip reads '{right_read}')")
            cuts[index] = best
        elif best is None:
            print(f"  SNIP CHECK {field}: could not get both snips to read cleanly around x={cuts[index]} "
                  f"- kept the measured cut")
    return cuts


def split_coordinate_snips(image, items, field=None, geometry=None):
    """
    One snip per coordinate when a row holds several ((A) ... (B) ...).
    The cut between two values is the widest ink-free gap just BEFORE the next
    value's start, so the next value's marker '(B)' stays with that value.
    Sets item['image']; leaves items alone if positions are unknown.
    """
    if image is None or len(items) < 2 or any(i.get("position_fraction") is None for i in items):
        return None
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        gray = np.array(ImageOps.grayscale(image))
        mask = (gray < 150).astype(np.uint8)
    inked = np.count_nonzero(mask, axis=0) > 0
    width = image.width
    # the read text only covers the handwriting, not the empty paper to its right
    # (or left): the position is measured along the inked part of the row
    ink_columns = np.flatnonzero(inked)
    ink_left = int(ink_columns[0]) if len(ink_columns) else 0
    ink_right = int(ink_columns[-1]) + 1 if len(ink_columns) else width
    span = max(1, ink_right - ink_left)
    cuts = [0]
    # a circled (B) is about as wide as the handwriting is tall (the circle is the tallest mark)
    ink_rows = np.flatnonzero(np.count_nonzero(mask, axis=1) > 0)
    marker_width = int(ink_rows[-1] - ink_rows[0] + 1) if len(ink_rows) else int(image.height)
    for item in items[1:]:
        expected = int(ink_left + item["position_fraction"] * span)
        low = max(cuts[-1] + 1, int(expected - 0.18 * span))
        high = min(width - 1, expected)
        gaps, run_start = [], None
        for x in range(low, high + 2):
            if x <= high and not inked[x]:
                if run_start is None:
                    run_start = x
            elif run_start is not None:
                if x - run_start >= 3:
                    gaps.append((run_start, x - run_start))
                run_start = None
        if item.get("marker_read"):
            # the value starts AFTER its marker: cut at the gap nearest to where the
            # marker begins, so '(B)' goes with its own value even when it touches
            # the previous number ('991+48(B)')
            target = expected - marker_width
            # the gap between the marker and its own value is not the cut
            before_marker = [g for g in gaps if g[0] + g[1] / 2 <= expected - marker_width * 0.5]
            near = min(before_marker, key=lambda g: abs(g[0] + g[1] / 2 - target), default=None)
            if near and abs(near[0] + near[1] / 2 - target) <= marker_width:
                cut = near[0] + near[1] // 2
            else:
                # no gap (the marker touches the previous number): one marker width
                # before where the value starts
                cut = max(cuts[-1] + 1, target)
        elif gaps:
            best = max(gaps, key=lambda g: g[1])
            cut = best[0] + best[1] // 2
        else:
            cut = max(cuts[-1] + 1, int(expected - 0.04 * span))
        cuts.append(cut)
    cuts.append(min(width, ink_right + 12))     # stop at the end of the handwriting, not the empty paper
    cuts[0] = max(0, ink_left - 12)
    circle_cuts = None
    if field and geometry:
        try:
            circle_cuts = cuts_from_circles_first(image, items, cuts, field, geometry)
        except Exception as exc:
            print(f"  CIRCLES FIRST {field}: skipped ({exc})")
    letter_cuts = None
    if field and not circle_cuts:
        try:
            letter_cuts, cuts = cuts_from_bullet_letters(image, items, cuts, field)
        except Exception as exc:
            print(f"  LETTER FIRST {field}: skipped ({exc})")
    if circle_cuts or letter_cuts:
        cuts = circle_cuts or letter_cuts
    elif field:
        try:
            cuts = verify_snip_cuts(image, items, cuts, field, step=max(3, marker_width // 6))
        except Exception as exc:
            print(f"  SNIP CHECK {field}: skipped ({exc})")
    if field and len(items) > 1:
        try:
            cuts = centre_cuts_in_gaps(image, items, cuts, field, geometry)        # S146
        except Exception as exc:
            print(f"  CUT IN GAP {field}: skipped ({exc})")
        remember_bullets_seen(items, cuts, field, geometry)               # S161
    apply_snip_cuts(image, items, cuts)
    print("  Coordinate snips cut at x =", cuts[1:-1], "of", width)
    return cuts


def cuts_from_circles_first(image, items, cuts, field, geometry):
    """S122: the bullet circles are found FIRST (no reading needed) and, when they look
    right, give the cuts straight away:
      - the first circle in each value's part of the line (between the cuts measured
        from the reading) is that value's bullet;
      - (A)'s circle must sit right after the printed label (its walk ends at the black
        label, or within a letter of the label's ':');
      - each cut goes just before its circle (the circle start walk), and is then
        checked with ONE read on each side: left = its value with nothing after it,
        right = its bullet then its value (look-alikes allowed).
    When every cut reads clean, these are the cuts - the cut tries are skipped and each
    cut window is built cheaply around them (S124). Otherwise None (the normal path).
    Lines with more values than the page's bullets wait for the bullet count (S115)."""
    hint = PAGE1_BULLET_HINT["count"]
    if len(items) < 2 or (hint and len(items) > hint) or PAGE_MAP["classes"] is None:
        return None
    page = geometry["page_image"]
    if page is not PAGE_MAP["page"]:
        return None
    offset = geometry["ocr_offset_x"]
    height = geometry.get("label_height", 40)
    band_top, band_bottom = geometry["read_band"]
    _lx, line_top, _rx, line_bottom = geometry["line_box"]
    x_start = max(0, int(offset + cuts[0] - height * 2))
    x_end = min(page.width, int(offset + cuts[-1]))
    line = page_crop(page, (x_start, line_top, x_end, line_bottom))
    circles = [(x_start + a, x_start + b) for a, b in find_circled_bullets(line, own_line_y=geometry.get("fill_line_y"))]
    picked = []
    for index in range(len(items)):
        part_start = offset + cuts[index] - (height if index == 0 else 0)
        part_end = offset + cuts[index + 1]
        inside = [c for c in circles if part_start <= (c[0] + c[1]) / 2.0 < part_end and c not in picked]
        if not inside:
            print(f"  CIRCLES FIRST {field}: no circle in ({chr(ord('A') + index)})'s part of the line - the cut tries "
                  f"decide")
            return None
        picked.append(min(inside, key=lambda c: c[0]))
    scan_x, scan_note = circle_start_by_scan(page, picked[0], band_top, band_bottom, height)
    label_end = geometry.get("label_end")
    after_label = "black label" in scan_note or (label_end is not None and scan_x is not None
                                                 and 0 <= scan_x - label_end <= 1.5 * height)
    if not after_label:
        print(f"  CIRCLES FIRST {field}: (A)'s circle at x={picked[0][0]} is not right after the printed label - the "
              f"cut tries decide")
        return None
    new_cuts = [cuts[0]]
    for circle in picked[1:]:
        start_x, _note = circle_start_by_scan(page, circle, band_top, band_bottom, height)
        start = int(circle[0]) if start_x is None or start_x < int(circle[0]) - 2 else start_x
        new_cuts.append(int(start - offset - 3))
    new_cuts.append(cuts[-1])
    if any(b <= a for a, b in zip(new_cuts, new_cuts[1:])):
        return None
    for item in items:
        item.pop("cut_window", None)
    checks = []
    for index in range(1, len(items)):
        left_item, right_item = items[index - 1], items[index]
        left_snip = image.crop((new_cuts[index - 1], 0, new_cuts[index], image.height))
        right_snip = image.crop((new_cuts[index], 0, new_cuts[index + 1], image.height))
        left_read = snip_read_compact(left_snip, field)
        right_read = snip_read_compact(right_snip, field)
        left = best_layout(left_read, field, left_item)
        right = best_layout(right_read, field, right_item)
        clean = ((left["found"] or left["tail"]) and not left["extra_after"]
                 and right["bullet"] and (right["found"] or right["head"]) and not right["extra_before"])
        step = {"cut": int(new_cuts[index]), "left_read": left_read, "right_read": right_read}
        checks.append((index, step, clean))
        if not clean:
            print(f"  CIRCLES FIRST {field}: the cut at ({right_item.get('marker') or chr(ord('A') + index)})'s circle "
                  f"reads '{left_read}' | '{right_read}' - not value | bullet + value - the cut tries decide")
            return None
    for index, step, _clean in checks:
        right_item = items[index]
        steps = [step]
        right_item["cut_window"] = (int(new_cuts[index]), int(new_cuts[index]))   # S139: read clean -> final
        right_item["snip_steps"] = {"measured": int(cuts[index]), "final": int(new_cuts[index]),
                                    "circle": True, "steps": steps}
    reads = "; ".join(f"'{s['left_read']}' | '{s['right_read']}'" for _i, s, _c in checks)
    print(f"  CIRCLES FIRST {field}: circles at x = {[c[0] for c in picked]} - (A)'s sits right after the label, "
          f"cuts just before each next circle at x = {new_cuts[1:-1]} read clean ({reads}) - cut tries skipped")
    return new_cuts


def cuts_from_bullet_letters(image, items, cuts, field):
    """S140 + S142: the next value's bullet LETTER tells where to look. One EasyOCR read of
    the line (with text boxes) finds the box whose text starts with that letter (or how it
    is often read: 8 for B, a circled letter, '(B'), nearest to where the reading expects
    that value. That box starts at the LETTER, not at the circle round it (S141: cutting
    right there put the circle's left side in the previous snip), so the cut is not put
    there: the gaps in the ink just left of the letter - within one circle width - are
    read as cuts, leftmost first, and the first one whose left snip still holds its whole
    value (nothing after it) and whose right snip starts with the bullet is used - the
    whole circle then stays with its bullet. All values found that way -> these are the
    cuts, final (S139). Otherwise the estimated cuts stay and the cut tries decide.
    Returns (final cuts or None, cuts to start the tries from)."""
    hint = PAGE1_BULLET_HINT["count"]
    if len(items) < 2 or (hint and len(items) > hint):
        return None, cuts
    boxes = easy_reader.readtext(np.array(image.convert("RGB")), detail=1, paragraph=False)
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        mask = (np.array(ImageOps.grayscale(image)) < 150).astype(np.uint8)
    inked = np.count_nonzero(mask, axis=0) > 0
    reach = int(1.3 * image.height)                    # about one circle width
    new_cuts, chosen, notes = list(cuts), [], []
    for index in range(1, len(items)):
        left_item, right_item = items[index - 1], items[index]
        letter = str(right_item.get("marker") or chr(ord("A") + index)).upper()
        shapes = sorted(set(LOOKALIKE_CLASSES.get(letter, letter) + letter))
        pattern = re.compile(r"^(.?)[\(\[{]?\s*[" + re.escape("".join(shapes)) + r"]")
        low, high = new_cuts[index - 1] + 4, cuts[index + 1] - 4
        candidates = []
        for box in boxes:
            text = str(box[1]).strip()
            x0 = int(min(point[0] for point in box[0]))
            found_letter = pattern.match(text)
            # S147: one stray character may come first - the left value's last digit read
            # in the same box ('1(B…'); the bullet then sits just right of the box's start
            if low < x0 < high and found_letter and (not found_letter.group(1)
                                                    or not found_letter.group(1).upper() in shapes):
                candidates.append((abs(x0 - cuts[index]), x0, text, bool(found_letter.group(1))))
        if not candidates:
            print(f"  LETTER FIRST {field}: no '{letter}' found in the line's text boxes - the cut tries decide")
            return None, cuts
        _distance, x0, text, stray_first = min(candidates)
        right_end = min(high, x0 + (reach if stray_first else 3))
        gaps, run = [], None
        for x in range(max(low, x0 - reach), right_end):
            if not inked[x]:
                run = x if run is None else run
            else:
                if run is not None and x - run >= 2:
                    gaps.append(run + (x - run) // 2)
                run = None
        if run is not None and right_end - run >= 2:
            gaps.append(run + (right_end - run) // 2)
        found = None
        for gap in sorted(gaps):                         # leftmost first: the whole circle goes right
            left_snip = image.crop((new_cuts[index - 1], 0, gap, image.height))
            right_snip = image.crop((gap, 0, cuts[index + 1], image.height))
            left_read = snip_read_compact(left_snip, field)
            right_read = snip_read_compact(right_snip, field)
            left = best_layout(left_read, field, left_item)
            right = best_layout(right_read, field, right_item)
            clean = ((left["found"] or left["tail"]) and not left["extra_after"]
                     and right["bullet"] and (right["found"] or right["head"]) and not right["extra_before"])
            if clean:
                found = (gap, {"cut": int(gap), "left_read": left_read, "right_read": right_read})
                break
        if not found:
            print(f"  LETTER FIRST {field}: '{text}' at x={x0}, but no gap within a circle's width left of it "
                  f"reads clean ({len(gaps)} tried) - the cut tries decide")
            return None, cuts
        new_cuts[index] = found[0]
        chosen.append((index, found[1]))
        notes.append(f"'{text}' at x={x0} -> cut at the gap x={found[0]} ('{found[1]['left_read']}' | "
                     f"'{found[1]['right_read']}')")
    if any(b <= a for a, b in zip(new_cuts, new_cuts[1:])):
        return None, cuts
    for index, step in chosen:
        items[index]["cut_window"] = (int(new_cuts[index]), int(new_cuts[index]))        # final (S139)
        items[index]["snip_steps"] = {"measured": int(cuts[index]), "final": int(new_cuts[index]),
                                      "steps": [step]}
    print(f"  LETTER FIRST {field}: " + "; ".join(notes) + " - the circle stays with its letter, final, cut tries "
          f"skipped (S142)")
    return new_cuts, new_cuts


def remember_bullets_seen(items, cuts, field, geometry):
    """S161: what the cut reads already showed is kept for the piece checks: a value whose
    snip was read with its bullet (the left snip of a cut for the value before it, the
    right snip for the value after it) gets 'bullet_seen_from' - the page x where that
    snip started, plus a third of a letter height. A piece that still starts there (or
    further left) holds that bullet, whatever a later read of it prints. The first value
    is also marked 'label_side_left': its left side faces the printed label."""
    if not items:
        return
    items[0]["label_side_left"] = True
    offset = (geometry or {}).get("ocr_offset_x")
    height = (geometry or {}).get("label_height", 40)
    if offset is None:
        return
    reads = {}
    for index in range(1, len(items)):
        info = items[index].get("snip_steps") or {}
        steps = info.get("steps") or []
        chosen = [t for t in steps if t.get("cut") == info.get("final")] or steps[-1:]
        if chosen:
            reads.setdefault(index - 1, []).append(chosen[-1].get("left_read", ""))
            reads.setdefault(index, []).append(chosen[-1].get("right_read", ""))
    seen = []
    for index, item in enumerate(items):
        if any(best_layout(read, field, item)["bullet"] for read in reads.get(index, []) if read):
            start = cuts[index] if index < len(cuts) else 0
            item["bullet_seen_from"] = int(offset + start + height * 0.33)
            seen.append(f"({item.get('marker') or chr(65 + index)})")
    if seen:
        print(f"  BULLETS SEEN {field}: {', '.join(seen)} read with their bullet when the line was cut - the piece "
              f"checks count that bullet as there while the piece still starts where its snip started (S161)")


def centre_cuts_in_gaps(image, items, cuts, field, geometry=None):
    """S146: a cut that reads clean can still sit on the very edge of the next bullet's
    circle (the tries step about a third of a letter at a time and stop at the first clean
    cut), leaving a sliver of the circle in the left snip. So each cut between two values
    is put in the MIDDLE of its white gap: if it is in ink, it moves left out of that ink
    (the edge of the circle) to the white gap before it; then to the middle of that gap.
    Never further than about one circle width, never across a stroke other than the one
    it sits in. Checked with one read on each side (left: its value, nothing after;
    right: its bullet + value) - if that is not clean, the cut stays where it was.
    S164: 'white' means white on the PAGE too - the OCR copy has its fill-in line taken
    out, and with it the bottom of a circle that sits on that line, and thin circle
    strokes can fall under its ink threshold; so a gap there could run into the next
    bullet's circle (Mile Post: x=332-352, the middle cut into (B)'s circle). The page's
    own handwriting (the colour map, fill-in lines out - what the piece checks see) is
    added: a column with ink in either is ink."""
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        mask = (np.array(ImageOps.grayscale(image)) < 150).astype(np.uint8)
    inked = np.count_nonzero(mask, axis=0) > 0
    offset = (geometry or {}).get("ocr_offset_x")
    if offset is not None and geometry.get("line_box") and geometry.get("page_image") is not None:
        _lx, band_top, _rx, band_bottom = geometry["line_box"]
        page_ink = piece_ink_mask(geometry["page_image"], (int(offset), int(band_top),
                                                           int(offset) + len(inked), int(band_bottom)))
        page_columns = page_ink.sum(axis=0) >= 2
        n = min(len(inked), len(page_columns))
        inked = inked.copy()
        inked[:n] |= page_columns[:n]
    reach = int(1.3 * image.height)
    new_cuts = list(cuts)
    for index in range(1, len(cuts) - 1):
        cut = int(new_cuts[index])
        low = max(int(new_cuts[index - 1]) + 4, cut - reach)
        x = cut
        while x > low and inked[min(x, len(inked) - 1)]:          # out of the ink it sits in (leftwards)
            x -= 1
        if x <= low or inked[min(x, len(inked) - 1)]:
            continue
        a = x
        while a - 1 > low and not inked[a - 1]:
            a -= 1
        b = x
        while b + 1 < len(inked) and not inked[b + 1]:
            b += 1
        middle = (a + b) // 2
        if abs(middle - cut) < 2 or b - a < 2:
            continue
        if middle > cut:
            continue          # S166: a clean cut is never moved right - right of it is the next bullet's circle
        left_item, right_item = items[index - 1], items[index]
        left_read = snip_read_compact(image.crop((new_cuts[index - 1], 0, middle, image.height)), field)
        right_read = snip_read_compact(image.crop((middle, 0, new_cuts[index + 1], image.height)), field)
        left = best_layout(left_read, field, left_item)
        right = best_layout(right_read, field, right_item)
        clean = ((left["found"] or left["tail"]) and not left["extra_after"]
                 and right["bullet"] and (right["found"] or right["head"]) and not right["extra_before"])
        if not clean:
            print(f"  CUT IN GAP {field} ({left_item.get('marker')})|({right_item.get('marker')}): the middle of the "
                  f"gap (x={middle}) reads '{left_read}' | '{right_read}' - not clean, cut stays at x={cut}")
            continue
        new_cuts[index] = middle
        window = right_item.get("cut_window")
        if window and window[0] == window[1]:
            right_item["cut_window"] = (middle, middle)                  # still final (S139)
        info = right_item.get("snip_steps")
        if info:
            info["final"] = middle
        print(f"  CUT IN GAP {field} ({left_item.get('marker')})|({right_item.get('marker')}): x={cut} -> x={middle}, "
              f"the middle of the white gap x={a}-{b} ('{left_read}' | '{right_read}')")
    return new_cuts


def apply_snip_cuts(image, items, cuts, margin=4):
    """item['image'] = its piece of the row: between its two cuts (neighbours never
    overlap), then trimmed to its own handwriting - it starts where its bullet starts
    and ends where its value ends, without the empty paper between two values."""
    width = image.width
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        mask = (np.array(ImageOps.grayscale(image)) < 150).astype(np.uint8)
    inked = np.count_nonzero(mask, axis=0) > 1
    for index, item in enumerate(items):
        x0 = max(0, cuts[index])
        x1 = min(width, cuts[index + 1])
        columns = np.flatnonzero(inked[x0:x1])
        if len(columns):
            x0, x1 = max(x0, x0 + int(columns[0]) - margin), min(x1, x0 + int(columns[-1]) + 1 + margin)
        item["snip_bounds"] = (int(x0), int(x1))
        if x1 - x0 > 10:
            item["image"] = image.crop((x0, 0, x1, image.height))


def ink_extent(image):
    """(first, last + 1) inked column of the handwriting (red ink, else dark ink)."""
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        mask = (np.array(ImageOps.grayscale(image)) < 150).astype(np.uint8)
    columns = np.flatnonzero(np.count_nonzero(mask, axis=0) > 0)
    if not len(columns):
        return None
    return int(columns[0]), int(columns[-1]) + 1


def find_next_bullet_value(result, field):
    """'Here is (A) - where is (B)?': on the OCR copy of the line, find where the last
    value found so far ends (grow a crop from its start until it reads that whole
    value), then read only what is to the right of it. Returns (cut, new item) or None."""
    image = result.get("ocr_image")
    items = result.get("items") or []
    cuts = result.get("snip_cuts")
    if image is None or not items or not cuts:
        return None
    last = items[-1]
    start = cuts[-2]
    mask = handwriting_mask(image).astype(np.uint8)
    if np.count_nonzero(mask) < 20:
        mask = (np.array(ImageOps.grayscale(image)) < 150).astype(np.uint8)
    inked = np.count_nonzero(mask, axis=0) > 0
    gaps, run = [], None                                   # ink-free gaps right of the start
    for x in range(start + 1, image.width + 1):
        if x < image.width and not inked[x]:
            run = x if run is None else run
        else:
            if run is not None and x - run >= 3:
                gaps.append(run + (x - run) // 2)
            run = None
    end = None
    for x in gaps:
        read = snip_read_compact(image.crop((start, 0, x, image.height)), field)
        if snip_split_parts(read, last["value"]) is not None:
            end = x
            break
    if end is None:
        print(f"  NEXT BULLET {field}: could not find where ({last.get('marker') or 'A'}) "
              f"{last['value']} ends")
        return None
    rest = image.crop((end, 0, image.width, image.height))
    if int(np.count_nonzero(mask[:, end:])) < 60:
        print(f"  NEXT BULLET {field}: nothing written after {last['value']} (x={end})")
        return None
    print(f"  NEXT BULLET {field}: ({last.get('marker') or 'A'}) {last['value']} ends at x={end} - "
          f"reading what is to the right of it")
    found = coordinate_consensus(rest, field)
    new = [i for i in found.get("items") or [] if str(i["value"]) != str(last["value"])]
    if not new:
        print(f"  NEXT BULLET {field}: no value found to the right of {last['value']}")
        return None
    return end, new[0]


def apply_page1_bullet_count(results):
    """The bullets on page 1 follow each other: 'here is (A) - where is (B)?'.
      - count = the most bullets seen on any page-1 value line (latitude, longitude,
        wheel count, mile post/station) where OCR saw the letter of EVERY value, or the
        count the Wheel count and mile post/station lines agree on; used when it is 2+
      - a line with FEWER values than that looks for the next one right after its last
        value (only in the handwriting after it) - if found, it is added and the line's
        snips are re-cut; if not, the line gets a warning (nothing is invented)
      - a line with MORE values keeps the ones with the most votes (the others are
        printed as dropped)"""
    fields = ("Latitude", "Longitude", "Wheel Count", "Mile Post/Station")
    candidates = {}
    for field in fields:
        items = (results.get(field) or {}).get("items") or []
        if len(items) >= 2 and all(i.get("marker_read") for i in items):
            candidates[field] = len(items)
    station_counts = {f: len((results.get(f) or {}).get("items") or []) for f in ("Wheel Count", "Mile Post/Station")}
    agreed = [n for n in station_counts.values() if n]
    if agreed and len(set(agreed)) == 1 and agreed[0] >= 2:
        candidates.setdefault("Wheel count + mile post/station lines", agreed[0])
    # S80: when most value lines agree on a count (2 or more), that count wins - one line
    # read into more pieces (e.g. a handwritten 77 read as 7 + 2) no longer sets the
    # count for the whole page; that line gets the warning instead.
    line_counts = {f: len((results.get(f) or {}).get("items") or []) for f in fields}
    line_counts = {f: n for f, n in line_counts.items() if n}
    tally = Counter(line_counts.values())
    majority = None
    if tally:
        (top, top_votes), *rest = tally.most_common()
        if top >= 2 and top_votes >= 2 and (not rest or rest[0][1] < top_votes):
            majority = top
    if majority is not None:
        expected = majority
        source = ", ".join(f for f, n in line_counts.items() if n == expected) + f" ({tally[expected]} of " \
                 f"{len(line_counts)} value lines agree)"
    elif candidates:
        expected = max(candidates.values())
        source = ", ".join(f for f, n in candidates.items() if n == expected)
    else:
        return
    print(f"BULLET COUNT: {expected} bullets (seen on {source}) -> every page 1 value line should have {expected}")
    for field in fields:
        result = results.get(field)
        items = (result or {}).get("items") or []
        if not result or not items:
            continue
        while len(items) < expected:
            found = find_next_bullet_value(result, field)
            if not found:
                break
            end, new_item = found
            items.append(new_item)
            for index, item in enumerate(items):
                item["marker"] = chr(ord("A") + index)
                item["index"] = index + 1
            image = result["ocr_image"]
            cuts = list(result["snip_cuts"][:-1]) + [end, result["snip_cuts"][-1]]
            extent = ink_extent(image)
            if extent:
                cuts[-1] = min(image.width, extent[1] + 12)
            try:
                cuts = verify_snip_cuts(image, items, cuts, field, step=max(3, image.height // 6))
            except Exception as exc:
                print(f"  SNIP CHECK {field}: skipped ({exc})")
            apply_snip_cuts(image, items, cuts)
            result["items"] = items
            result["snip_cuts"] = cuts
            place_cuts_at_bullets(result, field)
            refine_piece_images(result, field)
            print(f"BULLET COUNT: {field} - found ({items[-1]['marker']}) {new_item['value']} after "
                  f"({items[-2]['marker']}) {items[-2]['value']}; snips re-cut")
        if len(items) > expected:
            keep = sorted(items, key=lambda i: (i["vote_count"], i["average_confidence"]), reverse=True)[:expected]
            dropped = [i["value"] for i in items if i not in keep]
            keep.sort(key=lambda i: items.index(i))          # still left to right
            for item in keep:
                item.pop("marker", None)
                item.pop("image", None)
            for index, item in enumerate(keep):
                item["marker"] = chr(ord("A") + index)
                item["index"] = index + 1
            result["items"] = keep
            result["snip_cuts"] = split_coordinate_snips(result.get("ocr_image"), keep, field,
                                                         result.get("page_geometry"))
            place_cuts_at_bullets(result, field)
            refine_piece_images(result, field)
            print(f"BULLET COUNT: {field} had {len(items)} values -> kept the {expected} with the most "
                  f"votes, dropped {dropped}")
            warning = (f"⚠ {field}: {len(items)} values found, but the page has {expected} bullets - kept "
                       f"{', '.join(i['value'] for i in keep)} (most votes), dropped {', '.join(dropped)} "
                       f"- check the snip")
            result["warning"] = warning
            result["bullet_warning"] = {"text": warning, "read": len(items), "bullets": expected}   # S93
            print(f"BULLET COUNT: {warning}")
        elif len(items) < expected:
            warning = (f"⚠ {field}: {len(items)} value(s) found, but the page has {expected} bullets "
                       f"- check the snip")
            result["warning"] = warning
            print(f"BULLET COUNT: {warning}")


def find_circled_bullets(image, own_line_y=None):
    """Bullets ((A), (B) ...) in a real crop of the line: [(x0, x1)] left to right.
    Uses the SAME tests as the Notes bullets - no separate detector:
      - the red handwriting (_ink_mask, as the Notes circle test) is split into marks
        wherever there is an ink-free gap of 2+ px (a circle with its letter inside is
        one mark; digits are separate marks)
      - the line height is the lower quarter of those marks' heights (the digits)
      - a mark is a bullet when enclosure_evidence - the Notes' bullet test - says
        'circle' (ring + letter inside, 1.25x taller than the line) or 'cut-off circle'
        (both side arcs ( ) present)
    Inside a mark, only the columns where the ink runs much taller than the digits
    (>= 1.15x) are tested - that is the circle - so a circle touching a digit is
    still found and starts where the circle starts, not where the digit starts."""
    offset = getattr(image, "page_offset", None)
    mask = _ink_mask(image)
    if mask is None:
        return []
    # red that belongs to the LINE ABOVE (e.g. the bottom of its circle hanging into
    # this band): on the page-1 colour map the handwriting AND the fill-in lines are
    # red, so a circle touching its own fill-in line is one connected red shape with
    # that line. A red shape that touches the band's top edge (= comes down from the
    # line above) and is NOT connected to this line's own fill-in line is the line
    # above's - it is taken out of the mask AND of the picture the circle test looks
    # at. Everything connected to this line's own fill-in line stays.
    if offset is not None and PAGE_MAP["classes"] is not None and own_line_y is not None:
        red = (page_map_region(offset, image.width, image.height) == MAP_HANDWRITING).astype(np.uint8)
        count, labels, stats, _ = cv2.connectedComponentsWithStats(red, 8)
        line_row = int(own_line_y) - offset[1]
        rows = slice(max(0, line_row - 3), max(0, min(red.shape[0], line_row + 4)))
        removed = np.zeros(mask.shape, dtype=bool)
        for index in range(1, count):
            if stats[index, cv2.CC_STAT_TOP] != 0:
                continue                                   # does not come down from the line above
            on_own_line = np.count_nonzero((labels[rows] == index).any(axis=0))
            if on_own_line >= 0.25 * red.shape[1]:
                continue                                   # connected to this line's own fill-in line
            removed |= labels == index
        if removed.any():
            mask[removed] = 0
            paper = np.asarray(image.convert("RGB")).copy()
            colour = PAGE_BACKGROUND["colour"]
            paper[removed] = (np.clip(colour, 0, 255).astype(np.uint8) if colour is not None
                              else np.array((255, 255, 255), dtype=np.uint8))
            image = Image.fromarray(paper)
    inked = np.count_nonzero(mask, axis=0) > 0
    # the page-1 colour map for this crop (when it knows where it sits on page 1):
    # black there = a searched printed label - a circle's edge never goes into it
    if offset is not None and PAGE_MAP["classes"] is not None:
        printed = page_map_region(offset, image.width, image.height) == MAP_PRINTED
    else:
        printed = np.zeros(mask.shape, dtype=bool)
    marks, start, gap = [], None, 0
    for x in range(len(inked) + 1):
        if x < len(inked) and inked[x]:
            if start is None:
                start = x
            gap = 0
        elif start is not None:
            gap += 1
            if gap >= 2 or x >= len(inked):
                marks.append((start, x - gap + 1))
                start, gap = None, 0
    if not marks:
        return []
    crops = [image.crop((max(0, a - 2), 0, min(image.width, b + 2), image.height)) for a, b in marks]
    heights = [h for h in (ink_height(c) for c in crops) if h]
    # the digits' height: the LOWER quarter of the mark heights - marks that hold a
    # circle are taller and would pull a plain median up (on these lines the digits
    # are nearly as tall as the circles, so that matters)
    line_height = float(np.percentile(heights, 25)) if heights else None
    if not line_height:
        return []
    # inside each mark, the columns whose ink runs much taller than the digits are the
    # circle (a ring spans top to bottom); a circle touching a digit is found this way
    # too, and its start is where ITS tall columns start - not where the digit starts
    rows = np.arange(mask.shape[0])[:, None]
    has = mask > 0
    top = np.where(has.any(axis=0), np.argmax(has, axis=0), -1)
    bottom = np.where(has.any(axis=0), mask.shape[0] - 1 - np.argmax(has[::-1], axis=0), -1)
    span = np.where(top >= 0, bottom - top + 1, 0)
    tall = span >= 1.15 * line_height
    found = []
    for a, b in marks:
        x, run_start, run_gap = a, None, 0
        while x <= b:
            if x < b and tall[x]:
                run_start = x if run_start is None else run_start
                run_gap = 0
            elif run_start is not None:
                run_gap += 1
                if run_gap > 3 or x >= b:
                    run_end = x - run_gap + 1
                    if run_end - run_start >= 0.5 * line_height:
                        # the ring's far-left / far-right edges curve in, so they are not
                        # 'tall': the whole circle runs from the tall part out to the first
                        # column with no red pen ON THE CIRCLE'S OWN ROWS (its top to its
                        # bottom) - ink of the lines above / below does not stretch it - and
                        # never into black (a searched label). At most 60% further.
                        tall_top = top[run_start:run_end][top[run_start:run_end] >= 0]
                        tall_bottom = bottom[run_start:run_end][bottom[run_start:run_end] >= 0]
                        y0 = int(tall_top.min()) if len(tall_top) else 0
                        y1 = int(tall_bottom.max()) + 1 if len(tall_bottom) else mask.shape[0]
                        own = (mask[y0:y1] > 0).any(axis=0)
                        label = printed[y0:y1].any(axis=0)
                        reach = int(0.6 * (run_end - run_start)) + 2
                        left = run_start
                        while (left - 1 >= max(0, run_start - reach) and own[left - 1]
                               and not label[left - 1]):
                            left -= 1
                        right = run_end
                        while right < min(len(own), run_end + reach) and own[right] and not label[right]:
                            right += 1
                        crop = image.crop((max(0, left - 2), 0, min(image.width, right + 2), image.height))
                        kind = enclosure_evidence({"image": crop, "text": ""}, line_height=line_height)
                        if kind in ("circle", "cut-off circle"):
                            found.append((int(left), int(right)))
                    run_start, run_gap = None, 0
            x += 1
    return found


def circle_start_by_scan(page, circle, read_top, read_bottom, label_height, taken_out=None):
    """Where the first circle really starts, read on the page-1 colour map along the
    middle of the line (the middle 30% of the rows that were read - the circle's
    sides and the letter cross it; the line above's ink and the fill-in line do not).
    Start at the letter (the red part nearest the circle's middle) and go left:
    red (the letter) -> white (inside the circle) -> red (the circle) -> white. Each
    red part reached this way is taken, and the walk goes on to the next red part on
    the left only while the white between them is short. It stops when it would go
    too far:
      - the white goes on longer than half a label height (nothing more of this
        circle over there), or
      - it reaches black (a searched label)
    and then comes back to the leftmost red it took - the cut is just before it. So
    when the letter touches the circle (one red part), the cut is still at the left
    of that red. Returns (page x of that red's first column, note) or (None, why not)."""
    if PAGE_MAP["classes"] is None or page is not PAGE_MAP["page"]:
        return None, "circle start: no colour map - circle finder's edge used"
    a, b = int(circle[0]), int(circle[1])
    x0 = max(0, a - int(label_height))
    height = read_bottom - read_top
    y0, y1 = int(read_top + 0.35 * height), int(read_top + 0.65 * height) + 1
    classes = page_map_region((x0, y0), max(1, b - x0), max(1, y1 - y0))
    red = (classes == MAP_HANDWRITING).any(axis=0)
    black = (classes == MAP_PRINTED).any(axis=0) & ~red
    runs, start = [], None                    # red parts, left to right (page x)
    for i in range(len(red) + 1):
        if i < len(red) and red[i]:
            start = i if start is None else start
        elif start is not None:
            runs.append((x0 + start, x0 + i))
            start = None
    if not runs:
        return None, f"circle start: no red across the middle of the line - circle finder's edge x={a} used"
    middle = (a + b) / 2.0
    index = min(range(len(runs)), key=lambda k: 0 if runs[k][0] <= middle < runs[k][1]
                else min(abs(runs[k][0] - middle), abs(runs[k][1] - middle)))
    max_white = max(4, int(0.5 * label_height))
    taken = [runs[index]]
    stop = "the search area ends"
    while index > 0:
        left, right = runs[index - 1], runs[index]
        between = black[left[1] - x0:right[0] - x0]
        if between.any():
            stop = f"black label at x={left[1] + int(np.flatnonzero(between)[-1])}"
            break
        if right[0] - left[1] > max_white:
            stop = f"white wider than {max_white} px"
            break
        index -= 1
        taken.append(runs[index])
    else:
        before = black[:max(0, runs[0][0] - x0)]
        if before.any():
            stop = f"black label at x={x0 + int(np.flatnonzero(before)[-1])}"
        elif runs[0][0] - x0 > max_white:
            stop = f"white wider than {max_white} px"
    first = taken[-1][0]
    if taken_out is not None:
        taken_out.extend(taken)                  # S165: the red parts, letter first, leftmost last
    parts = ", white, ".join(f"red x={r[0]}-{r[1] - 1}" for r in taken)
    note = (f"circle start: from the letter going left: {parts}, then {stop} -> cut just before the leftmost "
            f"red, x={first} (circle finder had x={a})")
    return first, note


def printed_ink_mask(rgb):
    """S120/S121: printed (non-handwriting) ink in a crop's REAL colours: anything that
    is not the paper and not the red pen - black print, and also the lighter, blurred
    pixels of small print like a ':' on coloured paper."""
    rgb = rgb.astype(np.int32)
    r, g, b = rgb[:, :, 0], rgb[:, :, 1], rgb[:, :, 2]
    red = (r > 140) & (g < 120) & (b < 120) & (r - g > 60)      # red pen - not the orange / yellow paper
    paper_colour = PAGE_BACKGROUND.get("colour")
    if paper_colour is not None:
        paper = np.sqrt(((rgb - np.asarray(paper_colour, dtype=np.int32)) ** 2).sum(axis=2)) < \
            PAGE_BACKGROUND.get("threshold", 90)
    else:
        paper = rgb.min(axis=2) > 200
    return (~paper & ~red & (rgb.max(axis=2) < 170)) | ((rgb.max(axis=2) < 110) & ~red), red


def label_end_x(page, label):
    """S121: where the printed label ends - right after its ':' when it has one (found
    on the page). The first value's snip never starts left of it. None without a colon
    (the printed-ink check, S120, still keeps the label out)."""
    colon = find_label_colon(page, label)
    if colon is not None:
        print(f"  LABEL END: '{label.get('text', '')}' ends with a ':' at x={colon - 2} (its EasyOCR box ends "
              f"at x={int(label['x1'])}) - the first snip starts right after it")
    return colon


def find_label_colon(page, label):
    """S121: the ':' that ends a printed label (e.g. 'Longitude:'). The label's EasyOCR
    box often stops before it, so it is looked for just around the box's right end:
    two small printed marks, one above the other. Returns the page x just right of the
    colon, or None when the label has no colon there."""
    if page is None or not label:
        return None
    h = max(8, int(label["y1"] - label["y0"]))
    x0 = max(0, int(label["x1"] - 1.5 * h))
    x1 = min(page.width, int(label["x1"] + 1.2 * h))
    y0, y1 = max(0, int(label["y0"] - 0.2 * h)), min(page.height, int(label["y1"] + 0.2 * h))
    if x1 - x0 < 4 or y1 - y0 < 4:
        return None
    printed, _red = printed_ink_mask(np.asarray(page.crop((x0, y0, x1, y1)).convert("RGB")))
    count, _labels, stats, _c = cv2.connectedComponentsWithStats(printed.astype(np.uint8), connectivity=8)
    dots = [stats[i] for i in range(1, count)
            if 3 <= stats[i][cv2.CC_STAT_AREA] <= 0.12 * h * h
            and stats[i][cv2.CC_STAT_HEIGHT] <= 0.4 * h and stats[i][cv2.CC_STAT_WIDTH] <= 0.4 * h]
    pairs = []
    for a in dots:
        for b in dots:
            if b[cv2.CC_STAT_TOP] <= a[cv2.CC_STAT_TOP] + a[cv2.CC_STAT_HEIGHT]:
                continue                                          # b must sit below a
            overlap = (min(a[0] + a[2], b[0] + b[2]) - max(a[0], b[0]))
            gap = b[cv2.CC_STAT_TOP] - (a[cv2.CC_STAT_TOP] + a[cv2.CC_STAT_HEIGHT])
            if overlap >= 0.3 * min(a[2], b[2]) and 0.05 * h <= gap <= 0.7 * h:
                pairs.append(max(a[0] + a[2], b[0] + b[2]))
    return x0 + int(max(pairs)) + 2 if pairs else None


def printed_ink_end(page, box):
    """S120: where printed text ends inside a snip, judged by the page's REAL colours
    (like the stray marks): dark ink that is not the red handwriting - the end of the
    printed label, its ':' - with the long printed fill-in line taken out first. Only
    printed ink LEFT of the first handwriting in the box counts. Returns the page x
    just right of it, or None when there is none."""
    x0, y0, x1, y1 = (int(v) for v in box)
    if x1 - x0 < 4 or y1 - y0 < 4:
        return None
    dark, red = printed_ink_mask(np.asarray(page.crop((x0, y0, x1, y1)).convert("RGB")))
    length = max(20, int(1.5 * (y1 - y0)))
    lines = cv2.morphologyEx(dark.astype(np.uint8), cv2.MORPH_OPEN,
                             cv2.getStructuringElement(cv2.MORPH_RECT, (length, 1)))
    lines = cv2.dilate(lines, cv2.getStructuringElement(cv2.MORPH_RECT, (5, 5))) > 0   # line ends too
    printed = (dark & ~lines).sum(axis=0) >= 2
    hand = np.flatnonzero(red.sum(axis=0) >= 2)
    if not len(hand):
        return None
    before = np.flatnonzero(printed[:int(hand[0])])
    return x0 + int(before[-1]) + 2 if len(before) else None


def label_limit_left(page, box, low_x):
    """The left edge of the first piece may move out only up to the searched label:
    the first column right of the last black (label) column between low_x and the
    piece, on the colour map. S120: and never left of printed ink in the page's real
    colours (the label's end and its ':' - left out of the colour map's black when they
    sit outside the label's EasyOCR box). Returns the new lowest left edge."""
    limit = low_x
    if PAGE_MAP["classes"] is not None and page is PAGE_MAP["page"] and box[0] > low_x:
        x0, y0, x1, y1 = int(low_x), int(box[1]), int(box[0]), int(box[3])
        black = (page_map_region((x0, y0), x1 - x0, y1 - y0) == MAP_PRINTED).any(axis=0)
        cols = np.flatnonzero(black)
        limit = x0 + int(cols[-1]) + 1 if len(cols) else low_x
    printed = printed_ink_end(page, (min(int(low_x), int(box[0])), box[1], box[2], box[3]))
    return max(limit, printed) if printed is not None else limit


def place_cuts_at_window_circles(result, field, circles, windows, page, offset, height,
                                 band_top, band_bottom, line_top, line_bottom):
    """S112: with a cut window between every two values, a circle is a bullet only when
    it is INSIDE its window (between where the left value ends and the right value
    starts); circles anywhere else are round digits / marks and are ignored. When every
    window has its circle, each cut goes just before it (its left edge found by the
    circle start walk, kept inside the window); when one has none, the cuts the windows
    gave stay. (A)'s snip starts just before the first circle left of the first window
    when its walk ends at the printed label."""
    items = result["items"]
    cuts = list(result["snip_cuts"])
    page_windows = [(offset + w[0], offset + w[1]) for w in windows]
    picked = []
    for wl, wr in page_windows:
        inside = [c for c in circles if wl - 4 <= c[0] <= wr + 4]
        picked.append(min(inside, key=lambda c: c[0]) if inside else None)
    outside = [c[0] for c in circles if c not in picked]
    for item in items:
        item.pop("bullet_page_x0", None)
    if not all(picked):
        missing = [chr(ord("B") + i) for i, c in enumerate(picked) if c is None]
        print(f"  CUT WINDOW {field}: circles at x = {[c[0] for c in circles]} - none inside the window of "
              f"({', '.join(missing)}) - the circle-start walk is done from each bullet instead (S165)")
        walk_bullets_from_cuts(result, field, picked, page, offset, height, band_top, band_bottom,
                               line_top, line_bottom, circles)
        return
    new_cuts = [cuts[0]]
    for (wl, wr), circle in zip(page_windows, picked):
        scan_x, _note = circle_start_by_scan(page, circle, band_top, band_bottom, height)
        start = scan_x if scan_x is not None and wl <= scan_x <= wr + 4 else int(circle[0])
        new_cuts.append(int(min(max(start - offset - 3, wl - offset), wr - offset)))
    new_cuts.append(cuts[-1])
    if any(b <= a for a, b in zip(new_cuts, new_cuts[1:])):
        print(f"  CUT WINDOW {field}: circles out of order with the values - the cuts the windows gave stay")
        return
    if result.get("ocr_image") is not None:
        apply_snip_cuts(result["ocr_image"], items, new_cuts)
    result["snip_cuts"] = new_cuts
    for index, item in enumerate(items[1:], start=1):
        info = item.get("snip_steps") or {"measured": int(cuts[index]), "steps": []}
        info.update({"final": new_cuts[index], "circle": True})
        item["snip_steps"] = info
    first = [c for c in circles if c[1] <= page_windows[0][0] and c not in picked]
    first_note = "no circle left of the first window"
    if first:
        scan_x, first_note = circle_start_by_scan(page, min(first, key=lambda c: c[0]), band_top, band_bottom, height)
        if scan_x is not None and "black label" in first_note:
            items[0]["bullet_page_x0"] = int(max(0, label_limit_left(page, (scan_x, line_top, scan_x + 1, line_bottom),
                                                                      scan_x - 3)))
    print(f"  CUT WINDOW {field}: circle(s) inside the windows at x = {[c[0] for c in picked]} -> each cut just "
          f"before its circle (cuts at x = {new_cuts[1:-1]})"
          + (f"; circles outside the windows ignored: {outside}" if outside else ""))
    print(f"  CUT WINDOW {field}: ({items[0].get('marker') or 'A'}) {first_note}")


def circle_left_ink(page, circle, line_top, line_bottom, height):
    """S168: where a circle's ink really starts on the left: from the circle finder's edge
    (found from the circle's tall columns), follow the page's handwriting - all rows of
    the line, fill-in line out - to the left while there is ink in the column (short white
    breaks inside a thin, broken stroke - up to a twelfth of a letter height, at least 3 px -
    are crossed); a longer white run ends it. At most half a letter height left of the
    finder's edge."""
    edge = int(circle[0])
    reach = int(max(6, height * 0.5))
    x0 = max(0, edge - reach)
    ink = piece_ink_mask(page, (x0, int(line_top), edge + 3, int(line_bottom))).sum(axis=0) >= 1
    x = edge - x0
    leftmost = edge
    white = 0
    allowed = max(3, int(height / 12))
    while x - 1 >= 0:
        x -= 1
        if ink[x]:
            leftmost, white = x0 + x, 0
        else:
            white += 1
            if white > allowed:
                break
    return leftmost


def walk_bullets_from_cuts(result, field, picked, page, offset, height, band_top, band_bottom,
                           line_top, line_bottom, circles=()):
    """S165: the circle-start walk for every bullet, also when the circle finder did not
    put a circle inside the cut's window (e.g. the window is just the final cut, S139).
    For each value after the first: from its bullet's letter - the red just right of the
    cut - going left through the circle's strokes and the small gaps inside it, to the
    circle's leftmost red (it stops at white wider than half a letter height or at black
    print). The cut goes just before the leftmost red that still leaves the left value
    whole: the red parts the walk took are tried leftmost first, each with one read on
    each side (left: its value, nothing after; right: its bullet + value) - a part that
    is really the end of the left value (e.g. its last '1' close to the circle) fails
    that read and the next one is tried. None clean -> the cut stays.
    For the first value: the walk from its letter to the black label, when no circle
    was found for it.
    S166: a cut that already reads clean is only ever moved LEFT, never right: right of
    it is the next bullet's circle, and the walk across the middle of the line can miss
    the circle's left arc (it only crosses the middle rows lower down), so 'the leftmost
    red it took' can lie inside the circle. The circle finder's own left edge, when it is
    near the cut, is a candidate too."""
    items = result["items"]
    cuts = list(result["snip_cuts"])
    image = result.get("ocr_image")
    if image is None:
        return
    new_cuts = list(cuts)
    for index in range(1, len(items)):
        circle = picked[index - 1]
        if circle is None:
            start = offset + cuts[index]
            circle = (start, start + int(1.2 * height))   # the bullet's letter sits just right of the cut
        taken = []
        _scan_x, note = circle_start_by_scan(page, circle, band_top, band_bottom, height, taken_out=taken)
        chosen = None
        near = [r[0] for r in taken if offset + cuts[index] - 0.6 * height <= r[0] <= offset + cuts[index] + 1.2 * height]
        near += [int(c[0]) for c in circles if abs(c[0] - (offset + cuts[index])) <= 0.6 * height]   # S166
        for red_start in sorted(set(near)):                                    # only parts near the cut
            cut = int(red_start - offset - 3)
            if cut > cuts[index]:
                continue                                  # S166: never further right than the clean cut
            if not (new_cuts[index - 1] + 4 < cut < cuts[index + 1] - 4):
                continue
            left_read = snip_read_compact(image.crop((new_cuts[index - 1], 0, cut, image.height)), field)
            right_read = snip_read_compact(image.crop((cut, 0, cuts[index + 1], image.height)), field)
            left = best_layout(left_read, field, items[index - 1])
            right = best_layout(right_read, field, items[index])
            if ((left["found"] or left["tail"]) and not left["extra_after"]
                    and right["bullet"] and (right["found"] or right["head"]) and not right["extra_before"]):
                chosen = (cut, red_start, left_read, right_read)
                break
        letter = items[index].get("marker") or chr(ord("A") + index)
        # S167: the circle the circle finder found just RIGHT of the cut is this bullet's
        # circle (it was only 'outside the window' because the window is the cut itself)
        right_of_cut = [c for c in circles
                        if offset + cuts[index] - 4 <= c[0] <= offset + cuts[index] + 0.8 * height]
        circle_here = min(right_of_cut, key=lambda c: c[0]) if right_of_cut else None
        from_circle = False
        if circle_here is not None:
            # S168: with (B)'s circle known, the cut goes just before the circle - like Wheel
            # Count. The finder's edge comes from the circle's tall columns, and its thin
            # left arc reaches a little further left, so from that edge the page's own ink
            # (all rows of the line, fill-in line out) is followed left while it continues;
            # the first white column is where the circle starts. One read on each side checks
            # it (left: its whole value, nothing after; right: its bullet + value).
            leftmost = circle_left_ink(page, circle_here, line_top, line_bottom, height)
            cut = int(leftmost - offset - 2)
            if new_cuts[index - 1] + 4 < cut < cuts[index + 1] - 4:
                left_read = snip_read_compact(image.crop((new_cuts[index - 1], 0, cut, image.height)), field)
                right_read = snip_read_compact(image.crop((cut, 0, cuts[index + 1], image.height)), field)
                left = best_layout(left_read, field, items[index - 1])
                right = best_layout(right_read, field, items[index])
                arc_in_left = bool(re.search(r"[(\[{]\W*$", left_read))     # the circle's arc read as '('
                if ((left["found"] or left["tail"]) and not left["extra_after"] and not arc_in_left
                        and right["bullet"] and (right["found"] or right["head"]) and not right["extra_before"]):
                    chosen = (cut, leftmost, left_read, right_read)
                    from_circle = True
                    note = (f"circle finder: ({letter})'s circle at page x={int(circle_here[0])}-{int(circle_here[1])}; "
                            f"its ink followed left to page x={leftmost} (its thin left side) -> cut just before the "
                            f"circle, x={cut}")
        if chosen:
            new_cuts[index] = chosen[0]
            note += (f" -> the cut goes just before its red at x={chosen[1]} (cut x={chosen[0]}; reads "
                     f"'{chosen[2]}' | '{chosen[3]}')")
            items[index]["cut_window"] = (chosen[0], chosen[0])
            if from_circle:
                items[index]["cut_from_circle"] = True                             # S168
        elif circle_here is not None:
            page_cut = int(offset + cuts[index])
            note = (f"circle finder: ({letter})'s circle at page x={int(circle_here[0])}-{int(circle_here[1])}; the "
                    f"clean cut x={cuts[index]} (page x={page_cut}) is {int(circle_here[0]) - page_cut} px left of it, "
                    f"in the white before the circle - the whole circle is in ({letter})'s snip")
            if items[index].get("bullet_seen_from") is None:                       # S162 for this bullet too
                items[index]["bullet_seen_from"] = page_cut + int(height * 0.33)
        else:
            note += (" -> no red part at or left of the cut reads clean as a cut - the cut stays where it read clean "
                     "(S166: never moved right, into the circle)")
        print(f"  CIRCLE WALK {field} ({letter}): {note} (S165)")
    if any(b <= a for a, b in zip(new_cuts, new_cuts[1:])):
        print(f"  CIRCLE WALK {field}: cuts out of order - the cuts stay")
        return
    if new_cuts != cuts:
        apply_snip_cuts(image, items, new_cuts)
        result["snip_cuts"] = new_cuts
        for index, item in enumerate(items[1:], start=1):
            info = item.get("snip_steps") or {"measured": int(cuts[index]), "steps": []}
            info.update({"final": new_cuts[index]})
            if item.pop("cut_from_circle", False):
                info["circle"] = True                       # S168: placed at its circle, like Wheel Count
            item["snip_steps"] = info
    if items[0].get("bullet_page_x0") is None:
        start = offset + new_cuts[0]
        first_note = ""
        scan_x, first_note = circle_start_by_scan(page, (start, start + int(1.2 * height)), band_top, band_bottom,
                                                  height)
        if scan_x is not None and "black label" in first_note:
            items[0]["bullet_page_x0"] = int(max(0, label_limit_left(page, (scan_x, line_top, scan_x + 1,
                                                                            line_bottom), scan_x - 3)))
            print(f"  CIRCLE WALK {field} ({items[0].get('marker') or 'A'}): {first_note} (S165)")


def place_cuts_at_bullets(result, field):
    """'If it finds (B), start (B)'s snip right before it': the circled bullets are
    found on a real crop of the line; with one circle per value, each cut goes just
    before its value's circle (no reading or guessing needed). Otherwise the cuts
    found by reading stay."""
    geometry = result.get("page_geometry") or {}
    items = result.get("items") or []
    cuts = result.get("snip_cuts")
    for item in items:
        item.pop("bullet_page_x0", None)      # from an earlier run on this line (re-cut after the bullet count)
    if len(items) < 2 or not geometry or not cuts or len(cuts) != len(items) + 1:
        return
    page = geometry["page_image"]
    offset = geometry["ocr_offset_x"]
    height = geometry.get("label_height", 40)
    band_top, band_bottom = geometry["read_band"]
    x_start = max(0, int(offset + cuts[0] - height * 2))
    x_end = min(page.width, int(offset + cuts[-1]))
    _lx, line_top, _rx, line_bottom = geometry["line_box"]
    line = page_crop(page, (x_start, line_top, x_end, line_bottom))  # the line's own band only
    circles = [(x_start + a, x_start + b)
               for a, b in find_circled_bullets(line, own_line_y=geometry.get("fill_line_y"))]
    windows = [item.get("cut_window") for item in items[1:]]
    if all(windows):
        place_cuts_at_window_circles(result, field, circles, windows, page, offset, height,
                                     band_top, band_bottom, line_top, line_bottom)
        return
    if len(circles) > len(items):
        # more circles than values (e.g. a round digit or a stray mark passed the
        # circle test): each value's bullet is the FIRST circle in that value's own
        # part of the line (between the cuts found by reading) - a bullet comes
        # before its value. The others are dropped.
        kept = []
        for index in range(len(items)):
            part_start = offset + cuts[index] - (height if index == 0 else 0)
            part_end = offset + cuts[index + 1]
            inside = [c for c in circles if part_start <= (c[0] + c[1]) / 2.0 < part_end and c not in kept]
            if not inside:
                kept = None
                break
            kept.append(min(inside, key=lambda c: c[0]))
        found_at = [c[0] for c in circles]
        if kept is None:
            print(f"  BULLET CIRCLES {field}: {len(circles)} circle(s) at x = {found_at} for {len(items)} values - "
                  f"not one in every value's part - cuts from reading kept")
            return
        print(f"  BULLET CIRCLES {field}: {len(circles)} circle(s) at x = {found_at} for {len(items)} values - "
              f"kept the first circle in each value's part {[c[0] for c in kept]}, dropped "
              f"{[c[0] for c in circles if c not in kept]}")
        circles = kept
    if len(circles) != len(items):
        print(f"  BULLET CIRCLES {field}: {len(circles)} circle(s) at x = {[c[0] for c in circles]} for "
              f"{len(items)} values - cuts from reading kept")
        return
    # (B), (C) ... the same walk as (A) - going left from the letter to the circle's
    # side - but there is no black label left of them, only the previous value's
    # digits, which sit closer than the walk's 'too much white' stop. So the walk may
    # not go further left than the circle finder's edge (found from the circle's tall
    # columns - a digit is not tall): walked too far -> the finder's edge is used.
    starts, notes = [], []
    for circle in circles[1:]:
        scan_x, scan_note = circle_start_by_scan(page, circle, band_top, band_bottom, height)
        limit = int(circle[0]) - 2
        if scan_x is None:
            starts.append(int(circle[0]))
        elif scan_x < limit:
            starts.append(int(circle[0]))
            scan_note += (f" - that is past the circle finder's edge x={int(circle[0])} (the walk went into the "
                          f"previous value) -> x={int(circle[0])} used")
        else:
            starts.append(scan_x)
        notes.append(scan_note)
    new_cuts = [cuts[0]] + [int(start - offset - 3) for start in starts] + [cuts[-1]]
    if any(b <= a for a, b in zip(new_cuts, new_cuts[1:])):
        print(f"  BULLET CIRCLES {field}: circles out of order with the values - cuts from reading kept")
        return
    # (A) the same way as (B): its piece starts just before its own circle (page x),
    # not where the red ink left of it happens to stop. The circle's left edge is
    # checked on the colour map by going left from the letter: red (the letter),
    # white (inside the circle), red (the circle), white = the cut
    scan_x, scan_note = circle_start_by_scan(page, circles[0], band_top, band_bottom, height)
    # S96: the first bullet's circle comes right after the printed label - the walk left
    # from it ends at the label (or at a wide white gap before it). A walk that runs on
    # through red ink to the end of its search area started inside the handwriting: that
    # 'circle' is a round digit or a later bullet, and the circles do not line up with
    # the values -> they are not used.
    if "the search area ends" in scan_note:
        print(f"  BULLET CIRCLES {field}: circles rejected - ({items[0].get('marker') or 'A'})'s circle does not "
              f"sit after the printed label ({scan_note}) - cuts from reading kept")
        return
    image = result.get("ocr_image")
    result["reading_cuts"] = list(cuts)                 # S96: to go back to if the snips do not confirm
    result["cuts_from_circles"] = True
    if image is not None:
        apply_snip_cuts(image, items, new_cuts)
    result["snip_cuts"] = new_cuts
    start = scan_x if scan_x is not None else int(circles[0][0])
    # 3 px of margin before the circle - but never into the black label
    items[0]["bullet_page_x0"] = int(max(0, label_limit_left(page, (start, line_top, start + 1, line_bottom),
                                                             start - 3)))
    for index, item in enumerate(items[1:], start=1):
        info = item.get("snip_steps") or {"measured": int(cuts[index]), "steps": []}
        info.update({"final": new_cuts[index], "circle": True})
        item["snip_steps"] = info
    print(f"  BULLET CIRCLES {field}: {len(circles)} circled bullets found - each value's snip starts "
          f"just before its circle (cuts at x = {new_cuts[1:-1]}; "
          f"({items[0].get('marker') or 'A'}) starts at page x = {items[0]['bullet_page_x0']})")
    print(f"  BULLET CIRCLES {field}: ({items[0].get('marker') or 'A'}) {scan_note}")
    for index, item in enumerate(items[1:], start=1):
        print(f"  BULLET CIRCLES {field}: ({item.get('marker') or chr(ord('A') + index)}) {notes[index - 1]}")


def find_fill_line_above(page_image, x0, x1, y_start, y_stop):
    """Page y of the nearest printed fill-in line above y_start (a dark row with one
    unbroken run over >= 25% of the width), or None."""
    if y_start <= y_stop or x1 - x0 < 20:
        return None
    gray = np.asarray(page_image.crop((x0, y_stop, x1, y_start)).convert("L"))
    dark = gray < 120
    need = 0.25 * (x1 - x0)
    for y in range(dark.shape[0] - 1, -1, -1):
        row = np.concatenate(([0], dark[y].astype(np.int8), [0]))
        edges = np.flatnonzero(np.diff(row))
        if len(edges) and (edges[1::2] - edges[0::2]).max() >= need:
            return y_stop + y
    return None


def piece_page_box(result, index):
    """Page box of value `index`'s picture:
      - x: from where its bullet starts to where its value's ink ends (found on the
        OCR copy); the FIRST value also grows left while its red ink continues, so a
        circle starting under the end of the printed label is not cut off
      - y: the line's own band (fill-in line above -> just under its own fill-in line),
        so the lines above and below are never in the picture."""
    geometry = result.get("page_geometry") or {}
    items = result.get("items") or []
    cuts = result.get("snip_cuts")
    if not geometry or not cuts or len(cuts) != len(items) + 1:
        return None
    page = geometry["page_image"]
    offset = geometry["ocr_offset_x"]
    _lx, band_top, _rx, band_bottom = geometry["line_box"]
    height = geometry.get("label_height", 40)
    bounds = items[index].get("snip_bounds") or (cuts[index], cuts[index + 1])
    x0, x1 = offset + bounds[0], offset + bounds[1]
    if index == 0 and items[0].get("bullet_page_x0") is not None:
        x0 = items[0]["bullet_page_x0"]          # (A) found as a circle: start just before it
    elif index == 0:
        limit = max(0, int(x0 - height * 2))
        strip = page_crop(page, (limit, band_top, x0 + 1, band_bottom))
        red_columns = handwriting_mask(strip).sum(axis=0) >= 2
        x, gap, new_x = len(red_columns) - 1, 0, len(red_columns) - 1
        while x - 1 >= 0:
            x -= 1
            if red_columns[x]:
                new_x, gap = x, 0
            else:
                gap += 1
                if gap > 3:
                    break
        if new_x < len(red_columns) - 1:
            x0 = limit + new_x - 4
    x0, x1 = int(max(0, x0)), int(min(page.width, x1))
    # inside the band, keep only this value's own ink rows: grow from the rows that
    # were read, up and down, while its red ink continues (2 px gaps bridged). Ink of
    # the line above that crosses its fill-in line (e.g. a circle's bottom) sits
    # right under that line with paper in between -> not taken.
    read_top, read_bottom = geometry["read_band"]
    strip = page_crop(page, (x0, band_top, x1, band_bottom))
    red_rows = handwriting_mask(strip).sum(axis=1) >= 2
    start = max(0, min(len(red_rows) - 1, read_top - band_top))
    end = max(0, min(len(red_rows) - 1, read_bottom - band_top))
    y, gap, own_top = start, 0, start
    while y - 1 >= 0:
        y -= 1
        if red_rows[y]:
            own_top, gap = y, 0
        else:
            gap += 1
            if gap > 2:
                break
    y, gap, own_bottom = end, 0, end
    while y + 1 < len(red_rows):
        y += 1
        if red_rows[y]:
            own_bottom, gap = y, 0
        else:
            gap += 1
            if gap > 2:
                break
    y0 = band_top + max(0, own_top - 4)
    y1 = max(band_top + own_bottom + 5, read_bottom + 6)     # fill-in line stays in the picture
    return (x0, int(y0), x1, int(min(band_bottom, y1)))


PIECE_CHECK_ROUNDS = 8          # at most this many rounds of edge moves per piece
PIECE_CHECK_ROUNDS_EXPECTED = 12   # S158: when the value is known - keep going (safety cap)


SNIP_WHITE_MARGIN = 0.25    # S160: white on each side of a snip's ink, as a share of the label height,
                            # that counts as 'clearly apart from its neighbours' (about a third of a digit)


def snip_white_margins(page, box, band_top, band_bottom, height, check_left=True, check_right=True):
    """S160: how much white paper there is on each side of a snip's handwriting, on the
    page: from the snip's first / last ink column outwards to the next ink (the label, the
    previous or next value), within the line's band - the fill-in line not counted. Both at least half a letter height,
    and no ink at the snip's own edge columns -> 'clean': the snip holds its whole value
    and nothing of its neighbours, whatever the reader makes of the writing.
    Only the sides that face ANOTHER VALUE are measured (check_left / check_right): the
    first value's left side faces the printed label - its edge is set by the label's colon
    (S121) and the label's red underline / strike-through would only confuse the
    measure; the last value's right side faces nothing."""
    x0, _y0, x1, _y1 = box
    reach = int(height * 3)
    # the piece checks' own ink: handwriting WITHOUT the fill-in line under the values -
    # that line runs under every column and would leave no white anywhere
    inked = piece_ink_mask(page, (max(0, x0 - reach), band_top, min(page.width, x1 + reach),
                                  band_bottom)).sum(axis=0) >= 2
    inside = inked[x0 - max(0, x0 - reach): x0 - max(0, x0 - reach) + (x1 - x0)]
    columns = [i for i, v in enumerate(inside) if v]
    if not columns:
        return {"clean": False, "left": 0, "right": 0, "cut": ""}
    offset = x0 - max(0, x0 - reach)
    first_ink, last_ink = offset + columns[0], offset + columns[-1]
    left = 0
    x = first_ink - 1
    while x >= 0 and not inked[x]:
        left += 1
        x -= 1
    right = 0
    x = last_ink + 1
    while x < len(inked) and not inked[x]:
        right += 1
        x += 1
    cut = [side for side, at in (("left", offset), ("right", offset + (x1 - x0) - 1))
           if 0 <= at < len(inked) and inked[at] and (0 <= at - 1 < len(inked) and inked[at - 1])
           and (0 <= at + 1 < len(inked) and inked[at + 1])]
    need = max(8, int(height * SNIP_WHITE_MARGIN))
    cut = [side for side in cut if (side == "left" and check_left) or (side == "right" and check_right)]
    clean = (left >= need or not check_left) and (right >= need or not check_right) and not cut
    return {"clean": clean, "left": left if check_left else None, "right": right if check_right else None,
            "cut": " and ".join(cut), "need": need}


def read_guided_moves(read, item, box, height):
    """S158: the read says where the value is in the snip; anything after it (e.g. the
    next bullet) or in front of it (besides its own bullet) tells where the edge should
    be - characters of handwriting this size are about evenly spaced, so a position in
    the text is a position in the picture. Returns moves (edge deltas) that jump the
    edge there."""
    compact = re.sub(r"\s+", "", str(read or ""))
    span = value_span_in_read(compact, item.get("value"), item.get("marker"))
    if span is None or not compact:
        return []
    width, moves = box[2] - box[0], []
    per_char = width / max(1, len(compact))
    after = compact[span.end():].strip("()[]{}.:;,'|")
    if re.search(r"[0-9A-Za-z]", after):
        new_right = box[0] + int(per_char * span.end() + per_char * 0.3)
        if box[0] + 10 < new_right < box[2]:
            moves.append((0, 0, new_right - box[2], 0))            # right edge to where its value ends
    before = compact[:span.start()]
    own = str(item.get("marker") or "").upper()
    stray = re.sub(r"[()\[\]{}.:;,'|" + (re.escape(own + "".join(LOOKALIKE_CLASSES.get(own, ""))) if own else "")
                   + r"]", "", before)
    if re.search(r"[0-9A-Za-z]", stray):
        new_left = box[0] + int(per_char * span.start() - max(per_char * 2, height * 1.3))
        if box[0] < new_left < box[2] - 10:
            moves.append((new_left - box[0], 0, 0, 0))             # left edge to just before its bullet
    return moves


def snip_left_over(read, item):
    """S158: in words, what a snip still holds besides its bullet + value."""
    compact = re.sub(r"\s+", "", str(read or ""))
    span = value_span_in_read(compact, item.get("value"), item.get("marker"))
    if span is None:
        return f"its value {item.get('value')} is not whole in it"
    after = compact[span.end():].strip("()[]{}.:;,'|")
    before = compact[:span.start()].strip("()[]{}.:;,'|")
    parts = []
    own = str(item.get("marker") or "").upper()
    own_shapes = set(own + LOOKALIKE_CLASSES.get(own, "") + BULLET_LOOKALIKE_DIGITS.get(own, "")) if own else set()
    if before and not all(ch.upper() in own_shapes for ch in before):     # S166: its own bullet (A, 4, ...) is fine
        parts.append(f"'{before}' before its value")
    if after:
        parts.append(f"'{after}' after its value")
    return ", ".join(parts)


PIECE_PERFECT = 6
BULLET_LOOKALIKE_DIGITS = {"A": "4", "B": "8", "C": "6", "D": "0", "E": "3", "S": "5", "I": "1", "O": "0"}


def piece_read_score(page, box, item, field):
    """Score a piece out of 6 - four from reading it back, two from its pixels:
      +1 its value is there whole (exactly, or the same digits when a stray mark on
         the page was read as an extra '.' - e.g. 211.448.73 for 211448.73)
      +1 nothing of the value before it (no 2+ digits in front)
      +1 nothing after it (no '(B' / next digits)
      +1 its own bullet letter is there (or the digit it is often read as: B->8, A->4)
      +1 no handwriting cut at its left or right edge (ink running straight across
         the edge: in its outermost column and the page column just outside it) - a
         sliver of the next circle or a half digit shows up here even when the
         reader ignores it; a mark that only comes close to the edge is fine
      +1 no printed text in it (dark ink that is not red, after the fill-in line is
         removed) - e.g. the end of the printed label"""
    crop = page.crop(box)
    cleaned = remove_horizontal_lines(crop)
    read = snip_read_compact(cleaned, field)
    score = 0                                   # read points (value, before, after, bullet)
    parts = snip_split_parts(read, item["value"])
    if parts is None:                          # same digits, ignoring stray dots / marks
        squeeze = lambda t: re.sub(r"[^0-9A-Za-z+-]", "", t)
        read_s, value_s = squeeze(read), squeeze(str(item["value"]))
        index = read_s.find(value_s) if value_s else -1
        if index >= 0:
            parts = (read_s[:index], read_s[index + len(value_s):])
    if parts is not None:
        before, after = parts
        score += 1
        score += 0 if re.search(r"\d{2}", before) else 1
        score += 1 if after.strip(".)]|") == "" else 0
        letter = str(item.get("marker") or "").upper()
        lookalike = BULLET_LOOKALIKE_DIGITS.get(letter, "")
        # S161: the bullet also counts when this line already showed it in this snip (a
        # cut read) and the piece still starts where that snip started - a read that
        # just does not print the circled letter does not make the bullet missing
        known = (item.get("bullet_seen_from") is not None and box[0] <= item["bullet_seen_from"])
        score += 1 if (not item.get("marker_read") or re.search(r"[A-Za-z]", before)
                       or (lookalike and lookalike in before) or known) else 0
    pixel = 0                                   # pixel points (edges clean, no printed text)
    # an edge CUTS a mark when the handwriting runs straight across it: ink in the
    # piece's outermost column AND in the page column just outside it, on the same
    # rows. Ink that merely comes close to the edge (a 1-3 px gap to the next mark)
    # is not cut - the marks on these lines can sit only a few pixels apart.
    x0, y0, x1, y1 = box
    wide = piece_ink_mask(page, (max(0, x0 - 1), y0, min(page.width, x1 + 1), y1))   # fill-in lines out
    edge_ink = 0
    if wide.shape[1] >= 4:
        left_in, left_out = (wide[:, 1], wide[:, 0]) if x0 > 0 else (wide[:, 0], np.zeros_like(wide[:, 0]))
        right_in, right_out = ((wide[:, -2], wide[:, -1]) if x1 < page.width
                               else (wide[:, -1], np.zeros_like(wide[:, -1])))
        # S161: the first value's left side faces the printed LABEL, not another value -
        # ink there is its own circle running under the label's end; not a cut
        left_cut = 0 if item.get("label_side_left") else int((left_in & left_out).sum())
        edge_ink = left_cut + int((right_in & right_out).sum())
    pixel += 1 if edge_ink < 2 else 0
    gray = np.asarray(cleaned.convert("L"))
    printed = int(((gray < 100) & ~(make_red_mask_array(cleaned, loose=True) > 0)).sum())
    pixel += 1 if printed < max(30, int(0.002 * gray.size)) else 0
    # ranking: what it READS comes first (never give up the value or the bullet to
    # get cleaner edges), then clean pixels, then how close to clean (less cut ink at
    # the edge, less printed text) so a move that gets closer still counts
    return score + pixel, read, (score, pixel, -(edge_ink + printed))


def snap_moves(page, box, low_x, high_x, reach):
    """Big moves for an edge that cuts through handwriting: jump that edge to the
    nearest column with no red ink - outward (take the whole mark, e.g. the rest of a
    circle) or inward (drop the sliver, e.g. the edge of the next circle)."""
    x0, y0, x1, y1 = box
    region_x0, region_x1 = max(low_x, x0 - reach), min(high_x, x1 + reach)
    if region_x1 - region_x0 < 10:
        return []
    red = piece_ink_mask(page, (region_x0, y0, region_x1, y1))                         # fill-in lines out
    free = red.sum(axis=0) == 0
    def clear(page_x):
        i = page_x - region_x0
        return 0 <= i < len(free) and free[i]
    moves = []
    for side, edge, outward in (("left", x0, -1), ("right", x1 - 1, 1)):
        if clear(edge):
            continue                                      # this edge does not cut ink
        for direction in (outward, -outward):                 # out (take the whole mark), in (drop the sliver)
            x = edge
            while region_x0 <= x + direction < region_x1 and not clear(x + direction):
                x += direction
            target = x + direction
            if not clear(target):
                continue
            delta = target - edge + (-2 if direction < 0 else 2)
            moves.append((delta, 0, 0, 0) if side == "left" else (0, 0, delta, 0))
    return moves


def window_edge_limits(items, index, geometry, low_x, high_x):
    """S112: a snip's left edge may not go left of its own cut window (it would take the
    previous value's last digit) and its right edge may not go right of the next
    value's window (it would take the next bullet)."""
    offset = geometry.get("ocr_offset_x", 0)
    if index == 0 and geometry.get("label_end"):
        low_x = max(low_x, int(geometry["label_end"]))          # S121: right after the label's ':'
    own = items[index].get("cut_window") if index > 0 else None
    following = items[index + 1].get("cut_window") if index + 1 < len(items) else None
    if own:
        low_x = max(low_x, offset + own[0])
    if following:
        high_x = min(high_x, offset + following[1])
    return low_x, high_x


def refine_piece_images(result, field):
    """Check every final piece by reading it back. If it does not read perfectly
    (6/6), move its edges one small step at a time - left, right, top, bottom, in or
    out - keep a move only when the read gets BETTER, and go again (a few rounds), so
    a crop that made things worse is undone. Every try's read and score are kept.
    S158: also a line with ONE value - its snip starts right after the label's colon and
    is checked the same way (it used to be the whole line, label end included). Left /
    right edges never cross the next or previous value's piece and stay inside the band.
    S158: with the line's expected values known (S151) the finish line is the snip reading
    its bullet + its expected value and nothing else; up to PIECE_CHECK_ROUNDS_EXPECTED
    rounds, and every read is used: where it shows something after the value (the next
    bullet) or before it, the edge jumps straight there. A snip that still is not clean
    gets a note on the card saying what is still in it."""
    items = result.get("items") or []
    geometry = result.get("page_geometry") or {}
    if not items or not geometry:
        return
    items[0]["label_side_left"] = True              # S161: also on one-value lines
    page = geometry["page_image"]
    # S162: a bullet found as a CIRCLE on the page (the circle finder + the walk from its
    # letter to the circle's leftmost red, stopping at the black label) is known to be in
    # the piece as long as the piece starts at that circle - no read needs to print it
    from_circles = []
    for index, item in enumerate(items):
        if item.get("bullet_page_x0") is not None:
            circle_from = int(item["bullet_page_x0"] + geometry.get("label_height", 40) * 0.33)
            if item.get("bullet_seen_from") is None or circle_from > item["bullet_seen_from"]:
                item["bullet_seen_from"] = circle_from
                from_circles.append(f"({item.get('marker') or chr(65 + index)}) at page x={item['bullet_page_x0']}")
    if from_circles:
        print(f"  BULLETS SEEN {field}: circle(s) found on the page for {', '.join(from_circles)} - the piece checks "
              f"count that bullet as there while the piece starts at its circle (S162)")
    _lx, band_top, _rx, band_bottom = geometry["line_box"]
    height = geometry.get("label_height", 40)
    step = max(3, int(height * 0.15))
    boxes = [piece_page_box(result, i) for i in range(len(items))]
    checked = set()                                  # pieces whose picture the check made
    for index, item in enumerate(items):
        box = boxes[index]
        if not box:
            continue
        low_x = boxes[index - 1][2] if index > 0 and boxes[index - 1] else max(0, box[0] - int(height * 2))
        if index == 0:
            low_x = label_limit_left(page, box, low_x)       # never out into the black label
        high_x = boxes[index + 1][0] if index + 1 < len(items) and boxes[index + 1] else min(page.width, box[2] + int(height * 2))
        low_x, high_x = window_edge_limits(items, index, geometry, low_x, high_x)     # S112
        if index == 0 and box[0] < low_x < box[2] - 10:
            # S120: the first crop held printed text (the label's end / its ':') - it starts after it
            print(f"  PIECE CHECK {field}: ({item.get('marker') or 'A'}) first crop started in the printed label "
                  f"(x={box[0]}) - its left edge moved to x={low_x}, right of the printed ink")
            box = (int(low_x), box[1], box[2], box[3])
            boxes[index] = box
        try:
            score, read, rank = piece_read_score(page, box, item, field)
        except Exception as exc:
            print(f"  PIECE CHECK {field}: skipped ({exc})")
            break
        tries = [{"box": box, "read": read, "score": score, "kept": True}]          # [0] = the first crop
        rounds = 0
        expected_here = item.get("value") in (EXPECTED["by_field"].get(field) or [])
        max_rounds = PIECE_CHECK_ROUNDS_EXPECTED if expected_here else PIECE_CHECK_ROUNDS
        snip_is_right = False
        if expected_here and score < PIECE_PERFECT:
            # S163: the S160 test BEFORE any edge moves - nothing extra in the read and white
            # space on each side that faces another value: the first crop is right as it is
            # (the reader only misreads the handwriting), no moves are needed
            margins = snip_white_margins(page, box, band_top, band_bottom, height,
                                         check_left=index > 0, check_right=index + 1 < len(items))
            if not snip_left_over(read, item) and margins["clean"]:
                snip_is_right = True
                sides = ", ".join(f"{px} px {side} of the ink" for side, px in (("left", margins["left"]),
                                                                                  ("right", margins["right"]))
                                  if px is not None)
                print(f"  PIECE CHECK {field} ({item.get('marker') or 'A'}): reads '{read}' for {item['value']}, but "
                      f"nothing extra is in it and there is white space between it and the next value"
                      + (f" ({sides})" if sides else "") + " - the first crop is right, no edge moves needed; the "
                      f"handwriting is just read differently (S160/S163)")
        while score < PIECE_PERFECT and rounds < max_rounds and not snip_is_right:
            rounds += 1
            best = None
            fine = max(2, step // 3)
            moves = snap_moves(page, box, low_x, high_x, int(height * 2))
            moves = read_guided_moves(read, item, box, height) + moves        # S158: jump where the read says
            for size in (step, fine):
                # left out / in, right out / in, top up / down, bottom down / up
                moves += [(-size, 0, 0, 0), (size, 0, 0, 0), (0, 0, size, 0), (0, 0, -size, 0),
                          (0, -size, 0, 0), (0, size, 0, 0), (0, 0, 0, size), (0, 0, 0, -size)]
            for delta in moves:
                candidate = (max(low_x, box[0] + delta[0]), max(band_top, box[1] + delta[1]),
                             min(high_x, box[2] + delta[2]), min(band_bottom, box[3] + delta[3]))
                if candidate == box or candidate[2] - candidate[0] < 10 or candidate[3] - candidate[1] < 10:
                    continue
                cand_score, cand_read, cand_rank = piece_read_score(page, candidate, item, field)
                tries.append({"box": candidate, "read": cand_read, "score": cand_score, "kept": False})
                if cand_rank > rank and (best is None or cand_rank > best[4]):
                    best = (cand_score, candidate, cand_read, len(tries) - 1, cand_rank)
            if best is None:
                break                                  # no move makes it better -> stop
            score, box, read, rank = best[0], best[1], best[2], best[4]
            for t in tries:
                t["kept"] = False
            tries[best[3]]["kept"] = True
            boxes[index] = box
        if expected_here and score < PIECE_PERFECT and not snip_is_right:   # S158: shown, not settled for silently
            left_over = snip_left_over(read, item)
            margins = snip_white_margins(page, box, band_top, band_bottom, height,         # S160
                                         check_left=index > 0, check_right=index + 1 < len(items))
            letter = item.get("marker") or "A"
            if not left_over and margins["clean"]:
                # S160: nothing extra in the read and white space on both sides of the ink -
                # the snip is right; the reader just misreads the handwriting
                sides = ", ".join(f"{px} px {side} of the ink" for side, px in (("left", margins["left"]),
                                                                                  ("right", margins["right"]))
                                  if px is not None)
                print(f"  PIECE CHECK {field} ({letter}): reads '{read}' for {item['value']}, but nothing extra is "
                      f"in it and there is white space between it and the next value ({sides}) - the snip is right, "
                      f"the handwriting is just read differently (S160)")
            else:
                measured = " / ".join(f"{px} px {side}" for side, px in (("left", margins["left"]),
                                                                          ("right", margins["right"])) if px is not None)
                why = left_over or (f"ink runs to its {margins['cut']} edge" if margins["cut"] else
                                    f"only {measured} of white between it and the next value, "
                                    f"{margins.get('need', 0)} px needed")
                note = (f"{field} ({letter}): the snip could not be made to hold only its bullet "
                        f"and {item['value']} - it reads '{read}'" + (f" ({why})" if why else ""))
                result["note"] = "  ".join(([result["note"]] if result.get("note") else []) + [note])
                print(f"  PIECE CHECK {field}: {note}")
        item["piece_box"] = box
        item["piece_tries"] = tries
        item["piece_checked_value"] = item["value"]      # S97: the value this snip was checked against
        item["image"] = page.crop(box)
        checked.add(index)
        letter = f"({item.get('marker')}) " if item.get("marker") else ""
        if len(tries) > 1:
            print(f"  PIECE CHECK {field} {letter}{item['value']}: first crop read "
                  f"'{tries[0]['read']}' ({tries[0]['score']}/{PIECE_PERFECT}) -> after {rounds} round(s) "
                  f"'{read}' ({score}/{PIECE_PERFECT})")
        elif snip_is_right:
            print(f"  PIECE CHECK {field} {letter}{item['value']}: reads '{read}' ({score}/{PIECE_PERFECT} only "
                  f"because the handwriting is read differently) - crop kept as it is (S163)")
        else:
            print(f"  PIECE CHECK {field} {letter}{item['value']}: reads '{read}' "
                  f"({PIECE_PERFECT}/{PIECE_PERFECT}) - crop kept")
    # only when the check stopped early (an error): the pieces it did not get to show
    # their first crop - the picture that used to be made for every piece beforehand
    for index, item in enumerate(items):
        if index not in checked and boxes[index] and boxes[index][2] - boxes[index][0] > 5:
            item["image"] = page.crop(boxes[index])
    # S96: cuts placed at bullet circles stay only when the snips confirm them - every
    # piece reads at least half its points (its value, nothing of the others...). If not,
    # the circles did not line up with the values: the cuts found by reading are used.
    if result.pop("cuts_from_circles", False):
        weak = []
        for item in items:
            kept = [t for t in item.get("piece_tries") or [] if t.get("kept")]
            if kept and kept[-1]["score"] < PIECE_PERFECT / 2:
                weak.append(f"({item.get('marker')}) {item['value']} {kept[-1]['score']}/{PIECE_PERFECT}")
        reading_cuts = result.pop("reading_cuts", None)
        if weak and reading_cuts and result.get("ocr_image") is not None:
            print(f"  BULLET CIRCLES {field}: circles rejected - the snips cut at them do not read their values "
                  f"({', '.join(weak)}) - cuts from reading used instead")
            for item in items:
                for key in ("bullet_page_x0", "piece_box", "piece_tries"):
                    item.pop(key, None)
                if (item.get("snip_steps") or {}).get("circle"):
                    item["snip_steps"].update({"circle": False, "final": item["snip_steps"].get("measured")})
            apply_snip_cuts(result["ocr_image"], items, reading_cuts)
            result["snip_cuts"] = reading_cuts
            refine_piece_images(result, field)


def extract_coordinate(page_image, label, field, width_fraction=0.42):
    if label is None:
        return None
    label_height = label["y1"] - label["y0"]
    left = int(label["x1"] + label_height * 0.02)
    right = int(min(page_image.width, left + page_image.width * width_fraction))
    bottom = min(page_image.height, int(label["y1"] + label_height * 0.90))
    _v = lap_timer(2, measure=True)                                 # S405
    # dataC (accuracy fix A2): handwriting written tall, well above its label's top, is cut off by the usual
    # read area (it starts 0.35 label heights above the label) and no read gives a value at all - only then
    # the line is read once more from higher up (1.2 label heights above the label)
    for reach in (0.35, 1.2):
        top = max(0, int(label["y0"] - label_height * reach))
        provisional = page_image.crop((left, top, right, bottom))
        underline_y = find_underline_y(provisional)
        if underline_y is not None:
            final_bottom = max(1, underline_y - 2)
        else:
            final_bottom = int(provisional.height * 0.72)

        # the READ area stays as it was (label end -> fill-in line); the pictures shown are
        # real page crops made from it at the end (see refine_piece_images)
        crop_bottom = top + final_bottom
        coordinate_crop = page_image.crop((left, top, right, crop_bottom))
        cleaned = remove_horizontal_lines(coordinate_crop)
        trim = content_box(cleaned) or (0, 0, cleaned.width, cleaned.height)
        ocr_crop = cleaned.crop(trim)
        if PAGE_MAP["page"] is page_image:
            ocr_crop.page_offset = (left + trim[0], top + trim[1])     # where it sits on page 1
        result = coordinate_consensus(ocr_crop, field)
        if (result or {}).get("items"):
            break
        if reach == 0.35:
            first_try = (top, underline_y, final_bottom, crop_bottom, trim, ocr_crop, result)
            print(f"  {field}: no value in any read of the usual area - read again from higher up "
                  f"(tall handwriting - dataC fix A2)")
        else:                                       # nothing from higher up either: the usual area, as before
            top, underline_y, final_bottom, crop_bottom, trim, ocr_crop, result = first_try
    expected = EXPECTED["by_field"].get(field)
    if expected and result and len(result.get("items") or []) < len(expected):
        items_from_expected(field, result)                       # S158: no extra reads needed
    if (expected and result and result.get("attempt_count", 30) < 30
            and len(result.get("items") or []) != len(expected)):
        # S157: the first reads fitted the expected values, but the vote did not give that
        # many values (each read was off in a different place) - all 30 reads after all
        print(f"  EARLY STOP {field}: the vote gave {len(result.get('items') or [])} value(s) for {len(expected)} "
              f"expected - all 30 reads are made after all (S157)")
        result = coordinate_consensus(ocr_crop, field, allow_early_stop=False)
    _v(f"{field}: OCR attempts + consensus")
    if field in EXPECTED_FIELDS:                                   # S151
        match_bullets_to_rows(field, result)
        apply_expected_values(field, result)
    # where things are on the PAGE, for the 'Page 1 snip steps' tab (real page crops)
    line_bottom = top + (underline_y + int(label_height * 0.3) if underline_y is not None else final_bottom)
    # the line's own band: between the fill-in line of the line ABOVE and a little under
    # its own fill-in line. Every picture of this line (bullet search, pieces) stays in
    # it, so the handwriting of the lines above / below never gets in.
    above = find_fill_line_above(page_image, left, right, int(label["y0"]),
                                 max(0, int(label["y0"] - label_height * 2.5)))
    band_top_page = above + 3 if above is not None else max(0, int(label["y0"] - label_height * 0.8))
    band_bottom_page = min(page_image.height, line_bottom)
    geometry = {
        "page_image": page_image,
        "area_box": (max(0, int(label["x0"] - label_height * 0.5)),
                     max(0, int(label["y0"] - label_height * 1.6)),
                     right, min(page_image.height, int(label["y1"] + label_height * 1.6))),
        # a bit higher than the read area so tall handwriting / circles are not cut off in the picture
        "line_box": (max(0, int(label["x0"] - label_height * 0.2)), band_top_page,
                     right, band_bottom_page),
        "ocr_offset_x": left + trim[0],       # page x of the OCR copy's x = 0
        "read_band": (top, crop_bottom),      # page rows that were read
        "fill_line_y": top + underline_y if underline_y is not None else None,   # own fill-in line (page y)
        "label_end": label_end_x(page_image, label),   # S121: right of the label's ':' (or its box)
        "label_height": label_height,
    }
    cuts = split_coordinate_snips(ocr_crop, result.get("items", []), field, geometry)
    _v(f"{field}: snip check (cut between values)")
    if cuts is None and result.get("items"):
        extent = ink_extent(ocr_crop)
        if extent:
            cuts = [max(0, extent[0] - 12), min(ocr_crop.width, extent[1] + 12)]
    output = {**result, "image": coordinate_crop, "ocr_image": ocr_crop,
              "page_geometry": geometry, "snip_cuts": cuts}
    place_cuts_at_bullets(output, field)
    _v(f"{field}: bullet circles + circle start walk")
    refine_piece_images(output, field)
    _v(f"{field}: piece checks")
    return output


# ============================================================
# NOTES DETECTION
# ============================================================

def detect_notes_regions(image):
    print()
    print("Detecting handwriting in full Notes block...")
    _detector_started = time.perf_counter()
    wait_for_notes_detector()                             # S133: usually loaded long before
    output = notes_detector.predict(
        input=np.array(image),
        text_det_thresh=0.20,
        text_det_box_thresh=0.30,
        text_det_unclip_ratio=1.5,
        text_rec_score_thresh=0.0,
    )
    results = list(output)
    record_timing("Notes handwriting detector (whole Notes block)", time.perf_counter() - _detector_started, 2)
    if not results:
        return []
    data = results[0].json
    if callable(data):
        data = data()
    if isinstance(data, str):
        data = json.loads(data)
    res = data.get("res", data)
    texts = res.get("rec_texts", [])
    scores = res.get("rec_scores", [])
    boxes = res.get("rec_boxes", [])
    if isinstance(texts, np.ndarray):
        texts = texts.tolist()
    if isinstance(scores, np.ndarray):
        scores = scores.tolist()
    if isinstance(boxes, np.ndarray):
        boxes = boxes.tolist()

    items = []
    for index, text in enumerate(texts):
        text = str(text).strip()
        if not text:
            continue
        try:
            box = boxes[index]
            items.append({
                "text": text,
                "confidence": safe_float(scores[index]),
                "x0": int(float(box[0])),
                "y0": int(float(box[1])),
                "x1": int(float(box[2])),
                "y1": int(float(box[3])),
            })
        except Exception:
            continue
    return items


def is_notes_label(text):
    cleaned = re.sub(r"[^a-z]", "", str(text).lower())
    if cleaned in ["notes", "note"]:
        return True
    numbers = re.sub(r"[^0-9]", "", str(text))
    if numbers == "19" and len(str(text)) <= 4:
        return True
    return False


def detected_region_box(image, item):
    """The crop box crop_detected_region uses (in `image`'s coordinates)."""
    # A handwritten closing parenthesis is often clipped just beyond x1, so
    # extend the crop when the detector saw "(" without ")".
    item_text = str(item.get("text", ""))
    item_height = max(1, item["y1"] - item["y0"])
    right_padding = 5
    if "(" in item_text and ")" not in item_text:
        right_padding = max(30, int(item_height * 0.90))
    return (
        max(0, item["x0"] - 5),
        max(0, item["y0"] - 3),
        min(image.width, item["x1"] + right_padding),
        min(image.height, item["y1"] + 3),
    )


def crop_detected_region(image, item):
    return image.crop(detected_region_box(image, item))


# ============================================================
# TEXT NORMALIZATION
# ============================================================

def normalize_token(text):
    text = str(text).strip()
    text = (
        text
        .replace("—", "-")
        .replace("–", "-")
        .replace("−", "-")
        .replace("’", "'")
        .replace("‘", "'")
    )
    text = re.sub(r"[^A-Za-z0-9.%/@()'\-:*]", "", text)       # '*' kept (handwritten asterisk)
    return text.upper()


def normalize_for_matching(text):
    return re.sub(r"[^A-Z0-9.%/@()'\-:*]", "", normalize_token(text))


def normalize_alpha_for_matching(text):
    return re.sub(r"[^A-Z]", "", normalize_token(text))


def normalize_line(text):
    output = []
    for token in re.findall(r"\S+", str(text)):
        token = normalize_token(token)
        if token:
            output.append(token)
    return " ".join(output)


def tokenize_line(text):
    output = []
    for token in re.findall(r"\S+", str(text)):
        normalized = normalize_token(token)
        if normalized:
            output.append(normalized)
    return output


BULLET_MARKER_TOKEN = re.compile(r"^\([A-Za-z0-9]{1,2}\)$")


def is_non_english_token(token, at_line_start=False):
    """
    Whole tokens whose letters are NOT English words and must not enter the
    English word list (neighbour words, sentence scoring, language model):
      - number-shaped tokens with letter look-alikes: 34.O%  0O:37
      - bullet markers in parentheses: (A)  (B)  (1) - ONLY as the first token,
        because a bullet always starts the line; a (B) later in a line is text
      - known OCR junk: (CID:)
    """
    token = str(token or "").strip()
    return bool(
        is_number_shaped_token(token)
        or (at_line_start and BULLET_MARKER_TOKEN.fullmatch(token))
        or OCR_JUNK_TOKEN.fullmatch(token)
    )


def english_word_spans(text):
    """
    (start, end, word) for every letter run that counts as an English word, left
    to right. alpha_words_from_text, replace_nth_alpha_word and the English
    pass rebuild all use this, so their word numbering always agrees.
    """
    text = str(text)
    spans = []
    for token_number, token_match in enumerate(re.finditer(r"\S+", text)):
        if is_non_english_token(token_match.group(0), at_line_start=(token_number == 0)):
            continue
        for word_match in re.finditer(r"[A-Za-z]+", token_match.group(0)):
            spans.append((
                token_match.start() + word_match.start(),
                token_match.start() + word_match.end(),
                word_match.group(0),
            ))
    return spans


def replace_english_word_spans(text, replacements):
    """replacements: {word_number: new_word} -> text with those words swapped."""
    text = str(text)
    output = []
    last = 0
    for number, (start, end, word) in enumerate(english_word_spans(text)):
        output.append(text[last:start])
        output.append(replacements.get(number, word))
        last = end
    output.append(text[last:])
    return "".join(output)


def alpha_words_from_text(text):
    return [word.upper() for _, _, word in english_word_spans(text)]


# ============================================================
# STRING SIMILARITY
# ============================================================

def text_similarity(a, b):
    a = normalize_for_matching(a)
    b = normalize_for_matching(b)
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    sequence = SequenceMatcher(None, a, b).ratio()
    maximum = max(len(a), len(b))
    length_score = 1.0 - abs(len(a) - len(b)) / maximum
    return sequence * 0.78 + length_score * 0.22


def levenshtein_distance(a, b):
    a = str(a)
    b = str(b)
    if a == b:
        return 0
    if not a:
        return len(b)
    if not b:
        return len(a)
    previous = list(range(len(b) + 1))
    for i, char_a in enumerate(a, start=1):
        current = [i]
        for j, char_b in enumerate(b, start=1):
            insertion = current[j - 1] + 1
            deletion = previous[j] + 1
            substitution = previous[j - 1] + (0 if char_a == char_b else 1)
            current.append(min(insertion, deletion, substitution))
        previous = current
    return previous[-1]


def normalized_edit_similarity(a, b):
    a = normalize_alpha_for_matching(a)
    b = normalize_alpha_for_matching(b)
    if not a or not b:
        return 0.0
    distance = levenshtein_distance(a, b)
    return 1.0 - distance / max(len(a), len(b))


# ============================================================
# ROUGH CHARACTER ESTIMATE
# ============================================================

def estimate_visible_character_count(image):
    image = trim_to_content(image)
    red_mask = make_red_mask_array(image, loose=True)
    ys, xs = np.where(red_mask > 0)
    if len(xs) < 5:
        gray = np.array(ImageOps.grayscale(image))
        ys, xs = np.where(gray < 185)
    if len(xs) == 0:
        return {"count": 1.0, "rounded": 1, "reliability": 0.0, "aspect": 0.0}

    ink_width = max(1, int(xs.max() - xs.min() + 1))
    ink_height = max(1, int(ys.max() - ys.min() + 1))
    aspect = ink_width / ink_height
    estimated = max(1.0, aspect / 0.455)
    rounded = max(1, int(round(estimated)))

    if ink_height < 20:
        reliability = 0.35
    elif ink_height < 35:
        reliability = 0.60
    else:
        reliability = 0.85
    if estimated > 16:
        reliability *= 0.65

    return {
        "count": estimated,
        "rounded": rounded,
        "reliability": clamp(reliability),
        "aspect": aspect,
    }


def candidate_visible_length(text):
    return len(normalize_token(text))


def should_use_length_scoring(text):
    text = normalize_token(text)
    alpha_numeric = re.sub(r"[^A-Z0-9]", "", text)
    if not alpha_numeric:
        return False
    if re.fullmatch(r"\d+\.\d+%?", text):
        return False
    if len(alpha_numeric) <= 1 and len(text) > len(alpha_numeric):
        return False
    return True


def calculate_length_match_score(text, geometry):
    if not should_use_length_scoring(text):
        return 1.0
    difference = abs(candidate_visible_length(text) - geometry["count"])
    reliability = geometry["reliability"]
    tolerance = 0.60 + (1.0 - reliability) * 0.70
    score = math.exp(-0.5 * (difference / max(tolerance, 0.35)) ** 2)
    return clamp(score)


# ============================================================
# WHOLE-LINE OCR
# ============================================================

def _easyocr_left_to_right(results):
    sortable = []
    for result in results:
        try:
            if len(result) < 2:
                continue
            bbox = result[0]
            text = result[1]
            confidence = safe_float(result[2]) if len(result) >= 3 else 0.0
            xs = [point[0] for point in bbox]
            sortable.append(((min(xs) + max(xs)) / 2, text, confidence))
        except Exception:
            continue
    sortable.sort(key=lambda item: item[0])
    return sortable


def collect_black_white_attempts(black_white_image):
    """Whole-line reads of the line on page 1's step 4 (every non-paper pixel completely
    black on white): PaddleOCR at 1x, 2x and 3x and EasyOCR. The picture is already
    pure black / white, so the threshold / red versions of the first baseline would
    all be the same picture - they are not repeated."""
    attempts = []
    if black_white_image is None:
        return attempts
    pictures = [black_white_image.resize((black_white_image.width * scale, black_white_image.height * scale))
                for scale in [1, 2, 3]]
    for scale, (raw, confidence) in zip([1, 2, 3], paddle_read_text_images(pictures, kind="Notes whole lines")):
        text = normalize_line(raw)
        if text:
            attempts.append({"text": text, "confidence": confidence, "source": f"Paddle BlackWhite x{scale}"})
    try:
        easy_results = easy_reader.readtext(
            np.array(black_white_image.resize((black_white_image.width * 2, black_white_image.height * 2))),
            detail=1, paragraph=False)
    except Exception:
        easy_results = []
    if easy_results:
        sortable = _easyocr_left_to_right(easy_results)
        if sortable:
            text = normalize_line(" ".join(item[1] for item in sortable))
            if text:
                confidence = sum(safe_float(item[2]) for item in sortable) / len(sortable)
                attempts.append({"text": text, "confidence": confidence, "source": "EasyOCR BlackWhite"})
    return attempts


def compare_line_consensus(first, second):
    """Baseline 1 (the page as it is) vs baseline 2 (black/white): the two consensus
    lines lined up word by word; prints what is the same and what differs."""
    a = [e.get("display", e["text"]) for e in (first or {}).get("slots") or []]
    b = [e.get("display", e["text"]) for e in (second or {}).get("slots") or []]
    print()
    print("=" * 70)
    print("BASELINE 1 vs BASELINE 2 (page as it is vs black/white)")
    print("=" * 70)
    print(f"  1: {' '.join(a) or '(nothing)'}")
    print(f"  2: {' '.join(b) or '(nothing)'}")
    same = 0
    for tag, i1, i2, j1, j2 in SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if tag == "equal":
            same += i2 - i1
            for word in a[i1:i2]:
                print(f"  same     {word}")
        elif tag == "replace" and i2 - i1 == j2 - j1:
            for w1, w2 in zip(a[i1:i2], b[j1:j2]):
                print(f"  differ   1: {w1:<18} 2: {w2}")
        else:
            print(f"  differ   1: {' '.join(a[i1:i2]) or '(none)':<18} 2: {' '.join(b[j1:j2]) or '(none)'}")
    print(f"  -> {same} of {max(len(a), len(b))} word(s) the same")


def consensus_slot_rank(entry):
    """How sure a consensus slot is: (confident?, share of reads that fit it, share of
    reads with exactly that spelling). Words use the consensus' own confident rule;
    numbers / times / marks: >= 40% of the reads and a 15% lead."""
    if entry["type"] == "word":
        sure = consensus_entry_confident(entry)
    else:
        sure = entry.get("fit", 0) >= CONSENSUS_NUMBER_MIN_SHARE and entry.get("lead", 0) >= CONSENSUS_NUMBER_MIN_LEAD
    return (1 if sure else 0, float(entry.get("fit", 0) or 0), float(entry.get("exact_share", 0) or 0))


def merge_line_consensus(first, second):
    """The FINAL whole-line consensus, between baseline 1 (page as it is) and baseline
    2 (black/white). The two are lined up word by word:
      - the same in both -> that word
      - different -> the more sure one: a confident slot beats a not-confident one,
        then the larger share of its reads that fit it, then the larger share of
        reads with exactly that spelling; a full tie keeps baseline 1
      - words only one side has (a word split or joined differently) -> baseline 1's
    Returns a consensus like the other two, each slot marked with where it came from."""
    a = [dict(e) for e in (first or {}).get("slots") or []]
    b = [dict(e) for e in (second or {}).get("slots") or []]
    if not b:
        return first
    if not a:
        return second
    key = lambda e: str(e.get("text", "")).upper()
    slots = []
    for tag, i1, i2, j1, j2 in SequenceMatcher(None, [key(e) for e in a], [key(e) for e in b],
                                              autojunk=False).get_opcodes():
        if tag == "equal":
            for e in a[i1:i2]:
                e["from_baseline"] = "both"
                slots.append(e)
        elif tag == "replace" and i2 - i1 == j2 - j1:
            for e1, e2 in zip(a[i1:i2], b[j1:j2]):
                pick = e2 if consensus_slot_rank(e2) > consensus_slot_rank(e1) else e1
                pick["from_baseline"] = "2" if pick is e2 else "1"
                pick["other_baseline"] = e1.get("display", e1["text"]) if pick is e2 else e2.get("display", e2["text"])
                slots.append(pick)
        else:
            for e in a[i1:i2]:
                e["from_baseline"] = "1 (not lined up with 2)"
                slots.append(e)
    parts = []
    for e in slots:
        shown = e.get("display", e["text"] + e.get("suffix", ""))
        if shown == "." and parts:
            parts[-1] += "."
            continue
        parts.append(shown)
    return {"slots": slots, "text": " ".join(parts)}


def print_final_line_consensus(consensus):
    print()
    print("=" * 70)
    print("FINAL WHOLE-LINE CONSENSUS (between baseline 1 and baseline 2)")
    print("=" * 70)
    for e in consensus.get("slots") or []:
        shown = e.get("display", e["text"])
        where = e.get("from_baseline", "1")
        if e.get("other_baseline") is not None:
            sure, fit, exact = consensus_slot_rank(e)
            where += (f" (more sure: {'confident' if sure else 'not confident'}, {fit:.0%} of its reads fit, "
                      f"{exact:.0%} spelled exactly) "
                      f"- other baseline had {e['other_baseline']}")
        print(f"  {shown:<10} from baseline {where}")
    print(f"FINAL WHOLE-LINE CONSENSUS: {consensus.get('text', '')}")


def collect_whole_line_attempts(line_image, detector_text, detector_confidence, black_white_image=None):
    attempts = []
    detector_normalized = normalize_line(detector_text)
    if detector_normalized:
        attempts.append({
            "text": detector_normalized,
            "confidence": detector_confidence,
            "source": "Paddle detector",
        })

    versions = [
        ("Original", line_image),
        ("Threshold110", make_binary(line_image, 110)),
        ("Threshold130", make_binary(line_image, 130)),
        ("Threshold150", make_binary(line_image, 150)),
        ("Threshold170", make_binary(line_image, 170)),
        ("RedExcess", make_red_excess_image(line_image)),
        ("RedMask", make_red_mask_image(line_image, dilate=True, loose=True)),
    ]
    jobs = [(version_name, scale, version.resize((version.width * scale, version.height * scale)))
            for version_name, version in versions for scale in [1, 2]]
    for (version_name, scale, _picture), (raw, confidence) in zip(
            jobs, paddle_read_text_images([picture for _n, _s, picture in jobs], kind="Notes whole lines")):
        text = normalize_line(raw)
        if text:
            attempts.append({
                "text": text,
                "confidence": confidence,
                "source": "Paddle " + version_name + f" x{scale}",
            })

    try:
        easy_results = easy_reader.readtext(
            np.array(line_image.resize((line_image.width * 2, line_image.height * 2))),
            detail=1,
            paragraph=False,
        )
    except Exception:
        easy_results = []

    if easy_results:
        sortable = _easyocr_left_to_right(easy_results)
        if sortable:
            easy_text = normalize_line(" ".join(item[1] for item in sortable))
            easy_confidence = sum(item[2] for item in sortable) / len(sortable)
            if easy_text:
                attempts.append({
                    "text": easy_text,
                    "confidence": easy_confidence,
                    "source": "EasyOCR whole line",
                })
    return attempts


# ============================================================
# BASELINE TOKENS
# ============================================================

def build_baseline_tokens(attempts, detector_text):
    detector_tokens = tokenize_line(detector_text)
    target_count = len(detector_tokens)
    if target_count == 0:
        return []

    aligned_attempts = []
    for attempt in attempts:
        tokens = tokenize_line(attempt["text"])
        if len(tokens) == target_count:
            aligned_attempts.append({
                "tokens": tokens,
                "confidence": attempt["confidence"],
                "source": attempt["source"],
            })
    if not aligned_attempts:
        aligned_attempts.append({
            "tokens": detector_tokens,
            "confidence": 0.5,
            "source": "Detector fallback",
        })

    baseline = []
    for position in range(target_count):
        exact_groups = defaultdict(list)
        for attempt in aligned_attempts:
            exact_groups[attempt["tokens"][position]].append(attempt)
        all_tokens = [attempt["tokens"][position] for attempt in aligned_attempts]

        candidates = []
        for token, entries in exact_groups.items():
            exact_votes = len(entries)
            confidence = sum(entry["confidence"] for entry in entries) / exact_votes
            agreement = (
                sum(text_similarity(token, other) for other in all_tokens)
                / max(len(all_tokens), 1)
            )
            vote_score = min(exact_votes / 5.0, 1.0)
            score = vote_score * 0.45 + agreement * 0.30 + confidence * 0.25
            candidates.append({
                "text": token,
                "score": score,
                "exact_votes": exact_votes,
                "agreement": agreement,
                "confidence": confidence,
            })
        candidates.sort(
            key=lambda item: (item["score"], item["exact_votes"], item["confidence"]),
            reverse=True,
        )
        winner = dict(candidates[0])
        winner["alternatives"] = candidates[:5]
        baseline.append(winner)
    return baseline


# ============================================================
# VISUAL SEGMENTATION
# ============================================================

def make_segmentation_mask(image):
    gray = ImageOps.grayscale(image)
    gray = ImageEnhance.Contrast(gray).enhance(1.8)
    arr = np.array(gray)
    mask = (arr < 175).astype(np.uint8)
    height, width = mask.shape
    # row by row, top to bottom, as before: a row's runs are found on the mask AS IT IS
    # NOW (rows above may already have cleared part of it), then long runs are cleared.
    # Clearing only ever shortens runs, so a row with no long run at the start can never
    # get one - only the rows that have one are visited.
    limit = width * 0.25
    for y in np.flatnonzero(longest_run_per_row(mask > 0) > limit):
        starts, ends = row_runs(mask[y] > 0)
        for start, end in zip(starts, ends):
            if end - start > limit:
                mask[max(0, y - 2):min(height, y + 3), start:end] = 0
    return mask


def get_horizontal_gaps(mask):
    active = np.count_nonzero(mask, axis=0) > 1
    gaps = []
    in_gap = False
    start = 0
    for x in range(len(active)):
        if not active[x]:
            if not in_gap:
                start = x
                in_gap = True
        else:
            if in_gap:
                if start > 0:
                    gaps.append({
                        "x0": start,
                        "x1": x - 1,
                        "width": x - start,
                        "center": int((start + x - 1) / 2),
                    })
                in_gap = False
    return gaps


def choose_visual_gap_threshold(gaps, line_height):
    widths = sorted(gap["width"] for gap in gaps if gap["width"] >= 3)
    if not widths:
        return None
    minimum_possible_word_gap = max(4, int(line_height * 0.055))
    widths = [width for width in widths if width >= minimum_possible_word_gap]
    if not widths:
        return None
    if len(widths) == 1:
        return widths[0]

    best_index = None
    best_jump_score = -1.0
    for index in range(len(widths) - 1):
        left = widths[index]
        right = widths[index + 1]
        if left <= 0:
            continue
        ratio = right / left
        absolute_jump = right - left
        score = ratio * (1.0 + absolute_jump / max(line_height, 1))
        if score > best_jump_score:
            best_jump_score = score
            best_index = index

    if best_index is not None and best_jump_score >= 1.30:
        threshold = int(round((widths[best_index] + widths[best_index + 1]) / 2))
    else:
        threshold = int(np.percentile(widths, 65))
    return max(minimum_possible_word_gap, threshold)


def create_independent_visual_chunks(line_image):
    mask = make_segmentation_mask(line_image)
    gaps = get_horizontal_gaps(mask)
    threshold = choose_visual_gap_threshold(gaps, line_image.height)
    if threshold is None:
        return (
            [{"image": trim_to_content(line_image), "x0": 0, "x1": line_image.width}],
            None,
        )

    selected_gaps = [
        gap for gap in gaps
        if gap["width"] >= threshold
        and gap["center"] > line_image.width * 0.02
        and gap["center"] < line_image.width * 0.98
    ]
    selected_gaps.sort(key=lambda gap: gap["center"])

    boundaries = [0] + [gap["center"] for gap in selected_gaps] + [line_image.width]
    boundaries = sorted(set(boundaries))

    chunks = []
    for index in range(len(boundaries) - 1):
        x0 = boundaries[index]
        x1 = boundaries[index + 1]
        if x1 - x0 < 6:
            continue
        crop = line_image.crop((
            max(0, x0 - 3),
            0,
            min(line_image.width, x1 + 3),
            line_image.height,
        ))
        crop = trim_to_content(crop)
        if crop.width < 5 or crop.height < 5:
            continue
        chunks.append({"image": crop, "x0": x0, "x1": x1})
    return chunks, threshold


# ============================================================
# INDIVIDUAL WORD OCR
# ============================================================

def collect_word_attempts(image):
    """
    Four fast Paddle reads first. If they all strongly agree, accept them.
    Otherwise run the full Paddle + EasyOCR battery.
    """
    cache_key = image_cache_key(image)
    if cache_key in WORD_ATTEMPT_CACHE:
        CACHE_STATS["word_attempt_hits"] += 1
        return [dict(attempt) for attempt in WORD_ATTEMPT_CACHE[cache_key]]
    CACHE_STATS["word_attempt_misses"] += 1
    fast_started = time.perf_counter()

    fast_versions = [
        ("Original", image),
        ("T130", make_binary(image, 130)),
        ("RedExcess", make_red_excess_image(image)),
        ("RedMask", make_red_mask_image(image, dilate=False, loose=False)),
    ]
    fast_attempts = []
    fast_reads = paddle_read_text_images(
        [version.resize((version.width * 2, version.height * 2)) for _name, version in fast_versions],
        kind="Notes word pictures")
    for (version_name, version), (raw, confidence) in zip(fast_versions, fast_reads):
        normalized = normalize_token(raw)
        if normalized:
            fast_attempts.append({
                "text": normalized,
                "confidence": confidence,
                "source": "Paddle " + version_name + " x2 FAST",
            })

    fast_groups = defaultdict(list)
    for attempt in fast_attempts:
        fast_groups[attempt["text"]].append(attempt)

    fast_winner = None
    if fast_groups:
        winner_text, winner_entries = max(
            fast_groups.items(),
            key=lambda item: (
                len(item[1]),
                sum(safe_float(entry.get("confidence", 0.0)) for entry in item[1]),
            ),
        )
        winner_count = len(winner_entries)
        usable_count = len(fast_attempts)
        average_confidence = (
            sum(safe_float(entry.get("confidence", 0.0)) for entry in winner_entries)
            / max(1, winner_count)
        )
        best_confidence = max(
            (safe_float(entry.get("confidence", 0.0)) for entry in winner_entries),
            default=0.0,
        )
        if (
            usable_count >= 3
            and winner_count == usable_count
            and average_confidence >= 0.80
            and best_confidence >= 0.90
        ):
            fast_winner = winner_text
    add_work_time("word_fast", time.perf_counter() - fast_started)

    if fast_winner is not None:
        print(
            "      FAST OCR consensus accepted:",
            fast_winner,
            f"({len(fast_attempts)}/4 agreeing)",
        )
        WORD_ATTEMPT_CACHE[cache_key] = [dict(attempt) for attempt in fast_attempts]
        FAST_WORD_ACCEPTED_CACHE[cache_key] = True
        return [dict(attempt) for attempt in fast_attempts]

    full_started = time.perf_counter()

    versions = [("Original", image)]
    for threshold in [100, 115, 130, 145, 160, 175]:
        versions.append((f"T{threshold}", make_binary(image, threshold)))
    versions.extend(create_red_ocr_versions(image))

    attempts = [dict(attempt) for attempt in fast_attempts]
    already_done = {("Original", 2), ("T130", 2), ("RedExcess", 2), ("RedMask", 2)}

    jobs = [(version_name, scale, version.resize((version.width * scale, version.height * scale)))
            for version_name, version in versions for scale in [1, 2]
            if (version_name, scale) not in already_done]
    for (version_name, scale, _picture), (raw, confidence) in zip(
            jobs, paddle_read_text_images([picture for _n, _s, picture in jobs], kind="Notes word pictures")):
        text = normalize_token(raw)
        if text:
            attempts.append({
                "text": text,
                "confidence": confidence,
                "source": "Paddle " + version_name + f" x{scale}",
            })

    easy_names = {
        "Original", "T130", "T160", "RedExcess",
        "RedMask", "RedMaskDilated", "RedMaskLoose",
    }
    easy_jobs = [(version_name, np.array(version.resize((version.width * 2, version.height * 2))))
                 for version_name, version in versions if version_name in easy_names]
    for (version_name, _array), results in zip(easy_jobs, easy_read_arrays([a for _n, a in easy_jobs])):
        if not results:
            continue
        sortable = _easyocr_left_to_right(results)
        if sortable:
            combined_text = "".join(normalize_token(item[1]) for item in sortable)
            combined_confidence = sum(item[2] for item in sortable) / len(sortable)
            if combined_text:
                attempts.append({
                    "text": combined_text,
                    "confidence": combined_confidence,
                    "source": "EasyOCR " + version_name,
                })

    WORD_ATTEMPT_CACHE[cache_key] = [dict(attempt) for attempt in attempts]
    FAST_WORD_ACCEPTED_CACHE[cache_key] = False
    add_work_time("word_full", time.perf_counter() - full_started)
    return [dict(attempt) for attempt in attempts]


def score_word_attempts(attempts, image):
    geometry = estimate_visible_character_count(image)
    empty = {
        "text": "",
        "score": 0.0,
        "exact_votes": 0,
        "similar_votes": 0,
        "confidence": 0.0,
        "agreement": 0.0,
        "length_score": 0.0,
        "visible_length": 0,
        "expected_length": geometry["count"],
        "expected_length_rounded": geometry["rounded"],
        "length_reliability": geometry["reliability"],
        "uses_length": False,
        "alternatives": [],
    }
    if not attempts:
        return empty

    exact_groups = defaultdict(list)
    for attempt in attempts:
        text = normalize_token(attempt.get("text", ""))
        if not text:
            continue
        cleaned = dict(attempt)
        cleaned["text"] = text
        exact_groups[text].append(cleaned)
    if not exact_groups:
        return empty

    clean_attempts = []
    for entries in exact_groups.values():
        clean_attempts.extend(entries)

    candidates = []
    for candidate_text, exact_entries in exact_groups.items():
        similar_entries = [
            attempt for attempt in clean_attempts
            if text_similarity(candidate_text, attempt["text"]) >= 0.74
        ]
        if not similar_entries:
            similar_entries = list(exact_entries)

        exact_votes = len(exact_entries)
        similar_votes = len(similar_entries)
        best_confidence = max(
            safe_float(entry.get("confidence", 0.0)) for entry in exact_entries
        )
        average_confidence = (
            sum(safe_float(entry.get("confidence", 0.0)) for entry in similar_entries)
            / max(similar_votes, 1)
        )
        similarity_values = [
            text_similarity(candidate_text, entry["text"])
            for entry in similar_entries
        ]
        agreement = sum(similarity_values) / max(len(similarity_values), 1)

        use_length = should_use_length_scoring(candidate_text)
        length_score = calculate_length_match_score(candidate_text, geometry)

        score = (
            min(exact_votes / 12.0, 1.0) * 0.29
            + min(similar_votes / 22.0, 1.0) * 0.15
            + agreement * 0.20
            + average_confidence * 0.13
            + best_confidence * 0.04
        )
        if use_length:
            score += length_score * (0.19 * geometry["reliability"])
        else:
            score += 0.10
        if exact_votes == 1:
            score -= 0.08

        candidates.append({
            "text": candidate_text,
            "score": score,
            "exact_votes": exact_votes,
            "similar_votes": similar_votes,
            "confidence": best_confidence,
            "agreement": agreement,
            "length_score": length_score,
            "visible_length": candidate_visible_length(candidate_text),
            "expected_length": geometry["count"],
            "expected_length_rounded": geometry["rounded"],
            "length_reliability": geometry["reliability"] if use_length else 0.0,
            "uses_length": use_length,
        })

    candidates.sort(
        key=lambda item: (
            item["score"],
            item["exact_votes"],
            item["similar_votes"],
            item["confidence"],
        ),
        reverse=True,
    )
    winner = dict(candidates[0])

    alternatives = []
    for text, entries in exact_groups.items():
        alternatives.append({
            "text": text,
            "count": len(entries),
            "confidence": max(safe_float(entry.get("confidence", 0.0)) for entry in entries),
            "length": candidate_visible_length(text),
            "length_score": calculate_length_match_score(text, geometry),
        })
    alternatives.sort(key=lambda item: (item["count"], item["confidence"]), reverse=True)
    winner["alternatives"] = alternatives[:12]
    return winner


def read_word_crop(image):
    image = trim_to_content(image)
    key = image_cache_key(image)
    if key in WORD_OCR_CACHE:
        CACHE_STATS["hits"] += 1
        result = dict(WORD_OCR_CACHE[key])
        result["image"] = image
        result["strong_fast_consensus"] = bool(FAST_WORD_ACCEPTED_CACHE.get(key, False))
        return result

    CACHE_STATS["misses"] += 1
    attempts = collect_word_attempts(image)
    result = score_word_attempts(attempts, image)
    result["image"] = image
    result["strong_fast_consensus"] = bool(FAST_WORD_ACCEPTED_CACHE.get(key, False))
    cached = dict(result)
    cached.pop("image", None)
    WORD_OCR_CACHE[key] = cached
    return result


def visual_chunk_noise_metrics(image):
    """How much red handwriting a proposed visual chunk contains."""
    try:
        mask = make_red_mask_array(image, loose=True)
        red_pixels = int(np.count_nonzero(mask))
        total_pixels = max(1, int(mask.size))
        columns = np.where(np.any(mask > 0, axis=0))[0]
        rows = np.where(np.any(mask > 0, axis=1))[0]
        if len(columns) > 0 and len(rows) > 0:
            content_width = int(columns[-1] - columns[0] + 1)
            content_height = int(rows[-1] - rows[0] + 1)
        else:
            content_width = 0
            content_height = 0
        return {
            "red_pixels": red_pixels,
            "red_ratio": red_pixels / total_pixels,
            "content_width": content_width,
            "content_height": content_height,
        }
    except Exception:
        return {"red_pixels": 0, "red_ratio": 0.0, "content_width": 0, "content_height": 0}


def should_ignore_visual_chunk_as_noise(ocr, metrics):
    """Reject tiny weak chunks before they can change a line."""
    text = str(ocr.get("text", "")).strip()
    score = safe_float(ocr.get("score", 0.0))
    exact_votes = int(ocr.get("exact_votes", 0) or 0)
    similar_votes = int(ocr.get("similar_votes", 0) or 0)
    visible_length = candidate_visible_length(text)
    red_pixels = int(metrics.get("red_pixels", 0))
    content_width = int(metrics.get("content_width", 0))
    content_height = int(metrics.get("content_height", 0))

    if red_pixels < 18 or content_width <= 2 or content_height <= 2:
        return True
    if (
        visible_length <= 1
        and score < 0.66
        and exact_votes < 8
        and similar_votes < 10
    ):
        return True
    if score < 0.58 and exact_votes < 5 and similar_votes < 7:
        return True
    return False


def word_first_guess_for_mixed_visual_chunk(token, image):
    """
    Resolve a letters+digits visual OCR result (e.g. S6AM) as a WORD:
    alphabetic positions preserved, digit positions treated as unknown.
    """
    compact = re.sub(r"[^A-Z0-9]", "", str(token or "").upper())
    if (
        len(compact) < 3
        or not re.search(r"[A-Z]", compact)
        or not re.search(r"[0-9]", compact)
    ):
        return None
    letter_count = len(re.findall(r"[A-Z]", compact))
    digit_count = len(re.findall(r"[0-9]", compact))
    if letter_count < max(2, digit_count * 2):
        return None

    candidates = []
    for word in lazy_english_words(len(compact), mixed_pattern=compact):
        if not re.fullmatch(r"[A-Z]+", word):
            continue
        if any(
            observed.isalpha() and observed != candidate_character
            for observed, candidate_character in zip(compact, word)
        ):
            continue

        physical = candidate_individual_letter_support(word, image)
        whole_profile = build_word_character_profile_from_image(word, image)
        whole_character_values = [
            safe_float(item.get("confidence", 0.0))
            for item in (whole_profile or {}).get("characters", [])
        ]
        whole_support = (
            sum(whole_character_values) / max(len(whole_character_values), 1)
            if whole_character_values else 0.0
        )
        frequency = english_frequency_score(word)
        score = clamp(
            physical.get("score", 0.0) * 0.52
            + whole_support * 0.38
            + frequency * 0.10
        )
        candidates.append({
            "text": word,
            "score": score,
            "physical": physical.get("score", 0.0),
            "whole_support": whole_support,
            "frequency": frequency,
        })

    if not candidates:
        return None
    candidates.sort(
        key=lambda item: (item["score"], item["physical"], item["whole_support"]),
        reverse=True,
    )
    best = candidates[0]
    if best["score"] < 0.46:
        return None
    return {
        "text": best["text"],
        "raw_text": compact,
        "score": best["score"],
        "candidates": candidates[:8],
    }


def ocr_visual_chunks(chunks):
    results = []
    for index, chunk in enumerate(chunks, start=1):
        chunk_started = time.perf_counter()
        print()
        print(f"Reading visual chunk {index}/{len(chunks)}...")
        ocr = read_word_crop(chunk["image"])
        raw_visual_text = normalize_token(ocr.get("text", ""))

        word_first_guess = word_first_guess_for_mixed_visual_chunk(
            raw_visual_text,
            chunk["image"],
        )
        if word_first_guess is not None:
            print(
                "      WORD-FIRST mixed visual OCR:",
                raw_visual_text, "->", word_first_guess["text"],
            )
            print(
                "      Word candidates:",
                " | ".join(
                    f'{item["text"]}:{item["score"]:.3f}'
                    for item in word_first_guess["candidates"]
                ),
            )
            ocr["raw_mixed_text"] = raw_visual_text
            ocr["word_first_candidates"] = word_first_guess["candidates"]
            ocr["text"] = word_first_guess["text"]
            ocr["word_first_mixed_repair"] = True

        metrics = visual_chunk_noise_metrics(chunk["image"])
        ignored_as_noise = should_ignore_visual_chunk_as_noise(ocr, metrics)
        protected_by_fast_consensus = (
            bool(ocr.get("strong_fast_consensus", False))
            and int(metrics.get("red_pixels", 0) or 0) >= 500
            and int(metrics.get("content_width", 0) or 0) >= 3
            and int(metrics.get("content_height", 0) or 0) >= 3
        )
        if ignored_as_noise and protected_by_fast_consensus:
            ignored_as_noise = False
            print("      STRONG FAST OCR CONSENSUS -> chunk protected from noise filter")

        combined = {
            **chunk,
            **ocr,
            **metrics,
            "ignored_as_noise": ignored_as_noise,
            "protected_by_fast_consensus": protected_by_fast_consensus,
        }
        results.append(combined)

        print(
            "   ->", combined["text"],
            "| score=", round(combined["score"], 3),
            "| exact=", combined["exact_votes"],
            "| similar=", combined["similar_votes"],
            "| rough expected=", round(combined.get("expected_length", 0.0), 2),
        )
        if ignored_as_noise:
            print(
                "      IGNORED AS LOW-CONTENT / LOW-CONFIDENCE NOISE",
                "| red pixels=", combined.get("red_pixels", 0),
            )
        record_timing(
            f"Visual chunk {index}/{len(chunks)} -> {combined['text']}",
            time.perf_counter() - chunk_started, 4,
        )
    return results


# ============================================================
# ALIGNMENT
# ============================================================

def baseline_group_text(baseline_tokens):
    return " ".join(token["text"] for token in baseline_tokens)


def visual_group_text(visual_chunks):
    return " ".join(chunk["text"] for chunk in visual_chunks)


def visual_group_concat(visual_chunks):
    return "".join(chunk["text"] for chunk in visual_chunks)


def choose_visual_group_spacing(visual_chunks):
    """
    Preserve physical spaces found by the visual chunker unless the chunks are
    clearly fragments of one English word (GEO + METRIC -> GEOMETRIC).
    """
    if not visual_chunks:
        return "", False
    if len(visual_chunks) == 1:
        return visual_chunks[0]["text"], False

    spaced = visual_group_text(visual_chunks)
    joined = visual_group_concat(visual_chunks)

    alpha_parts = []
    for chunk in visual_chunks:
        letters = re.sub(r"[^A-Za-z]", "", chunk["text"]).upper()
        if letters:
            alpha_parts.append(letters)
    joined_letters = "".join(alpha_parts)

    contains_nonletters = any(
        re.search(r"[^A-Za-z]", chunk["text"]) is not None
        for chunk in visual_chunks
    )
    if contains_nonletters:
        return spaced, True

    joined_is_word = is_general_english_word(joined_letters)
    each_part_is_word = bool(alpha_parts) and all(
        is_general_english_word(part) for part in alpha_parts
    )
    if joined_is_word and not each_part_is_word:
        return joined, False
    return spaced, True


def calculate_alignment_match_score(baseline_group, visual_group):
    baseline_text = baseline_group_text(baseline_group)
    visual_text = visual_group_text(visual_group)
    visual_concat = visual_group_concat(visual_group)
    similarity = max(
        text_similarity(baseline_text, visual_text),
        text_similarity(baseline_text, visual_concat),
    )
    visual_quality = sum(chunk["score"] for chunk in visual_group) / max(len(visual_group), 1)
    visual_agreement = sum(chunk["agreement"] for chunk in visual_group) / max(len(visual_group), 1)
    baseline_quality = sum(token["score"] for token in baseline_group) / max(len(baseline_group), 1)
    grouping_penalty = abs(len(baseline_group) - len(visual_group)) * 0.035
    complexity_penalty = (len(baseline_group) + len(visual_group) - 2) * 0.012
    score = (
        similarity * 0.54
        + visual_quality * 0.19
        + visual_agreement * 0.12
        + baseline_quality * 0.15
        - grouping_penalty
        - complexity_penalty
    )
    return {
        "score": score,
        "similarity": similarity,
        "visual_quality": visual_quality,
        "visual_agreement": visual_agreement,
        "baseline_quality": baseline_quality,
    }


def dynamically_align_sequences(baseline_tokens, visual_chunks):
    n = len(baseline_tokens)
    m = len(visual_chunks)
    negative_infinity = -1e9
    dp = [[negative_infinity for _ in range(m + 1)] for _ in range(n + 1)]
    previous = [[None for _ in range(m + 1)] for _ in range(n + 1)]
    dp[0][0] = 0.0

    for i in range(n + 1):
        for j in range(m + 1):
            if dp[i][j] <= negative_infinity / 2:
                continue
            for baseline_count in range(1, MAX_ALIGNMENT_GROUP + 1):
                for visual_count in range(1, MAX_ALIGNMENT_GROUP + 1):
                    if i + baseline_count > n or j + visual_count > m:
                        continue
                    match = calculate_alignment_match_score(
                        baseline_tokens[i:i + baseline_count],
                        visual_chunks[j:j + visual_count],
                    )
                    new_score = dp[i][j] + match["score"]
                    ni = i + baseline_count
                    nj = j + visual_count
                    if new_score > dp[ni][nj]:
                        dp[ni][nj] = new_score
                        previous[ni][nj] = {
                            "from_i": i, "from_j": j,
                            "match": match, "type": "match",
                        }
            if i < n:
                score = dp[i][j] - 0.45
                if score > dp[i + 1][j]:
                    dp[i + 1][j] = score
                    previous[i + 1][j] = {
                        "from_i": i, "from_j": j,
                        "match": None, "type": "baseline_only",
                    }
            if j < m:
                score = dp[i][j] - 0.45
                if score > dp[i][j + 1]:
                    dp[i][j + 1] = score
                    previous[i][j + 1] = {
                        "from_i": i, "from_j": j,
                        "match": None, "type": "visual_only",
                    }

    alignment = []
    i = n
    j = m
    while i > 0 or j > 0:
        step = previous[i][j]
        if step is None:
            if i > 0 and j > 0:
                step = {
                    "from_i": i - 1, "from_j": j - 1,
                    "match": calculate_alignment_match_score(
                        baseline_tokens[i - 1:i],
                        visual_chunks[j - 1:j],
                    ),
                    "type": "match",
                }
            elif i > 0:
                step = {"from_i": i - 1, "from_j": j, "match": None, "type": "baseline_only"}
            else:
                step = {"from_i": i, "from_j": j - 1, "match": None, "type": "visual_only"}
        from_i = step["from_i"]
        from_j = step["from_j"]
        alignment.append({
            "type": step["type"],
            "baseline": baseline_tokens[from_i:i],
            "visual": visual_chunks[from_j:j],
            "match": step["match"],
        })
        i = from_i
        j = from_j
    alignment.reverse()
    return alignment


# ============================================================
# MULTI-WORD VISUAL SPLITTING
# ============================================================

def split_chunk_into_n_parts(image, part_count):
    if part_count <= 1:
        return [trim_to_content(image)]
    mask = make_segmentation_mask(image)
    gaps = get_horizontal_gaps(mask)
    usable = [
        gap for gap in gaps
        if gap["width"] >= max(4, int(image.height * 0.045))
        and gap["center"] > image.width * 0.05
        and gap["center"] < image.width * 0.95
    ]
    usable.sort(key=lambda gap: gap["width"], reverse=True)
    selected = usable[:part_count - 1]
    if len(selected) < part_count - 1:
        return None
    selected.sort(key=lambda gap: gap["center"])
    boundaries = [0] + [gap["center"] for gap in selected] + [image.width]

    pieces = []
    for index in range(part_count):
        x0 = boundaries[index]
        x1 = boundaries[index + 1]
        crop = image.crop((max(0, x0 - 3), 0, min(image.width, x1 + 3), image.height))
        pieces.append(trim_to_content(crop))
    return pieces


def refine_multi_baseline_single_visual(baseline_group, visual_chunk):
    pieces = split_chunk_into_n_parts(visual_chunk["image"], len(baseline_group))
    if pieces is None:
        return None
    piece_results = [read_word_crop(piece) for piece in pieces]
    combined_visual_text = " ".join(result["text"] for result in piece_results)
    similarity = text_similarity(baseline_group_text(baseline_group), combined_visual_text)
    average_score = sum(result["score"] for result in piece_results) / max(len(piece_results), 1)
    average_agreement = sum(result["agreement"] for result in piece_results) / max(len(piece_results), 1)
    score = average_score * 0.43 + average_agreement * 0.22 + similarity * 0.35
    return {
        "text": combined_visual_text,
        "pieces": piece_results,
        "score": score,
        "similarity": similarity,
        "image": visual_chunk["image"],
    }


# ============================================================
# INITIAL DECISION LOGIC
# ============================================================

def individual_result_is_very_strong(visual):
    return (
        visual.get("exact_votes", 0) >= 8
        and visual.get("similar_votes", 0) >= 12
        and visual.get("agreement", 0.0) >= 0.90
    )


def _decision(text, source, baseline_group, visual_group, refinement=None):
    return {
        "text": text,
        "source": source,
        "baseline": baseline_group,
        "visual": visual_group,
        "refinement": refinement,
    }


def choose_aligned_group_output(alignment_item):
    baseline_group = alignment_item["baseline"]
    visual_group = alignment_item["visual"]
    item_type = alignment_item["type"]
    baseline_text = baseline_group_text(baseline_group)

    if item_type == "baseline_only":
        return _decision(baseline_text, "Baseline only", baseline_group, visual_group)
    if item_type == "visual_only":
        return _decision(visual_group_text(visual_group), "Visual only", baseline_group, visual_group)

    match = alignment_item["match"]
    visual_text = visual_group_text(visual_group)
    visual_concat = visual_group_concat(visual_group)
    visual_replacement_text, visual_spacing_preserved = choose_visual_group_spacing(visual_group)

    # One baseline token, several visual chunks.
    if len(baseline_group) == 1 and len(visual_group) > 1:
        baseline = baseline_group[0]
        if normalize_for_matching(baseline["text"]) == normalize_for_matching(visual_concat):
            return _decision(
                visual_replacement_text,
                "Visual pieces confirm baseline; physical spacing preserved"
                if visual_spacing_preserved else "Visual pieces confirm baseline",
                baseline_group, visual_group,
            )
        visual_score = sum(chunk["score"] for chunk in visual_group) / len(visual_group)
        if visual_score > baseline["score"] + 0.05:
            return _decision(
                visual_replacement_text,
                "Multiple visual chunks replaced baseline; physical spacing preserved"
                if visual_spacing_preserved else "Multiple visual chunks replaced baseline",
                baseline_group, visual_group,
            )
        return _decision(baseline["text"], "Baseline retained", baseline_group, visual_group)

    # Several baseline tokens, one visual chunk.
    if len(baseline_group) > 1 and len(visual_group) == 1:
        refinement = refine_multi_baseline_single_visual(baseline_group, visual_group[0])
        if refinement is not None:
            baseline_score = sum(token["score"] for token in baseline_group) / len(baseline_group)
            if (
                refinement["score"] > baseline_score + 0.02
                or (
                    refinement["similarity"] >= 0.68
                    and refinement["score"] >= baseline_score - 0.04
                )
            ):
                return _decision(
                    refinement["text"],
                    "Split visual crop replaced baseline group",
                    baseline_group, visual_group, refinement,
                )
        return _decision(baseline_text, "Baseline group retained", baseline_group, visual_group, refinement)

    # One-to-one.
    if len(baseline_group) == 1 and len(visual_group) == 1:
        baseline = baseline_group[0]
        visual = visual_group[0]
        if normalize_for_matching(baseline["text"]) == normalize_for_matching(visual["text"]):
            return _decision(visual["text"], "Baseline + visual agree", baseline_group, visual_group)

        if individual_result_is_very_strong(visual):
            if visual.get("uses_length", False):
                expected = visual.get("expected_length", candidate_visible_length(visual["text"]))
                baseline_error = abs(candidate_visible_length(baseline["text"]) - expected)
                visual_error = abs(candidate_visible_length(visual["text"]) - expected)
                if visual_error + 0.30 < baseline_error:
                    return _decision(
                        visual["text"],
                        "Strong visual replacement + visible character length",
                        baseline_group, visual_group,
                    )
            if visual["score"] >= baseline["score"] - 0.03:
                return _decision(
                    visual["text"],
                    "Strong visual consensus replacement",
                    baseline_group, visual_group,
                )

        if (
            visual["exact_votes"] >= 4
            and visual["agreement"] >= 0.80
            and visual["score"] >= baseline["score"] + 0.03
        ):
            return _decision(visual["text"], "Individual visual replacement", baseline_group, visual_group)

        return _decision(baseline["text"], "Baseline retained", baseline_group, visual_group)

    # Many-to-many.
    visual_score = sum(chunk["score"] for chunk in visual_group) / max(len(visual_group), 1)
    baseline_score = sum(token["score"] for token in baseline_group) / max(len(baseline_group), 1)
    if visual_score > baseline_score + 0.05 and match["similarity"] >= 0.58:
        return _decision(visual_text, "Visual group replacement", baseline_group, visual_group)
    return _decision(baseline_text, "Baseline group retained", baseline_group, visual_group)


# ============================================================
# OCR CHARACTER-LENGTH CONSENSUS
# ============================================================

def add_length_vote(votes, text, weight):
    text = normalize_alpha_for_matching(text)
    if not text:
        return
    votes[len(text)] += max(0.01, float(weight))


def get_piece_ocr_evidence(piece):
    evidence = []
    text = normalize_alpha_for_matching(piece.get("text", ""))
    if text:
        evidence.append((text, max(0.75, piece.get("score", 0.0))))
    for alternative in piece.get("alternatives", []):
        alt = normalize_alpha_for_matching(alternative.get("text", ""))
        if not alt:
            continue
        vote_weight = min(alternative.get("count", 1) / 10.0, 1.0)
        confidence_weight = alternative.get("confidence", 0.0)
        evidence.append((alt, vote_weight * 0.60 + confidence_weight * 0.40))
    return evidence


def consensus_ocr_word_length(current_word, evidence):
    votes = defaultdict(float)
    current_word = normalize_alpha_for_matching(current_word)
    if current_word:
        add_length_vote(votes, current_word, 1.25)
    for observed, weight in evidence:
        add_length_vote(votes, observed, weight)
    if not votes:
        return len(current_word)
    ordered = sorted(
        votes.items(),
        key=lambda item: (item[1], -abs(item[0] - len(current_word))),
        reverse=True,
    )
    return ordered[0][0]


# ============================================================
# SPLIT DECISION INTO WORD UNITS
# ============================================================

# ============================================================
# WHOLE-LINE READS OF THE CURRENT NOTES LINE (shared by the word checks)
# ============================================================
LINE_WHOLE_READ_TOKENS = []            # one list of letter-words per whole-line read
WHOLE_LINE_AGREEMENT_MIN_SHARE = 0.50  # C: this share of reads spelling the word = certain
WHOLE_LINE_AGREEMENT_MIN_READS = 4


WORD_IMAGE_MESSAGES_PRINTED = set()   # WORD IMAGE line printed once per group per Notes line



# ============================================================
# WHOLE-LINE CONSENSUS (all whole-line reads combined, at the start)
# ============================================================
# The 14-16 whole-line reads usually already agree on most of the line. They
# are lined up token by token and combined:
#   - numbers: look-alikes fixed (O->0, I/l->1) and voted ('69.0%', '5:45');
#     a lone '%' joins the number before it
#   - words: exact majority, or the English word that best fits ALL the reads
#     (EXTENAL / EXTERNAL / EXENA -> EXTERNAL)
#   - a single mark just before a time is the '@' ('C 5:45' -> '@ 5:45')
#   - a leading single letter followed by ')' or '.' in some reads is
#     evidence of a bullet ('A)69.O%')
# Confident consensus words are settled before any image reads; the bullet
# evidence is used when the circle test cannot confirm a circled mark.
LINE_CONSENSUS = {}
CONSENSUS_TOKEN = re.compile(r"\d[\dOoIl.,:]*%?|[A-Za-z][A-Za-z0-9]*[A-Za-z]:?|[A-Za-z][).]?|%|\S")
CONSENSUS_MIN_SLOT_SUPPORT = 0.40   # a slot must have a token in at least this share of reads
CONSENSUS_WORD_MIN_FIT = 0.80        # fitted word must match the reads this well on average
CONSENSUS_WORD_MIN_MARGIN = 0.10     # ... and beat the next word by this much
CONSENSUS_AT_LOOKALIKES = {"C", "E", "@", "G", "O", "2", "Q"}


TIME_AROUND_COLON = re.compile(r"(?<![A-Za-z0-9])([0-9Oo]{1,2})\s*:\s*([0-9Oo]{2})(?![A-Za-z0-9])")


def normalize_times_around_colons(text):
    """A colon with at most 2 digits on each side is a time; letter O next to it
    is a zero: 'O:37' -> '0:37', 'OO:37' -> '00:37', '5 : 45' -> '5:45'."""
    return TIME_AROUND_COLON.sub(
        lambda m: m.group(1).translate(str.maketrans("Oo", "00")) + ":" + m.group(2).translate(str.maketrans("Oo", "00")),
        str(text or ""),
    )


def same_clock_time(a, b):
    """'0:37' and '00:37' are the same time."""
    match_a = re.fullmatch(r"\s*(\d{1,2}):(\d{2})\s*", str(a))
    match_b = re.fullmatch(r"\s*(\d{1,2}):(\d{2})\s*", str(b))
    return bool(match_a and match_b) and (int(match_a.group(1)), match_a.group(2)) == (int(match_b.group(1)), match_b.group(2))


def consensus_tokens(text):
    tokens = []
    for token in CONSENSUS_TOKEN.findall(normalize_times_around_colons(text)):
        if token == "%" and tokens and re.match(r"\d", tokens[-1]) and not tokens[-1].endswith("%"):
            tokens[-1] += "%"                       # '69.O %' -> '69.O%'
            continue
        if token == "(":
            continue
        tokens.append(token)
    return tokens


def consensus_key(token):
    token = str(token).upper()
    if re.match(r"\d", token):
        return token.translate(str.maketrans({"O": "0", "I": "1", "L": "1"}))
    return re.sub(r"[^A-Z0-9@%]", "", token)


def consensus_similarity(a, b):
    raw_a, raw_b = str(a).strip(), str(b).strip()
    a, b = consensus_key(a), consensus_key(b)
    if not a or not b:
        return 1.0 if raw_a and raw_a == raw_b else 0.0
    return SequenceMatcher(None, a, b, autojunk=False).ratio()


def align_tokens_to_reference(reference, tokens, inserts=None):
    """reference index -> aligned token (or None), best total similarity.
    inserts (a list) collects tokens with no reference partner as (index, token):
    the token sits just before reference position 'index'."""
    n, m = len(reference), len(tokens)
    score = [[0.0] * (m + 1) for _ in range(n + 1)]
    move = [[None] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        move[i][0] = "up"
    for j in range(1, m + 1):
        move[0][j] = "left"
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            match = score[i - 1][j - 1] + consensus_similarity(reference[i - 1], tokens[j - 1]) - 0.3
            options = [(match, "diag"), (score[i - 1][j], "up"), (score[i][j - 1], "left")]
            score[i][j], move[i][j] = max(options, key=lambda item: item[0])
    aligned = [None] * n
    i, j = n, m
    while i > 0 or j > 0:
        step = move[i][j]
        if step == "diag":
            aligned[i - 1] = tokens[j - 1]
            i, j = i - 1, j - 1
        elif step == "up":
            i -= 1
        else:
            if inserts is not None:
                inserts.append((i, tokens[j - 1]))
            j -= 1
    return aligned


PATTERN_KEEP_SHARE = 0.60      # a character is KEPT unless its agreement is low (below this share)
PATTERN_FILL_SHARE = 0.40      # a '?' is FILLED when this share of the reads agree on it ...
PATTERN_FILL_LEAD = 0.15       # ... and it leads the next character by at least this much
PATTERN_LONGER_MIN_SHARE = 0.10  # a longer spelling given by this share of reads adds '?' positions


def pattern_variant_text(token, kind):
    if kind == "word":
        return re.sub(r"[^A-Z]", "", str(token).upper())
    if kind == "mark":
        compact = re.sub(r"\s+", "", str(token))
        return (re.sub(r"[^A-Za-z0-9@]", "", compact).upper()[:1] or compact[:1])
    return consensus_key(token)


def slot_character_pattern(variants, kind):
    """
    Character-by-character agreement of every read in one slot.
    pattern: character kept where >= PATTERN_KEEP_SHARE of the reads have it, else '?'
    filled : '?' replaced by the character >= PATTERN_FILL_SHARE of the reads have there
    options: per '?' position, the characters the reads offer (most common first)
    The reference length is the longest reading that at least 20% of reads give.
    """
    texts = [pattern_variant_text(token, kind) for token, _ in variants]
    texts = [t for t in texts if t]
    if not texts:
        return None
    counts = {}
    for text in texts:
        counts[text] = counts.get(text, 0) + 1
    supported = [t for t in counts if counts[t] / len(texts) >= PATTERN_LONGER_MIN_SHARE] or list(counts)
    reference = max(supported, key=lambda t: (len(t), counts[t]))
    columns = [dict() for _ in reference]
    for text in texts:
        matcher = SequenceMatcher(None, reference, text, autojunk=False)
        for tag, i1, i2, j1, j2 in matcher.get_opcodes():
            if tag == "equal" or (tag == "replace" and i2 - i1 == j2 - j1):
                for offset in range(i2 - i1):
                    character = text[j1 + offset]
                    columns[i1 + offset][character] = columns[i1 + offset].get(character, 0) + 1
    pattern, filled, options, optional, optional_letters = [], [], [], [], []
    for position, column in enumerate(columns):
        coverage = sum(column.values()) / len(texts)
        ranked = sorted(column.items(), key=lambda item: -item[1])
        top, top_count = ranked[0] if ranked else ("?", 0)
        if coverage < 0.5:
            optional.append(position)      # only some reads have a character here
            optional_letters.append((position, top, top_count / len(texts)))
        share = top_count / len(texts)
        second_share = ranked[1][1] / len(texts) if len(ranked) > 1 else 0.0
        pattern.append(top if share >= PATTERN_KEEP_SHARE else "?")
        filled.append(
            top if share >= PATTERN_KEEP_SHARE
            or (share >= PATTERN_FILL_SHARE and share - second_share >= PATTERN_FILL_LEAD)
            else "?"
        )
        if share < PATTERN_KEEP_SHARE:
            options.append([(c, n / len(texts)) for c, n in ranked[:3]])
    for position in optional:
        pattern[position] = "?"             # possible missing letter -> must be looked into
    return {"pattern": "".join(pattern), "filled": "".join(filled), "options": options,
            "reads": len(texts), "optional": optional, "optional_letters": optional_letters}


def optional_letter_decision(char_pattern):
    """
    A position only SOME reads see (LOS vs LOSS -> 'LOS?'). With one such
    position and no other '?':
      - the word WITH the letter the reads show there is English and the word
        WITHOUT it is not  -> really high confidence -> letter inserted
      - both are English     -> left open for the N+1 / context check
    """
    pattern = char_pattern["pattern"]
    letters = char_pattern.get("optional_letters") or []
    if len(letters) != 1:
        return None, "several possible extra letters -> left open"
    position, letter, share = letters[0]
    without = pattern[:position] + pattern[position + 1:]
    if "?" in without:
        return None, "other letters also uncertain -> left open"
    with_letter = without[:position] + letter + without[position:]
    with_english = zipf_frequency(with_letter.lower(), "en") >= 2.5
    without_english = zipf_frequency(without.lower(), "en") >= 2.5
    if with_english and not without_english:
        return with_letter, (f"{without}? -> {with_letter} is English, {without} is not -> "
                             f"'{letter}' inserted ({share:.0%} of reads show it)")
    if with_english and without_english:
        return None, (f"{without}? -> both {with_letter} and {without} are English -> "
                      "left open for the N+1 / context check")
    return None, f"{without}? -> {with_letter} is not English -> not inserted"


def english_words_one_longer(pattern):
    """Common English words one letter longer than a pattern, with the extra
    letter anywhere: '??ERNA?' -> EXTERNAL, INTERNAL, MATERNAL ..."""
    found = []
    for position in range(len(pattern) + 1):
        longer = pattern[:position] + "?" + pattern[position:]
        for word in lazy_english_words(len(longer), mixed_pattern=longer):
            if zipf_frequency(word.lower(), "en") >= 2.5 and word not in found:
                found.append(word)
    return found


def english_words_for_pattern(pattern, optional=None):
    """Common English words that fit a word pattern ('ME?AL' -> METAL, ...).
    Optional positions (only some reads have a letter there) are tried both
    filled and left out: 'LOS?' -> LOSS, LOST, LOSE ... and LOS."""
    import itertools
    if not pattern:
        return []
    optional = list(optional or [])
    variants = []
    for count in range(len(optional) + 1):
        for removed in itertools.combinations(optional, count):
            variants.append("".join(c for i, c in enumerate(pattern) if i not in removed))
    found = []
    for variant in variants:
        if not variant:
            continue
        if "?" in variant:
            words = lazy_english_words(len(variant), mixed_pattern=variant)
        else:
            words = [variant]
        for word in words:
            if zipf_frequency(word.lower(), "en") >= 2.5 and word not in found:
                found.append(word)
    return found


CONSENSUS_SUSPECT_ZIPF = 4.0      # a short consensus word rarer than this is looked into
CONSENSUS_SUSPECT_MAX_LEN = 4
DIGIT_LETTER_SWAP = {"0": "O", "1": "I", "2": "Z", "3": "E", "4": "A", "5": "S",
                     "6": "G", "7": "T", "8": "B", "9": "G"}


def digit_swap_candidates(word, variants):
    """
    Words built from the consensus word plus a letter that other reads show as
    a look-alike digit, put where those reads have it:
    DIS + 'N6S' (6->G, just before the S) -> DIGS.
    Returns {candidate: 'N6S (6->G)'}.
    """
    found = {}
    for token in variants:
        raw = re.sub(r"[^A-Za-z0-9]", "", str(token)).upper()
        if not re.search(r"\d", raw) or not re.search(r"[A-Z]", raw):
            continue
        swapped = "".join(DIGIT_LETTER_SWAP.get(c, c) for c in raw)
        for k, character in enumerate(raw):
            if not character.isdigit():
                continue
            letter = swapped[k]
            before = swapped[k - 1] if k > 0 else None
            after = swapped[k + 1] if k + 1 < len(swapped) else None
            for position in range(len(word) + 1):                    # inserted letter (N+1)
                if (after and position < len(word) and word[position] == after) or \
                        (before and position > 0 and word[position - 1] == before):
                    anchor = f"'{after}' lines up with {word}'s '{after}'" if (
                        after and position < len(word) and word[position] == after
                    ) else f"'{before}' lines up with {word}'s '{before}'"
                    candidate = word[:position] + letter + word[position:]
                    found.setdefault(candidate, (
                        f"{raw}: {anchor}, the rest of {raw} sits where {word[:position] or word} is, "
                        f"and '{character}' has no partner in {word} -> an extra letter (N+1): "
                        f"{character}->{letter} -> {candidate}"
                    ))
            for position in range(len(word)):                        # replaced letter (same length)
                if (after and position + 1 < len(word) and word[position + 1] == after) or \
                        (before and position > 0 and word[position - 1] == before):
                    candidate = word[:position] + letter + word[position + 1:]
                    found.setdefault(candidate, f"{raw}: {character}->{letter} replaces a letter -> {candidate}")
    return {
        candidate: label for candidate, label in found.items()
        if candidate != word and zipf_frequency(candidate.lower(), "en") >= 2.5
    }


CONSENSUS_OPTIONAL_LM_MARGIN = 0.30   # the word WITH the letter must read this much more naturally
CONSENSUS_SUSPECT_LM_TOLERANCE = 0.30 # a read-supported word is refused only if it reads this much WORSE


def review_optional_letter_context(resolved):
    """
    'LOS?' where both LOSS and LOS are English: the reads (36%) show the extra
    letter, so context decides. Uses the language model on the confident
    neighbouring words ('METAL LOSS' vs 'METAL LOS'); the word with the letter is
    used only when it reads clearly more naturally. Otherwise it stays open.
    """
    words = [e for e in resolved if e["type"] == "word"]
    for index, entry in enumerate(words):
        if entry.get("optional_inserted") or "both" not in str(entry.get("optional_note", "")):
            continue
        char_pattern = entry.get("char_pattern") or {}
        letters = char_pattern.get("optional_letters") or []
        if len(letters) != 1:
            continue
        position, letter, share = letters[0]
        pattern = char_pattern.get("pattern", "")
        without = pattern[:position] + pattern[position + 1:]
        if "?" in without:
            continue
        with_letter = without[:position] + letter + without[position:]
        left = [w["text"] for w in words[max(0, index - 2):index] if consensus_entry_confident(w)]
        right = [w["text"] for w in words[index + 1:index + 3] if consensus_entry_confident(w)]
        if not left and not right:
            continue
        with_score = contextual_sentence_log_probability(" ".join(left + [with_letter] + right).lower())
        without_score = contextual_sentence_log_probability(" ".join(left + [without] + right).lower())
        if with_score is None or without_score is None:
            continue
        phrase_with = " ".join(left + [with_letter] + right)
        phrase_without = " ".join(left + [without] + right)
        if with_score >= without_score + CONSENSUS_OPTIONAL_LM_MARGIN:
            entry.update(text=with_letter, fit=1.0, margin=1.0, optional_inserted=True,
                         method=(f"{without}? -> '{phrase_with}' ({with_score:.2f}) reads clearly better than "
                                 f"'{phrase_without}' ({without_score:.2f}), {share:.0%} of reads show '{letter}' "
                                 f"-> {with_letter}"))
        else:
            entry["review_reason"] = (f"context: '{phrase_with}' {with_score:.2f} vs '{phrase_without}' "
                                      f"{without_score:.2f} -> not clear enough, left for the image checks")


CONSENSUS_CHOICE_MAX_WORDS = 3        # only a small set of pattern words is judged this way
CONSENSUS_SEEN_POSITION_SHARE = 0.30  # a letter position this share of reads show must not be thrown away


def review_pattern_choice_context(resolved):
    """
    Several English words fit a word's pattern (E?TE?NAL -> EXTERNAL, ETERNAL).
    Decided by the READS, never by the language model alone:
      a word that throws away a letter position at least 30% of the reads show
      (the '?' in E?TE...) is ruled out when another fitting word keeps it.
    If that leaves exactly one word, it is used; otherwise the word stays open
    for the image checks.
    """
    for entry in resolved:
        if entry["type"] != "word" or consensus_entry_confident(entry):
            continue
        if "both" in str(entry.get("optional_note", "")):
            continue                                     # LOS? is handled by its own rule
        fits = list(entry.get("pattern_words") or [])
        if not 2 <= len(fits) <= CONSENSUS_CHOICE_MAX_WORDS:
            continue
        char_pattern = entry.get("char_pattern") or {}
        pattern = char_pattern.get("pattern", "")
        seen = [(p, letter, share) for p, letter, share in (char_pattern.get("optional_letters") or [])
                if share >= CONSENSUS_SEEN_POSITION_SHARE]
        if not seen or not pattern:
            entry["review_reason"] = f"{', '.join(fits)} all fit and the reads do not rule any out -> left for the image checks"
            continue
        keepers = [w for w in fits if len(w) >= len(pattern)]      # keep every seen position (or add one)
        dropped = [w for w in fits if len(w) < len(pattern)]
        seen_text = ", ".join(f"position {p + 1} ('{letter}' in {share:.0%} of reads)" for p, letter, share in seen)
        if len(keepers) == 1:
            entry.update(text=keepers[0], fit=1.0, margin=1.0, evidence_choice=True,
                         method=(f"{pattern} fits {', '.join(fits)} | the reads show a letter at {seen_text} | "
                                 f"{', '.join(dropped) or '-'} would throw it away -> {keepers[0]}"))
        else:
            entry["review_reason"] = (f"the reads show a letter at {seen_text}, but "
                                      f"{len(keepers)} words keep it ({', '.join(keepers) or 'none'}) -> left for the image checks")


def review_suspect_consensus_words(resolved):
    """
    A short, rare consensus word (DIS) is not trusted as is:
      1. other reads with look-alike digits (N6S: 6->G) -> English words
      2. the one that fits the neighbouring words at least as well is used
      3. nothing fits -> the word is left open ('?') for the image checks
    """
    words = [e for e in resolved if e["type"] == "word"]
    for index, entry in enumerate(words):
        word = entry["text"]
        if len(word) > CONSENSUS_SUSPECT_MAX_LEN or not consensus_entry_confident(entry):
            continue
        frequency = zipf_frequency(word.lower(), "en")
        if frequency >= CONSENSUS_SUSPECT_ZIPF:
            continue
        # context is judged by the language model on the confident neighbouring
        # words (word frequency alone would always prefer the commoner word)
        left = [w["text"] for w in words[max(0, index - 2):index] if consensus_entry_confident(w)]
        right = [w["text"] for w in words[index + 1:index + 3] if consensus_entry_confident(w)]
        digit_reads = sorted({
            re.sub(r"[^A-Za-z0-9]", "", str(t)).upper() for t in entry.get("variants") or []
            if re.search(r"\d", str(t)) and re.search(r"[A-Za-z]", str(t))
        })
        candidates = digit_swap_candidates(word, entry.get("variants") or [])
        options, rejected = [], []
        current_score = None
        if candidates and (left or right):
            current_phrase = " ".join(left + [word] + right)
            current_score = contextual_sentence_log_probability(current_phrase.lower())
            for candidate, label in candidates.items():
                phrase = " ".join(left + [candidate] + right)
                score = contextual_sentence_log_probability(phrase.lower())
                if score is None or current_score is None:
                    rejected.append(f"{candidate} (language model unavailable)")
                elif score >= current_score - CONSENSUS_SUSPECT_LM_TOLERANCE:
                    # the reads already show the letter (and the majority letters stay), so
                    # context only has to not speak clearly against it
                    options.append((score, candidate, label, phrase))
                else:
                    rejected.append(f"'{phrase}' {score:.2f} reads clearly worse than '{current_phrase}' "
                                    f"{current_score:.2f}")
        elif candidates:
            rejected.append("no confident neighbouring words to judge context")
        if options:
            options.sort(reverse=True)
            score, candidate, label, phrase = options[0]
            share = entry.get("exact_share")
            majority = f"{word} in {share:.0%} of reads (N={len(word)})" if share else word
            entry.update(text=candidate, fit=1.0, margin=1.0, digit_evidence=True,
                         method=(f"{majority}, rare here (freq {frequency:.1f}) | {label} | context: "
                                 f"'{phrase}' {score:.2f} vs '{' '.join(left + [word] + right)}' "
                                 f"{current_score:.2f} -> not against it -> {candidate}"))
        else:
            if not digit_reads:
                why = "no read of this word has a look-alike digit"
            elif not candidates:
                why = f"reads with digits ({', '.join(digit_reads)}) give no English word"
            else:
                why = f"reads with digits ({', '.join(digit_reads)}) give {'; '.join(rejected)}"
            entry.update(fit=0.0, margin=0.0,
                         review_reason=f"{word} is rare here (freq {frequency:.1f}); {why} -> left for the image checks")


def consensus_slot_type(variants):
    kinds = {}
    for token, weight in variants:
        key = consensus_key(token)
        if re.fullmatch(r"\d{1,2}:\d{2}", key):
            kind = "time"
        elif re.match(r"\d", key):
            kind = "number"
        elif len(re.sub(r"[^A-Z]", "", key)) >= 2:
            kind = "word"
        else:
            kind = "mark"
        kinds[kind] = kinds.get(kind, 0.0) + weight
    return max(kinds.items(), key=lambda item: item[1])[0]


def resolve_consensus_word(variants, candidate_words=None):
    """candidate_words: the words to score (pattern-fitting words); no word-list scan."""
    total = sum(w for _, w in variants) or 1.0
    exact = {}
    for token, weight in variants:
        word = re.sub(r"[^A-Z]", "", str(token).upper())
        if len(word) >= 2:
            exact[word] = exact.get(word, 0.0) + weight
    if not exact:
        return None
    best_exact, best_weight = max(exact.items(), key=lambda item: item[1])
    share = best_weight / total
    if share >= 0.5 and zipf_frequency(best_exact.lower(), "en") >= 2.3:
        return {"text": best_exact, "fit": 1.0, "margin": 1.0, "exact_share": share,
                "method": f"exact in {share:.0%} of reads"}
    candidates = set(candidate_words or [])
    candidates.update(w for w in exact if zipf_frequency(w.lower(), "en") >= 2.5)
    scored = []
    for candidate in candidates:
        fit = sum(
            weight * SequenceMatcher(None, candidate, re.sub(r"[^A-Z]", "", str(token).upper()), autojunk=False).ratio()
            for token, weight in variants
        ) / total
        scored.append((fit, candidate))
    if not scored:
        return {"text": best_exact, "fit": share, "margin": 0.0, "method": "no English word fits"}
    scored.sort(reverse=True)
    fit, word = scored[0]
    margin = fit - (scored[1][0] if len(scored) > 1 else 0.0)
    return {"text": word, "fit": fit, "margin": margin,
            "method": f"best fit to all reads ({fit:.2f}, next {scored[1][1] if len(scored) > 1 else '-'} "
                      f"{scored[1][0] if len(scored) > 1 else 0:.2f})"}


def build_whole_line_consensus(whole_attempts):
    reads = []
    for attempt in whole_attempts or []:
        tokens = consensus_tokens(attempt.get("text", ""))
        if tokens:
            reads.append((tokens, safe_float(attempt.get("confidence", 0.5))))
    if not reads:
        return {}
    counts = sorted(len(t) for t, _ in reads)
    median = counts[len(counts) // 2]
    reads = [(t, w) for t, w in reads if len(t) >= median * 0.5]      # drop cut-short reads
    count_votes = {}
    for tokens, _ in reads:
        count_votes[len(tokens)] = count_votes.get(len(tokens), 0) + 1
    # B: the reference is the read the OTHER reads agree with most (sum of token
    # similarities after lining up), not simply the highest-confidence read - a
    # read with a merged or junk token (METAL2O5) no longer becomes the reference
    def agreement(candidate):
        total = 0.0
        for other, _ in reads:
            if other is candidate:
                continue
            for index, token in enumerate(align_tokens_to_reference(candidate, other)):
                if token is not None:
                    total += consensus_similarity(candidate[index], token)
        return total
    scored_references = sorted(
        ((agreement(tokens), weight, tokens) for tokens, weight in reads),
        key=lambda item: (item[0], item[1]), reverse=True,
    )
    reference = scored_references[0][2]

    slots = [[] for _ in reference]
    symbol_inserts = {}
    for tokens, weight in reads:
        inserts = []
        for index, token in enumerate(align_tokens_to_reference(reference, tokens, inserts)):
            if token is not None:
                slots[index].append((token, weight))
        for index, token in set(inserts):
            if not re.search(r"[A-Za-z0-9]", str(token)):
                symbol_inserts.setdefault((index, str(token)), []).append((token, weight))
    # a symbol the reference read missed (e.g. a leading '*') is added back when
    # at least 30% of the reads have it in the same place
    for (index, symbol), variants in sorted(symbol_inserts.items(), key=lambda item: -item[0][0]):
        if len(variants) >= 0.3 * len(reads):
            slots.insert(index, variants)

    resolved = []
    for index, variants in enumerate(slots):
        if not variants:
            continue
        kind = consensus_slot_type(variants)
        total = sum(w for _, w in variants) or 1.0
        entry = {"type": kind, "reads": len(variants), "support": len(variants) / max(len(reads), 1)}
        if kind in ("number", "time"):
            votes = {}
            for token, weight in variants:
                key = consensus_key(token)
                if (kind == "time") == bool(re.fullmatch(r"\d{1,2}:\d{2}", key)):
                    votes[key] = votes.get(key, 0.0) + weight
            text, weight = max(votes.items(), key=lambda item: item[1]) if votes else (consensus_key(variants[0][0]), 0.0)
            ranked_votes = sorted(votes.values(), reverse=True) if votes else [0.0]
            lead = (ranked_votes[0] - (ranked_votes[1] if len(ranked_votes) > 1 else 0.0)) / total
            entry.update(text=text, fit=weight / total, lead=lead,
                         method=f"voted ({weight / total:.0%}, leads by {lead:.0%})")
        elif kind == "word":
            char_pattern = slot_character_pattern(variants, kind)
            pattern_fits = (
                english_words_for_pattern(char_pattern["pattern"], char_pattern["optional"])
                if char_pattern else []
            )
            if char_pattern and char_pattern["optional"]:
                # the reads disagree on this word's length -> also words ONE letter
                # longer than the pattern (a letter all reads may have missed)
                for word in english_words_one_longer(char_pattern["pattern"]):
                    if word not in pattern_fits:
                        pattern_fits.append(word)
            word = resolve_consensus_word(variants, candidate_words=pattern_fits)
            if not word:
                continue
            entry.update(word)
            entry["variants"] = [token for token, _ in variants]
            if sum(1 for token, _ in variants if str(token).endswith(":")) >= len(variants) / 2:
                entry["suffix"] = ":"
            if char_pattern and char_pattern["optional"]:
                inserted, note = optional_letter_decision(char_pattern)
                entry["optional_note"] = note
                entry["pattern_words"] = pattern_fits
                if inserted and "exact_share" not in entry:
                    entry.update(text=inserted, fit=1.0, margin=1.0, method=note, optional_inserted=True)
                    char_pattern = None             # decided here -> unique-word rule not needed
            if char_pattern:
                fitting = pattern_fits
                entry["pattern_words"] = fitting
                # English word first: the word settles only when exactly ONE English
                # word fits the pattern (with and without its possible missing
                # letters). Several fits (LOS? -> LOS, LOSS, LOST ...) stay open and
                # go on to the regular checks, with these words as starting points.
                if (
                    len(fitting) == 1 and "exact_share" not in entry
                    and "?" in char_pattern["pattern"]
                ):
                    entry.update(text=fitting[0], fit=1.0, margin=1.0,
                                 method=f"only English word fitting {char_pattern['pattern']}")
        else:
            votes = {}
            closes = 0
            for token, weight in variants:
                compact = re.sub(r"\s+", "", str(token))
                letter = re.sub(r"[^A-Za-z0-9@]", "", compact).upper()[:1] or compact[:1]
                if letter:
                    votes[letter] = votes.get(letter, 0.0) + weight
                if re.fullmatch(r"[A-Za-z0-9][).]", str(token)):
                    closes += 1
            if not votes:
                continue
            letter, weight = max(votes.items(), key=lambda item: item[1])
            entry.update(text=letter, fit=weight / total, method=f"voted ({weight / total:.0%})",
                         bullet_evidence=closes)
        char_pattern = slot_character_pattern(variants, kind)
        if char_pattern:
            entry["char_pattern"] = char_pattern
        resolved.append(entry)

    # A: a slot only a few reads have anything in (e.g. the '5' from METAL2O5 in one
    # read) is never confident - numbers, words and marks alike
    for entry in resolved:
        if entry.get("support", 1.0) < CONSENSUS_MIN_SLOT_SUPPORT:
            entry.update(fit=0.0, margin=0.0, lead=0.0, low_support=True,
                         method=(f"only in {entry['reads']} of {len(reads)} reads "
                                 f"(< {CONSENSUS_MIN_SLOT_SUPPORT:.0%}) -> not confident, not used"))
            entry["display"] = entry["text"] + "?"

    review_suspect_consensus_words(resolved)
    review_optional_letter_context(resolved)
    review_pattern_choice_context(resolved)

    # a single mark right before a time is the '@'
    for index, entry in enumerate(resolved[:-1]):
        if entry["type"] == "mark" and resolved[index + 1]["type"] == "time" \
                and entry["text"] in CONSENSUS_AT_LOOKALIKES:
            entry["method"] += f" -> '@' (mark '{entry['text']}' before a time)"
            entry["text"] = "@"
    # a leading single letter with ')' or '.' evidence is shown as a bullet
    if resolved and resolved[0]["type"] == "mark" and resolved[0].get("bullet_evidence", 0) > 0 \
            and re.fullmatch(r"[A-Z0-9]", resolved[0]["text"]):
        resolved[0]["display"] = "(" + resolved[0]["text"] + ")"     # bullets are always written (A)

    parts = []
    for entry in resolved:
        shown = entry.get("display", entry["text"] + entry.get("suffix", ""))
        if entry["type"] == "word" and not consensus_entry_confident(entry):
            # not confident: show what the reads actually support, not a guess
            shown = (entry.get("char_pattern") or {}).get("pattern") or (shown + "?")
            entry["display"] = shown
            fits = entry.get("pattern_words") or []
            entry["method"] = (
                "not confident" + (f" - English words that fit: {', '.join(fits[:6])}" if fits else "")
                + (f" | {entry['review_reason']}" if entry.get("review_reason") else "")
            )
        if shown == "." and parts:
            parts[-1] += "."                           # sentence end joins the word before it
            continue
        parts.append(shown)
    return {"slots": resolved, "text": " ".join(parts)}


def print_whole_line_consensus(consensus, title="WHOLE-LINE CONSENSUS (all whole-line reads combined)"):
    if not consensus:
        return
    print()
    print("=" * 70)
    print(title)
    print("=" * 70)
    for entry in consensus["slots"]:
        extra = ""
        if entry.get("bullet_evidence"):
            extra = f" | ')' or '.' after it in {entry['bullet_evidence']} read(s) -> bullet evidence"
        print(f"  {entry.get('display', entry['text']):<10} {entry['type']:<6} {entry['method']}{extra}")
    print(f"WHOLE-LINE CONSENSUS: {consensus['text']}   ('?' = not confident, not used)")

    pattern_parts, filled_parts, details = [], [], []
    for entry in consensus["slots"]:
        char_pattern = entry.get("char_pattern")
        if entry["text"] == "@" and entry["type"] == "mark":
            pattern_parts.append("@")
            filled_parts.append("@")
            continue
        if not char_pattern:
            pattern_parts.append(entry["text"])
            filled_parts.append(entry["text"])
            continue
        pattern_parts.append(char_pattern["pattern"])
        filled_parts.append(char_pattern["filled"])
        if "?" in char_pattern["pattern"]:
            offers = " ".join(
                "[" + "/".join(f"{c} {share:.0%}" for c, share in column) + "]"
                for column in char_pattern["options"]
            )
            line = f"  {char_pattern['pattern']:<10} ? offers: {offers}"
            if entry["type"] == "word":
                fitting = entry.get("pattern_words") or []
                shown = ", ".join(fitting[:8]) + (" ..." if len(fitting) > 8 else "")
                line += f" | English words that fit: {shown or 'none'}"
                if entry.get("optional_note"):
                    line += f" | {entry['optional_note']}"
            details.append(line)
    print(f"CHARACTER PATTERN (? only where agreement is low, below {PATTERN_KEEP_SHARE:.0%}): {' '.join(pattern_parts)}")
    print(f"BEST FILL (? filled where >= {PATTERN_FILL_SHARE:.0%} agree and it leads by "
          f"{PATTERN_FILL_LEAD:.0%}):  {' '.join(filled_parts)}")
    for line in details:
        print(line)


CONSENSUS_NUMBER_MIN_SHARE = 0.40   # a number/time is used when this share of reads vote for it
CONSENSUS_NUMBER_MIN_LEAD = 0.15    # ... and it leads the next reading by this much
LINE_NUMBER_SPAN = re.compile(r"\d[\dOoIl:]*(?:\s*[.,]\s*[\dOoIl]+)?\s*%?")


def apply_consensus_numbers(decisions):
    """
    Numbers and times from the whole-line consensus are USED, not just shown:
    the line's numbers/times are matched to the consensus ones in order (only
    when both have the same count), and a line value that differs is replaced
    by a confident consensus value ('69.O' -> '69.0%', '5:1' -> '5:11').
    """
    slots = [e for e in (LINE_CONSENSUS.get("slots") or []) if e["type"] in ("number", "time")]
    confident = [
        e for e in slots
        if e.get("fit", 0) >= CONSENSUS_NUMBER_MIN_SHARE and e.get("lead", 0) >= CONSENSUS_NUMBER_MIN_LEAD
    ]
    if not slots or len(confident) != len(slots):
        return decisions                           # not every consensus number is sure -> leave the line
    spans = []
    for decision_index, decision in enumerate(decisions):
        for match in LINE_NUMBER_SPAN.finditer(str(decision.get("text", ""))):
            spans.append((decision_index, match))
    if len(spans) != len(slots):
        if spans or slots:
            print(f"CONSENSUS NUMBERS: line has {len(spans)} number(s), consensus {len(slots)} -> not applied")
        return decisions
    # replace from the end so earlier match positions stay valid
    for (decision_index, match), slot in reversed(list(zip(spans, slots))):
        current = match.group(0)
        compact = re.sub(r"\s+", "", current)
        if consensus_key(compact) == slot["text"]:
            continue
        current_is_time = bool(re.fullmatch(r"[0-9Oo]{1,2}:[0-9Oo]{2}", compact))
        if current_is_time != (slot["type"] == "time"):
            print(f"CONSENSUS NUMBER NOT USED: '{current.strip()}' and '{slot['text']}' are not the same kind "
                  "(time vs number) -> the line keeps its value")
            continue
        if current_is_time and same_clock_time(normalize_times_around_colons(compact), slot["text"]):
            continue                                   # 00:37 vs 0:37 -> same time, keep the line's form
        if len(slot["text"]) < len(compact):
            print(f"CONSENSUS NUMBER NOT USED: '{slot['text']}' is shorter than '{current.strip()}' "
                  "-> the line keeps its value (the consensus never drops characters)")
            continue
        text = str(decisions[decision_index]["text"])
        trailing = current[len(current.rstrip()):]
        new_value = slot["text"]
        if new_value.endswith("%") and not compact.endswith("%"):
            # the '%' may already be the next piece ('69.O' then '%'): not added twice
            after = text[match.end():].lstrip()
            if not after:
                after = next((str(d.get("text", "")).lstrip() for d in decisions[decision_index + 1:]
                              if str(d.get("text", "")).strip()), "")
            if after.startswith("%"):
                new_value = new_value[:-1]
                print(f"CONSENSUS NUMBER: '{slot['text']}' - the '%' is already the next piece -> "
                      f"'{new_value}' used, so the line does not get two '%'")
        decisions[decision_index]["text"] = text[:match.start()] + new_value + trailing + text[match.end():]
        decisions[decision_index]["source"] = (
            str(decisions[decision_index].get("source", "")) + " | consensus number"
        ).strip(" |")
        print(f"CONSENSUS NUMBER USED: '{current.strip()}' -> '{new_value}' ({slot['method']})")
    return decisions


def consensus_entry_confident(entry):
    confident = entry.get("fit", 0) >= CONSENSUS_WORD_MIN_FIT and entry.get("margin", 0) >= CONSENSUS_WORD_MIN_MARGIN
    if (entry.get("char_pattern") or {}).get("optional") and not (
        entry.get("optional_inserted") or entry.get("evidence_choice") or entry.get("digit_evidence")
    ):
        confident = False
    return confident


def consensus_confident_words():
    """Consensus words (in line order) that are confident enough to settle a word."""
    words = []
    for entry in (LINE_CONSENSUS.get("slots") or []):
        if entry["type"] != "word":
            continue
        words.append((entry["text"], consensus_entry_confident(entry)))   # one rule for display and use
    return words


def consensus_bullet_letter(raw_mark):
    """Leading-letter bullet evidence from the consensus, or None."""
    slots = LINE_CONSENSUS.get("slots") or []
    if not slots or slots[0]["type"] != "mark" or not slots[0].get("bullet_evidence") \
            or slots[0].get("low_support"):
        return None
    letter = slots[0]["text"]
    own = bullet_mark_core(re.sub(r"\s+", "", str(raw_mark)))
    if own is None or str(own).upper() != letter:
        return None
    return letter



def remember_line_whole_reads(whole_attempts):
    LINE_WHOLE_READ_TOKENS.clear()
    WORD_IMAGE_MESSAGES_PRINTED.clear()
    for attempt in whole_attempts or []:
        tokens = [t.upper() for t in re.findall(r"[A-Za-z]+", str(attempt.get("text", "")))]
        if tokens:
            LINE_WHOLE_READ_TOKENS.append(tokens)


def whole_line_word_agreement(word):
    """(reads spelling the word exactly, reads with any word)."""
    word = normalize_alpha_for_matching(word)
    total = len(LINE_WHOLE_READ_TOKENS)
    hits = sum(1 for tokens in LINE_WHOLE_READ_TOKENS if word in tokens)
    return hits, total


def whole_line_evidence_for_word(word, minimum_similarity=0.6):
    """
    3: evidence for ONE word of a split group, from the whole-line reads.
    In each read, the token most like the word is taken; each distinct token
    counts by its share of the reads (e.g. DIS in 12 of 16 reads -> 0.68).
    """
    word = normalize_alpha_for_matching(word)
    if not word or not LINE_WHOLE_READ_TOKENS:
        return []
    counts = {}
    for tokens in LINE_WHOLE_READ_TOKENS:
        best, best_ratio = None, 0.0
        for token in tokens:
            ratio = SequenceMatcher(None, word, token, autojunk=False).ratio()
            if ratio > best_ratio:
                best, best_ratio = token, ratio
        if best and best_ratio >= minimum_similarity:
            counts[best] = counts.get(best, 0) + 1
    total = len(LINE_WHOLE_READ_TOKENS)
    return [(token, 0.9 * count / total) for token, count in counts.items()]


def word_image_visuals(decision):
    """
    5: the image pieces that belong to the WORDS of a group. Symbol-only pieces
    ('@', '%', ':') never belong to a word; number-only pieces ('205') are left
    out when the group's text has its own number token for them. If that would
    leave nothing, every piece is kept.
    """
    visuals = [v for v in decision.get("visual", []) if v.get("image") is not None]
    text = str(decision.get("text", ""))
    has_number_token = any(re.search(r"\d", token) for token in text.split())
    kept = []
    for visual in visuals:
        piece = re.sub(r"\s+", "", str(visual.get("text", "")))
        if piece and not re.search(r"[A-Za-z0-9]", piece):
            continue                                        # symbol only
        if has_number_token and piece and not re.search(r"[A-Za-z]", piece):
            continue                                        # number that has its own token
        kept.append(visual)
    if kept and len(kept) < len(visuals):
        left_out = [str(v.get("text", "")) for v in visuals if v not in kept]
        message = (f"WORD IMAGE: '{text}' uses {len(kept)} of {len(visuals)} pieces "
                   f"(left out non-word pieces: {', '.join(left_out)})")
        if message not in WORD_IMAGE_MESSAGES_PRINTED:
            WORD_IMAGE_MESSAGES_PRINTED.add(message)
            print(message)
    return kept or visuals


def split_decision_into_word_units(decision):
    words = alpha_words_from_text(decision.get("text", ""))
    if not words:
        return []

    units = []
    refinement = decision.get("refinement")
    if (
        refinement
        and refinement.get("pieces")
        and len(refinement["pieces"]) == len(words)
    ):
        for index, word in enumerate(words):
            piece = refinement["pieces"][index]
            units.append({
                "word": word,
                "piece": piece,
                "image": piece.get("image"),
                "evidence": get_piece_ocr_evidence(piece),
                "word_index": index,
            })
        return units

    word_visuals = word_image_visuals(decision)
    visual_images = [visual.get("image") for visual in word_visuals]

    if len(words) == 1:
        image = combine_images_horizontal(visual_images, gap=0) if visual_images else None
        evidence = []
        for visual in word_visuals:
            evidence.extend(get_piece_ocr_evidence(visual))
        for baseline in decision.get("baseline", []):
            baseline_text = normalize_alpha_for_matching(baseline.get("text", ""))
            if baseline_text:
                evidence.append((baseline_text, baseline.get("score", 0.5)))
        units.append({
            "word": words[0],
            "piece": None,
            "image": image,
            "evidence": evidence,
            "word_index": 0,
        })
        return units

    if visual_images:
        combined = combine_images_horizontal(visual_images, gap=0)
        pieces = split_chunk_into_n_parts(combined, len(words))
        if pieces is not None:
            for index, word in enumerate(words):
                piece_result = read_word_crop(pieces[index])
                evidence = get_piece_ocr_evidence(piece_result)
                # the image was split by guess -> the whole-line reads also count
                evidence.extend(whole_line_evidence_for_word(word))
                units.append({
                    "word": word,
                    "piece": piece_result,
                    "image": pieces[index],
                    "evidence": evidence,
                    "word_index": index,
                })
            return units

    for index, word in enumerate(words):
        units.append({
            "word": word,
            "piece": None,
            "image": None,
            "evidence": [(word, 1.0)],
            "word_index": index,
        })
    return units


# ============================================================
# PRE-CANDIDATE INDIVIDUAL CHARACTER OCR
# ============================================================
#   whole-line OCR -> baseline word locations/lengths
#   -> each word split into character crops -> each crop OCR'd
#   -> characters above CHARACTER_LOCK_THRESHOLD are LOCKED
#   -> only THEN may English candidates be generated
# ============================================================

def normalize_single_ocr_character(text, alphabetic_only=False):
    pattern = r"[^A-Za-z]" if alphabetic_only else r"[^A-Za-z0-9]"
    cleaned = re.sub(pattern, "", str(text).upper())
    if len(cleaned) != 1:
        return ""
    return cleaned


def physical_character_should_lock(recognized_character, confidence, reference_character):
    recognized = normalize_single_ocr_character(recognized_character)
    reference = normalize_single_ocr_character(reference_character)
    return bool(
        recognized
        and reference
        and safe_float(confidence) > CHARACTER_LOCK_THRESHOLD
        and recognized == reference
    )


def _isolated_character_jobs(crop):
    """The pictures a letter crop is read in: (source name, picture), always the same
    versions in the same order (original, each threshold, red mask; each scale)."""
    versions = [("Original", crop)]
    for threshold in CHARACTER_OCR_THRESHOLDS:
        versions.append((f"Threshold{threshold}", make_binary(crop, threshold)))
    versions.append(("RedMask", make_red_mask_image(crop, dilate=True, loose=True)))
    jobs = []
    for version_name, version in versions:
        for scale in CHARACTER_OCR_SCALES:
            jobs.append((f"{version_name} x{scale}", version.resize((
                max(1, version.width * scale),
                max(1, version.height * scale),
            ))))
    return jobs


LETTER_PREFETCH = {"checked": False, "on": True}   # S8: first batch of a run is checked


def prefetch_isolated_characters(crops, alphabetic_only=False):
    """Read MANY letter crops in one go (S8): every crop not read yet has its pictures
    (_isolated_character_jobs) sent in one batched PaddleOCR call, and each crop's
    result goes into CHARACTER_OCR_CACHE through read_isolated_character - so the
    later read_isolated_character(crop) for the same crop finds it already read and
    scores it exactly as before. The FIRST time in a run, the same crops are also read
    the S2 way (one batch of 4 same-size pictures per crop) and compared in the log;
    any difference switches this off for the rest of the run (crops are then read one
    by one as before)."""
    if not LETTER_PREFETCH["on"] or not BATCH_OCR or "letter crops" in BATCH_OFF:
        return
    prefix = "CHAR_ALPHA:" if alphabetic_only else "CHAR_ALNUM:"
    pending, seen = [], set()
    for crop in crops:
        if crop is None:
            continue
        key = prefix + image_cache_key(crop)
        if key in CHARACTER_OCR_CACHE or key in seen:
            continue
        seen.add(key)
        pending.append(crop)
    if len(pending) < 2:
        return                                      # nothing to gain over the normal read
    started = time.perf_counter()
    all_jobs = [_isolated_character_jobs(crop) for crop in pending]
    reads = paddle_read_text_images([picture for jobs in all_jobs for _source, picture in jobs],
                                    kind="letter crops")
    if not LETTER_PREFETCH["checked"]:
        LETTER_PREFETCH["checked"] = True
        single = [read for jobs in all_jobs
                  for read in paddle_read_text_images([picture for _source, picture in jobs], kind="letter crops")]
        same = sum(1 for a, b in zip(reads, single) if not batch_reads_differ(a, b))
        junk = sum(1 for a, b in zip(reads, single) if a[0] != b[0] and not batch_reads_differ(a, b))
        print(f"BATCH OCR CHECK (letter crops, {len(pending)} crops read together): {same} of {len(reads)} "
              f"reads identical to reading each crop on its own"
              + (f" ({junk} junk read(s) not counted)" if junk else "")
              + ("" if same == len(reads) else " - reading crops together switched OFF for the rest of this run"))
        # S37: which reads differed - the crop, the version of it, both reads
        position = 0
        for crop_number, jobs in enumerate(all_jobs, start=1):
            for source, picture in jobs:
                together, alone = reads[position], single[position]
                if together[0] != alone[0]:
                    print(f"    crop {crop_number} ({pending[crop_number - 1].width}x"
                          f"{pending[crop_number - 1].height} px), version {source}: many crops together "
                          f"'{together[0]}' ({together[1]:.3f}) vs this crop on its own '{alone[0]}' "
                          f"({alone[1]:.3f})"
                          + ("" if batch_reads_differ(together, alone) else " - junk read, not counted"))
                position += 1
        if same != len(reads):
            LETTER_PREFETCH["on"] = False
            reads = single
    add_work_time("letter", time.perf_counter() - started, count=len(pending))
    position = 0
    for crop, jobs in zip(pending, all_jobs):
        read_isolated_character(crop, alphabetic_only=alphabetic_only,
                                _reads=reads[position:position + len(jobs)], _jobs=jobs)
        position += len(jobs)


def read_isolated_character(crop, alphabetic_only=False, _reads=None, _jobs=None):
    empty = {
        "character": "",
        "confidence": 0.0,
        "best_raw_confidence": 0.0,
        "agreement": 0.0,
        "votes": 0,
        "attempts": [],
        "alternatives": [],
        "alphabetic_only": alphabetic_only,
    }
    if crop is None:
        return dict(empty)

    key = ("CHAR_ALPHA:" if alphabetic_only else "CHAR_ALNUM:") + image_cache_key(crop)
    if key in CHARACTER_OCR_CACHE:
        cached = CHARACTER_OCR_CACHE[key]
        result = dict(cached)
        result["alternatives"] = [dict(item) for item in cached.get("alternatives", [])]
        result["attempts"] = [dict(item) for item in cached.get("attempts", [])]
        return result

    # all versions of the crop are read together (one batched PaddleOCR call instead of
    # one call + one temp file each); same pictures, same order as before. When the crop
    # was already read with others (prefetch_isolated_characters), those reads are used.
    if _reads is not None and _jobs is not None:
        jobs, reads = _jobs, _reads
    else:
        letter_started = time.perf_counter()
        jobs = _isolated_character_jobs(crop)
        reads = paddle_read_text_images([picture for _source, picture in jobs], kind="letter crops")
        add_work_time("letter", time.perf_counter() - letter_started)

    attempts = []
    for (source, _picture), (raw, confidence) in zip(jobs, reads):
        character = normalize_single_ocr_character(raw, alphabetic_only=alphabetic_only)
        if not character:
            continue
        attempts.append({
            "character": character,
            "confidence": safe_float(confidence),
            "source": source,
            "raw": str(raw),
        })

    if not attempts:
        CHARACTER_OCR_CACHE[key] = dict(empty)
        return dict(empty)

    groups = defaultdict(list)
    for attempt in attempts:
        groups[attempt["character"]].append(attempt)
    total_weight = sum(max(0.05, attempt["confidence"]) for attempt in attempts)

    ranked = []
    for character, entries in groups.items():
        weight = sum(max(0.05, entry["confidence"]) for entry in entries)
        agreement = weight / max(total_weight, 1e-9)
        best_raw = max(entry["confidence"] for entry in entries)
        average_raw = sum(entry["confidence"] for entry in entries) / max(len(entries), 1)
        confidence = clamp(best_raw * 0.50 + average_raw * 0.20 + agreement * 0.30)
        ranked.append({
            "character": character,
            "confidence": confidence,
            "best_raw_confidence": best_raw,
            "average_raw_confidence": average_raw,
            "agreement": agreement,
            "votes": len(entries),
            "attempts": [dict(entry) for entry in entries],
        })

    ranked.sort(
        key=lambda item: (
            item["confidence"],
            item["agreement"],
            item["best_raw_confidence"],
            item["votes"],
        ),
        reverse=True,
    )
    winner = dict(ranked[0])
    winner["alternatives"] = [
        {
            "character": item["character"],
            "confidence": item["confidence"],
            "agreement": item["agreement"],
            "votes": item["votes"],
            "best_raw_confidence": item["best_raw_confidence"],
        }
        for item in ranked
    ]
    winner["alphabetic_only"] = alphabetic_only
    CHARACTER_OCR_CACHE[key] = dict(winner)
    return dict(winner)


def align_observed_token_to_reference(observed, reference):
    observed = re.sub(r"[^A-Z0-9]", "", str(observed).upper())
    reference = re.sub(r"[^A-Z0-9]", "", str(reference).upper())
    target_length = len(reference)
    if target_length == 0 or not observed:
        return [None] * target_length
    if len(observed) == target_length:
        return list(observed)

    if len(observed) == target_length + 1:
        best = None
        best_score = -1.0
        for remove_index in range(len(observed)):
            collapsed = observed[:remove_index] + observed[remove_index + 1:]
            score = SequenceMatcher(None, collapsed, reference).ratio()
            if score > best_score:
                best_score = score
                best = collapsed
        if best is not None:
            return list(best)

    aligned = [None] * target_length
    matcher = SequenceMatcher(None, reference, observed, autojunk=False)
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == "equal":
            for offset in range(i2 - i1):
                aligned[i1 + offset] = observed[j1 + offset]
        elif tag == "replace":
            span = min(i2 - i1, j2 - j1)
            for offset in range(span):
                aligned[i1 + offset] = observed[j1 + offset]
    return aligned


def build_whole_line_character_consensus(baseline_tokens, whole_attempts):
    token_count = len(baseline_tokens)
    aligned_attempts = []
    for attempt in whole_attempts:
        tokens = tokenize_line(attempt.get("text", ""))
        if len(tokens) != token_count:
            continue
        aligned_attempts.append({
            "tokens": tokens,
            "confidence": max(0.01, safe_float(attempt.get("confidence", 0.0))),
            "source": attempt.get("source", "whole-line OCR"),
        })

    output = []
    for token_index, baseline in enumerate(baseline_tokens):
        token_text = normalize_token(baseline.get("text", ""))
        reference = re.sub(r"[^A-Z0-9]", "", token_text.upper())
        if not reference:
            output.append(None)
            continue

        per_position = [defaultdict(float) for _ in reference]
        per_position_raw = [defaultdict(list) for _ in reference]
        observations = 0
        for attempt in aligned_attempts:
            observed = re.sub(
                r"[^A-Z0-9]", "",
                normalize_token(attempt["tokens"][token_index]).upper(),
            )
            if not observed:
                continue
            aligned = align_observed_token_to_reference(observed, reference)
            observations += 1
            for position, character in enumerate(aligned):
                if not character:
                    continue
                weight = attempt["confidence"]
                per_position[position][character] += weight
                per_position_raw[position][character].append(weight)

        characters = []
        locked = {}
        for position, reference_character in enumerate(reference):
            votes = per_position[position]
            if not votes:
                characters.append({
                    "position": position,
                    "character": "",
                    "confidence": 0.0,
                    "agreement": 0.0,
                    "votes": 0,
                    "best_raw_confidence": 0.0,
                    "reference_character": reference_character,
                    "locked": False,
                    "source": "whole-line consensus",
                })
                continue
            total_weight = sum(votes.values())
            winner, winner_weight = max(votes.items(), key=lambda item: item[1])
            agreement = winner_weight / max(total_weight, 1e-9)
            raw_values = per_position_raw[position][winner]
            best_raw = max(raw_values) if raw_values else 0.0
            average_raw = sum(raw_values) / len(raw_values) if raw_values else 0.0
            confidence = clamp(agreement * 0.78 + average_raw * 0.14 + best_raw * 0.08)
            is_locked = confidence > CHARACTER_LOCK_THRESHOLD and observations >= 3
            if is_locked:
                locked[position] = winner
            characters.append({
                "position": position,
                "character": winner,
                "confidence": confidence,
                "agreement": agreement,
                "votes": len(raw_values),
                "best_raw_confidence": best_raw,
                "reference_character": reference_character,
                "locked": is_locked,
                "source": "whole-line consensus",
            })

        output.append({
            "token": token_text,
            "reference": reference,
            "length": len(reference),
            "characters": characters,
            "locked": locked,
            "available": bool(characters),
            "source": "whole-line consensus",
            "observations": observations,
        })
    return output


def merge_physical_and_consensus_character_profiles(physical, consensus):
    """
    Only a physically isolated character may create a lock. Whole-line
    agreement is advisory only. N is the OCR token's alphanumeric length.
    """
    if physical is None and consensus is None:
        return None

    if physical is None:
        output = dict(consensus)
        output["locked"] = {}
        output["source"] = "whole-line consensus advisory only - NO CHARACTER LOCKS"
        characters = []
        for item in consensus.get("characters", []):
            copied = dict(item)
            copied["locked"] = False
            copied["source"] = "whole-line consensus advisory only"
            characters.append(copied)
        output["characters"] = characters
        output["available"] = False
        return output

    if consensus is None:
        physical = dict(physical)
        physical["length"] = len(physical.get("reference", ""))
        return physical

    reference = physical.get("reference") or consensus.get("reference") or ""
    if not reference:
        return physical

    physical_chars = {item.get("position"): item for item in physical.get("characters", [])}
    consensus_chars = {item.get("position"): item for item in consensus.get("characters", [])}

    combined_characters = []
    combined_locks = {}
    for position, reference_character in enumerate(reference):
        p = physical_chars.get(position)
        c = consensus_chars.get(position)
        physical_character = p.get("character", "") if p else ""
        physical_confidence = p.get("confidence", 0.0) if p else 0.0
        physical_lock = physical_character_should_lock(
            physical_character, physical_confidence, reference_character,
        )
        if p and physical_character:
            merged = dict(p)
            merged["position"] = position
            merged["reference_character"] = reference_character
            merged["locked"] = physical_lock
            if c and c.get("character"):
                if c.get("character") == physical_character:
                    merged["source"] = "physical isolated OCR; whole-line agrees"
                else:
                    merged["source"] = "physical isolated OCR; whole-line disagrees"
            else:
                merged["source"] = "physical isolated OCR"
        elif c and c.get("character"):
            merged = dict(c)
            merged["position"] = position
            merged["reference_character"] = reference_character
            merged["locked"] = False
            merged["source"] = "whole-line advisory only; no isolated character result"
        else:
            merged = {
                "position": position,
                "character": "",
                "confidence": 0.0,
                "agreement": 0.0,
                "votes": 0,
                "best_raw_confidence": 0.0,
                "reference_character": reference_character,
                "locked": False,
                "source": "no isolated character evidence",
            }
        if merged.get("locked") and merged.get("character"):
            combined_locks[position] = merged["character"]
        combined_characters.append(merged)

    return {
        "token": physical.get("token", consensus.get("token", "")),
        "reference": reference,
        "length": len(reference),
        "characters": combined_characters,
        "locked": combined_locks,
        "available": True,
        "source": (
            "PHYSICAL isolated-character OCR is lock authority; "
            "whole-line OCR is advisory; N fixed to token length"
        ),
        "geometry": physical.get("geometry"),
        "image": physical.get("image"),
    }


def split_line_into_token_crops_by_red_gaps(image, baseline_tokens):
    """
    One physical crop for every baseline token, using real red-ink gaps
    where possible and low-density valleys otherwise. Always returns crops.
    """
    if image is None:
        return None
    token_texts = [
        normalize_token(token.get("text", "") if isinstance(token, dict) else token)
        for token in baseline_tokens
    ]
    token_count = len(token_texts)
    if token_count <= 0:
        return None
    image = trim_to_content(image)
    if token_count == 1:
        return [image]

    red_mask = make_red_mask_array(image, loose=True)
    ys, xs = np.where(red_mask > 0)
    if len(xs) >= 8:
        y0 = max(0, int(ys.min()) - 2)
        y1 = min(red_mask.shape[0], int(ys.max()) + 3)
        work_mask = red_mask[y0:y1, :]
    else:
        gray = np.array(ImageOps.grayscale(image))
        work_mask = (gray < 175).astype(np.uint8)

    density = np.count_nonzero(work_mask, axis=0).astype(np.float32)
    if len(density) >= 3:
        kernel = np.ones(3, dtype=np.float32) / 3.0
        smooth = np.convolve(density, kernel, mode="same")
    else:
        smooth = density
    width = image.width

    low_limit = max(0.30, float(np.percentile(smooth, 18)))
    low = smooth <= low_limit
    gaps = []
    start = None
    for x, is_low in enumerate(low):
        if is_low and start is None:
            start = x
        elif not is_low and start is not None:
            if x - start >= 2:
                center = (start + x - 1) // 2
                if width * 0.015 < center < width * 0.985:
                    gaps.append({
                        "x0": start, "x1": x - 1, "width": x - start,
                        "center": center,
                        "density": float(np.mean(smooth[start:x])),
                    })
            start = None
    if start is not None and width - start >= 2:
        center = (start + width - 1) // 2
        if width * 0.015 < center < width * 0.985:
            gaps.append({
                "x0": start, "x1": width - 1, "width": width - start,
                "center": center,
                "density": float(np.mean(smooth[start:width])),
            })

    weights = []
    for token in token_texts:
        compact = re.sub(r"\s+", "", token)
        alnum = re.sub(r"[^A-Z0-9]", "", compact.upper())
        punctuation = re.sub(r"[A-Z0-9]", "", compact.upper())
        weights.append(max(1.0, len(alnum) + 0.55 * len(punctuation)))
    total_weight = sum(weights)
    cumulative = 0.0
    expected_boundaries = []
    for index in range(token_count - 1):
        cumulative += weights[index]
        expected_boundaries.append(width * cumulative / max(total_weight, 1e-9))

    selected_centers = []
    used_gap_indexes = set()
    for expected in expected_boundaries:
        best = None
        best_score = -1e9
        search_radius = max(image.height * 1.5, width * 0.12)
        for gap_index, gap in enumerate(gaps):
            if gap_index in used_gap_indexes:
                continue
            distance = abs(gap["center"] - expected)
            if distance > search_radius:
                continue
            distance_score = 1.0 - distance / max(search_radius, 1.0)
            width_score = min(gap["width"] / max(image.height * 0.20, 1.0), 1.5)
            blank_score = 1.0 / (1.0 + gap["density"])
            score = distance_score * 0.62 + width_score * 0.24 + blank_score * 0.14
            if score > best_score:
                best_score = score
                best = (gap_index, gap["center"])
        if best is not None:
            used_gap_indexes.add(best[0])
            selected_centers.append(int(best[1]))
        else:
            radius = max(3, int(width / max(token_count, 1) * 0.22))
            left = max(2, int(expected) - radius)
            right = min(width - 2, int(expected) + radius)
            if right > left:
                local = smooth[left:right + 1]
                minimum = float(local.min())
                positions = np.where(local <= minimum + 0.10)[0]
                if len(positions):
                    center = min(
                        (left + int(p) for p in positions),
                        key=lambda value: abs(value - expected),
                    )
                else:
                    center = int(expected)
            else:
                center = int(expected)
            selected_centers.append(center)

    min_piece_width = max(5, int(image.height * 0.16))
    boundaries = [0]
    remaining = token_count - 1
    for index, proposed in enumerate(selected_centers):
        minimum = boundaries[-1] + min_piece_width
        maximum = width - min_piece_width * (remaining - index)
        boundaries.append(max(minimum, min(maximum, int(proposed))))
    boundaries.append(width)

    pieces = []
    overlap = max(2, int(image.height * 0.045))
    for index in range(token_count):
        x0 = boundaries[index]
        x1 = boundaries[index + 1]
        crop = image.crop((max(0, x0 - overlap), 0, min(width, x1 + overlap), image.height))
        pieces.append(trim_to_content(crop))
    return pieces


def build_pre_candidate_character_profiles(line_image, baseline_tokens, whole_attempts):
    pieces = split_line_into_token_crops_by_red_gaps(line_image, baseline_tokens)
    if pieces is None or len(pieces) != len(baseline_tokens):
        pieces = split_chunk_into_n_parts(line_image, len(baseline_tokens))
    if pieces is None or len(pieces) != len(baseline_tokens):
        pieces = []

    consensus_profiles = build_whole_line_character_consensus(baseline_tokens, whole_attempts)

    profiles = []
    for token_index, baseline in enumerate(baseline_tokens):
        token_text = normalize_token(baseline.get("text", ""))
        alpha_numeric = re.sub(r"[^A-Z0-9]", "", token_text.upper())

        if not alpha_numeric:
            profile = {
                "token": token_text,
                "reference": "",
                "length": 0,
                "characters": [],
                "locked": {},
                "available": False,
                "source": "non-alphanumeric token",
            }
            profiles.append(profile)
            baseline["character_profile"] = profile
            continue

        token_crop = pieces[token_index] if pieces else None
        physical_profile = None
        compact_token = re.sub(r"\s+", "", token_text)
        token_is_pure_alphanumeric = bool(re.fullmatch(r"[A-Z0-9]+", compact_token.upper()))

        if token_crop is not None and token_is_pure_alphanumeric:
            geometry = estimate_visible_character_count(token_crop)
            geometry_rounded = int(geometry.get("rounded", 0) or 0)
            geometry_reliability = safe_float(geometry.get("reliability", 0.0))
            geometry_difference = abs(safe_float(geometry.get("count", 0.0)) - len(alpha_numeric))

            if (
                geometry_reliability >= 0.80
                and geometry_rounded > 0
                and geometry_rounded != len(alpha_numeric)
                and geometry_difference >= 0.85
            ):
                profile = {
                    "token": token_text,
                    "reference": alpha_numeric,
                    "length": len(alpha_numeric),
                    "characters": [],
                    "locked": {},
                    "available": False,
                    "source": (
                        "PHYSICAL character crops DEFERRED: visible character "
                        "count disagrees with baseline token length; wait for "
                        "recognized visual word"
                    ),
                    "geometry": geometry,
                    "image": token_crop,
                }
                profiles.append(profile)
                baseline["character_profile"] = profile
                continue

            # The per-letter crop reads that used to be made here were never used for
            # decisions (misaligned, e.g. METAL read as C-M-E-A-L) -> removed.
            # Each word gets its own letter profile later in the English pass.
            physical_profile = None

        consensus_profile = (
            consensus_profiles[token_index]
            if token_index < len(consensus_profiles) else None
        )
        profile = merge_physical_and_consensus_character_profiles(physical_profile, consensus_profile)
        if profile is None:
            profile = {
                "token": token_text,
                "reference": alpha_numeric,
                "length": len(alpha_numeric),
                "characters": [],
                "locked": {},
                "available": False,
                "source": "character evidence unavailable",
            }
        profiles.append(profile)
        baseline["character_profile"] = profile
    return profiles


def _align_observation_to_reference(reference, observation):
    """Needleman-Wunsch alignment of one OCR read to the reference word."""
    reference = normalize_alpha_for_matching(reference)
    observation = normalize_alpha_for_matching(observation)
    n = len(reference)
    m = len(observation)
    if not reference:
        return {}
    if not observation:
        return {i: None for i in range(n)}

    match_score = 3
    mismatch_score = -1
    gap_score = -2
    score = [[0] * (m + 1) for _ in range(n + 1)]
    trace = [[None] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        score[i][0] = i * gap_score
        trace[i][0] = "U"
    for j in range(1, m + 1):
        score[0][j] = j * gap_score
        trace[0][j] = "L"
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            diagonal = score[i - 1][j - 1] + (
                match_score if reference[i - 1] == observation[j - 1] else mismatch_score
            )
            up = score[i - 1][j] + gap_score
            left = score[i][j - 1] + gap_score
            best = max(diagonal, up, left)
            score[i][j] = best
            if diagonal == best:
                trace[i][j] = "D"
            elif up == best:
                trace[i][j] = "U"
            else:
                trace[i][j] = "L"

    mapping = {i: None for i in range(n)}
    i = n
    j = m
    while i > 0 or j > 0:
        direction = trace[i][j]
        if direction == "D":
            mapping[i - 1] = observation[j - 1]
            i -= 1
            j -= 1
        elif direction == "U":
            mapping[i - 1] = None
            i -= 1
        elif direction == "L":
            j -= 1
        else:
            break
    return mapping


def _reference_letter_confidence(result, reference_letter):
    reference_letter = normalize_single_ocr_character(reference_letter, alphabetic_only=True)
    if not reference_letter:
        return 0.0
    for alternative in result.get("alternatives", []) or []:
        if normalize_single_ocr_character(
            alternative.get("character", ""), alphabetic_only=True,
        ) == reference_letter:
            return safe_float(alternative.get("confidence", 0.0))
    return 0.0


def _ink_bbox_x(image):
    if image is None:
        return 0, 0
    mask = make_red_mask_array(image, loose=True)
    columns = np.where(np.count_nonzero(mask, axis=0) > 0)[0]
    if len(columns) == 0:
        return 0, image.width
    return int(columns[0]), int(columns[-1]) + 1


def _letter_crop_record(position, reference_character, crop, result,
                        connected_left=False, connected_right=False):
    return {
        "position": position,
        "reference_character": reference_character,
        "image": crop,
        "winner": result.get("character", ""),
        "winner_confidence": safe_float(result.get("confidence", 0.0)),
        "reference_confidence": _reference_letter_confidence(result, reference_character),
        "alternatives": [dict(item) for item in result.get("alternatives", [])],
        "attempts": [dict(item) for item in result.get("attempts", [])],
        "connected_left": connected_left,
        "connected_right": connected_right,
    }


def adaptive_connected_letter_crops(word, image, read_positions=None):
    """
    One crop per letter using neighbor-aware boundary refinement. When a pair
    reads correctly as a whole but cannot be split cleanly, the letters are
    marked CONNECTED and their crops are allowed to overlap.
    read_positions: only these letter positions are OCR-read (the '?' letters);
    boundaries are only refined next to them. None = every letter.
    """
    word = normalize_alpha_for_matching(word)
    if not word or image is None:
        return []

    image = trim_to_content(image)
    ink_left, ink_right = _ink_bbox_x(image)
    if ink_right > ink_left:
        image = trim_to_content(image.crop((ink_left, 0, ink_right, image.height)))

    n = len(word)
    if n == 1:
        result = read_isolated_character(image, alphabetic_only=True)
        return [_letter_crop_record(0, word[0], image, result)]

    width = image.width
    boundaries = [int(round(index * width / n)) for index in range(n + 1)]
    boundaries[0] = 0
    boundaries[-1] = width
    connected_boundaries = set()
    average = width / max(n, 1)

    for boundary_index in range(1, n):
        if read_positions is not None and not (
            (boundary_index - 1) in read_positions or boundary_index in read_positions
        ):
            continue                                   # both letters locked -> no refining reads
        left_letter = word[boundary_index - 1]
        right_letter = word[boundary_index]
        pair_text = left_letter + right_letter

        expected = boundaries[boundary_index]
        search_half = max(4, int(average * 0.34))
        candidate_boundaries = range(
            max(boundaries[boundary_index - 1] + 2, expected - search_half),
            min(boundaries[boundary_index + 1] - 2, expected + search_half) + 1,
            max(1, int(average * 0.06)),
        )

        # every trial cut of this boundary is cut first and all their crops are read
        # together in one batch (S8); the loop below then scores them exactly as before
        trial_crops = []
        for candidate_boundary in candidate_boundaries:
            left_crop = trim_to_content(image.crop((
                boundaries[boundary_index - 1], 0, candidate_boundary, image.height,
            )))
            right_crop = trim_to_content(image.crop((
                candidate_boundary, 0, boundaries[boundary_index + 1], image.height,
            )))
            trial_crops.append((candidate_boundary, left_crop, right_crop))
        prefetch_isolated_characters([crop for _b, left, right in trial_crops for crop in (left, right)],
                                     alphabetic_only=True)

        best = None
        for candidate_boundary, left_crop, right_crop in trial_crops:
            left_match = _reference_letter_confidence(
                read_isolated_character(left_crop, alphabetic_only=True), left_letter,
            )
            right_match = _reference_letter_confidence(
                read_isolated_character(right_crop, alphabetic_only=True), right_letter,
            )
            pair_score = (
                min(left_match, right_match) * 0.62
                + (left_match + right_match) / 2 * 0.38
            )
            candidate = {
                "boundary": candidate_boundary,
                "score": pair_score,
                "left_match": left_match,
                "right_match": right_match,
            }
            if best is None or candidate["score"] > best["score"]:
                best = candidate

        if best is None:
            continue
        if best["left_match"] >= 0.40 and best["right_match"] >= 0.40:
            boundaries[boundary_index] = best["boundary"]
            continue
        # S52: only now is the two-letter picture needed (the best cut is weak on one
        # side): is it read as exactly these two letters? Read here instead of for every
        # boundary up front - the same picture (the boundaries it uses have not moved),
        # the same read, so the same answer.
        pair_left = max(0, boundaries[boundary_index - 1] - int(average * 0.10))
        pair_right = min(width, boundaries[boundary_index + 1] + int(average * 0.10))
        pair_crop = trim_to_content(image.crop((pair_left, 0, pair_right, image.height)))
        pair_ocr = read_word_crop(pair_crop)
        pair_recognized = normalize_alpha_for_matching(pair_ocr.get("text", "")) == pair_text
        if pair_recognized:
            boundaries[boundary_index] = best["boundary"]
            connected_boundaries.add(boundary_index)

    output = []
    normal_overlap = max(1, int(average * 0.06))
    connected_overlap = max(normal_overlap, int(average * 0.28))
    for position in range(n):
        left_overlap = connected_overlap if position in connected_boundaries else normal_overlap
        right_overlap = connected_overlap if position + 1 in connected_boundaries else normal_overlap
        x0 = max(0, boundaries[position] - left_overlap)
        x1 = min(width, boundaries[position + 1] + right_overlap)
        crop = trim_to_content(image.crop((x0, 0, x1, image.height)))
        if read_positions is not None and position not in read_positions:
            record = _letter_crop_record(position, word[position], crop, {})
            record["not_read"] = True                  # locked letter -> crop not read
            output.append(record)
            continue
        result = read_isolated_character(crop, alphabetic_only=True)
        output.append(_letter_crop_record(
            position, word[position], crop, result,
            connected_left=position in connected_boundaries,
            connected_right=(position + 1) in connected_boundaries,
        ))
    return output


def build_individual_letter_crop_diagnostics(word, image, read_positions=None):
    return adaptive_connected_letter_crops(word, image, read_positions=read_positions)


def open_letter_positions(characters):
    return {item.get("position", index) for index, item in enumerate(characters or [])
            if not item.get("locked")}


def candidate_individual_letter_support(candidate_word, image):
    """
    How well the handwriting supports a proposed word when the SAME image is
    segmented into exactly len(candidate_word) letter crops.
    """
    empty = {"score": 0.0, "coverage": 0.0, "mean_match": 0.0, "strong_matches": 0, "diagnostics": []}
    candidate_word = normalize_alpha_for_matching(candidate_word)
    if not candidate_word or image is None:
        return empty
    diagnostics = build_individual_letter_crop_diagnostics(candidate_word, image)
    if not diagnostics:
        return empty

    matches = []
    observed_positions = 0
    strong_matches = 0
    for item in diagnostics:
        reference = normalize_single_ocr_character(
            item.get("reference_character", ""), alphabetic_only=True,
        )
        alternatives = item.get("alternatives", []) or []
        if alternatives:
            observed_positions += 1
        reference_confidence = 0.0
        for alternative in alternatives:
            if normalize_single_ocr_character(
                alternative.get("character", ""), alphabetic_only=True,
            ) == reference:
                reference_confidence = max(
                    reference_confidence,
                    safe_float(alternative.get("confidence", 0.0)),
                )
        matches.append(reference_confidence)
        if reference_confidence >= 0.60:
            strong_matches += 1

    coverage = observed_positions / max(len(diagnostics), 1)
    mean_match = sum(matches) / max(len(matches), 1)
    return {
        "score": clamp(mean_match * 0.78 + coverage * 0.22),
        "coverage": coverage,
        "mean_match": mean_match,
        "strong_matches": strong_matches,
        "diagnostics": diagnostics,
    }


NPLUS1_OCR_WINDOW = 0.10     # N+1 candidates further than this below the best OCR score get no crops


def strong_visible_nplus1_geometry(current_word, character_profile):
    """Visible-count estimate must be ~0.85-1.55 characters above N."""
    if not character_profile:
        return False
    geometry = character_profile.get("geometry", {}) or {}
    count = safe_float(geometry.get("count", 0.0))
    reliability = safe_float(geometry.get("reliability", 0.0))
    n = len(normalize_alpha_for_matching(current_word))
    if n <= 0:
        return False
    extra = count - n
    return reliability >= 0.80 and 0.85 <= extra <= 1.55


def profile_fully_certain(word, characters):
    """Every letter locked AND the word is valid English -> letter crops not needed."""
    return (
        bool(characters)
        and all(item.get("locked") for item in characters)
        and zipf_frequency(normalize_alpha_for_matching(word).lower(), "en") >= 2.3
    )


def build_word_character_profile_from_image(word, image):
    """
    OCR the complete word crop many ways and align those reads back to the
    current word, giving a confidence for EACH character position.
    """
    word = normalize_alpha_for_matching(word)
    if not word or image is None:
        return None
    image = trim_to_content(image)
    profile_cache_key = (word, image_cache_key(image))

    if profile_cache_key in CHARACTER_PROFILE_CACHE:
        CACHE_STATS["character_profile_hits"] += 1
        cached = CHARACTER_PROFILE_CACHE[profile_cache_key]
        result = dict(cached)
        result["characters"] = [dict(item) for item in cached.get("characters", [])]
        result["locked"] = dict(cached.get("locked", {}))
        result["image"] = image
        if profile_fully_certain(word, result["characters"]):
            result["individual_letter_crops"] = []
            result["letter_crops_skipped"] = True
        else:
            result["individual_letter_crops"] = build_individual_letter_crop_diagnostics(
                word, image, read_positions=open_letter_positions(result["characters"]),
            )
        return result

    CACHE_STATS["character_profile_misses"] += 1
    attempts = collect_word_attempts(image)

    usable = []
    for attempt in attempts:
        observed = normalize_alpha_for_matching(attempt.get("text", ""))
        if not observed:
            continue
        if len(observed) not in {max(1, len(word) - 1), len(word), len(word) + 1}:
            continue
        confidence = clamp(safe_float(attempt.get("confidence", 0.0)))
        if confidence <= 0.0:
            continue
        usable.append({
            "text": observed,
            "confidence": confidence,
            "source": attempt.get("source", ""),
            "mapping": _align_observation_to_reference(word, observed),
        })

    characters = []
    locked = {}
    for position, reference_character in enumerate(word):
        total_weight = 0.0
        reference_weight = 0.0
        reference_raw = []
        alternatives = defaultdict(float)
        alternative_raw = defaultdict(list)
        observations = 0
        for attempt in usable:
            observed_character = attempt["mapping"].get(position)
            if not observed_character:
                continue
            observations += 1
            weight = max(0.05, attempt["confidence"])
            total_weight += weight
            alternatives[observed_character] += weight
            alternative_raw[observed_character].append(attempt["confidence"])
            if observed_character == reference_character:
                reference_weight += weight
                reference_raw.append(attempt["confidence"])

        positional_agreement = reference_weight / total_weight if total_weight > 0.0 else 0.0
        average_reference_raw = sum(reference_raw) / len(reference_raw) if reference_raw else 0.0
        confidence = clamp(positional_agreement * 0.78 + average_reference_raw * 0.22)

        ranked_alternatives = sorted(alternatives.items(), key=lambda item: item[1], reverse=True)
        best_alternative = ranked_alternatives[0][0] if ranked_alternatives else ""
        best_alternative_share = (
            ranked_alternatives[0][1] / total_weight
            if ranked_alternatives and total_weight > 0.0 else 0.0
        )
        is_locked = confidence > CHARACTER_LOCK_THRESHOLD and observations >= 2
        if is_locked:
            locked[position] = reference_character

        characters.append({
            "position": position,
            "character": reference_character,
            "confidence": confidence,
            "agreement": positional_agreement,
            "votes": len(reference_raw),
            "observations": observations,
            "best_raw_confidence": max(reference_raw) if reference_raw else 0.0,
            "reference_character": reference_character,
            "locked": is_locked,
            "source": "repeated whole-word OCR positional confidence",
            "best_alternative": best_alternative,
            "best_alternative_share": best_alternative_share,
            "alternatives": [
                {
                    "character": character,
                    "share": weight / total_weight if total_weight > 0 else 0.0,
                    "count": len(alternative_raw[character]),
                    "best_raw": max(alternative_raw[character]) if alternative_raw[character] else 0.0,
                }
                for character, weight in ranked_alternatives[:5]
            ],
        })

    available = bool(usable) and any(item.get("observations", 0) >= 2 for item in characters)
    result = {
        "token": word,
        "reference": word,
        "length": len(word),
        "characters": characters,
        "locked": locked,
        "available": available,
        "source": "REPEATED WHOLE-WORD OCR -> per-character positional confidence",
        "geometry": estimate_visible_character_count(image),
        "image": image,
        "attempt_count": len(usable),
    }
    if profile_fully_certain(word, characters):
        result["individual_letter_crops"] = []
        result["letter_crops_skipped"] = True
    else:
        result["individual_letter_crops"] = build_individual_letter_crop_diagnostics(
            word, image, read_positions=open_letter_positions(characters),
        )

    cached = dict(result)
    cached.pop("image", None)
    cached.pop("individual_letter_crops", None)
    cached["characters"] = [dict(item) for item in characters]
    cached["locked"] = dict(locked)
    CHARACTER_PROFILE_CACHE[profile_cache_key] = cached
    return result


def print_word_character_profile_before_candidates(profile):
    if not profile or not profile.get("characters", []):
        print("Per-character confidence before candidates: unavailable")
        return

    print("Per-character confidence BEFORE candidates:")
    pattern = []
    for item in profile.get("characters", []):
        character = item.get("reference_character", "?") or "?"
        confidence = safe_float(item.get("confidence", 0.0))
        state = "LOCKED" if item.get("locked") else "OPEN"
        alternative = item.get("best_alternative", "")
        alt_share = safe_float(item.get("best_alternative_share", 0.0))
        pattern.append(character if item.get("locked") else "?")
        alternative_text = ""
        if alternative and alternative != character:
            alternative_text = f" | strongest alternate={alternative}({alt_share:.3f})"
        print(
            f"  {item.get('position', 0) + 1}: {character} "
            f"confidence={confidence:.3f} [{state}]{alternative_text}"
        )
    print("Candidate lock pattern:", "".join(pattern))
    print(
        "Rule: LOCKED characters must stay in those positions; only ? positions "
        "may change. N+1 may insert one extra character while preserving the "
        "locked sequence."
    )

    letter_crops = profile.get("individual_letter_crops", [])
    if profile.get("letter_crops_skipped"):
        print("INDIVIDUAL LETTER CROPS: skipped (every letter locked and the word is valid English)")
    if any(item.get("not_read") for item in letter_crops):
        read_numbers = [str(item.get("position", 0) + 1) for item in letter_crops if not item.get("not_read")]
        print("LETTER CROPS read only for the ? letters: " + (", ".join(read_numbers) or "none"))
        letter_crops = [item for item in letter_crops if not item.get("not_read")]
    if letter_crops:
        print("INDIVIDUAL LETTER CROPS / ALL OCR LETTER ALTERNATIVES:")
        for item in letter_crops:
            alternatives = item.get("alternatives", [])
            if alternatives:
                alternatives_text = " | ".join(
                    f'{alternative.get("character", "?")}:'
                    f'{safe_float(alternative.get("confidence", 0.0)):.3f} '
                    f'(votes={alternative.get("votes", 0)}, '
                    f'agree={safe_float(alternative.get("agreement", 0.0)):.3f})'
                    for alternative in alternatives
                )
            else:
                alternatives_text = "NO LETTER READ"
            print(
                f'  Crop {item.get("position", 0) + 1} '
                f'(word letter {item.get("reference_character", "?")})'
                f'{connection_text_for(item)}: {alternatives_text}'
            )


def connection_text_for(item):
    bits = []
    if item.get("connected_left", False):
        bits.append("CONNECTED-LEFT")
    if item.get("connected_right", False):
        bits.append("CONNECTED-RIGHT")
    return " [" + ", ".join(bits) + "]" if bits else ""


def get_decision_word_character_profile(decision, word_index):
    """
    Physical character profile for the exact alphabetic word being corrected.
    For mixed tokens such as (0.3%DENT) the matching visual word crop is used.
    """
    current = 0
    for baseline in decision.get("baseline", []):
        baseline_words = alpha_words_from_text(baseline.get("text", ""))
        profile = baseline.get("character_profile")
        for local_word_index, baseline_word in enumerate(baseline_words):
            if current != word_index:
                current += 1
                continue

            word = normalize_alpha_for_matching(baseline_word)
            if not word:
                return None

            if profile:
                reference = re.sub(r"[^A-Z0-9]", "", str(profile.get("reference", "")).upper())
                if (
                    profile.get("available")
                    and len(baseline_words) == 1
                    and reference == word
                    and profile.get("length") == len(word)
                ):
                    return profile

            best_visual = None
            best_score = 0.0
            candidates = []
            refinement = decision.get("refinement") or {}
            candidates.extend(refinement.get("pieces", []) or [])
            candidates.extend(decision.get("visual", []) or [])
            for visual in candidates:
                image = visual.get("image")
                if image is None:
                    continue
                visual_word = normalize_alpha_for_matching(visual.get("text", ""))
                if not visual_word:
                    continue
                score = normalized_edit_similarity(word, visual_word)
                if visual_word == word:
                    score += 0.35
                if len(visual_word) == len(word):
                    score += 0.10
                score += min(visual.get("score", 0.0), 1.0) * 0.10
                if score > best_score:
                    best_score = score
                    best_visual = image

            if best_visual is not None and best_score >= 0.68:
                visual_profile = build_word_character_profile_from_image(word, best_visual)
                if visual_profile:
                    return visual_profile

            if profile and profile.get("available"):
                reference = re.sub(r"[^A-Z0-9]", "", str(profile.get("reference", "")).upper())
                start_position = reference.find(word)
                if start_position >= 0:
                    end_position = start_position + len(word)
                    source_characters = {
                        item.get("position"): item for item in profile.get("characters", [])
                    }
                    sliced_characters = []
                    sliced_locks = {}
                    for new_position, old_position in enumerate(range(start_position, end_position)):
                        source = source_characters.get(old_position)
                        if source is None:
                            item = {
                                "position": new_position,
                                "character": "",
                                "confidence": 0.0,
                                "agreement": 0.0,
                                "votes": 0,
                                "best_raw_confidence": 0.0,
                                "reference_character": word[new_position],
                                "locked": False,
                                "source": "missing sliced character evidence",
                            }
                        else:
                            item = dict(source)
                            item["position"] = new_position
                            item["reference_character"] = word[new_position]
                        if item.get("locked") and item.get("character"):
                            sliced_locks[new_position] = item["character"]
                        sliced_characters.append(item)
                    return {
                        "token": word,
                        "reference": word,
                        "length": len(word),
                        "characters": sliced_characters,
                        "locked": sliced_locks,
                        "available": bool(sliced_characters),
                        "source": str(profile.get("source", "")) + " | sliced to alphabetic word",
                        "geometry": None,
                        "image": profile.get("image"),
                    }
            return None
    return None


def character_lock_violation_count(candidate, character_profile):
    if not character_profile:
        return 0
    locks = character_profile.get("locked", {})
    if not locks:
        return 0
    candidate = normalize_alpha_for_matching(candidate)
    target_length = character_profile.get("length", 0)
    if not candidate or target_length <= 0:
        return 999

    def violations_for_collapsed(collapsed):
        return sum(
            1 for position, character in locks.items()
            if position >= len(collapsed) or collapsed[position] != character
        )

    if len(candidate) == target_length:
        return violations_for_collapsed(candidate)
    if ALLOW_ONE_EXTRA_ENGLISH_CHARACTER and len(candidate) == target_length + 1:
        best = 999
        for extra_position in range(len(candidate)):
            collapsed = candidate[:extra_position] + candidate[extra_position + 1:]
            best = min(best, violations_for_collapsed(collapsed))
        return best
    return 999


def generate_sentence_grammar_rescue_candidates(
    seeds, target_length, character_profile,
    max_candidates=120,
):
    """
    Tightly constrained candidates for the FINAL sentence pass only. May break
    at most ONE lock and must stay very close to the OCR seed.
    """
    normalized_seeds = [
        normalize_alpha_for_matching(seed) for seed in seeds
        if normalize_alpha_for_matching(seed)
    ]
    if not normalized_seeds:
        return []

    results = []
    for length in allowed_english_lengths(target_length):
        for word in lazy_english_words(length):
            violations = character_lock_violation_count(word, character_profile)
            if violations > 1:
                continue
            best_distance = min(levenshtein_distance(seed, word) for seed in normalized_seeds)
            if length == target_length:
                if best_distance > 1:
                    continue
            else:
                if best_distance > 2:
                    continue
            frequency = zipf_frequency(word.lower(), "en")
            if frequency < 2.0:
                continue
            results.append({
                "text": word,
                "lock_violations": violations,
                "edit_distance": best_distance,
                "frequency": frequency,
            })
    results.sort(
        key=lambda item: (-item["lock_violations"], -item["edit_distance"], item["frequency"]),
        reverse=True,
    )
    return results[:max_candidates]


def candidate_respects_character_locks(candidate, character_profile):
    if not character_profile:
        return True
    locks = character_profile.get("locked", {})
    if not locks:
        return True
    candidate = normalize_alpha_for_matching(candidate)
    target_length = character_profile.get("length", 0)
    if not candidate or target_length <= 0:
        return False

    if len(candidate) == target_length:
        return all(
            position < len(candidate) and candidate[position] == character
            for position, character in locks.items()
        )
    if ALLOW_ONE_EXTRA_ENGLISH_CHARACTER and len(candidate) == target_length + 1:
        for extra_position in range(len(candidate)):
            collapsed = candidate[:extra_position] + candidate[extra_position + 1:]
            if all(
                position < len(collapsed) and collapsed[position] == character
                for position, character in locks.items()
            ):
                return True
        return False
    return False


# ============================================================
# ENGLISH LENGTH RULE  (N or N+1, never shorter)
# ============================================================

def english_candidate_length_allowed(candidate_length, target_length):
    if candidate_length == target_length:
        return True
    if ALLOW_ONE_EXTRA_ENGLISH_CHARACTER and candidate_length == target_length + 1:
        return True
    return False


def allowed_english_lengths(target_length):
    lengths = [target_length]
    if ALLOW_ONE_EXTRA_ENGLISH_CHARACTER:
        lengths.append(target_length + 1)
    return lengths


# ============================================================
# GENERAL ENGLISH CANDIDATES
# ============================================================

def max_allowed_edit_distance(target_length):
    # Short words need extra tolerance (WRH -> WITH). The N / N+1 length rule
    # still protects against random longer words.
    if target_length <= 4:
        return 3
    if target_length <= 9:
        return 2
    return 3


def generate_general_english_candidates(
    seeds, target_length, max_candidates=100,
    character_profile=None,
):
    normalized_seeds = [
        normalize_alpha_for_matching(seed) for seed in seeds
        if normalize_alpha_for_matching(seed)
    ]
    if not normalized_seeds:
        return []

    max_edit = max_allowed_edit_distance(target_length)
    candidates = []
    for length in allowed_english_lengths(target_length):
        for word in lazy_english_words(
            length,
            character_profile=character_profile,
            enforce_character_locks=True,
        ):
            best_distance = 999
            best_similarity = 0.0
            best_seed = None
            for seed in normalized_seeds:
                distance = levenshtein_distance(seed, word)
                similarity = normalized_edit_similarity(seed, word)
                if distance < best_distance:
                    best_distance = distance
                    best_similarity = similarity
                    best_seed = seed
                elif distance == best_distance and similarity > best_similarity:
                    best_similarity = similarity
                    best_seed = seed
            if best_distance > max_edit:
                continue
            minimum_similarity = 0.35 if target_length <= 4 else 0.55
            if best_similarity < minimum_similarity:
                continue
            candidates.append({
                "text": word,
                "distance": best_distance,
                "similarity": best_similarity,
                "seed": best_seed,
                "length": len(word),
                "extra_character": len(word) == target_length + 1,
                "frequency": zipf_frequency(word.lower(), "en"),
            })

    candidates.sort(key=lambda item: (
        item["distance"],
        item["extra_character"],
        -item["similarity"],
        -item["frequency"],
    ))

    return candidates[:max_candidates]


def score_candidate_against_ocr_evidence(candidate, evidence):
    if not evidence:
        return 0.0
    similarities = []
    for observed, weight in evidence:
        observed = normalize_alpha_for_matching(observed)
        if not observed:
            continue
        similarities.append((
            normalized_edit_similarity(candidate, observed),
            max(0.05, weight),
        ))
    if not similarities:
        return 0.0
    similarities.sort(key=lambda item: item[0], reverse=True)
    selected = similarities[:8]
    total_weight = sum(weight for similarity, weight in selected)
    if total_weight <= 0:
        return 0.0
    return sum(similarity * weight for similarity, weight in selected) / total_weight


def candidate_exact_ocr_support(candidate, evidence):
    candidate = normalize_alpha_for_matching(candidate)
    support = 0.0
    for observed, weight in evidence:
        if normalize_alpha_for_matching(observed) == candidate:
            support += weight
    return clamp(support / 3.0)


# ============================================================
# ENGLISH FREQUENCY
# ============================================================

def english_frequency_score(word):
    return clamp((zipf_frequency(word.lower(), "en") - 1.0) / 5.5)


def phrase_frequency_raw(phrase):
    if not phrase:
        return 0.0
    try:
        return float(zipf_frequency(phrase.lower(), "en"))
    except Exception:
        return 0.0


def phrase_frequency_score(phrase):
    return clamp((phrase_frequency_raw(phrase) - 1.0) / 5.5)


# ============================================================
# FLATTEN SENTENCE WORDS
# ============================================================

def get_all_current_alpha_words(decisions):
    output = []
    for decision_index, decision in enumerate(decisions):
        for word_index, word in enumerate(alpha_words_from_text(decision.get("text", ""))):
            output.append({
                "decision_index": decision_index,
                "word_index": word_index,
                "word": word,
            })
    return output


def get_word_neighbors(decisions, decision_index, word_index):
    flattened = get_all_current_alpha_words(decisions)
    position = None
    for index, item in enumerate(flattened):
        if item["decision_index"] == decision_index and item["word_index"] == word_index:
            position = index
            break
    if position is None:
        return None, None
    left = flattened[position - 1]["word"] if position > 0 else None
    right = flattened[position + 1]["word"] if position < len(flattened) - 1 else None
    return left, right


def contextual_phrase_score(candidate, left_word, right_word):
    scores = []
    if left_word:
        scores.append(phrase_frequency_score(f"{left_word} {candidate}"))
    if right_word:
        scores.append(phrase_frequency_score(f"{candidate} {right_word}"))
    if left_word and right_word:
        scores.append(phrase_frequency_score(f"{left_word} {candidate} {right_word}"))
    if not scores:
        return english_frequency_score(candidate)
    return max(scores) * 0.65 + (sum(scores) / len(scores)) * 0.35


# ============================================================
# INITIAL ENGLISH CANDIDATE SCORING
# ============================================================

def score_english_candidate(candidate, current_word, target_length, evidence, left_word, right_word):
    candidate_text = candidate["text"]
    candidate_length = len(candidate_text)
    if not english_candidate_length_allowed(candidate_length, target_length):
        return None

    if candidate_length == target_length:
        length_score = 1.0
        extra_character = False
    else:
        length_score = 0.90
        extra_character = True

    ocr_score = score_candidate_against_ocr_evidence(candidate_text, evidence)
    exact_ocr_support = candidate_exact_ocr_support(candidate_text, evidence)
    frequency_score = english_frequency_score(candidate_text)
    context_score = contextual_phrase_score(candidate_text, left_word, right_word)
    current_similarity = normalized_edit_similarity(candidate_text, current_word)

    total = (
        ocr_score * 0.36
        + length_score * 0.14
        + frequency_score * 0.14
        + context_score * 0.23
        + current_similarity * 0.08
        + exact_ocr_support * 0.05
    )
    if not extra_character:
        total += 0.015
    else:
        if context_score > 0.50:
            total += 0.025
        if exact_ocr_support > 0.05:
            total += 0.035
    if ocr_score < 0.58:
        total -= 0.18

    return {
        "text": candidate_text,
        "score": total,
        "ocr_score": ocr_score,
        "exact_ocr_support": exact_ocr_support,
        "length": candidate_length,
        "target_length": target_length,
        "extra_character": extra_character,
        "length_score": length_score,
        "frequency": zipf_frequency(candidate_text.lower(), "en"),
        "frequency_score": frequency_score,
        "context_score": context_score,
        "current_similarity": current_similarity,
        "edit_distance": levenshtein_distance(current_word, candidate_text),
    }


# ============================================================
# CORRECT ONE WORD - INITIAL PASS
# ============================================================

def fully_locked_valid_english_word(word, character_profile, minimum_zipf=2.3):
    """Skip candidate search when every position is locked and word is English."""
    word = normalize_alpha_for_matching(word)
    if (
        not word
        or character_profile is None
        or not character_profile.get("available", False)
    ):
        return False
    target_length = int(character_profile.get("length", 0) or 0)
    if target_length <= 0 or target_length != len(word):
        return False
    locked = character_profile.get("locked", {}) or {}
    if len(locked) != target_length:
        return False
    for position, character in enumerate(word):
        if normalize_alpha_for_matching(locked.get(position, "")) != character:
            return False
    return zipf_frequency(word.lower(), "en") >= minimum_zipf


def pure_nplus1_insertion_candidates(current_word, character_profile):
    """Real English words formed by inserting exactly ONE character."""
    current_word = normalize_alpha_for_matching(current_word)
    if not current_word:
        return []
    output = []
    for candidate_word in lazy_english_words(
        len(current_word) + 1,
        character_profile=character_profile,
        insertion_base=current_word,
        enforce_character_locks=True,
    ):
        insertion_positions = [
            remove_index for remove_index in range(len(candidate_word))
            if candidate_word[:remove_index] + candidate_word[remove_index + 1:] == current_word
        ]
        if not insertion_positions:
            continue
        output.append({
            "text": candidate_word,
            "insertion_positions": insertion_positions,
            "frequency": zipf_frequency(candidate_word.lower(), "en"),
        })
    return output


def nplus1_physical_segmentation_hypotheses(
    current_word, image, character_profile, evidence, maximum_candidates=12,
):
    """
    When geometry says a character may have been dropped, compare the N-letter
    segmentation against N+1 English candidates, each segmented as itself.
    """
    current_word = normalize_alpha_for_matching(current_word)
    nothing = {"geometry_supports_nplus1": False, "current": None, "candidates": []}
    if not current_word or image is None or not character_profile:
        return nothing
    if not strong_visible_nplus1_geometry(current_word, character_profile):
        return nothing

    current_physical = candidate_individual_letter_support(current_word, image)
    nplus_words = lazy_english_words(
        len(current_word) + 1,
        character_profile=character_profile,
        insertion_base=current_word,
        enforce_character_locks=True,
    )

    ocr_scores = {}
    for candidate_word in nplus_words:
        candidate_word = normalize_alpha_for_matching(candidate_word)
        if candidate_word:
            ocr_scores[candidate_word] = score_candidate_against_ocr_evidence(candidate_word, evidence)
    if ocr_scores:
        best_ocr = max(ocr_scores.values())
        close = [w for w, value in ocr_scores.items() if value >= best_ocr - NPLUS1_OCR_WINDOW]
        if len(close) < len(ocr_scores):
            print(f"N+1 CHECK: {len(close)} of {len(ocr_scores)} candidate(s) within {NPLUS1_OCR_WINDOW:.2f} "
                  f"of the best OCR score -> only those get letter crops: {', '.join(close)}")
        nplus_words = close
    ranked = []
    for candidate_word in nplus_words:
        candidate_word = normalize_alpha_for_matching(candidate_word)
        if not candidate_word:
            continue
        candidate_physical = candidate_individual_letter_support(candidate_word, image)
        candidate_ocr = ocr_scores.get(candidate_word, score_candidate_against_ocr_evidence(candidate_word, evidence))
        similarity = normalized_edit_similarity(current_word, candidate_word)
        score = clamp(
            candidate_physical.get("score", 0.0) * 0.60
            + candidate_ocr * 0.30
            + similarity * 0.10
        )
        ranked.append({
            "text": candidate_word,
            "score": score,
            "physical": safe_float(candidate_physical.get("score", 0.0)),
            "coverage": safe_float(candidate_physical.get("coverage", 0.0)),
            "strong_matches": int(candidate_physical.get("strong_matches", 0) or 0),
            "ocr": candidate_ocr,
            "similarity": similarity,
            "physical_gain": (
                safe_float(candidate_physical.get("score", 0.0))
                - safe_float(current_physical.get("score", 0.0))
            ),
            "diagnostics": candidate_physical.get("diagnostics", []),
        })
    ranked.sort(key=lambda item: (item["score"], item["physical"], item["ocr"]), reverse=True)

    geometry = character_profile.get("geometry", {}) or {}
    print()
    print("=" * 70)
    print("DUAL PHYSICAL SEGMENTATION: N vs N+1")
    print("=" * 70)
    print("Current OCR word:", current_word, "| N=", len(current_word))
    print(
        "Visible character estimate:",
        round(safe_float(geometry.get("count", 0.0)), 2),
        "| reliability=", round(safe_float(geometry.get("reliability", 0.0)), 3),
    )
    print(
        "Current N-letter physical support:",
        round(safe_float(current_physical.get("score", 0.0)), 3),
    )
    for item in ranked[:maximum_candidates]:
        print(
            "  N+1 candidate:", item["text"],
            "| physical=", round(item["physical"], 3),
            "| physical gain=", round(item["physical_gain"], 3),
            "| OCR=", round(item["ocr"], 3),
            "| total=", round(item["score"], 3),
        )
        for crop in item.get("diagnostics", []):
            alternatives = crop.get("alternatives", []) or []
            alternatives_text = (
                " | ".join(
                    f'{alternative.get("character", "?")}:'
                    f'{safe_float(alternative.get("confidence", 0.0)):.3f}'
                    for alternative in alternatives
                )
                if alternatives else "NO LETTER READ"
            )
            print(
                f'      crop {crop.get("position", 0) + 1} '
                f'({crop.get("reference_character", "?")})'
                f'{connection_text_for(crop)}: {alternatives_text}'
            )

    return {
        "geometry_supports_nplus1": True,
        "current": {
            "text": current_word,
            "physical": safe_float(current_physical.get("score", 0.0)),
            "diagnostics": current_physical.get("diagnostics", []),
        },
        "candidates": ranked[:maximum_candidates],
    }


def choose_physical_nplus1_word_before_language(current_word, image, character_profile, evidence):
    """EARLY N-vs-N+1 decision, before any language model."""
    comparison = nplus1_physical_segmentation_hypotheses(
        current_word, image, character_profile, evidence,
    )
    if not comparison.get("geometry_supports_nplus1", False) or not comparison.get("candidates"):
        return None

    current_physical = safe_float((comparison.get("current") or {}).get("physical", 0.0))
    best = comparison["candidates"][0]
    if (
        best["ocr"] >= 0.56
        and best["physical"] >= 0.30
        and (
            best["physical_gain"] >= 0.06
            or (current_physical < 0.32 and best["physical"] >= 0.38)
        )
    ):
        print(
            "EARLY PHYSICAL N+1 WORD RESCUE:", current_word, "->", best["text"],
            "| N physical=", round(current_physical, 3),
            "| N+1 physical=", round(best["physical"], 3),
        )
        return best
    print("Dual segmentation result: N-letter word retained physically.")
    return None


CONTEXT_NPLUS1_MIN_GAIN = 0.01   # S36: the rescue needs the longer word to read better in context


def best_contextual_nplus1_rescue(current_word, left_word, right_word, evidence, character_profile):
    """N+1 only as a PHYSICAL OCR hypothesis; context is a tie-breaker."""
    current_word = normalize_alpha_for_matching(current_word)
    if len(current_word) < 2:
        return None

    current_context = contextual_phrase_score(current_word, left_word, right_word)
    image = character_profile.get("image") if character_profile else None
    geometry = (character_profile.get("geometry", {}) if character_profile else {}) or {}
    geometry_count = safe_float(geometry.get("count", 0.0))
    geometry_reliability = safe_float(geometry.get("reliability", 0.0))
    geometry_supports_nplus1 = strong_visible_nplus1_geometry(current_word, character_profile)
    current_physical = candidate_individual_letter_support(current_word, image)

    candidates = pure_nplus1_insertion_candidates(current_word, character_profile)
    if not candidates:
        return None

    ranked = []
    for candidate in candidates:
        candidate_text = candidate["text"]
        context_score = contextual_phrase_score(candidate_text, left_word, right_word)
        ocr_score = score_candidate_against_ocr_evidence(candidate_text, evidence)
        frequency_score = english_frequency_score(candidate_text)
        similarity = normalized_edit_similarity(candidate_text, current_word)
        candidate_physical = candidate_individual_letter_support(candidate_text, image)
        physical_gain = candidate_physical["score"] - current_physical["score"]
        score = clamp(
            candidate_physical["score"] * 0.42
            + ocr_score * 0.26
            + context_score * 0.20
            + similarity * 0.08
            + frequency_score * 0.04
        )
        ranked.append({
            **candidate,
            "context_score": context_score,
            "ocr_score": ocr_score,
            "frequency_score": frequency_score,
            "similarity": similarity,
            "score": score,
            "context_gain": context_score - current_context,
            "physical_support": candidate_physical["score"],
            "physical_coverage": candidate_physical["coverage"],
            "physical_strong_matches": candidate_physical["strong_matches"],
            "current_physical_support": current_physical["score"],
            "physical_gain": physical_gain,
        })
    ranked.sort(
        key=lambda item: (
            item["score"], item["physical_support"], item["ocr_score"], item["context_score"],
        ),
        reverse=True,
    )
    best = ranked[0]

    geometry_accept = (
        geometry_supports_nplus1
        and best["ocr_score"] >= 0.56
        and best["similarity"] >= 0.80
    )
    physical_accept = (
        best["physical_gain"] >= 0.12
        and best["physical_support"] >= 0.38
        and best["ocr_score"] >= 0.56
        and best["similarity"] >= 0.80
    )
    if not (geometry_accept or physical_accept):
        return None

    best["geometry_supports_nplus1"] = geometry_supports_nplus1
    best["geometry_count"] = geometry_count
    best["geometry_reliability"] = geometry_reliability
    return best


def correct_single_english_word(current_word, evidence, left_word, right_word, character_profile=None):
    current_word = normalize_alpha_for_matching(current_word)
    if len(current_word) < 2:
        return {
            "before": current_word,
            "after": current_word,
            "changed": False,
            "target_length": len(current_word),
            "allowed_lengths": [len(current_word)],
            "candidates": [],
        }

    if character_profile and character_profile.get("length", 0) > 0:
        target_length = character_profile["length"]
    else:
        target_length = consensus_ocr_word_length(current_word, evidence)

    allowed_lengths = allowed_english_lengths(target_length)
    current_frequency = zipf_frequency(current_word.lower(), "en")

    if fully_locked_valid_english_word(current_word, character_profile, minimum_zipf=2.3):
        return {
            "before": current_word,
            "after": current_word,
            "changed": False,
            "target_length": target_length,
            "allowed_lengths": allowed_lengths,
            "current_frequency": current_frequency,
            "candidates": [],
            "reason": (
                "Candidate search skipped - every character is hard-locked "
                "and current word is valid English"
            ),
            "fully_locked_skip": True,
        }

    seeds = {current_word}
    for observed, weight in evidence:
        observed = normalize_alpha_for_matching(observed)
        if observed:
            seeds.add(observed)

    if character_profile is not None and not character_profile.get("available", False):
        return {
            "before": current_word,
            "after": current_word,
            "changed": False,
            "target_length": target_length,
            "allowed_lengths": allowed_lengths,
            "candidates": [],
            "reason": "Character profile unavailable - dictionary search blocked",
        }

    candidates = generate_general_english_candidates(
        seeds, target_length, max_candidates=100, character_profile=character_profile,
    )

    agreeing_reads, total_reads = whole_line_word_agreement(current_word)
    whole_line_certain = (
        total_reads >= WHOLE_LINE_AGREEMENT_MIN_READS
        and agreeing_reads / total_reads >= WHOLE_LINE_AGREEMENT_MIN_SHARE
        and current_frequency >= 2.3
    )
    if whole_line_certain:
        print(f"WHOLE-LINE AGREEMENT: {current_word} spelled exactly in {agreeing_reads}/{total_reads} "
              "whole-line reads -> N+1 (extra letter) check skipped")
        allowed_lengths = [target_length]
        candidates = [c for c in candidates if len(c["text"]) == target_length]

    if ALLOW_ONE_EXTRA_ENGLISH_CHARACTER and not whole_line_certain:
        for candidate_word in lazy_english_words(
            target_length + 1,
            character_profile=character_profile,
            insertion_base=current_word,
            enforce_character_locks=True,
        ):
            candidates.append({
                "text": candidate_word,
                "distance": 1,
                "similarity": SequenceMatcher(None, current_word, candidate_word, autojunk=False).ratio(),
                "seed": current_word,
                "length": len(candidate_word),
                "extra_character": True,
                "frequency": zipf_frequency(candidate_word.lower(), "en"),
            })

    if (
        english_candidate_length_allowed(len(current_word), target_length)
        and candidate_respects_character_locks(current_word, character_profile)
    ):
        candidates.append({
            "text": current_word,
            "distance": 0,
            "similarity": 1.0,
            "seed": current_word,
            "length": len(current_word),
            "extra_character": len(current_word) == target_length + 1,
            "frequency": current_frequency,
        })

    unique = {}
    for candidate in candidates:
        if whole_line_certain and len(candidate["text"]) != target_length:
            continue
        if english_candidate_length_allowed(len(candidate["text"]), target_length):
            unique[candidate["text"]] = candidate

    scored = []
    for candidate in unique.values():
        result = score_english_candidate(
            candidate, current_word, target_length, evidence, left_word, right_word,
        )
        if result is not None:
            scored.append(result)
    scored.sort(
        key=lambda item: (item["score"], item["context_score"], item["ocr_score"], item["frequency"]),
        reverse=True,
    )

    if not scored:
        return {
            "before": current_word,
            "after": current_word,
            "changed": False,
            "target_length": target_length,
            "allowed_lengths": allowed_lengths,
            "candidates": [],
        }

    best = scored[0]
    current_scored = next((item for item in scored if item["text"] == current_word), None)
    current_score = current_scored["score"] if current_scored is not None else -999.0
    improvement = best["score"] - current_score
    current_is_real_word = current_frequency >= 2.3

    early_nplus1 = None if whole_line_certain else choose_physical_nplus1_word_before_language(
        current_word,
        character_profile.get("image") if character_profile else None,
        character_profile,
        evidence,
    )
    if early_nplus1 is not None:
        return {
            "before": current_word,
            "after": early_nplus1["text"],
            "changed": True,
            "target_length": target_length,
            "allowed_lengths": allowed_lengths,
            "reason": "Early physical N-vs-N+1 segmentation favored longer word",
            "candidates": [{
                "text": early_nplus1["text"],
                "score": early_nplus1["score"],
                "ocr_score": early_nplus1["ocr"],
                "length": len(early_nplus1["text"]),
                "context_score": 0.0,
                "frequency": zipf_frequency(early_nplus1["text"].lower(), "en"),
                "physical_score": early_nplus1["physical"],
                "physical_gain": early_nplus1["physical_gain"],
            }],
            "character_profile": character_profile,
        }

    should_replace = False

    if current_is_real_word and not whole_line_certain:
        contextual_nplus1 = best_contextual_nplus1_rescue(
            current_word, left_word, right_word, evidence, character_profile,
        )
        if contextual_nplus1 is not None and contextual_nplus1["context_gain"] < CONTEXT_NPLUS1_MIN_GAIN:
            print(
                "Contextual N+1 phrase rescue NOT used:", current_word, "->", contextual_nplus1["text"],
                "| context gain=", round(contextual_nplus1["context_gain"], 3),
                f"(needs >= {CONTEXT_NPLUS1_MIN_GAIN}: the longer word does not read better in its sentence)",
            )
            contextual_nplus1 = None
        if contextual_nplus1 is not None:
            existing = next(
                (item for item in scored if item.get("text") == contextual_nplus1.get("text")),
                None,
            )
            if existing is None:
                existing = score_english_candidate(
                    {"text": contextual_nplus1["text"]},
                    current_word, target_length, evidence, left_word, right_word,
                )
                if existing is not None:
                    scored.append(existing)
            if existing is not None:
                best = existing
                improvement = best["score"] - current_score
                should_replace = True
                print(
                    "Contextual N+1 phrase rescue:", current_word, "->", best["text"],
                    "| context gain=", round(contextual_nplus1["context_gain"], 3),
                    "| geometry N+1=", contextual_nplus1.get("geometry_supports_nplus1", False),
                    "| visible count=", round(contextual_nplus1.get("geometry_count", 0.0), 2),
                    "| candidate physical=", round(contextual_nplus1.get("physical_support", 0.0), 3),
                    "| current physical=", round(contextual_nplus1.get("current_physical_support", 0.0), 3),
                )

    if (
        not should_replace
        and best["text"] != current_word
        and best["ocr_score"] >= 0.62
        and best["score"] >= 0.57
        and improvement >= 0.015
    ):
        should_replace = True

    if (
        not should_replace
        and not current_is_real_word
        and best["text"] != current_word
        and best["ocr_score"] >= 0.58
        and best["context_score"] >= 0.40
        and best["score"] >= 0.54
        and improvement >= 0.0
    ):
        should_replace = True

    return {
        "before": current_word,
        "after": best["text"] if should_replace else current_word,
        "changed": should_replace,
        "target_length": target_length,
        "allowed_lengths": allowed_lengths,
        "current_frequency": current_frequency,
        "best": best,
        "current_score": current_score,
        "improvement": improvement,
        "candidates": scored[:10],
    }


# ============================================================
# MIXED ALPHANUMERIC OCR WORD REPAIR
# ============================================================
# A handwritten English WORD may not contain digits (L0SS, D1GS, S6AM).
# Pure numeric structures (65.0%, 4:33, coordinates) are left alone.

def decision_neighbor_words_for_whole_token(decisions, decision_index):
    left_word = None
    right_word = None
    for index in range(decision_index - 1, -1, -1):
        words = alpha_words_from_text(decisions[index].get("text", ""))
        if words:
            left_word = words[-1]
            break
    for index in range(decision_index + 1, len(decisions)):
        words = alpha_words_from_text(decisions[index].get("text", ""))
        if words:
            right_word = words[0]
            break
    return left_word, right_word


# Digit -> letters it is commonly mistaken for in handwriting OCR.
DIGIT_READ_AS_LETTERS = {
    "0": ["O", "D", "Q"], "1": ["I", "L", "T"], "2": ["Z"], "3": ["B", "E"],
    "4": ["A"], "5": ["S"], "6": ["G", "B"], "7": ["T"], "8": ["B"], "9": ["G", "Q"],
}


def lookalike_first_word_candidates(token):
    """
    Letters+digits token -> English word candidates, in this order:
      1. LOOK-ALIKES: swap each digit for the letters it looks like
         (L055 -> LOSS, DI6S -> DIGS). Real words found here win.
      2. CLOSE WORDS: if no look-alike version is a word, real words one letter
         away from a look-alike version (L0SE -> LOSE).
      3. ANY LETTER: only when MOST of the token is digits (most of the word is
         unknown) - every English word with the known letters in place.
    Returns (candidates, stage) - candidates are dicts with text/frequency/swaps.
    """
    compact = re.sub(r"[^A-Z0-9]", "", str(token or "").upper())
    if len(compact) < 2 or not re.search(r"[A-Z]", compact) or not re.search(r"[0-9]", compact):
        return [], None

    versions = [""]
    for ch in compact:
        options = DIGIT_READ_AS_LETTERS.get(ch, [ch]) if ch.isdigit() else [ch]
        versions = [v + o for v in versions for o in options][:64]

    def swaps_for(word):
        return ", ".join(f"{d}->{word[i]}" for i, d in enumerate(compact) if d.isdigit())

    found = {}
    for version in versions:
        frequency = zipf_frequency(version.lower(), "en")
        if frequency >= 2.5:
            found[version] = {"text": version, "frequency": frequency, "swaps": swaps_for(version)}
    if found:
        return sorted(found.values(), key=lambda c: -c["frequency"]), "look-alike"

    for version in versions[:16]:
        for position in range(len(version)):
            pattern = version[:position] + "0" + version[position + 1:]     # digit = wildcard
            for word in lazy_english_words(len(pattern), mixed_pattern=pattern):
                word = word.upper()
                if word == version or word in found:
                    continue
                frequency = zipf_frequency(word.lower(), "en")
                if frequency >= 3.0:
                    found[word] = {"text": word, "frequency": frequency,
                                   "swaps": f"one letter from {version}"}
    if found:
        return sorted(found.values(), key=lambda c: -c["frequency"])[:40], "close word"

    digits = sum(ch.isdigit() for ch in compact)
    if digits * 2 < len(compact):
        return [], None              # most of the word is known: do not guess wildly
    output = []
    for word in lazy_english_words(len(compact), mixed_pattern=compact):
        frequency = zipf_frequency(word.lower(), "en")
        if frequency >= 2.3:
            output.append({"text": word.upper(), "frequency": frequency, "swaps": "any letter"})
    return output, ("any letter" if output else None)


def is_number_shaped_token(raw_token):
    """34.O% / 0O:37: a NUMBER with letter look-alikes - handled in the number direction."""
    core = str(raw_token).strip("()")
    digits = sum(ch.isdigit() for ch in core)
    letters = [ch for ch in core.upper() if ch.isalpha()]
    return bool(digits and re.search(r"[.:%]", core) and letters
                and all(ch in "OQDILSBZ" for ch in letters) and len(letters) <= digits)


def mixed_alphanumeric_word_candidates(token):
    """English candidates for a letters+digits token - look-alikes first (see above)."""
    compact = re.sub(r"[^A-Z0-9]", "", str(token or "").upper())
    candidates, stage = lookalike_first_word_candidates(compact)
    if candidates:
        print(f"LOOK-ALIKE FIRST: {compact} -> {stage}: "
              + ", ".join(f"{c['text']} ({c['swaps']})" for c in candidates[:6]))
    fixed_positions = sum(1 for character in compact if character.isalpha())
    return [{**c, "fixed_positions": fixed_positions} for c in candidates]


def repair_mixed_alphanumeric_word_decisions(decisions):
    """Whole-decision repair when OCR inserted digits into a handwritten word."""
    for decision_index, decision in enumerate(decisions):
        raw_text = str(decision.get("text", "")).strip()
        if re.search(r"\s", raw_text):
            # Several separate pieces ('7 165 IN'): normalize_token would delete the
            # spaces and repair them as ONE word (7165IN -> WITHIN). Never merge them.
            continue
        original = normalize_token(raw_text)
        if not re.fullmatch(r"[A-Za-z0-9]+", original):
            continue
        candidates = mixed_alphanumeric_word_candidates(original)
        if not candidates:
            continue

        left_word, right_word = decision_neighbor_words_for_whole_token(decisions, decision_index)

        physical_image = None
        visual_items = [item for item in decision.get("visual", []) if item.get("image") is not None]
        if visual_items:
            physical_image = combine_images_horizontal(
                [item["image"] for item in visual_items], gap=0,
            )

        ranked = []
        for candidate in candidates:
            candidate_text = candidate["text"]
            context_score = contextual_phrase_score(candidate_text, left_word, right_word)
            frequency_score = english_frequency_score(candidate_text)
            physical_support = 0.0
            if physical_image is not None:
                try:
                    candidate_profile = build_word_character_profile_from_image(candidate_text, physical_image)
                except Exception:
                    candidate_profile = None
                if candidate_profile and candidate_profile.get("available", False):
                    character_values = [
                        safe_float(item.get("confidence", 0.0))
                        for item in candidate_profile.get("characters", [])
                    ]
                    if character_values:
                        physical_support = sum(character_values) / len(character_values)
            # A digit usually stands for the letter it LOOKS like (6->G, 5->S, 1->I/L, 0->O):
            # candidates using those letters at the digit positions get a bonus.
            digit_positions = [i for i, ch in enumerate(original) if ch.isdigit()]
            lookalike_share = 0.0
            if digit_positions and len(candidate_text) == len(original):
                hits = sum(
                    1 for i in digit_positions
                    if candidate_text[i].upper() in DIGIT_LOOKALIKE_LETTERS.get(original[i], [])
                )
                lookalike_share = hits / len(digit_positions)
            score = clamp(
                physical_support * 0.64 + context_score * 0.26 + frequency_score * 0.10
                + lookalike_share * 0.15
            )
            ranked.append({
                **candidate,
                "context_score": context_score,
                "frequency_score": frequency_score,
                "physical_support": physical_support,
                "lookalike": lookalike_share,
                "score": score,
            })

        ranked.sort(
            key=lambda item: (
                item["score"], item["physical_support"], item["context_score"], item["frequency"],
            ),
            reverse=True,
        )
        if not ranked:
            continue
        best = ranked[0]

        print()
        print("Mixed-token physical candidate ranking for", original)
        for item in ranked[:8]:
            print(
                "   ", item["text"],
                "| physical=", round(item.get("physical_support", 0.0), 3),
                "| context=", round(item.get("context_score", 0.0), 3),
                "| freq=", round(item.get("frequency_score", 0.0), 3),
                "| look-alike=", round(item.get("lookalike", 0.0), 2),
                "| total=", round(item.get("score", 0.0), 3),
            )

        decision["mixed_alphanumeric_before"] = original
        decision["mixed_alphanumeric_candidates"] = ranked[:8]
        decision["text"] = best["text"]
        decision["source"] = (
            "Whole mixed alphanumeric OCR token repaired using fixed letters "
            "+ digit wildcards + English context"
        )
        print("Mixed alphanumeric whole-token repair:", original, "->", best["text"])
    return decisions


def is_wordlike_mixed_alphanumeric_token(token):
    if is_number_shaped_token(str(token or "")):
        return False            # 34.O% / 0O:37 are numbers - fixed in the number direction, not as words
    token = normalize_token(token)
    if not token:
        return False
    compact = re.sub(r"[^A-Z0-9]", "", token.upper())
    return bool(
        len(compact) >= 2
        and re.search(r"[A-Z]", compact)
        and re.search(r"[0-9]", compact)
    )


def mixed_token_candidate_score(candidate_word, left_word=None, right_word=None):
    candidate_word = normalize_alpha_for_matching(candidate_word)
    if not candidate_word:
        return 0.0
    context_score = contextual_phrase_score(candidate_word, left_word, right_word)
    frequency_score = english_frequency_score(candidate_word)
    return clamp(context_score * 0.62 + frequency_score * 0.38)


def choose_mixed_token_english_replacement(token, left_word=None, right_word=None):
    """Resolve a letters+digits token to a letters-only English word."""
    normalized = normalize_token(token)
    compact = re.sub(r"[^A-Z0-9]", "", normalized.upper())
    if not is_wordlike_mixed_alphanumeric_token(normalized):
        return None

    candidates = mixed_alphanumeric_word_candidates(compact)

    # Allow ONE alphabetic OCR mismatch if the strict pattern finds nothing.
    if not candidates:
        relaxed = []
        for word in lazy_english_words(len(compact)):
            if not re.fullmatch(r"[A-Z]+", word):
                continue
            alphabetic_mismatches = sum(
                1 for observed, proposed in zip(compact, word)
                if not observed.isdigit() and observed != proposed
            )
            if alphabetic_mismatches > 1:
                continue
            frequency = zipf_frequency(word.lower(), "en")
            if frequency < 2.3:
                continue
            relaxed.append({
                "text": word,
                "frequency": frequency,
                "fixed_positions": sum(1 for character in compact if character.isalpha()),
                "relaxed_alphabetic_mismatches": alphabetic_mismatches,
            })
        candidates = relaxed

    ranked = []
    for candidate in candidates:
        word = normalize_alpha_for_matching(candidate.get("text", ""))
        if not word or not re.fullmatch(r"[A-Z]+", word):
            continue
        score = mixed_token_candidate_score(word, left_word, right_word)
        score -= safe_float(candidate.get("relaxed_alphabetic_mismatches", 0)) * 0.12
        ranked.append({
            **candidate,
            "text": word,
            "score": score,
            "context_score": contextual_phrase_score(word, left_word, right_word),
        })
    if not ranked:
        return None
    ranked.sort(
        key=lambda item: (
            item.get("score", 0.0), item.get("context_score", 0.0), item.get("frequency", 0.0),
        ),
        reverse=True,
    )
    return {"before": normalized, "after": ranked[0]["text"], "candidates": ranked[:8]}


def merge_mixed_tokens_with_whole_line_evidence(decisions, whole_attempts):
    """Fill digit positions of a mixed token from repeated whole-line reads."""
    if not decisions:
        return decisions

    evidence_tokens = []
    for attempt in whole_attempts or []:
        evidence_tokens.extend(
            re.findall(r"[A-Z0-9]+", normalize_line(attempt.get("text", "")).upper())
        )

    for decision in decisions:
        for raw_token in re.findall(r"\S+", str(decision.get("text", ""))):
            core = re.sub(r"[^A-Z0-9]", "", raw_token.upper())
            # Checked on the RAW token: stripping the colon first made a time
            # like 0O:37 look like the word-ish token 0O37 (it then became LOS7).
            if is_number_shaped_token(raw_token) or not is_wordlike_mixed_alphanumeric_token(raw_token):
                continue

            compatible = []
            for candidate in evidence_tokens:
                if len(candidate) != len(core):
                    continue
                if not (re.search(r"[A-Z]", candidate) and re.search(r"[0-9]", candidate)):
                    continue
                conflicts = 0
                agreements = 0
                for observed, other in zip(core, candidate):
                    if observed.isalpha() and other.isalpha():
                        if observed == other:
                            agreements += 1
                        else:
                            conflicts += 1
                if conflicts <= 1 and agreements >= 1:
                    compatible.append(candidate)
            if not compatible:
                continue

            merged = []
            for position, original in enumerate(core):
                if original.isalpha():
                    merged.append(original)
                    continue
                votes = defaultdict(int)
                for candidate in compatible:
                    character = candidate[position]
                    if character.isalpha():
                        votes[character] += 1
                if votes:
                    best_character, best_votes = max(votes.items(), key=lambda item: item[1])
                    merged.append(best_character if best_votes >= 2 else original)
                else:
                    merged.append(original)

            merged_core = "".join(merged)
            if merged_core == core:
                continue

            current_text = str(decision.get("text", ""))
            replacement_token = re.sub(
                re.escape(core), merged_core, raw_token, count=1, flags=re.IGNORECASE,
            )
            pattern = re.compile(r"(?<!\S)" + re.escape(raw_token) + r"(?!\S)", re.IGNORECASE)
            new_text, count = pattern.subn(replacement_token, current_text, count=1)
            if count:
                decision["text"] = new_text
                decision["source"] = (
                    str(decision.get("source", "")) + " | repeated whole-line mixed-token evidence"
                ).strip(" |")
                print(
                    "MIXED TOKEN WHOLE-LINE EVIDENCE:", core, "+",
                    sorted(set(compatible)), "->", merged_core,
                )
    return decisions


def apply_repeated_whole_line_missing_character_rescue(decisions, whole_attempts):
    """N+1 recovery when 3+ whole-line reads agree on a one-letter-longer word."""
    if not decisions:
        return decisions

    flat = []
    for decision_index, decision in enumerate(decisions):
        for raw_token in re.findall(r"\S+", str(decision.get("text", ""))):
            word = normalize_alpha_for_matching(raw_token)
            if word:
                flat.append({"decision_index": decision_index, "raw_token": raw_token, "word": word})

    for flat_index, record in enumerate(flat):
        current = record["word"]
        if not current or flat_index + 1 >= len(flat):
            continue
        following_word = flat[flat_index + 1]["word"]
        votes = defaultdict(int)

        for attempt in whole_attempts or []:
            words = [
                normalize_alpha_for_matching(token)
                for token in re.findall(r"[A-Za-z]+", str(attempt.get("text", "")))
            ]
            words = [word for word in words if word]
            for index in range(len(words) - 1):
                candidate = words[index]
                if words[index + 1] != following_word:
                    continue
                if len(candidate) != len(current) + 1:
                    continue
                if any(
                    candidate[:remove_index] + candidate[remove_index + 1:] == current
                    for remove_index in range(len(candidate))
                ):
                    votes[candidate] += 1

        if not votes:
            continue
        candidate, vote_count = max(votes.items(), key=lambda item: item[1])
        if vote_count < 3:
            continue

        decision = decisions[record["decision_index"]]
        before = str(decision.get("text", ""))
        raw_token = record["raw_token"]
        pattern = re.compile(r"(?<!\S)" + re.escape(raw_token) + r"(?!\S)", re.IGNORECASE)
        after, count = pattern.subn(candidate, before, count=1)
        if count:
            decision["text"] = after
            decision["source"] = (
                str(decision.get("source", "")) + " | repeated whole-line N+1 token recovery"
            ).strip(" |")
            print(
                "REPEATED WHOLE-LINE N+1 TOKEN RECOVERY:", before, "->", after,
                "| votes=", vote_count,
            )
    return decisions


def resolve_mixed_pattern_tokens_with_sentence_context(decisions, previous_context_words=None):
    """
    If a mixed token (DI6S -> DI?S) matches several English words, keep it
    unresolved until the rest of the sentence has finished correcting.
    """
    if not decisions:
        return decisions

    for decision in decisions:
        for raw_token in re.findall(r"\S+", str(decision.get("text", ""))):
            compact = re.sub(r"[^A-Z0-9]", "", raw_token.upper())
            if not is_wordlike_mixed_alphanumeric_token(compact):
                continue
            if is_number_shaped_token(raw_token):
                continue                  # 34.O% / 0O:37 are numbers, fixed in the number direction
            pattern = "".join(character if character.isalpha() else "?" for character in compact)
            found, stage = lookalike_first_word_candidates(compact)
            candidates = [c["text"] for c in found]
            if not candidates:
                continue
            print(f"LOOK-ALIKE FIRST: {compact} -> {stage}: "
                  + ", ".join(f"{c['text']} ({c['swaps']})" for c in found[:6]))

            if len(candidates) == 1:
                chosen = candidates[0]
                repaired_token = re.sub(
                    re.escape(compact), chosen, raw_token, count=1, flags=re.IGNORECASE,
                )
                token_pattern = re.compile(
                    r"(?<!\S)" + re.escape(raw_token) + r"(?!\S)", re.IGNORECASE,
                )
                decision["text"] = token_pattern.sub(
                    repaired_token, str(decision.get("text", "")), count=1,
                )
                print("MIXED-PATTERN UNIQUE PHYSICAL MATCH:", compact, "pattern=", pattern, "->", chosen)
                continue

            decision.setdefault("deferred_mixed_patterns", []).append({
                "raw_token": raw_token,
                "compact": compact,
                "pattern": pattern,
                "candidates": candidates,
            })
            print()
            print("MIXED-PATTERN DEFERRED UNTIL FULL SENTENCE:", compact, "pattern=", pattern)
            print("  Physical-pattern candidates:", candidates)
            print("  No word chosen yet.")
    return decisions


def deferred_mixed_token_records(decisions):
    records = []
    for decision in decisions or []:
        records.extend(decision.get("deferred_mixed_patterns", []))
    return records


def resolve_deferred_mixed_tokens_with_full_sentence(text, decisions):
    """Resolve deferred DI?S-style tokens with the full corrected sentence + LM."""
    result = str(text or "")
    records = deferred_mixed_token_records(decisions)
    if not result or not records:
        return result

    for record in records:
        raw_token = record.get("raw_token", "")
        compact = record.get("compact", "")
        pattern = record.get("pattern", "")
        candidates = list(record.get("candidates", []))
        if not raw_token or not candidates:
            continue

        tokens = re.findall(r"\S+", result)
        target_index = None
        for index, token in enumerate(tokens):
            token_compact = re.sub(r"[^A-Z0-9]", "", token.upper())
            if token_compact == compact or (
                len(token_compact) == len(pattern)
                and all(
                    expected == "?" or expected == actual
                    for expected, actual in zip(pattern, token_compact)
                )
                and any(character.isdigit() for character in token_compact)
            ):
                target_index = index
                break
        if target_index is None:
            continue

        scored = []
        for candidate in candidates:
            candidate_tokens = list(tokens)
            original_token = candidate_tokens[target_index]
            original_core = re.sub(r"[^A-Za-z0-9]", "", original_token)
            candidate_tokens[target_index] = re.sub(
                re.escape(original_core), candidate, original_token,
                count=1, flags=re.IGNORECASE,
            )
            candidate_sentence = " ".join(candidate_tokens)
            lm_score = contextual_sentence_log_probability(candidate_sentence)
            if lm_score is None:
                continue
            scored.append({
                "candidate": candidate,
                "sentence": candidate_sentence,
                "lm_score": lm_score,
                "frequency": zipf_frequency(candidate.lower(), "en"),
            })

        if not scored:
            print(
                "FULL-SENTENCE MIXED-PATTERN RESOLUTION DEFERRED:", compact,
                "| contextual LM unavailable.",
            )
            continue

        scored.sort(key=lambda item: (item["lm_score"], item["frequency"]), reverse=True)
        best = scored[0]
        print()
        print("FULL-SENTENCE MIXED-PATTERN RESOLUTION:", compact, "pattern=", pattern)
        for rank, item in enumerate(scored[:10], start=1):
            print(
                f"  {rank}.", item["candidate"],
                "| LM=", round(item["lm_score"], 4),
                "| freq=", round(item["frequency"], 2),
                "| sentence=", item["sentence"],
            )
        result = best["sentence"]
        print("  Selected:", compact, "->", best["candidate"])
    return result


def repair_mixed_alphanumeric_tokens_inside_decisions(decisions):
    """Repair mixed alphanumeric WORDS even when embedded in a phrase."""
    if not decisions:
        return decisions

    tokenized = []
    for decision_index, decision in enumerate(decisions):
        for token_index, token in enumerate(re.findall(r"\S+", str(decision.get("text", "")))):
            tokenized.append({
                "decision_index": decision_index,
                "token_index": token_index,
                "token": token,
            })

    for flat_index, record in enumerate(tokenized):
        token = record["token"]
        if not is_wordlike_mixed_alphanumeric_token(token):
            continue

        decision = decisions[record["decision_index"]]
        deferred_compacts = {
            item.get("compact", "") for item in decision.get("deferred_mixed_patterns", [])
        }
        token_compact = re.sub(r"[^A-Z0-9]", "", token.upper())
        if token_compact in deferred_compacts:
            print()
            print(
                "STRICT WORD-TYPE GUARD DEFERRED:", token,
                "| waiting for full corrected sentence context",
            )
            continue

        left_word = None
        right_word = None
        for prior in range(flat_index - 1, -1, -1):
            words = alpha_words_from_text(tokenized[prior]["token"])
            if words:
                left_word = words[-1]
                break
        for following in range(flat_index + 1, len(tokenized)):
            words = alpha_words_from_text(tokenized[following]["token"])
            if words:
                right_word = words[0]
                break

        replacement = choose_mixed_token_english_replacement(token, left_word, right_word)
        if replacement is None:
            print()
            print(
                "STRICT WORD-TYPE GUARD: unresolved letters+digits token retained "
                "for OCR evidence:", token,
            )
            continue

        core = re.sub(r"[^A-Za-z0-9]", "", token)
        repaired_token = re.sub(
            re.escape(core), replacement["after"], token, count=1, flags=re.IGNORECASE,
        )
        token_pattern = re.compile(r"(?<!\S)" + re.escape(token) + r"(?!\S)", re.IGNORECASE)
        new_text, count = token_pattern.subn(
            repaired_token, str(decision.get("text", "")), count=1,
        )
        if count:
            decision["text"] = new_text
            decision["source"] = (
                str(decision.get("source", "")) + " | strict letters-only English-word guard"
            ).strip(" |")
            decision.setdefault("mixed_alphanumeric_embedded_repairs", []).append(replacement)
            record["token"] = repaired_token
            print()
            print(
                "STRICT WORD-TYPE GUARD:", token, "->", repaired_token,
                "| context:", left_word, "< token >", right_word,
            )
    return decisions


def repair_mixed_alphanumeric_tokens_in_final_text(text):
    """Final backstop: no English-looking token may leave Notes with digits."""
    tokens = re.findall(r"\S+", str(text or ""))
    if not tokens:
        return str(text or "")
    output = list(tokens)
    for index, token in enumerate(tokens):
        if not is_wordlike_mixed_alphanumeric_token(token):
            continue
        left_word = None
        right_word = None
        for prior in range(index - 1, -1, -1):
            words = alpha_words_from_text(output[prior])
            if words:
                left_word = words[-1]
                break
        for following in range(index + 1, len(tokens)):
            words = alpha_words_from_text(tokens[following])
            if words:
                right_word = words[0]
                break

        compact = re.sub(r"[^A-Z0-9]", "", token.upper())
        pattern = "".join(character if character.isalpha() else "?" for character in compact)
        exact_pattern_candidates = [
            candidate for candidate in lazy_english_words(len(pattern), mixed_pattern=pattern)
            if len(candidate) == len(pattern)
            and all(
                expected == "?" or expected == actual.upper()
                for expected, actual in zip(pattern, candidate)
            )
        ]
        if len(set(candidate.upper() for candidate in exact_pattern_candidates)) > 1:
            print(
                "FINAL STRICT WORD-TYPE GUARD DEFERRED:", token,
                "| multiple physical-pattern words remain; refusing local guess",
            )
            continue

        replacement = choose_mixed_token_english_replacement(token, left_word, right_word)
        if replacement is None:
            continue
        core = re.sub(r"[^A-Za-z0-9]", "", token)
        output[index] = re.sub(
            re.escape(core), replacement["after"], token, count=1, flags=re.IGNORECASE,
        )
        print("FINAL STRICT WORD-TYPE GUARD:", token, "->", output[index])
    return " ".join(output)


# ============================================================
# INITIAL ENGLISH CORRECTION PASS
# ============================================================

# ============================================================
# DUPLICATE-NEIGHBOUR GUARD
# ============================================================
# A correction that makes a word the SAME as the word right next to it
# ('DIS' -> 'NOTE' giving 'NOTE NOTE') is only allowed if the repeat makes
# sense in context. The words before and after are scored by the language
# model WITH the repeat and WITHOUT it; the repeat must read at least as well.
# ('HAD HAD' in 'HE HAD HAD ENOUGH' can pass; 'NOTE NOTE WITHIN' does not.)

DUPLICATE_CONTEXT_WORDS = 3


def duplicate_makes_sense(words, index):
    """(True/False, reason) - does words[index] repeating its neighbour make sense?"""
    word = words[index]
    low = max(0, index - DUPLICATE_CONTEXT_WORDS)
    high = min(len(words), index + DUPLICATE_CONTEXT_WORDS + 1)
    with_repeat = words[low:high]
    without_repeat = words[low:index] + words[index + 1:high]
    try:
        lm_with = contextual_sentence_log_probability(" ".join(with_repeat))
        lm_without = contextual_sentence_log_probability(" ".join(without_repeat))
    except Exception:
        lm_with = lm_without = None
    if lm_with is not None and lm_without is not None:
        return lm_with >= lm_without, (
            f"'{' '.join(with_repeat)}' LM={lm_with:.3f} vs "
            f"'{' '.join(without_repeat)}' LM={lm_without:.3f}"
        )
    frequency = phrase_frequency_raw(f"{word} {word}")
    return frequency >= 3.0, f"'{word} {word}' phrase frequency {frequency:.2f} (language model unavailable)"


def duplicate_guard_allows(decisions, decision_index, word_index, current_word, new_word):
    """False when the change would create a repeat of a neighbour that does not make sense."""
    new_word = normalize_alpha_for_matching(new_word)
    if not new_word or new_word == normalize_alpha_for_matching(current_word):
        return True
    words, flat_index = build_candidate_sentence_words(decisions, decision_index, word_index, new_word)
    if flat_index is None:
        return True
    left = words[flat_index - 1] if flat_index > 0 else None
    right = words[flat_index + 1] if flat_index + 1 < len(words) else None
    if new_word not in (left, right):
        return True
    makes_sense, reason = duplicate_makes_sense(words, flat_index)
    if makes_sense:
        print(f"DUPLICATE GUARD: {current_word} -> {new_word} repeats its neighbour but reads fine ({reason})")
        return True
    print(f"DUPLICATE GUARD: {current_word} -> {new_word} REJECTED - it would repeat the next word "
          f"and the repeat does not make sense ({reason})")
    return False


# ============================================================
# EVIDENCE WORD SEARCH ('?' positions: high-confidence letters, then numbers)
# ============================================================
# For a word with '?' (open) positions:
#   1. every '?' collects its HIGH-confidence reads: letters from the whole-word
#      reads and letters/numbers from the letter's own crop;
#   2. a high-confidence NUMBER is swapped for the letter(s) it looks like
#      (6 -> G/B, 5 -> S, 0 -> O/D/Q, 1 -> I/L/T, ...);
#   3. words are built from these options, most confident first, and the
#      first one that is a real English word wins.
#   e.g. D??S: ?1 I 88%, ?2 L 100% / crop 6 94%  ->  DILS (not a word)
#        ->  6 swapped for G  ->  DIGS (word)  -> evidence word = DIGS
# Runs LAST, after the English passes, the contextual language model and the
# sentence sanity check - and only for words that are still not English words.

EVIDENCE_HIGH_CONFIDENCE = 0.60     # a read must reach this to count as "high"
EVIDENCE_WORD_MIN_ZIPF = 2.5        # how common a word must be to count as English
EVIDENCE_MAX_COMBINATIONS = 400


def evidence_options_for_position(character_item, crop, min_confidence=None, include_whole_word=True):
    """High-confidence (letter, confidence, source) options for one '?' position."""
    if min_confidence is None:
        min_confidence = EVIDENCE_HIGH_CONFIDENCE
    options = {}

    def add(letter, confidence, source):
        letter = str(letter or "").upper()
        if len(letter) != 1 or not letter.isalpha():
            return
        if confidence > options.get(letter, (0.0, ""))[0]:
            options[letter] = (confidence, source)

    for alternative in (character_item.get("alternatives") or []) if include_whole_word else []:
        share = safe_float(alternative.get("share", alternative.get("confidence", 0.0)))
        if share >= min_confidence:
            add(alternative.get("character"), share, "whole word")
    if crop is not None and crop.get("image") is not None:
        try:
            read = read_isolated_character(crop["image"], alphabetic_only=False)
        except Exception:
            read = {}
        for alternative in read.get("alternatives") or []:
            character = str(alternative.get("character", ""))
            confidence = safe_float(alternative.get("confidence", 0.0))
            if confidence < min_confidence or len(character) != 1:
                continue
            if character.isalpha():
                add(character, confidence, "crop letter")
            elif character.isdigit():
                for letter in DIGIT_READ_AS_LETTERS.get(character, []):
                    add(letter, confidence, f"crop number {character}->{letter}")
    return sorted(
        ((letter, confidence, source) for letter, (confidence, source) in options.items()),
        key=lambda item: -item[1],
    )


# ------------------------------------------------------------
# CROP EVIDENCE DECISION (runs before the regular word check)
# ------------------------------------------------------------
# For a word with '?' positions:
#   1. each '?' takes the high-confidence (>= 80%) reads of its OWN letter crop
#      (the crops already made - no new snips);
#   2. a high-confidence NUMBER becomes the letter(s) it looks like (6 -> G ...);
#   3. the word is rebuilt with those letters and must be an English word;
#   4. it must fit the context (the words before / after it);
#   5. if all pass, the word is KEPT and locked (no candidate search, no N+1
#      check, no later re-checks for it).
# If ANY '?' has no high-confidence crop read, or no word passes, the word goes
# through the regular process exactly as before.
CROP_DECISION_MIN_CONFIDENCE = 0.80
CROP_DECISION_MIN_CONTEXT = 0.35          # phrase-fit score the word must reach
CROP_DECISION_CONTEXT_TOLERANCE = 0.05    # a changed word may be at most this much worse in context


def consensus_inserted_words():
    """Consensus words whose extra letter was proven (reads + English / context)."""
    return {e["text"] for e in (LINE_CONSENSUS.get("slots") or [])
            if e["type"] == "word" and (e.get("optional_inserted") or e.get("digit_evidence")
                                        or e.get("evidence_choice"))}


def consensus_word_for(flat_index, word, line_word_count):
    """The confident consensus word for this word position, or None.
    Positions line up when the consensus has the same number of words as the
    line; otherwise the most similar confident consensus word (>= 0.6) is used."""
    words = consensus_confident_words()
    if not words:
        return None
    word = normalize_alpha_for_matching(word)
    if len(words) == line_word_count and 0 <= flat_index < len(words):
        text, confident = words[flat_index]
        return text if confident else None
    best, best_ratio = None, 0.0
    for text, confident in words:
        if not confident:
            continue
        ratio = SequenceMatcher(None, word, text, autojunk=False).ratio()
        if ratio > best_ratio:
            best, best_ratio = text, ratio
    return best if best_ratio >= 0.6 else None


def every_word_settled(decisions):
    """True when every letter-word of the line is locked (kept) - nothing left to decide."""
    any_word = False
    for decision in decisions:
        for word_index, word in enumerate(alpha_words_from_text(decision.get("text", ""))):
            any_word = True
            if not is_crop_locked(decision, word_index, word):
                return False
    return any_word


def consensus_word_fits_ink(decision, consensus_word):
    """
    Before a consensus word is locked, the snip's ink width is checked (image
    measurement only, no OCR): if the ink clearly holds one more letter than the
    word has (e.g. ~5.34 letters for MEAL), the word is NOT locked - the reads
    may all have missed a letter (the T in METAL). Same threshold as the N+1 check.
    Groups with more than one word cannot be measured per word -> allowed.
    """
    if len(alpha_words_from_text(decision.get("text", ""))) != 1:
        return True, None
    images = [v["image"] for v in word_image_visuals(decision) if v.get("image") is not None]
    if not images:
        return True, None
    try:
        image = images[0] if len(images) == 1 else combine_images_horizontal(images, gap=0)
        geometry = estimate_visible_character_count(image)
    except Exception:
        return True, None
    word = normalize_alpha_for_matching(consensus_word)
    if strong_visible_nplus1_geometry(word, {"geometry": geometry}):
        return False, (f"the ink holds ~{safe_float(geometry.get('count', 0)):.2f} letters, "
                       f"{word} has {len(word)}")
    return True, None


def lock_word(decision, word_index, word, reason):
    decision.setdefault("crop_locked", {})[word_index] = normalize_alpha_for_matching(word)
    decision.setdefault("locked_reason", {})[word_index] = reason


def whole_line_settled(word):
    """(settled?, agreeing reads, total reads): a real word (2+ letters) spelled
    exactly in at least half of the whole-line reads (and at least 4 reads)."""
    word = normalize_alpha_for_matching(word)
    agreeing, total = whole_line_word_agreement(word)
    settled = (
        len(word) >= 2
        and total >= WHOLE_LINE_AGREEMENT_MIN_READS
        and agreeing / total >= WHOLE_LINE_AGREEMENT_MIN_SHARE
        and zipf_frequency(word.lower(), "en") >= 2.3
    )
    return settled, agreeing, total


def is_crop_locked(decision, word_index, word):
    locked = (decision or {}).get("crop_locked") or {}
    return locked.get(word_index) == normalize_alpha_for_matching(word)


UNIQUE_PATTERN_MIN_ZIPF = 2.5     # words rarer than this do not count as competitors


def unique_pattern_word(current_word, profile):
    """
    If exactly ONE common English word of the same length fits the locked
    letters (PAC?ET -> PACKET) and nothing suggests a missing letter, that word
    is the answer. Returns it, or None (-> crop evidence / regular process).
    """
    characters = (profile or {}).get("characters") or []
    if not characters or all(c.get("locked") for c in characters) or not any(c.get("locked") for c in characters):
        return None
    pattern = "".join(
        (c.get("reference_character") or "?") if c.get("locked") else "?" for c in characters
    )
    words = lazy_english_words(len(characters), character_profile=profile, enforce_character_locks=True)
    common = [w for w in words if zipf_frequency(w.lower(), "en") >= UNIQUE_PATTERN_MIN_ZIPF]
    if len(common) != 1:
        return None
    word = common[0]
    agreeing, total = whole_line_word_agreement(word)
    whole_line_certain = (
        total >= WHOLE_LINE_AGREEMENT_MIN_READS and agreeing / total >= WHOLE_LINE_AGREEMENT_MIN_SHARE
    )
    if strong_visible_nplus1_geometry(current_word, profile) and not whole_line_certain:
        print(f"UNIQUE PATTERN: {pattern} -> only {word}, but the letter count suggests a missing "
              "letter -> regular process (N+1 check)")
        return None
    print(f"UNIQUE PATTERN: {pattern} -> the only English word that fits is {word} "
          "(no sign of a missing letter) -> KEPT")
    return word


def crop_evidence_decision(current_word, profile, left_word, right_word):
    """The word to keep from the letter crops, or None (-> regular process)."""
    characters = (profile or {}).get("characters") or []
    if not characters or all(c.get("locked") for c in characters):
        return None
    current = normalize_alpha_for_matching(current_word)
    crops = {c.get("position"): c for c in profile.get("individual_letter_crops") or []}
    print()
    print(f"CROP EVIDENCE CHECK for {current_word} (each ? needs its own crop read >= "
          f"{CROP_DECISION_MIN_CONFIDENCE:.0%})")
    slots = []
    for index, item in enumerate(characters):
        letter = item.get("reference_character") or item.get("character") or "?"
        if item.get("locked"):
            slots.append([(letter, 1.0)])
            continue
        options = evidence_options_for_position(
            item, crops.get(item.get("position", index)),
            min_confidence=CROP_DECISION_MIN_CONFIDENCE, include_whole_word=False,
        )
        if not options:
            print(f"  ? at {index + 1}: no crop read >= {CROP_DECISION_MIN_CONFIDENCE:.0%} -> regular process")
            return None
        print(f"  ? at {index + 1}: " + ", ".join(f"{l} {c:.0%} ({src})" for l, c, src in options))
        slots.append([(l, c) for l, c, _ in options])

    import itertools
    combos = []
    for count, combo in enumerate(itertools.product(*slots)):
        if count >= EVIDENCE_MAX_COMBINATIONS:
            break
        combos.append(("".join(ch for ch, _ in combo), sum(c for _, c in combo) / len(combo)))
    combos.sort(key=lambda item: -item[1])

    current_context = contextual_phrase_score(current, left_word, right_word)
    seen = set()
    for word, _ in combos:
        if word in seen:
            continue
        seen.add(word)
        if zipf_frequency(word.lower(), "en") < EVIDENCE_WORD_MIN_ZIPF:
            print(f"  {word}: not an English word")
            continue
        context = contextual_phrase_score(word, left_word, right_word)
        if context < CROP_DECISION_MIN_CONTEXT:
            print(f"  {word}: English, but does not fit context ({left_word} < {word} > {right_word}: "
                  f"{context:.3f} < {CROP_DECISION_MIN_CONTEXT})")
            continue
        if word != current and context < current_context - CROP_DECISION_CONTEXT_TOLERANCE:
            print(f"  {word}: fits context worse than {current} ({context:.3f} vs {current_context:.3f})")
            continue
        print(f"  {word}: English word, fits context ({context:.3f}) -> KEPT")
        return word
    print("  no word passed -> regular process")
    return None


def flat_line_words(decisions):
    """All letter-words of the line in order (same numbering as the word checks)."""
    words = []
    for decision in decisions:
        words.extend(normalize_alpha_for_matching(w) for w in alpha_words_from_text(decision.get("text", "")))
    return words


def pass_two_recheck_indexes(words_before, words_after):
    """Changed words + their neighbours, or None (= re-check everything) if the word count changed."""
    if len(words_before) != len(words_after):
        return None
    changed = [i for i, (a, b) in enumerate(zip(words_before, words_after)) if a != b]
    recheck = set()
    for index in changed:
        recheck.update({index - 1, index, index + 1})
    return {i for i in recheck if 0 <= i < len(words_after)}


def general_english_correction_pass(decisions, only_flat_indexes=None):
    print()
    print("=" * 70)
    print("GENERAL ENGLISH WORD CORRECTION")
    print("=" * 70)
    if only_flat_indexes is not None:
        words_now = flat_line_words(decisions)
        if only_flat_indexes:
            print("Re-checking only changed words and their neighbours: "
                  + ", ".join(words_now[i] for i in sorted(only_flat_indexes)))
        else:
            print("No word changed -> nothing to re-check.")

    flat_counter = 0
    flat_counter_total = len(flat_line_words(decisions))
    for decision_index, decision in enumerate(decisions):
        decision_words = alpha_words_from_text(decision.get("text", ""))
        flat_start = flat_counter
        flat_counter += len(decision_words)
        if only_flat_indexes is not None and not any(
            flat_start + i in only_flat_indexes for i in range(len(decision_words))
        ):
            continue                        # nothing to re-check here -> no image reads at all

        # 1: a real word spelled exactly in most whole-line reads is settled here,
        #    before its images are read
        for word_index, word in enumerate(decision_words):
            if is_crop_locked(decision, word_index, word):
                continue
            settled, agreeing, total_reads = whole_line_settled(word)
            if settled:
                lock_word(decision, word_index, word, f"whole-line agreement {agreeing}/{total_reads}")
                print()
                print(f"WHOLE-LINE AGREEMENT: {word} spelled exactly in {agreeing}/{total_reads} "
                      "whole-line reads -> KEPT (no image reads, candidate search or re-checks)")
                continue
            consensus_word = consensus_word_for(flat_start + word_index, word, flat_counter_total)
            if consensus_word:
                ink_ok, ink_note = consensus_word_fits_ink(decision, consensus_word)
                if not ink_ok:
                    print()
                    print(f"WHOLE-LINE CONSENSUS: {consensus_word} NOT locked -> {ink_note} "
                          "-> a letter may be missing, regular check decides")
                    consensus_word = None
            if consensus_word:
                current = normalize_alpha_for_matching(word)
                if consensus_word == current:
                    lock_word(decision, word_index, word, "whole-line consensus")
                    print()
                    print(f"WHOLE-LINE CONSENSUS: {word} confirmed by the combined reads -> KEPT")
                elif (
                    zipf_frequency(current.lower(), "en") < 2.3
                    or consensus_word in consensus_inserted_words()
                ) and duplicate_guard_allows(
                    decisions, decision_index, word_index, word, consensus_word,
                ):
                    decision["text"] = replace_nth_alpha_word(decision["text"], word_index, consensus_word)
                    decision_words[word_index] = consensus_word
                    lock_word(decision, word_index, consensus_word, "whole-line consensus")
                    print()
                    if consensus_word in consensus_inserted_words():
                        print(f"WHOLE-LINE CONSENSUS: {word} -> {consensus_word} (the extra letter is shown by "
                              "the reads and proven by English / context) -> KEPT")
                    else:
                        print(f"WHOLE-LINE CONSENSUS: {word} is not a word -> {consensus_word} "
                              "(best fit to all whole-line reads) -> KEPT")
        if decision_words and all(
            is_crop_locked(decision, i, w) for i, w in enumerate(decision_words)
        ):
            previous = {c.get("word_index"): c for c in decision.get("english_word_corrections", []) or []}
            decision["english_word_corrections"] = [
                previous.get(i) or {
                    "before": w, "after": w, "changed": False, "candidates": [],
                    "word_index": i, "locked_word": True,
                }
                for i, w in enumerate(decision_words)
            ]
            continue                        # every word settled -> no image reads for this group
        units = split_decision_into_word_units(decision)
        if not units:
            continue
        original_words = alpha_words_from_text(decision.get("text", ""))
        if not original_words:
            continue
        corrected_words = list(original_words)
        word_corrections = []

        for unit_index, unit in enumerate(printed_once(units, lambda u: u["word"])):
            current_word = unit["word"]
            if only_flat_indexes is not None and flat_start + unit["word_index"] not in only_flat_indexes:
                previous = next(
                    (c for c in decision.get("english_word_corrections", []) or []
                     if c.get("word_index") == unit["word_index"]),
                    None,
                )
                word_corrections.append(previous or {
                    "before": current_word, "after": current_word, "changed": False,
                    "candidates": [], "word_index": unit["word_index"],
                })
                continue
            if is_crop_locked(decision, unit["word_index"], current_word):
                previous = next(
                    (c for c in decision.get("english_word_corrections", []) or []
                     if c.get("word_index") == unit["word_index"]),
                    None,
                )
                print()
                reason = (decision.get("locked_reason") or {}).get(unit["word_index"], "crop evidence")
                print(f"KEPT earlier ({reason}): {current_word} -> skipped")
                word_corrections.append(previous or {
                    "before": current_word, "after": current_word, "changed": False,
                    "candidates": [], "word_index": unit["word_index"], "crop_evidence": True,
                })
                continue
            left_word, right_word = get_word_neighbors(decisions, decision_index, unit["word_index"])

            character_profile = None
            if unit.get("image") is not None:
                character_profile = build_word_character_profile_from_image(current_word, unit.get("image"))
            if character_profile is None:
                character_profile = get_decision_word_character_profile(decision, unit["word_index"])

            print()
            print_word_character_profile_before_candidates(character_profile)

            kept_word = unique_pattern_word(current_word, character_profile)
            if not kept_word:
                kept_word = crop_evidence_decision(current_word, character_profile, left_word, right_word)
            if kept_word and (
                kept_word == normalize_alpha_for_matching(current_word)
                or duplicate_guard_allows(decisions, decision_index, unit["word_index"], current_word, kept_word)
            ):
                changed = kept_word != normalize_alpha_for_matching(current_word)
                if changed:
                    print("English correction:", current_word, "->", kept_word)
                    corrected_words[unit_index] = kept_word
                decision.setdefault("crop_locked", {})[unit["word_index"]] = kept_word
                word_corrections.append({
                    "before": current_word, "after": kept_word, "changed": changed,
                    "candidates": [], "target_length": len(kept_word),
                    "allowed_lengths": [len(kept_word)], "crop_evidence": True,
                    "character_profile": character_profile, "word_index": unit["word_index"],
                })
                continue

            correction = correct_single_english_word(
                current_word, unit["evidence"], left_word, right_word,
                character_profile=character_profile,
            )

            print()
            print("Current word:", current_word)
            print("OCR consensus length:", correction["target_length"])
            print("Allowed lengths:", correction["allowed_lengths"])
            print("Context:", left_word, "<", current_word, ">", right_word)
            if character_profile:
                locks = character_profile.get("locked", {})
                if locks:
                    print(
                        "Hard character locks BEFORE candidates:",
                        " ".join(
                            f"{position + 1}:{character}"
                            for position, character in sorted(locks.items())
                        ),
                    )
                else:
                    print("Hard character locks BEFORE candidates: none")
            if correction.get("fully_locked_skip", False):
                print(
                    "Candidate search SKIPPED: all existing characters are "
                    "hard-locked and the current word is valid English."
                )
            if correction.get("candidates"):
                print("Top candidates:")
                for candidate in correction["candidates"][:8]:
                    print(
                        "   ", candidate["text"],
                        "| total=", round(candidate.get("score", 0.0), 3),
                        "| OCR=", round(candidate.get("ocr_score", 0.0), 3),
                        "| chars=", candidate.get("length", len(candidate["text"])),
                        "| context=", round(candidate.get("context_score", 0.0), 3),
                        "| freq=", round(candidate.get("frequency", 0.0), 2),
                    )
            if correction["changed"] and not duplicate_guard_allows(
                decisions, decision_index, unit["word_index"], current_word, correction["after"],
            ):
                correction["changed"] = False
                correction["after"] = current_word
            if correction["changed"]:
                print("English correction:", current_word, "->", correction["after"])
                corrected_words[unit_index] = correction["after"]

            correction["character_profile"] = character_profile
            correction["word_index"] = unit["word_index"]
            word_corrections.append(correction)

        old_text = decision["text"]
        if len(original_words) == len(corrected_words):
            if re.fullmatch(r"[A-Za-z ]+", old_text):
                new_text = " ".join(corrected_words)
            else:
                new_text = replace_english_word_spans(
                    old_text, dict(enumerate(corrected_words)),
                )
            if new_text != old_text:
                decision["text"] = new_text
                decision["source"] = "General English readability + OCR length or +1"

        decision["english_word_corrections"] = word_corrections
    return decisions


# ============================================================
# LAZY CONTEXTUAL LANGUAGE MODEL
# ============================================================
# Loaded only when OCR leaves several realistic whole-sentence choices.
# Install once if needed:   python -m pip install transformers

_CONTEXTUAL_LM_TOKENIZER = None
_CONTEXTUAL_LM_MODEL = None
_CONTEXTUAL_LM_DEVICE = None
_CONTEXTUAL_LM_LOAD_FAILED = False


def load_contextual_language_model():
    """The contextual language model, loaded the first time a Notes line needs it (S263: no longer
    loaded in the background on every packet - the Notes lines are usually settled by the printed
    text, so it was loaded for nothing and competed with the reading for the GPU)."""
    global _CONTEXTUAL_LM_TOKENIZER, _CONTEXTUAL_LM_MODEL
    global _CONTEXTUAL_LM_DEVICE, _CONTEXTUAL_LM_LOAD_FAILED

    if _CONTEXTUAL_LM_TOKENIZER is not None and _CONTEXTUAL_LM_MODEL is not None:
        return True
    if _CONTEXTUAL_LM_LOAD_FAILED:
        return False

    print()
    print("Ambiguous English phrase detected -> lazy-loading contextual language model... (S263)")
    _lm_started = time.perf_counter()
    try:
        IMPORT_RECORD["local"].loader = "language model"
        waited = import_shared("torch", "language model") + import_shared("transformers", "language model")  # S155
        if waited >= 0.05:
            print(f"LANGUAGE MODEL: waited {waited:.1f} s for another loader to finish importing a shared library (S155)")
        import torch
        from transformers import AutoTokenizer, AutoModelForMaskedLM
    except Exception as exc:
        _CONTEXTUAL_LM_LOAD_FAILED = True
        print()
        print("Contextual language model unavailable.")
        print("Install it once with:")
        print("  python -m pip install transformers")
        print("Import error:", exc)
        return False

    try:
        tokenizer = AutoTokenizer.from_pretrained(CONTEXTUAL_LANGUAGE_MODEL_NAME)
        model = AutoModelForMaskedLM.from_pretrained(CONTEXTUAL_LANGUAGE_MODEL_NAME)
        device = "cuda" if torch.cuda.is_available() else "cpu"
        model.to(device)
        model.eval()
        _CONTEXTUAL_LM_TOKENIZER = tokenizer
        _CONTEXTUAL_LM_MODEL = model
        _CONTEXTUAL_LM_DEVICE = device
        print("Contextual language model loaded:", CONTEXTUAL_LANGUAGE_MODEL_NAME, "on", device)
        record_timing("Language model load (once per run, only when a Notes line needs it)",
                      time.perf_counter() - _lm_started, 3)
        report_shared_libraries()                     # S155: every loader's imports are in by then
        return True
    except Exception as exc:
        _CONTEXTUAL_LM_LOAD_FAILED = True
        print("Could not load contextual language model:", exc)
        return False


def contextual_sentence_log_probability(sentence):
    """Pseudo-log-likelihood from the masked LM. Higher = more natural. (Its time is
    counted for the 'inside:' split of the step that asked for it.)"""
    started = time.perf_counter()
    try:
        return _contextual_sentence_log_probability(sentence)
    finally:
        add_work_time("lm", time.perf_counter() - started)


def _contextual_sentence_log_probability(sentence):
    """Pseudo-log-likelihood from the masked LM. Higher = more natural. S350: worked out in the OCR process
    (the language model loads there, next to the OCR models) when that process is used."""
    if ocr_process_used():
        return ocr_process_call("lm", "score", (sentence,))
    if not load_contextual_language_model():
        return None
    import torch

    tokenizer = _CONTEXTUAL_LM_TOKENIZER
    model = _CONTEXTUAL_LM_MODEL
    device = _CONTEXTUAL_LM_DEVICE

    encoded = tokenizer(sentence, return_tensors="pt", truncation=True, max_length=96)
    input_ids = encoded["input_ids"][0]
    attention_mask = encoded["attention_mask"][0]
    special_mask = tokenizer.get_special_tokens_mask(
        input_ids.tolist(), already_has_special_tokens=True,
    )
    positions = [
        index for index, is_special in enumerate(special_mask)
        if not is_special and attention_mask[index].item() == 1
    ]
    if not positions:
        return None

    batch_ids = input_ids.unsqueeze(0).repeat(len(positions), 1)
    batch_attention = attention_mask.unsqueeze(0).repeat(len(positions), 1)
    targets = []
    for row, position in enumerate(positions):
        targets.append(int(input_ids[position].item()))
        batch_ids[row, position] = tokenizer.mask_token_id
    batch_ids = batch_ids.to(device)
    batch_attention = batch_attention.to(device)

    with torch.inference_mode():
        logits = model(input_ids=batch_ids, attention_mask=batch_attention).logits
        log_probs = torch.log_softmax(logits, dim=-1)

    values = [
        float(log_probs[row, position, target_id].item())
        for row, (position, target_id) in enumerate(zip(positions, targets))
    ]
    if not values:
        return None
    return sum(values) / len(values)


def print_candidate_letter_crop_diagnostics(current_word, candidate_word, character_profile):
    if not character_profile:
        return
    image = character_profile.get("image")
    if image is None:
        return
    current_word = normalize_alpha_for_matching(current_word)
    candidate_word = normalize_alpha_for_matching(candidate_word)
    if not candidate_word or candidate_word == current_word:
        return
    diagnostics = adaptive_connected_letter_crops(candidate_word, image)
    if not diagnostics:
        return
    print("Candidate-specific physical letter crops:", current_word, "->", candidate_word)
    for item in diagnostics:
        alternatives = item.get("alternatives", []) or []
        alternatives_text = (
            " | ".join(
                f'{alternative.get("character", "?")}:'
                f'{safe_float(alternative.get("confidence", 0.0)):.3f}'
                for alternative in alternatives
            )
            if alternatives else "NO LETTER READ"
        )
        print(
            f'  candidate crop {item.get("position", 0) + 1} '
            f'({item.get("reference_character", "?")})'
            f'{connection_text_for(item)}: {alternatives_text}'
        )


def contextual_candidate_physical_gate(
    current_word, candidate_word, current_ocr, candidate_ocr, character_profile,
):
    """
    OCR / physical handwriting decides which candidates the language model is
    even ALLOWED to see. The LM only ranks inside that set.
    """
    current_word = normalize_alpha_for_matching(current_word)
    candidate_word = normalize_alpha_for_matching(candidate_word)
    result = {
        "allowed": False,
        "reason": "",
        "current_physical": 0.0,
        "candidate_physical": 0.0,
        "physical_gain": 0.0,
        "geometry_nplus1": False,
    }
    if not current_word or not candidate_word:
        result["reason"] = "empty word"
        return result
    if candidate_word == current_word:
        result["allowed"] = True
        result["reason"] = "current OCR word"
        return result

    length_delta = len(candidate_word) - len(current_word)
    ocr_drop = current_ocr - candidate_ocr
    image = character_profile.get("image") if character_profile else None

    if length_delta == 0:
        if candidate_ocr >= current_ocr:
            result["allowed"] = True
            result["reason"] = "same length and OCR is equal/better"
            return result
        if ocr_drop <= CONTEXTUAL_SAME_LENGTH_MAX_OCR_DROP:
            result["allowed"] = True
            result["reason"] = "same length and OCR difference is within physical gate"
            return result
        result["reason"] = (
            "same-length candidate rejected: OCR support is materially weaker "
            "than current word"
        )
        return result

    if length_delta != 1:
        result["reason"] = "candidate length is neither N nor N+1"
        return result
    if candidate_ocr < CONTEXTUAL_LANGUAGE_MODEL_MIN_OCR:
        result["reason"] = "N+1 OCR support below minimum"
        return result
    if ocr_drop > CONTEXTUAL_NPLUS1_MAX_OCR_DROP:
        result["reason"] = "N+1 OCR drop exceeds maximum"
        return result

    geometry_nplus1 = strong_visible_nplus1_geometry(current_word, character_profile)
    result["geometry_nplus1"] = geometry_nplus1

    current_physical_score = safe_float(
        candidate_individual_letter_support(current_word, image).get("score", 0.0)
    )
    candidate_physical_score = safe_float(
        candidate_individual_letter_support(candidate_word, image).get("score", 0.0)
    )
    physical_gain = candidate_physical_score - current_physical_score
    result["current_physical"] = current_physical_score
    result["candidate_physical"] = candidate_physical_score
    result["physical_gain"] = physical_gain

    geometry_accept = (
        geometry_nplus1
        and candidate_ocr >= CONTEXTUAL_LANGUAGE_MODEL_MIN_OCR
        and ocr_drop <= CONTEXTUAL_NPLUS1_MAX_OCR_DROP
    )
    one_insertion_close_ocr_accept = ocr_drop <= 0.070 and any(
        candidate_word[:remove_index] + candidate_word[remove_index + 1:] == current_word
        for remove_index in range(len(candidate_word))
    )
    crop_accept = candidate_physical_score >= 0.38 and physical_gain >= 0.10

    if geometry_accept or crop_accept or one_insertion_close_ocr_accept:
        result["allowed"] = True
        if geometry_accept:
            geometry = (character_profile.get("geometry", {}) if character_profile else {}) or {}
            result["reason"] = (
                "N+1 physically authorized by visible character count "
                f'{safe_float(geometry.get("count", 0.0)):.2f} '
                f'(reliability={safe_float(geometry.get("reliability", 0.0)):.2f})'
            )
        elif crop_accept:
            result["reason"] = "N+1 physically supported by candidate letter crops"
        else:
            result["reason"] = "N+1 exact one-character insertion with near-equal OCR support"
        return result

    result["reason"] = (
        "N+1 rejected: language improvement has no sufficient physical "
        "missing-character evidence"
    )
    return result


def contextual_candidate_options_for_word(decisions, records, flat_index):
    record = records[flat_index]
    current_word = normalize_alpha_for_matching(record.get("word", ""))
    if not current_word:
        return []
    decision = decisions[record["decision_index"]]
    word_index = record["word_index"]
    if is_crop_locked(decision, word_index, current_word):
        return [{"text": current_word, "ocr": 1.0, "source": "kept by crop evidence"}]
    corrections = decision.get("english_word_corrections", []) or []
    correction = corrections[word_index] if word_index < len(corrections) else {}
    scored = [c for c in correction.get("candidates", []) or [] if c.get("score") is not None and c.get("text")]
    if scored:
        best = max(scored, key=lambda c: c["score"])
        others = [c["score"] for c in scored if normalize_alpha_for_matching(c["text"]) != current_word]
        lead = best["score"] - max(others, default=0.0)
        if normalize_alpha_for_matching(best["text"]) == current_word and lead >= NEIGHBOUR_LEAD_KEEP:
            print(f"Context candidate kept by the neighbour check: {current_word} (total {best['score']:.3f}, "
                  f"{lead:.3f} ahead of the next) - the sentence model may not change it (S484)")
            return [{"text": current_word, "ocr": 1.0, "source": "kept by the neighbour check (S484)"}]
    evidence = record.get("evidence", []) or [(current_word, 1.0)]
    current_ocr = score_candidate_against_ocr_evidence(current_word, evidence)

    corrections = decision.get("english_word_corrections", []) or []
    correction = corrections[word_index] if word_index < len(corrections) else {}
    character_profile = correction.get("character_profile")
    if character_profile is None:
        character_profile = get_decision_word_character_profile(decision, word_index)

    options = {
        current_word: {
            "text": current_word,
            "ocr": current_ocr,
            "source": "current OCR",
            "physical_gate": "current OCR word",
        }
    }
    seen_candidates = {current_word}
    candidate_sources = []

    for candidate in correction.get("candidates", []) or []:
        candidate_text = normalize_alpha_for_matching(candidate.get("text", ""))
        if not candidate_text or candidate_text in seen_candidates:
            continue
        candidate_ocr = safe_float(candidate.get(
            "ocr_score",
            score_candidate_against_ocr_evidence(candidate_text, evidence),
        ))
        candidate_sources.append((candidate_text, candidate_ocr, "existing English/OCR candidate"))
        seen_candidates.add(candidate_text)

    for candidate in decision.get("mixed_alphanumeric_candidates", []) or []:
        candidate_text = normalize_alpha_for_matching(candidate.get("text", ""))
        if not candidate_text or candidate_text in seen_candidates:
            continue
        candidate_ocr = score_candidate_against_ocr_evidence(candidate_text, evidence)
        candidate_sources.append((candidate_text, candidate_ocr, "mixed-token OCR candidate"))
        seen_candidates.add(candidate_text)

    for candidate_text, candidate_ocr, source in candidate_sources:
        if candidate_ocr < CONTEXTUAL_LANGUAGE_MODEL_MIN_OCR:
            print(
                "Context candidate rejected before LM:", current_word, "->", candidate_text,
                "| OCR=", round(candidate_ocr, 3), "| reason=below minimum OCR",
            )
            continue
        if len(candidate_text) == len(current_word) + 1:
            print_candidate_letter_crop_diagnostics(current_word, candidate_text, character_profile)

        gate = contextual_candidate_physical_gate(
            current_word, candidate_text, current_ocr, candidate_ocr, character_profile,
        )
        if not gate["allowed"]:
            print(
                "Context candidate rejected before LM:", current_word, "->", candidate_text,
                "| current OCR=", round(current_ocr, 3),
                "| candidate OCR=", round(candidate_ocr, 3),
                "| reason=", gate["reason"],
            )
            continue

        print(
            "Context candidate ALLOWED for LM:", current_word, "->", candidate_text,
            "| current OCR=", round(current_ocr, 3),
            "| candidate OCR=", round(candidate_ocr, 3),
            "| geometry N+1=", gate.get("geometry_nplus1", False),
            "| candidate physical=", round(gate.get("candidate_physical", 0.0), 3),
            "| reason=", gate["reason"],
        )
        options[candidate_text] = {
            "text": candidate_text,
            "ocr": candidate_ocr,
            "source": source,
            "physical_gate": gate["reason"],
            "geometry_nplus1": gate.get("geometry_nplus1", False),
            "candidate_physical": gate.get("candidate_physical", 0.0),
            "physical_gain": gate.get("physical_gain", 0.0),
        }

    output = list(options.values())
    output.sort(key=lambda item: item["ocr"], reverse=True)
    return output[:8]


def build_contextual_sentence_candidates(decisions):
    """Beam-build complete OCR-plausible sentence alternatives."""
    records = get_sentence_word_records(decisions)
    if len(records) < 2:
        return records, []

    current_words = [normalize_alpha_for_matching(record.get("word", "")) for record in records]
    option_sets = []
    flexible = 0
    for flat_index in range(len(records)):
        options = contextual_candidate_options_for_word(decisions, records, flat_index)
        if not options:
            options = [{"text": current_words[flat_index], "ocr": 1.0, "source": "current OCR"}]
        option_sets.append(options)
        if len(options) > 1:
            flexible += 1
    if flexible == 0:
        return records, []

    beam = [{"words": [], "ocr_values": [], "changes": 0}]
    for flat_index, options in enumerate(option_sets):
        expanded = []
        for state in beam:
            for option in options:
                words = state["words"] + [option["text"]]
                ocr_values = state["ocr_values"] + [option["ocr"]]
                changes = state["changes"] + (1 if option["text"] != current_words[flat_index] else 0)
                average_ocr = sum(ocr_values) / len(ocr_values)
                expanded.append({
                    "words": words,
                    "ocr_values": ocr_values,
                    "changes": changes,
                    "beam_score": average_ocr - changes * 0.012,
                })
        expanded.sort(key=lambda item: item["beam_score"], reverse=True)
        beam = expanded[:CONTEXTUAL_LANGUAGE_MODEL_BEAM_WIDTH]

    if not any(state["words"] == current_words for state in beam):
        beam.append({
            "words": current_words,
            "ocr_values": [
                score_candidate_against_ocr_evidence(
                    current_words[index],
                    records[index].get("evidence", []) or [(current_words[index], 1.0)],
                )
                for index in range(len(records))
            ],
            "changes": 0,
            "beam_score": 1.0,
        })
    beam.sort(key=lambda item: item["beam_score"], reverse=True)
    return records, beam[:CONTEXTUAL_LANGUAGE_MODEL_MAX_SENTENCES]


def contextual_language_model_rescue(decisions):
    """Final semantic English check for genuinely ambiguous OCR."""
    records, candidates = build_contextual_sentence_candidates(decisions)
    if not candidates:
        return decisions

    current_words = [normalize_alpha_for_matching(record.get("word", "")) for record in records]

    print()
    print("=" * 70)
    print("CONTEXTUAL WHOLE-SENTENCE ENGLISH CHECK")
    print("=" * 70)

    scored = []
    for state in candidates:
        sentence = " ".join(state["words"])
        lm_score = contextual_sentence_log_probability(sentence)
        if lm_score is None:
            print("Contextual model unavailable -> keeping OCR result.")
            return decisions
        average_ocr = sum(state["ocr_values"]) / max(len(state["ocr_values"]), 1)
        scored.append({**state, "sentence": sentence, "lm_score": lm_score, "average_ocr": average_ocr})

    lm_values = [item["lm_score"] for item in scored]
    lm_min = min(lm_values)
    lm_span = max(max(lm_values) - lm_min, 1e-9)
    for item in scored:
        item["lm_normalized"] = (item["lm_score"] - lm_min) / lm_span
        item["combined_score"] = (
            item["lm_normalized"] * 0.72
            + item["average_ocr"] * 0.28
            - item["changes"] * 0.008
        )
    scored.sort(key=lambda item: item["combined_score"], reverse=True)

    print("Only OCR/physically admissible alternatives were sent to the model.")
    print("Top contextual sentence candidates:")
    for rank, item in enumerate(scored[:10], start=1):
        print(
            f"{rank}.", item["sentence"],
            "| LM=", round(item["lm_score"], 4),
            "| OCR=", round(item["average_ocr"], 3),
            "| combined=", round(item["combined_score"], 4),
        )

    best = scored[0]
    baseline = next((item for item in scored if item["words"] == current_words), None)
    if baseline is None:
        return decisions
    gain = best["combined_score"] - baseline["combined_score"]
    if best["words"] == current_words or gain < CONTEXTUAL_LANGUAGE_MODEL_MIN_SCORE_GAIN:
        print("Contextual result: current OCR sentence retained.")
        return decisions

    print()
    print("Contextual sentence rescue:")
    print("  Before:", " ".join(current_words))
    print("  After :", best["sentence"])
    print("  Combined score gain:", round(gain, 4))

    replacements = defaultdict(list)
    for flat_index, (before_word, after_word) in enumerate(zip(current_words, best["words"])):
        if before_word == after_word:
            continue
        record = records[flat_index]
        replacements[record["decision_index"]].append((record["word_index"], before_word, after_word))

    for decision_index, items in replacements.items():
        items.sort(key=lambda item: item[0], reverse=True)
        decision = decisions[decision_index]
        for word_index, before_word, after_word in items:
            decision["text"] = replace_nth_alpha_word(decision.get("text", ""), word_index, after_word)
            print("  contextual replacement:", before_word, "->", after_word)
        decision["source"] = (
            str(decision.get("source", "")) + " | Contextual whole-sentence language model"
        ).strip(" |")
    return decisions


# ============================================================
# FINAL SENTENCE SANITY PASS
# ============================================================

def get_sentence_word_records(decisions):
    records = []
    for decision_index, decision in enumerate(decisions):
        units = split_decision_into_word_units(decision)
        unit_by_index = {unit["word_index"]: unit for unit in units}
        for word_index, word in enumerate(alpha_words_from_text(decision.get("text", ""))):
            unit = unit_by_index.get(word_index)
            if unit is None:
                unit = {
                    "word": word,
                    "word_index": word_index,
                    "evidence": [(word, 1.0)],
                    "image": None,
                    "piece": None,
                }
            records.append({
                "decision_index": decision_index,
                "word_index": word_index,
                "word": word,
                "evidence": unit.get("evidence", []),
                "unit": unit,
            })
    return records


def replace_nth_alpha_word(text, word_index, replacement):
    # Same word numbering as alpha_words_from_text (bullets / numbers / junk skipped)
    return replace_english_word_spans(text, {word_index: replacement})


def sentence_words_only(decisions):
    words = []
    for decision in decisions:
        words.extend(alpha_words_from_text(decision.get("text", "")))
    return words


def sentence_context_windows(words, index):
    windows = []
    count = len(words)
    if index - 1 >= 0:
        windows.append((2, " ".join(words[index - 1:index + 1])))
    if index + 1 < count:
        windows.append((2, " ".join(words[index:index + 2])))
    if index - 1 >= 0 and index + 1 < count:
        windows.append((3, " ".join(words[index - 1:index + 2])))
    if index - 2 >= 0:
        windows.append((3, " ".join(words[index - 2:index + 1])))
    if index + 2 < count:
        windows.append((3, " ".join(words[index:index + 3])))
    if index - 2 >= 0 and index + 1 < count:
        windows.append((4, " ".join(words[index - 2:index + 2])))
    if index - 1 >= 0 and index + 2 < count:
        windows.append((4, " ".join(words[index - 1:index + 3])))
    return windows


def score_sentence_word_context(words, index):
    windows = sentence_context_windows(words, index)
    if not windows:
        return {
            "score": english_frequency_score(words[index]),
            "raw_best": 0.0,
            "raw_average": 0.0,
            "windows": [],
        }

    scored_windows = []
    for size, phrase in windows:
        raw = phrase_frequency_raw(phrase)
        normalized = phrase_frequency_score(phrase)
        size_weight = 1.00 if size == 2 else (1.15 if size == 3 else 1.25)
        scored_windows.append({
            "size": size,
            "phrase": phrase,
            "raw": raw,
            "normalized": normalized,
            "weighted": normalized * size_weight,
        })

    weighted_values = sorted((item["weighted"] for item in scored_windows), reverse=True)
    raw_values = [item["raw"] for item in scored_windows]
    best = weighted_values[0]
    second = weighted_values[1] if len(weighted_values) > 1 else best
    average = sum(weighted_values) / len(weighted_values)
    return {
        "score": best * 0.50 + second * 0.25 + average * 0.25,
        "raw_best": max(raw_values),
        "raw_average": sum(raw_values) / len(raw_values),
        "windows": scored_windows,
    }


def build_candidate_sentence_words(decisions, decision_index, word_index, candidate):
    records = get_sentence_word_records(decisions)
    words = [record["word"] for record in records]
    target_flat_index = None
    for flat_index, record in enumerate(records):
        if record["decision_index"] == decision_index and record["word_index"] == word_index:
            target_flat_index = flat_index
            break
    if target_flat_index is None:
        return words, None
    words[target_flat_index] = candidate
    return words, target_flat_index


def sentence_candidate_score(
    decisions, decision_index, word_index, current_word, candidate_word,
    evidence, target_length, previous_context_words=None,
):
    candidate_word = normalize_alpha_for_matching(candidate_word)
    if not english_candidate_length_allowed(len(candidate_word), target_length):
        return None
    candidate_words, flat_index = build_candidate_sentence_words(
        decisions, decision_index, word_index, candidate_word,
    )
    if flat_index is None:
        return None

    context = score_sentence_word_context(candidate_words, flat_index)

    # Line N is also judged as a continuation of the finished lines above it.
    previous_context_words = previous_context_words or []
    cross_line_context_score = 0.0
    cross_line_windows = []
    if previous_context_words:
        cross_line_context_score, cross_line_windows = previous_context_phrase_score(
            previous_context_words, candidate_words,
        )
        context["score"] = clamp(context["score"] * 0.68 + cross_line_context_score * 0.32)

    ocr_score = score_candidate_against_ocr_evidence(candidate_word, evidence)
    word_frequency = zipf_frequency(candidate_word.lower(), "en")
    word_frequency_score = english_frequency_score(candidate_word)
    similarity = normalized_edit_similarity(current_word, candidate_word)
    exact_ocr = candidate_exact_ocr_support(candidate_word, evidence)
    extra_character = len(candidate_word) == target_length + 1
    length_score = 0.93 if extra_character else 1.0

    total = (
        context["score"] * 0.47
        + ocr_score * 0.22
        + word_frequency_score * 0.14
        + similarity * 0.08
        + length_score * 0.06
        + exact_ocr * 0.03
    )
    if word_frequency < 1.8:
        total -= 0.12
    elif word_frequency < 2.4:
        total -= 0.05
    if word_frequency >= 4.0:
        total += 0.025

    # Short words (WRH -> WITH) are not destroyed by low OCR similarity when
    # sentence context strongly supports them.
    if ocr_score < 0.53:
        if target_length <= 4 and context["score"] >= 0.55:
            total -= 0.08
        else:
            total -= 0.25

    return {
        "text": candidate_word,
        "score": total,
        "context_score": context["score"],
        "cross_line_context_score": cross_line_context_score,
        "cross_line_windows": cross_line_windows,
        "context": context,
        "ocr_score": ocr_score,
        "frequency": word_frequency,
        "frequency_score": word_frequency_score,
        "similarity": similarity,
        "exact_ocr": exact_ocr,
        "target_length": target_length,
        "length": len(candidate_word),
        "extra_character": extra_character,
    }


def sentence_word_is_suspicious(decisions, decision_index, word_index, word):
    word = normalize_alpha_for_matching(word)
    frequency = zipf_frequency(word.lower(), "en")
    words, flat_index = build_candidate_sentence_words(decisions, decision_index, word_index, word)
    if flat_index is None:
        return False
    context = score_sentence_word_context(words, flat_index)
    if frequency < 2.0:
        return True
    if frequency < 3.0 and context["score"] < 0.38:
        return True
    return False


def final_sentence_sanity_pass(decisions, previous_context_words=None):
    sanity_log = []
    previous_context_words = previous_context_words or []

    print()
    print("=" * 70)
    print("FINAL SENTENCE SANITY CHECK")
    print("=" * 70)
    if previous_context_words:
        print("Previous finished Notes lines used as context:", " ".join(previous_context_words))

    for pass_number in range(1, MAX_SENTENCE_SANITY_PASSES + 1):
        sentence_before = " ".join(sentence_words_only(decisions))
        print()
        print(f"SENTENCE SANITY PASS {pass_number}")
        print("Sentence before:")
        print(sentence_before)

        pass_log = {"pass": pass_number, "before": sentence_before, "changes": []}
        changed_this_pass = False

        for record in get_sentence_word_records(decisions):
            decision_index = record["decision_index"]
            word_index = record["word_index"]
            current_word = normalize_alpha_for_matching(record["word"])
            if len(current_word) < 2:
                continue
            if is_crop_locked(decisions[decision_index], word_index, current_word):
                continue                                     # kept by crop evidence

            current_decision = decisions[decision_index]
            units = split_decision_into_word_units(current_decision)
            unit = next(
                (candidate_unit for candidate_unit in units if candidate_unit["word_index"] == word_index),
                None,
            )
            if unit is None:
                evidence = [(current_word, 1.0)]
            else:
                evidence = unit.get("evidence", [(current_word, 1.0)])

            character_profile = None
            if unit is not None and unit.get("image") is not None:
                character_profile = build_word_character_profile_from_image(current_word, unit.get("image"))
            if character_profile is None:
                character_profile = get_decision_word_character_profile(current_decision, word_index)

            if character_profile and character_profile.get("length", 0) > 0:
                target_length = character_profile["length"]
            else:
                target_length = consensus_ocr_word_length(current_word, evidence)

            if not sentence_word_is_suspicious(decisions, decision_index, word_index, current_word):
                continue

            if character_profile is None or not character_profile.get("available", False):
                print()
                print("Suspicious word:", current_word)
                print("Sentence correction skipped: no usable per-character confidence profile.")
                continue

            if fully_locked_valid_english_word(current_word, character_profile, minimum_zipf=2.3):
                print()
                print(
                    "Sentence candidate search SKIPPED:", current_word,
                    "- all existing characters are hard-locked and the current word is valid English.",
                )
                continue

            print()
            print("Suspicious word:", current_word)
            print("OCR consensus length:", target_length)
            print("Allowed lengths:", allowed_english_lengths(target_length))
            print_word_character_profile_before_candidates(character_profile)

            seeds = {current_word}
            for observed, weight in evidence:
                observed = normalize_alpha_for_matching(observed)
                if observed:
                    seeds.add(observed)

            generated = generate_general_english_candidates(
                seeds, target_length, max_candidates=180, character_profile=character_profile,
            )
            candidate_words = {candidate["text"] for candidate in generated}

            # Grammar rescue: a NONWORD may test very close real words that
            # break at most ONE high-confidence lock.
            grammar_rescue_meta = {}
            if zipf_frequency(current_word.lower(), "en") < 1.8:
                rescue_candidates = generate_sentence_grammar_rescue_candidates(
                    seeds, target_length, character_profile, max_candidates=120,
                )
                for rescue in rescue_candidates:
                    grammar_rescue_meta[rescue["text"]] = rescue
                    candidate_words.add(rescue["text"])
                if rescue_candidates:
                    print(
                        "Grammar rescue enabled: current token is not an English word; "
                        "testing close real words that break at most ONE "
                        f">{CHARACTER_LOCK_THRESHOLD:.2f} character lock."
                    )

            if candidate_respects_character_locks(current_word, character_profile):
                candidate_words.add(current_word)

            scored = []
            for candidate_word in candidate_words:
                result = sentence_candidate_score(
                    decisions, decision_index, word_index, current_word, candidate_word,
                    evidence, target_length, previous_context_words=previous_context_words,
                )
                if result is None:
                    continue
                rescue_meta = grammar_rescue_meta.get(candidate_word)
                if rescue_meta is not None:
                    result["grammar_rescue"] = True
                    result["lock_violations"] = rescue_meta["lock_violations"]
                    result["edit_distance"] = rescue_meta["edit_distance"]
                else:
                    result["grammar_rescue"] = False
                    result["lock_violations"] = 0
                    result["edit_distance"] = levenshtein_distance(current_word, candidate_word)
                scored.append(result)

            scored.sort(
                key=lambda item: (item["score"], item["context_score"], item["frequency"], item["ocr_score"]),
                reverse=True,
            )
            if not scored:
                continue

            current_result = next((item for item in scored if item["text"] == current_word), None)
            if current_result is None:
                current_score = -999.0
                current_context = 0.0
            else:
                current_score = current_result["score"]
                current_context = current_result["context_score"]

            best = scored[0]
            print("Top sentence candidates:")
            for item in scored[:12]:
                print(
                    "   ", item["text"],
                    "| total=", round(item["score"], 3),
                    "| context=", round(item["context_score"], 3),
                    "| OCR=", round(item["ocr_score"], 3),
                    "| freq=", round(item["frequency"], 2),
                    "| chars=", item["length"],
                )
            if best.get("grammar_rescue"):
                print(
                    "Best grammar-rescue candidate:", best["text"],
                    "| broken high-confidence locks=", best.get("lock_violations", 0),
                    "| edit distance=", best.get("edit_distance", 0),
                )

            improvement = best["score"] - current_score
            context_improvement = best["context_score"] - current_context
            current_frequency = zipf_frequency(current_word.lower(), "en")

            replace = False
            if (
                best["text"] != current_word
                and best["ocr_score"] >= 0.56
                and best["context_score"] > current_context + 0.055
                and improvement >= 0.025
            ):
                replace = True

            if (
                best.get("grammar_rescue")
                and current_frequency < 1.8
                and best["text"] != current_word
                and best.get("lock_violations", 0) <= 1
                and best.get("edit_distance", 99) <= (1 if len(best["text"]) == target_length else 2)
                and best["frequency"] >= 2.5
                and best["ocr_score"] >= 0.60
                and best["context_score"] >= 0.42
                and (
                    best["context_score"] >= current_context + 0.10
                    or (current_context < 0.20 and best["context_score"] >= 0.42)
                )
            ):
                replace = True
                print(
                    "GRAMMAR RESCUE OVERRIDE:", current_word, "->", best["text"],
                    "| broke", best.get("lock_violations", 0),
                    f"high-confidence lock(s) above {CHARACTER_LOCK_THRESHOLD:.2f}",
                    "because the current token is a nonword and sentence context improves strongly.",
                )

            # Short nonword rule (WRH -> WITH).
            if (
                current_frequency < 1.8
                and best["text"] != current_word
                and best["frequency"] >= 2.5
                and (
                    best["ocr_score"] >= 0.53
                    or (
                        target_length <= 4
                        and best["context_score"] >= 0.55
                        and best["ocr_score"] >= 0.38
                    )
                )
                and context_improvement >= 0.025
                and improvement >= -0.005
            ):
                replace = True

            if replace and not duplicate_guard_allows(
                decisions, decision_index, word_index, current_word, best["text"],
            ):
                replace = False
            if replace:
                print("SENTENCE CORRECTION:", current_word, "->", best["text"])
                decisions[decision_index]["text"] = replace_nth_alpha_word(
                    decisions[decision_index]["text"], word_index, best["text"],
                )
                decisions[decision_index]["source"] = "Final sentence sanity correction"
                pass_log["changes"].append({
                    "before": current_word,
                    "after": best["text"],
                    "target_length": target_length,
                    "current_score": current_score,
                    "new_score": best["score"],
                    "current_context": current_context,
                    "new_context": best["context_score"],
                    "ocr_score": best["ocr_score"],
                    "frequency": best["frequency"],
                    "top_candidates": scored[:12],
                })
                changed_this_pass = True

        sentence_after = " ".join(sentence_words_only(decisions))
        pass_log["after"] = sentence_after
        sanity_log.append(pass_log)
        print()
        print("Sentence after:")
        print(sentence_after)
        if not changed_this_pass:
            print("No sentence-level changes. Sentence is stable.")
            break

    return decisions, sanity_log


# ============================================================
# TIME HANDLING
# ============================================================

def extract_digits(text):
    return re.sub(r"[^0-9]", "", str(text))


def is_valid_clock_time_text(text):
    match = re.fullmatch(r"(\d{1,2}):(\d{2})", normalize_token(text))
    if not match:
        return False
    hour = int(match.group(1))
    minute = int(match.group(2))
    return 1 <= hour <= 12 and 0 <= minute <= 59


def read_digits_only(image):
    versions = [
        ("Original", image),
        ("RedExcess", make_red_excess_image(image)),
        ("RedMask", make_red_mask_image(image, dilate=True, loose=True)),
        ("T130", make_binary(image, 130)),
        ("T155", make_binary(image, 155)),
    ]
    groups = defaultdict(list)
    for name, version in versions:
        for scale in [1, 2, 3]:
            resized = version.resize((version.width * scale, version.height * scale))
            raw, confidence = paddle_read_text_image(resized)
            digits = extract_digits(raw)
            if digits:
                groups[digits].append(confidence)
    candidates = [
        {
            "digits": digits,
            "votes": len(confidences),
            "confidence": sum(confidences) / len(confidences),
        }
        for digits, confidences in groups.items()
    ]
    candidates.sort(key=lambda item: (item["votes"], item["confidence"]), reverse=True)
    if not candidates:
        return {"digits": "", "votes": 0, "confidence": 0.0}
    return candidates[0]


def vertical_colon_score(image, x):
    mask = make_red_mask_array(image, loose=True)
    height, width = mask.shape
    half_width = max(2, int(height * 0.04))
    strip = mask[:, max(0, x - half_width):min(width, x + half_width + 1)]
    if strip.size == 0:
        return 0.0
    row_density = np.sum(strip, axis=1).astype(np.float32)
    upper = row_density[int(height * 0.15):int(height * 0.48)]
    lower = row_density[int(height * 0.52):int(height * 0.85)]
    if len(upper) == 0 or len(lower) == 0:
        return 0.0
    full_column_density = float(np.mean(np.sum(strip, axis=0)))
    dot_strength = min(float(upper.max()), float(lower.max())) / max(strip.shape[1], 1)
    stroke_penalty = min(1.0, full_column_density / max(height * 0.55, 1))
    return max(0.0, dot_strength - stroke_penalty * 0.45)


def generate_time_split_candidates(image):
    width = image.width
    candidates = [
        (vertical_colon_score(image, x), x)
        for x in range(max(4, int(width * 0.15)), min(width - 4, int(width * 0.65)))
    ]
    candidates.sort(reverse=True)
    selected = []
    for score, x in candidates:
        if any(
            abs(x - existing_x) < max(5, image.height * 0.08)
            for existing_score, existing_x in selected
        ):
            continue
        selected.append((score, x))
        if len(selected) >= 8:
            break
    return selected


def evaluate_time_split(image, split_x, colon_visual_score):
    exclusion = max(2, int(image.height * 0.04))
    left_end = max(1, split_x - exclusion)
    right_start = min(image.width - 1, split_x + exclusion)
    left = read_digits_only(image.crop((0, 0, left_end, image.height)))
    right = read_digits_only(image.crop((right_start, 0, image.width, image.height)))
    left_digits = left["digits"]
    right_digits = right["digits"]

    valid_shape = 1 <= len(left_digits) <= 2 and len(right_digits) == 2
    candidate_time = left_digits + ":" + right_digits if valid_shape else ""
    valid_clock = is_valid_clock_time_text(candidate_time) if candidate_time else False

    vote_score = (min(left["votes"] / 5.0, 1.0) + min(right["votes"] / 5.0, 1.0)) / 2.0
    confidence_score = (left["confidence"] + right["confidence"]) / 2.0
    score = (
        colon_visual_score * 0.25
        + vote_score * 0.25
        + confidence_score * 0.20
        + (1.0 if valid_shape else 0.0) * 0.15
        + (1.0 if valid_clock else 0.0) * 0.15
    )
    return {
        "text": candidate_time,
        "score": score,
        "split_x": split_x,
        "colon_score": colon_visual_score,
        "left": left,
        "right": right,
        "valid_shape": valid_shape,
        "valid_clock": valid_clock,
    }


def infer_time_from_digits(digits):
    digits = extract_digits(digits)
    candidates = []
    if len(digits) == 3:
        candidate = digits[0] + ":" + digits[1:]
        if is_valid_clock_time_text(candidate):
            candidates.append(candidate)
    elif len(digits) == 4:
        for candidate in (digits[0] + ":" + digits[1:], digits[:2] + ":" + digits[2:]):
            if is_valid_clock_time_text(candidate):
                candidates.append(candidate)
    return candidates


def refine_time_from_image(image, original_text):
    original_digits = extract_digits(original_text)
    split_candidates = generate_time_split_candidates(image)
    evaluated = [
        evaluate_time_split(image, split_x, colon_score)
        for colon_score, split_x in split_candidates
    ]
    evaluated.sort(key=lambda item: item["score"], reverse=True)
    if evaluated:
        best = evaluated[0]
        if best["valid_clock"] and best["score"] >= 0.52:
            return {**best, "method": "physical colon + side OCR"}

    base = {
        "split_x": None, "colon_score": 0.0, "left": None, "right": None,
        "valid_shape": True, "valid_clock": True,
    }
    inferred = infer_time_from_digits(original_digits)
    if len(inferred) == 1:
        return {**base, "text": inferred[0], "score": 0.50, "method": "time structure"}

    if len(inferred) == 2:
        width = image.width
        possible = []
        for time_text in inferred:
            fraction = len(time_text.split(":")[0]) / max(len(original_digits), 1)
            expected_x = int(width * fraction)
            nearby_scores = [
                colon_score - abs(split_x - expected_x) / max(width, 1) * 0.5
                for colon_score, split_x in split_candidates
            ]
            possible.append((max(nearby_scores) if nearby_scores else 0.0, time_text))
        possible.sort(reverse=True)
        return {
            **base,
            "text": possible[0][1],
            "score": 0.48,
            "colon_score": possible[0][0],
            "method": "time structure + split position",
        }

    return {
        "text": original_text, "score": 0.0, "split_x": None, "colon_score": 0.0,
        "left": None, "right": None, "valid_shape": False, "valid_clock": False,
        "method": "unresolved",
    }


# ============================================================
# PHYSICAL STRUCTURE (circled markers, numbers, WORD:, @ time)
# ============================================================

def _ink_mask(image):
    """Red handwriting only (orange Dig Packet paper is NOT ink); dark ink as fallback."""
    rgb = np.array(image.convert("RGB"))
    if rgb.size == 0:
        return None
    mask = make_red_mask_array(image, loose=False).astype(np.uint8) * 255
    if np.count_nonzero(mask) < 60:
        mask = make_red_mask_array(image, loose=True).astype(np.uint8) * 255
    if np.count_nonzero(mask) < 60:
        gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
        mask = (gray < 110).astype(np.uint8) * 255
    # remove paper speckle
    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN,
                            cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3)), iterations=1)
    return mask


CIRCLE_SECTORS = 36
CIRCLE_MIN_RING_COVERAGE = 0.70     # ink in >= 70% of directions at the outer edge
CIRCLE_MIN_HEIGHT_RATIO = 1.25     # circle is taller than the line's other handwriting
CIRCLE_MIN_INSIDE_INK = 0.04        # >= 4% of the middle area has ink (the letter)


def ink_height(image):
    mask = _ink_mask(image) if image is not None else None
    if mask is None:
        return None
    ys, _ = np.where(mask > 0)
    return int(ys.max() - ys.min() + 1) if len(ys) else None


def circled_content_image(chunk, line_height=None, report=False):
    """
    If the chunk is a CIRCLE WITH SOMETHING INSIDE (a circled A / B / 1), return a
    crop of just the inside; otherwise None.
    Test (like reading a clock face around the mark's centre):
      - a RING: ink in nearly every direction near the outer edge
        (tolerates gaps, touching strokes and a form line crossing it)
      - CONTENT: ink in the middle (the letter)
    A plain O / D has a ring but an EMPTY middle; other letters have no ring.
    """
    image = chunk.get("image")
    if image is None:
        return None
    mask = _ink_mask(image)
    if mask is None:
        return None
    ys, xs = np.where(mask > 0)
    def say(reason):
        if report:
            print(f"CIRCLE TEST on first mark {chunk.get('text', '')!r}: NOT a circle - {reason}")
        return None

    if len(xs) < 60:
        return say("too little ink")
    x0, x1, y0, y1 = int(xs.min()), int(xs.max()), int(ys.min()), int(ys.max())
    w, h = x1 - x0 + 1, y1 - y0 + 1
    edge = []
    if y0 <= 1:
        edge.append("top")
    if y1 >= mask.shape[0] - 2:
        edge.append("bottom")
    if x0 <= 1:
        edge.append("left")
    if x1 >= mask.shape[1] - 2:
        edge.append("right")
    edge_note = f" | ink touches crop {'/'.join(edge)} edge - circle may be CUT OFF" if edge else ""
    if not (0.55 <= w / max(h, 1) <= 1.8) or min(w, h) < 12:
        return say(f"shape {w}x{h} px is not round enough{edge_note}")
    cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0
    rx, ry = w / 2.0, h / 2.0

    dx = (xs - cx) / max(rx, 1)
    dy = (ys - cy) / max(ry, 1)
    radius = np.sqrt(dx * dx + dy * dy)               # 1.0 = on the outer edge
    angle = (np.degrees(np.arctan2(dy, dx)) + 360) % 360

    ring = (radius >= 0.62) & (radius <= 1.15)
    sectors = set((angle[ring] // (360 / CIRCLE_SECTORS)).astype(int).tolist())
    coverage = len(sectors) / CIRCLE_SECTORS

    middle_area = np.pi * (0.5 * rx) * (0.5 * ry)
    inside_ink = int(np.count_nonzero(radius < 0.5))
    inside_share = inside_ink / max(middle_area, 1)

    ratio = h / line_height if line_height else None
    numbers = (f"ring={coverage:.2f} (need {CIRCLE_MIN_RING_COVERAGE:.2f}) | "
               f"inside={inside_share:.2f} (need {CIRCLE_MIN_INSIDE_INK:.2f}) | "
               f"height={h}px" + (f" vs line {line_height:.0f}px = {ratio:.2f}x (need {CIRCLE_MIN_HEIGHT_RATIO:.2f}x)"
                                  if ratio else " (no line to compare)") + edge_note)
    if coverage < CIRCLE_MIN_RING_COVERAGE:
        return say("ring incomplete | " + numbers)
    if inside_share < CIRCLE_MIN_INSIDE_INK:
        return say("nothing inside the ring | " + numbers)
    if line_height:
        if h < CIRCLE_MIN_HEIGHT_RATIO * line_height:
            return say("not taller than the other handwriting | " + numbers)   # a plain O / D / B
    elif coverage < 0.90:
        return say("no line to compare with and ring not near-perfect | " + numbers)
    if report:
        print(f"CIRCLE TEST on first mark {chunk.get('text', '')!r}: circle found | " + numbers)
    pad_x, pad_y = int(0.62 * rx), int(0.62 * ry)
    return image.crop((
        max(0, int(cx) - pad_x), max(0, int(cy) - pad_y),
        min(image.width, int(cx) + pad_x), min(image.height, int(cy) + pad_y),
    ))


BULLET_SIDE_ARC_MIN = 0.70     # a cut-off circle still shows both side arcs: ( A )
STAR_MAX_RIM = 0.55            # a star only touches its rim at spoke tips (real *: 0.47);
                               # a circled letter's rim is far more continuous (0.58-0.83)


def outer_rim_coverage(image):
    """Share of directions with ink right at the outer edge (a circle's rim is continuous)."""
    mask = _ink_mask(image) if image is not None else None
    if mask is None:
        return 0.0
    ys, xs = np.where(mask > 0)
    if len(xs) < 40:
        return 0.0
    x0, x1, y0, y1 = xs.min(), xs.max(), ys.min(), ys.max()
    rx, ry = (x1 - x0 + 1) / 2.0, (y1 - y0 + 1) / 2.0
    dx, dy = (xs - (x0 + x1) / 2.0) / max(rx, 1), (ys - (y0 + y1) / 2.0) / max(ry, 1)
    radius = np.sqrt(dx * dx + dy * dy)
    angle = (np.degrees(np.arctan2(dy, dx)) + 360) % 360
    return len(set((angle[(radius >= 0.85) & (radius <= 1.15)] // 10).astype(int).tolist())) / 36


def side_arc_measurements(image):
    """Left arc, right arc, inside ink, ink height, and which crop edges the ink touches."""
    mask = _ink_mask(image) if image is not None else None
    if mask is None:
        return None
    ys, xs = np.where(mask > 0)
    if len(xs) < 60:
        return None
    x0, x1, y0, y1 = xs.min(), xs.max(), ys.min(), ys.max()
    w, h = x1 - x0 + 1, y1 - y0 + 1
    cx, cy, rx, ry = (x0 + x1) / 2.0, (y0 + y1) / 2.0, w / 2.0, h / 2.0
    dx, dy = (xs - cx) / max(rx, 1), (ys - cy) / max(ry, 1)
    radius = np.sqrt(dx * dx + dy * dy)
    angle = (np.degrees(np.arctan2(dy, dx)) + 360) % 360
    ring = (radius >= 0.62) & (radius <= 1.15)
    sectors = set((angle[ring] // 10).astype(int).tolist())
    left = [k for k in range(36) if 120 <= k * 10 + 5 <= 240]
    right = [k for k in range(36) if k * 10 + 5 >= 300 or k * 10 + 5 <= 60]
    return {
        "left": len(sectors & set(left)) / len(left),
        "right": len(sectors & set(right)) / len(right),
        "inside": np.count_nonzero(radius < 0.5) / max(np.pi * 0.25 * rx * ry, 1),
        "height": int(h),
        "touches_top_or_bottom": bool(y0 <= 1 or y1 >= mask.shape[0] - 2),
    }


def enclosure_evidence(chunk, line_height=None, report=False):
    """
    What surrounds a leading mark, if anything:
      'brackets'        - it was read with ( ) around it
      'circle'          - a full ring with something inside, taller than the line
      'cut-off circle'  - ring cut by the crop's top/bottom edge, but both side
                          arcs are there - it looks like parentheses ( A )
    A star shape ('*') is never an enclosure.
    """
    raw = str(chunk.get("text", ""))
    if "(" in raw and ")" in raw:
        return "brackets"
    try:
        rim = outer_rim_coverage(chunk.get("image"))
        if looks_like_asterisk(chunk) and rim < STAR_MAX_RIM:
            if report:
                print(f"ENCLOSURE TEST on first mark {raw!r}: star shape (spokes, broken rim {rim:.2f}) "
                      f"- an asterisk, not a circled bullet")
            return None
    except Exception:
        pass
    if circled_content_image(chunk, line_height=line_height, report=report) is not None:
        return "circle"
    measured = side_arc_measurements(chunk.get("image"))
    if not measured or not line_height:
        return None
    ratio = measured["height"] / line_height
    if (measured["touches_top_or_bottom"]
            and measured["left"] >= BULLET_SIDE_ARC_MIN and measured["right"] >= BULLET_SIDE_ARC_MIN
            and measured["inside"] >= CIRCLE_MIN_INSIDE_INK and ratio >= CIRCLE_MIN_HEIGHT_RATIO):
        if report:
            print(f"ENCLOSURE TEST on first mark {raw!r}: CUT-OFF circle - both side arcs present "
                  f"(left={measured['left']:.2f} right={measured['right']:.2f}, "
                  f"{ratio:.2f}x line height) -> looks like ( )")
        return "cut-off circle"
    if report:
        print(f"ENCLOSURE TEST on first mark {raw!r}: no enclosure | left arc={measured['left']:.2f} "
              f"right arc={measured['right']:.2f} | {ratio:.2f}x line height | "
              f"cut at top/bottom={measured['touches_top_or_bottom']}")
    return None


def bullet_mark_core(raw):
    """
    BULLET RULE 1: a bullet mark is ONE letter or a NUMBER (1-2 digits), and the
    only other characters allowed are  .  (  )
      'A' '(A)' 'A.' 'B)' '1' '(2)' '10.'  -> 'A' / 'A' / 'A' / 'B' / '1' / '2' / '10'
      '@' '0%' 'A1' '*' '4:' 'AB'          -> None (not a bullet)
    """
    text = re.sub(r"\s+", "", str(raw or "")).upper()
    if not text or not re.fullmatch(r"[A-Z0-9.()]+", text):
        return None
    core = re.sub(r"[.()]", "", text)
    if re.fullmatch(r"[A-Z]", core) or re.fullmatch(r"[0-9]{1,2}", core):
        return core
    return None


def mark_runs_into_number(mark_text, next_text):
    """
    NUMBER GUARD: the first mark is the start of a number, not a bullet, when it
    runs straight into more digits or a percent sign:
      '40.' + '0%'   '1.' + '5%'   '40' + '.0%'   '40' + '%'
    A circled / bracketed mark like '(1)' is closed, so it is never caught here.
    """
    mark = re.sub(r"\s+", "", str(mark_text or ""))
    following = re.sub(r"\s+", "", str(next_text or ""))
    if not following or not re.fullmatch(r"\d{1,3}\.?", mark):
        return False
    if following.startswith("%"):
        return True
    if mark.endswith(".") and following[0].isdigit():
        return True
    if not mark.endswith(".") and re.match(r"\.\d", following):
        return True
    return False


def leading_mark_info(visual_chunks):
    """The first handwritten mark of a line, if it passes bullet rule 1 and the number guard."""
    if not visual_chunks:
        return None
    chunks = sorted(visual_chunks, key=lambda c: (safe_float(c.get("x0", 0.0)), safe_float(c.get("y0", 0.0))))
    first = chunks[0]
    raw = str(first.get("text", ""))
    text = bullet_mark_core(raw)
    if text is None or len(chunks) < 2:
        return None
    following = next((c for c in chunks[1:] if not c.get("ignored_as_noise")), None)
    if following is not None and mark_runs_into_number(raw, following.get("text", "")):
        return None
    heights = [h for h in (ink_height(c.get("image")) for c in chunks[1:] if not c.get("ignored_as_noise")) if h]
    line_height = float(np.median(heights)) if heights else None
    return {
        "text": text,
        "enclosure": enclosure_evidence(first, line_height=line_height),
        "score": safe_float(first.get("score", 0.0)),
    }


def apply_leading_circled_marker_structure(decisions, visual_chunks):
    """
    Whatever is written INSIDE a circle at the start of a Notes line becomes a
    marker in parentheses:  (A) 34.0% ...   (B) 29.0% ...   (1) ...
    The letter inside the circle is read on its own (the whole chunk is often
    misread as @ / 4 / O because of the circle).
    """
    if not decisions or not visual_chunks:
        return decisions
    chunks = sorted(visual_chunks, key=lambda item: (safe_float(item.get("x0", 0.0)), safe_float(item.get("y0", 0.0))))
    if len(chunks) < 2:
        return decisions
    marker_chunk = chunks[0]
    chunk_text = re.sub(r"[^A-Za-z0-9]", "", str(marker_chunk.get("text", ""))).upper()
    if len(chunk_text) > 3:
        return decisions                               # a real word, not a circled mark
    raw_mark = str(marker_chunk.get("text", ""))
    # BULLET RULE 1 on the mark's own read: only a letter / number with . ( )
    # can be a bullet ('*' is not). Exception: '@' - a real @ never starts a
    # line, so a line-start '@' is a circled letter misread and stays allowed.
    compact_mark = re.sub(r"\s+", "", raw_mark)
    if (compact_mark and re.sub(r"[().]", "", compact_mark) != "@"
            and bullet_mark_core(compact_mark) is None):
        print(f"BULLET RULE 1: first mark {raw_mark!r} is not a letter/number with only . ( ) "
              "-> not a bullet")
        return decisions
    following = next((c for c in chunks[1:] if not c.get("ignored_as_noise")), None)
    if following is not None and mark_runs_into_number(raw_mark, following.get("text", "")):
        print(f"BULLET NUMBER GUARD: first mark {raw_mark!r} runs straight into "
              f"{following.get('text', '')!r} -> part of a number, not a bullet")
        return decisions
    other_heights = [
        height for height in (ink_height(c.get("image")) for c in chunks[1:] if not c.get("ignored_as_noise"))
        if height
    ]
    line_height = float(np.median(other_heights)) if other_heights else None
    enclosure = enclosure_evidence(marker_chunk, line_height=line_height, report=True)
    consensus_letter = consensus_bullet_letter(raw_mark) if enclosure is None else None
    if enclosure is None and not consensus_letter:
        return decisions
    if consensus_letter:
        print(f"BULLET EVIDENCE: no circle confirmed, but the whole-line reads show "
              f"'{consensus_letter})' -> treated as a bullet")
    inside = None if consensus_letter else circled_content_image(marker_chunk, line_height=line_height)
    if inside is None and marker_chunk.get("image") is not None:
        image = marker_chunk["image"]          # cut-off circle / brackets: read the middle
        inside = image.crop((int(image.width * 0.2), int(image.height * 0.15),
                             int(image.width * 0.8), int(image.height * 0.85)))

    letter = consensus_letter
    try:
        if letter:
            raise StopIteration                       # letter already known from the consensus
        read = read_isolated_character(inside, alphabetic_only=True)
        if read.get("character") and safe_float(read.get("confidence")) >= 0.30:
            letter = read["character"]
        else:
            read = read_isolated_character(inside, alphabetic_only=False)
            if read.get("character") and safe_float(read.get("confidence")) >= 0.30:
                letter = read["character"]
    except StopIteration:
        pass
    except Exception:
        letter = None
    if not letter:
        # Nothing readable inside the circle: the mark's own read must pass rule 1
        letter = bullet_mark_core(raw_mark)
        if letter is None:
            print(f"BULLET RULE 1: first mark {raw_mark!r} is not a letter/number with only . ( ) "
                  "-> not a bullet")
    if not letter:
        return decisions

    marker = f"({letter.upper()})"
    first_text = str(decisions[0].get("text", "")).strip()
    # drop the circled mark if the text already contains it as a stray token
    first_tokens = first_text.split()
    removed_token = ""
    glued = False
    if first_tokens and re.sub(r"[^A-Za-z0-9]", "", first_tokens[0]).upper() in {chunk_text, letter.upper()} \
            and len(re.sub(r"[^A-Za-z0-9]", "", first_tokens[0])) <= 2:
        removed_token = first_tokens[0]
        first_tokens = first_tokens[1:]
    elif first_tokens:
        rest = split_glued_bullet_letter(first_tokens[0], letter)
        if rest is not None:
            # the circled letter read glued onto the number after it ('A69.O'): the
            # letter is the bullet, the rest is the number
            print(f"CIRCLED MARK GLUED TO THE NUMBER: '{first_tokens[0]}' -> bullet '{letter.upper()}' + '{rest}'")
            removed_token = first_tokens[0][:len(first_tokens[0]) - len(rest)]
            glued = True
            first_tokens = [rest] + first_tokens[1:]
    if first_tokens and first_tokens[0] == marker:
        return decisions
    decisions[0]["text"] = " ".join([marker] + first_tokens)
    decisions[0]["source"] = (str(decisions[0].get("source", "")) + " | circled mark -> parentheses").strip(" |")
    decisions[0]["closed_circle_marker"] = marker
    # Kept so the cross-line bullet pass can put the line back if this marker
    # does not fit the A -> B / 1 -> 2 sequence (bullet rule 2).
    decisions[0]["circled_marker_info"] = {"marker": marker, "removed": removed_token, "glued": glued}
    print()
    print(f"CIRCLED MARK DETECTED: {marker_chunk.get('text', '')!r} -> {marker}")
    return decisions


def split_glued_bullet_letter(token, letter):
    """'A69.O' / 'A)69.O' / 'A.69.0%' with bullet letter A -> '69.O' / '69.O' / '69.0%':
    the token starts with the circled bullet's own letter (optionally followed by ')' or
    '.') and then a digit. Returns what follows the letter, or None when the token does
    not start that way."""
    match = re.fullmatch(r"\(?([A-Za-z])[).:,]{0,2}(\d.*)", str(token or ""))     # S483: 'B.)2B%' too
    if not match or match.group(1).upper() != str(letter or "").upper():
        return None
    return match.group(2)


def apply_visual_numeric_structure(decisions):
    """A physically separated decimal + % sequence beats O/0 confusion."""
    for decision in decisions:
        visual = [item for item in decision.get("visual", []) if not item.get("ignored_as_noise", False)]
        tokens = [normalize_token(item.get("text", "")) for item in visual]
        tokens = [token for token in tokens if token]
        for index in range(max(0, len(tokens) - 1)):
            if index + 1 >= len(tokens):
                break
            number = tokens[index]
            pct = tokens[index + 1]
            if pct == "%" and re.fullmatch(r"\d+(?:\.\d+)?", number):
                current = str(decision.get("text", ""))
                prefix_match = re.match(r"^\s*(\([A-Za-z]\))", current)
                prefix = prefix_match.group(1) + " " if prefix_match else ""
                decision["text"] = prefix + number + "%"
                decision["source"] = (
                    str(decision.get("source", "")) + " | visual numeric decimal/percent structure"
                ).strip(" |")
                print("VISUAL NUMERIC STRUCTURE:", current, "->", decision["text"])
                break
    return decisions


def attach_percent_across_decisions(decisions):
    """
    A '%' piece that sits directly after a number piece belongs to that number,
    even when alignment put the '%' into the NEXT group (where it was then
    dropped because that group kept its whole-line word):
      Decision 1: visual 'A 69. 0'   Decision 2: visual '% EXTERNAC' -> text 'EXTERNAL'
      -> Decision 1 text '... 69. 0%'  (spacing is joined later: 69.0%)
    """
    for index in range(len(decisions) - 1):
        current = [c for c in decisions[index].get("visual", []) if not c.get("ignored_as_noise")]
        following = [c for c in decisions[index + 1].get("visual", []) if not c.get("ignored_as_noise")]
        if not current or not following:
            continue
        last_piece = normalize_token(current[-1].get("text", ""))
        first_piece = normalize_token(following[0].get("text", ""))
        if first_piece != "%" or not re.search(r"\d$", last_piece):
            continue
        current_text = str(decisions[index].get("text", "")).rstrip()
        following_text = str(decisions[index + 1].get("text", ""))
        if current_text.endswith("%") or "%" in following_text:
            continue                                   # the % is already in the text
        if not re.search(r"\d$", current_text):
            continue
        decisions[index]["text"] = current_text + "%"
        decisions[index]["source"] = (
            str(decisions[index].get("source", "")) + " | % attached from next group"
        ).strip(" |")
        print(f"PERCENT ATTACHED ACROSS GROUPS: {current_text!r} -> {decisions[index]['text']!r} "
              f"(the '%' piece was aligned into the next group)")
    return decisions


def collect_leading_colon_anchor(detector_text, whole_attempts):
    """Repeated leading WORD: structure from independent whole-line reads."""
    entries = [{"text": str(detector_text).strip(), "confidence": 0.70}] + list(whole_attempts or [])
    votes = defaultdict(list)
    for entry in entries:
        value = str(entry.get("text", "")).strip()
        confidence = safe_float(entry.get("confidence", 0.0))
        match = re.match(r"^\s*\*?\s*([A-Za-z]{2,14})\s*:", value)   # '* NOTE:' counts too
        if match and confidence >= 0.55:
            votes[match.group(1).upper()].append(confidence)
    if not votes:
        return None
    word, confidences = max(
        votes.items(),
        key=lambda item: (len(item[1]), sum(item[1]) / max(len(item[1]), 1)),
    )
    if len(confidences) < 2:
        return None
    return {
        "word": word,
        "votes": len(confidences),
        "confidence": sum(confidences) / len(confidences),
    }


def refine_leading_colon_anchor_from_visual(anchor, visual_chunks):
    chunks = sorted(
        visual_chunks or [],
        key=lambda item: (safe_float(item.get("x0", 0.0)), safe_float(item.get("y0", 0.0))),
    )
    for index in range(len(chunks) - 1):
        word = normalize_alpha_for_matching(chunks[index].get("text", ""))
        mark = normalize_token(chunks[index + 1].get("text", ""))
        if (
            2 <= len(word) <= 14
            and mark == ":"
            and safe_float(chunks[index].get("score", 0.0)) >= 0.60
        ):
            result = {
                "word": word,
                "votes": max(2, int((anchor or {}).get("votes", 0))),
                "confidence": max(0.90, safe_float((anchor or {}).get("confidence", 0.0))),
                "source": "physical visual WORD + colon",
            }
            print("PHYSICAL LEADING WORD: STRUCTURE:", (anchor or {}).get("word"), "->", word + ":")
            return result
    return anchor


def apply_leading_colon_anchor(text, anchor):
    if not anchor:
        return text
    text = str(text).strip()
    star = ""
    if text.startswith("*"):                      # keep a leading asterisk in front
        star = "* "
        text = text[1:].lstrip()
    match = re.match(r"^\s*[A-Za-z]+:?\s*", text)
    if match:
        remainder = text[match.end():].lstrip()
        return star + anchor["word"] + ":" + ((" " + remainder) if remainder else "")
    return star + text


def apply_at_time_structure(decisions):
    clock_pattern = re.compile(r"^\d{1,2}:\d{2}$")
    not_at_marks = ["%", ".", "(", ")", ":"]

    # A mark and a time that are visual chunks INSIDE the same decision.
    for decision in decisions:
        visual = [item for item in decision.get("visual", []) if not item.get("ignored_as_noise", False)]
        visual_tokens = [normalize_token(item.get("text", "")) for item in visual]
        visual_tokens = [token for token in visual_tokens if token]
        if len(visual_tokens) >= 2:
            final_time = visual_tokens[-1]
            mark = visual_tokens[-2]
            if (
                clock_pattern.fullmatch(final_time)
                and len(re.sub(r"\s+", "", mark)) == 1
                and not mark.isdigit()
                and mark not in not_at_marks
            ):
                rebuilt = visual_tokens[:-2] + ["@", final_time]
                decision["text"] = " ".join(rebuilt)
                decision["source"] = "Physical visual mark immediately before clock time resolved as @"
                decision["at_time_visual_structure"] = {
                    "visual_tokens": visual_tokens,
                    "resolved_tokens": rebuilt,
                }

    # A mark at the end of one decision followed by a time decision.
    for index in range(len(decisions) - 1):
        current = decisions[index]
        following = decisions[index + 1]
        following_text = normalize_token(following.get("text", ""))
        # Only a real clock time (00:37, 8:43, 0O:37, or 843 with the colon lost);
        # a word with digits in it (D165) is NOT a time.
        if not (looks_like_clock_time(following_text) or re.fullmatch(r"\d{3,4}", following_text)):
            continue

        raw_current = str(current.get("text", "")).strip()
        current_parts = raw_current.split()
        current_text = normalize_token(raw_current)

        current_visual = [
            item for item in current.get("visual", []) if not item.get("ignored_as_noise", False)
        ]
        current_visual_tokens = [normalize_token(item.get("text", "")) for item in current_visual]
        current_visual_tokens = [token for token in current_visual_tokens if token]
        if len(current_visual_tokens) >= 2:
            physical_mark = current_visual_tokens[-1]
            physical_prefix = current_visual_tokens[:-1]
            if (
                len(physical_mark) == 1
                and not physical_mark.isdigit()
                and physical_mark not in not_at_marks
                and physical_prefix
            ):
                current["text"] = " ".join(physical_prefix + ["@"])
                current["source"] = "Physical visual trailing mark before clock resolved as @"
                current["at_time_visual_structure"] = {
                    "visual_tokens": current_visual_tokens,
                    "resolved_tokens": physical_prefix + ["@"],
                }
                print(
                    "PRE-ENGLISH PHYSICAL @/TIME STRUCTURE:", raw_current,
                    "| visual=", current_visual_tokens, "->", current["text"], following_text,
                )
                continue

        if len(current_text) == 1 and current_text not in not_at_marks:
            current["text"] = "@"
            current["source"] = "@ before time structure"
            continue

        if len(current_parts) >= 2:
            trailing = normalize_token(current_parts[-1])
            if len(trailing) == 1 and trailing not in not_at_marks:
                current_parts[-1] = "@"
                current["text"] = " ".join(current_parts)
                current["source"] = "Trailing @ before time structure"
    return decisions


def refine_times_after_at(decisions):
    for index in range(len(decisions) - 1):
        if normalize_token(decisions[index].get("text", "")) != "@":
            continue
        time_decision = decisions[index + 1]
        confident_times = [
            e["text"] for e in (LINE_CONSENSUS.get("slots") or [])
            if e["type"] == "time" and e.get("fit", 0) >= CONSENSUS_NUMBER_MIN_SHARE
            and e.get("lead", 0) >= CONSENSUS_NUMBER_MIN_LEAD
        ]
        current_time = consensus_key(re.sub(r"\s+", "", str(time_decision.get("text", ""))))
        if any(same_clock_time(normalize_times_around_colons(current_time), t) for t in confident_times):
            print(f"TIME AFTER @: {current_time} matches the confident whole-line consensus -> image check skipped")
            continue
        visual_images = [
            visual["image"] for visual in time_decision.get("visual", [])
            if visual.get("image") is not None
        ]
        if not visual_images:
            continue
        image = combine_images_horizontal(visual_images, gap=0)
        refinement = refine_time_from_image(image, time_decision["text"])
        time_decision["time_refinement"] = refinement
        if refinement["valid_clock"]:
            time_decision["text"] = refinement["text"]
            time_decision["source"] = "Resolved as time after @"
    return decisions


# ============================================================
# WHOLE-LINE STRUCTURAL PUNCTUATION ANCHORS
# ============================================================

def collect_structural_punctuation_anchors(detector_text, whole_attempts):
    """Remember parentheses / leading percentage seen by the full-line reads."""
    entries = [{"text": str(detector_text).strip(), "confidence": 0.80, "source": "detector"}]
    entries.extend(whole_attempts or [])

    open_confidence = 0.0
    close_confidence = 0.0
    prefix_votes = defaultdict(list)
    for entry in entries:
        value = str(entry.get("text", "")).strip()
        confidence = safe_float(entry.get("confidence", 0.0))
        if value.startswith("(") and confidence >= 0.80:
            open_confidence = max(open_confidence, confidence)
        first_open = value.find("(")
        if first_open >= 0 and value.find(")", first_open + 1) >= 0 and confidence >= 0.80:
            close_confidence = max(close_confidence, confidence)
        match = re.match(r"^\s*\(\s*(\d+(?:\.\d+)?)\s*%", value)
        if match and confidence >= 0.80:
            prefix_votes[match.group(1)].append(confidence)

    best_percent_value = None
    if prefix_votes:
        best_percent_value = max(
            prefix_votes.items(),
            key=lambda item: (len(item[1]), sum(item[1]) / max(len(item[1]), 1)),
        )[0]

    has_open = open_confidence >= 0.80
    # If "(" is established, a matching ")" is expected later in the line.
    has_close = close_confidence >= 0.80 or has_open
    return {
        "has_open": has_open,
        "has_close": has_close,
        "open_confidence": open_confidence,
        "close_confidence": close_confidence,
        "percent_value": best_percent_value,
    }


def apply_structural_punctuation_anchors(text, anchors):
    text = str(text).strip()
    anchors = anchors or {}
    if anchors.get("has_open", False):
        percent_value = anchors.get("percent_value")
        if percent_value:
            replacement = "(" + str(percent_value) + "%"
            if re.match(r"^\s*\(?\s*\d+(?:\.\d+)?\s*%", text):
                text = re.sub(r"^\s*\(?\s*\d+(?:\.\d+)?\s*%", replacement, text, count=1)
            elif not text.startswith("("):
                text = "(" + text
        elif not text.startswith("("):
            text = "(" + text

    if anchors.get("has_close", False):
        first_open = text.find("(")
        if first_open >= 0 and text.find(")", first_open + 1) < 0:
            text = re.sub(r"\s+[A-Za-z]$", "", text).rstrip()
            text += ")"
    return text


# ============================================================
# FINAL-LINE STRUCTURE REPAIRS
# ============================================================

# ============================================================
# NUMBERS WITH LETTERS / GLUED WORDS+DIGITS (final line clean-up)
# ============================================================

LETTER_AS_DIGIT = {"O": "0", "Q": "0", "D": "0", "I": "1", "L": "1", "S": "5", "B": "8", "Z": "2"}
DIGIT_LOOKALIKE_LETTERS = {
    "0": ["O"], "1": ["I", "L"], "2": ["Z"], "4": ["A"], "5": ["S"],
    "6": ["G"], "8": ["B"],
}


def fix_letters_in_numbers(text):
    """
    Number / time / percent shaped tokens: letter look-alikes become digits.
      34.O% -> 34.0%     0O:37 -> 00:37     1O.5 -> 10.5
    Only when the token is mostly digits and has number punctuation (. : %).
    """
    output = []
    for token in str(text).split():
        core = token.strip("()")
        digits = sum(ch.isdigit() for ch in core)
        letters = [ch for ch in core.upper() if ch.isalpha()]
        number_shaped = (
            digits >= 1 and letters and re.search(r"[.:%]", core)
            and all(ch in LETTER_AS_DIGIT for ch in letters)
            and len(letters) <= digits
            and re.fullmatch(r"[0-9A-Za-z.:%]+", core)
        )
        if number_shaped:
            fixed = "".join(LETTER_AS_DIGIT.get(ch.upper(), ch) if ch.isalpha() else ch for ch in core)
            if fixed != core:
                print(f"NUMBER WITH LETTER LOOK-ALIKES: {core} -> {fixed}")
                token = token.replace(core, fixed)
        output.append(token)
    return " ".join(output)


def segment_letters_into_words(letters):
    """
    Best split of a letter run into English words (DIGSINTHIS -> DIGS IN THIS).
    Returns (words, score) or (None, -inf) when no sensible split exists.
    """
    letters = letters.upper()
    n = len(letters)
    best = [(-1e9, None)] * (n + 1)
    best[0] = (0.0, [])
    for end in range(1, n + 1):
        for start in range(max(0, end - 20), end):
            prev_score, prev_words = best[start]
            if prev_words is None:
                continue
            word = letters[start:end]
            freq = zipf_frequency(word.lower(), "en")
            if len(word) == 1 and word not in ("A", "I"):
                word_score = -4.0                    # stray single letter
            elif (freq < 2.5
                  or (len(word) == 2 and freq < 5.0)   # 2-letter words must be common (IN, IS, TO)
                  or (len(word) == 3 and freq < 3.0)):
                word_score = -6.0 * len(word)        # not a (usable) English word
            else:
                word_score = freq - 2.0              # -2: prefer fewer, longer words
            score = prev_score + word_score
            if score > best[end][0]:
                best[end] = (score, prev_words + [word])
    return best[n][1], best[n][0]


def split_glued_token(token, whole_attempts=None):
    """
    A glued letters+digits token (2D16SINTHIS) is split where letters and digits
    meet: 2 | D | 16 | SINTHIS. Every digit piece is tried as a NUMBER and as
    look-alike LETTERS (16 -> IG / LG); letter runs are split into English words.
    The best-scoring reading wins (2 DIGS IN THIS). Returns a list of words or None.
    """
    compact = re.sub(r"[^A-Za-z0-9]", "", str(token)).upper()
    if (len(compact) < 6 or not re.search(r"[A-Z]", compact) or not re.search(r"[0-9]", compact)
            or sum(ch.isalpha() for ch in compact) < 4):
        return None
    runs = re.findall(r"[A-Z]+|[0-9]+", compact)
    choices = []
    for run in runs:
        if run.isalpha():
            choices.append([("L", run, 0)])
            continue
        options = [("N", run, 0)]
        letter_versions = [""]
        for ch in run:
            letter_versions = [v + l for v in letter_versions for l in DIGIT_LOOKALIKE_LETTERS.get(ch, [])]
        for version in letter_versions:
            if version and len(version) == len(run):
                options.append(("L", version, len(run)))
        choices.append(options)

    # Words the whole-line reads saw, also with digit look-alikes as letters
    # (DI6S -> DIGS), so a piece the reads support gets a bonus.
    evidence_words = set()
    for attempt in whole_attempts or []:
        for raw in re.findall(r"[A-Z0-9]+", normalize_line(attempt.get("text", "")).upper()):
            if raw.isalpha():
                evidence_words.add(raw)
            elif re.search(r"[A-Z]", raw):
                versions = [""]
                for ch in raw:
                    versions = [v + l for v in versions for l in (DIGIT_LOOKALIKE_LETTERS.get(ch, [ch]) if ch.isdigit() else [ch])]
                evidence_words.update(versions[:16])

    combos = [[]]
    for options in choices:
        combos = [c + [o] for c in combos for o in options]
        if len(combos) > 256:
            combos = combos[:256]

    best_words, best_score = None, -1e9
    for combo in combos:
        words, score, letters = [], 0.0, ""
        valid = True
        for kind, text, converted in combo + [("END", "", 0)]:
            if kind == "L":
                letters += text
                score -= 1.0 * converted              # each digit->letter swap costs a little
                continue
            if letters:
                segment, seg_score = segment_letters_into_words(letters)
                if segment is None:
                    valid = False
                    break
                words += segment
                score += seg_score
                letters = ""
            if kind == "N":
                words.append(text)
                score += 1.0                          # a plain number is fine
        if not valid:
            continue
        score += 1.5 * sum(1 for w in words if w in evidence_words)
        if score > best_score:
            best_score, best_words = score, words
    if not best_words:
        return None
    if any(w.isalpha() and len(w) > 1 and zipf_frequency(w.lower(), "en") < 2.5 for w in best_words):
        return None
    return best_words


def repair_glued_tokens(text, whole_attempts=None):
    output = []
    for token in str(text).split():
        words = None
        if re.search(r"[A-Za-z]", token) and re.search(r"[0-9]", token) and not re.search(r"[.:%]", token):
            words = split_glued_token(token, whole_attempts)
        if words and " ".join(words) != token.upper():
            print(f"GLUED LETTERS+DIGITS SPLIT: {token} -> {' '.join(words)}")
            output.extend(words)
        else:
            output.append(token)
    return " ".join(output)


def remove_stray_at_marks(text):
    """'@' only belongs before a clock time; elsewhere it is a misread mark."""
    tokens = str(text).split()
    kept = []
    for index, token in enumerate(tokens):
        following = tokens[index + 1] if index + 1 < len(tokens) else ""
        if token == "@" and not re.fullmatch(r"\d{1,2}:\d{2}", following):
            print(f"STRAY @ REMOVED (not before a time): ... @ {following}")
            continue
        kept.append(token)
    return " ".join(kept)


def remove_repeated_word_runs(text):
    """
    Drop a run that repeats the words right before it (after a glued token is
    split): '2 DIGS IN THIS DIES IN THIS PACKET' -> '2 DIGS IN THIS PACKET'.
    Words count as the same when they are near-identical (DIGS ~ DIES).
    """
    tokens = str(text).split()
    changed = True
    while changed:
        changed = False
        for size in range(min(6, len(tokens) // 2), 1, -1):
            for start in range(0, len(tokens) - 2 * size + 1):
                first = tokens[start:start + size]
                second = tokens[start + size:start + 2 * size]
                if not all(w.isalpha() for w in first + second):
                    continue
                if all(a == b or normalized_edit_similarity(a, b) >= 0.74 for a, b in zip(first, second)):
                    print(f"REPEATED WORDS REMOVED: {' '.join(second)}")
                    tokens = tokens[:start + size] + tokens[start + 2 * size:]
                    changed = True
                    break
            if changed:
                break
    return " ".join(tokens)


SPLIT_CLOCK_TIME = re.compile(r"(?<![\d:.])(\d{1,2})(?:\s+:\s*|\s*:\s+)(\d{2})(?![\d:])")


def join_split_clock_time(text):
    """S422: a clock time the reading kept in two pieces because of a gap after (or before) its colon -
    '7: 24' -> '7:24' - so the '@' steps after it see the time (else 'LOSS @ 7: 24' lost its '@' as a stray
    one: '7:' alone is no time)."""
    def join(match):
        joined = f"{match.group(1)}:{match.group(2)}"
        print(f"CLOCK TIME JOINED: '{match.group(0)}' -> '{joined}' (S422)")
        return joined
    return SPLIT_CLOCK_TIME.sub(join, str(text))


def fix_mark_before_clock_time(text):
    """
    A single mark right before a clock time is the handwritten '@'.
    OCR reads a circled @ as 0 / O / C / Q / 6 / E / G / a / & ...:
      "0 8:43" -> "@ 8:43"      "E 00:37" -> "@ 00:37"
    Letters that are real one-letter words / markers (A, I, B after ANOMALY...)
    are only converted when they are not a marker in parentheses.
    """
    tokens = str(text).split()
    for index in range(len(tokens) - 1):
        mark = tokens[index]
        if not looks_like_clock_time(tokens[index + 1]):
            continue
        if mark == "@":
            continue
        if len(mark) == 1 and (not mark.isalnum() or mark.upper() in "0OQCEG6&"):
            tokens[index] = "@"
    # A circled @ is sometimes read as TWO pieces ("0 C 8:43" -> "0 @ 8:43"):
    # a lone mark right before "@ <time>" is part of that same @.
    cleaned = []
    for index, token in enumerate(tokens):
        nxt = tokens[index + 1] if index + 1 < len(tokens) else ""
        after = tokens[index + 2] if index + 2 < len(tokens) else ""
        if (nxt == "@" and looks_like_clock_time(after)
                and (token == "@" or (len(token) == 1 and token.upper() in "0OQCEG6&"))):
            continue
        cleaned.append(token)
    return " ".join(cleaned)


# OCR look-alikes: a read letter/digit that is easily mistaken for another.
OCR_LOOKALIKES = {
    frozenset(pair) for pair in [
        ("O", "D"), ("O", "0"), ("O", "Q"), ("D", "0"), ("S", "5"), ("L", "1"),
        ("I", "1"), ("I", "L"), ("B", "8"), ("Z", "2"), ("G", "6"), ("A", "4"),
        ("U", "V"), ("M", "N"), ("H", "N"), ("C", "L"), ("C", "E"), ("E", "F"),
        ("T", "I"), ("R", "K"), ("W", "V"), ("C", "G"),
    ]
}
DIGIT_AS_LETTER = {"0": "O", "5": "S", "1": "L", "8": "B", "6": "G", "4": "A"}


def digits_as_letter_read(token):
    """205 -> ?OS : digits that look like letters become those letters, others are unknown."""
    return "".join(DIGIT_AS_LETTER.get(ch, "?") for ch in str(token))


def fused_read_cost(word, read):
    """
    How badly `read` fails to be a partial view of `word`.
      letter missing from the read   0.15 (OCR drops letters all the time)
      look-alike swap (D/O, 5/S ...) 0.40
      wrong letter                   1.20
      extra letter in the read       2.00 (OCR rarely invents letters)
      '?' in the read matches anything for free.
    """
    word = str(word).upper()
    read = str(read).upper()
    n, m = len(word), len(read)
    dp = [[0.0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][0] = dp[i - 1][0] + 0.15
    for j in range(1, m + 1):
        dp[0][j] = dp[0][j - 1] + 2.0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            a, b = word[i - 1], read[j - 1]
            if a == b or b == "?":
                sub = 0.0
            elif frozenset((a, b)) in OCR_LOOKALIKES:
                sub = 0.4
            else:
                sub = 1.2
            dp[i][j] = min(
                dp[i - 1][j] + 0.15,       # read missed this letter
                dp[i][j - 1] + 2.0,        # read has an extra letter
                dp[i - 1][j - 1] + sub,
            )
    return dp[n][m]


def fused_word_cost(word, reads, cap=1.5):
    """Total cost of `word` explaining EVERY distinct read (one noisy read is capped)."""
    return sum(min(fused_read_cost(word, read), cap) for read in reads)


def rescue_numeric_tokens_as_words(text, whole_attempts):
    """
    A pure-digit token sitting between words (METAL 205 @ 8:43) may be a
    handwritten WORD the visual chunk read as digits (LOSS -> 205).
    Evidence comes from the repeated whole-line reads: the alphabetic token
    each read saw in that same position (after the left word / before the
    right anchor). A word needs support from 2+ independent reads, and the
    contextual language model (when available) must prefer it over the digits.
    """
    tokens = str(text).split()
    if len(tokens) < 2:
        return text
    attempt_token_lists = [
        normalize_line(attempt.get("text", "")).split()
        for attempt in whole_attempts or []
    ]
    attempt_token_lists = [t for t in attempt_token_lists if t]

    for index, token in enumerate(tokens):
        if not re.fullmatch(r"\d{2,4}", token):
            continue
        left = tokens[index - 1] if index > 0 else ""
        if not re.fullmatch(r"[A-Za-z]{3,}", left):
            continue                       # only numbers sitting after a word
        right = None
        for following in tokens[index + 1:]:
            if len(following) > 1:
                right = following
                break

        # ---- what did each whole-line read see at EXACTLY this position?
        evidence = []                       # one set of words per read that saw a word
        number_votes = 0                    # reads that saw digits here
        for attempt_tokens in attempt_token_lists:
            positions = set()
            scores = [text_similarity(left, t) for t in attempt_tokens]
            if scores and max(scores) >= 0.5:
                j = scores.index(max(scores))
                if j + 1 < len(attempt_tokens):
                    positions.add(j + 1)
            if right is not None:
                r_scores = [text_similarity(right, t) for t in attempt_tokens]
                if r_scores and max(r_scores) >= 0.6:
                    k = r_scores.index(max(r_scores))
                    if k - 1 >= 0:
                        positions.add(k - 1)
            seen = [attempt_tokens[p] for p in positions]
            words = {
                t for t in seen
                if re.fullmatch(r"[A-Z]{2,8}", t)
                and text_similarity(t, left) < 0.8
                and (right is None or text_similarity(t, right) < 0.8)
            }
            if any(re.fullmatch(r"\d{2,4}", t) for t in seen):
                number_votes += 1
            elif words:
                evidence.append(words)
        if len(evidence) < 2 or len(evidence) <= number_votes:
            continue

        # ---- English candidates grown from that evidence
        seeds = sorted({t for found in evidence for t in found})
        candidates = set()
        for seed in seeds:
            for item in generate_general_english_candidates([seed], len(seed), max_candidates=25):
                word = item["text"]
                if zipf_frequency(word.lower(), "en") >= 3.0:
                    candidates.add(word)
        candidates.discard(left.upper())
        if right:
            candidates.discard(right.upper())

        # ---- FUSE the partial reads: the true word must explain ALL of them.
        # Each distinct read is one partial view (LO, LOS, LDSS); the visual
        # chunk's digits are one more view (205 -> ?OS).
        reads = sorted({t for found in evidence for t in found})
        digit_read = digits_as_letter_read(token)
        if digit_read.strip("?"):
            reads.append(digit_read)
        longest = max(len(r) for r in reads)

        ranked = []
        for word in candidates:
            if len(word) < longest - 1:
                continue                     # cannot contain the longest read
            ranked.append({"word": word, "cost": fused_word_cost(word, reads)})
        if not ranked:
            continue
        ranked.sort(key=lambda item: (item["cost"], -zipf_frequency(item["word"].lower(), "en")))
        best_cost = ranked[0]["cost"]
        ranked = [item for item in ranked if item["cost"] <= best_cost + 1.0][:15]

        print()
        print("NUMERIC TOKEN INSIDE WORDS:", token, "| context:", left, "<", token, ">", right)
        print("  Partial reads to fuse:", reads)
        print("  Best fusions (lower = explains all reads better):",
              ", ".join(f"{r['word']}({r['cost']:.2f})" for r in ranked))

        original_sentence = " ".join(tokens)
        original_lm = contextual_sentence_log_probability(original_sentence)
        chosen = None
        if original_lm is not None:
            # Fusion cost leads; the language model confirms / breaks near-ties.
            best_total = None
            best_lm = None
            for item in ranked:
                trial = tokens[:index] + [item["word"]] + tokens[index + 1:]
                lm = contextual_sentence_log_probability(" ".join(trial))
                item["lm"] = lm
                if lm is None:
                    continue
                total = lm - 0.7 * item["cost"]
                item["total"] = total
                if best_total is None or total > best_total:
                    best_total = total
                    best_lm = lm
                    chosen = item
            for item in sorted(ranked, key=lambda i: i.get("total", -99), reverse=True)[:5]:
                if item.get("lm") is not None:
                    print(f"    {item['word']}: fusion cost={item['cost']:.2f} LM={item['lm']:.3f} total={item['total']:.3f}")
            if chosen is None or best_lm <= original_lm:
                print("  Kept the number: language model prefers the digits.")
                continue
            print(f"  LM: digits={original_lm:.3f} -> {chosen['word']}={best_lm:.3f}")
        else:
            print("  Kept the number: language model unavailable (type the word in the correction box).")
            continue

        print("  NUMERIC -> WORD:", token, "->", chosen["word"])
        tokens[index] = chosen["word"]
    return " ".join(tokens)


def clean_final_spacing(text):
    text = str(text)
    # A number split by the visual chunker: "40. 0%" -> "40.0%"
    text = re.sub(r"(\d)\.\s+(\d)", r"\1.\2", text)
    text = re.sub(r"\s+%", "%", text)
    text = re.sub(r"\(\s+", "(", text)
    text = re.sub(r"\s+\)", ")", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def restore_outer_punctuation(text, detector_text, whole_attempts=None):
    detector_text = str(detector_text).strip()
    whole_attempts = whole_attempts or []
    opening_evidence = detector_text.startswith("(")

    strongest_open_confidence = 0.0
    for attempt in whole_attempts:
        attempt_text = str(attempt.get("text", "")).strip()
        if attempt_text.startswith("("):
            strongest_open_confidence = max(
                strongest_open_confidence, safe_float(attempt.get("confidence", 0.0)),
            )
    if strongest_open_confidence >= 0.80:
        opening_evidence = True

    if opening_evidence and not text.startswith("("):
        text = "(" + text

    first_open_index = text.find("(")
    if first_open_index >= 0 and text.find(")", first_open_index + 1) < 0:
        text += ")"
    return text


# ============================================================
# SEQUENTIAL NOTES-LINE CONTEXT / JOINED-WORD SPACING
# ============================================================

def previous_notes_context_words(previous_lines, maximum_words=14):
    """Line 2 sees finished Line 1; Line 3 sees Lines 1+2; and so on."""
    words = []
    for line in previous_lines or []:
        text = line.get("text", "") if isinstance(line, dict) else str(line)
        words.extend(alpha_words_from_text(text))
    if maximum_words and len(words) > maximum_words:
        words = words[-maximum_words:]
    return [normalize_alpha_for_matching(word) for word in words if word]


def visual_word_sequence_for_result(result):
    output = []
    for chunk in result.get("visual_chunks", []) or []:
        for word in alpha_words_from_text(str(chunk.get("text", "")).strip()):
            cleaned = normalize_alpha_for_matching(word)
            if cleaned:
                output.append(cleaned)
    return output


def joined_word_split_candidates(word):
    """Two-word splits of a joined token where both pieces are real words."""
    word = normalize_alpha_for_matching(word)
    if len(word) < 4:
        return []
    candidates = []
    for split_at in range(1, len(word)):
        left = word[:split_at]
        right = word[split_at:]
        if len(left) == 1 and left not in {"A", "I"}:
            continue
        if len(right) == 1 and right not in {"A", "I"}:
            continue
        left_frequency = zipf_frequency(left.lower(), "en")
        right_frequency = zipf_frequency(right.lower(), "en")
        if left_frequency < 2.2 or right_frequency < 2.2:
            continue
        phrase = left + " " + right
        candidates.append({
            "text": phrase,
            "left": left,
            "right": right,
            "left_frequency": left_frequency,
            "right_frequency": right_frequency,
            "phrase_frequency": phrase_frequency_raw(phrase),
        })
    return candidates


def previous_context_phrase_score(previous_words, candidate_words):
    previous_words = [normalize_alpha_for_matching(x) for x in previous_words if x]
    candidate_words = [normalize_alpha_for_matching(x) for x in candidate_words if x]
    if not candidate_words:
        return 0.0, []
    combined = previous_words + candidate_words
    start_current = len(previous_words)

    windows = []
    for size in (2, 3, 4, 5):
        for end in range(start_current + 1, len(combined) + 1):
            start = end - size
            if start < 0 or end <= start_current:
                continue
            phrase = " ".join(combined[start:end])
            windows.append((phrase, phrase_frequency_raw(phrase), phrase_frequency_score(phrase), size))
    if not windows:
        return 0.0, []

    scored = []
    for phrase, raw, normalized, size in windows:
        weight = 1.0 + 0.10 * max(0, size - 2)
        scored.append((normalized * weight, phrase, raw, normalized, size))
    scored.sort(reverse=True)
    top = scored[:5]
    return clamp(sum(item[0] for item in top) / len(top)), top


def refine_joined_words_with_previous_lines(result, previous_lines):
    """Split joined OCR words (ATSEAM -> AT SEAM) when evidence agrees."""
    text = str(result.get("text", "")).strip()
    if not text:
        return result

    previous_words = previous_notes_context_words(previous_lines)
    visual_words = visual_word_sequence_for_result(result)
    current_words = alpha_words_from_text(text)
    if not current_words:
        return result

    updated_text = text
    spacing_log = []
    for original_word in current_words:
        word = normalize_alpha_for_matching(original_word)
        if len(word) < 4:
            continue
        joined_frequency = zipf_frequency(word.lower(), "en")
        split_candidates = joined_word_split_candidates(word)
        if not split_candidates:
            continue

        best = None
        for candidate in split_candidates:
            left = candidate["left"]
            right = candidate["right"]
            visual_support = 0.0
            for i in range(len(visual_words) - 1):
                if visual_words[i] == left and visual_words[i + 1] == right:
                    visual_support = 1.0
                    break
            context_score, context_windows = previous_context_phrase_score(previous_words, [left, right])
            phrase_score = phrase_frequency_score(candidate["text"])
            piece_score = clamp((english_frequency_score(left) + english_frequency_score(right)) / 2.0)
            score = (
                visual_support * 0.40
                + phrase_score * 0.20
                + piece_score * 0.18
                + context_score * 0.22
            )
            if joined_frequency >= 2.5 and visual_support < 1.0:
                continue
            if visual_support < 1.0 and phrase_score < 0.26:
                continue
            candidate_info = dict(candidate)
            candidate_info.update({
                "score": score,
                "visual_support": visual_support,
                "context_score": context_score,
                "context_windows": context_windows,
            })
            if best is None or score > best["score"]:
                best = candidate_info

        if best is None:
            continue
        required = 0.42 if best["visual_support"] >= 1.0 else 0.58
        if best["score"] < required:
            continue

        pattern = re.compile(
            r"(?<![A-Za-z])" + re.escape(original_word) + r"(?![A-Za-z])", re.IGNORECASE,
        )
        new_text, count = pattern.subn(best["text"], updated_text, count=1)
        if count:
            print()
            print("SEQUENTIAL NOTES CONTEXT / JOINED-WORD SPACING:")
            print(
                "Previous finished Notes context:",
                " ".join(previous_words) if previous_words else "<none>",
            )
            print(f"Joined token: {original_word} -> {best['text']}")
            print(
                "visual_support=", f"{best['visual_support']:.3f}",
                "phrase_score=", f"{phrase_frequency_score(best['text']):.3f}",
                "previous_context=", f"{best['context_score']:.3f}",
                "total=", f"{best['score']:.3f}",
            )
            updated_text = new_text
            spacing_log.append({"before": original_word, "after": best["text"], **best})

    result["text"] = clean_final_spacing(updated_text)
    result["sequential_context_words"] = previous_words
    result["joined_word_spacing"] = spacing_log
    return result


# ============================================================
# READ ONE NOTES LINE
# ============================================================

def looks_like_clock_time(text):
    """8:43 / 00:37 / 0O:37 / B:43  (letter look-alikes allowed before the check)."""
    core = str(text or "").strip().upper()
    core = "".join(LETTER_AS_DIGIT.get(ch, ch) if ch.isalpha() else ch for ch in core)
    return re.fullmatch(r"\d{1,2}:\d{2}", core) is not None


AT_MARK_MIN_RING = 0.75       # the @'s outer curl goes most of the way round
AT_MARK_MIN_INSIDE = 0.10     # ...with the small 'a' curl inside it


def ring_measurements(image):
    """(ring coverage, inside share) of a mark, measured like a clock face; None if no ink."""
    mask = _ink_mask(image) if image is not None else None
    if mask is None:
        return None
    ys, xs = np.where(mask > 0)
    if len(xs) < 40:
        return None
    x0, x1, y0, y1 = xs.min(), xs.max(), ys.min(), ys.max()
    w, h = x1 - x0 + 1, y1 - y0 + 1
    if not (0.45 <= w / max(h, 1) <= 2.2) or min(w, h) < 8:
        return None
    cx, cy, rx, ry = (x0 + x1) / 2.0, (y0 + y1) / 2.0, w / 2.0, h / 2.0
    dx, dy = (xs - cx) / max(rx, 1), (ys - cy) / max(ry, 1)
    radius = np.sqrt(dx * dx + dy * dy)
    angle = (np.degrees(np.arctan2(dy, dx)) + 360) % 360
    ring = (radius >= 0.62) & (radius <= 1.15)
    coverage = len(set((angle[ring] // (360 / CIRCLE_SECTORS)).astype(int).tolist())) / CIRCLE_SECTORS
    inside = np.count_nonzero(radius < 0.5) / max(np.pi * 0.25 * rx * ry, 1)
    return coverage, inside


def looks_like_at_mark(chunk):
    """The handwritten @: an outer curl most of the way round with ink inside."""
    measured = ring_measurements(chunk.get("image"))
    if not measured:
        return False
    coverage, inside = measured
    return coverage >= AT_MARK_MIN_RING and inside >= AT_MARK_MIN_INSIDE


def keep_at_mark_before_time(visual_chunks):
    """
    The handwritten '@' sits RIGHT BEFORE a clock time and is often misread:
      - dropped as noise ('C ... IGNORED AS LOW-CONTENT')  -> small mark kept as '@'
      - read as a digit ('2', the detector even shows a circled 2)
        -> kept as '@' only when it is CIRCLE-SHAPED with something inside
           (a circled 'a' is exactly what '@' looks like)
    Rescued chunks are flagged, so the '@' can be put back in front of that
    time if alignment later drops it.
    """
    for index, chunk in enumerate(visual_chunks[:-1]):
        following = next((c for c in visual_chunks[index + 1:] if not c.get("ignored_as_noise")), None)
        if following is None or not looks_like_clock_time(following.get("text")):
            continue
        text = re.sub(r"\s+", "", str(chunk.get("text", "")))
        if text == "@" or len(text) > 2:
            continue
        reason = None
        if chunk.get("ignored_as_noise") and not any(ch.isdigit() for ch in text):
            reason = "small mark dropped as noise"
        elif looks_like_at_mark(chunk):
            reason = "@-shaped mark (curl with ink inside)"
        if not reason:
            continue
        print(f"KEPT '@' MARK BEFORE TIME: chunk {text!r} -> '@' ({reason}; before {following.get('text')})")
        chunk["ignored_as_noise"] = False
        chunk["text"] = "@"
        chunk["at_mark_before_time"] = True
        chunk["at_following_time"] = following.get("text")
    return visual_chunks


def restore_at_before_time(final_text, visual_chunks):
    """
    If a chunk was recognised as the '@' but alignment dropped it, put '@' back
    in front of the time it was physically written before.
    """
    marks = [c for c in visual_chunks or [] if c.get("at_mark_before_time")]
    if not marks:
        return final_text
    tokens = str(final_text).split()
    for mark in marks:
        target = str(mark.get("at_following_time", ""))
        target_norm = "".join(LETTER_AS_DIGIT.get(ch, ch) if ch.isalpha() else ch for ch in target.upper())
        for index, token in enumerate(tokens):
            if not looks_like_clock_time(token):
                continue
            token_norm = "".join(LETTER_AS_DIGIT.get(ch, ch) if ch.isalpha() else ch for ch in token.upper())
            if token_norm != target_norm and len(marks) > 1:
                continue
            if index == 0 or tokens[index - 1] != "@":
                print(f"'@' RESTORED before {token} (the mark was written there; alignment had dropped it)")
                tokens.insert(index, "@")
            break
    return " ".join(tokens)


ASTERISK_MIN_SPOKES = 6          # * has 6-8 spokes (real one: 7); W has 5; X / + have 4
ASTERISK_SPOKE_COVERAGE = 0.70   # ink along >= 70% of the way from centre outward
ASTERISK_MAX_CONFIDENT_SCORE = 0.60


# S361: the 36 directions (every 10 degrees) x 12 steps outward (22%-85% of the way), worked out once
SPOKE_ANGLES = np.radians(np.arange(0, 360, 10)).reshape(-1, 1)
SPOKE_STEPS = np.linspace(0.22, 0.85, 12).reshape(1, -1)
SPOKE_COS, SPOKE_SIN = np.cos(SPOKE_ANGLES) * SPOKE_STEPS, np.sin(SPOKE_ANGLES) * SPOKE_STEPS


def count_spokes(box, cx, cy, rx, ry):
    """Number of separate ink 'spokes' running outward from (cx, cy). S361: all 36 x 12 points at once
    (numpy) instead of one at a time - the same points, the same rounding, the same 70% rule."""
    h, w = box.shape
    xs = np.rint(cx + SPOKE_COS * rx).astype(int)
    ys = np.rint(cy + SPOKE_SIN * ry).astype(int)
    inside = (xs >= 0) & (xs < w) & (ys >= 0) & (ys < h)
    total = inside.sum(axis=1)
    inked = (box[np.clip(ys, 0, h - 1), np.clip(xs, 0, w - 1)] & inside).sum(axis=1)
    share = np.divide(inked, total, out=np.zeros(len(total)), where=total > 0)
    hits = (total > 0) & (share >= ASTERISK_SPOKE_COVERAGE)
    if hits.all():
        return 0                         # a solid blob, not strokes
    return int((hits & ~np.roll(hits, 1)).sum())


def looks_like_asterisk(chunk):
    """
    Star SHAPE: 5+ separate spokes of ink running outward from one centre
    (an X plus a centre line gives 6). X / + have 4, letters fewer, and a
    letter with an empty middle cannot fake spokes.
    """
    image = chunk.get("image")
    if image is None:
        return False
    mask = _ink_mask(image)
    if mask is None:
        return False
    ys, xs = np.where(mask > 0)
    if len(xs) < 40:
        return False
    x0, x1, y0, y1 = xs.min(), xs.max(), ys.min(), ys.max()
    w, h = x1 - x0 + 1, y1 - y0 + 1
    if not (0.5 <= w / max(h, 1) <= 2.0) or min(w, h) < 10:
        return False
    box = mask[y0:y1 + 1, x0:x1 + 1] > 0
    box = cv2.dilate(box.astype(np.uint8), cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (3, 3))) > 0
    rx, ry = w / 2.0, h / 2.0
    best = 0
    for sx in (-0.12, -0.06, 0.0, 0.06, 0.12):          # hand-drawn centre wobble
        for sy in (-0.12, -0.06, 0.0, 0.06, 0.12):
            cx, cy = rx + sx * w, ry + sy * h
            if not box[int(cy), int(cx)]:
                continue                                  # strokes must cross at the centre
            best = max(best, count_spokes(box, cx, cy, rx, ry))
    return best >= ASTERISK_MIN_SPOKES


def mark_leading_asterisk(visual_chunks):
    """
    '*' is RARE, so it is the LAST interpretation tried for the first mark on a line:
      1. circled marker  (a circle with something inside -> handled as (A)/(B))
      2. '@' before a time  (already applied before this runs)
      3. a CONFIDENT OCR read (letter / number) stays as read
      4. only a leftover, low-confidence, 1-2 character mark with the star
         shape becomes '*' - kept in its real position, so it flows through
         the normal steps like any other piece.
    """
    if not visual_chunks:
        return visual_chunks
    chunks = sorted(visual_chunks, key=lambda c: (safe_float(c.get("x0", 0.0)), safe_float(c.get("y0", 0.0))))
    first = chunks[0]
    text = re.sub(r"\s+", "", str(first.get("text", "")))
    if text == "*" or len(text) > 2 or text == "@":
        return visual_chunks
    confident = (not first.get("ignored_as_noise")
                 and safe_float(first.get("score", 0.0)) >= ASTERISK_MAX_CONFIDENT_SCORE)
    if confident:
        return visual_chunks                                        # 3. confident read wins
    heights = [hgt for hgt in (ink_height(c.get("image")) for c in chunks[1:] if not c.get("ignored_as_noise")) if hgt]
    line_height = float(np.median(heights)) if heights else None
    if circled_content_image(first, line_height=line_height) is not None:
        return visual_chunks                                        # 1. circled marker wins
    if not looks_like_asterisk(first):
        return visual_chunks
    print(f"ASTERISK (last resort): first mark read as {text!r} "
          f"(score={safe_float(first.get('score', 0.0)):.2f}) has a star shape -> '*'")
    first["text"] = "*"
    first["ignored_as_noise"] = False
    first["asterisk"] = True
    return visual_chunks


OCR_JUNK_TOKEN = re.compile(r"^\(?CID:?\d*\)?:?$", re.IGNORECASE)


def remove_anchor_colon_junk(text, whole_attempts, anchor):
    """
    '(CID:)' is a known OCR junk string: always removed.
    The colon after a leading word ('NOTE:') is sometimes read as its own piece
    '0' / 'O'. That piece is removed only when NONE of the whole-line reads saw a
    0 / O right after the word (they saw 'NOTE:2', 'NOTE2' ...).
    """
    tokens = [t for t in str(text).split() if not OCR_JUNK_TOKEN.fullmatch(t)]
    if len(tokens) != len(str(text).split()):
        print("OCR JUNK REMOVED: (CID:)")
    if anchor and anchor.get("word"):
        word = str(anchor["word"]).upper()
        for index, token in enumerate(tokens[:-1]):
            if token.rstrip(":").upper() != word:
                continue
            nxt = tokens[index + 1]
            if nxt.upper() not in ("0", "O", "."):
                break
            seen_zero = False
            for attempt in whole_attempts or []:
                compact = re.sub(r"\s+", "", normalize_line(attempt.get("text", "")).upper())
                position = compact.find(word)
                if position < 0:
                    continue
                after = compact[position + len(word):].lstrip(":;.")
                if after[:1] in ("0", "O"):
                    seen_zero = True
                    break
            if not seen_zero:
                print(f"COLON PIECE REMOVED after {word}: {nxt!r} (no whole-line read has it)")
                tokens.pop(index + 1)
            break
    return " ".join(tokens)


def collect_word_evidence(decisions, evidence):
    """
    Keep every word ranking this line produced (both English passes), so a later
    cross-line check can see what the line ITSELF thought of each alternative:
      evidence = [{"before": w, "after": w2, "scores": {WORD: best score}}, ...]
    """
    for decision in decisions or []:
        for correction in decision.get("english_word_corrections", []) or []:
            scores = {}
            for candidate in correction.get("candidates", []) or []:
                text = str(candidate.get("text", "")).upper()
                if text:
                    scores[text] = max(scores.get(text, 0.0), safe_float(candidate.get("score", 0.0)))
            if not scores:
                continue
            evidence.append({
                "before": str(correction.get("before", "")).upper(),
                "after": str(correction.get("after", "")).upper(),
                "scores": scores,
            })
    return evidence


def clean_numbers_and_junk_before_english(decisions):
    """
    Runs the number and junk clean-ups BEFORE the English passes, so letters that
    are really digits or OCR junk are not treated as English words:
      34.O% -> 34.0%     0O:37 -> 00:37     (CID:) -> removed
    Otherwise the English scoring sees 'O' / 'CID' as neighbour words
    ('O < EFTERNAL', 'LOSS > O') and the language model scores those too.
    The same clean-ups still run again at the end of the line as a backstop.
    """
    for number, decision in enumerate(decisions, start=1):
        before = str(decision.get("text", "")).strip()
        if not before:
            continue
        kept = [token for token in before.split() if not OCR_JUNK_TOKEN.fullmatch(token)]
        if len(kept) != len(before.split()):
            print(f"OCR JUNK REMOVED BEFORE ENGLISH: decision {number}: {before!r}")
        after = fix_letters_in_numbers(" ".join(kept)) if kept else ""
        if after != before:
            decision["text"] = after
            decision["source"] = (
                str(decision.get("source", "")) + " | numbers/junk cleaned before English"
            ).strip(" |")
            print(f"CLEANED BEFORE ENGLISH: decision {number}: {before!r} -> {after!r}")
    return decisions


OVERLAP_CLEAR_WIN_MARGIN = 0.5    # overlap winner must beat the next word by this much to be kept


def resolve_overlap_word(tail, pieces):
    """
    The word written where a group's whole-line text ('...DIS') and the next
    group's digit-read pieces ('7 165') describe the SAME ink. Candidates come
    from the whole-line word; each is scored by how well it explains BOTH the
    whole-line word and the pieces read as look-alike letters ('7165' -> '?LGS').
    """
    look_read = "".join(
        ch if ch.isalpha() else DIGIT_AS_LETTER.get(ch, "?") for ch in pieces
    )
    reads = [tail]
    if look_read.strip("?"):
        reads.append(look_read)
    candidates = {}
    for length in sorted({len(tail), len(pieces)}):
        for item in generate_general_english_candidates([tail], length, max_candidates=60):
            word = item["text"]
            if zipf_frequency(word.lower(), "en") >= 3.0:
                candidates[word] = fused_word_cost(word, reads)
    if not candidates:
        return tail, []
    ranked = sorted(candidates.items(), key=lambda kv: (kv[1], -zipf_frequency(kv[0].lower(), "en")))
    return ranked[0][0], ranked[:6]


def reconcile_baseline_image_overlap(decisions):
    """
    Fixes groups whose TEXT and IMAGES cover different words:
      Group 1: text 'NOTE:2DIS' (whole-line read kept)  images '* NOTE 2'
      Group 2: text '7 165 IN'  (visual pieces)          images '7 165 IN'
    'DIS' and '7 165' are the SAME handwritten word counted twice. Group 1 gets
    the text of its own images ('* NOTE 2' - keeps the '*'), and the word goes
    to group 2, resolved from the whole-line word + the pieces' look-alike letters.
    """
    for index in range(len(decisions) - 1):
        first, second = decisions[index], decisions[index + 1]
        first_visual = [c for c in first.get("visual", []) if not c.get("ignored_as_noise")]
        second_visual = [c for c in second.get("visual", []) if not c.get("ignored_as_noise")]
        if len(first.get("baseline", [])) != 1 or not first_visual or not second_visual:
            continue
        first_text = str(first.get("text", "")).strip()
        if normalize_token(first_text) != normalize_token(baseline_group_text(first["baseline"])):
            continue                                   # group 1 did not keep its whole-line read
        whole = re.sub(r"[^A-Z0-9]", "", first_text.upper())
        seen = re.sub(r"[^A-Z0-9]", "", visual_group_concat(first_visual).upper())
        if not seen or not whole.startswith(seen) or len(whole) - len(seen) < 2:
            continue
        tail = whole[len(seen):]
        if sum(ch.isalpha() for ch in tail) < 2:
            continue

        second_base = re.sub(r"[^A-Z0-9]", "", baseline_group_text(second.get("baseline", [])).upper())
        extra = []
        for chunk in second_visual:
            piece = re.sub(r"[^A-Z0-9]", "", normalize_token(chunk.get("text", "")).upper())
            if piece and second_base.startswith(piece):
                break
            extra.append(chunk)
        if not extra or len(extra) == len(second_visual):
            continue
        extra_text = " ".join(normalize_token(c.get("text", "")) for c in extra)
        second_text = str(second.get("text", "")).strip()
        if not second_text.startswith(extra_text):
            continue
        pieces = re.sub(r"[^A-Z0-9]", "", extra_text.upper())
        if not re.search(r"\d", pieces) or not (len(tail) <= len(pieces) <= len(tail) + 2):
            continue

        word, ranked = resolve_overlap_word(tail, pieces)
        first["text"] = visual_group_text(first_visual)
        second["text"] = (word + " " + second_text[len(extra_text):].strip()).strip()
        first["source"] = (str(first.get("source", "")) + " | text trimmed to its own images").strip(" |")
        second["source"] = (str(second.get("source", "")) + " | overlap word resolved").strip(" |")
        print()
        print(f"TEXT/IMAGE OVERLAP FIX: whole-line '{first_text}' covers ink that went to the next group")
        print(f"  group {index + 1}: '{first_text}' -> '{first['text']}'   (its own images)")
        print(f"  group {index + 2}: '{second_text}' -> '{second['text']}'   "
              f"(whole-line '{tail}' + pieces '{extra_text}')")
        if ranked:
            print("  word candidates (lower = explains both better): "
                  + ", ".join(f"{w}({c:.2f})" for w, c in ranked))
        if (
            len(ranked) >= 2 and ranked[0][0] == word
            and ranked[1][1] - ranked[0][1] >= OVERLAP_CLEAR_WIN_MARGIN
            and zipf_frequency(word.lower(), "en") >= 2.3
        ):
            lock_word(second, 0, word,
                      f"overlap fix clear winner, lead {ranked[1][1] - ranked[0][1]:.2f}")
            print(f"  {word} is a clear winner (lead {ranked[1][1] - ranked[0][1]:.2f} over "
                  f"{ranked[1][0]}) -> KEPT (no candidate search or re-checks)")
    return decisions


JOINED_WORD_MIN_ZIPF = 2.5            # S486: each half of a split must be at least this common an English word
JOINED_WORD_CONTEXT_GAIN = 0.05       # S486: and the line must read better with the split by at least this much


def split_joined_words(decisions):
    """S486: two words read as one ('INTHIS', 'ACSEAM', 'NOTE:3'). A letters-only piece that is not an English word
    gets the splits whose halves are both English words (letters exactly as read, in order) as candidates; the
    context check - its left and right neighbours, as for every word - decides: the split is kept only when the
    line reads better with it. A word glued to a number by a colon ('NOTE:3') is spaced when the word is English.
    A split piece takes no part in the later word-candidate steps (its words are taken as they are)."""
    flat = [(d_index, t_index, token) for d_index, d in enumerate(decisions)
            for t_index, token in enumerate(str(d.get("text") or "").split())]
    words = [token for _d, _t, token in flat]
    changed = {}
    for position, (d_index, t_index, token) in enumerate(flat):
        colon = re.fullmatch(r"([A-Za-z]{2,}):(\d+)", token)
        if colon and is_general_english_word(colon.group(1)):
            changed[(d_index, t_index)] = f"{colon.group(1)}: {colon.group(2)}"
            print(f"SPLIT INTO WORDS: {token} -> {changed[(d_index, t_index)]} (an English word, its colon, a number) "
                  f"(S486)")
            continue
        if not re.fullmatch(r"[A-Za-z]{4,}", token) or is_general_english_word(token):
            continue
        left = next((w for w in reversed(words[:position]) if re.fullmatch(r"[A-Za-z]+", w)), None)
        right = next((w for w in words[position + 1:] if re.fullmatch(r"[A-Za-z]+", w)), None)
        upper = token.upper()
        splits = [(upper[:cut], upper[cut:]) for cut in range(1, len(upper))
                  if all((len(half) >= 2 or half in ("A", "I"))
                         and is_general_english_word(half, JOINED_WORD_MIN_ZIPF) for half in (upper[:cut], upper[cut:]))]
        if not splits:
            continue
        current = contextual_phrase_score(upper, left, right)
        scored = sorted(((contextual_phrase_score(f"{a} {b}", left, right), f"{a} {b}") for a, b in splits),
                        reverse=True)
        best_score, best = scored[0]
        print(f"SPLIT CHECK: {left or 'None'} < {token} > {right or 'None'} - as one word {current:.3f}; "
              + "; ".join(f"{text} {score:.3f}" for score, text in scored[:4]) + " (S486)")
        if best_score >= current + JOINED_WORD_CONTEXT_GAIN:
            changed[(d_index, t_index)] = best
            print(f"SPLIT INTO WORDS: {token} -> {best} (both English words; the line reads better with them) (S486)")
    for d_index, decision in enumerate(decisions):
        tokens = str(decision.get("text") or "").split()
        new = [changed.get((d_index, t_index), token) for t_index, token in enumerate(tokens)]
        if new != tokens:
            decision["text"] = " ".join(new)
            decision["english_word_corrections"] = []          # its words now are what they are - no old candidates
            decision["source"] = (str(decision.get("source", "")) + " | joined words split (S486)").strip(" |")
    return decisions


NOTES_PRINTED_CONTEXT = {}            # S484: {'results', 'path'} of the Dig Packet whose Notes lines are being read
NOTES_SHORT_WORDS = {"A", "I", "AT", "IN", "OF", "ON", "TO", "IS", "OR", "AN", "AS", "BY", "NO", "UP", "IT", "@"}
NEIGHBOUR_LEAD_KEEP = 0.10            # S484: a word the neighbour check chose this far ahead of the next is kept


def notes_line_printed(text):
    """S484: what is printed for the anomaly of the Notes line being read (notes_printed_for) - None when the line
    has no bullet / anomaly it can be tied to, or nothing is printed for it."""
    results, path = NOTES_PRINTED_CONTEXT.get("results"), NOTES_PRINTED_CONTEXT.get("path")
    if not results:
        return None
    wheels = {item.get("marker") or "": item.get("value")
              for item in (results.get("Wheel Count") or {}).get("items") or []}
    letter = notes_line_letter(text, wheels) if wheels else None
    if letter is None:
        return None
    return notes_printed_for(results, path, wheels.get(letter))


def notes_printed_before_sentence_check(decisions):
    """S484: the line put right from what is printed for its anomaly (notes_line_fixed - the depth's stray mark,
    the colon of the time, the @, look-alike event words) BEFORE the whole-sentence check, piece by piece in its
    own place. Returns (decisions, True when a piece now holds a different number of words)."""
    texts = [str(d.get("text") or "") for d in decisions]
    counts = [len(t.split()) for t in texts]
    tokens = [token for t in texts for token in t.split()]
    line = " ".join(tokens)
    if "%" not in line:
        return decisions, False
    printed = notes_line_printed(line)
    if printed is None:
        return decisions, False
    new_tokens, fixes, _differs, _compared = notes_line_fixed(tokens, printed)
    if not fixes:
        return decisions, False
    moved, position = False, 0
    for decision, count in zip(decisions, counts):
        new_text = " ".join(new_tokens[position:position + count])
        position += count
        if count and new_text != decision.get("text"):
            moved = moved or len(alpha_words_from_text(new_text)) != len(alpha_words_from_text(decision.get("text", "")))
            decision["text"] = new_text
            decision["printed_fixed"] = True
            decision["source"] = (str(decision.get("source", "")) + " | printed values (S484)").strip(" |")
    print()
    print(f"NOTES BEFORE THE SENTENCE CHECK: '{line}' -> '{' '.join(new_tokens)}' ({'; '.join(fixes)}; "
          f"{printed['where']}) (S484)")
    return decisions, moved


def notes_line_nonwords(decisions):
    """S484: the pieces of a Notes line that are not words, numbers, a depth %, a time, a bullet or the @ - garbage
    a sentence cannot be judged with ('22%O', 'BC', 'IO'). Printed event words count as words."""
    tokens = [token for d in decisions for token in str(d.get("text") or "").split()]
    known = notes_line_known_words(" ".join(tokens))
    return [token for index, token in enumerate(tokens) if not notes_token_fits(token, index, known)]


def notes_line_known_words(text):
    """S484: the printed event's words of a Notes line's anomaly (and EXTERNAL / INTERNAL) - words even when the
    English word list does not know them."""
    printed = notes_line_printed(text) or {}
    return set(re.findall(r"[A-Z]+", str(printed.get("event") or "").upper())) | {"EXTERNAL", "INTERNAL"}


def notes_token_fits(token, index, known):
    """S484: a Notes line piece that is a word, a number, a depth %, a time, the line's bullet or the @."""
    if index == 0 and re.fullmatch(r"\(?[A-Z][).:,]{0,2}\)?", token):
        return True                                        # the bullet
    if re.fullmatch(r"[(*]*[\d.,]+%?[)]*|\d{1,2}[:.]\d{2}|[\d+.]+|[@*()\-.,:]+", token):
        return True
    core = re.sub(r"[^A-Za-z0-9]", "", token).upper()
    return not core or (core.isalpha() and (core in known or (core in NOTES_SHORT_WORDS if len(core) <= 2
                                                              else is_general_english_word(core))))


def notes_word_runs(decisions):
    """S485: the stretches of a Notes line made only of words, between its non-words - each as its pieces
    (decisions), when it holds at least two words. A piece put right from the printed values is not in one."""
    known = notes_line_known_words(" ".join(str(d.get("text") or "") for d in decisions))
    runs, run, position = [], [], 0
    for decision in decisions:
        tokens = str(decision.get("text") or "").split()
        words_only = not decision.get("printed_fixed") and all(
            notes_token_fits(t, position + i, known) and re.search(r"[A-Za-z]", t) for i, t in enumerate(tokens))
        position += len(tokens)
        if tokens and words_only:
            run.append(decision)
            continue
        if tokens:
            runs.append(run)
            run = []
    runs.append(run)
    return [r for r in runs if sum(len(alpha_words_from_text(d.get("text", ""))) for d in r) >= 2]


def read_notes_line(line_image, detector_text, detector_confidence, previous_notes_lines=None,
                    black_white_image=None):
    print()
    print(f"CHAR-FIRST PIPELINE VERSION: {CHARACTER_LOCK_PIPELINE_VERSION}")
    _lap = lap_timer(3, measure=True)                               # S405

    baseline_1_attempts = collect_whole_line_attempts(line_image, detector_text, detector_confidence)
    _lap(f"Whole-line reads ({len(baseline_1_attempts)})")
    # baseline 2: the same line on page 1's step 4 (all ink black on white)
    black_white_attempts = collect_black_white_attempts(black_white_image)
    if black_white_attempts:
        _lap(f"Black/white whole-line reads ({len(black_white_attempts)})")
    # every later step of the line (agreement counts, baseline tokens, character
    # confidence, rescues, repairs) uses the reads of BOTH baselines; each baseline's
    # own consensus is built from its own reads only (below)
    whole_attempts = baseline_1_attempts + black_white_attempts
    remember_line_whole_reads(whole_attempts)
    structural_anchors = collect_structural_punctuation_anchors(detector_text, whole_attempts)
    leading_colon_anchor = collect_leading_colon_anchor(detector_text, whole_attempts)
    if leading_colon_anchor:
        print("Repeated leading WORD: structure remembered:", leading_colon_anchor)
    if structural_anchors.get("has_open", False) or structural_anchors.get("has_close", False):
        print("Full-line structural punctuation remembered:", structural_anchors)

    baseline_tokens = build_baseline_tokens(whole_attempts, detector_text)
    character_profiles = build_pre_candidate_character_profiles(line_image, baseline_tokens, whole_attempts)
    _lap("Character confidence")

    print()
    print("=" * 70)
    print("WHOLE-LINE BASELINE")
    print("=" * 70)
    for attempt in baseline_1_attempts:
        print(f'{attempt["source"]}: {attempt["text"]} ({attempt["confidence"]:.3f})')
    print()
    print(f"Baseline tokens (from the reads of both baselines, {len(whole_attempts)}):")
    print([token["text"] for token in baseline_tokens])

    # S130: the printed rows are checked straight away, on the raw whole-line reads - a
    # line that matches is written from its row and the consensus work below is skipped
    known_line = text_first_note_line(whole_attempts)       # S102: the printed rows first
    if known_line:
        for attempt in black_white_attempts:
            print(f'{attempt["source"]}: {attempt["text"]} ({attempt["confidence"]:.3f})')
        text, why = known_line
        print()
        print(f"TEXT FIRST: the whole-line reads match a printed row - {why} (consensus not needed - S130)")
        print("=" * 70)
        print("FINAL LINE:")
        print(text)
        print("=" * 70)
        return {"text": text, "leading_mark": None, "circled_marker": None, "word_evidence": [],
                "whole_attempts": whole_attempts, "baseline_tokens": baseline_tokens,
                "character_profiles": character_profiles, "visual_chunks": [], "visual_gap_threshold": None,
                "structural_anchors": structural_anchors, "alignment": [], "decisions": [],
                "sentence_sanity": [], "sequential_context_words": [], "joined_word_spacing": [],
                "text_first": why}

    LINE_CONSENSUS.clear()
    try:
        LINE_CONSENSUS.update(build_whole_line_consensus(baseline_1_attempts))
    except Exception as exc:
        print("Whole-line consensus failed:", exc)
    print_whole_line_consensus(LINE_CONSENSUS)
    _lap("Whole-line consensus 1 (incl. language model load when it happens)")

    # SECOND whole-line baseline: the same line on page 1's step 4 (all ink black on
    # white), with its own consensus, compared with the first; the FINAL whole-line
    # consensus is then made between the two (merge_line_consensus).
    if black_white_image is None:
        print()
        print("WHOLE-LINE BASELINE 2: no black/white page for this line (page 1 has no colour map) - skipped")
    elif not black_white_attempts:
        print()
        print("WHOLE-LINE BASELINE 2: nothing was read on the black/white line - skipped")
    if black_white_attempts:
        print()
        print("=" * 70)
        print("WHOLE-LINE BASELINE 2 - BLACK/WHITE (page 1 step 4: all ink black on white)")
        print("=" * 70)
        for attempt in black_white_attempts:
            print(f'{attempt["source"]}: {attempt["text"]} ({attempt["confidence"]:.3f})')
        try:
            black_white_consensus = build_whole_line_consensus(black_white_attempts)
        except Exception as exc:
            print("Black/white consensus failed:", exc)
            black_white_consensus = {}
        print_whole_line_consensus(black_white_consensus,
                                   title="WHOLE-LINE CONSENSUS 2 (black/white reads combined)")
        compare_line_consensus(LINE_CONSENSUS, black_white_consensus)
        if black_white_consensus:
            # the FINAL whole-line consensus is between the two - it is what the rest of
            # the line's reading uses from here on
            final_consensus = merge_line_consensus(dict(LINE_CONSENSUS), black_white_consensus)
            LINE_CONSENSUS.clear()
            LINE_CONSENSUS.update(final_consensus)
            print_final_line_consensus(LINE_CONSENSUS)
        _lap("Black/white consensus 2 + compare + final consensus")

    print()
    print("=" * 70)
    print("INDEPENDENT VISUAL CHUNKS")
    print("=" * 70)
    raw_chunks, visual_gap_threshold = create_independent_visual_chunks(line_image)
    _lap("Split into visual chunks")
    print("Visual gap threshold:", visual_gap_threshold)
    print("Visual chunks:", len(raw_chunks))
    visual_chunks = ocr_visual_chunks(raw_chunks)
    visual_chunks = keep_at_mark_before_time(visual_chunks)
    visual_chunks = mark_leading_asterisk(visual_chunks)
    _lap(f"All visual chunks ({len(visual_chunks)})")
    leading_colon_anchor = refine_leading_colon_anchor_from_visual(leading_colon_anchor, visual_chunks)

    usable_visual_chunks = [chunk for chunk in visual_chunks if not chunk.get("ignored_as_noise", False)]
    ignored_count = len(visual_chunks) - len(usable_visual_chunks)
    if ignored_count:
        print()
        print(f"Ignoring {ignored_count} weak visual chunk(s) before alignment.")

    print()
    print("=" * 70)
    print("DYNAMIC ALIGNMENT")
    print("=" * 70)
    alignment = dynamically_align_sequences(baseline_tokens, usable_visual_chunks)
    decisions = []
    for number, item in enumerate(alignment, start=1):
        decision = choose_aligned_group_output(item)
        decisions.append(decision)
        print()
        print(f"Decision {number}:")
        print("  Baseline:", baseline_group_text(decision["baseline"]))
        print("  Visual:", visual_group_text(decision["visual"]))
        print("  Result:", decision["text"])
        print("  Source:", decision["source"])

    # Physical structure BEFORE any English candidate search.
    decisions = reconcile_baseline_image_overlap(decisions)
    decisions = apply_leading_circled_marker_structure(decisions, visual_chunks)
    decisions = apply_visual_numeric_structure(decisions)
    decisions = attach_percent_across_decisions(decisions)
    decisions = apply_at_time_structure(decisions)
    decisions = merge_mixed_tokens_with_whole_line_evidence(decisions, whole_attempts)
    decisions = apply_repeated_whole_line_missing_character_rescue(decisions, whole_attempts)
    decisions = resolve_mixed_pattern_tokens_with_sentence_context(
        decisions, previous_notes_context_words(previous_notes_lines or []),
    )
    decisions = repair_mixed_alphanumeric_word_decisions(decisions)
    decisions = repair_mixed_alphanumeric_tokens_inside_decisions(decisions)
    decisions = clean_numbers_and_junk_before_english(decisions)
    decisions = apply_consensus_numbers(decisions)
    _lap("Alignment + structure fixes")

    before_first_english_pass = tuple(decision.get("text", "") for decision in decisions)
    words_before_first_pass = flat_line_words(decisions)
    WORK_TIMES.clear()
    work_started = time.perf_counter()
    decisions = general_english_correction_pass(decisions)
    word_evidence = collect_word_evidence(decisions, [])
    _lap("English correction pass 1")
    print_work_breakdown(time.perf_counter() - work_started, 4)
    after_first_english_pass = tuple(decision.get("text", "") for decision in decisions)
    first_english_pass_changed = after_first_english_pass != before_first_english_pass

    decisions = refine_times_after_at(decisions)
    _lap("Time check after @")
    after_structure_pass = tuple(decision.get("text", "") for decision in decisions)
    structure_changed = after_structure_pass != after_first_english_pass

    if first_english_pass_changed or structure_changed:
        print()
        print("Text changed before second English pass -> running verification correction pass.")
        recheck = pass_two_recheck_indexes(words_before_first_pass, flat_line_words(decisions))
        if recheck is None:
            print("Word count changed -> every word is re-checked.")
        WORK_TIMES.clear()
        work_started = time.perf_counter()
        decisions = general_english_correction_pass(decisions, only_flat_indexes=recheck)
        collect_word_evidence(decisions, word_evidence)
        _lap("English correction pass 2")
        print_work_breakdown(time.perf_counter() - work_started, 4)
    else:
        print()
        print("No text changed -> redundant second English pass skipped.")

    # S484: the pieces that are not words yet (the depth with a stray mark, the @, the time, a bullet) are settled
    # first - from what the packet prints for this line's anomaly - and the whole-sentence language model only
    # judges a line that is made of words; a word the neighbour check chose with a clear lead stays
    decisions = split_joined_words(decisions)                    # S486: 'INTHIS' -> 'IN THIS' when context says so
    decisions, words_moved = notes_printed_before_sentence_check(decisions)
    nonwords = notes_line_nonwords(decisions)
    if every_word_settled(decisions):
        print()
        print("Every word in this line is settled -> language-model step and sentence check skipped.")
        sentence_sanity_log = []
    elif nonwords or words_moved:
        print()
        print("SENTENCE CHECK WAITS: " + (f"the line still has non-words ({', '.join(nonwords)})" if nonwords else
                                          "the printed values changed which words the line has")
              + " - the whole-sentence language model judges only the stretches made of words (S484/S485)")
        # S485: every stretch of two or more words in a row (nothing else between them) is checked as a sentence -
        # English and context - on its own
        for run in notes_word_runs(decisions):
            print(f"SENTENCE CHECK ON THE WORDS: '{' '.join(d['text'] for d in run)}' (between the line's "
                  f"non-words) (S485)")
            WORK_TIMES.clear()
            work_started = time.perf_counter()
            contextual_language_model_rescue(run)                 # its pieces are the line's own (changed in place)
            _lap("Contextual language model (words between non-words)")
            print_work_breakdown(time.perf_counter() - work_started, 4)
        decisions, sentence_sanity_log = final_sentence_sanity_pass(
            decisions,
            previous_context_words=previous_notes_context_words(previous_notes_lines or []),
        )
    else:
        WORK_TIMES.clear()
        work_started = time.perf_counter()
        decisions = contextual_language_model_rescue(decisions)
        _lap("Contextual language model")
        print_work_breakdown(time.perf_counter() - work_started, 4)
        decisions, sentence_sanity_log = final_sentence_sanity_pass(
            decisions,
            previous_context_words=previous_notes_context_words(previous_notes_lines or []),
        )

    _lap("Sentence sanity check")
    final_text = " ".join(decision["text"] for decision in decisions if decision["text"])
    final_text = restore_outer_punctuation(final_text, detector_text, whole_attempts)
    final_text = apply_structural_punctuation_anchors(final_text, structural_anchors)
    final_text = apply_leading_colon_anchor(final_text, leading_colon_anchor)
    final_text = clean_final_spacing(final_text)
    final_text = apply_leading_colon_anchor(final_text, leading_colon_anchor)

    sequential_result = refine_joined_words_with_previous_lines(
        {"text": final_text, "visual_chunks": visual_chunks},
        previous_notes_lines or [],
    )
    final_text = sequential_result.get("text", final_text)
    final_text = apply_structural_punctuation_anchors(final_text, structural_anchors)
    final_text = clean_final_spacing(final_text)

    final_text = resolve_deferred_mixed_tokens_with_full_sentence(final_text, decisions)
    final_text = repair_mixed_alphanumeric_tokens_in_final_text(final_text)
    final_text = clean_final_spacing(final_text)
    final_text = fix_letters_in_numbers(final_text)
    final_text = repair_glued_tokens(final_text, whole_attempts)
    final_text = join_split_clock_time(final_text)                          # S422
    final_text = fix_mark_before_clock_time(final_text)
    final_text = restore_at_before_time(final_text, visual_chunks)
    final_text = remove_stray_at_marks(final_text)
    final_text = remove_repeated_word_runs(final_text)
    final_text = rescue_numeric_tokens_as_words(final_text, whole_attempts)
    final_text = clean_final_spacing(final_text)
    final_text = apply_leading_colon_anchor(final_text, leading_colon_anchor)
    final_text = remove_anchor_colon_junk(final_text, whole_attempts, leading_colon_anchor)
    final_text = fix_tokens_from_other_reads(final_text, whole_attempts)     # S98
    _lap("Final fixes (punctuation, @ time, number->word)")

    print()
    print("=" * 70)
    print("FINAL LINE:")
    print(final_text)
    print("=" * 70)

    return {
        "text": final_text,
        "leading_mark": leading_mark_info(visual_chunks),
        "circled_marker": (decisions[0].get("circled_marker_info") if decisions else None),
        "word_evidence": word_evidence,
        "whole_attempts": whole_attempts,
        "baseline_tokens": baseline_tokens,
        "character_profiles": character_profiles,
        "visual_chunks": visual_chunks,
        "visual_gap_threshold": visual_gap_threshold,
        "structural_anchors": structural_anchors,
        "alignment": alignment,
        "decisions": decisions,
        "sentence_sanity": sentence_sanity_log,
        "sequential_context_words": sequential_result.get("sequential_context_words", []),
        "joined_word_spacing": sequential_result.get("joined_word_spacing", []),
    }


# ============================================================
# EXTRACT NOTES
# ============================================================
# The printed "19. Notes:" label is removed from the TEXT only; the images
# given to OCR are the original, unmasked crops.

def strip_known_notes_header(text, found_label_text="Notes:"):
    if text is None:
        return ""
    cleaned = str(text).strip()
    if not cleaned:
        return ""

    label_word = clean_label_text(found_label_text)
    label_variants = {"notes", "note", "noles"}
    if label_word:
        label_variants.add(label_word)
    label_pattern = "(?:" + "|".join(
        re.escape(value) for value in sorted(label_variants, key=len, reverse=True) if value
    ) + ")"
    prefix_pattern = re.compile(
        r"^\s*(?:19\s*[\.:\-)]?\s*)?" + label_pattern + r"\s*[\.:\-]?\s*",
        re.IGNORECASE,
    )
    previous = None
    while cleaned and cleaned != previous:
        previous = cleaned
        cleaned = prefix_pattern.sub("", cleaned, count=1).strip()
    return cleaned


def detector_item_is_only_known_notes_header(item_text, found_label_text="Notes:"):
    if item_text is None:
        return False
    text = str(item_text).strip()
    if not text:
        return False
    if strip_known_notes_header(text, found_label_text) == "":
        return True
    return is_notes_label(text)


def group_notes_detector_items_by_physical_row(items):
    """Merge detector boxes that are visibly on the same handwritten row."""
    if not items:
        return []
    items = sorted(items, key=lambda item: (item["y0"], item["x0"]))
    rows = []
    for item in items:
        item_h = max(1, item["y1"] - item["y0"])
        item_cy = (item["y0"] + item["y1"]) / 2.0
        best = None
        best_score = -1.0
        for row_index, row_items in enumerate(rows):
            ry0 = min(x["y0"] for x in row_items)
            ry1 = max(x["y1"] for x in row_items)
            rh = max(1, ry1 - ry0)
            rcy = (ry0 + ry1) / 2.0
            overlap = max(0, min(item["y1"], ry1) - max(item["y0"], ry0))
            overlap_ratio = overlap / max(1, min(item_h, rh))
            center_ratio = abs(item_cy - rcy) / max(item_h, rh)
            if overlap_ratio >= 0.34 or center_ratio <= 0.38:
                score = overlap_ratio - center_ratio * 0.25
                if score > best_score:
                    best_score = score
                    best = row_index
        if best is None:
            rows.append([item])
        else:
            rows[best].append(item)

    grouped = []
    for row_items in rows:
        row_items = sorted(row_items, key=lambda item: item["x0"])
        x0 = min(x["x0"] for x in row_items)
        y0 = min(x["y0"] for x in row_items)
        x1 = max(x["x1"] for x in row_items)
        y1 = max(x["y1"] for x in row_items)
        widths = [max(1, x["x1"] - x["x0"]) for x in row_items]
        confidence = sum(
            x.get("confidence", 0.0) * w for x, w in zip(row_items, widths)
        ) / max(sum(widths), 1)
        grouped.append({
            "text": " ".join(x["text"] for x in row_items).strip(),
            "confidence": confidence,
            "x0": x0, "y0": y0, "x1": x1, "y1": y1,
            "width": max(1, x1 - x0),
            "height": max(1, y1 - y0),
            "center_x": (x0 + x1) / 2.0,
            "center_y": (y0 + y1) / 2.0,
            "source_items": row_items,
        })
    grouped.sort(key=lambda item: (item["y0"], item["x0"]))
    return grouped


BULLET_LOOKALIKES = {"4": "A", "8": "B", "6": "G", "0": "O", "1": "I", "5": "S", "2": "Z"}
BULLET_PREFIX = re.compile(r"^\s*(?:\(([A-Z0-9]{1,2})\)|([A-Z0-9]{1,2})[.)])\s+(.*)$")


def _bullet_step(marker):
    """A -> 0, B -> 1 ... / '3' -> 3 ; None if not a simple bullet."""
    if marker.isdigit():
        return int(marker)
    if len(marker) == 1 and marker.isalpha():
        return ord(marker) - ord("A")
    return None


def bullet_sequence_options(marker):
    """The marker as read, then its look-alike (a circled A is often read as 4)."""
    options = [marker]
    lookalike = BULLET_LOOKALIKES.get(marker)
    if lookalike and lookalike not in options:
        options.append(lookalike)
    return [option for option in options if _bullet_step(option) is not None]


def bullet_is_sequence_start(option):
    """A list starts at A (letters) or 1 (numbers)."""
    return _bullet_step(option) == (1 if option.isdigit() else 0)


def bullet_sequence_label(is_digit, step):
    return str(step) if is_digit else chr(ord("A") + step)


def enforce_bullet_sequence(entries):
    """
    BULLET RULE 2: bullets follow a sequence - A then B then C, or 1 then 2 then 3 -
    and a list starts at A or 1. Lines without a bullet (and '*' lines) are skipped
    over and do not break the sequence. Look-alikes count (4 -> A, 8 -> B).
    A marker that fits neither the next step nor a new start is rejected.
    """
    expected = None                     # (is_digit, step) the next bullet must have
    for entry in entries:
        if not entry["marker"]:
            continue
        options = bullet_sequence_options(entry["marker"])
        chosen, how = None, None
        if expected is not None:
            for option in options:
                if option.isdigit() == expected[0] and _bullet_step(option) == expected[1]:
                    chosen, how = option, "next in the sequence"
                    break
        if chosen is None:
            for option in options:
                if bullet_is_sequence_start(option):
                    chosen, how = option, "starts a sequence"
                    break
        if chosen is None:
            wanted = (bullet_sequence_label(*expected) + " (or a new list at A / 1)"
                      if expected is not None else "A or 1 to start a list")
            print(f"BULLET REJECTED (rule 2): line {entry['index'] + 1}: {entry['marker']!r} "
                  f"does not fit the A->B / 1->2 sequence - expected {wanted}")
            entry["rejected_marker"] = entry["marker"]
            entry["marker"] = None
            continue
        if chosen != entry["marker"]:
            print(f"BULLET LOOK-ALIKE: line {entry['index'] + 1}: {entry['marker']!r} read as "
                  f"{chosen!r} ({how})")
            entry["marker"] = chosen
        expected = (chosen.isdigit(), _bullet_step(chosen) + 1)
    return entries


def normalize_note_bullets(line_results, page1_bullets=None):
    """
    After ALL Notes lines are read, find list bullets and give them one format.
    Rule 1: a bullet mark is one letter or a number, with only . ( ) around it.
    Number guard: a mark running straight into digits / % is part of a number.
    Rule 2: bullets run A -> B -> C or 1 -> 2 -> 3, starting at A or 1.
    Within those rules, a line's first mark is a bullet when it is at the start and:
      - it has something around it (circle, cut-off circle / parentheses, brackets), or
      - neighbouring lines have bullets and it FITS THE SEQUENCE (A before (B)),
        even when the OCR read it but alignment dropped it, or
      - it does not make sense in the sentence (a lone letter other than A/I, or
        a lone letter/number right before a number) AND other lines have bullets.
    Bullets then all get the format of the clearly detected ones, e.g. (A) (B).
    Lines starting with '*' keep their asterisk and do not break the sequence.
    """
    entries = []
    for index, line in enumerate(line_results):
        text = str(line.get("text", "")).strip()
        entry = {"index": index, "text": text, "marker": None, "style": None,
                 "rest": text, "candidate": None, "evidence": [], "hidden": False}
        if not text or text.startswith("*"):
            entries.append(entry)
            continue
        match = BULLET_PREFIX.match(text)
        if match and bullet_mark_core(match.group(1) or match.group(2)) is None:
            match = None                                # rule 1: e.g. 'A1)' is not a bullet
        if match:
            entry["marker"] = match.group(1) or match.group(2)
            entry["style"] = "paren" if match.group(1) else ("dot" if text.lstrip()[len(entry["marker"])] == "." else "close")
            entry["rest"] = match.group(3)
            entries.append(entry)
            continue
        tokens = text.split()
        mark = line.get("leading_mark") or {}
        first = tokens[0].upper() if tokens else ""
        if (len(tokens) >= 2 and re.fullmatch(r"[A-Z0-9]{1,2}", first)
                and bullet_mark_core(first) is not None
                and not mark_runs_into_number(first, tokens[1])):
            entry["candidate"] = first
            entry["rest"] = " ".join(tokens[1:])
            nonsense = (first.isalpha() and first not in ("A", "I")) or bool(re.match(r"\d", tokens[1]))
            if nonsense:
                entry["evidence"].append("does not fit the sentence")
        elif mark.get("text") and not text.upper().startswith(mark["text"]):
            entry["candidate"] = mark["text"]           # read by OCR, dropped during alignment
            entry["hidden"] = True
        if entry["candidate"] and mark.get("enclosure") and mark.get("text") == entry["candidate"]:
            entry["evidence"].append(f"{mark['enclosure']} around it")
        entries.append(entry)

    known = [e for e in entries if e["marker"]]
    style = "paren"
    if known:
        styles = [e["style"] for e in known]
        style = max(set(styles), key=styles.count)

    def fits_sequence(entry):
        marked = [e for e in entries if e["marker"] or e["candidate"]]
        position = marked.index(entry)
        for other in marked:
            if not other["marker"]:
                continue
            step_other = _bullet_step(other["marker"])
            for guess in {entry["candidate"], BULLET_LOOKALIKES.get(entry["candidate"], entry["candidate"])}:
                step_guess = _bullet_step(guess)
                if step_other is None or step_guess is None:
                    continue
                if other["marker"].isdigit() != guess.isdigit():
                    continue
                if step_other - step_guess == marked.index(other) - position:
                    return guess
        return None

    for entry in entries:
        if not entry["candidate"]:
            continue
        guess = fits_sequence(entry) if known else None
        if guess:
            entry["evidence"].append(f"fits the sequence of the other bullets ({guess})")
        accepted = any("around it" in ev for ev in entry["evidence"]) or bool(guess) or (
            known and any("does not fit" in ev for ev in entry["evidence"]))
        if not accepted:
            continue
        entry["marker"] = guess or entry["candidate"]
        entry["style"] = style
        entry["accepted_now"] = True

    # No clearly detected bullet anywhere: two or more line-start marks that RUN IN
    # ORDER (A, B / 1, 2 - look-alikes allowed), at least one of which does not fit
    # its sentence or has something around it, are a list too.
    pending = [e for e in entries if e["candidate"] and not e["marker"]]
    if not any(e["marker"] for e in entries) and len(pending) >= 2:
        letters = [BULLET_LOOKALIKES.get(e["candidate"], e["candidate"]) for e in pending]
        for guesses in (letters, [e["candidate"] for e in pending]):
            steps = [_bullet_step(g) for g in guesses]
            same_kind = len({g.isdigit() for g in guesses}) == 1
            in_order = same_kind and None not in steps and all(b - a == 1 for a, b in zip(steps, steps[1:]))
            if in_order and any(e["evidence"] for e in pending):
                for entry, guess in zip(pending, guesses):
                    entry["marker"] = guess
                    entry["style"] = style
                    entry["evidence"].append("line-start marks run in order " + ", ".join(guesses))
                break

    # S89: page 1 says how many bullets the packet has. When the Notes have exactly that
    # many lines with a percentage (the anomaly lines), those lines are (A), (B), ... in
    # order - a bullet nobody could read is filled in, instead of the ones that WERE read
    # being thrown out for 'not starting at A'. Only when no bullet already read says
    # otherwise (a read (B) on the first of these lines leaves everything as it was).
    if page1_bullets and page1_bullets >= 2:
        anomaly_lines = [e for e in entries if e["text"] and not e["text"].startswith("*") and "%" in e["text"]]
        letters = [chr(ord("A") + i) for i in range(page1_bullets)]
        if len(anomaly_lines) == page1_bullets and not any(
                e["marker"] and e["marker"].upper() not in (letter, BULLET_LOOKALIKES.get(e["marker"], "").upper())
                for e, letter in zip(anomaly_lines, letters)):
            for number, (entry, letter) in enumerate(zip(anomaly_lines, letters), start=1):
                if entry["marker"] == letter:
                    continue
                entry["marker"] = letter
                entry["style"] = style
                entry["evidence"].append(f"page 1 has {page1_bullets} bullets and the Notes have {page1_bullets} "
                                         f"lines with a %: this is line {number} of them -> ({letter})")
                line_results[entry["index"]]["bullet_filled"] = True        # S99: look for its circle

    enforce_bullet_sequence(entries)

    for entry in entries:
        if entry.get("rejected_marker"):
            # A circled marker written by the per-line step that failed rule 2:
            # put the line back the way it was read.
            circle = line_results[entry["index"]].get("circled_marker")
            if circle and entry["text"].startswith(circle["marker"]):
                joiner = "" if circle.get("glued") else " "
                restored = f"{circle.get('removed', '')}{joiner}{entry['text'][len(circle['marker']):].strip()}".strip()
                print(f"BULLET: line {entry['index'] + 1}: {entry['text']!r} -> {restored!r}  "
                      "(circled marker removed - not in the sequence)")
                line_results[entry["index"]]["text"] = restored
            continue
        if not entry["marker"]:
            continue
        marker = entry["marker"]
        formatted = {"paren": f"({marker})", "dot": f"{marker}.", "close": f"{marker})"}[style]
        new_text = f"{formatted} {entry['rest']}".strip()
        if new_text != entry["text"]:
            why = "; ".join(entry["evidence"]) or "matching the other bullets' format"
            print(f"BULLET: line {entry['index'] + 1}: {entry['text']!r} -> {new_text!r}  ({why})")
            line_results[entry["index"]]["text"] = new_text
    return line_results


VERTICAL_MIN_SAME_WORDS = 0.60     # share of word positions that must match exactly
VERTICAL_MAX_WORD_DIFFERENCE = 2   # only words 1-2 letters apart are compared


def _piece_kind(token):
    if token == "@":
        return "at"
    if re.fullmatch(r"\d{1,2}:\d{2}", token):
        return "time"
    if re.search(r"\d", token):
        return "number"
    if re.fullmatch(r"[A-Z]+", token):
        return "word"
    return "other"


def _split_line_for_vertical(text):
    """(prefix, pieces): the bullet / '*' prefix is kept aside and never compared."""
    text = str(text or "").strip()
    match = re.match(r"^(\*|\([A-Z0-9]{1,2}\)|[A-Z0-9]{1,2}[.)])\s+(.*)$", text)
    if match:
        return match.group(1), match.group(2).split()
    return "", text.split()


def _letters_apart(a, b):
    """Edit distance (insert / delete / substitute)."""
    previous = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        current = [i]
        for j, cb in enumerate(b, 1):
            current.append(min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + (ca != cb)))
        previous = current
    return previous[-1]


def _line_support(line, word):
    """(best score this line gave `word`, how many of its whole-line reads contain it)."""
    score = 0.0
    for group in line.get("word_evidence", []) or []:
        score = max(score, safe_float(group["scores"].get(word, 0.0)))
    reads = 0
    for attempt in line.get("whole_attempts", []) or []:
        tokens = re.findall(r"[A-Z]+", normalize_line(attempt.get("text", "")).upper())
        reads += word in tokens
    return score, reads


def _line_considered(line, word, alternative):
    """Did this line itself rank `alternative` as a candidate for its `word`?"""
    for group in line.get("word_evidence", []) or []:
        involved = set(group["scores"]) | {group["before"], group["after"]}
        if word in involved and alternative in involved:
            return True
    return False


VERTICAL_LM_TOLERANCE = 0.05   # new sentence may not read worse than this (LM log-probability)


def vertical_change_fits_own_line(pieces, index, mine, theirs):
    """
    A word taken from a parallel line must also make sense in ITS OWN line:
    the whole line is scored by the language model with the old word and with the
    new word; the change stands only if the sentence reads at least as well.
    Falls back to the neighbour-word context score if the model is unavailable.
    """
    old_sentence = " ".join(pieces)
    new_pieces = list(pieces)
    new_pieces[index] = theirs
    new_sentence = " ".join(new_pieces)
    try:
        lm_old = contextual_sentence_log_probability(old_sentence)
        lm_new = contextual_sentence_log_probability(new_sentence)
    except Exception:
        lm_old = lm_new = None
    if lm_old is not None and lm_new is not None:
        ok = lm_new >= lm_old - VERTICAL_LM_TOLERANCE
        return {"accept": ok, "detail": (
            f"sentence LM with {theirs} = {lm_new:.3f} vs with {mine} = {lm_old:.3f} "
            + ("-> reads at least as well, change kept" if ok else "-> reads worse, change dropped"))}
    words = [p for p in pieces if re.fullmatch(r"[A-Z]+", p)]
    position = [n for n, p in enumerate(pieces) if re.fullmatch(r"[A-Z]+", p)].index(index)
    left = words[position - 1] if position > 0 else None
    right = words[position + 1] if position + 1 < len(words) else None
    try:
        near_old = contextual_phrase_score(mine, left, right)
        near_new = contextual_phrase_score(theirs, left, right)
    except Exception:
        return {"accept": True, "detail": "context check unavailable - kept on the line's own evidence"}
    ok = near_new >= near_old
    return {"accept": ok, "detail": (
        f"neighbour-word context {left} < {theirs} > {right} = {near_new:.3f} vs {mine} = {near_old:.3f} "
        + ("-> fits at least as well, change kept" if ok else "-> fits worse, change dropped"))}


def apply_vertical_context(line_results):
    """
    Notes lines written in PARALLEL (same format, near-identical wording - e.g. one
    line per dig) check each other. Where two parallel lines differ by 1-2 letters
    in ONE WORD, a line adopts the other line's word only when that line ITSELF
    ranked it at least as high and its own whole-line reads support it at least as
    much. Numbers, percents, times, '@' and bullets are never touched.
    """
    parsed = []
    for line in line_results:
        prefix, pieces = _split_line_for_vertical(line.get("text", ""))
        parsed.append({"prefix": prefix, "pieces": pieces, "kinds": [_piece_kind(p) for p in pieces]})

    changes = []
    for i in range(len(parsed)):
        for j in range(len(parsed)):
            if i == j:
                continue
            a, b = parsed[i], parsed[j]
            if len(a["pieces"]) < 3 or a["kinds"] != b["kinds"]:
                continue                                   # not the same format
            word_positions = [k for k, kind in enumerate(a["kinds"]) if kind == "word"]
            if len(word_positions) < 2:
                continue
            same = sum(1 for k in word_positions if a["pieces"][k] == b["pieces"][k])
            if same / len(word_positions) < VERTICAL_MIN_SAME_WORDS:
                continue                                   # not near-identical wording
            for k in word_positions:
                mine, theirs = a["pieces"][k], b["pieces"][k]
                if mine == theirs or _letters_apart(mine, theirs) > VERTICAL_MAX_WORD_DIFFERENCE:
                    continue
                if not _line_considered(line_results[i], mine, theirs):
                    continue                               # this line never thought it could be that word
                my_score_mine, my_reads_mine = _line_support(line_results[i], mine)
                my_score_theirs, my_reads_theirs = _line_support(line_results[i], theirs)
                if my_score_theirs < my_score_mine or my_reads_theirs < my_reads_mine:
                    continue                               # this line's own evidence favours its word
                their_score_theirs, _ = _line_support(line_results[j], theirs)
                their_score_mine, _ = _line_support(line_results[j], mine)
                if their_score_mine > their_score_theirs:
                    continue                               # the other line is not sure either
                changes.append((i, j, k, mine, theirs,
                                my_score_theirs, my_score_mine, my_reads_theirs, my_reads_mine))

    done = set()
    for i, j, k, mine, theirs, s_theirs, s_mine, r_theirs, r_mine in changes:
        if (i, k) in done:
            continue
        if any(c[0] == j and c[2] == k and c[3] == theirs for c in changes):
            continue                                       # both lines would swap: no clear answer
        done.add((i, k))
        verdict = vertical_change_fits_own_line(parsed[i]["pieces"], k, mine, theirs)
        header = (f"VERTICAL CONTEXT: line {i + 1}: {mine} -> {theirs} | line {j + 1} has the same format "
                  f"and wording | line {i + 1}'s own evidence: {theirs} score={s_theirs:.3f} reads={r_theirs} "
                  f"vs {mine} score={s_mine:.3f} reads={r_mine}")
        if not verdict["accept"]:
            print(header)
            print(f"   REJECTED after re-checking line {i + 1}'s own sentence: {verdict['detail']}")
            continue
        parsed[i]["pieces"][k] = theirs
        new_text = " ".join(([parsed[i]["prefix"]] if parsed[i]["prefix"] else []) + parsed[i]["pieces"])
        print(header)
        print(f"   Re-checked in line {i + 1}'s own sentence: {verdict['detail']}")
        line_results[i]["text"] = new_text
    return line_results


def mid_line_asterisk_warnings(line_results):
    """
    '*' usually only starts a line. A '*' anywhere else is KEPT as read, but
    flagged in the terminal and on the Notes card so it is checked by eye.
    """
    warnings = []
    for number, line in enumerate(line_results, start=1):
        text = str(line.get("text", "")).strip()
        if any(character == "*" for character in text[1:]):
            message = (f"⚠ Notes line {number}: '*' in the middle of the line "
                       f"(usually only at the start) - check by eye: {text}")
            print("MID-LINE ASTERISK:", message)
            warnings.append(message)
    return warnings


def extract_notes(page_image, label, page1_bullets=None):
    if label is None:
        return None

    label_height = label["y1"] - label["y0"]
    top = max(0, int(label["y0"] - label_height * 0.35))
    notes_crop = page_image.crop((0, top, page_image.width, page_image.height))

    found_label_name = str(label.get("text", "Notes:")).strip() or "Notes:"
    if not found_label_name.endswith(":"):
        found_label_name += ":"

    print()
    print("Known Notes label already found by EasyOCR:")
    print(found_label_name)
    print("Keeping original Notes OCR images; removing the known label from text only.")

    detected = detect_notes_regions(notes_crop)
    handwriting_items = []
    for item in detected:
        if detector_item_is_only_known_notes_header(item["text"], found_label_name):
            print("Ignoring known printed Notes header detector box:", item["text"])
            continue
        handwriting_items.append(item)

    handwriting_items = group_notes_detector_items_by_physical_row(handwriting_items)
    print("Physical Notes rows after conservative grouping:", len(handwriting_items))
    progress_add_steps(len(handwriting_items) - 1)        # one step per line (1 was assumed)

    line_results = []
    for line_number, item in enumerate(handwriting_items, start=1):
        progress_step(f"Notes line {line_number} of {len(handwriting_items)}")
        NOTES_LINE_CONTEXT["line"] += 1                      # S70: a new line, new word blocks
        line_crop = crop_detected_region(notes_crop, item)
        # the same line on page 1's black/white page (step 4: all ink black on white)
        black_line = None
        if PAGE_MAP.get("black_white") is not None and PAGE_MAP["page"] is page_image:
            bx0, by0, bx1, by1 = detected_region_box(notes_crop, item)
            black_line = PAGE_MAP["black_white"].crop((bx0, by0 + top, bx1, by1 + top))
        original_detector_text = str(item["text"]).strip()
        detector_text_for_ocr = strip_known_notes_header(original_detector_text, found_label_name)
        if not detector_text_for_ocr:
            print()
            print("Skipping detector row because it contained only the known Notes label:")
            print(original_detector_text)
            continue

        print()
        print("#" * 70)
        print("NOTES LINE", line_number)
        print("Detector originally read:", original_detector_text)
        if detector_text_for_ocr != original_detector_text:
            print("Detector text after removing known Notes header:", detector_text_for_ocr)
        print("#" * 70)

        with timed(f"Notes line {line_number}", 2, measure=True):          # S405
            result = read_notes_line(
                line_crop,
                detector_text_for_ocr,
                item["confidence"],
                previous_notes_lines=line_results,
                black_white_image=black_line,
            )

        raw_result_text = result.get("text", "")
        if line_number == 1:
            cleaned_result_text = strip_known_notes_header(raw_result_text, found_label_name)
        else:
            # Later rows cannot be the printed header; a handwritten NOTE: is real.
            cleaned_result_text = raw_result_text
        if cleaned_result_text != raw_result_text:
            print()
            print("Removed already-known Notes header from final OCR line:")
            print("Before:", raw_result_text)
            print("After:", cleaned_result_text)

        result["text"] = cleaned_result_text
        result["image"] = line_crop
        try:
            bx0, by0, bx1, by1 = detected_region_box(notes_crop, item)
            result["page_box"] = (bx0, by0 + top, bx1, by1 + top)      # S99: where the line sits on page 1
        except Exception:
            result["page_box"] = None
        result["detector_text"] = detector_text_for_ocr
        result["original_detector_text"] = original_detector_text
        result["detector_confidence"] = item["confidence"]
        line_results.append(result)

    line_results = normalize_note_bullets(line_results, page1_bullets)
    # S99: a bullet filled in from page 1's count (S89) - nobody read it - is looked for
    # again with the line's crop widened left and down (a circle its crop cut off)
    for line in line_results:
        bullet = re.match(r"^\(([A-Z])\)", str(line.get("text", "")))
        if bullet and line.get("bullet_filled") and line.get("page_box"):
            seen = look_for_cut_off_circle(page_image, line["page_box"], bullet.group(1))
            line["bullet_seen"] = seen
            print(f"BULLET ({bullet.group(1)}): looked for again with the line's crop widened - "
                  + ("a circle IS there (it was cut off by the line's crop)" if seen else
                     "no circle found there either - the bullet comes from page 1's count only"))
    line_results = apply_vertical_context(line_results)
    warnings = mid_line_asterisk_warnings(line_results)
    final_text = "\n".join(line["text"] for line in line_results if line["text"])
    display_value = found_label_name + "\n" + final_text if final_text else found_label_name
    return {
        "warnings": warnings,
        "value": final_text,
        "display_value": display_value,
        "label": found_label_name,
        "lines": line_results,
        "image": notes_crop,
    }


# ============================================================
# PIPELINE NAME (Dig Packet page 1, one handwritten line)
# ============================================================
# Read like a coordinate, not like a Notes line: the fill-in line after the
# printed label is found, the handwriting above it is cropped, and the reads are
# taken as written. It is a name / code (e.g. SHC 20-1), not an English sentence,
# so there is NO English pass, no language model and no look-alike swaps.
# Several reads are compared; a value that two or more reads agree on wins.

def guided_pipeline_name_reread(name_result, page_image):
    """S101: when no read of the pipeline name is spelled by a printed line (dig sheet,
    map red notes), its handwriting area is read again a little wider - to the right,
    then up/down, then both - and those reads are added; returns True when there are
    new reads to check against the printed lines again."""
    if not name_result or name_result.get("confirmed") or not name_result.get("read_box") or page_image is None:
        return False
    left, top, right, bottom = name_result["read_box"]
    h = name_result.get("label_height", 40)
    added = []
    for label, box in (("wider right", (left, top, min(page_image.width, right + int(1.5 * h)), bottom)),
                       ("taller", (left, max(0, top - int(0.3 * h)), right, min(page_image.height, bottom + int(0.3 * h)))),
                       ("wider + taller", (left, max(0, top - int(0.3 * h)), min(page_image.width, right + int(1.5 * h)),
                                           min(page_image.height, bottom + int(0.3 * h))))):
        image = trim_to_content(remove_horizontal_lines(page_image.crop(box)))
        text, confidence = paddle_read_text_image(image)
        if text:
            added.append((f"PaddleOCR {label}", str(text), float(confidence or 0)))
    if not added:
        return False
    name_result["reads"] = list(name_result.get("reads") or []) + added
    print("PIPELINE NAME: no read matched a printed line - read again around it: "
          + "; ".join(f"{r}: {t!r} ({c:.2f})" for r, t, c in added))
    return True


def find_label_phrase(results, targets, name):
    """Printed label found by any of `targets` (letters only, e.g. 'wheelcount').
    EasyOCR may split a label into several boxes on one row ('6. Wheel' + 'count/station:');
    up to 4 neighbouring boxes on the same row are joined before checking."""
    boxes = []
    for result in results:
        if len(result) < 2:
            continue
        xs = [point[0] for point in result[0]]
        ys = [point[1] for point in result[0]]
        boxes.append({"text": str(result[1]), "x0": int(min(xs)), "y0": int(min(ys)),
                      "x1": int(max(xs)), "y1": int(max(ys)),
                      "confidence": safe_float(result[2]) if len(result) >= 3 else 0.0})
    for start in boxes:
        merged = dict(start)
        parts = [start]
        for _ in range(5):
            if any(t in clean_label_text(merged["text"]) for t in targets):
                shown = " + ".join(f'"{b["text"]}"' for b in parts)
                print(f"{name} found as {shown}")
                return merged
            height = max(1, merged["y1"] - merged["y0"])
            centre = (merged["y0"] + merged["y1"]) / 2.0
            nxt = [b for b in boxes if b not in parts
                   and abs((b["y0"] + b["y1"]) / 2.0 - centre) <= height * 0.6
                   and 0 <= b["x0"] - merged["x1"] <= height * 2.5]
            if not nxt:
                break
            b = min(nxt, key=lambda b: b["x0"] - merged["x1"])
            parts.append(b)
            merged = {"text": f'{merged["text"]} {b["text"]}',
                      "x0": min(merged["x0"], b["x0"]), "y0": min(merged["y0"], b["y0"]),
                      "x1": max(merged["x1"], b["x1"]), "y1": max(merged["y1"], b["y1"]),
                      "confidence": min(merged["confidence"], b["confidence"])}
    print(f"{name}: NOT FOUND")
    return None


def find_pipeline_name_label(results):
    """'Pipeline name:' printed label. EasyOCR may return it as one box
    ('5. Pipeline name:') or as 'Pipeline' + 'name:' side by side on one row."""
    boxes = []
    for result in results:
        if len(result) < 2:
            continue
        xs = [point[0] for point in result[0]]
        ys = [point[1] for point in result[0]]
        boxes.append({
            "text": str(result[1]),
            "x0": int(min(xs)), "y0": int(min(ys)), "x1": int(max(xs)), "y1": int(max(ys)),
            "confidence": safe_float(result[2]) if len(result) >= 3 else 0.0,
        })
    for box in boxes:
        if "pipelinename" in clean_label_text(box["text"]):
            print(f'Pipeline name found as "{box["text"]}"')
            return box
    for box in boxes:
        if not clean_label_text(box["text"]).endswith("pipeline"):
            continue
        height = max(1, box["y1"] - box["y0"])
        center = (box["y0"] + box["y1"]) / 2.0
        right = [b for b in boxes
                 if b is not box and clean_label_text(b["text"]).startswith("name")
                 and abs((b["y0"] + b["y1"]) / 2.0 - center) <= height * 0.6
                 and 0 <= b["x0"] - box["x1"] <= height * 2.5]
        if right:
            name = min(right, key=lambda b: b["x0"] - box["x1"])
            print(f'Pipeline name found as "{box["text"]}" + "{name["text"]}"')
            return {
                "text": f'{box["text"]} {name["text"]}',
                "x0": min(box["x0"], name["x0"]), "y0": min(box["y0"], name["y0"]),
                "x1": max(box["x1"], name["x1"]), "y1": max(box["y1"], name["y1"]),
                "confidence": min(box["confidence"], name["confidence"]),
            }
    print("Pipeline name: NOT FOUND")
    return None


def pipeline_name_line(band, label_height):
    """(right end x, y) of the fill-in line that starts right after the label, or None.
    Gaps up to ~1/3 label height are bridged (handwriting crossing the line)."""
    gray = np.array(ImageOps.grayscale(band))
    dark = gray < 140
    height, width = dark.shape
    bridge = max(3, int(label_height * 0.35))
    start_limit = max(10, int(label_height * 1.5))
    best, best_length = None, 0
    for y in range(int(height * 0.40), height):
        xs = np.flatnonzero(dark[y])
        if len(xs) == 0 or xs[0] > start_limit:
            continue
        run_start, run_end = xs[0], xs[0]
        for x in xs[1:]:
            if x - run_end <= bridge:
                run_end = x
            else:
                break
        if run_end - run_start > best_length:
            best_length, best = run_end - run_start, (int(run_end), y)
    if best is not None and best_length >= label_height * 3:
        return best
    return None


def pipeline_name_reads(image):
    """[(reader, text, confidence)] - PaddleOCR and EasyOCR, each at 1x and 2x."""
    reads = []
    variants = [("1x", image),
                ("2x", image.resize((image.width * 2, image.height * 2), Image.LANCZOS))]
    for size, variant in variants:
        padded = Image.new("RGB", (variant.width + 20, variant.height + 20), (255, 255, 255))
        padded.paste(variant.convert("RGB"), (10, 10))
        try:
            text, confidence = paddle_read_text_image(padded)
            reads.append((f"PaddleOCR {size}", str(text).strip(), safe_float(confidence)))
        except Exception as exc:
            print(f"Pipeline name: PaddleOCR {size} failed: {exc}")
        try:
            boxes = easy_reader.readtext(np.array(padded), detail=1, paragraph=False)
            boxes = sorted(boxes, key=lambda b: min(point[0] for point in b[0]))
            text = " ".join(str(b[1]).strip() for b in boxes if str(b[1]).strip())
            confidence = (sum(safe_float(b[2]) for b in boxes) / len(boxes)) if boxes else 0.0
            reads.append((f"EasyOCR {size}", text, confidence))
        except Exception as exc:
            print(f"Pipeline name: EasyOCR {size} failed: {exc}")
    return reads


def pipeline_name_consensus(reads):
    """(value, warning or None). Reads are compared ignoring spaces and letter case
    only; the value shown is the highest-confidence spelling of the winning read."""
    groups = {}
    for reader, text, confidence in reads:
        key = re.sub(r"\s+", "", text).upper()
        if key:
            groups.setdefault(key, []).append((confidence, text, reader))
    if not groups:
        return "", "⚠ no read returned any text - check the snip"
    best_key = max(groups, key=lambda k: (len(groups[k]), max(c for c, _, _ in groups[k])))
    agreeing = groups[best_key]
    value = max(agreeing, key=lambda item: item[0])[1]
    if len(agreeing) >= 2:
        return value, None
    return value, (f"⚠ no two reads agree - using the highest-confidence read "
                   f"({agreeing[0][2]}); check the snip")


PIPELINE_NAME_SNIP_STEPS = {}       # the pipeline name's picture box, for the snip steps tab


def pipeline_name_snip_box(page_image, label, right, line_y, label_height):
    """The pipeline name's picture, cut the same way as the page-1 value pieces, on the
    page-1 colour map (white = paper, black = the searched name 'Pipeline name:', red =
    handwriting). Going right from the label: white, black (the label), then the
    LEFTMOST red = where the handwriting starts; it goes on over red and short white
    gaps and stops at white wider than 1.5 label heights = where it ends. Only this
    line's red counts: marks that reach down to its fill-in line (the line above's
    writing ends higher) and do not start below it (the next line's circles). A mark
    that crosses the fill-in line counts only when it starts above and comes down
    through it (most of it above the line, like the X of 'INDEX'); one coming UP
    through it from below (most of it below) is the next line's. The
    fill-in lines are not counted (piece-check map), but the picture keeps its own
    fill-in line at the bottom like the other pieces. Specks smaller than 5% of a
    label height squared (a left-over bit of a fill-in line's end, dust) are not
    handwriting. Returns a page box or None."""
    PIPELINE_NAME_SNIP_STEPS.clear()
    if PAGE_MAP.get("piece_classes") is None or page_image is not PAGE_MAP["page"]:
        return None
    h = int(label_height)
    x0, x1 = max(0, int(label["x1"]) - h), int(right)
    # the line's own band, the same way as the value lines: from the fill-in line
    # above (+3) to a little under its own fill-in line (0.3 label heights)
    above = find_fill_line_above(page_image, int(label["x1"]), x1, int(label["y0"]),
                                 max(0, int(label["y0"] - h * 2.5)))
    y0 = above + 3 if above is not None else max(0, int(label["y0"] - h * 0.8))
    y1 = min(page_image.height, int(line_y + 0.3 * h))
    if x1 - x0 < 10 or y1 - y0 < 10:
        return None
    red = (page_map_region((x0, y0), x1 - x0, y1 - y0, PAGE_MAP["piece_classes"]) == MAP_HANDWRITING)
    black = page_map_region((x0, y0), x1 - x0, y1 - y0) == MAP_PRINTED
    # marks crossing the fill-in line were split by taking the line out (the line and
    # 2 rows above / below it): join them back across that strip before judging them
    line_row = int(line_y) - y0
    joined = red.astype(np.uint8)
    grown = cv2.dilate(joined, cv2.getStructuringElement(cv2.MORPH_RECT, (9, 11)))
    strip = slice(max(0, line_row - 8), min(joined.shape[0], line_row + 9))
    joined[strip] = grown[strip]                        # joined only around the fill-in line (for grouping only;
                                                        # each mark keeps its own real red pixels)
    count, labels = cv2.connectedComponents(joined, connectivity=8)
    own = np.zeros(red.shape, dtype=bool)
    speck = max(20, int(0.05 * h * h))                  # left-over bits of a fill-in line end, dust
    for index in range(1, count):
        mark = (labels == index) & red
        rows = np.flatnonzero(mark.any(axis=1))
        if len(rows) == 0 or np.count_nonzero(mark) < speck:
            continue
        top, bottom = int(rows[0]), int(rows[-1])
        if bottom < line_row - h or top > line_row:
            continue
        if bottom > line_row + 1:
            # it crosses the fill-in line: it is this line's only when it STARTS above
            # the line and comes down through it (like the X of 'INDEX') - most of it
            # above the line. A mark coming UP from below (the next line's circle
            # poking through) has most of it below -> not on this line.
            above = int(np.count_nonzero(mark[:line_row]))
            below = int(np.count_nonzero(mark[line_row + 1:]))
            if above < below:
                continue
        own |= mark
    red_cols = own.any(axis=0)
    # the black that counts is the searched label itself: only black on the label's
    # own rows and no further right than half a label height past its box - black
    # anywhere else in the area (other lines, a stray dark bit) is not the label
    label_rows = slice(max(0, int(label["y0"]) - y0), max(0, min(black.shape[0], int(label["y1"]) - y0 + 1)))
    label_limit = max(0, min(black.shape[1], int(label["x1"]) + h // 2 - x0))
    black_cols = black[label_rows, :label_limit].any(axis=0)
    label_end = int(np.flatnonzero(black_cols)[-1]) + 1 if black_cols.any() else 0
    reds = np.flatnonzero(red_cols[label_end:]) + label_end
    if not len(reds):
        print("PIPELINE NAME SNIP: no handwriting right of the label on the colour map - old crop kept")
        return None
    start = int(reds[0])                                # leftmost red after the black label
    end, gap, stop = start, 0, "the fill-in line ends"
    max_white = int(1.5 * h)
    for x in range(start, len(red_cols)):
        if red_cols[x]:
            end, gap = x, 0
        else:
            gap += 1
            if gap > max_white:
                stop = f"white wider than {max_white} px"
                break
    rows = np.flatnonzero(own[:, start:end + 1].any(axis=1))
    top_row = int(rows[0]) if len(rows) else 0
    box = (x0 + start - 4, y0 + max(0, top_row - 4), x0 + end + 5, min(page_image.height, int(line_y) + 6))
    note = (f"black label ends x={x0 + label_end}, leftmost red x={x0 + start}, "
            f"handwriting to x={x0 + end} ({stop}) -> snip {box}")
    print(f"PIPELINE NAME SNIP: {note}")
    PIPELINE_NAME_SNIP_STEPS.update({"box": box})
    return box


def extract_pipeline_name(page_image, label):
    if label is None:
        return None
    label_height = max(1, label["y1"] - label["y0"])
    left = int(label["x1"] + 2)
    top = max(0, int(label["y0"] - label_height * 0.90))
    bottom = min(page_image.height, int(label["y1"] + label_height * 0.60))
    band = page_image.crop((left, top, page_image.width, bottom))
    line = pipeline_name_line(band, label_height)
    if line is not None:
        right = min(page_image.width, left + line[0] + 4)
        text_bottom = top + max(1, line[1] - 2)          # handwriting sits above the line
        print(f"Pipeline name: fill-in line ends at x={right}, line at y={top + line[1]}")
    else:
        right = int(min(page_image.width, left + page_image.width * 0.42))
        text_bottom = bottom
        print("Pipeline name: fill-in line not found - reading 42% of the page width to the right")

    # the snip shown in the window: real, unaltered crop of label + line
    snip = page_image.crop((label["x0"], top, right, bottom))

    # OCR copy only (never shown): printed lines removed, cropped to the ink
    handwriting = page_image.crop((left, top, right, text_bottom))
    ocr_image = trim_to_content(remove_horizontal_lines(handwriting))
    if line is not None:
        box = pipeline_name_snip_box(page_image, label, right, top + line[1], label_height)
        if box is not None:
            snip = page_image.crop(box)             # a real, unaltered page crop
    if not dt_cell_has_ink(ocr_image):
        print("Pipeline name: no handwriting on the line")
        return {"value": "", "image": snip, "reads": [], "warning": None}

    reads = pipeline_name_reads(ocr_image)
    value, warning = pipeline_name_consensus(reads)
    print()
    print("PIPELINE NAME READS:")
    for reader, text, confidence in reads:
        print(f"    {reader}: {text!r} ({confidence:.2f})")
    print(f"    -> {value!r}" + (f"  {warning}" if warning else ""))
    steps = dict(PIPELINE_NAME_SNIP_STEPS) if PIPELINE_NAME_SNIP_STEPS else None
    if steps:
        steps["area_box"] = (max(0, int(label["x0"] - label_height * 0.5)), top, right, bottom)
    return {"value": value, "image": snip, "reads": reads, "warning": warning, "snip_steps": steps,
            "read_box": (left, top, right, text_bottom), "label_height": label_height}     # S101


