def dm_render_page(page, zoom):
    pixmap = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
    mode = "RGB" if pixmap.n < 4 else "RGBA"
    image = Image.frombytes(mode, [pixmap.width, pixmap.height], pixmap.samples)
    return image if mode == "RGB" else image.convert("RGB")     # dataC: no extra copy of an RGB picture


def dm_easyocr_items_from_image(image):
    results = dm_easy_reader.readtext(np.array(image), detail=1, paragraph=False)
    items = []
    for result in results:
        if len(result) < 2:
            continue
        bbox = result[0]
        value = str(result[1]).strip()
        confidence = safe_float(result[2]) if len(result) >= 3 else 0.0
        if not value:
            continue
        xs = [safe_float(point[0]) for point in bbox]
        ys = [safe_float(point[1]) for point in bbox]
        if not xs or not ys:
            continue
        items.append({
            "text": value, "confidence": confidence,
            "x0": int(min(xs)), "y0": int(min(ys)),
            "x1": int(max(xs)), "y1": int(max(ys)),
        })
    return items


def dm_group_ocr_items_into_lines(items, split_gap_factor=None):
    """
    Group OCR words into text rows by height. With split_gap_factor, a row is
    also cut wherever two neighbouring words are further apart than
    split_gap_factor x the typical word height - so a map label printed on the
    same height further right does NOT become part of the row.
    """
    if not items:
        return []
    ordered = sorted(items, key=lambda item: ((item["y0"] + item["y1"]) / 2.0, item["x0"]))
    groups = []
    for item in ordered:
        center_y = (item["y0"] + item["y1"]) / 2.0
        height = max(1, item["y1"] - item["y0"])
        best_group = None
        best_distance = None
        for group in groups:
            group_height = max(1, group["y1"] - group["y0"])
            tolerance = max(6, min(height, group_height) * 0.7)
            distance = abs(center_y - group["center_y"])
            if distance <= tolerance and (best_distance is None or distance < best_distance):
                best_group = group
                best_distance = distance
        if best_group is None:
            groups.append({
                "items": [item],
                "x0": item["x0"], "y0": item["y0"],
                "x1": item["x1"], "y1": item["y1"],
                "center_y": center_y,
            })
        else:
            best_group["items"].append(item)
            best_group["x0"] = min(best_group["x0"], item["x0"])
            best_group["y0"] = min(best_group["y0"], item["y0"])
            best_group["x1"] = max(best_group["x1"], item["x1"])
            best_group["y1"] = max(best_group["y1"], item["y1"])
            best_group["center_y"] = (best_group["y0"] + best_group["y1"]) / 2.0

    if split_gap_factor:
        heights = sorted(max(1, item["y1"] - item["y0"]) for item in items)
        max_gap = split_gap_factor * heights[len(heights) // 2]
        split_groups = []
        for group in groups:
            ordered = sorted(group["items"], key=lambda item: item["x0"])
            segment = [ordered[0]]
            for item in ordered[1:]:
                if item["x0"] - max(i["x1"] for i in segment) > max_gap:
                    split_groups.append(segment)
                    segment = [item]
                else:
                    segment.append(item)
            split_groups.append(segment)
        groups = [
            {
                "items": segment,
                "x0": min(i["x0"] for i in segment), "y0": min(i["y0"] for i in segment),
                "x1": max(i["x1"] for i in segment), "y1": max(i["y1"] for i in segment),
            }
            for segment in split_groups
        ]

    lines = []
    for group in groups:
        line_items = sorted(group["items"], key=lambda item: item["x0"])
        value = " ".join(item["text"] for item in line_items).strip()
        if not value:
            continue
        lines.append({
            "text": value,
            "confidence": sum(item["confidence"] for item in line_items) / len(line_items),
            "x0": group["x0"], "y0": group["y0"],
            "x1": group["x1"], "y1": group["y1"],
        })
    lines.sort(key=lambda item: (item["y0"], item["x0"]))
    return lines


def dm_easyocr_read_single_line(image):
    working = image
    if working.height < 80:
        scale = min(4, max(2, int(round(90 / max(working.height, 1)))))
        working = working.resize((working.width * scale, working.height * scale))
    results = dm_easy_reader.readtext(np.array(working), detail=1, paragraph=False)
    if not results:
        return "", 0.0
    ordered = sorted(results, key=lambda result: min(point[0] for point in result[0]))
    value = " ".join(
        str(result[1]).strip() for result in ordered if str(result[1]).strip()
    ).strip()
    confidences = [safe_float(result[2]) for result in ordered if len(result) >= 3]
    confidence = sum(confidences) / len(confidences) if confidences else 0.0
    return value, confidence


def dm_paddle_read_text_image(image):
    if dm_paddle_reader is None or image is None:
        return "", 0.0
    array = np.array(image.convert("RGB"))
    try:
        results = dm_paddle_reader.predict(input=array, batch_size=1)
    except TypeError:
        try:
            results = dm_paddle_reader.predict(array)
        except Exception:
            return "", 0.0
    except Exception:
        return "", 0.0

    values = []
    try:
        iterator = list(results)
    except Exception:
        iterator = [results]
    for result in iterator:
        result_dict = None
        if isinstance(result, dict):
            result_dict = result
        elif hasattr(result, "json"):
            try:
                result_dict = result.json
            except Exception:
                pass
        if result_dict is None:
            try:
                result_dict = dict(result)
            except Exception:
                result_dict = None
        if not result_dict:
            continue
        candidates = []
        if "rec_text" in result_dict:
            candidates.append((result_dict.get("rec_text", ""), result_dict.get("rec_score", 0.0)))
        if "res" in result_dict and isinstance(result_dict["res"], dict):
            res = result_dict["res"]
            candidates.append((res.get("rec_text", ""), res.get("rec_score", 0.0)))
        for value, confidence in candidates:
            value = str(value or "").strip()
            if value:
                values.append((value, safe_float(confidence)))
    if not values:
        return "", 0.0
    values.sort(key=lambda item: item[1], reverse=True)
    return values[0]


def dm_yellow_pixel_mask(image):
    rgb = np.asarray(image if image.mode == "RGB" else image.convert("RGB"))
    if rgb.size == 0:
        return np.zeros((image.height, image.width), dtype=np.uint8)
    # dataC: the cheap range tests on the 8-bit channels first; the two arithmetic tests only on the pixels
    # that pass them (few - most of a page is white or dark). (r + g) / 2 - b >= 25 is r + g - 2b >= 50
    # exactly (whole numbers). Same mask as before.
    r, g, b = rgb[:, :, 0], rgb[:, :, 1], rgb[:, :, 2]
    candidates = (r >= 225) & (g >= 220) & (b >= 125) & (b <= 235)
    ys, xs = np.nonzero(candidates)
    if len(ys):
        rr = r[ys, xs].astype(np.int16)
        gg = g[ys, xs].astype(np.int16)
        bb = b[ys, xs].astype(np.int16)
        keep = (np.abs(rr - gg) <= 35) & (rr + gg - 2 * bb >= 50)
        candidates[ys[~keep], xs[~keep]] = False
    return candidates.astype(np.uint8) * 255


def dm_find_yellow_note_boxes(image):
    mask = dm_yellow_pixel_mask(image)
    kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (9, 5))
    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel, iterations=2)
    count, _labels, stats, _centroids = cv2.connectedComponentsWithStats(mask, connectivity=8)

    page_height = image.height
    page_width = image.width
    minimum_width = max(40, int(page_width * dm_MAP_NOTE_BOX_MIN_WIDTH_FRACTION))
    minimum_height = max(18, int(page_height * dm_MAP_NOTE_BOX_MIN_HEIGHT_FRACTION))

    boxes = []
    for label_index in range(1, count):
        x = int(stats[label_index, cv2.CC_STAT_LEFT])
        y = int(stats[label_index, cv2.CC_STAT_TOP])
        width = int(stats[label_index, cv2.CC_STAT_WIDTH])
        height = int(stats[label_index, cv2.CC_STAT_HEIGHT])
        area = int(stats[label_index, cv2.CC_STAT_AREA])
        if width < minimum_width or height < minimum_height:
            continue
        if width > page_width * 0.9 or height > page_height * 0.45:
            continue
        if area / max(width * height, 1) < 0.42:
            continue
        padding_x = max(5, int(width * 0.025))
        padding_y = max(4, int(height * 0.1))
        x0 = max(0, x - padding_x)
        y0 = max(0, y - padding_y)
        x1 = min(page_width, x + width + padding_x)
        y1 = min(page_height, y + height + padding_y)
        boxes.append({"x0": x0, "y0": y0, "x1": x1, "y1": y1, "image": image.crop((x0, y0, x1, y1))})
    boxes.sort(key=lambda item: (item["y0"], item["x0"]))
    return boxes


def dm_screen_for_map_page(page):
    # dataC: once per page of an open document (a Dig Packet's pages are screened up to 3 times: map-like
    # check, map pages, text pages)
    memo = _page_memo(page)
    screened = memo.get("map_screen")
    if screened is None:
        scan = dm_render_page(page, dm_MAP_PAGE_SCAN_ZOOM)
        screened = memo["map_screen"] = bool(dm_find_yellow_note_boxes(scan))
    return screened


def dm_map_parameter_keyword_hits(value):
    value = str(value or "").upper()
    return sum(1 for pattern in dm_MAP_PARAMETER_KEYWORDS if re.search(pattern, value))


def dm_map_overlay_line_style(page_image, line):
    padding_x = 4
    padding_y = 3
    x0 = max(0, int(line["x0"]) - padding_x)
    y0 = max(0, int(line["y0"]) - padding_y)
    x1 = min(page_image.width, int(line["x1"]) + padding_x)
    y1 = min(page_image.height, int(line["y1"]) + padding_y)
    crop = np.array(page_image.crop((x0, y0, x1, y1)).convert("RGB"))
    if crop.size == 0:
        return {
            "is_overlay": False, "pure_white_fraction": 0.0, "bright_fraction": 0.0,
            "dark_fraction": 0.0, "height": max(1, y1 - y0),
        }
    r = crop[:, :, 0].astype(np.int16)
    g = crop[:, :, 1].astype(np.int16)
    b = crop[:, :, 2].astype(np.int16)
    total_pixels = max(crop.shape[0] * crop.shape[1], 1)
    pure_white = (r >= 245) & (g >= 245) & (b >= 245)
    bright_neutral = (
        (r >= 220) & (g >= 220) & (b >= 220)
        & (np.maximum.reduce([r, g, b]) - np.minimum.reduce([r, g, b]) <= 28)
    )
    dark = (r <= 70) & (g <= 70) & (b <= 70)
    pure_white_fraction = np.count_nonzero(pure_white) / total_pixels
    bright_fraction = np.count_nonzero(bright_neutral) / total_pixels
    dark_fraction = np.count_nonzero(dark) / total_pixels
    return {
        "is_overlay": (
            pure_white_fraction >= dm_MAP_OVERLAY_MIN_PURE_WHITE_FRACTION
            and bright_fraction >= dm_MAP_OVERLAY_MIN_BRIGHT_FRACTION
            and dark_fraction >= dm_MAP_OVERLAY_MIN_DARK_FRACTION
        ),
        "pure_white_fraction": pure_white_fraction,
        "bright_fraction": bright_fraction,
        "dark_fraction": dark_fraction,
        "height": max(1, int(line["y1"] - line["y0"])),
    }


def dm_pure_black_pixel_mask(image):
    """255 = exactly black pixel; everything else 0."""
    rgb = np.array(image.convert("RGB"))
    if rgb.size == 0:
        return np.zeros((image.height, image.width), dtype=np.uint8)
    limit = dm_MAP_PURE_BLACK_MAX_CHANNEL
    pure_black = (rgb[:, :, 0] <= limit) & (rgb[:, :, 1] <= limit) & (rgb[:, :, 2] <= limit)
    return pure_black.astype(np.uint8) * 255


def dm_prepare_pure_black_green_then_white(image):
    """Pure black stays black; every other pixel becomes white."""
    keep_mask = dm_pure_black_pixel_mask(image)
    output = np.full(keep_mask.shape, 255, dtype=np.uint8)
    output[keep_mask > 0] = 0
    return Image.fromarray(output, mode="L").convert("RGB")


def dm_remove_border_artifacts_from_clean_image(image):
    """Remove long thin black lines touching the image border."""
    gray = np.array(image.convert("L"))
    if gray.size == 0:
        return image
    black = (gray == 0).astype(np.uint8)
    component_count, labels, stats, _centroids = cv2.connectedComponentsWithStats(black, connectivity=8)
    height, width = black.shape
    minimum_height = max(20, int(round(height * dm_MAP_BORDER_ARTIFACT_MIN_HEIGHT_FRACTION)))
    margin = dm_MAP_BORDER_ARTIFACT_EDGE_MARGIN_PIXELS
    cleaned = gray.copy()
    for label_index in range(1, component_count):
        x = int(stats[label_index, cv2.CC_STAT_LEFT])
        y = int(stats[label_index, cv2.CC_STAT_TOP])
        component_width = int(stats[label_index, cv2.CC_STAT_WIDTH])
        component_height = int(stats[label_index, cv2.CC_STAT_HEIGHT])
        touches_border = (
            x <= margin
            or x + component_width >= width - 1 - margin
            or y <= margin
            or y + component_height >= height - 1 - margin
        )
        if not touches_border:
            continue
        is_vertical_line = (
            component_height >= minimum_height
            and component_width <= dm_MAP_BORDER_ARTIFACT_MAX_WIDTH_PIXELS
            and component_height / max(component_width, 1) >= dm_MAP_BORDER_ARTIFACT_MIN_ASPECT_RATIO
        )
        is_horizontal_line = (
            component_width >= int(round(width * dm_MAP_BORDER_ARTIFACT_MIN_HEIGHT_FRACTION))
            and component_height <= dm_MAP_BORDER_ARTIFACT_MAX_WIDTH_PIXELS
            and component_width / max(component_height, 1) >= dm_MAP_BORDER_ARTIFACT_MIN_ASPECT_RATIO
        )
        if not (is_vertical_line or is_horizontal_line):
            continue
        cleaned[labels == label_index] = 255
        print("Removed border artifact:", {
            "x": x, "y": y, "width": component_width, "height": component_height,
        })
    return Image.fromarray(cleaned, mode="L").convert("RGB")


def dm_crop_map_overlay_line(page_image, line, horizontal_padding=12, vertical_padding=5):
    return page_image.crop((
        max(0, int(line["x0"]) - horizontal_padding),
        max(0, int(line["y0"]) - vertical_padding),
        min(page_image.width, int(line["x1"]) + horizontal_padding),
        min(page_image.height, int(line["y1"]) + vertical_padding),
    ))


def dm_simple_text_quality(value):
    value = str(value or "").strip()
    if not value:
        return 0.0
    letters = len(re.findall(r"[A-Za-z]", value))
    digits = len(re.findall(r"[0-9]", value))
    spaces = value.count(" ")
    punctuation = len(re.findall(r"[.\-:'\"]", value))
    noise = max(0, len(value) - letters - digits - spaces - punctuation)
    usable = letters + digits + punctuation
    return clamp(usable / max(len(value), 1) - min(0.35, noise * 0.04))


def dm_choose_best_ocr(variants):
    scored = []
    for variant in variants:
        value = str(variant.get("text", "")).strip()
        if not value:
            continue
        confidence = safe_float(variant.get("confidence", 0.0))
        score = confidence * 0.68 + dm_simple_text_quality(value) * 0.32
        scored.append({**variant, "score": score})
    if not scored:
        return {"text": "", "confidence": 0.0, "source": "NONE", "score": 0.0}
    scored.sort(key=lambda item: (item["score"], item["confidence"]), reverse=True)
    return scored[0]


def dm_read_map_line_from_pipeline_detection(pipeline_detection_page, line):
    """Read the already-clean crop with EasyOCR and PaddleOCR; keep the best."""
    crop = dm_crop_map_overlay_line(pipeline_detection_page, line)
    easy_text, easy_conf = dm_easyocr_read_single_line(crop)
    paddle_text, paddle_conf = dm_paddle_read_text_image(crop)
    best = dm_choose_best_ocr([
        {"text": easy_text, "confidence": easy_conf, "source": "EasyOCR pipeline"},
        {"text": paddle_text, "confidence": paddle_conf, "source": "PaddleOCR pipeline"},
    ])
    return {
        **line,
        "text": best["text"],
        "winner": best["source"],
        "score": best["score"],
        "easy_text": easy_text,
        "easy_conf": easy_conf,
        "paddle_text": paddle_text,
        "paddle_conf": paddle_conf,
        "line_image": crop,
        "clean_image": crop,
    }


def dm_merge_short_row_gaps(active_rows, maximum_gap):
    if len(active_rows) == 0:
        return []
    bands = []
    start = int(active_rows[0])
    previous = start
    for row in active_rows[1:]:
        row = int(row)
        if row - previous - 1 > maximum_gap:
            bands.append((start, previous))
            start = row
        previous = row
    bands.append((start, previous))
    return bands


def dm_first_suspicious_tail_index(selected, page_width):
    """Where the OCR rows stop looking like the left-indented pipeline block."""
    if len(selected) < 4:
        return len(selected)
    widths = [max(1, item["x1"] - item["x0"]) for item in selected]
    median_left = float(np.median([item["x0"] for item in selected]))
    baseline_widths = sorted(widths[:max(3, int(round(len(widths) * 0.8)))])
    wide_reference = float(np.percentile(baseline_widths, 90))
    width_limit = max(
        wide_reference * dm_MAP_TAIL_WIDTH_OUTLIER_MULTIPLIER,
        page_width * dm_MAP_TAIL_WIDTH_PAGE_FRACTION,
    )
    typical_height = float(np.median([max(1, item["y1"] - item["y0"]) for item in selected]))
    left_limit = max(30.0, typical_height * 0.8)

    print()
    print("HYBRID TAIL GEOMETRY:")
    print(
        "  median left =", round(median_left, 1),
        "| wide reference =", round(wide_reference, 1),
        "| suspicious width limit =", round(width_limit, 1),
    )
    for index, item in enumerate(selected):
        width = item["x1"] - item["x0"]
        left_difference = abs(item["x0"] - median_left)
        suspicious = width > width_limit or left_difference > left_limit
        print(
            f"  OCR row {index + 1}:", "width=", round(width, 1),
            "leftDiff=", round(left_difference, 1),
            "SUSPICIOUS" if suspicious else "safe",
        )
        if suspicious and index >= max(3, int(len(selected) * 0.55)):
            return index
    return len(selected)


def dm_recover_tail_rows_from_left_roi(page_image, safe_prefix, original_selected):
    """Rebuild trailing rows from exact-black pixels in a narrow left ROI."""
    if not safe_prefix:
        return []
    safe_prefix = sorted(safe_prefix, key=lambda item: (item["y0"], item["x0"]))
    expected_left = float(np.median([item["x0"] for item in safe_prefix]))
    expected_height = float(np.median([max(1, item["y1"] - item["y0"]) for item in safe_prefix]))
    centers = [(item["y0"] + item["y1"]) / 2.0 for item in safe_prefix]
    steps = [
        centers[index + 1] - centers[index]
        for index in range(len(centers) - 1)
        if centers[index + 1] > centers[index]
    ]
    expected_step = float(np.median(steps)) if steps else expected_height * 1.15
    last_safe_center = (safe_prefix[-1]["y0"] + safe_prefix[-1]["y1"]) / 2.0

    scan_x0 = max(0, int(round(expected_left - 20)))
    scan_x1 = min(page_image.width, int(round(expected_left + page_image.width * 0.68)))
    scan_y0 = max(0, int(round(last_safe_center + expected_step * 0.2 - expected_height * 0.8)))
    scan_y1 = min(page_image.height, int(round(scan_y0 + max(expected_step * 8.5, expected_height * 9.0))))

    print()
    print("v8 PURE-BLACK TAIL RECOVERY:")
    print("  ROI =", (scan_x0, scan_y0, scan_x1, scan_y1))
    keep_mask = dm_pure_black_pixel_mask(page_image.crop((scan_x0, scan_y0, scan_x1, scan_y1)))
    row_counts = np.count_nonzero(keep_mask > 0, axis=1)
    active_rows = np.where(row_counts >= dm_MAP_PURE_BLACK_ROW_MIN_PIXELS)[0]
    bands = dm_merge_short_row_gaps(active_rows, dm_MAP_PURE_BLACK_ROW_JOIN_GAP)

    candidates = []
    for local_y0, local_y1 in bands:
        if local_y1 - local_y0 + 1 < 3:
            continue
        center = scan_y0 + (local_y0 + local_y1) / 2.0
        if center - last_safe_center < expected_step * 0.4:
            continue
        candidates.append((center, local_y0, local_y1))
    print("  pure-black candidate row centers:", [round(candidate[0], 1) for candidate in candidates])

    recovered = []
    previous_center = last_safe_center
    for center, local_y0, local_y1 in candidates:
        gap = center - previous_center
        if gap > expected_step * dm_MAP_PURE_BLACK_TAIL_STOP_MULTIPLIER:
            print("  Tail STOP at gap", round(gap, 1))
            break
        ys, xs = np.where(keep_mask[local_y0:local_y1 + 1, :] > 0)
        if len(xs) == 0:
            continue
        row_left = scan_x0 + int(xs.min())
        row_right = scan_x0 + int(xs.max()) + 1
        if abs(row_left - expected_left) > max(40, expected_height):
            continue
        y_padding = max(5, int(round(expected_height * 0.2)))
        row = {
            "text": "",
            "confidence": 0.0,
            "x0": max(0, row_left - 8),
            "y0": max(0, scan_y0 + local_y0 - y_padding),
            "x1": min(page_image.width, row_right + 8),
            "y1": min(page_image.height, scan_y0 + local_y1 + y_padding + 1),
            "hybrid_tail_recovery": True,
        }
        row["style"] = dm_map_overlay_line_style(page_image, row)
        print("  recovered pure-black row:", (row["x0"], row["y0"], row["x1"], row["y1"]))
        recovered.append(row)
        previous_center = center

    if recovered:
        print("  Recovered", len(recovered), "tail row(s).")
        return safe_prefix + recovered
    print("  No pure-black tail rows recovered.")
    return safe_prefix


def dm_hybrid_pipeline_rows(page_image, selected):
    selected = sorted(selected, key=lambda item: (item["y0"], item["x0"]))
    suspicious_index = dm_first_suspicious_tail_index(selected, page_image.width)
    if suspicious_index >= len(selected):
        print("Hybrid tail: no suspicious trailing OCR box; ordinary boxes kept.")
        return selected
    safe_prefix = selected[:suspicious_index]
    print(
        "Hybrid tail: keeping", len(safe_prefix),
        "safe OCR row(s); rebuilding from OCR row", suspicious_index + 1, "downward.",
    )
    return dm_recover_tail_rows_from_left_roi(page_image, safe_prefix, selected)


def dm_normalize_map_text_spacing(value):
    value = re.sub(r"\s+", " ", str(value or "").strip())
    if not value:
        return value
    value = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", value)
    value = re.sub(r"(?<=[A-Za-z])(?=[0-9])", " ", value)
    value = re.sub(r"^([A-Z]{2,6})B(No|NO)$", r"\1:\2", value)
    value = re.sub(r"^Grade\s*[xX]\s*-?\s*(\d+)$", r"Grade X-\1", value, flags=re.IGNORECASE)
    value = re.sub(r"^A\s*\.?\s*O\s*\.?\s*Smith$", "A.O.Smith", value, flags=re.IGNORECASE)
    # Abbreviation glued to the next word: "Sta.Discharge" -> "Sta. Discharge".
    # (Upper-case initials such as "A.O.Smith" are left alone.)
    value = re.sub(r"(?<=[a-z]\.)(?=[A-Z][a-z])", " ", value)
    return re.sub(r"\s+", " ", value).strip()


def dm_reconstruct_yellow_surface(page_image):
    raw = dm_yellow_pixel_mask(page_image)
    radius = max(2, int(dm_V11_YELLOW_RECONSTRUCT_RADIUS))
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1))
    reconstructed = cv2.morphologyEx(raw, cv2.MORPH_CLOSE, kernel, iterations=2)
    reconstructed = cv2.dilate(
        reconstructed,
        cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5)),
        iterations=1,
    )
    return raw, reconstructed


def dm_save_debug_step_image(image, filename):
    if not SAVE_DEBUG_IMAGES:
        return None
    path = os.path.join(DOWNLOAD_FOLDER, filename)
    image.save(path)
    print("Saved yellow debug step:", path)
    return path


def dm_build_yellow_white_geometry_page(page_image):
    """Yellow stays yellow; every non-yellow pixel becomes white."""
    rgb = np.array(page_image.convert("RGB"))
    yellow = dm_yellow_pixel_mask(page_image) > 0
    output = np.full(rgb.shape, 255, dtype=np.uint8)
    output[yellow] = dm_V12_NOTE_SHEET_COLOR
    return Image.fromarray(output, mode="RGB"), yellow.astype(np.uint8)


def dm_build_v20_step2_yellow_black(step1_page):
    """Every white pixel from Step 1 becomes black; yellow stays yellow."""
    rgb = np.array(step1_page.convert("RGB"))
    white = np.all(rgb == 255, axis=2)
    output = rgb.copy()
    output[white] = (0, 0, 0)
    return Image.fromarray(output, mode="RGB")


def dm_v20_enclosed_black_text_mask(step2_page):
    """Black components NOT touching the page edge = text inside callouts."""
    rgb = np.array(step2_page.convert("RGB"))
    black = np.all(rgb == 0, axis=2).astype(np.uint8)
    component_count, labels, stats, _ = cv2.connectedComponentsWithStats(black, connectivity=8)
    edge_labels = set()
    if labels.size:
        edge_labels.update(np.unique(labels[0, :]).tolist())
        edge_labels.update(np.unique(labels[-1, :]).tolist())
        edge_labels.update(np.unique(labels[:, 0]).tolist())
        edge_labels.update(np.unique(labels[:, -1]).tolist())
    # which marks to keep - decided for all marks at once (not touching the page edge,
    # big enough), then the result picture filled in ONE pass over the page instead
    # of one full-page pass per mark (same result, much faster with ~1000 marks)
    keep = np.zeros(component_count, dtype=bool)
    if component_count > 1:
        keep[1:] = stats[1:, cv2.CC_STAT_AREA] >= dm_V20_TEXT_MASK_MIN_COMPONENT_AREA
        for label_index in edge_labels:
            if 0 <= int(label_index) < component_count:
                keep[int(label_index)] = False
        keep[0] = False
    kept_components = int(keep.sum())
    enclosed = (keep[labels].astype(np.uint8) * 255) if labels.size else np.zeros_like(black, dtype=np.uint8)
    print()
    print(
        "v20 ENCLOSED-BLACK SCAN:", kept_components,
        "non-edge black component(s) retained as possible text",
    )
    return enclosed


def dm_v20_text_blocks_from_enclosed_mask(enclosed_mask):
    """Group enclosed text islands into independent note blocks by proximity."""
    if not np.any(enclosed_mask > 0):
        return []
    line_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (dm_V20_TEXT_DILATE_X, dm_V20_TEXT_DILATE_Y))
    line_mask = cv2.dilate(enclosed_mask, line_kernel, iterations=1)
    block_kernel = cv2.getStructuringElement(cv2.MORPH_RECT, (dm_V20_BLOCK_DILATE_X, dm_V20_BLOCK_DILATE_Y))
    block_mask = cv2.dilate(line_mask, block_kernel, iterations=1)
    component_count, labels, stats, _ = cv2.connectedComponentsWithStats(
        (block_mask > 0).astype(np.uint8), connectivity=8,
    )

    blocks = []
    for label_index in range(1, component_count):
        x = int(stats[label_index, cv2.CC_STAT_LEFT])
        y = int(stats[label_index, cv2.CC_STAT_TOP])
        w = int(stats[label_index, cv2.CC_STAT_WIDTH])
        h = int(stats[label_index, cv2.CC_STAT_HEIGHT])
        if w < dm_V20_BLOCK_MIN_WIDTH or h < dm_V20_BLOCK_MIN_HEIGHT:
            continue
        region = enclosed_mask[y:y + h, x:x + w]
        original_text_pixels = int(np.count_nonzero(region))
        if original_text_pixels < dm_V20_BLOCK_MIN_TEXT_PIXELS:
            continue
        ys, xs = np.where(region > 0)
        if xs.size == 0:
            continue
        blocks.append({
            "x0": x + int(xs.min()),
            "y0": y + int(ys.min()),
            "x1": x + int(xs.max()) + 1,
            "y1": y + int(ys.max()) + 1,
            "text_pixels": original_text_pixels,
        })
    blocks.sort(key=lambda item: (item["y0"], item["x0"]))
    print("v20 TEXT-ISLAND GROUPING:", len(blocks), "independent enclosed text block(s)")
    for index, block in enumerate(blocks, start=1):
        print(
            f"  Text block {index}:", (block["x0"], block["y0"], block["x1"], block["y1"]),
            "| enclosed black pixels=", block["text_pixels"],
        )
    return blocks


def dm_normalize_wt_display_text(value):
    """
    A wall-thickness line: 360WT / .360 W:T / 0.360" W.T -> .360" W.T.
    Wall thickness is always under one inch, so the value is written as .NNN
    """
    if value is None:
        return value
    match = re.fullmatch(
        r'(?i)\s*0?\s*[.,]?\s*(\d{2,3})\s*["”\'`]{0,2}\s*W\s*[.:,]?\s*T\s*[.:,]?\s*',
        str(value),
    )
    if not match:
        return value
    return "." + match.group(1) + '" W.T.'


def dm_normalize_od_display_text(value):
    """30 OD / 30 O.D / 30"O.D.. -> exactly one ' O.D.' ending (and W.T. lines)."""
    if value is None:
        return value
    value = dm_normalize_wt_display_text(value)
    return re.sub(
        r'(?i)\b(\d+(?:\.\d+)?)\s*(["”]?)\s*O\s*\.?\s*D(?:\s*\.)*(?=\s|$)',
        lambda match: match.group(1) + match.group(2) + " O.D.",
        str(value),
    )


def dm_normalize_yellow_lat_long_lines(lines):
    """Lat./Long. line pairs in yellow boxes -> Latitude / Longitude."""
    if not lines:
        return lines
    output = [str(line) for line in lines]

    def parse_coordinate_line(value):
        stripped = str(value).strip()
        lat_match = re.match(r"(?i)^Lat(?:itude)?(?:[\s\._,:]+)(.+?)\s*$", stripped)
        if lat_match and lat_match.group(1).strip():
            return "lat", lat_match.group(1).strip()
        long_match = re.match(r"(?i)^Long(?:itude)?(?:[\s\._,:]+)(.+?)\s*$", stripped)
        if long_match and long_match.group(1).strip():
            return "long", long_match.group(1).strip()
        return None, None

    parsed = [parse_coordinate_line(line) for line in output]
    for index in range(len(output) - 1):
        first_kind, first_value = parsed[index]
        second_kind, second_value = parsed[index + 1]
        if first_kind == "lat" and second_kind == "long":
            output[index] = "Latitude " + first_value
            output[index + 1] = "Longitude " + second_value
        elif first_kind == "long" and second_kind == "lat":
            output[index] = "Longitude " + first_value
            output[index + 1] = "Latitude " + second_value
    return output


def dm_horizontal_page_words(page):
    """The PDF's own words on a page, like page.get_text('words') - (x0, y0, x1, y1,
    word, block, line, word_no, colour) in PDF points, colour = the text colour as
    0xRRGGBB - but ONLY from straight, left-to-right
    lines. Map labels written at an angle ('Missouri Pacific Railroad', 'Index 129')
    are left out, so their letters cannot mix into a note or a pipeline block. Words
    are split at the real space characters. Empty for a scanned page (no text)."""
    words = []
    try:
        data = page.get_text("rawdict")
    except Exception:
        return words
    for b_no, block in enumerate(data.get("blocks", [])):
        for l_no, line in enumerate(block.get("lines", [])):
            dx, dy = line.get("dir", (1, 0))
            if dx < 0.99 or abs(dy) > 0.02:
                continue                                    # not straight left-to-right text
            word, box, w_no, colour = "", None, 0, 0
            for span in line.get("spans", []):
                span_colour = int(span.get("color", 0) or 0)
                for ch in span.get("chars", []):
                    c, (cx0, cy0, cx1, cy1) = ch.get("c", ""), ch["bbox"]
                    if not c or c.isspace():
                        if word:
                            words.append((*box, word, b_no, l_no, w_no, colour)); w_no += 1
                        word, box = "", None
                        continue
                    colour = span_colour
                    word += c
                    box = [cx0, cy0, cx1, cy1] if box is None else [min(box[0], cx0), min(box[1], cy0),
                                                                    max(box[2], cx1), max(box[3], cy1)]
            if word:
                words.append((*box, word, b_no, l_no, w_no, colour))
    return words


def dm_text_layer_lines(page_words, box, zoom):
    """The PDF's own text (no OCR) inside a page-image box: the words whose centre is
    in the box (page_words = page.get_text('words'), box in render pixels, zoom =
    pixels per PDF point), joined into their printed lines, top to bottom. Returns
    [(text, (x0, y0, x1, y1) in render pixels)]; [] when the page has no text there."""
    if not page_words:
        return []
    bx0, by0, bx1, by1 = (v / zoom for v in box)
    rows = {}
    for w in page_words:
        cx, cy = (w[0] + w[2]) / 2.0, (w[1] + w[3]) / 2.0
        if bx0 <= cx <= bx1 and by0 <= cy <= by1 and str(w[4]).strip():
            rows.setdefault((w[5], w[6]), []).append(w)
    lines = []
    for words in rows.values():
        words.sort(key=lambda w: w[0])
        x0, y0 = min(w[0] for w in words), min(w[1] for w in words)
        x1, y1 = max(w[2] for w in words), max(w[3] for w in words)
        lines.append((" ".join(str(w[4]) for w in words), (x0 * zoom, y0 * zoom, x1 * zoom, y1 * zoom)))
    lines.sort(key=lambda item: (item[1][1], item[1][0]))
    return lines


def dm_v20_ocr_text_block(enclosed_mask, block, page_words=None, zoom=None):
    """OCR one note block on a clean white-background / black-text crop."""
    height, width = enclosed_mask.shape
    x0 = max(0, block["x0"] - dm_V20_BLOCK_PADDING)
    y0 = max(0, block["y0"] - dm_V20_BLOCK_PADDING)
    x1 = min(width, block["x1"] + dm_V20_BLOCK_PADDING)
    y1 = min(height, block["y1"] + dm_V20_BLOCK_PADDING)
    mask_crop = enclosed_mask[y0:y1, x0:x1]
    clean = np.full((mask_crop.shape[0], mask_crop.shape[1], 3), 255, dtype=np.uint8)
    clean[mask_crop > 0] = (0, 0, 0)
    crop = Image.fromarray(clean, mode="RGB")

    # the PDF's own text when the map has a text layer here (exact, no OCR); OCR otherwise
    printed = dm_text_layer_lines(page_words, (x0, y0, x1, y1), zoom) if page_words and zoom else []
    if printed and len(re.findall(r"[A-Za-z0-9]", " ".join(t for t, _b in printed))) >= dm_NOTE_MIN_ALNUM_CHARACTERS:
        lines = [{"text": t, "confidence": 1.0, "x0": b[0], "y0": b[1], "x1": b[2], "y1": b[3],
                  "source": "PDF text layer"} for t, b in printed]
    else:
        lines = dm_group_ocr_items_into_lines(dm_easyocr_items_from_image(crop))
    raw_text_lines = [line["text"] for line in lines if str(line.get("text", "")).strip()]
    normalized_text_lines = dm_normalize_yellow_lat_long_lines(raw_text_lines)
    value = "\n".join(normalized_text_lines).strip()

    normalized_index = 0
    for line in lines:
        if not str(line.get("text", "")).strip():
            continue
        if normalized_index < len(normalized_text_lines):
            line["text"] = normalized_text_lines[normalized_index]
        normalized_index += 1
    return crop, value, lines, (x0, y0, x1, y1)


# A real yellow callout always contains readable text. Aerial imagery or
# app screenshots can contain pale-yellow patches that pass the colour
# screen; their "enclosed text" is random blobs that OCR cannot read.
dm_NOTE_MIN_ALNUM_CHARACTERS = 6
dm_NOTE_MIN_AVERAGE_CONFIDENCE = 0.35


def dm_note_text_is_readable(value, lines):
    """True only when an OCR'd note block looks like real text."""
    value = str(value or "").strip()
    alnum = len(re.findall(r"[A-Za-z0-9]", value))
    if alnum < dm_NOTE_MIN_ALNUM_CHARACTERS:
        return False, f"only {alnum} letters/digits"

    has_word = any(
        len(word) >= 3 and zipf_frequency(word.lower(), "en") >= 2.0
        for word in re.findall(r"[A-Za-z]+", value)
    )
    has_number = re.search(r"\d{2,}", value) is not None
    if not (has_word or has_number):
        return False, "no real English word or number"

    confidences = [safe_float(line.get("confidence", 0.0)) for line in lines or []]
    average = sum(confidences) / len(confidences) if confidences else 0.0
    if average < dm_NOTE_MIN_AVERAGE_CONFIDENCE:
        return False, f"average OCR confidence {average:.2f}"
    return True, "readable"


def dm_build_full_page_yellow_isolation(page_image, page_words=None, zoom=None):
    """PASS A: two visible steps, then enclosed-text scan and OCR."""
    step1_page, yellow_mask = dm_build_yellow_white_geometry_page(page_image)
    dm_save_debug_step_image(step1_page, dm_V20_YELLOW_STEP1_FILE)
    step2_page = dm_build_v20_step2_yellow_black(step1_page)
    dm_save_debug_step_image(step2_page, dm_V20_YELLOW_STEP2_FILE)

    enclosed_mask = dm_v20_enclosed_black_text_mask(step2_page)
    text_blocks = dm_v20_text_blocks_from_enclosed_mask(enclosed_mask)

    boxes = []
    for block_index, block in enumerate(text_blocks, start=1):
        crop, value, lines, crop_bounds = dm_v20_ocr_text_block(enclosed_mask, block, page_words, zoom)
        x0, y0, x1, y1 = crop_bounds
        readable, reason = dm_note_text_is_readable(value, lines)
        if not readable:
            print(
                f"  Rejected yellow block {block_index} at {crop_bounds}: "
                f"not a text callout ({reason}). OCR read: {value!r}"
            )
            continue
        boxes.append({
            "x0": x0, "y0": y0, "x1": x1, "y1": y1,
            "image": crop,
            "value": value,
            "lines": lines,
            "detected_index": block_index,
            "yellow_fraction": 1.0,
            "source": ("PDF text layer" if lines and all(l.get("source") == "PDF text layer" for l in lines)
                       else "OCR"),
        })

    print()
    print("v20 TWO-STEP YELLOW PASS:", len(boxes), "readable note text block(s) kept")
    from_text = sum(1 for box in boxes if box["source"] == "PDF text layer")
    print(f"YELLOW NOTES: {from_text} read from the PDF text layer (exact), {len(boxes) - from_text} by OCR")
    for index, box in enumerate(boxes, start=1):
        print()
        print(f"  Note text block {index}:", (box["x0"], box["y0"], box["x1"], box["y1"]), f"({box['source']})")
        print(box["value"])

    reconstructed_yellow = (yellow_mask > 0).astype(np.uint8) * 255
    return step2_page, boxes, reconstructed_yellow


def dm_build_full_page_pipeline_isolation(page_image, note_boxes=None, reconstructed_yellow=None):
    """PASS B: pure-black page with the complete yellow callout surface erased."""
    cleaned = dm_prepare_pure_black_green_then_white(page_image)
    cleaned = dm_remove_border_artifacts_from_clean_image(cleaned)
    if reconstructed_yellow is None:
        _raw_yellow, reconstructed_yellow = dm_reconstruct_yellow_surface(page_image)
    radius = max(1, int(dm_V11_PIPELINE_YELLOW_BLANK_DILATE))
    expanded = cv2.dilate(
        (reconstructed_yellow > 0).astype(np.uint8),
        cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (radius * 2 + 1, radius * 2 + 1)),
        iterations=1,
    )
    array = np.array(cleaned.convert("RGB"))
    array[expanded > 0] = (255, 255, 255)
    print()
    print("v11 FULL-PAGE PIPELINE PASS:", "pure-black page built; complete yellow-callout surface removed")
    return Image.fromarray(array, mode="RGB")


def dm_clean_line_style(line):
    return {
        "is_overlay": True,
        "pure_white_fraction": 1.0,
        "bright_fraction": 1.0,
        "dark_fraction": 0.15,
        "height": max(1, int(line["y1"] - line["y0"])),
    }


def dm_grow_clean_block_from_anchor(lines, anchor_index, page_width):
    anchor = lines[anchor_index]
    heights = [max(1, line["y1"] - line["y0"]) for line in lines]
    typical_height = float(np.median(heights)) if heights else 20.0
    maximum_gap = max(dm_V10_PIPELINE_MIN_GAP_PIXELS, typical_height * dm_V10_PIPELINE_GAP_MULTIPLIER)
    left_drift = max(dm_V10_PIPELINE_MIN_LEFT_DRIFT_PIXELS, int(page_width * dm_V10_PIPELINE_LEFT_DRIFT_FRACTION))

    aligned = [line for line in lines if abs(line["x0"] - anchor["x0"]) <= left_drift]
    aligned.sort(key=lambda item: (item["y0"], item["x0"]))
    anchor_in_aligned = min(
        range(len(aligned)),
        key=lambda index: abs(aligned[index]["y0"] - anchor["y0"]) + abs(aligned[index]["x0"] - anchor["x0"]),
    )

    selected = [aligned[anchor_in_aligned]]
    current = aligned[anchor_in_aligned]
    for index in range(anchor_in_aligned - 1, -1, -1):
        candidate = aligned[index]
        if current["y0"] - candidate["y1"] > maximum_gap:
            break
        selected.append(candidate)
        current = candidate
    current = aligned[anchor_in_aligned]
    for index in range(anchor_in_aligned + 1, len(aligned)):
        candidate = aligned[index]
        if candidate["y0"] - current["y1"] > maximum_gap:
            break
        selected.append(candidate)
        current = candidate
    selected.sort(key=lambda item: (item["y0"], item["x0"]))
    return selected


def dm_bbox_from_lines(lines):
    return (
        min(line["x0"] for line in lines),
        min(line["y0"] for line in lines),
        max(line["x1"] for line in lines),
        max(line["y1"] for line in lines),
    )


def dm_bbox_iou(first, second):
    x0 = max(first[0], second[0])
    y0 = max(first[1], second[1])
    x1 = min(first[2], second[2])
    y1 = min(first[3], second[3])
    intersection = max(0, x1 - x0) * max(0, y1 - y0)
    if intersection <= 0:
        return 0.0
    first_area = max(1, (first[2] - first[0]) * (first[3] - first[1]))
    second_area = max(1, (second[2] - second[0]) * (second[3] - second[1]))
    return intersection / max(first_area + second_area - intersection, 1)


dm_PIPELINE_TALL_ITEM_FACTOR = 1.8     # word taller than 1.8x the typical word = map label
dm_PIPELINE_ROW_SPLIT_GAP_FACTOR = 2.5  # gap wider than 2.5x word height = different text


def dm_filter_pipeline_words(items):
    """
    Remove OCR words that cannot be pipeline-block text before rows are built:
      - taller than 1.8x the typical word (big or multi-row map labels)
      - vertical text (narrower than tall)
    A tall word would otherwise stretch one row over several real rows and
    glue them together ('Grade X-52 Electric Flash Weld A. 0. Smith ...').
    """
    if not items:
        return items
    heights = sorted(max(1, item["y1"] - item["y0"]) for item in items)
    typical = heights[len(heights) // 2]
    kept, dropped = [], []
    for item in items:
        width = max(1, item["x1"] - item["x0"])
        height = max(1, item["y1"] - item["y0"])
        vertical = width < height * 0.8 and len(re.sub(r"\W", "", item["text"])) > 2
        if height > typical * dm_PIPELINE_TALL_ITEM_FACTOR or vertical:
            dropped.append(item)
        else:
            kept.append(item)
    if dropped:
        print(f"PIPELINE DISCOVERY: ignored {len(dropped)} tall/vertical map word(s) "
              f"(typical word height {typical}px):",
              ", ".join(repr(i["text"]) for i in dropped[:8]) + (" ..." if len(dropped) > 8 else ""))
    return kept


def dm_discover_all_pipeline_candidates(detection_page):
    """OCR the isolated page once and find EVERY left-aligned parameter block."""
    lines = dm_group_ocr_items_into_lines(
        dm_filter_pipeline_words(dm_easyocr_items_from_image(detection_page)),
        split_gap_factor=dm_PIPELINE_ROW_SPLIT_GAP_FACTOR,
    )
    prepared = [
        {**line, "style": dm_clean_line_style(line)}
        for line in lines
        if str(line.get("text", "")).strip()
    ]
    prepared.sort(key=lambda item: (item["y0"], item["x0"]))

    anchor_indices = [
        index for index, line in enumerate(prepared)
        if dm_map_parameter_keyword_hits(line["text"]) > 0
    ]
    raw_candidates = []
    for anchor_index in anchor_indices:
        selected = dm_grow_clean_block_from_anchor(prepared, anchor_index, detection_page.width)
        if len(selected) < dm_V10_PIPELINE_MIN_LINES:
            continue
        combined = "\n".join(item["text"] for item in selected)
        if dm_map_parameter_keyword_hits(combined) < dm_MAP_PARAMETER_BLOCK_MIN_HITS:
            continue
        raw_candidates.append({"lines": selected, "bbox": dm_bbox_from_lines(selected)})

    raw_candidates.sort(key=lambda item: (-len(item["lines"]), item["bbox"][1], item["bbox"][0]))
    unique = []
    for candidate in raw_candidates:
        if any(
            dm_bbox_iou(candidate["bbox"], existing["bbox"]) >= dm_V10_PIPELINE_DUPLICATE_IOU
            for existing in unique
        ):
            continue
        unique.append(candidate)
    unique.sort(key=lambda item: (item["bbox"][1], item["bbox"][0]))

    print()
    print("v10 PIPELINE DISCOVERY:", len(unique), "separate candidate block(s)")
    for index, candidate in enumerate(unique, start=1):
        print("  candidate", index, "bbox=", candidate["bbox"], "lines=", len(candidate["lines"]))
    return unique


# ------------------------------------------------------------
# HEAD RECOVERY: rows ABOVE the discovered block
# ------------------------------------------------------------
# Some label lines (e.g. 36" O.D. / .360" W.T. / Grade / manufacturer)
# render as NEAR-black instead of exact black, so they vanish from the
# pure-black page. Map labels are dark text wrapped in a WHITE halo;
# imagery shadows are not. That halo test finds them again.

dm_HEAD_DARK_MAX_CHANNEL = 90
dm_HEAD_WHITE_MIN_CHANNEL = 225
dm_HEAD_HALO_RADIUS = 4
dm_HEAD_MAX_ROWS = 8
dm_HEAD_STOP_GAP_MULTIPLIER = 2.3
dm_HEAD_MIN_CONFIDENCE = 0.40
dm_HEAD_MIN_TEXT_QUALITY = 0.50


def dm_halo_text_mask(image):
    """255 where a pixel is dark AND close to a white outline pixel."""
    rgb = np.array(image.convert("RGB")).astype(np.int16)
    if rgb.size == 0:
        return np.zeros((image.height, image.width), dtype=np.uint8)
    dark = rgb.max(axis=2) <= dm_HEAD_DARK_MAX_CHANNEL
    white = (rgb.min(axis=2) >= dm_HEAD_WHITE_MIN_CHANNEL).astype(np.uint8)
    size = dm_HEAD_HALO_RADIUS * 2 + 1
    near_white = cv2.dilate(
        white, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (size, size)), iterations=1,
    ) > 0
    return (dark & near_white).astype(np.uint8) * 255


def dm_recover_head_rows_mask(page_image, block_lines):
    if not block_lines:
        return []
    block_lines = sorted(block_lines, key=lambda item: (item["y0"], item["x0"]))
    expected_left = float(np.median([line["x0"] for line in block_lines]))
    expected_height = float(np.median([max(1, line["y1"] - line["y0"]) for line in block_lines]))
    centers = [(line["y0"] + line["y1"]) / 2.0 for line in block_lines]
    steps = [b - a for a, b in zip(centers, centers[1:]) if b > a]
    expected_step = float(np.median(steps)) if steps else expected_height * 1.15
    first_center = centers[0]
    block_right = max(line["x1"] for line in block_lines)

    scan_x0 = max(0, int(expected_left - 20))
    scan_x1 = min(page_image.width, int(block_right + (block_right - expected_left) * 0.5))
    scan_y1 = max(0, int(block_lines[0]["y0"]) - 1)
    scan_y0 = max(0, int(scan_y1 - expected_step * (dm_HEAD_MAX_ROWS + 1)))
    if scan_y1 - scan_y0 < expected_height or scan_x1 <= scan_x0:
        return []

    print()
    print("HEAD RECOVERY (rows above the block, white-halo text):")
    print("  ROI =", (scan_x0, scan_y0, scan_x1, scan_y1))

    mask = dm_halo_text_mask(page_image.crop((scan_x0, scan_y0, scan_x1, scan_y1)))
    row_counts = np.count_nonzero(mask > 0, axis=1)
    active_rows = np.where(row_counts >= dm_MAP_PURE_BLACK_ROW_MIN_PIXELS)[0]
    bands = dm_merge_short_row_gaps(active_rows, dm_MAP_PURE_BLACK_ROW_JOIN_GAP)
    bands = [
        (local_y0, local_y1) for local_y0, local_y1 in bands
        if local_y1 - local_y0 + 1 >= max(3, int(expected_height * 0.25))
    ]
    bands.sort(key=lambda band: band[0], reverse=True)   # nearest to the block first

    recovered = []
    previous_center = first_center
    for local_y0, local_y1 in bands:
        if len(recovered) >= dm_HEAD_MAX_ROWS:
            break
        center = scan_y0 + (local_y0 + local_y1) / 2.0
        gap = previous_center - center
        if gap < expected_step * 0.4:
            continue
        if gap > expected_step * dm_HEAD_STOP_GAP_MULTIPLIER:
            print("  Head STOP at gap", round(gap, 1))
            break

        band_mask = mask[local_y0:local_y1 + 1, :]
        ys, xs = np.where(band_mask > 0)
        if len(xs) == 0:
            continue
        row_left = scan_x0 + int(xs.min())
        if abs(row_left - expected_left) > max(40, expected_height):
            print("  Head row skipped (not left-aligned):", round(center, 1), "left=", row_left)
            continue

        row_right = scan_x0 + int(xs.max()) + 1
        pad = max(5, int(round(expected_height * 0.2)))
        crop_x0 = max(0, row_left - 8)
        crop_x1 = min(page_image.width, row_right + 8)
        crop_y0 = max(0, scan_y0 + local_y0 - pad)
        crop_y1 = min(page_image.height, scan_y0 + local_y1 + pad + 1)

        # Clean crop: white background, black halo-text pixels only.
        row_mask = dm_halo_text_mask(page_image.crop((crop_x0, crop_y0, crop_x1, crop_y1)))
        clean = np.full(row_mask.shape, 255, dtype=np.uint8)
        clean[row_mask > 0] = 0
        clean_image = Image.fromarray(clean, mode="L").convert("RGB")

        easy_text, easy_conf = dm_easyocr_read_single_line(clean_image)
        paddle_text, paddle_conf = dm_paddle_read_text_image(clean_image)
        best = dm_choose_best_ocr([
            {"text": easy_text, "confidence": easy_conf, "source": "EasyOCR head"},
            {"text": paddle_text, "confidence": paddle_conf, "source": "PaddleOCR head"},
        ])
        text = str(best["text"]).strip()
        alnum = len(re.findall(r"[A-Za-z0-9]", text))
        if (
            alnum < 2
            or safe_float(best.get("confidence", 0.0)) < dm_HEAD_MIN_CONFIDENCE
            or dm_simple_text_quality(text) < dm_HEAD_MIN_TEXT_QUALITY
        ):
            print("  Head STOP: row is not readable text:", repr(text))
            break

        text = dm_normalize_od_display_text(dm_normalize_map_text_spacing(text))
        print("  recovered head row:", (crop_x0, crop_y0, crop_x1, crop_y1), "->", text,
              f"({best['source']}, {safe_float(best.get('confidence', 0.0)):.2f})")
        recovered.append({
            "x0": crop_x0, "y0": crop_y0, "x1": crop_x1, "y1": crop_y1,
            "text": text,
            "winner": best["source"],
            "score": best.get("score", 0.0),
            "easy_text": easy_text,
            "easy_conf": easy_conf,
            "paddle_text": paddle_text,
            "paddle_conf": paddle_conf,
            "line_image": clean_image,
            "clean_image": clean_image,
            "head_recovery": True,
        })
        previous_center = center

    recovered.reverse()   # top to bottom
    print("  Recovered", len(recovered), "head row(s).")
    return recovered


dm_HEAD_OCR_MIN_CONFIDENCE = 0.30
dm_HEAD_DEBUG_FILE = "DigMap_Head_ROI.png"


def dm_head_geometry(block_lines):
    block_lines = sorted(block_lines, key=lambda item: (item["y0"], item["x0"]))
    expected_left = float(np.median([line["x0"] for line in block_lines]))
    expected_height = float(np.median([max(1, line["y1"] - line["y0"]) for line in block_lines]))
    centers = [(line["y0"] + line["y1"]) / 2.0 for line in block_lines]
    steps = [b - a for a, b in zip(centers, centers[1:]) if b > a]
    expected_step = float(np.median(steps)) if steps else expected_height * 1.15
    return block_lines, expected_left, expected_height, expected_step, centers[0]


def dm_split_tall_item_into_rows(roi, item, expected_step):
    """
    EasyOCR sometimes returns ONE box covering two or more stacked rows
    (e.g. '.360" W.T.' + 'Grade XC-60'). Cut it into rows at the emptiest
    pixel rows near the evenly spaced expected boundaries.
    """
    height = item["y1"] - item["y0"]
    count = max(2, int(round(height / max(expected_step, 1))))
    crop = roi.crop((item["x0"], item["y0"], item["x1"], item["y1"]))
    mask = dm_halo_text_mask(crop)
    if np.count_nonzero(mask) < 20:
        rgb = np.array(crop.convert("RGB")).astype(np.int16)
        mask = (rgb.max(axis=2) <= 90).astype(np.uint8) * 255
    row_counts = np.count_nonzero(mask > 0, axis=1).astype(np.float32)

    cuts = [0]
    search = max(3, int(expected_step * 0.3))
    for index in range(1, count):
        expected = int(round(index * height / count))
        low = max(cuts[-1] + 3, expected - search)
        high = min(height - 3, expected + search)
        if high <= low:
            cut = expected
        else:
            local = row_counts[low:high + 1]
            minimum = float(local.min())
            positions = [low + int(p) for p in np.where(local <= minimum + 0.5)[0]]
            cut = min(positions, key=lambda value: abs(value - expected))
        cuts.append(cut)
    cuts.append(height)

    rows = []
    for top, bottom in zip(cuts, cuts[1:]):
        if bottom - top < 6:
            continue
        rows.append({
            "text": "?",                 # placeholder; each row is re-OCR'd later
            "confidence": 0.0,
            "x0": item["x0"], "x1": item["x1"],
            "y0": item["y0"] + top, "y1": item["y0"] + bottom,
            "split_from": item["text"],
        })
    print(f"  split tall box {item['text']!r} into {len(rows)} row(s)")
    return rows


def dm_recover_head_rows_ocr(page_image, block_lines):
    """
    EasyOCR on the ORIGINAL colour map directly above the block.
    Accept only lines that sit on the block's left edge, at its normal line
    spacing, and read as real text. Walks upward; stops at the first gap.
    """
    block_lines, expected_left, expected_height, expected_step, first_center = dm_head_geometry(block_lines)
    block_right = max(line["x1"] for line in block_lines)

    scan_x0 = max(0, int(expected_left - expected_height * 1.5))
    scan_x1 = min(page_image.width, int(block_right + (block_right - expected_left) * 0.6))
    scan_y1 = max(0, int(block_lines[0]["y0"]) - 1)
    scan_y0 = max(0, int(scan_y1 - expected_step * (dm_HEAD_MAX_ROWS + 1)))
    if scan_y1 - scan_y0 < expected_height or scan_x1 <= scan_x0:
        return [], None

    roi = page_image.crop((scan_x0, scan_y0, scan_x1, scan_y1))
    print()
    print("HEAD RECOVERY - OCR on original map above the block:")
    print("  ROI =", (scan_x0, scan_y0, scan_x1, scan_y1),
          "| expected left =", round(expected_left, 1),
          "| line step =", round(expected_step, 1))

    # Drop OCR words that cannot belong to the block BEFORE grouping them into
    # lines: tall / vertical labels (e.g. a rotated "Valentine Road") would
    # otherwise stretch one "line" over several real rows and merge them.
    block_right_local = block_right - scan_x0
    kept_items = []
    ignored_items = []
    for item in dm_easyocr_items_from_image(roi):
        width = max(1, item["x1"] - item["x0"])
        height = max(1, item["y1"] - item["y0"])
        reason = None
        if item["x0"] > block_right_local:
            reason = "right of block column"
        elif width < height * 0.8 and len(re.sub(r"\W", "", item["text"])) > 2:
            reason = "vertical text"
        elif height > expected_height * 1.8:
            if height <= expected_step * 7:
                split_rows = dm_split_tall_item_into_rows(roi, item, expected_step)
                if split_rows:
                    item["reason"] = f"split into {len(split_rows)} rows"
                    ignored_items.append(item)
                    kept_items.extend(split_rows)
                    continue
            reason = "too tall"
        if reason:
            item["reason"] = reason
            ignored_items.append(item)
            print("  ignore word:", repr(item["text"]), "|", reason)
        else:
            kept_items.append(item)

    lines = dm_group_ocr_items_into_lines(kept_items)
    for line in lines:
        line["x0"] += scan_x0
        line["x1"] += scan_x0
        line["y0"] += scan_y0
        line["y1"] += scan_y0
        line["center"] = (line["y0"] + line["y1"]) / 2.0
        line["status"] = "not reached"
    lines.sort(key=lambda line: line["center"], reverse=True)   # nearest to block first

    left_tolerance = max(40, expected_height * 1.2)
    recovered = []
    previous_center = first_center
    for line in lines:
        if len(recovered) >= dm_HEAD_MAX_ROWS:
            break
        text = str(line.get("text", "")).strip()
        gap = previous_center - line["center"]
        if gap < expected_step * 0.4:
            line["status"] = "overlaps block"
            continue
        if line["y1"] - line["y0"] > expected_height * 1.7:
            line["status"] = "row too tall (merged rows)"
            print("  skip:", repr(text), "|", line["status"])
            continue
        if abs(line["x0"] - expected_left) > left_tolerance:
            line["status"] = f"not left-aligned (left={line['x0']})"
            print("  skip:", repr(text), "|", line["status"])
            continue
        if gap > expected_step * dm_HEAD_STOP_GAP_MULTIPLIER:
            line["status"] = f"gap {gap:.0f} too large -> STOP"
            print("  STOP:", repr(text), "|", line["status"])
            break

        pad_y = max(5, int(round(expected_height * 0.2)))
        crop_box = (
            max(0, line["x0"] - 8), max(0, line["y0"] - pad_y),
            min(page_image.width, line["x1"] + 8), min(page_image.height, line["y1"] + pad_y),
        )
        original_crop = page_image.crop(crop_box)
        halo = dm_halo_text_mask(original_crop)
        clean_array = np.full(halo.shape, 255, dtype=np.uint8)
        clean_array[halo > 0] = 0
        clean_crop = Image.fromarray(clean_array, mode="L").convert("RGB")

        easy_text, easy_conf = dm_easyocr_read_single_line(original_crop)
        paddle_text, paddle_conf = dm_paddle_read_text_image(original_crop)
        paddle_clean_text, paddle_clean_conf = dm_paddle_read_text_image(clean_crop)
        easy_clean_text, easy_clean_conf = dm_easyocr_read_single_line(clean_crop)
        clean_x2 = clean_crop.resize((clean_crop.width * 2, clean_crop.height * 2))
        paddle_x2_text, paddle_x2_conf = dm_paddle_read_text_image(clean_x2)
        best = dm_choose_best_ocr([
            {"text": easy_clean_text, "confidence": easy_clean_conf, "source": "EasyOCR head clean"},
            {"text": paddle_x2_text, "confidence": paddle_x2_conf, "source": "PaddleOCR head clean x2"},
            {"text": "" if text.strip("? ") == "" else text,
             "confidence": line.get("confidence", 0.0), "source": "EasyOCR head ROI"},
            {"text": easy_text, "confidence": easy_conf, "source": "EasyOCR head line"},
            {"text": paddle_text, "confidence": paddle_conf, "source": "PaddleOCR head line"},
            {"text": paddle_clean_text, "confidence": paddle_clean_conf, "source": "PaddleOCR head clean"},
        ])
        best_text = str(best["text"]).strip()
        alnum = len(re.findall(r"[A-Za-z0-9]", best_text))
        if (
            alnum < 2
            or safe_float(best.get("confidence", 0.0)) < dm_HEAD_OCR_MIN_CONFIDENCE
            or dm_simple_text_quality(best_text) < dm_HEAD_MIN_TEXT_QUALITY
        ):
            line["status"] = f"unreadable ({best_text!r}) -> STOP"
            print("  STOP:", line["status"])
            break

        best_text = dm_normalize_od_display_text(dm_normalize_map_text_spacing(best_text))
        line["status"] = "KEPT"
        print(f"  KEPT: {best_text}  ({best['source']}, {safe_float(best.get('confidence', 0.0)):.2f})")
        recovered.append({
            "x0": crop_box[0], "y0": crop_box[1], "x1": crop_box[2], "y1": crop_box[3],
            "text": best_text,
            "winner": best["source"],
            "score": best.get("score", 0.0),
            "easy_text": easy_text or text,
            "easy_conf": easy_conf,
            "paddle_text": paddle_text or paddle_clean_text,
            "paddle_conf": max(paddle_conf, paddle_clean_conf),
            "line_image": original_crop,
            "clean_image": clean_crop,
            "head_recovery": True,
        })
        previous_center = line["center"]

    # Diagnostic picture: green = kept, red = rejected / not used. Only drawn when it is
    # going to be saved (SAVE_DEBUG_IMAGES = True) - otherwise it would be thrown away.
    if SAVE_DEBUG_IMAGES:
        try:
            debug = roi.copy()
            draw = ImageDraw.Draw(debug)
            font = get_font(18, bold=True)
            for item in ignored_items:
                draw.rectangle((item["x0"], item["y0"], item["x1"], item["y1"]), outline=(255, 140, 0), width=3)
                draw.text((item["x0"], max(0, item["y0"] - 20)), "ignored: " + item["reason"],
                          fill=(255, 140, 0), font=font)
            for line in lines:
                box = (line["x0"] - scan_x0, line["y0"] - scan_y0, line["x1"] - scan_x0, line["y1"] - scan_y0)
                color = (0, 200, 0) if line["status"] == "KEPT" else (230, 0, 0)
                draw.rectangle(box, outline=color, width=3)
                draw.text((box[2] + 6, box[1]), line["status"], fill=color, font=font)
            dm_save_debug_step_image(debug, dm_HEAD_DEBUG_FILE)
        except Exception as exc:
            print("  (could not save head debug image:", exc, ")")

    if not lines:
        print("  EasyOCR found no text above the block.")
    recovered.reverse()
    print("  OCR head recovery:", len(recovered), "row(s).")
    return recovered, roi


def dm_recover_head_rows(page_image, block_lines):
    """OCR method first; pixel (white-halo) method only as a backup."""
    if not block_lines:
        return []
    recovered, _roi = dm_recover_head_rows_ocr(page_image, block_lines)
    if recovered:
        return recovered
    print("  OCR head recovery found nothing -> trying white-halo pixel method.")
    return dm_recover_head_rows_mask(page_image, block_lines)


# ------------------------------------------------------------
# INITIALS IN PIPELINE BLOCK ROWS (pipeline data block only)
# ------------------------------------------------------------
# Names such as a manufacturer can start with initials ('A. O. Smith',
# 'U. S. Steel'). OCR reads the dots as _ or , and letters as look-alike
# digits ('A_ 0. Smith'). Two or more SINGLE characters, each followed by a
# separator, with at least one real separator (. _ ,) and a word right after
# them, are rewritten as initials and joined to the word ('A.O.Smith').
# No manufacturer names are listed.

DIGIT_AS_INITIAL = {"0": "O", "1": "I", "5": "S", "8": "B", "2": "Z", "6": "G"}
dm_INITIALS_PATTERN = re.compile(
    r"(?<![A-Za-z0-9.])((?:[A-Za-z0-9](?:\s*[._,]\s*|\s+)){2,})(?=[A-Za-z]{2,}\b)"
)


def dm_fix_initials_in_block_row(text):
    """
    Two steps:
      1. pull apart - clean each initial:      'A_ 0. Smith' -> 'A. O. Smith'
      2. push together - join initials + word: 'A. O. Smith' -> 'A.O.Smith'
    """
    def rewrite(match, joined):
        run = match.group(1)
        if not re.search(r"[._,]", run):
            return run                        # 'A B Word' without any dot: leave alone
        characters = re.findall(r"[A-Za-z0-9]", run)
        if not characters[0].isalpha():
            return run                        # initials start with a real letter ('Class 1 A. No' stays)
        letters = [DIGIT_AS_INITIAL.get(ch, ch).upper() for ch in characters]
        if any(not ch.isalpha() for ch in letters):
            return run                        # a digit with no letter look-alike: not initials
        if joined:
            return "".join(ch + "." for ch in letters)          # A.O.  (word follows directly)
        return " ".join(ch + "." for ch in letters) + " "       # A. O.  (space before the word)

    original = str(text).strip()
    apart = re.sub(r"\s+", " ", dm_INITIALS_PATTERN.sub(lambda m: rewrite(m, False), original)).strip()
    together = re.sub(r"\s+", " ", dm_INITIALS_PATTERN.sub(lambda m: rewrite(m, True), original)).strip()
    if together != original:
        print(f"BLOCK ROW INITIALS: {original!r} -> pulled apart {apart!r} -> pushed together {together!r}")
    return together


dm_MERGED_ROW_HEIGHT_FACTOR = 1.5


def dm_split_merged_block_rows(page, lines):
    """
    A block row much taller than the others is two printed rows that OCR read
    as ONE box (e.g. 'A. O. Smith' over 'Electric Flash Weld' ->
    'Electric Flash Weld A_ 0. Smith'). Cut it at the emptiest pixel rows,
    one piece per printed row; each piece is read on its own afterwards.
    """
    if len(lines) < 3:
        return lines
    heights = sorted(max(1, l["y1"] - l["y0"]) for l in lines)
    typical = heights[len(heights) // 2]
    ordered = sorted(lines, key=lambda l: l["y0"])
    centers = [(l["y0"] + l["y1"]) / 2.0 for l in ordered]
    steps = sorted(b - a for a, b in zip(centers, centers[1:]) if b > a)
    step = steps[len(steps) // 2] if steps else typical * 1.15
    output = []
    for line in ordered:
        height = line["y1"] - line["y0"]
        if height <= typical * dm_MERGED_ROW_HEIGHT_FACTOR:
            output.append(line)
            continue
        pieces = dm_split_tall_item_into_rows(
            page, {"text": line.get("text", ""), "x0": line["x0"], "y0": line["y0"],
                   "x1": line["x1"], "y1": line["y1"]}, step,
        )
        if len(pieces) < 2:
            output.append(line)
            continue
        print(f"PIPELINE BLOCK: row {line.get('text', '')!r} is {height}px tall "
              f"(typical {typical}px) -> split into {len(pieces)} rows")
        for piece in pieces:
            piece["style"] = line.get("style")
            output.append(piece)
    return output


def dm_pipeline_block_from_text_layer(page_words, candidate, zoom):
    """A pipeline data block's rows from the PDF text layer (exact, no OCR): the printed
    lines inside the block found on the page, plus the lines above and below it that
    start at the same left edge and follow on at the same line spacing (the head / tail
    rows the OCR otherwise has to recover). Returns line dicts like the OCR path, or []
    when the page has no text there."""
    x0, y0, x1, y1 = candidate["bbox"]
    inside = dm_text_layer_lines(page_words, (x0, y0, x1, y1), zoom)
    if not inside:
        return []
    left = min(b[0] for _t, b in inside)
    step = (max(b[1] for _t, b in inside) - min(b[1] for _t, b in inside)) / max(1, len(inside) - 1) \
        if len(inside) > 1 else (inside[0][1][3] - inside[0][1][1]) * 1.3
    everything = dm_text_layer_lines(page_words, (0, 0, 1e9, 1e9), zoom)
    same_left = [(t, b) for t, b in everything if abs(b[0] - left) <= max(6.0, step * 0.25)]
    rows = sorted(inside, key=lambda item: item[1][1])
    for direction in (-1, 1):
        while True:
            edge = rows[0] if direction < 0 else rows[-1]
            nxt = [(t, b) for t, b in same_left if (t, b) not in rows
                   and 0 < (edge[1][1] - b[1] if direction < 0 else b[1] - edge[1][1]) <= step * 1.6]
            if not nxt:
                break
            pick = min(nxt, key=lambda item: abs(item[1][1] - edge[1][1]))
            rows = [pick] + rows if direction < 0 else rows + [pick]
    return [{"text": re.sub(r"\s+", " ", t).strip(), "x0": int(b[0]), "y0": int(b[1]), "x1": int(b[2]),
             "y1": int(b[3]), "confidence": 1.0, "source": "PDF text layer"} for t, b in rows]


def dm_find_pipeline_blocks(page_image, note_boxes=None, reconstructed_yellow=None, detection_page=None,
                            page_words=None, zoom=None):
    note_boxes = note_boxes or []
    if detection_page is None:
        detection_page = dm_build_full_page_pipeline_isolation(
            page_image, note_boxes, reconstructed_yellow=reconstructed_yellow,
        )

    results = []
    for candidate_index, candidate in enumerate(dm_discover_all_pipeline_candidates(detection_page), start=1):
        printed = dm_pipeline_block_from_text_layer(page_words, candidate, zoom) if page_words and zoom else []
        if printed:
            print()
            print(f"PIPELINE BLOCK {candidate_index}: {len(printed)} row(s) read from the PDF text layer (exact) - "
                  f"row OCR and head / tail recovery skipped")
            final_lines = printed
            final_x0 = max(0, min(line["x0"] for line in final_lines) - dm_MAP_BLOCK_FINAL_CROP_X_PADDING)
            final_y0 = max(0, min(line["y0"] for line in final_lines) - dm_MAP_BLOCK_FINAL_CROP_Y_PADDING)
            final_x1 = min(detection_page.width, max(line["x1"] for line in final_lines) + dm_MAP_BLOCK_FINAL_CROP_X_PADDING)
            final_y1 = min(detection_page.height, max(line["y1"] for line in final_lines) + dm_MAP_BLOCK_FINAL_CROP_Y_PADDING)
            pipeline_crop = detection_page.crop((final_x0, final_y0, final_x1, final_y1))
            results.append({
                "x0": final_x0, "y0": final_y0, "x1": final_x1, "y1": final_y1,
                "image": pipeline_crop,
                "original_map_image": page_image.crop((final_x0, final_y0, final_x1, final_y1)),
                "clean_image": pipeline_crop,
                "lines": final_lines,
                "value": "\n".join(line["text"] for line in final_lines),
                "source": "PDF text layer",
            })
            continue
        print()
        print(f"Running v23 direct pipeline OCR for candidate {candidate_index}...")
        working_lines = dm_hybrid_pipeline_rows(detection_page, candidate["lines"])
        working_lines = dm_split_merged_block_rows(detection_page, working_lines)
        final_lines = []
        for line in working_lines:
            final_line = dm_read_map_line_from_pipeline_detection(detection_page, line)
            if final_line["text"].strip():
                final_line["text"] = dm_normalize_map_text_spacing(final_line["text"])
                final_line["text"] = dm_normalize_od_display_text(final_line["text"])
                final_lines.append(final_line)
        if not final_lines:
            continue

        head_rows = dm_recover_head_rows(page_image, final_lines)
        display_page = detection_page
        if head_rows:
            display_page = detection_page.copy()
            for row in head_rows:
                display_page.paste(row["clean_image"], (row["x0"], row["y0"]))
            final_lines = head_rows + final_lines

        for line in final_lines:
            line["text"] = dm_fix_initials_in_block_row(line["text"])

        final_x0 = max(0, min(line["x0"] for line in final_lines) - dm_MAP_BLOCK_FINAL_CROP_X_PADDING)
        final_y0 = max(0, min(line["y0"] for line in final_lines) - dm_MAP_BLOCK_FINAL_CROP_Y_PADDING)
        final_x1 = min(detection_page.width, max(line["x1"] for line in final_lines) + dm_MAP_BLOCK_FINAL_CROP_X_PADDING)
        final_y1 = min(detection_page.height, max(line["y1"] for line in final_lines) + dm_MAP_BLOCK_FINAL_CROP_Y_PADDING)
        pipeline_crop = display_page.crop((final_x0, final_y0, final_x1, final_y1))
        results.append({
            "x0": final_x0, "y0": final_y0, "x1": final_x1, "y1": final_y1,
            "image": pipeline_crop,
            "original_map_image": page_image.crop((final_x0, final_y0, final_x1, final_y1)),
            "clean_image": pipeline_crop,
            "lines": final_lines,
            "value": "\n".join(line["text"] for line in final_lines),
        })
    results.sort(key=lambda item: (item["y0"], item["x0"]))
    return results


# ============================================================
# DIG PACKET TABLE PAGES - HIGHLIGHTED ROWS / CELLS
# ============================================================
# Some packets include the ILI listing (spreadsheet screenshot). Rows or cells
# shown in a colour are the ones that matter.
#   - a fully coloured row -> an overall snip of the row, then EVERY non-empty
#     cell of it as its own snip + value (like the 6000 form fields)
#   - only some cells coloured -> each coloured cell as its own snip + value
# The header (incl. its coloured group labels such as B31G) is never a highlight.
# An 'x' in the first column marks the defect row(s). The Event cell comes first.

TABLE_MIN_DATA_ROWS = 10           # a table page needs at least this many equal-height rows
TABLE_MIN_IMAGE_PIXELS = 800_000   # embedded image large enough to be a table screenshot
TABLE_ROW_COLOURED_SHARE = 0.80    # this share of a row's cells coloured the same -> whole row
TABLE_OCR_UPSCALE = 3
TABLE_COLOUR_NAMES = {
    "yellow": (255, 255, 0), "green": (146, 208, 80), "blue": (0, 176, 240),
    "light blue": (155, 194, 230), "orange": (255, 192, 0), "red": (255, 0, 0),
    "pink": (255, 153, 204), "purple": (112, 48, 160), "light green": (198, 239, 206),
    "light yellow": (255, 242, 204),
}


def dt_colour_name(rgb):
    return min(TABLE_COLOUR_NAMES, key=lambda name: sum(
        (a - b) ** 2 for a, b in zip(TABLE_COLOUR_NAMES[name], rgb)))


def dt_merge_positions(positions, gap=2):
    groups = []
    for value in positions:
        if groups and value - groups[-1][-1] <= gap:
            groups[-1].append(value)
        else:
            groups.append([value])
    return [int(round(sum(group) / len(group))) for group in groups]


def dt_find_grid(image):
    """Equal-height data rows, column lines, and the header band above them."""
    gray = np.asarray(image.convert("L")).astype(int)
    height, width = gray.shape
    dark = gray < 160
    lines = dt_merge_positions([y for y in range(height) if dark[y].mean() > 0.5])
    if len(lines) < TABLE_MIN_DATA_ROWS + 2:
        return None
    gaps = np.diff(lines)
    values, counts = np.unique(gaps, return_counts=True)
    spacing = int(values[np.argmax(counts)])
    if counts.max() < TABLE_MIN_DATA_ROWS or spacing < 8:
        return None
    best, start = (0, 0), None
    for index, gap in enumerate(gaps):
        if abs(gap - spacing) <= 2:
            start = index if start is None else start
            if index + 1 - start > best[1] - best[0]:
                best = (start, index + 1)
        else:
            start = None
    rows = lines[best[0]:best[1] + 1]
    if len(rows) - 1 < TABLE_MIN_DATA_ROWS:
        return None
    top, bottom = rows[0], rows[-1]
    column_share = dark[top:bottom].mean(axis=0)
    columns = dt_merge_positions([x for x in range(width) if column_share[x] > 0.85])
    if len(columns) < 5:
        return None
    if columns[0] > 5:
        columns = [0] + columns
    if columns[-1] < width - 6:
        columns = columns + [width - 1]
    above = [y for y in lines if top - 6 * spacing <= y < top]
    header = None
    if above:
        header_top = min(above)
        below = [y for y in lines if y > header_top + spacing // 2]
        header = (header_top, min(below[0], top) if below else top)
    return {"rows": rows, "columns": columns, "spacing": spacing, "header": header}


def dt_cell_colour(pixels, x0, y0, x1, y1):
    """Background colour of a cell (text pixels ignored), or None if white/grey."""
    cell = pixels[y0 + 2:y1 - 1, x0 + 2:x1 - 1].reshape(-1, 3)
    if len(cell) == 0:
        return None
    background = cell[cell.max(axis=1) > 120]
    if len(background) < max(5, 0.2 * len(cell)):
        return None
    median = np.median(background, axis=0)
    if median.max() - median.min() < 50:
        return None
    return tuple(int(v) for v in median)


def dt_cell_has_ink(image):
    gray = np.asarray(image.convert("L")).astype(int)
    return int((gray < 110).sum()) >= 6


def dt_prepare_for_ocr(image, scale):
    """Black text on white, cropped tight around the text, enlarged and padded.
    The coloured background (yellow / blue / green) is removed using each pixel's
    brightest channel; wide, mostly empty cells are cropped to their text."""
    brightest = np.asarray(image.convert("RGB")).astype(float).max(axis=2)
    clean = np.clip((brightest - 60) / (195 - 60) * 255, 0, 255).astype("uint8")
    ys, xs = np.nonzero(clean < 128)
    if len(xs) == 0:
        return None
    clean = clean[max(0, ys.min() - 3):ys.max() + 4, max(0, xs.min() - 3):xs.max() + 4]
    gray = Image.fromarray(clean)
    gray = gray.resize((gray.width * scale, gray.height * scale), Image.LANCZOS)
    padded = Image.new("L", (gray.width + 24, gray.height + 24), 255)
    padded.paste(gray, (12, 12))
    return padded.convert("RGB")


def dt_read_looks_wrong(text):
    text = str(text or "")
    return bool(re.search(r"[\[\]{}|]", text)) or bool(re.search(r"[a-z][A-Z][a-z]", text))


def dt_read_cells(images):
    """dt_read_cell for several cells at once: the Paddle reads go to the GPU in
    batches (pictures of similar shape together); the EasyOCR check for an odd-looking
    or unsure read is the same as before. Returns the texts in order."""
    prepared = []
    for image in images:
        if image.width < 4 or image.height < 4 or not dt_cell_has_ink(image):
            prepared.append(None)
        else:
            prepared.append(dt_prepare_for_ocr(image, TABLE_OCR_UPSCALE))
    wanted = [i for i, p in enumerate(prepared) if p is not None]
    reads = dict(zip(wanted, paddle_read_text_images([prepared[i] for i in wanted], kind="table cells")))
    texts = []
    for i, picture in enumerate(prepared):
        if picture is None:
            texts.append("")
            continue
        text, confidence = reads[i]
        text, confidence = str(text).strip(), safe_float(confidence)
        if dt_read_looks_wrong(text) or confidence < 0.60:
            try:
                results = easy_reader.readtext(np.array(picture), detail=1, paragraph=False)
            except Exception:
                results = []
            if results:
                results.sort(key=lambda r: min(p[0] for p in r[0]))
                easy_text = " ".join(str(r[1]).strip() for r in results).strip()
                easy_conf = sum(safe_float(r[2]) for r in results) / len(results)
                if easy_text and (dt_read_looks_wrong(text) or easy_conf > confidence):
                    text = easy_text
        texts.append(text)
    return texts


def dt_read_cell(image):
    """Paddle reads the prepared cell; an odd-looking or unsure read is checked
    with EasyOCR and the better one is kept."""
    if image.width < 4 or image.height < 4 or not dt_cell_has_ink(image):
        return ""
    prepared = dt_prepare_for_ocr(image, TABLE_OCR_UPSCALE)
    if prepared is None:
        return ""
    text, confidence = paddle_read_text_image(prepared)
    text, confidence = str(text).strip(), safe_float(confidence)
    if dt_read_looks_wrong(text) or confidence < 0.60:
        try:
            results = easy_reader.readtext(np.array(prepared), detail=1, paragraph=False)
        except Exception:
            results = []
        if results:
            results.sort(key=lambda r: min(p[0] for p in r[0]))
            easy_text = " ".join(str(r[1]).strip() for r in results).strip()
            easy_conf = sum(safe_float(r[2]) for r in results) / len(results)
            if easy_text and (dt_read_looks_wrong(text) or easy_conf > confidence):
                text = easy_text
    return text


TABLE_HEADER_UNITS = {"ft": "ft", "in": "in", "%": "%", "°": "°", "deg": "°", "psi": "PSI", "psig": "PSIG",
                      "mm": "mm", "m": "m", "in2": "in²", "yr": "yr", "mpy": "mpy",
                      # Int/Ext column codes (I = internal, E = external); I misread as l, 1 or |
                      "i/e": "I/E", "l/e": "I/E", "1/e": "I/E", "/e": "I/E"}


def dt_clean_header_name(text):
    """A column name only: letters, digits, spaces and the few signs names use
    (/ + % ' &); stray marks from the cell borders (_ - | " ...) are dropped."""
    name = re.sub(r"\bU[I|l1]S\b", "U/S", str(text or ""))
    name = re.sub(r"\bD[I|l1]S\b", "D/S", name)
    name = re.sub(r"(?<=[A-Za-z])\|(?=[A-Za-z])", "/", name)     # Int|Ext -> Int/Ext (a '|' between letters is a '/')
    name = re.sub(r"[^A-Za-z0-9 /+%'&.]", " ", name)
    name = re.sub(r"\s+", " ", name).strip(" .'/")
    name = re.sub(r"\b([A-Za-z]{3,}) ([a-z])\b", r"\1\2", name)   # 'Toleranc e' -> 'Tolerance' (a letter split off)
    return name


def dt_clean_header_units(text):
    """The units part on its own: brackets and stray marks removed, then matched to a
    known unit when it is one (or close to one, e.g. PSII -> PSI); otherwise what
    was read (e.g. 0.1, I/E) is kept."""
    text = str(text or "")
    opening = max(text.rfind("["), text.rfind("("), text.rfind("{"))
    if opening >= 0:
        text = text[opening + 1:]                    # only what comes after the bracket
    inner = re.sub(r"[\[\]\(\)\{\}|_\"]", "", text).strip()
    compact = re.sub(r"[^A-Za-z0-9%°./]", "", inner)
    if len(compact) > 1 and compact[-1] in "1lI" and compact[-2].isalpha() and compact[-2] != compact[-1]:
        compact = compact[:-1]                       # 'I/E1' -> 'I/E' (the closing ']' read as 1 / l / I)
    if not compact:
        return ""
    key = compact.lower()
    if key in TABLE_HEADER_UNITS:
        return TABLE_HEADER_UNITS[key]
    close = get_close_matches(key, list(TABLE_HEADER_UNITS), n=1, cutoff=0.75)
    if not close and len(key) == 1 and key in ("i",):
        close = ["in"]                               # 'i' -> 'in' (the n cut off)
    return TABLE_HEADER_UNITS[close[0]] if close else compact


def dt_clear_filter_arrow(cell):
    """The spreadsheet's filter-arrow button in the header cell's bottom-right corner is
    made white WITHOUT touching letters: in that corner only NEUTRAL GREY pixels (the
    button's grey border, light fill and mid-grey triangle: equal R, G, B, value
    80-250) are whitened. Letter strokes are black (with coloured smoothing edges),
    so a letter running into the corner (the 'd' of Weld, the 'm' of Seam) stays whole."""
    arr = np.array(cell.convert("RGB"))
    h, w = arr.shape[:2]
    corner = arr[max(0, h - 24):, max(0, w - 26):].astype(np.int16)
    value = corner.max(axis=2)
    spread = value - corner.min(axis=2)
    grey = (spread <= 20) & (value >= 80) & (value <= 250)
    corner[grey] = 255
    arr[max(0, h - 24):, max(0, w - 26):] = corner.astype(np.uint8)
    return Image.fromarray(arr)


# words that belong in these table headers, written the way they are shown; checked
# before general English (e.g. 'Sean' is an English name but a header means 'Seam')
TABLE_HEADER_WORDS = {w.lower(): w for w in [
    "Seam", "Weld", "Girth", "Odometer", "Factor", "Int", "Ext", "Int/Ext", "MAOP", "SMYS", "FPR",
    "Psafe", "Pburst", "Feature", "Event", "Joint", "Length", "Distance", "Depth", "Width", "Inches",
    "Tolerance", "Covered", "Segment", "Pipe", "Long", "Position", "Safety", "Install", "Year",
    "Operating", "Stress", "Latitude", "Longitude", "Height", "Prior", "Dig", "Vendor", "Comment",
    "WT", "OD", "GW", "ID", "U/S", "D/S", "BWP", "O'clock", "No", "to", "in"]}


def dt_header_word_known(word):
    """A header word that is right as it is: in the header word list, general English,
    or not a word (numbers, signs)."""
    if not re.search(r"[A-Za-z]{2,}", word):
        return True
    return word.lower() in TABLE_HEADER_WORDS or is_general_english_word(word, 2.5)


def dt_header_one_letter_fix(word):
    """Fix a header word against the header word list, in this order, each step only
    when exactly ONE list word fits:
      1. one letter wrong (same length) - any word not in the list ('Sean' -> 'Seam',
         'Facter' -> 'Factor', '0'clock' -> 'O'clock')
      2. one letter missing - only a word that is not English ('Toleranc' -> 'Tolerance')
      3. one letter extra   - only a word that is not English ('Pburstt' -> 'Pburst')
    A word already in the list is written the list's way. Returns (word, what was done)."""
    low = word.lower()
    if low in TABLE_HEADER_WORDS:
        shown = TABLE_HEADER_WORDS[low]
        return shown, ("" if shown == word else "written the header list's way")
    if len(low) < 3:
        return word, ""
    keys = list(TABLE_HEADER_WORDS)
    wrong = [k for k in keys if len(k) == len(low) and sum(1 for x, y in zip(k, low) if x != y) == 1]
    if len(wrong) == 1:
        return TABLE_HEADER_WORDS[wrong[0]], "one letter wrong"
    if dt_header_word_known(word):
        return word, ""                              # an English word is not stretched or shortened
    missing = [k for k in keys if len(k) == len(low) + 1
               and any(k[:i] + k[i + 1:] == low for i in range(len(k)))]
    if len(missing) == 1:
        return TABLE_HEADER_WORDS[missing[0]], "one letter missing"
    extra = [k for k in keys if len(k) == len(low) - 1
             and any(low[:i] + low[i + 1:] == k for i in range(len(low)))]
    if len(extra) == 1:
        return TABLE_HEADER_WORDS[extra[0]], "one letter extra"
    return word, ""


def dt_header_drop_trailing_units(text):
    """A units-line read WITHOUT its bracket ('e 0.1', 'e in'): the trailing words that
    are units (ft, in, PSI, %, degrees...) or plain decimals (0.1) are not the name and
    are dropped. Anything else stays - '10%' in 'FPR + 10%' is part of the name."""
    words = str(text or "").split()
    known_units = {u.lower() for u in TABLE_HEADER_UNITS} | {v.lower() for v in TABLE_HEADER_UNITS.values()}
    while words and (words[-1].lower().strip("[](){}|") in known_units
                     or re.fullmatch(r"\d*\.\d+\]?", words[-1])):
        words.pop()
    return " ".join(words)


# whole header names, written the way the table prints them; a name whose letters and
# digits match one of these (spaces and '/' ignored) is written this way
TABLE_HEADER_NAMES = [
    "Dig / BWP Us", "Feature No", "Event", "Odometer", "Joint Length", "U/S GW ID", "Distance to U/S Weld",
    "Distance to D/S Weld", "OD", "WT", "Covered Segment", "MAOP", "Int/Ext", "SMYS", "Tolerance", "Depth",
    "Depth in Inches", "Length", "Width", "O'clock", "Pipe Long Seam", "Seam Position", "Safety Factor",
    "Install Year", "Operating Stress", "FPR", "FPR + 10%", "Psafe", "Pburst", "Prior Dig", "Vendor Comment",
    "Latitude", "Longitude", "Height"]

# opposites written side by side in a header are a pair and take a '/' between them
TABLE_HEADER_OPPOSITES = [("Int", "Ext"), ("Internal", "External"), ("In", "Out"), ("Inside", "Outside"),
                          ("Min", "Max"), ("Up", "Down"), ("Upstream", "Downstream"), ("Start", "End")]

CODE_LOOKALIKES = {"l": "I", "1": "I", "|": "I", "i": "I", "!": "I", "0": "O", "o": "O"}


def dt_header_name_key(text):
    """A header name's letters and digits only, lower case (spaces and '/' ignored)."""
    return re.sub(r"[^a-z0-9%+']", "", str(text or "").lower())


def dt_header_opposite_pairs(name):
    """Two opposites side by side get a '/' between them: 'Int Ext', or one word where the
    '/' was read as I, l, 1 or | ('IntIExt', 'Intlext') -> 'Int/Ext'. Returns (name, what)."""
    words, out, done, i = name.split(), [], [], 0
    while i < len(words):
        joined = None
        for a, b in TABLE_HEADER_OPPOSITES:
            if i + 1 < len(words) and words[i].lower() == a.lower() and words[i + 1].lower() == b.lower():
                joined, step = f"{a}/{b}", 2
            elif re.fullmatch(rf"{a}[Il1|]?{b}", words[i], flags=re.I) or re.fullmatch(rf"{a}/{b}", words[i], flags=re.I):
                joined, step = f"{a}/{b}", 1
            if joined:
                break
        if joined:
            before = " ".join(words[i:i + step])
            if before != joined:
                done.append(f"'{before}' -> '{joined}' ({joined.split('/')[0]} and {joined.split('/')[1]} "
                            f"are opposites side by side - a '/' between them)")
            out.append(joined)
            i += step
        else:
            out.append(words[i])
            i += 1
    return " ".join(out), done


def dt_header_known_name(name):
    """The name written the table's way when its letters / digits match a known header
    name, spaces and '/' ignored ('Dig BWP Us' -> 'Dig / BWP Us')."""
    key = dt_header_name_key(name)
    for known in TABLE_HEADER_NAMES:
        if key and dt_header_name_key(known) == key:
            return known
    return name


def dt_header_cut_off_name(words):
    """A header whose text Excel cut off at the column's right edge ('Covered Segm' for
    'Covered Segment' in a narrow column) -> the known header it is the start of.
    Only when ALL of these hold:
      - every read word but the last is the known name's word (letters / digits only,
        '/' ignored), in order;
      - the last read word is the START of the known name's next word, at least 3
        letters, and is not itself a word of the header word list (so 'FPR' stays
        'FPR' and is not turned into 'FPR + 10%');
      - exactly ONE known name fits.
    Returns (known name, the read) or (None, None)."""
    read_keys = [dt_header_name_key(w) for w in words]
    read_keys = [k for k in read_keys if k]
    if not read_keys:
        return None, None
    last = read_keys[-1]
    if len(re.sub(r"[^a-z]", "", last)) < 3 or last in TABLE_HEADER_WORDS:
        return None, None
    fits = []
    for known in TABLE_HEADER_NAMES:
        known_keys = [k for k in (dt_header_name_key(w) for w in known.split()) if k]
        n = len(read_keys)
        if len(known_keys) < n or known_keys[:n - 1] != read_keys[:-1]:
            continue
        cut_word = known_keys[n - 1]
        if cut_word != last and cut_word.startswith(last):
            fits.append(known)
    if len(fits) == 1:
        return fits[0], " ".join(words)
    return None, None


def dt_units_from_opposites(name, units):
    """Units that are two one-letter codes ('l/E') for a name that is an opposite pair
    ('Int/Ext'): the codes are the pair's first letters -> 'I/E', when the codes as read
    fit them (I may be read as l / 1 / |, O as 0). Returns (units, what) - unchanged
    and '' when this does not apply."""
    pair = re.search(r"([A-Za-z]+)/([A-Za-z]+)", name or "")
    codes = re.fullmatch(r"\s*(\S?)\s*/\s*(\S)\s*", units or "")
    if not pair or not codes:
        return units, ""
    initials = (pair.group(1)[0].upper(), pair.group(2)[0].upper())
    read = tuple(CODE_LOOKALIKES.get(c, c.upper()) if c else "" for c in codes.groups())
    if all(r in ("", want) for r, want in zip(read, initials)):
        fixed = f"{initials[0]}/{initials[1]}"
        if fixed != units:
            return fixed, (f"units '{units}' are the first letters of {pair.group(1)} / {pair.group(2)} "
                           f"-> '{fixed}'")
    return units, ""


def dt_header_piece_versions(piece):
    """Ways to read one text piece of a header (a line / word group EasyOCR found):
    the piece as it is and three clean-ups, each at two sizes."""
    gray = piece.convert("L")
    stretched = ImageOps.autocontrast(gray, cutoff=2).convert("RGB")
    versions = [("Original", piece), ("Contrast", stretched),
                ("Threshold150", make_binary(piece, 150)), ("Threshold190", make_binary(piece, 190))]
    out = []
    for name, version in versions:
        for scale in (1.0, 1.5):
            picture = version if scale == 1.0 else version.resize(
                (int(version.width * scale), int(version.height * scale)), Image.LANCZOS)
            out.append((f"{name} x{scale:g}", picture.convert("RGB")))
    return out


import numpy as np
def dt_header_group_cells(image, grid):
    """S299: the group headings above the header row (a merged, filled cell over several columns -
    'B31G', 'B31GM', 'Effective Area'): [(x0, x1, y0, y1, [column indexes])]. A column has one when a
    line sits a little above its header cell with a fill or text between; neighbours with no line
    between them in that band share it."""
    rgb = np.asarray(image.convert("RGB")).astype(int)
    gray = np.asarray(image.convert("L")).astype(int)
    dark = gray < 160
    columns, spacing = grid["columns"], grid["spacing"]
    top = grid["header"][0]
    cells = []
    for i in range(len(columns) - 1):
        a, b = columns[i] + 3, columns[i + 1] - 2
        if b - a < 6:
            continue
        line = next((y for y in range(top - 3, max(0, top - 3 * spacing), -1) if dark[y, a:b].mean() > 0.6), None)
        if line is None or top - line < 8:
            continue
        band = rgb[line + 2:top - 1, a:b].min(axis=2)          # a coloured fill (light yellow too) or text
        if band.size == 0 or (band < 235).mean() < 0.3:      # blank paper above: no group heading
            continue
        cells.append((i, line))
    groups = []
    for i, line in cells:
        if groups and groups[-1]["cols"][-1] == i - 1 and abs(groups[-1]["line"] - line) <= 2:
            x = columns[i]                                   # a vertical line between them in the band = a new group
            band_mid = slice(line + 3, top - 2)
            if dark[band_mid, max(0, x - 1):x + 2].any(axis=1).mean() < 0.8:
                groups[-1]["cols"].append(i)
                continue
        groups.append({"cols": [i], "line": line})
    return [(columns[g["cols"][0]], columns[g["cols"][-1] + 1], g["line"], top, g["cols"]) for g in groups]


# S342: the group headings an ILI table puts over repeated columns (FPR under each assessment method)
TABLE_GROUP_HEADINGS = ["B31G", "B31GM", "Modified B31G", "Effective Area", "RSTRENG", "RSTRENG 0.85dL",
                        "0.85dL", "Kastner", "DNV", "Original B31G", "Equivalent"]


def dt_read_group_heading(crop):
    """S342: a group heading read the way the column headers are - EasyOCR and PaddleOCR on 8 versions
    (as it is, stronger contrast, two thresholds, two sizes) - instead of one PaddleOCR read (which gave
    'cYammnenenatYetYetYo' and 'ent'). A read close to a known heading (TABLE_GROUP_HEADINGS, 60% alike)
    is that heading; else the most common read whose words are all English / header words; else None.
    Returns (heading or None, what was read - for the log)."""
    big = crop.resize((crop.width * 3, crop.height * 3), Image.LANCZOS)
    reads = []
    try:
        reads.append(" ".join(str(r[1]) for r in sorted(easy_reader.readtext(np.array(big), detail=1,
                                                                             paragraph=False),
                                                         key=lambda r: min(p[0] for p in r[0]))))
    except Exception:
        pass
    try:
        reads += [text for text, _conf in paddle_read_text_images(
            [picture for _name, picture in dt_header_piece_versions(big)], kind="table group heading")]
    except Exception:
        pass
    reads = [dt_clean_header_name(r) for r in reads if r and dt_clean_header_name(r)]
    listing = " | ".join(f"'{r}'" for r in reads) or "nothing read"

    def squeeze(text):
        return re.sub(r"[^a-z0-9.]", "", text.lower())
    best, score = None, 0.0
    for read in reads:
        for known in TABLE_GROUP_HEADINGS:
            ratio = SequenceMatcher(None, squeeze(read), squeeze(known)).ratio()
            if ratio > score:
                best, score = known, ratio
    if best and score >= 0.6:
        return best, f"reads {listing} -> '{best}' (a known heading, {score:.0%} alike)"
    good = Counter(r for r in reads if re.search(r"[A-Za-z]{2,}", r) and all(dt_header_word_known(w) for w in r.split()))
    if good:
        heading = good.most_common(1)[0][0]
        return heading, f"reads {listing} -> '{heading}' (most common read of English / header words)"
    return None, f"reads {listing} -> none is a known heading or English - named 'Group N' instead"


def dt_read_headers(image, grid):
    """Column names: each header cell read on its own (no words running into the
    next column); the filter arrow is whited out without touching letters
    (dt_clear_filter_arrow). Each text piece EasyOCR finds in the header (a line or
    word group) is then read again in 8 versions by PaddleOCR (batched) and the
    piece's NAME text is voted on - the most common reading of the 9 wins (ties: the
    more confident). The header becomes its name only (stray marks dropped) plus, when
    it has units in brackets, the units read on their own -> 'Name [units]'."""
    columns = grid["columns"]
    names = [""] * (len(columns) - 1)
    if not grid.get("header"):
        return names
    y0, y1 = grid["header"]
    headers = []                                     # per column: pieces + units info
    for index in range(len(names)):
        cell = image.crop((columns[index] + 2, y0 + 2, columns[index + 1] - 1, y1 - 1)).convert("RGB")
        if cell.width < 6 or cell.height < 6:
            continue
        cell = dt_clear_filter_arrow(cell)
        big = np.array(cell.resize((cell.width * 3, cell.height * 3), Image.LANCZOS))
        try:
            results = easy_reader.readtext(big, detail=1, paragraph=False)
        except Exception:
            continue
        ordered = sorted(results, key=lambda r: (round(min(p[1] for p in r[0]) / 20),
                                                 min(p[0] for p in r[0])))
        pieces, unit_box, unit_text = [], None, ""
        for points, text, conf in ordered:
            text = str(text).strip()
            xs, ys = [p[0] for p in points], [p[1] for p in points]
            x0b, x1b, y0b, y1b = int(min(xs)), int(max(xs)), int(min(ys)), int(max(ys))
            bracket = re.search(r"[\[\(\{]", text)
            if unit_box is not None:
                continue                             # anything after the units is not the name
            if bracket:
                # the units start at the bracket: that part of this piece's box is read alone
                start = x0b + (x1b - x0b) * bracket.start() / max(1, len(text))
                unit_box = (max(0, int(start) - 12), max(0, y0b - 3),
                            min(big.shape[1], x1b + 4), min(big.shape[0], y1b + 3))
                unit_text = text[bracket.start():]
                # this piece is ALWAYS read too: letters in front of the bracket (the 'e' of
                # a header that wraps as 'Toleranc' / 'e [0.1]') belong to the NAME, even
                # when EasyOCR did not see them
            crop = Image.fromarray(big[max(0, y0b - 3):min(big.shape[0], y1b + 3),
                                       max(0, x0b - 4):min(big.shape[1], x1b + 4)])
            pieces.append({"easy": text, "easy_conf": float(conf), "crop": crop, "units_line": bool(bracket),
                           "versions": dt_header_piece_versions(crop) if crop.width > 4 and crop.height > 4 else []})
        headers.append({"index": index, "big": big, "pieces": pieces, "unit_box": unit_box,
                        "unit_text": unit_text})

    # S42: every piece's versions are read in two steps. First only TWO versions made
    # differently (Original x1 and Threshold150 x1). A piece whose EasyOCR name and
    # both of those reads are spelled exactly the same, with every word a known word,
    # is settled - its other 6 versions could only add more copies of that reading.
    # Every other piece gets all its versions read, as before. Reads are batched by
    # shape and the first batch is checked, as before.
    def piece_name(raw, piece):
        raw = str(raw)
        bracket = re.search(r"[\[\(\{]", raw)
        name = raw[:bracket.start()] if bracket else raw
        if not bracket and piece.get("units_line"):
            name = dt_header_drop_trailing_units(name)
        return dt_clean_header_name(name)

    header_started = time.perf_counter()
    first_versions = ("Original x1", "Threshold150 x1")
    read_by_version = {}                             # (header, piece, version) -> (raw, confidence)
    jobs = [(h_i, p_i, v_name, picture) for h_i, header in enumerate(headers)
            for p_i, piece in enumerate(header["pieces"]) for v_name, picture in piece["versions"]
            if v_name in first_versions]
    for (h_i, p_i, v_name, _p), read in zip(jobs, paddle_read_text_images(
            [picture for _a, _b, _c, picture in jobs], kind="table headers")):
        read_by_version[(h_i, p_i, v_name)] = read
    settled, all_pieces = set(), 0
    for h_i, header in enumerate(headers):
        for p_i, piece in enumerate(header["pieces"]):
            if not piece["versions"]:
                continue
            all_pieces += 1
            bracket = re.search(r"[\[\(\{]", piece["easy"])
            easy_name = dt_clean_header_name(piece["easy"][:bracket.start()] if bracket else piece["easy"])
            first = [read_by_version.get((h_i, p_i, v)) for v in first_versions]
            if (easy_name and all(r is not None for r in first)
                    and all(piece_name(r[0], piece) == easy_name for r in first)
                    and all(dt_header_word_known(w) for w in easy_name.split())):
                settled.add((h_i, p_i))
    jobs = [(h_i, p_i, v_name, picture) for h_i, header in enumerate(headers)
            for p_i, piece in enumerate(header["pieces"]) for v_name, picture in piece["versions"]
            if v_name not in first_versions and (h_i, p_i) not in settled]
    for (h_i, p_i, v_name, _p), read in zip(jobs, paddle_read_text_images(
            [picture for _a, _b, _c, picture in jobs], kind="table headers")):
        read_by_version[(h_i, p_i, v_name)] = read
    full_count = sum(len(piece["versions"]) for header in headers for piece in header["pieces"])
    print(f"TABLE HEADER READS: {len(settled)} of {all_pieces} piece(s) settled by EasyOCR + 2 PaddleOCR versions "
          f"spelled the same (known words) -> {len(read_by_version)} of {full_count} version pictures read "
          f"({time.perf_counter() - header_started:.1f} s)")
    votes = defaultdict(list)                        # (header, piece) -> [(name text, confidence, source)]
    for h_i, header in enumerate(headers):           # in the versions' own order, as before
        for p_i, piece in enumerate(header["pieces"]):
            for v_name, _picture in piece["versions"]:
                read = read_by_version.get((h_i, p_i, v_name))
                if read is not None:
                    votes[(h_i, p_i)].append((piece_name(read[0], piece), read[1], f"Paddle {v_name}"))

    shown, changed, read_logs = [], [], []
    for h_i, header in enumerate(headers):
        parts = []                                   # (voted text, from the units line?)
        for p_i, piece in enumerate(header["pieces"]):
            easy_text = piece["easy"]
            bracket = re.search(r"[\[\(\{]", easy_text)
            easy_name = dt_clean_header_name(easy_text[:bracket.start()] if bracket else easy_text)
            candidates = [(easy_name, piece["easy_conf"], "EasyOCR")] + votes.get((h_i, p_i), [])
            # the vote does not care about capitals: 'FPR' and 'fpr' are ONE reading; it is
            # written the way most of its reads wrote it. On the units line an empty name
            # (nothing in front of the bracket) is a reading too.
            tally = {}
            for text, confidence, _source in candidates:
                if not text and not piece.get("units_line"):
                    continue
                entry = tally.setdefault(text.lower(), {"count": 0, "conf": 0.0, "spellings": Counter()})
                entry["count"] += 1
                entry["conf"] += confidence
                entry["spellings"][text] += 1
            listing = " | ".join(f"{source} '{text}'" for text, _conf, source in candidates)
            if not tally:
                read_logs.append(f"  column {header['index'] + 1}, piece '{easy_text}': {listing} "
                                 f"-> no name in any read, left out")
                continue
            ranked = sorted(tally.values(), key=lambda e: (-e["count"], -e["conf"]))
            shown_as = lambda e: e["spellings"].most_common(1)[0][0]
            best = ranked[0]
            winner, count = shown_as(best), best["count"]
            reason = f"most common, {count} of {len(candidates)} reads (capitals not counted)"
            # English / header-word check: a reading whose words are all known beats one with
            # an unknown word, whatever the count (8 copies of one misread by the same model
            # are not 8 opinions)
            if winner and not all(dt_header_word_known(w) for w in winner.split()):
                for other in ranked[1:]:
                    text = shown_as(other)
                    if text and all(dt_header_word_known(w) for w in text.split()):
                        reason = (f"'{winner}' ({count} reads) has a word that is not English or a header word; "
                                  f"'{text}' ({other['count']} reads) is")
                        winner = text
                        break
            if len(tally) > 1 or winner != easy_name:
                read_logs.append(f"  column {header['index'] + 1}, piece '{easy_text}': {listing} "
                                 f"-> '{winner}' ({reason})")
            if winner:
                parts.append((winner, bool(piece.get("units_line"))))
        # join the pieces: 1-2 small letters on the units line (or right after a word) that
        # make the word before them a known word are the END of that word, not a new word
        # ('Toleranc' + 'e' -> 'Tolerance')
        words = []
        for text, units_line in parts:
            if (words and re.fullmatch(r"[a-z]{1,2}", text)
                    and (units_line or not dt_header_word_known(words[-1]))
                    and dt_header_word_known(words[-1] + text)):
                read_logs.append(f"  column {header['index'] + 1}: '{words[-1]}' + '{text}' "
                                 f"(letters in front of the units, on the next line) -> '{words[-1] + text}'")
                words[-1] = words[-1] + text
            else:
                words.extend(text.split())
        # a header Excel cut off at the column's edge ('Covered Segm') is the known name it
        # starts (checked FIRST - the one-letter fix would make 'Segm' -> 'Seam')
        cut_name, cut_read = dt_header_cut_off_name(words)
        if cut_name:
            read_logs.append(f"  column {header['index'] + 1}: '{cut_read}' is the start of the known header "
                             f"'{cut_name}' (the text was cut off at the column's edge) -> '{cut_name}'")
            words = cut_name.split()
        # a word one letter from a header-list word -> that word: one letter wrong
        # (Sean -> Seam), missing (Toleranc -> Tolerance) or extra (Pburstt -> Pburst)
        fixed_words = []
        for w in words:
            new_word, what = dt_header_one_letter_fix(w) if not cut_name else (w, "")
            if what:
                read_logs.append(f"  column {header['index'] + 1}: {what} vs a header word: '{w}' -> '{new_word}'")
            fixed_words.append(new_word)
        easy_whole = dt_clean_header_name(" ".join(
            dt_clean_header_name(p["easy"][:m.start()] if (m := re.search(r"[\[\(\{]", p["easy"])) else p["easy"])
            for p in header["pieces"]))
        parts = [" ".join(fixed_words)]
        if parts[0] != easy_whole:
            changed.append(f"'{easy_whole}' -> '{parts[0]}'")
        name = dt_clean_header_name(" ".join(parts))
        # opposites side by side take a '/' (IntIExt -> Int/Ext); then a name that is a known
        # header (spaces and '/' ignored) is written the table's way (Dig BWP Us -> Dig / BWP Us)
        name, pair_done = dt_header_opposite_pairs(name)
        for what in pair_done:
            read_logs.append(f"  column {header['index'] + 1}: {what}")
        known_name = dt_header_known_name(name)
        if known_name != name:
            read_logs.append(f"  column {header['index'] + 1}: '{name}' is the known header '{known_name}' "
                             f"(same letters, spaces and '/' ignored) -> written that way")
            name = known_name
        units, big, unit_box = "", header["big"], header["unit_box"]
        if unit_box is not None and unit_box[2] - unit_box[0] > 4 and unit_box[3] - unit_box[1] > 4:
            alone, _c = paddle_read_text_image(Image.fromarray(big[unit_box[1]:unit_box[3], unit_box[0]:unit_box[2]]))
            from_alone, from_full = dt_clean_header_units(alone), dt_clean_header_units(header["unit_text"])
            known = set(TABLE_HEADER_UNITS.values())
            # a known unit wins: the units read on their own first, then the full header read
            units = (from_alone if from_alone in known else
                     from_full if from_full in known else from_alone or from_full)
            if re.match(r"(latitude|longitude)", name.lower()) and units in ("%", "o", "O", "0"):
                units = "°"                          # a coordinate is in degrees: '°' read as '%'
            units, what = dt_units_from_opposites(name, units)
            if what:
                read_logs.append(f"  column {header['index'] + 1}: {what}")
        names[header["index"]] = f"{name} [{units}]" if units else name
        shown.append(names[header["index"]] or "(empty)")
    # S299: column names that repeat (FPR under B31G, B31GM and Effective Area) get the group heading above
    # them in front ('B31GM FPR') - else their values were taken for one thing and compared
    counts = Counter(dt_header_name_key(n) for n in names if n)
    if any(c > 1 for c in counts.values()):
        for number, (x0, x1, gy0, gy1, cols) in enumerate(dt_header_group_cells(image, grid), start=1):
            crop = image.crop((x0 + 2, gy0 + 2, x1 - 1, gy1 - 1)).convert("RGB")
            group, how = dt_read_group_heading(crop)                                   # S342
            read_logs.append(f"  heading over columns {cols[0] + 1}-{cols[-1] + 1}: {how} (S342)")
            if not group:
                group = f"Group {number}"               # S342: unreadable - never a garbled name
            for index in cols:
                if index < len(names) and names[index] and counts[dt_header_name_key(names[index])] > 1:
                    read_logs.append(f"  column {index + 1}: '{names[index]}' repeats in the table - under the "
                                     f"heading '{group}' -> '{group} {names[index]}' (S299)")
                    names[index] = f"{group} {names[index]}"
        shown = [names[h["index"]] or "(empty)" for h in headers]
    if read_logs:
        print("TABLE HEADER READS (pieces whose reads did not all agree, or whose name was changed):")
        for line in read_logs:
            print(line)
    if changed:
        print("TABLE HEADER VOTES (EasyOCR read -> name used): " + " | ".join(changed))
    if shown:
        print("TABLE HEADERS (name only; units read on their own): " + " | ".join(shown))
    return names

def dt_check_code_units(headers, items):
    """A column whose units are one-letter codes ('Int/Ext [I/E]'): its values should each
    be one of the codes. Logged as a check of the units (values are not changed)."""
    for c, header in enumerate(headers):
        units = re.search(r"\[([A-Za-z])/([A-Za-z])\]", header or "")
        if not units:
            continue
        codes = {units.group(1).upper(), units.group(2).upper()}
        shown_codes = f"{units.group(1).upper()}/{units.group(2).upper()}"
        values = [cell["value"].strip().upper() for item in items for cell in item["cells"]
                  if cell.get("column") == c and cell.get("value")]
        if not values:
            continue
        counts = Counter(values)
        listing = ", ".join(f"{v} x{n}" for v, n in counts.most_common())
        if set(counts) <= codes:
            print(f"UNITS CHECK: {header}: the column's values are {listing} - each one of "
                  f"{shown_codes} -> the units fit the column")
        else:
            others = ", ".join(sorted(set(counts) - codes))
            print(f"UNITS CHECK: {header}: the column's values are {listing} - {others} is not one of "
                  f"{shown_codes} ⚠ check the header units or those cells")


def dt_find_column(headers, *keywords):
    for index, header in enumerate(headers):
        cleaned = re.sub(r"[^a-z]", "", header.lower())
        if any(keyword in cleaned for keyword in keywords):
            return index
    return None


def dt_row_snip(image, grid, row_index):
    """REAL snips, unaltered: (header band, row) - two separate crops of the page,
    never joined, resized or cut. Shown separately in the window."""
    columns, rows = grid["columns"], grid["rows"]
    x0, x1 = columns[0], columns[-1] + 1
    header = grid.get("header")
    header_snip = image.crop((x0, header[0], x1, header[1] + 1)) if header else None
    row_snip = image.crop((x0, rows[row_index], x1, rows[row_index + 1] + 1))
    return header_snip, row_snip


def dt_cell_snip(image, grid, row_index, col):
    """REAL snips, unaltered: (header cell, data cell) - two separate crops of the page."""
    columns, rows = grid["columns"], grid["rows"]
    x0, x1 = columns[col], columns[col + 1] + 1
    header = grid.get("header")
    header_snip = image.crop((x0, header[0], x1, header[1] + 1)) if header else None
    cell_snip = image.crop((x0, rows[row_index], x1, rows[row_index + 1] + 1))
    return header_snip, cell_snip


def dt_page_table_image(document, page):
    """The table picture: the largest embedded image, else the rendered page."""
    best = None
    for info in page.get_images(full=True):
        xref, width, height = info[0], info[2], info[3]
        if width * height >= TABLE_MIN_IMAGE_PIXELS and (best is None or width * height > best[0]):
            best = (width * height, xref)
    if best:
        try:
            data = document.extract_image(best[1])
            return Image.open(io.BytesIO(data["image"])).convert("RGB")
        except Exception:
            pass
    return render_page(page, 2.0)


PIPELINE_NAME_LOOKALIKES = str.maketrans({"1": "I", "|": "I", "l": "I", "0": "O", "5": "S", "8": "B"})


def pipeline_name_key(text):
    """For comparing a handwriting read with printed text: capitals, letters and
    digits only, and look-alike characters made the same (1/I/l/|, 0/O, 5/S, 8/B)."""
    return re.sub(r"[^A-Za-z0-9|]", "", str(text or "")).translate(PIPELINE_NAME_LOOKALIKES).upper()


def pipeline_name_printed_words(key, words, limit=6):
    """Printed words (indexes into `words`, one printed line) that together spell
    `key`: in ANY order (the handwriting may have them in different spots), each word
    used once, other printed words on the line ignored. Of all ways that fit, the one
    whose words sit closest together. Returns the indexes in printed order, or None."""
    keys = [pipeline_name_key(w) for w in words]
    best = []

    def search(rest, used):
        if not rest:
            span = max(used) - min(used)
            if not best or span < best[1]:
                best[:] = [sorted(used), span]
            return
        if len(used) >= limit:
            return
        for index, word_key in enumerate(keys):
            if word_key and index not in used and rest.startswith(word_key):
                search(rest[len(word_key):], used + [index])

    search(key, [])
    return best[0] if best else None


def link_coloured_map_notes_to_table(results):
    """A yellow map note printed in a colour other than black (e.g. red) is compared
    with the table rows read from the highlighted table page(s): the row whose
    Odometer equals the note's Wheel Count (S438: written the same) is the same anomaly.
    The match is kept with the note (note['table_match']) and shown in the log and the
    summary."""
    tables = results.get("Table Highlights") or []
    for map_page in results.get("Map Pages") or []:
        for note in map_page.get("notes", []):
            colour = note.get("text_colour")
            if not colour or colour == "black":
                continue
            found = re.search(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)", str(note.get("value") or ""), re.IGNORECASE)
            label = f"yellow note {note.get('index')} ({colour} text)"
            if not found:
                print(f"COLOURED MAP NOTE: {label} on map page {map_page.get('page_number')} has no Wheel Count "
                      f"to compare with the table")
                continue
            wheel = found.group(1)                               # S438: as written
            match = None
            for table_page in tables:
                for item in table_page.get("items", []):
                    text = cmp_table_cell(item, r"odometer") or item.get("odometer") or ""
                    digits = re.sub(r"[^0-9.]", "", str(text))
                    try:
                        if digits and wheel_same(digits, wheel):          # S438: exactly
                            match = f"table page {table_page.get('page_number')} {item.get('title')}"
                            break
                    except ValueError:
                        continue
                if match:
                    break
            note["table_match"] = match
            if match:
                print(f"COLOURED MAP NOTE: {label} on map page {map_page.get('page_number')} - Wheel Count "
                      f"{found.group(1)} = Odometer of {match} -> the same anomaly")
            else:
                print(f"COLOURED MAP NOTE: {label} on map page {map_page.get('page_number')} - Wheel Count "
                      f"{found.group(1)} is not in the table rows read" + ("" if tables else " (no table page found)"))


def confirm_pipeline_name_on_dig_sheet(document, name_result, sheets):
    """The page-1 pipeline name is handwriting; the dig sheet page(s) print the same
    name as real text (the PDF's text layer, e.g. 'Boardwalk' / 'Index 129 BTI
    Refugio to Edna'). A PaddleOCR read of the handwriting is compared with each
    printed line: when printed words on one line spell the whole read - look-alikes
    1/I, 0/O, 5/S, 8/B counted as the same, spaces and brackets ignored, the words in
    any order, other words on the line allowed - the name is confirmed and written
    the way the page prints it: those printed words, in printed order, with the
    page's spaces and capitals ('1NDEX129(BT1)' -> 'Index 129 BTI'). The 'no two
    reads agree' warning is dropped."""
    if not name_result or not name_result.get("reads") or not sheets:
        return
    wanted = [(reader, text) for reader, text, _conf in name_result["reads"]
              if str(reader).startswith("PaddleOCR") and len(pipeline_name_key(text)) >= 4]
    if not wanted:
        return
    found = None                                     # (span, page, reader, read, printed, line)
    for sheet in sheets:
        lines = defaultdict(list)                    # printed lines, words in order
        for w in document[sheet["page"] - 1].get_text("words"):
            lines[(w[5], w[6])].append(w[4])
        for line in lines.values():
            for reader, text in wanted:
                picked = pipeline_name_printed_words(pipeline_name_key(text), line)
                if picked is None:
                    continue
                span = picked[-1] - picked[0]
                printed = " ".join(line[i].strip(",;:") for i in picked)
                if found is None or span < found[0]:
                    found = (span, sheet["page"], reader, text, printed, " ".join(line))
    if found is None:
        print("PIPELINE NAME: no PaddleOCR read is spelled by the printed words of one line on the dig sheet "
              "page(s) - page-1 result kept")
        return
    _span, page_number, reader, text, printed, line_text = found
    old = name_result.get("value")
    name_result["value"] = printed
    name_result["warning"] = None
    name_result["confirmed"] = f"{reader} read {text!r} is spelled by {printed!r} printed on page {page_number}"
    print(f"PIPELINE NAME: {reader} read {text!r} is spelled by the words {printed!r} in the printed line "
          f"{line_text!r} on page {page_number} (look-alikes 1/I, 0/O, 5/S, 8/B allowed) -> written as page "
          f"{page_number} prints it: {printed!r} (was {old!r})")


def confirm_pipeline_name_on_map_red_notes(name_result, map_pages):
    """When the dig sheet did not confirm the page-1 pipeline name, the map page's red
    notes (exact PDF text, e.g. 'SHC 20-1' written along the pipeline) are checked the
    SAME way as the dig sheet's printed lines: each line of a red note is one printed
    line, and its words must spell a whole PaddleOCR read (look-alikes 1/I, 0/O, 5/S,
    8/B counted as the same, spaces and brackets ignored). A red note that does not
    spell a read (e.g. 'Note: Dresser 220 Sleeve Installed ...') confirms nothing.
    When one fits, the name is written as the map prints it and the 'no two reads
    agree' warning is dropped."""
    if not name_result or not name_result.get("reads") or name_result.get("confirmed"):
        return
    wanted = [(reader, text) for reader, text, _conf in name_result["reads"]
              if str(reader).startswith("PaddleOCR") and len(pipeline_name_key(text)) >= 4]
    notes = [(map_page.get("page_number"), red) for map_page in map_pages or []
             for red in map_page.get("red_notes", []) or []]
    if not wanted:
        return
    if not notes:
        print("PIPELINE NAME: the map page(s) have no red notes to compare with - page-1 result kept")
        return
    found = None                                     # (span, page, note index, reader, read, printed, line)
    for page_number, red in notes:
        for line_text in str(red.get("value") or "").split("\n"):
            line = line_text.split()
            for reader, text in wanted:
                picked = pipeline_name_printed_words(pipeline_name_key(text), line)
                if picked is None:
                    continue
                span = picked[-1] - picked[0]
                printed = " ".join(line[i].strip(",;:") for i in picked)
                if found is None or span < found[0]:
                    found = (span, page_number, red.get("index"), reader, text, printed, line_text)
    if found is None:
        print(f"PIPELINE NAME: no PaddleOCR read is spelled by the words of one line of the map's "
              f"{len(notes)} red note(s) - page-1 result kept")
        return
    _span, page_number, index, reader, text, printed, line_text = found
    old = name_result.get("value")
    name_result["value"] = printed
    name_result["warning"] = None
    name_result["confirmed_red_note"] = (page_number, index)          # S173: the Line ID's map snip
    name_result["confirmed"] = (f"{reader} read {text!r} is spelled by {printed!r} in red note {index} "
                                f"on map page {page_number}")
    print(f"PIPELINE NAME: {reader} read {text!r} is spelled by the words {printed!r} in red note {index} "
          f"line {line_text!r} on map page {page_number} (look-alikes 1/I, 0/O, 5/S, 8/B allowed) -> "
          f"written as the map prints it: {printed!r} (was {old!r})")


TABLE_SIGN_DEGREES = 0.05       # S423: a coordinate this close to one the packet gives with its '-' (about 3 miles) shares it


def fix_table_coordinate_signs(results):
    """S423: a table Latitude / Longitude read without its '-' ('93.30173373' - PaddleOCR drops the minus at
    the cell edge) while the same packet gives that axis WITH a '-': a map note's ('Long. -93.30171292') or another
    row's on the same table page read with it. A number within TABLE_SIGN_DEGREES of such a coordinate cannot be on
    the other side of the world - it gets the minus. Only a missing minus is put in (never one taken away).
    S435: no wheel count arithmetic - which coordinate it is matched with goes by the coordinates alone."""
    tables = results.get("Table Highlights") or []
    if not tables:
        return
    axes = {"Latitude": r"latitude", "Longitude": r"longitude"}
    for axis, pattern in axes.items():
        notes = []                                     # (value, where it comes from) - for every table page
        for note in map_note_coordinates(results.get("Map Pages")):
            text = note["lat_text" if axis == "Latitude" else "lon_text"]
            if text.startswith("-"):
                notes.append((float(text), f"map page {note['page']} note ({note['label']})"))
        fixed = []
        for table_page in tables:
            cells, anchors = [], list(notes)
            for row in table_page.get("items") or []:
                for cell in row.get("cells") or []:
                    if re.match(pattern, re.sub(r"[^a-z]", "", cell["name"].lower())) \
                            and re.fullmatch(r"\s*-?\d{1,3}\.\d+\s*", str(cell.get("value") or "")):
                        cells.append((row, cell))
                        if str(cell["value"]).strip().startswith("-"):
                            anchors.append((float(cell["value"]), f"table page {table_page['page_number']} "
                                                                  f"{row.get('title')}"))
            for row, cell in cells:
                value = str(cell["value"]).strip()
                if value.startswith("-") or not anchors:
                    continue
                near = min(anchors, key=lambda a: abs(abs(a[0]) - float(value)))
                if abs(abs(near[0]) - float(value)) <= TABLE_SIGN_DEGREES:
                    cell["read_value"], cell["value"] = value, "-" + value
                    fixed.append((table_page["page_number"], row, value, near))
        if fixed:
            near_names = list(dict.fromkeys(f"{n[1]} {n[0]}" for *_x, n in fixed))
            print(f"COORDINATE SIGN: {len(fixed)} table {axis} cell(s) read without the '-' - "
                  + "; ".join(f"page {p} {r.get('title')} {v} -> -{v}" for p, r, v, _n in fixed)
                  + f" - the packet gives this {axis} with a '-' within {TABLE_SIGN_DEGREES}° "
                    f"({'; '.join(near_names)}) (S423/S435)")


def map_note_coordinates_vs_table(results):
    """Every yellow map note (any text colour) with a Wheel Count is compared with the
    table row whose Odometer equals it (S438: written the same), on everything both have:
      - Latitude / Longitude: rounded to the shorter of the two decimal lengths;
      - Event: the row's Event name must appear in the note's description lines (the
        lines that are not Wheel Count / Latitude / Longitude / Mile / Station), e.g.
        'Metal Loss' in 'External Metal Loss', 'AGM 13' in 'AGM 13 / 20' Upstream of';
      - Int/Ext: when the description says External or Internal, E / I must fit it.
    (Mile / Station has no table column, so it is not compared here.) A difference gets
    a warning on the TABLE cell (orange under the cell, '⚠ check snip' in the wheel
    counts table) - the value itself is NOT changed: the map and the table can come
    from different sources. White rows on a map note had these cells read for this
    (see extract_table_highlights). note['table_match'] is still set for coloured
    notes only."""
    from decimal import Decimal, InvalidOperation
    tables = results.get("Table Highlights") or []
    if not tables:
        return
    patterns = {"Latitude": r"Lat(?:itude)?\.?\s*(-?\d{1,2}\.\d+)",
                "Longitude": r"Long(?:itude)?\.?\s*(-?\d{1,3}\.\d+)"}
    not_description = re.compile(r"^\s*(wheel\s*count|lat(itude)?\b|long(itude)?\b|mile|station|sta\b|mp\b)",
                                 re.IGNORECASE)

    def letters(text):
        return re.sub(r"[^A-Z0-9]", "", str(text).upper())

    def find_cell(item, pattern):
        return next((c for c in item.get("cells", [])
                     if re.match(pattern, re.sub(r"[^a-z]", "", c["name"].lower()))), None)

    def flag(cell, warning, note, label, map_value):
        cell["warning"] = f"{cell['warning']}  {warning}" if cell.get("warning") else warning
        cell.setdefault("warning_details", []).append({     # for the Warnings tab
            "text": warning,
            "pictures": [(f"{label} - map", note.get("image"))],
            "values": [("Table cell reads", cell.get("value")), (f"{label} has", map_value)]})

    for map_page in results.get("Map Pages") or []:
        for note in map_page.get("notes", []):
            text = str(note.get("value") or "")
            found_wheel = re.search(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)", text, re.IGNORECASE)
            if not found_wheel:
                continue
            note_values = {name: m.group(1) for name, pattern in patterns.items()
                           if (m := re.search(pattern, text, re.IGNORECASE))}
            description = " ".join(line.strip() for line in text.split("\n")
                                   if line.strip() and not not_description.match(line))
            wheel = found_wheel.group(1)                         # S438: as written
            colour = note.get("text_colour")
            label = (f"yellow note {note.get('index')}" + (f" ({colour} text)" if colour and colour != "black" else "")
                     + f" on map page {map_page.get('page_number')}")
            for table_page in tables:
                for item in table_page.get("items", []):
                    odometer = cmp_table_cell(item, r"odometer") or item.get("odometer") or ""
                    digits = re.sub(r"[^0-9.]", "", str(odometer))
                    try:
                        if not digits or not wheel_same(digits, wheel):    # S438: exactly
                            continue
                    except ValueError:
                        continue
                    row = f"table page {table_page.get('page_number')} {item.get('title')}"
                    parts = []
                    for name, note_value in note_values.items():
                        cell = find_cell(item, name.lower())
                        table_value = str((cell or {}).get("value") or "").replace(" ", "")
                        if not re.fullmatch(r"-?\d{1,3}\.\d+", table_value):
                            continue
                        places = min(len(table_value.split(".")[1]), len(note_value.split(".")[1]))
                        step = Decimal(1).scaleb(-places)
                        try:
                            same = Decimal(table_value).quantize(step) == Decimal(note_value).quantize(step)
                        except InvalidOperation:
                            continue
                        if same:
                            parts.append(f"{name} {table_value} same")
                            continue
                        parts.append(f"{name} {note_value} (map) vs {table_value} (table) -> DIFFERENT")
                        flag(cell, f"⚠ the map note with this Wheel Count ({label}) has {note_value} - check the snip",
                             note, label, note_value)
                    event_cell = find_cell(item, "event")
                    if description and event_cell and letters(event_cell.get("value")):
                        if letters(event_cell["value"]) in letters(description):
                            parts.append(f"Event '{event_cell['value']}' same (in '{description}')")
                        else:
                            parts.append(f"Event '{event_cell['value']}' (table) not in '{description}' (map) "
                                         f"-> DIFFERENT")
                            flag(event_cell, f"⚠ the map note with this Wheel Count ({label}) says "
                                             f"'{description}' - check the snip", note, label, description)
                    side_cell = find_cell(item, "intext")
                    side = "EXTERNAL" if "EXTERNAL" in description.upper() else (
                        "INTERNAL" if "INTERNAL" in description.upper() else None)
                    side_value = letters((side_cell or {}).get("value"))
                    if side and side_value in {"E", "I"}:
                        if side_value == side[0]:
                            parts.append(f"Int/Ext {side_value} same ({side.title()})")
                        else:
                            parts.append(f"Int/Ext {side_value} (table) vs {side.title()} (map) -> DIFFERENT")
                            flag(side_cell, f"⚠ the map note with this Wheel Count ({label}) says "
                                            f"{side.title()} - check the snip", note, label, side.title())
                    if not parts:
                        print(f"MAP NOTE vs TABLE: {label} - Wheel Count {found_wheel.group(1)} = {row}, "
                              f"but the row has nothing read that the note can be compared with")
                    else:
                        verdict = ("check the table cell's snip" if any("DIFFERENT" in p for p in parts)
                                   else "everything compared matches")
                        print(f"MAP NOTE vs TABLE: {label} - Wheel Count {found_wheel.group(1)} = {row}: "
                              + "; ".join(parts) + f" -> {verdict}")


def page1_item(result, label):
    """The page-1 value item of one bullet ('(A)'), or the only item when there are no bullets."""
    items = (result or {}).get("items") or []
    marker = label.strip("() ")
    if not marker:
        return items[0] if len(items) == 1 else None
    return next((item for item in items if item.get("marker") == marker), None)


def digits_dropped_from(read, full, most=2):
    """True when `read` is `full` with 1..most characters left out - everything else the
    same and in the same order ('00553.07' in '100553.07'). A different digit anywhere
    ('100559.07') does not count."""
    read, full = re.sub(r"\s", "", str(read)), re.sub(r"\s", "", str(full))
    if not 1 <= len(full) - len(read) <= most:
        return False
    position = 0
    for character in full:
        if position < len(read) and read[position] == character:
            position += 1
    return position == len(read)


# S77: each Notes line names an anomaly, e.g. "(B) 28.0% EXTERNAL METAL LOSS @ 00:24".
# Its bullet leads to the page-1 Wheel Count with that letter, and that Wheel Count to
# the table row with the same Odometer. Where a part of the line is a look-alike read of
# what that row says, the row's value is used (blue note under the Notes). A part that
# reads as something else is left as read - only look-alike reads are fixed:
#   percentage: 28.0%0 with Depth [%] 28 -> 28.0%   (stray marks after the % dropped)
#   time:       00124 with O'clock 00:24 -> 00:24   (colon read as 1 / I / .)
#   words:      10550 where Int/Ext + Event say EXTERNAL METAL LOSS -> LOSS @
#               (digits that are look-alikes of a missing word; one extra mark before
#               the time = the @)
NOTE_LOOKALIKE_LETTERS = {"0": "O", "1": "L", "5": "S", "8": "B", "2": "Z", "6": "G", "7": "T", "4": "A",
                          "3": "E", "$": "S", "|": "I"}
AT_SIGN_LOOKALIKES = set("O0@ZC2E")
NOTE_WORD_MATCH_MIN = 0.75          # S467: how alike a read word must be to a printed event word to take it


def note_word_lookalike(token, word):
    """'' if token is not a look-alike of word; word, or word + ' @' (one extra mark at the
    end that looks like an @)."""
    if not re.search(r"[0-9$|]", token):           # only reads with digits / symbols are fixed
        return ""
    mapped = "".join(NOTE_LOOKALIKE_LETTERS.get(c, c) for c in token.upper())
    mapped_i = mapped.replace("L", "I")
    word = word.upper()
    for candidate in (mapped, mapped_i):
        if candidate == word:
            return word
        if len(candidate) == len(word) + 1 and candidate.startswith(word) and token[-1].upper() in AT_SIGN_LOOKALIKES:
            return word + " @"
    return ""


def table_row_for_wheel_count(results, wheel):
    try:
        target = re.sub(r"[^0-9.]", "", str(wheel))          # S438: as written
        if wheel_decimal(target) is None:
            return None, None
    except ValueError:
        return None, None
    for table_page in results.get("Table Highlights") or []:
        for item in table_page.get("items", []):
            odometer = re.sub(r"[^0-9.]", "", str(cmp_table_cell(item, r"odometer") or ""))
            try:
                if wheel_same(odometer, target):                     # S438: exactly
                    return table_page, item
            except ValueError:
                continue
    return None, None


def page1_bullet_count(results):
    """S89: how many bullets page 1 has - the count most page-1 value lines have (2 or
    more lines agreeing), else None."""
    counts = [len((results.get(f) or {}).get("items") or [])
              for f in ("Latitude", "Longitude", "Wheel Count", "Mile Post/Station")]
    counts = [n for n in counts if n]
    if not counts:
        return None
    (top, votes), *rest = Counter(counts).most_common()
    return top if top >= 2 and votes >= 2 and (not rest or rest[0][1] < votes) else None


# S478: every Dig Packet's text pages (its printed dig sheet) as soon as they are read - while it waits (S353) or
# when it is read: {PDF path: (file name, text pages)}. A packet's page 1 lists every dig of its family, but its dig
# sheet is only its own dig's - the other bullets' dig sheets are in the family's other packets of the same drop.
FAMILY_DIG_SHEETS = {}


def remember_dig_sheets(path, pages):
    """S478: a packet's text pages, for the Notes check of the other packets in the drop."""
    if path and pages:
        FAMILY_DIG_SHEETS[os.path.abspath(path)] = (os.path.basename(path), list(pages))


def notes_anomaly_from_dig_sheet(results, wheel, path=None):
    """S467: what the packet's printed dig sheet says about this wheel count - (where, event, clock, depth,
    int/ext) or None. ROSEN sheet: its 'log dist. : 252181.47 ft  o'clock : 12:51  event : ...  depth : 22 %'
    line; ENTEGRA sheet: the target's Feature Type / Depth(%) / Orientation under 'Target Anomaly Details'.
    S478: when its own packet has none, the dig sheet of another packet of the same drop (matched by the same
    wheel count as written)."""
    found = dig_sheet_anomaly(results.get("Text Pages") or [], wheel)
    if found is not None:
        return found
    own = os.path.abspath(path) if path else None
    for other, (name, pages) in list(FAMILY_DIG_SHEETS.items()):
        if other != own:
            found = dig_sheet_anomaly(pages, wheel)
            if found is not None:
                return (f"{name}'s {found[0]} (same drop - S478)",) + found[1:]
    return None


def dig_sheet_anomaly(pages, wheel):
    """S467/S478: one packet's text pages -> its dig sheet's (where, event, clock, depth, int/ext) for this wheel
    count, or None."""
    for page in pages:
        text = page.get("text") or ""
        rosen = re.search(r"log\s*dist\.?\s*:\s*([0-9]+\.[0-9]+)", text, re.IGNORECASE)
        if rosen and wheel_same(rosen.group(1), wheel):
            event = re.search(r"event\s*:\s*(.+?)\s+(?:internal|depth|length|width|latitude)\s*:", text,
                              re.IGNORECASE)
            clock = re.search(r"o.?clock\s*:\s*(\d{1,2}:\d{2})", text, re.IGNORECASE)
            depth = re.search(r"depth\s*:\s*([0-9.]+)\s*%", text, re.IGNORECASE)
            return (f"dig sheet page {page.get('page')}", event.group(1) if event else "",
                    clock.group(1) if clock else "", depth.group(1) if depth else "", "")
        if page.get("wheel") and wheel_same(page["wheel"], wheel):
            values = {v["label"].strip().lower(): v["text"] for v in page.get("values") or [] if v.get("label")}
            event = values.get("feature type", "")
            clock = re.search(r"\d{1,2}:\d{2}", values.get("orientation", ""))
            depth = re.search(r"[0-9.]+", values.get("depth(%)", values.get("depth (%)", "")))
            int_ext = {"EXTERNAL": "E", "INTERNAL": "I"}.get(event.split(" ")[0].upper() if event else "", "")
            if event or clock:
                return (f"dig sheet page {page.get('page')}", event, clock.group(0) if clock else "",
                        depth.group(0) if depth else "", int_ext)
    return None


def notes_anomaly_from_map_note(results, wheel):
    """S467: the yellow map note of this wheel count - (where, event) or None. The event is the note's
    first line after 'Wheel Count ...' with letters and no digits ('Linear Seam Weld Variation B')."""
    for map_page in results.get("Map Pages") or []:
        for note in map_page.get("notes") or []:
            lines = [line.strip() for line in str(note.get("value") or "").splitlines() if line.strip()]
            for index, line in enumerate(lines):
                found = re.search(r"Wheel\s*Count\s*([0-9]+\.[0-9]+)", line, re.IGNORECASE)
                if found and wheel_same(found.group(1), wheel):
                    event = next((l for l in lines[index + 1:] if re.search(r"[A-Za-z]{3}", l)
                                  and not re.search(r"\d", l)
                                  and not re.match(r"(Lat|Long|Mile)", l, re.IGNORECASE)), "")
                    if event:
                        return f"map page {map_page.get('page_number')} note", event
    return None


def notes_bullets_tidied(results):
    """S483: a page-1 Notes line's bullet written as page 1 writes its bullets - '(A)' - when it was read as 'A)',
    'A.', '(A.', 'B.)' or 'C ' before the depth, or twice ('(B) B.)2B%', '(A) (A)22%'). Only letters that page 1
    uses as bullets (its Wheel Count / Latitude / Longitude / Mile Post lines) are taken; the rest of the line
    stays as read."""
    notes = results.get("Notes") or {}
    if not notes.get("value"):
        return
    letters = {str(item.get("marker") or "").upper() for field in ("Wheel Count", "Latitude", "Longitude",
                                                                   "Mile Post/Station")
               for item in (results.get(field) or {}).get("items") or [] if item.get("marker")}
    letters = {letter for letter in letters if re.fullmatch(r"[A-Z]", letter)}
    if not letters:
        return
    new_lines, changed = [], []
    for line in notes["value"].split("\n"):
        new = line
        twice = re.match(r"^\(\s*([A-Z])\s*\)\s*\(?\s*\1\s*[).:,]{1,2}\s*", line)
        loose = re.match(r"^\(?\s*([A-Z])\s*[).:,]{1,2}\s*(?=\S)", line)
        spaced = re.match(r"^([A-Z])\s+(?=\d)", line)
        if twice:
            new = f"({twice.group(1)}) " + line[twice.end():]
        elif re.match(r"^\([A-Z]\)\S", line) and line[1] in letters:
            new = line[:3] + " " + line[3:]                         # '(A)22%' -> '(A) 22%'
        elif loose and loose.group(1) in letters and not line.startswith(f"({loose.group(1)}) "):
            new = f"({loose.group(1)}) " + line[loose.end():]
        elif spaced and spaced.group(1) in letters:
            new = f"({spaced.group(1)}) " + line[spaced.end():]
        if new != line:
            changed.append((line, new))
        new_lines.append(new)
    if not changed:
        return
    for old, new in changed:
        print(f"NOTES BULLET: '{old}' -> '{new}' (page 1 uses the bullet(s) {', '.join(sorted(letters))}) (S483)")
    notes["value"] = "\n".join(new_lines)
    for record, text in zip([l for l in notes.get("lines") or [] if l.get("text")], new_lines):
        record["text"] = text
    notes["display_value"] = (notes.get("label") or "Notes") + "\n" + notes["value"]


def notes_printed_for(results, path, wheel):
    """S467/S484: what the packet prints for this wheel count - its ILI table row (Depth [%], O'clock, Int/Ext,
    Event), else its dig sheet (S478: also another packet's of the same drop) and its yellow map note:
    {'source', 'where', 'event', 'clock', 'depth', 'int_ext'} or None."""
    table_page, row = table_row_for_wheel_count(results, wheel)
    if row is not None:
        return {"source": "TABLE", "where": f"table page {table_page.get('page_number')} {row.get('title')}",
                "depth": cmp_table_cell(row, r"depth%"), "clock": cmp_table_cell(row, r"oclock"),
                "int_ext": (cmp_table_cell(row, r"intext") or "").strip().upper()[:1],
                "event": cmp_table_cell(row, r"event$") or ""}
    # S467: not in the ILI table (a validation dig, below reporting specifications) - the dig sheet and the map
    # note say what it is
    sheet = notes_anomaly_from_dig_sheet(results, wheel, path)
    note = notes_anomaly_from_map_note(results, wheel)
    if sheet is None and note is None:
        return None
    events = [e for e in ((sheet or ("", ""))[1], (note or ("", ""))[1]) if e]
    clock, depth, int_ext = (sheet[2], sheet[3], sheet[4]) if sheet else ("", "", "")
    return {"source": "DIG SHEET / MAP NOTE",
            "where": " + ".join(w for w in ((sheet or ("",))[0], (note or ("",))[0]) if w),
            "event": " / ".join(dict.fromkeys(events).keys() if len({e.lower() for e in events}) > 1 else events[:1]),
            "clock": clock, "depth": depth, "int_ext": int_ext}


def notes_line_letter(line, wheels):
    """S484: the bullet letter a Notes line starts with ('(A)' - S483: or 'A)', 'A.', 'A ' before a number), ''
    for the only anomaly of a packet without bullets, None when it cannot be told."""
    bullet = re.match(r"^\(?\s*([A-Z])\s*(?:\)|[.:,]{1,2}\)?|\s+(?=\d))", line)
    if bullet and bullet.group(1) in wheels:
        return bullet.group(1)
    return "" if len(wheels) == 1 else None


def notes_line_fixed(tokens, printed):
    """S467/S484: a Notes line's words put right from what is printed for its anomaly (see notes_vs_table_rows):
    (tokens, fixes, what still differs, whether there was anything printed to compare)."""
    event, clock, depth, int_ext = printed["event"] or "", printed["clock"], printed["depth"], printed["int_ext"]
    expected_words = list(dict.fromkeys(
        ([{"E": "EXTERNAL", "I": "INTERNAL"}[int_ext]] if int_ext in ("E", "I") else [])
        + re.findall(r"[A-Za-z]+", event.upper())))
    tokens = list(tokens)
    fixes = []
    # percentage with stray marks after the %
    for index, token in enumerate(tokens):
        found = re.match(r"^(\d+(?:\.\d+)?)%(.+)$", token)
        if found and depth not in (None, "") and cmp_same_number(found.group(1), re.sub(r"[^0-9.]", "", str(depth))):
            tokens[index] = found.group(1) + "%"
            fixes.append(f"{token} -> {tokens[index]} (Depth [%] {depth})")
    # missing words read as look-alike digits
    words_in_line = {t.upper() for t in tokens}
    for word in expected_words:
        if word in words_in_line:
            continue
        for index, token in enumerate(tokens):
            fixed = note_word_lookalike(token, word)
            if fixed.endswith(" @") and "@" in tokens:
                fixed = ""
            if fixed:
                tokens[index] = fixed
                fixes.append(f"{token} -> {fixed} ({'Int/Ext ' + int_ext if word in ('EXTERNAL', 'INTERNAL') else 'Event ' + event})")
                break
    # S467: missing words read as a look-alike WORD ('LINEAL' for LINEAR, 'VACATION' for VARIATION): a
    # letters-only read, not one of the expected words itself, same first letter, at most one letter
    # longer or shorter and mostly the same letters - the closest one takes the printed word
    words_in_line = {t.upper() for t in tokens}
    expected_set = set(expected_words)
    for word in expected_words:
        if word in words_in_line or len(word) < 4:
            continue
        best, best_score = None, NOTE_WORD_MATCH_MIN
        for index, token in enumerate(tokens):
            read = token.upper()
            if not re.fullmatch(r"[A-Z]+", read) or read in expected_set or read[0] != word[0] \
                    or abs(len(read) - len(word)) > 1:
                continue
            score = SequenceMatcher(None, read, word).ratio()
            if score >= best_score:
                best, best_score = index, score
        if best is not None:
            read = tokens[best].upper()
            nxt = tokens[best + 1] if best + 1 < len(tokens) else ""
            # S479: the word with the @ stuck on its end, right before the time ('LOSSC 00124') - the extra
            # mark is the @, not a letter to throw away
            fixed = (word + " @" if len(read) == len(word) + 1 and read.startswith(word)
                     and read[-1] in AT_SIGN_LOOKALIKES and "@" not in "".join(tokens)
                     and re.fullmatch(r"[0-9Il.:]{3,5}", nxt) else word)
            fixes.append(f"{tokens[best]} -> {fixed} (Event {event})")
            tokens[best] = fixed
            words_in_line = {t.upper() for t in tokens}
    # time with the colon read as a digit
    clock_digits = re.sub(r"[^0-9]", "", str(clock or ""))
    has_time = any(re.fullmatch(r"\d{1,2}:\d{2}", t) for t in tokens)
    if clock_digits and not has_time:
        for index in range(len(tokens) - 1, -1, -1):
            token = tokens[index]
            if not re.fullmatch(r"[0-9IlOo.:]{4,5}", token) or not re.search(r"\d", token):
                continue
            digits = token if len(token) == 4 else (token[:2] + token[3:] if token[2] in "1Il.:" else None)
            # S467: a one-digit hour with its colon read as a 1 ('7124' for 7:24)
            short = token[0] + token[2:] if len(token) == 4 and token[1] in "1Il.:" else None
            # S484: and an O read for a 0 ('1IO0' for 1:00)
            as_digits = lambda t: t.replace("I", "1").replace("l", "1").replace("O", "0").replace("o", "0")
            digits = as_digits(digits) if digits else None
            short = as_digits(short) if short else None
            if digits and digits == clock_digits.zfill(4):
                tokens[index] = digits[:2] + ":" + digits[2:]     # S467: as written, the colon put back
            elif short and short == clock_digits.lstrip("0"):
                tokens[index] = short[0] + ":" + short[1:]        # S467: '7124' -> '7:24' as written
            else:
                continue
            fixes.append(f"{token} -> {tokens[index]} (O'clock {clock.strip()})")
            break
    # S467: the @ before the time read as a letter ('B E 12:51' -> 'B @ 12:51'): one look-alike mark
    # right before the time, when the line has no @ yet
    times = [index for index, t in enumerate(tokens) if re.fullmatch(r"\d{1,2}:\d{2}", t)]
    if times and times[-1] > 0 and "@" not in "".join(tokens):
        mark = tokens[times[-1] - 1]
        event_words = re.findall(r"[A-Za-z]+", event.upper())
        last = event_words[-1] if event_words else ""
        before = tokens[times[-1] - 2].upper() if times[-1] > 1 else ""
        if len(mark) == 1 and mark.upper() in AT_SIGN_LOOKALIKES:
            tokens[times[-1] - 1] = "@"
            fixes.append(f"{mark} -> @ (before the time)")
        elif last and before == last and len(mark) == len(last) + 1 and mark.upper().startswith(last) \
                and mark[-1].upper() in AT_SIGN_LOOKALIKES:
            # S484: the event's last word is already there ('B BC 1:00') - the B read again with the @ is the @
            tokens[times[-1] - 1] = "@"
            fixes.append(f"{mark} -> @ (the event's last word '{last}' is already before it; the @ before the time)")
        elif last and len(mark) == len(last) + 1 and mark.upper().startswith(last) \
                and mark[-1].upper() in AT_SIGN_LOOKALIKES:
            # S479: the event's last word and the @ read as one word ('BC 12:51' -> 'B @ 12:51', 'LOSSC' ->
            # 'LOSS @') - the printed event confirms the word, so only the look-alike mark becomes the @
            tokens[times[-1] - 1] = mark[:-1] + " @"
            fixes.append(f"{mark} -> {mark[:-1]} @ (the event's last word '{last}' and the @ before the time)")
    # S476: what the line still does not show of what is printed - so 'agrees' is only said when every printed
    # word, the o'clock and the depth are in it, and a line with nothing printed to compare is said so
    words_in_line = {t.upper() for t in tokens}
    differs = [f"word {w}" for w in expected_words if w not in words_in_line]
    line_times = [t for t in tokens if re.fullmatch(r"\d{1,2}:\d{2}", t)]
    if clock_digits and not any(t.replace(":", "").lstrip("0") == clock_digits.lstrip("0") for t in line_times):
        differs.append(f"O'clock {clock.strip()}")
    depth_text = re.sub(r"[^0-9.]", "", str(depth or ""))
    line_depths = [m.group(1) for m in (re.match(r"^\(?[A-Z]?\)?(\d+(?:\.\d+)?)%", t) for t in tokens) if m]
    if depth_text and not any(cmp_same_number(d, depth_text) for d in line_depths):
        differs.append(f"Depth {depth_text}%")
    compared = bool(expected_words or clock_digits or depth_text)
    return tokens, fixes, differs, compared


def notes_vs_table_rows(results, path=None):
    """Each page-1 Notes line checked against what the packet prints for its wheel count: the ILI table
    row (Depth [%], O'clock, Int/Ext, Event); S467: when the anomaly has no table row, its dig sheet
    (event, o'clock, depth) and its yellow map note (event) instead. Look-alike words, a stray mark
    after the %, the @ and a colon read as a digit are put right from them (notes_line_fixed)."""
    notes = results.get("Notes") or {}
    wheels = {}
    for item in (results.get("Wheel Count") or {}).get("items") or []:
        wheels[item.get("marker") or ""] = item.get("value")
    if not notes.get("value") or not wheels:
        return
    corrections = []
    new_lines = []
    for line in notes["value"].split("\n"):
        letter = notes_line_letter(line, wheels)
        if letter is None or "%" not in line:
            new_lines.append(line)
            continue
        wheel = wheels.get(letter)
        printed = notes_printed_for(results, path, wheel)
        if printed is None:
            new_lines.append(line)
            continue
        source, where, clock = printed["source"], printed["where"], printed["clock"]
        tokens, fixes, differs, compared = notes_line_fixed(line.split(" "), printed)
        new_line = " ".join(tokens)
        new_lines.append(new_line)
        still = (f" - still differs from it: {', '.join(differs)} (no safe fix - left as read for Verify)"
                 if differs else "")
        if fixes:
            text = f"({letter}) " if letter else ""
            corrections.append(f"Notes {text.strip() or 'line'}: " + "; ".join(fixes) + f" - from {where} "
                               f"(Wheel Count {wheel})")
            print(f"NOTES vs {source}: '{line}' -> '{new_line}' CORRECTED ({'; '.join(fixes)}; {where}, "
                  f"Wheel Count {wheel})" + still + (" (S467)" if source != "TABLE" else ""))
        elif not compared:
            print(f"NOTES vs {source}: '{line}' - {where} prints no event, o'clock or depth for Wheel Count {wheel} "
                  f"- nothing to check it against (S476)")
        elif differs:
            print(f"NOTES vs {source}: '{line}' does not match {where} (Wheel Count {wheel}) on: {', '.join(differs)} "
                  f"- no safe fix, left as read for Verify (S476)")
        else:
            print(f"NOTES vs {source}: '{line}' agrees with {where} (Wheel Count {wheel}) - nothing to fix")
    if corrections:
        notes["value"] = "\n".join(new_lines)
        for record, text in zip([l for l in notes.get("lines") or [] if l.get("text")], new_lines):
            record["text"] = text
        notes["display_value"] = (notes.get("label") or "Notes") + "\n" + notes["value"]
        notes["corrections"] = corrections


# S108: letters and digits that handwriting reads mix up. A read is compared with what
# it should show through these, never character for character only: '18.77+1938' is
# '1' + bullet B (read as 8) + 77+1938.
LOOKALIKE_CLASSES = {
    "0": "0OoDQ", "1": "1Il|i!", "2": "2Zz", "3": "3", "4": "4A", "5": "5Ss", "6": "6Gb", "7": "7Tt",
    "8": "8B", "9": "9gq", "+": "+tT", ".": ".,", "-": "-~_",
    "A": "A4④Ⓐⓐ", "B": "B8⑧Ⓑⓑ", "C": "C(⑥Ⓒ", "D": "D0Ⓓ", "E": "E3", "G": "G6", "I": "I1l|", "O": "O0", "S": "S5",
    "T": "T7", "Z": "Z2",
}


def lookalike_pattern(text):
    """A regex matching `text` with every character allowed to be read as one of its
    look-alikes (B/8, A/4, S/5, O/0, I/1, Z/2, G/6, T/7, +/t ...)."""
    parts = []
    for character in str(text):
        allowed = LOOKALIKE_CLASSES.get(character.upper() if character.isalpha() else character, character)
        parts.append("[" + "".join(re.escape(c) for c in sorted(set(allowed + character))) + "]")
    return "".join(parts)


class _Span:
    """A found value's place in a read (what re.Match gives: start() / end())."""
    def __init__(self, start, end):
        self._start, self._end = start, end

    def start(self):
        return self._start

    def end(self):
        return self._end


def _same_character(got, want):
    """Look-alike-aware: is `got` (as read) the character `want` (as it should be)?"""
    if got == want:
        return True
    allowed = LOOKALIKE_CLASSES.get(want.upper() if want.isalpha() else want, want) + want
    return got in allowed or got.upper() in allowed.upper()


def _one_edit_apart(window, value):
    """S145: True when `window` is `value` with at most ONE character wrong, missing or
    extra (look-alikes count as the same)."""
    a, b = window, value
    if abs(len(a) - len(b)) > 1:
        return False
    i = j = edits = 0
    while i < len(a) and j < len(b):
        if _same_character(a[i], b[j]):
            i += 1
            j += 1
            continue
        edits += 1
        if edits > 1:
            return False
        if len(a) == len(b):
            i += 1
            j += 1
        elif len(a) < len(b):
            j += 1                     # a character of the value is missing in the read
        else:
            i += 1                     # an extra character in the read
    return edits + (len(a) - i) + (len(b) - j) <= 1


def fuzzy_value_match(read, value):
    """S109 + S145: the value in the read with at most ONE character wrong (e.g. '72+1938'
    for 77+1938), missing ('32.3107154' for 32.31071514) or extra; look-alikes count as
    the same. The window closest to the value's length wins; None when there is none."""
    read, value = str(read), str(value)
    best = None
    for length in (len(value), len(value) - 1, len(value) + 1):
        if length < 1:
            continue
        for start in range(0, len(read) - length + 1):
            window = read[start:start + length]
            if _one_edit_apart(window, value):
                key = (abs(length - len(value)), start)
                if best is None or key < best[0]:
                    best = (key, start, length)
    return _Span(best[1], best[1] + best[2]) if best else None


def value_end_fits(read, value, letter):
    """S145: the read ENDS the way the value ends - its last two characters (look-alikes
    allowed), nothing but marks after them - and, without its own bullet in front, it is
    within one character of the value's length. That is enough to say the snip ends where
    the value ends and holds about all of it (a misread in the middle does not matter for
    where to cut). Returns the value's span in the read, or None."""
    read, value = str(read or ""), str(value or "")
    if len(value) < 6:
        return None
    junk = "()[]{}.:;,'\"| "
    end = re.search(lookalike_pattern(value[-2:]) + r"[" + re.escape(junk) + r"]*$", read)
    if not end:
        return None
    letter = str(letter or "").upper()
    own = "".join(sorted(set(LOOKALIKE_CLASSES.get(letter, letter) + letter))) if letter else ""
    lead = re.match(r"^[" + re.escape(junk) + r"]*" + (r"(?:[(\[{]?[" + re.escape(own) + r"][)\]}1Il|.:]{0,2})?"
                                                        if own else ""), read)
    start = lead.end() if lead else 0
    body = read[start:end.start() + 2]
    if abs(len(re.sub(r"\s", "", body)) - len(value)) <= 1:
        return _Span(start, end.start() + 2)
    return None


def snip_layout(read, value, letter):
    """How a snip's read lines up with what it should show - its own bullet, then its
    value - with look-alikes allowed everywhere. Returns a dict:
      found       the whole value is in the read
      head, tail  its first / last 3 characters are (at the start after the bullet /
                  at the very end)
      extra_before  something besides its own bullet before the value (another
                  value's digit, the previous bullet)
      extra_after   something after the value (the next bullet, digits)
      bullet      its own bullet (letter or the digit it is read as) is there"""
    read = str(read or "")
    value = re.sub(r"\s", "", str(value or ""))
    letter = str(letter or "").upper()
    own = set(LOOKALIKE_CLASSES.get(letter, letter) + letter) if letter else set()
    junk = "()[]{}.:;,'\"| "
    match = re.search(lookalike_pattern(value), read) if value else None
    if match is None and len(value) >= 6:
        match = fuzzy_value_match(read, value)        # S109/S145: one character wrong, missing or extra
    if match is None and len(value) >= 6:
        match = value_end_fits(read, value, letter)   # S145: ends like the value, about its length
    out = {"found": bool(match), "head": False, "tail": False, "extra_before": False,
           "extra_after": False, "bullet": False}
    if match:
        before, after = read[:match.start()], read[match.end():]
    else:
        head = re.search(lookalike_pattern(value[:3]), read) if len(value) >= 3 else None
        tail_match = None
        for m in re.finditer(lookalike_pattern(value[-3:]), read) if len(value) >= 3 else []:
            tail_match = m
        out["head"] = bool(head)
        out["tail"] = bool(tail_match and read[tail_match.end():].strip(junk) == "")
        before = read[:head.start()] if head else ""
        after = read[tail_match.end():] if tail_match else ""
    core = before.strip(junk)
    # S109: the circle round a bullet is read as '(' before the letter and ')', '1',
    # 'I', 'l' or '|' after it - those belong to the bullet, they are not extra ink
    bullet_mark = (re.search(r"[({\[]?[" + re.escape("".join(sorted(own))) + r"][)\]}1Il|]{0,2}$", core)
                   if core and own else None)
    if bullet_mark:
        out["bullet"] = True
        core = core[:bullet_mark.start()].strip(junk)
    elif not letter:
        out["bullet"] = True
    out["extra_before"] = bool(re.search(r"[0-9A-Za-z]", core))
    out["extra_after"] = bool(re.search(r"[0-9A-Za-z]", after.strip(junk)))
    if match:
        out["head"] = out["tail"] = True
    return out


def layout_quality(layout):
    """Better snips sort higher: whole value, then its ends, then nothing extra, then the bullet."""
    return (layout["found"], layout["head"] + layout["tail"], not layout["extra_before"],
            not layout["extra_after"], layout["bullet"])


def fit_snips_to_values(results):
    """S97 + S105/S108: after the map / table corrections every page-1 value is as
    sure as it gets, and each snip is made to hold exactly its own bullet + value. Every
    read is compared through look-alikes (B/8, A/4, S/5, 0/O, 1/I, 7/T ...), so '18.77'
    is seen as '1' + bullet B + '77', not as a value starting with 18.
      pass 1, every snip: give back what is not its own - shrink from the right while
              something follows its value (the next bullet / digits), from the left
              while something besides its own bullet comes before it (the previous
              value's last digit)
      pass 2, every snip: take what is missing - grow right while its value's end is not
              there, left while its start is not, then left in small steps while that
              brings in its own bullet and nothing else
    One step is about half a character; never past the label or the neighbouring
    snips; each step is read again. Kept only when the snip lines up better than
    before. A snip that still does not hold its value gets a warning."""
    for field in ("Latitude", "Longitude", "Wheel Count", "Mile Post/Station"):
        result = results.get(field) or {}
        items = result.get("items") or []
        geometry = result.get("page_geometry") or {}
        if len(items) < 2 or not geometry or any(not item.get("piece_box") for item in items):
            continue
        page = geometry["page_image"]
        height = geometry.get("label_height", 40)
        step = max(6, int(height * 0.6))
        fine = max(3, step // 2)
        state = []
        for item in items:
            box = tuple(item["piece_box"])
            read = snip_read_compact(remove_horizontal_lines(page.crop(box)), field)
            layout = snip_layout(read, item["value"], item.get("marker"))
            state.append({"box": box, "read": read, "layout": layout, "start": (box, read, layout_quality(layout)),
                          "tries": []})

        def look(index, box):
            entry, item = state[index], items[index]
            read = snip_read_compact(remove_horizontal_lines(page.crop(box)), field)
            layout = snip_layout(read, item["value"], item.get("marker"))
            entry["tries"].append({"box": box, "read": read, "score": sum(map(int, layout_quality(layout))),
                                   "kept": False})
            return read, layout

        def accept(index, box, read, layout):
            state[index].update({"box": box, "read": read, "layout": layout})

        def limits(index):
            low = state[index - 1]["box"][2] if index > 0 else label_limit_left(
                page, state[0]["box"], max(0, state[0]["box"][0] - int(height * 6)))
            high = state[index + 1]["box"][0] if index + 1 < len(items) else min(page.width, state[index]["box"][2]
                                                                                 + int(height * 6))
            return window_edge_limits(items, index, geometry, low, high)                # S112

        # pass 1: give back what is not its own
        for index in range(len(items)):
            entry = state[index]
            for _ in range(12):
                box = entry["box"]
                if not entry["layout"]["extra_after"] or box[2] - fine <= box[0] + 2 * step:
                    break
                candidate = (box[0], box[1], box[2] - fine, box[3])
                read, layout = look(index, candidate)
                if layout["found"] or layout["head"] or not entry["layout"]["found"]:
                    accept(index, candidate, read, layout)
                else:
                    break                                      # would cut into its own value
            for _ in range(12):
                box = entry["box"]
                if not entry["layout"]["extra_before"] or box[0] + fine >= box[2] - 2 * step:
                    break
                candidate = (box[0] + fine, box[1], box[2], box[3])
                read, layout = look(index, candidate)
                if layout["found"] or layout["tail"] or not entry["layout"]["found"]:
                    accept(index, candidate, read, layout)
                else:
                    break
        # pass 2: take what is missing
        for index in range(len(items)):
            entry = state[index]
            low_x, high_x = limits(index)
            for _ in range(16):
                box = entry["box"]
                if entry["layout"]["found"] or entry["layout"]["tail"] or box[2] + fine > high_x:
                    break
                candidate = (box[0], box[1], box[2] + fine, box[3])
                read, layout = look(index, candidate)
                if layout["extra_after"] and not layout["found"]:
                    break
                accept(index, candidate, read, layout)
            for _ in range(16):
                box = entry["box"]
                if entry["layout"]["found"] or entry["layout"]["head"] or box[0] - fine < low_x:
                    break
                candidate = (box[0] - fine, box[1], box[2], box[3])
                read, layout = look(index, candidate)
                if layout["extra_before"]:
                    break
                accept(index, candidate, read, layout)
            for _ in range(8):                                  # take in its own bullet, nothing else
                box = entry["box"]
                if entry["layout"]["bullet"] or box[0] - fine < low_x:
                    break
                candidate = (box[0] - fine, box[1], box[2], box[3])
                read, layout = look(index, candidate)
                if layout["extra_before"] or layout_quality(layout) < layout_quality(entry["layout"]):
                    break
                accept(index, candidate, read, layout)
        # keep what lines up better than before
        for index, item in enumerate(items):
            entry = state[index]
            if not entry["tries"]:
                continue
            quality = layout_quality(entry["layout"])
            first_read = entry["start"][1]
            if quality > entry["start"][2]:
                for t in entry["tries"]:
                    t["kept"] = t["box"] == entry["box"]
                for t in item.get("piece_tries") or []:
                    t["kept"] = False
                item.setdefault("piece_tries", []).extend(entry["tries"])
                item["piece_box"] = entry["box"]
                item["image"] = page.crop(entry["box"])
                verdict = ("holds its bullet and value" if entry["layout"]["found"] and entry["layout"]["bullet"]
                           else "holds its value" if entry["layout"]["found"] else "better, value still not whole")
                print(f"SNIP FIT {field} ({item.get('marker')}) {item['value']}: '{first_read}' -> '{entry['read']}' "
                      f"({len(entry['tries'])} reads, look-alikes like B/8 counted as the same) - {verdict}")
            else:
                print(f"SNIP FIT {field} ({item.get('marker')}) {item['value']}: '{first_read}' - "
                      f"{len(entry['tries'])} reads did not line up better, snip kept")
            if not entry["layout"]["found"] and not (entry["layout"]["head"] or entry["layout"]["tail"]):
                warning = (f"⚠ {field} ({item.get('marker')}): the snip could not be made to read "
                           f"{item['value']} - check the picture")
                result["warning"] = f"{result['warning']}  {warning}" if result.get("warning") else warning


# ============================================================
# S102: TEXT FIRST - the packet's printed text is read before its handwriting
# ============================================================
# The map notes, the table rows and the dig sheet are printed (or PDF text), read
# quickly and reliably. They are read FIRST, so the handwriting reads know what to
# look for: which Wheel Counts, coordinates and stations exist in this packet, and
# what each anomaly row says (depth, o'clock, internal/external, event). A handwriting
# read that matches one of them can be confirmed with a few more reads instead of the
# whole slow path; one that does not is read the normal way.
TEXT_FIRST = {"known": {}, "anomalies": [], "letters": {}, "bullets": None}
GUIDED_STEP_FRACTION = 0.6        # one guided widening step = 0.6 x label height (about half a character)


def _note_fields(text):
    text = str(text or "")
    grab = lambda pattern: (re.search(pattern, text, re.IGNORECASE) or [None, None])[1]
    return {"Wheel Count": grab(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)"),
            "Latitude": grab(r"Lat(?:itude|\.)\s*(-?[0-9]+\.[0-9]+)"),
            "Longitude": grab(r"Long(?:itude|\.)\s*(-?[0-9]+\.[0-9]+)"),
            "Mile Post/Station": grab(r"(?:Mile|Station|Sta\.?)\s*([0-9]+\+[0-9.]+)")}


def build_text_first(results):
    """S102: what the printed text of this packet says, kept for the handwriting reads."""
    known = {field: [] for field in ("Wheel Count", "Latitude", "Longitude", "Mile Post/Station")}
    for map_page in results.get("Map Pages") or []:
        for note in map_page.get("notes", []):
            for field, value in _note_fields(note.get("value")).items():
                if value and value not in known[field]:
                    known[field].append(value)
    anomalies = []
    for table_page in results.get("Table Highlights") or []:
        for item in table_page.get("items", []):
            odometer = re.sub(r"[^0-9.]", "", str(cmp_table_cell(item, r"odometer") or ""))
            if odometer and odometer not in known["Wheel Count"]:
                known["Wheel Count"].append(odometer)
            for field, pattern in (("Latitude", r"latitude"), ("Longitude", r"longitude")):
                value = str(cmp_table_cell(item, pattern) or "").strip()
                if re.fullmatch(r"-?\d+\.\d+", value) and value not in known[field]:
                    known[field].append(value)
            depth = cmp_table_cell(item, r"depth%")
            if odometer and depth not in (None, ""):
                anomalies.append({"wheel": odometer, "depth": str(depth).strip(),
                                  "clock": str(cmp_table_cell(item, r"oclock") or "").strip(),
                                  "int_ext": (cmp_table_cell(item, r"intext") or "").strip().upper()[:1],
                                  "event": str(cmp_table_cell(item, r"event$") or "").strip(),
                                  "where": f"table page {table_page.get('page_number')} {item.get('title')}"})
    TEXT_FIRST.update({"known": known, "anomalies": anomalies, "letters": {}, "bullets": None})
    print(f"TEXT FIRST: printed values known before the handwriting is read - "
          + ", ".join(f"{len(v)} {k}" for k, v in known.items()) + f", {len(anomalies)} anomaly row(s)")


def _closeness(read, known_value):
    """How close a handwriting read is to a printed value: 0 = same, 1-2 = a digit or
    two dropped / added / swapped, None = not close."""
    a, b = re.sub(r"\s", "", str(read)), re.sub(r"\s", "", str(known_value))
    if a == b:
        return 0
    if digits_dropped_from(a, b) or digits_dropped_from(b, a):
        return abs(len(a) - len(b))
    if len(a) == len(b):
        differ = sum(1 for x, y in zip(a, b) if x != y)
        return differ if differ <= 2 else None
    return None


def guided_page1_reread(results):
    """S100: a page-1 value that is not one of the packet's printed values but close to
    exactly one of them (a digit dropped, added or misread) is read again around its
    snip - as cut, then wider to the left, wider to the right, both - and when one of
    those reads holds the printed value, that value is used (blue note). Reads that do
    not show it leave the value as it was read (the map check at the end still runs)."""
    known = TEXT_FIRST.get("known") or {}
    for field in ("Latitude", "Longitude", "Wheel Count", "Mile Post/Station"):
        result = results.get(field) or {}
        items = result.get("items") or []
        values = known.get(field) or []
        geometry = result.get("page_geometry") or {}
        if not items or not values or not geometry:
            continue
        page = geometry["page_image"]
        height = geometry.get("label_height", 40)
        step = max(6, int(height * GUIDED_STEP_FRACTION))
        for index, item in enumerate(items):
            read_value = str(item.get("value") or "")
            if not read_value or read_value in values:
                continue
            close = [(c, v) for v in values for c in [_closeness(read_value, v)] if c is not None and c > 0]
            if not close:
                # S113: the snip itself may read a printed value that the read value is a
                # near variant of (e.g. -93.96703609 read, -93.9670368961 voted)
                adopt_printed_value_read_in_snip(result, field, item, index, items, values, page)
                continue
            best = min(c for c, _v in close)
            candidates = [v for c, v in close if c == best]
            if len(candidates) != 1:
                print(f"GUIDED RE-READ {field} {read_value}: close to {len(candidates)} printed values - left as read")
                continue
            target = candidates[0]
            box = item.get("piece_box") or (geometry.get("ocr_offset_x", 0), geometry["line_box"][1],
                                             geometry.get("ocr_offset_x", 0) + (result.get("ocr_image").width
                                                                                if result.get("ocr_image") else 0),
                                             geometry["line_box"][3])
            if box[2] - box[0] < 10:
                continue
            low_x = items[index - 1]["piece_box"][2] if index > 0 and items[index - 1].get("piece_box") else 0
            high_x = (items[index + 1]["piece_box"][0] if index + 1 < len(items) and items[index + 1].get("piece_box")
                      else page.width)
            squeeze = lambda t: re.sub(r"[^0-9+.-]", "", t)
            tries, found = [], None
            for left, right, label in ((0, 0, "as cut"), (1, 0, "1 step wider left"), (2, 0, "2 steps wider left"),
                                       (0, 1, "1 step wider right"), (1, 1, "1 step wider both sides"),
                                       (3, 0, "3 steps wider left")):
                candidate = (max(low_x, box[0] - left * step), box[1], min(high_x, box[2] + right * step), box[3])
                read = snip_read_compact(remove_horizontal_lines(page.crop(candidate)), field)
                tries.append(f"{label}: '{read}'")
                if squeeze(target) and (re.search(lookalike_pattern(target), re.sub(r"\s", "", read))
                                         or fuzzy_value_match(re.sub(r"\s", "", read), target)):  # S108/S145
                    found = (label, read)
                    break
            if found:
                item["value"] = target
                if len(items) == 1:
                    result["value"] = target
                note = (f"{field}{' (' + item['marker'] + ')' if item.get('marker') and len(items) > 1 else ''}: "
                        f"read {read_value} - the snip read again {found[0]} shows {target}, a value printed in this "
                        f"packet (map note / table)")
                result["note"] = f"{result['note']}  {note}" if result.get("note") else note
                print(f"GUIDED RE-READ {field} {read_value} -> {target} CONFIRMED ({'; '.join(tries)})")
            else:
                print(f"GUIDED RE-READ {field} {read_value}: printed {target} not seen in {len(tries)} re-reads "
                      f"({'; '.join(tries)}) - left as read")


def adopt_printed_value_read_in_snip(result, field, item, index, items, values, page):
    """S113: when a page-1 value is not printed in this packet but its snip reads one of
    the printed values of the same kind exactly (look-alikes allowed) and that printed
    value is close to the read value (S113 printed_variants), the printed value is used,
    with a blue note."""
    read_value = str(item.get("value") or "")
    near = [v for v in printed_variants(field, read_value)[1:] if v in values]
    box = item.get("piece_box")
    if not near or not box:
        return False
    read = snip_read_compact(remove_horizontal_lines(page.crop(tuple(box))), field)
    compact = re.sub(r"\s", "", read)
    shown = [v for v in near if re.search(lookalike_pattern(v), compact)]
    if not shown:                                # S145: one character wrong, missing or extra
        shown = [v for v in near if fuzzy_value_match(compact, v)]
    if len(shown) != 1:
        print(f"PRINTED VALUE IN SNIP {field} {read_value}: snip reads '{read}' - "
              + ("none of the close printed values " + ", ".join(near) if not shown else
                 "several close printed values") + " - left as read")
        return False
    target = shown[0]
    item["value"] = target
    if len(items) == 1:
        result["value"] = target
    marker = f" ({item['marker']})" if item.get("marker") and len(items) > 1 else ""
    note = (f"{field}{marker}: the votes gave {read_value}, but the snip reads '{read}' - that is {target}, a "
            f"value printed in this packet (map note / table)")
    result["note"] = f"{result['note']}  {note}" if result.get("note") else note
    print(f"PRINTED VALUE IN SNIP {field}{marker}: {read_value} -> {target} CORRECTED (the snip reads '{read}')")
    return True


def remember_page1_letters(results):
    """S102: which anomaly row each page-1 bullet is (its Wheel Count = the row's Odometer)."""
    letters = {}
    for item in (results.get("Wheel Count") or {}).get("items") or []:
        for anomaly in TEXT_FIRST.get("anomalies") or []:
            try:
                if wheel_same(re.sub(r"[^0-9.]", "", str(item.get("value"))), anomaly["wheel"]):   # S438
                    letters[item.get("marker") or ""] = anomaly
            except ValueError:
                continue
    TEXT_FIRST["letters"] = letters
    TEXT_FIRST["bullets"] = page1_bullet_count(results)


def _supported(word, attempts_tokens):
    """A printed word is supported when some whole-line read has it, or something close
    to it (look-alike letters / a letter missing or extra)."""
    from difflib import SequenceMatcher
    word = word.upper()
    for tokens in attempts_tokens:
        for token in tokens:
            if token == word or SequenceMatcher(None, token, word).ratio() >= 0.72:
                return True
    return False


def text_first_note_line(whole_attempts):
    """S102: a Notes line whose whole-line reads already show one of the packet's
    anomaly rows - its depth %, its o'clock time and its words (EXTERNAL / INTERNAL +
    the Event, e.g. METAL LOSS) - is written from that row straight away, in the line's
    own way of writing the numbers; the slow word-by-word reading is skipped. The
    packet's footnote (NOTE: <n> DIGS IN THIS PACKET, n = page 1's bullets) the same
    way. Returns (text, why) or None (then the line is read the normal way)."""
    texts = [str(a.get("text", "")) for a in whole_attempts or []]
    if not texts:
        return None
    tokens = [[t.upper() for t in re.findall(r"[A-Za-z]{2,}", text)] for text in texts]
    numbers = [re.findall(r"\d+(?:[.,][0-9Oo]+)?", text.replace("O", "0").replace("o", "0")) for text in texts]
    flat_numbers = [n.replace(",", ".") for group in numbers for n in group]
    # the footnote
    bullets = TEXT_FIRST.get("bullets")
    if bullets and bullets >= 2 and _supported("NOTE", tokens) and _supported("PACKET", tokens) \
            and _supported("IN", tokens) and sum(1 for group in numbers if str(bullets) in group) >= max(2, len(texts) // 3):
        # dataC (accuracy fix A3): a hand-drawn star is often read as an X glued in front of NOTE ('XNOTE',
        # 'XNDTE') instead of '*' - two or more reads with such a mark before NOTE count as the star too
        star_as_x = sum(1 for text in texts if re.match(r"\s*[xX×✱※]\s*N[O0D]T[E3]", text))
        star = "* " if any("*" in text for text in texts) or star_as_x >= 2 else ""
        stop = "." if sum(1 for text in texts if text.rstrip().endswith(".")) >= max(2, len(texts) // 3) else ""
        return (f"{star}NOTE: {bullets} DIGS IN THIS PACKET{stop}",
                f"the reads show NOTE, IN, PACKET and {bullets}, and page 1 has {bullets} bullets - the packet footnote")
    # an anomaly line
    matches = []
    for letter, anomaly in (TEXT_FIRST.get("letters") or {}).items():
        depth = re.sub(r"[^0-9.]", "", anomaly["depth"])
        clock_digits = re.sub(r"[^0-9]", "", anomaly["clock"])
        if not depth or not clock_digits:
            continue
        depth_seen = [n for n in flat_numbers if cmp_same_number(n, depth)]
        clock_seen = []
        for text in texts:
            for token in re.findall(r"[0-9Oo]{1,2}[:.;][0-9Oo]{2}|[0-9Oo]{4,5}", text):
                digits = re.sub(r"[^0-9]", "", token.replace("O", "0").replace("o", "0"))
                if len(digits) == 5 and token[2] in "1Il.:":
                    digits = digits[:2] + digits[3:]
                if digits.zfill(4) == clock_digits.zfill(4):
                    clock_seen.append(token)
        words = ([{"E": "EXTERNAL", "I": "INTERNAL"}[anomaly["int_ext"]]] if anomaly["int_ext"] in ("E", "I") else []) \
            + re.findall(r"[A-Za-z]+", anomaly["event"].upper())
        if (len(depth_seen) >= max(2, len(texts) // 3) and clock_seen
                and all(_supported(word, tokens) for word in words)):
            matches.append((letter, anomaly, depth_seen, clock_seen, words))
    if len(matches) != 1:
        return None
    letter, anomaly, depth_seen, clock_seen, words = matches[0]
    percent = Counter(n for n in depth_seen if "." in n).most_common(1)
    percent = (percent[0][0] if percent else re.sub(r"[^0-9.]", "", anomaly["depth"])) + "%"
    clean_times = [t.replace("O", "0").replace("o", "0").replace(".", ":").replace(";", ":") for t in clock_seen
                   if re.fullmatch(r"[0-9Oo]{1,2}[:.;][0-9Oo]{2}", t)]
    # the time as the reads write it; a 2-digit hour (00:37) wins over 0:37 when any read shows it
    two_digit = [t for t in clean_times if re.fullmatch(r"\d{2}:\d{2}", t)]
    pool = two_digit or clean_times
    time_text = Counter(pool).most_common(1)[0][0] if pool else anomaly["clock"]
    bullet = f"({letter}) " if letter else ""
    return (f"{bullet}{percent} {' '.join(words)} @ {time_text}",
            f"the reads show {percent}, {time_text} and {', '.join(words)} - {anomaly['where']} (Wheel Count "
            f"{anomaly['wheel']}, bullet {letter or '-'})")


def fix_tokens_from_other_reads(final_text, whole_attempts):
    """S98: what the other reads saw guides the line's own word reads. A token of the
    finished line made of digits / symbols that is a look-alike of a word most
    whole-line reads have (and the line does not) becomes that word - e.g. '10550'
    becomes 'LOSS @' when the whole-line reads say LOSS (one extra mark before the time
    = the @); a percentage with marks glued after the % ('28.0%0') loses them when the
    whole-line reads have the clean form."""
    texts = [str(a.get("text", "")) for a in whole_attempts or []]
    if not texts or not final_text:
        return final_text
    counts = Counter()
    for text in texts:
        for word in set(re.findall(r"[A-Za-z]{3,}", text.upper())):
            counts[word] += 1
    # words at least 2 of the reads have and that are real English words (the look-alike
    # test below is strict: only digits / symbols that spell the word, letter by letter)
    common = [w for w, n in counts.most_common() if n >= 2 and zipf_frequency(w.lower(), "en") >= 3.0]
    tokens = final_text.split(" ")
    present = {t.upper() for t in tokens}
    changed = []
    for index, token in enumerate(tokens):
        cleaned = re.match(r"^(\d+(?:\.\d+)?%)[^\s%]+$", token)
        if cleaned and any(cleaned.group(1) in text.replace("O", "0") for text in texts):
            tokens[index] = cleaned.group(1)
            changed.append(f"{token} -> {tokens[index]}")
            continue
        for word in common:
            if word in present:
                continue
            fixed = note_word_lookalike(token, word)
            if fixed.endswith(" @") and "@" in tokens:
                fixed = ""
            if fixed:
                tokens[index] = fixed
                present.add(word)
                changed.append(f"{token} -> {fixed} ({counts[word]} of {len(texts)} whole-line reads have {word})")
                break
    if changed:
        new_text = " ".join(tokens)
        print(f"OTHER READS GUIDE: '{final_text}' -> '{new_text}' ({'; '.join(changed)})")
        return new_text
    return final_text


def look_for_cut_off_circle(page_image, box, label=""):
    """S99: a Notes line's bullet that its own crop cut off: the line is looked at again
    with its crop widened to the left and downward, and the first mark there is put
    through the same circle test. Returns True (a circle is there), False, or None."""
    x0, y0, x1, y1 = box
    height = max(10, y1 - y0)
    wide = (max(0, int(x0 - 1.0 * height)), max(0, int(y0 - 0.25 * height)),
            min(page_image.width, int(x0 + 2.0 * height)), min(page_image.height, int(y1 + 0.45 * height)))
    crop = page_image.crop(wide)
    mask = _ink_mask(crop)
    if mask is None or np.count_nonzero(mask) < 60:
        return None
    columns = np.flatnonzero((mask > 0).sum(axis=0) >= 2)
    if not len(columns):
        return None
    start, end = int(columns[0]), int(columns[0])
    for c in columns[1:]:
        if c - end > max(4, int(0.15 * height)):
            break
        end = int(c)
    mark = crop.crop((max(0, start - 3), 0, min(crop.width, end + 4), crop.height))
    found = circled_content_image({"image": mark, "text": label}, line_height=height * 0.75, report=True)
    return found is not None


def page1_values_vs_map_notes(results):
    """S34: each page-1 bullet's Latitude/Longitude finds its yellow map note (the same
    exact-coordinate match as the map check). That note's Wheel Count and Mile/Station
    are compared with the SAME bullet's page-1 Wheel Count and Mile Post/Station.
    A difference adds an orange warning under that page-1 section and the page-1 value
    is kept - except when the packet itself proves the right value (S62):
      - Wheel Count: the page-1 read is the note's Wheel Count with 1-2 digits missing
        ('00553.07' vs '100553.07'), and the read value is nowhere else in the packet
        (no map note Wheel Count, no table Odometer) -> the note's value is used;
      - Mile Post/Station: the SAME bullet's page-1 Wheel Count, as read, equals the
        note's Wheel Count (coordinates AND wheel count agree: it is that anomaly) ->
        the note's printed Mile/Station is used.
    A corrected value gets a blue note saying what was read and why it was changed."""
    notes_with_coordinates = []
    for map_page in results.get("Map Pages") or []:
        for note in map_page.get("notes", []):
            text = str(note.get("value") or "")
            lat = re.search(r"Lat(?:itude)?\.?\s*(-?\d{1,2}\.\d+)", text, re.IGNORECASE)
            lon = re.search(r"Long(?:itude)?\.?\s*(-?\d{1,3}\.\d+)", text, re.IGNORECASE)
            if not (lat and lon):
                continue
            wheel = re.search(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)", text, re.IGNORECASE)
            mile = re.search(r"(?:Mile\s*Post|Mile|Station|Sta\.?|MP)\s*:?\s*([0-9]+\s*\+\s*[0-9]+(?:\.[0-9]+)?)",
                             text, re.IGNORECASE)
            notes_with_coordinates.append({
                "lat": float(lat.group(1)), "lon": float(lon.group(1)),
                "Wheel Count": wheel.group(1) if wheel else None,
                "Mile Post/Station": re.sub(r"\s", "", mile.group(1)) if mile else None,
                "label": f"yellow note {note.get('index')} on map page {map_page.get('page_number')}",
                "image": note.get("image"),
            })
    if not notes_with_coordinates:
        return
    known_wheels = [float(n["Wheel Count"]) for n in notes_with_coordinates if n.get("Wheel Count")]
    for map_page in results.get("Map Pages") or []:          # notes without coordinates too
        for note in map_page.get("notes", []):
            found = re.search(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)", str(note.get("value") or ""), re.IGNORECASE)
            if found:
                known_wheels.append(found.group(1))              # S438: as written
    for table_page in results.get("Table Highlights") or []:
        for item in table_page.get("items", []):
            odometer = re.sub(r"[^0-9.]", "", str(cmp_table_cell(item, r"odometer") or item.get("odometer") or ""))
            if wheel_decimal(odometer) is not None:              # S438: as written
                known_wheels.append(odometer)

    def nowhere_else(value):
        try:
            number = re.sub(r"[^0-9.]", "", value)
        except ValueError:
            return True
        return not any(wheel_same(number, known) for known in known_wheels)      # S438: exactly

    def correct(field, result, label, key, page_value, map_value, why):
        item = page1_item(result, label)
        if item is None:
            return False
        item["value"] = map_value
        if len(result.get("items") or []) == 1:
            result["value"] = map_value
        note_text = f"{key}: page 1 read {page_value} - corrected to {map_value} from the map note ({why})"
        result["note"] = f"{result['note']}  {note_text}" if result.get("note") else note_text
        print(f"PAGE 1 vs MAP NOTE: {key} {page_value} -> {map_value} CORRECTED ({why})")
        return True
    named = []
    for field in ("Latitude", "Longitude"):
        named += coordinate_display_items(field, results.get(field))
    confirmed = {}            # S93: (field, bullet) -> how its map note confirmed it

    def same_value(field, page_value, map_value):
        if field == "Wheel Count":
            try:
                return wheel_same(re.sub(r"[^0-9.]", "", page_value), map_value)          # S438: exactly
            except ValueError:
                return False
        clean = lambda v: re.sub(r"\.0+$", "", re.sub(r"\s", "", str(v)).upper())
        return clean(page_value) == clean(map_value)
    for label, lat, lon in pair_latitudes_with_longitudes(named):
        lat_text, lon_text = clean_coordinate_text(lat), clean_coordinate_text(lon)
        if lat_text is None or lon_text is None:
            continue
        wheel_read = next((value for key, value in coordinate_display_items("Wheel Count", results.get("Wheel Count"))
                           if key[len("Wheel Count"):].strip() == label), None)
        # S481: the bullet's own note (its page-1 Wheel Count's) - else the closest - not the first one nearby
        note = nearest_map_note(notes_with_coordinates, float(lat_text), float(lon_text), wheel_read,
                                lambda n: n.get("Wheel Count"))
        if note is None:
            continue
        # the bullet's Wheel Count AS READ equals the note's: coordinates + wheel count agree
        wheel_agrees = bool(wheel_read and note.get("Wheel Count")
                            and same_value("Wheel Count", wheel_read, note["Wheel Count"]))
        for field in ("Wheel Count", "Mile Post/Station"):
            map_value = note.get(field)
            result = results.get(field)
            page_value = next((value for key, value in coordinate_display_items(field, result)
                               if key[len(field):].strip() == label), None)
            if not map_value or not page_value:
                continue
            key = f"{field} {label}".strip()
            if same_value(field, page_value, map_value):
                print(f"PAGE 1 vs MAP NOTE: {key} {page_value} = {note['label']} ({map_value}) -> same")
                confirmed[(field, label)] = f"{label or 'the value'} = {note['label']}"
                continue
            if field == "Wheel Count" and digits_dropped_from(page_value, map_value) and nowhere_else(page_value):
                if correct(field, result, label, key, page_value, map_value,
                           f"{note['label']} has the same coordinates; {page_value} is {map_value} with digit(s) "
                           f"missing; {page_value} is no other Wheel Count in the packet"):
                    confirmed[(field, label)] = f"{label or 'the value'} corrected from {note['label']}"
                    continue
            if field == "Mile Post/Station" and wheel_agrees:
                if correct(field, result, label, key, page_value, map_value,
                           f"{note['label']} has the same coordinates and the same Wheel Count {wheel_read} "
                           f"as this bullet - its printed {map_value} is used"):
                    confirmed[(field, label)] = f"{label or 'the value'} corrected from {note['label']}"
                    continue
            warning = (f"⚠ {key}: page 1 reads {page_value}, but the map note with this bullet's coordinates "
                       f"({note['label']}) has {map_value} - check the snip")
            result["warning"] = f"{result['warning']}  {warning}" if result.get("warning") else warning
            result.setdefault("warning_details", []).append({   # for the Warnings tab
                "text": warning,
                "pictures": [(f"Page 1 {key} - snip", page1_value_image(result, label)),
                             (f"{note['label']} - map", note.get("image"))],
                "values": [(f"Page 1 {key} reads", page_value), (f"{note['label']} has", map_value)]})
            print(f"PAGE 1 vs MAP NOTE: {key} {page_value} vs {note['label']} {map_value} -> DIFFERENT "
                  f"(warning added; page-1 value kept)")
    # S93: a page-1 line read into more values than the page has bullets keeps the ones
    # with the most votes and gets a warning (S80). When the map notes then confirm or
    # correct EVERY value it kept, the warning has nothing left to point at -> it becomes
    # a blue note saying so.
    for field in ("Wheel Count", "Mile Post/Station"):
        result = results.get(field) or {}
        bullet_warning = result.get("bullet_warning")
        if not bullet_warning:
            continue
        labels = [key[len(field):].strip() for key, _value in coordinate_display_items(field, result)]
        if not labels or not all((field, label) in confirmed for label in labels):
            continue
        result["warning"] = (result.get("warning") or "").replace(bullet_warning["text"], "").strip() or None
        note_text = (f"{field}: {bullet_warning['read']} values were read for {bullet_warning['bullets']} bullets - "
                     f"the {len(labels)} kept are confirmed by the map notes ("
                     + "; ".join(confirmed[(field, label)] for label in labels) + ")")
        result["note"] = f"{result['note']}  {note_text}" if result.get("note") else note_text
        print(f"BULLET COUNT: {field} warning resolved - {note_text}")



def read_dig_sheets(document):
    """Vendor dig sheets (e.g. Entegra) are real text in the PDF - read exactly,
    no OCR: the Target joint's seam o'clock and the target feature's odometer."""
    sheets = []
    for page_index in range(len(document)):
        page = document[page_index]
        words = page.get_text("words")
        if not words:
            continue
        sheet = dig_sheet_from_words(words, page_index)
        if sheet is not None:
            sheets.append(sheet)
    return sheets


def dig_sheet_from_words(words, page_index):
    """One page's words (PDF text words, or dataC: OCR words of a page drawn without a text layer - same form)
    -> its dig sheet {'page', 'target_seam', 'target_feature'}, or None when it is not one."""
    if True:
        text = " ".join(w[4] for w in words)
        if "Seam" not in text or "Target" not in text or "Odometer" not in text:
            return None
        header = next((w for w in words if w[4].rstrip(":") == "Joints"), None)
        targets = [w for w in words if w[4] == "Target"]
        target = (min(targets, key=lambda w: abs((w[1] + w[3]) / 2 - (header[1] + header[3]) / 2))
                  if header and targets else None)
        seam = next((w for i, w in enumerate(words) if w[4] == "Seam"
                     and i + 1 < len(words) and words[i + 1][4].lower().startswith("(o")), None)
        sheet = {"page": page_index + 1, "target_seam": None, "target_feature": None}
        if target and seam:
            seam_y = (seam[1] + seam[3]) / 2
            target_x = (target[0] + target[2]) / 2
            clocks = [w for w in words if abs((w[1] + w[3]) / 2 - seam_y) < 4
                      and re.fullmatch(r"\d{1,2}:\d{2}", w[4])]
            if clocks:
                sheet["target_seam"] = min(clocks, key=lambda w: abs((w[0] + w[2]) / 2 - target_x))[4]
        feature = re.search(r"Odometer Distance of Target Feature \(ft\)\s*([0-9]+\.[0-9]+)", text)
        if feature:
            sheet["target_feature"] = feature.group(1)
        if sheet["target_seam"] or sheet["target_feature"]:
            print(f"Page {page_index + 1}: dig sheet - target feature {sheet['target_feature']} "
                  f"| target joint seam {sheet['target_seam']}")
            return sheet
        return None


# dataC (accuracy fix A6): a vendor dig sheet printed to PDF with its letters drawn as outlines has no PDF text
# layer - it is neither a picture page (no picture on it) nor a text page. Such a page is read with EasyOCR into
# words of the same form as PDF text words and goes through the same dig sheet / text page readers.
OUTLINE_TEXT_MIN_DRAWINGS = 300        # a page drawn with at least this many paths, no text and no picture
OUTLINE_TEXT_KIND = "outline text page (OCR)"


def outline_text_pages(document, skip_pages=()):
    """Page indexes (0-based) that have no PDF text, no picture and many drawn paths: text drawn as outlines."""
    found = []
    for index in range(len(document)):
        if index + 1 in skip_pages:
            continue
        page = document[index]
        if len(page.get_text("words")) >= OTHER_TEXT_PAGE_WORDS:
            continue
        area = abs(page.rect.width * page.rect.height) or 1
        if any(fitz.Rect(info["bbox"]).get_area() > 0.25 * area for info in page.get_image_info()):
            continue                                     # a picture page (a big picture on it) - not this
        if len(page_drawings(page)) >= OUTLINE_TEXT_MIN_DRAWINGS:
            found.append(index)
    return found


def ocr_page_words(page, zoom=None):
    """A page read by EasyOCR as PDF-like words (x0, y0, x1, y1, text, 0, 0, 0) in PDF points - each OCR piece
    split into its words, spread over its width (as read_other_document does for picture pages)."""
    zoom = zoom or OTHER_OCR_ZOOM
    image = dm_render_page(page, zoom)
    found = dm_easy_reader.readtext(np.array(image), detail=1, paragraph=False)
    # EasyOCR finds the text boxes; each box is read again by PaddleOCR's text reader (printed text: it keeps
    # ':' '-' '°' that EasyOCR often drops) - a read PaddleOCR is unsure of keeps EasyOCR's text
    crops = []
    for box, _text, _confidence in found:
        xs, ys = [p[0] for p in box], [p[1] for p in box]
        crops.append(image.crop((max(0, int(min(xs)) - 4), max(0, int(min(ys)) - 3),
                                 min(image.width, int(max(xs)) + 4), min(image.height, int(max(ys)) + 3))))
    rereads = paddle_read_text_images(crops, kind="outline text page") if crops else []
    words = []
    for (box, text, _confidence), (paddle_text, paddle_confidence) in zip(found, rereads):
        if str(paddle_text).strip() and safe_float(paddle_confidence) >= 0.80:
            text = str(paddle_text).strip()
        xs, ys = [float(p[0]) for p in box], [float(p[1]) for p in box]
        x0, y0, x1, y1 = min(xs) / zoom, min(ys) / zoom, max(xs) / zoom, max(ys) / zoom
        pieces, at = str(text).split(), x0
        step = (x1 - x0) / max(1, len(" ".join(pieces)))
        for piece in pieces:
            words.append((at, y0, at + step * len(piece), y1, piece, 0, 0, 0))
            at += step * (len(piece) + 1)
    return words


# ============================================================
# S194: PRIORITY VALUES FROM EVERY TEXT PAGE OF A DIG PACKET
# ============================================================
# Pages with a PDF text layer that are not map pages (e.g. a vendor's dig sheet:
# 'Target Anomaly Details', the joint table, GPS coordinates) are read for the things
# looked for, exactly (PDF text, no OCR):
#   - a header row naming two or more of them ('Feature Type | Depth(%) | Length (in) |
#     Width (in)', 'Latitude(°) | Longitude(°)') -> under each header, the first thing
#     below it (within 30 points) that sits under that header;
#   - a joint-table row ('W.T. (in): 0.250 0.250 ...') -> the value in the Target column
#     (pipe values only - a joint's coordinates are not the anomaly's);
#   - 'label: value' on one row ('Comments: ...' -> a note);
#   - the line right above 'Item Number' -> the Line ID (the sheet's title line);
#   - 'Odometer Distance of Target Feature (ft) 100553.07' -> the Wheel Count it is about.
TEXT_PAGE_ROW_TOLERANCE = 2.5       # points: words this close in height are on one row
TEXT_PAGE_LABEL_GAP = 6.0           # points: a wider gap between words starts another cell
TEXT_PAGE_PIPE_ROW_FIELDS = {"Wall Thickness", "Outside Diameter", "Pipe Grade"}
TEXT_PAGE_VALUE_REACH = 30.0        # points: how far under its header a value may be
TEXT_PAGE_JOINT_COLUMNS = 5         # S202: a joint-table row has a label and at least this many values


def text_page_rows(words, split_names=False):
    """Words (PyMuPDF 'words') grouped into rows, top to bottom; each row a list of cells
    (words close together), left to right: {'text', 'x0', 'y0', 'x1', 'y1'}. S214:
    split_names - a word ending in ':' also ends its cell (for other documents: emails, OCR)."""
    rows = []
    for word in sorted(words, key=lambda w: ((w[1] + w[3]) / 2, w[0])):
        middle = (word[1] + word[3]) / 2
        if rows and abs(rows[-1]["middle"] - middle) <= TEXT_PAGE_ROW_TOLERANCE:
            rows[-1]["words"].append(word)
        else:
            rows.append({"middle": middle, "words": [word]})
    result = []
    for row in rows:
        cells = []
        for word in sorted(row["words"], key=lambda w: w[0]):
            # S214: a name ending in ':' ends its cell - 'Wheel Count: 100553.07' is a name and a
            # value even when the words sit close (an email's text, an OCR piece). Not for a Dig
            # Packet's text pages: their 'Note: 1) If indication...' boilerplate stays out
            if cells and word[0] - cells[-1]["x1"] <= TEXT_PAGE_LABEL_GAP and not (
                    split_names and cells[-1]["text"].endswith(":")):
                cell = cells[-1]
                cell.update(text=f"{cell['text']} {word[4]}", x1=word[2], y0=min(cell["y0"], word[1]),
                            y1=max(cell["y1"], word[3]))
            else:
                cells.append({"text": word[4], "x0": word[0], "y0": word[1], "x1": word[2], "y1": word[3]})
        result.append(cells)
    return result


def text_page_union(cells):
    return {"x0": min(c["x0"] for c in cells), "y0": min(c["y0"] for c in cells),
            "x1": max(c["x1"] for c in cells), "y1": max(c["y1"] for c in cells)}


def text_page_is_number(text):
    return re.fullmatch(r"-?\d*\.?\d+", str(text).replace(",", "")) is not None


def read_text_page_values(document):
    """S194: every text page that is not a map page, read for the things looked for.
    Returns [{'page', 'wheel', 'values': [{'field', 'label', 'text', 'box'}], ...}] - boxes
    in PDF points (S212: no screenshots - the value is shown on its page)."""
    pages = []
    for page_index in range(len(document)):
        page = document[page_index]
        words = page.get_text("words")
        if len(words) < 10 or dm_screen_for_map_page(page):
            continue
        record = text_page_record(words, page_index + 1, "text page")
        if record:
            pages.append(record)
    return pages


def text_page_record(words, page_number, kind, split_names=False):
    """S194/S213: one page's words (PDF text words, or OCR words of a picture page - in the
    same form: x0, y0, x1, y1, text) read for the things looked for: {'page', 'wheel',
    'values'} or None when nothing was found."""
    rows = text_page_rows(words, split_names)
    text = " ".join(w[4] for w in words)
    wheel = re.search(r"Target Feature \(ft\)\s*([0-9]+\.[0-9]+)", text) or \
        re.search(r"Wheel\s*Count:?\s*([0-9]+\.[0-9]+)", text, re.IGNORECASE)
    target = next((c for row in rows for c in row if c["text"] == "Target"), None)
    found = []

    def keep(field, label, value_cells):
        box = text_page_union(value_cells)
        found.append({"field": field, "label": label, "text": " ".join(c["text"] for c in value_cells),
                      "box": (box["x0"], box["y0"], box["x1"], box["y1"])})

    for index, row in enumerate(rows):
        named = [(cell, priority_field_of(cell["text"])) for cell in row]
        headers = [(cell, field) for cell, field in named if field and not text_page_is_number(cell["text"])]
        if len(headers) >= 2:                      # a header row -> under each header, its value
            # S202: the row's other headers too ('Orientation', 'FPR MB31G', 'Elevation(ft)')
            others = [(c, None) for c, f in named if f is None and not text_page_is_number(c["text"])]
            for cell, field in headers + others:
                # the first row below (within TEXT_PAGE_VALUE_REACH) with something under this header:
                # a label beside the table ('GPS Coordinates') is not under it, so it is passed over
                for below in rows[index + 1:]:
                    if below[0]["y0"] - cell["y1"] > TEXT_PAGE_VALUE_REACH:
                        break
                    under = [c for c in below if c["x1"] > cell["x0"] - TEXT_PAGE_LABEL_GAP
                             and c["x0"] < cell["x1"] + TEXT_PAGE_LABEL_GAP]
                    if under:
                        keep(field, cell["text"], under)
                        break
            continue
        first, field = named[0] if named else (None, None)
        numbers = [c for c in row[1:] if text_page_is_number(c["text"])]
        if first is not None and len(row) - 1 >= TEXT_PAGE_JOINT_COLUMNS and target and \
                (first["text"].endswith((":", ")"))                           # a joint-table row
                 # dataC (fix A6): on a page read by OCR the label's small '(ft):' can be lost - a label of
                 # words followed by numbers in every other cell is a joint-table row too
                 or (kind == OUTLINE_TEXT_KIND and re.search(r"[A-Za-z]{3}", first["text"])
                     and len(numbers) >= TEXT_PAGE_JOINT_COLUMNS and len(numbers) == len(row) - 1)):
            # the Target column's value; a pipe value stays one of its things, everything else
            # (S202) is an other value named for the target joint
            middle = (target["x0"] + target["x1"]) / 2
            pick = min(row[1:], key=lambda c: abs((c["x0"] + c["x1"]) / 2 - middle))
            if pick["text"] != "Target" and \
                    abs((pick["x0"] + pick["x1"]) / 2 - middle) < (target["x1"] - target["x0"]) * 2:
                keep(field if field in TEXT_PAGE_PIPE_ROW_FIELDS else None,
                     f"Target joint {first['text'].rstrip(':')}", [pick])
        elif first is not None and len(row) >= 2 and first["text"].endswith(":") and len(numbers) < 3:
            value_cells = row[1:]                                    # 'label: value'
            if field:
                keep(field, first["text"].rstrip(":"), value_cells)
            elif re.search(PRIORITY_NOTE_LABEL, first["text"], re.IGNORECASE):
                keep(PRIORITY_NOTES, first["text"].rstrip(":"), value_cells)
            elif not re.search(r"_{2,}|[☐☑☒]", " ".join(c["text"] for c in value_cells)):
                keep(None, first["text"].rstrip(":"), value_cells)   # S202 (not a blank form line)
        if any(c["text"].startswith("Item Number") for c in row) and index > 0:   # the title line above it
            title = rows[index - 1]
            title_text = " ".join(c["text"] for c in title)
            if re.search(r"\d", title_text) and re.search(r"[A-Za-z]{3}", title_text):
                keep("Line ID", "title line", title)
    if not found:
        return None
    print(f"Page {page_number}: {kind} - " + "; ".join(f"{v['field'] or v['label']} {v['text']!r}" for v in found)
          + (f" | about Wheel Count {wheel.group(1)}" if wheel else "") + " (S194)")
    return {"page": page_number, "wheel": wheel.group(1) if wheel else None, "values": found,
            "text": text}                                # S467: the page's words, for the Notes lines' check


# ============================================================
# S213: ANY OTHER DOCUMENT - read with what it has
# ============================================================
# A PDF that is not a 6000 form, a Dig Packet or an OmegaWrap quote request is still read:
# every page with a PDF text layer exactly (the same reader as a Dig Packet's dig sheet),
# every page that is a picture with EasyOCR (its words in the same form). What it finds
# goes into the Verify tab's end table - in the column of the anomaly it names (its Wheel
# Count), else an Info column - and the values read by OCR come up on the Verify list.
OTHER_OCR_ZOOM = 3.0                # picture pages are read by EasyOCR at this zoom (about 216 dpi)
OTHER_TEXT_PAGE_WORDS = 10          # a page with fewer PDF text words than this is read as a picture
DIG_PACKET_MARKERS = ("WHEEL COUNT", "TARGET FEATURE", "ANOMALY INVESTIGATION", "DIG PACKET", "DIG SHEET")
SCAN_LOOK_ZOOM = 1.5                # S213: page 1 of an all-picture PDF is read by EasyOCR at this zoom


def scan_is_dig_packet(path):
    """S213: an all-picture PDF - a Dig Packet when EasyOCR finds a Dig Packet sign on its page 1
    ('Anomaly Investigation', 'Dig Packets', 'Wheel count'...). Returns (is it, what was found)."""
    with pdf_turn("looking at a scanned PDF's page 1"), fitz.open(path) as document:
        image = dm_render_page(document[0], SCAN_LOOK_ZOOM)
    text = " ".join(str(t) for _box, t, _c in dm_easy_reader.readtext(np.array(image), detail=1, paragraph=False))
    text = re.sub(r"\s+", " ", text.upper())
    marker = next((m for m in DIG_PACKET_MARKERS + ("ANOMALY",) if m in text), None)
    return marker is not None, marker


# S214: what can be dropped in besides PDFs - pictures (read like a scanned PDF) and emails
# (their text read like a text page, their attachments dropped in as documents of their own)
IMAGE_INPUTS = (".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".gif")
EMAIL_INPUTS = (".eml", ".msg")
INPUT_FOLDER = os.path.join(tempfile.gettempdir(), "dig_reader_inputs")    # the PDFs made from them
EMAIL_LINE_CHARACTERS = 100         # an email's text is written this many characters per line
EMAIL_TABLE_CELL_GAP = "    "       # an HTML table cell ends with this many spaces: a cell gap in the PDF


def input_pdf_path(path, suffix):
    """S214: where the PDF made from a dropped picture / email is kept."""
    os.makedirs(INPUT_FOLDER, exist_ok=True)
    stem = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.splitext(os.path.basename(path))[0])[:60]
    return os.path.join(INPUT_FOLDER, f"{stem}_{hashlib.md5(path.encode('utf-8')).hexdigest()[:8]}{suffix}.pdf")


def image_to_pdf(path):
    """S214: a dropped picture (a multi-page TIFF too) as a PDF of picture pages - read like a scan."""
    out = input_pdf_path(path, "")
    with fitz.open(path) as picture:
        data = picture.convert_to_pdf()
    with open(out, "wb") as file:
        file.write(data)
    return out


def html_to_text(html):
    """S214: an HTML email body as text lines; a table cell ends with a cell gap, a row with a new line."""
    import html as html_module
    text = re.sub(r"(?is)<(script|style).*?</\1>", "", html)
    text = re.sub(r"(?i)</t[dh]\s*>", EMAIL_TABLE_CELL_GAP, text)
    text = re.sub(r"(?i)<br\s*/?>|</(p|div|tr|li|h\d)\s*>", "\n", text)
    text = html_module.unescape(re.sub(r"<[^>]+>", "", text))
    return [line.rstrip() for line in text.splitlines()]


def email_parts(path):
    """S214: an email's header lines, body lines and attachments [(file name, bytes)].
    .eml with Python's own email reader; .msg (Outlook) with the free 'extract-msg' package."""
    if path.lower().endswith(".eml"):
        import email
        from email import policy
        with open(path, "rb") as file:
            message = email.message_from_binary_file(file, policy=policy.default)
        headers = [f"{name}: {message[name]}" for name in ("From", "To", "Cc", "Date", "Subject") if message[name]]
        body = message.get_body(preferencelist=("plain", "html"))
        content = body.get_content() if body is not None else ""
        lines = html_to_text(content) if body is not None and body.get_content_type() == "text/html" \
            else content.splitlines()
        attachments = [(part.get_filename(), part.get_payload(decode=True)) for part in message.iter_attachments()
                       if part.get_filename()]
        return headers, lines, attachments
    try:
        import extract_msg
    except ImportError:
        raise RuntimeError("an Outlook .msg email needs the free package extract-msg: pip install extract-msg")
    message = extract_msg.Message(path)
    try:
        headers = [f"{name}: {value}" for name, value in (("From", message.sender), ("To", message.to),
                                                           ("Cc", message.cc), ("Date", message.date),
                                                           ("Subject", message.subject)) if value]
        lines = (message.body or "").splitlines() or html_to_text(
            (message.htmlBody or b"").decode("utf-8", "ignore") if isinstance(message.htmlBody, bytes)
            else str(message.htmlBody or ""))
        attachments = [(a.longFilename or a.shortFilename, a.data) for a in message.attachments
                       if (a.longFilename or a.shortFilename) and isinstance(a.data, bytes)]
    finally:
        message.close()
    return headers, lines, attachments


def email_to_pdf(path):
    """S214: a dropped email as a text PDF (its headers, then its body) - read like a text page -
    and its attachments that can be read (PDFs, pictures, emails) saved next to it.
    Returns (the PDF, [attachment paths])."""
    headers, lines, attachments = email_parts(path)
    import textwrap
    document = fitz.open()
    page, y = None, 0
    for line in headers + [""] + lines:
        for piece in textwrap.wrap(line, EMAIL_LINE_CHARACTERS, replace_whitespace=False, drop_whitespace=False) or [""]:
            if page is None or y > page.rect.height - 50:
                page, y = document.new_page(), 50
            page.insert_text((40, y), piece, fontsize=10, fontname="helv")
            y += 14
    out = input_pdf_path(path, "_email")
    document.save(out)
    document.close()
    saved = []
    for name, data in attachments:
        if data and os.path.splitext(name)[1].lower() in (".pdf",) + IMAGE_INPUTS + EMAIL_INPUTS:
            target = os.path.join(INPUT_FOLDER, re.sub(r"[^A-Za-z0-9._ -]+", "_", name))
            with open(target, "wb") as file:
                file.write(data)
            saved.append(target)
    return out, saved


def other_document_pages(path):
    """S213: which pages of a PDF have a PDF text layer and which are pictures."""
    with fitz.open(path) as document:
        text = [i for i in range(len(document)) if len(document[i].get_text("words")) >= OTHER_TEXT_PAGE_WORDS]
        return text, [i for i in range(len(document)) if i not in text]


def read_other_document(path, ocr=True):
    """S213: a PDF of no known kind, read with what it has: its text pages exactly, its
    picture pages by EasyOCR (only when ocr - the OCR models are ready). Returns
    {'path', 'pages': [text_page_record + 'from_text']}."""
    print()
    print("OTHER DOCUMENT:", path)
    pages = []
    with timed("Other document"):
        progress_step("Text pages")
        with timed("Text pages (PDF text)", 1), pdf_turn("Other document: text pages"):
            with fitz.open(path) as document:
                pictures = {}
                for index in range(len(document)):
                    page = document[index]
                    words = page.get_text("words")
                    if len(words) >= OTHER_TEXT_PAGE_WORDS:
                        record = text_page_record(words, index + 1, "text page", split_names=True)
                        if record:
                            pages.append(dict(record, from_text=True))
                    elif ocr:
                        pictures[index] = dm_render_page(page, OTHER_OCR_ZOOM)
        progress_step("Picture pages (OCR)")
        with timed(f"Picture pages read by EasyOCR ({len(pictures)})", 1):
            for index, image in pictures.items():
                words = []
                for box, text, _confidence in dm_easy_reader.readtext(np.array(image), detail=1, paragraph=False):
                    xs, ys = [p[0] for p in box], [p[1] for p in box]
                    x0, y0, x1, y1 = (min(xs) / OTHER_OCR_ZOOM, min(ys) / OTHER_OCR_ZOOM, max(xs) / OTHER_OCR_ZOOM,
                                      max(ys) / OTHER_OCR_ZOOM)
                    # one OCR piece ('Joint Number: 24380') -> its words, spread over its width, so a
                    # name ending in ':' and its value become two cells, like PDF text words (S214)
                    pieces, at = str(text).split(), x0
                    step = (x1 - x0) / max(1, len(" ".join(pieces)))
                    for piece in pieces:
                        words.append((at, y0, at + step * len(piece), y1, piece, 0, 0, 0))
                        at += step * (len(piece) + 1)
                record = text_page_record(words, index + 1, "picture page (OCR)", split_names=True)
                if record:
                    pages.append(dict(record, from_text=False))
    found = sum(len(p["values"]) for p in pages)
    print(f"OTHER DOCUMENT: {found} value(s) found on {len(pages)} page(s)"
          + (f"; {len(pictures)} picture page(s) read by OCR" if pictures else "") + " (S213)")
    return {"path": path, "pages": sorted(pages, key=lambda p: p["page"])}


# ============================================================
# S320: 10000-35 WALL THICKNESS FORM - an Excel workbook (.xlsx)
# ============================================================
# The form's cells are read exactly (no OCR): every label ('Nominal OD', 'Project Number' ...) and
# the value right of it, the ticked Company boxes (Excel form controls - kept in the file's VML,
# not in a cell) and the grid readings (letters A, B, C ... across, numbers 1, 2, 3 ... down; a
# reading with no unit of its own takes the form's 'Units of Measurement'). A PDF of the sheet is
# made for the Verify and Pages tabs: the cells as real PDF text, the pictures as pictures. The
# photo on the grid is only read for its TYPED text, never for handwriting: the camera app's
# white text block (pure white, no colour - the marker on the pipe never is) and a flat grey
# label ('Gouge #1' - one exact colour, which a photo never has); a read is kept only when EasyOCR
# is sure of every word of it and it is one of the known kinds (a date, PN, WC#, pipe size, a
# defect label ...). The 6000 form the file name names ('..._6000-10-233-08192026') is joined
# with it when the other things they both give agree.
WORKBOOK_INPUTS = (".xlsx", ".xlsm")
WT35_KIND_WHY = "an Excel workbook with the 10000-35 wall thickness form's labels"
# (pattern on a label cell's text - lower case, letters / digits / '/' only; the row it goes in;
#  the priority field it is, or None for an 'everything else found' row)
WT35_LABELS = [
    (r"date", "Date", None),
    (r"projectnumber", "Project Number", None),
    (r"projectname", "Project Name", None),
    (r"company", "Company", None),
    (r"facilitytype", "Facility Type", None),
    (r"operatingarea", "Operating Area", None),
    (r"facility/?location", "Facility/Location", None),
    (r"nominalod", "Nominal OD", "Outside Diameter"),
    (r"nominalwallthickness", "Nominal Wall Thickness", "Wall Thickness"),
    (r"yieldstrength", "Yield Strength", "SMYS"),
    (r"classlocation", "Class Location", "Class Location"),
    (r"maop", "MAOP", None),
    (r"performedby.*", "Performed By", None),
    (r"remarks?", "Remarks", "notes"),             # its Additional notes (PRIORITY_NOTES is made further down)
    (r"axial", "Axial spacing", None),
    (r"circumferential", "Circumferential spacing", None),
    (r"unitsofmeasurement", "Units of Measurement", None),
]
WT35_NEEDED_LABELS = 5              # a workbook is this form when at least this many of its labels are found
WT35_EXCEL_ERRORS = {"#VALUE!", "#REF!", "#N/A", "#NAME?", "#DIV/0!", "#NUM!", "#NULL!", "#SPILL!", "#CALC!"}
WT35_MARGIN = 18.0                  # points around the sheet on its PDF page
WT35_FILE_LINE = 16.0               # points: the file name line at the top of the page
WT35_DEFECT = (r"\b(gouge|dent|corrosion|metal\s*loss|crack(?:ing)?|scratch|arc\s*burn|lamination|wrinkle|"
               r"buckle|pit(?:ting)?|groove|anomaly)\b(?:\s*grid\s*#?|\s*#)\s*(\d+)")   # S343: 'Grid 3' needs no '#'
# S321: one wheel count or several ('WC: 100553.07 - 100572.03', '... & ...', '... and ...', '... to ...')
WT35_WHEEL = (r"\b(?:WC|Wheel\s*Count)\s*[:#]*\s*(\d{4,}\.\d+(?:\s*(?:-|–|to|&|and|,)\s*\d{4,}\.\d+)*)")
WT35_FILE_WHEEL = r"(?:^|[_\s])WC[_\s#:]*(\d{4,}\.\d+(?:[_\s]*(?:-|to|&|and)[_\s]*\d{4,}\.\d+)*)"
# S321: what a form says about its pipe, compared with what the other documents say at each wheel count
# it names: (field or row of the end table, the form's row, number tolerance - None = words)
WT35_DETAILS = [("Outside Diameter", "Nominal OD", 1e-6), ("Wall Thickness", "Nominal Wall Thickness", 1e-6),
                ("SMYS", "Yield Strength", 1e-6), ("Class Location", "Class Location", 1e-6),
                ("Defect name", None, None), ("Project Number", "Project Number", 1e-6), ("MAOP", "MAOP", 1e-6),
                ("Operating Area", "Operating Area", None)]
WT35_WHEELS_SAID = {}               # document id -> what the terminal was told last about its wheel counts
# S322: a form's own rows carry its defect name (or this tag) - 'Grid row 1 - Gouge #3' - so several forms share a column without a pick;
# these rows say the same for the whole pipe and stay shared
WT35_SHARED_ROWS = {"Project Number", "MAOP", "Operating Area", "Company", "Facility Type",
                    "Facility/Location"}          # S331: Project Name is each form's own (it follows the job)
WT35_NO_DEFECT_TAG = "WT readings"
WT35_NAME_FILLER = {"defect", "anomaly", "grid", "actual", "the", "and", "with", "readings", "reading"}
WT35_DEPTH_TOLERANCE = 0.0005       # inches: a grid reading 'equals' a defect's depth this close
WT35_DEFECTS_SAID = {}              # what the terminal was told last about the defects
WT35_SIX_THOUSAND = r"(?<![0-9])(6000-\d+-\d+)(?:-(\d{8}))?"
WT35_FILE_START = r"^\s*10000-35\s*(?:wall\s*thickness)?\s*"     # S323: the form's name at the front of its file name
# the photo: what typed text looks like, and how sure EasyOCR has to be of every word of a read
WT35_PHOTO_CONFIDENCE = 0.80
WT35_WHITE_MIN = 235                # the camera app's text: every colour channel at least this bright ...
WT35_WHITE_CHROMA = 18              # ... and this close to each other (no colour)
WT35_TAG_FLAT = 2                   # a label's fill: one grey, at most this far from its neighbours (5 x 5)
WT35_TAG_MIN_FILL = 0.5             # at least this share of the label is its one grey ...
WT35_TAG_MIN_COVER = 0.85           # ... and with its dark text and their soft edges, this share
WT35_MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"]
WT35_PHOTO_PATTERNS = [             # (row, field, pattern on a line of typed text, how the value is written)
    ("Photo date", None,
     r"\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|June?|July?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|"
     r"Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?\s+(\d{1,2}),?\s+(20\d\d)\b",
     lambda m: f"{WT35_MONTHS.index(m.group(1)[:3].lower()) + 1}/{int(m.group(2))}/{m.group(3)}"),
    ("Project Number", None, r"\bPN\s*#?\s*(\d{4,6})\b", lambda m: m.group(1)),
    ("Line ID", "Line ID", r"\bPN\s*#?\s*\d{4,6}\s+([A-Z]{2,5}\s*\d+(?:-\d+)?)\b", lambda m: m.group(1)),
    ("Outside Diameter", "Outside Diameter",
     r"(\d+(?:\.\d+)?)\s*(?:\"|”|in)?\s*[x×X]\s*\d*\.\d+\s*(?:\"|”|in)?\s*[x×X]\s*(?:X-?\s*\d{2,3}|Gr)",
     lambda m: f'{m.group(1)}"'),
    ("Wall Thickness", "Wall Thickness",
     r"\d+(?:\.\d+)?\s*(?:\"|”|in)?\s*[x×X]\s*(\d*\.\d+)\s*(?:\"|”|in)?\s*[x×X]\s*(?:X-?\s*\d{2,3}|Gr)",
     lambda m: f'{m.group(1)}"'),
    ("Pipe Grade", "Pipe Grade",
     r"\d*\.\d+\s*(?:\"|”|in)?\s*[x×X]\s*(X-?\s*\d{2,3}|Gr(?:ade)?\.?\s*B)\b",
     lambda m: re.sub(r"\s+", "", m.group(1))),
    ("Photo wheel counts", None, r"\bWC\s*#?\s*:?\s*(\d{4,}\.\d+(?:\s*-\s*\d{4,}\.\d+)?)",
     lambda m: re.sub(r"\s*-\s*", " - ", m.group(1))),
    ("Photo company", None, r"^([A-Za-z][A-Za-z&.' ]*\b(?:Pipelines?|Gas|Energy|Transmission|Company|LLC|Inc)\b\.?)$",
     lambda m: m.group(1)),
    ("Photo route", None, r"^([A-Za-z][A-Za-z.' ]* to [A-Za-z][A-Za-z.' ]*)$", lambda m: m.group(1)),
]
WT35_TAG_PATTERN = r"^([A-Za-z][A-Za-z .\-]*?)\s*#\s*(\d+)$"
WT35_LINK_SAID = {}                 # (document id, 6000 form id or number) -> what the terminal was told last


def wt35_label_key(text):
    return re.sub(r"[^a-z0-9/]", "", str(text or "").lower())


def wt35_file_name_values(name):
    """S323: what a 10000-35 form's file name says besides its wheel counts - e.g. '10000-35 wall thickness PN
    17748 SHC 20-1 Digs Red River to Sharon WC 100553.07 Gouge Grid #1_6000-10-233-08192026.xlsx':
    Project Number 17748, Line ID SHC 20-1, route 'Red River to Sharon', defect 'Gouge #1', 6000 form
    6000-10-233 of 8/19/2026. A ' (1)' copy number is left out. [(field or None, row, value)]."""
    stem = re.sub(r"\s*\(\d+\)\s*$", "", os.path.splitext(name)[0])
    found = []
    six = re.search(WT35_SIX_THOUSAND, stem)
    words = re.sub(WT35_FILE_START, "", stem[:six.start()] if six else stem, flags=re.IGNORECASE).strip(" _")
    words = words.replace("_", " ")
    project = re.search(r"\bPN\s*#?\s*(\d{4,6})\b", words)
    if project:
        found.append((None, "Project Number", project.group(1)))
    line = re.search(r"\bPN\s*#?\s*\d{4,6}\s+([A-Z]{2,5}\s*\d+(?:-\d+)?)\b", words)
    if line:
        found.append(("Line ID", "Line ID", " ".join(line.group(1).split())))
    # the route: what follows the line (or the PN) up to the wheel count / the defect, without 'Digs'
    start = line.end() if line else project.end() if project else 0
    stops = [m.start() for m in (re.search(r"\bWC\b", words[start:]), re.search(WT35_DEFECT, words[start:], re.I))
             if m]
    route = words[start:start + min(stops)] if stops else words[start:]
    route = " ".join(re.sub(r"^\s*digs?\b", "", route.strip(), flags=re.IGNORECASE).split())
    if re.search(r"[A-Za-z]{2,}.* to .*[A-Za-z]{2,}", route):
        found.append((None, "Route", route))
    defect = re.search(WT35_DEFECT, words, re.IGNORECASE)
    if defect:
        found.append(("Defect name", "Defect name", f"{' '.join(defect.group(1).split()).title()} #{defect.group(2)}"))
    if six and six.group(2):
        day = six.group(2)
        found.append((None, "6000 form date", f"{int(day[:2])}/{int(day[2:4])}/{day[4:]}"))
    return found


def wt35_wheel_numbers(text, pattern):
    """S321: every wheel count a text names after 'WC' / 'Wheel Count' - both of a range
    ('WC: 100553.07 - 100572.03' -> ['100553.07', '100572.03']), in order."""
    found = []
    for match in re.finditer(pattern, str(text or ""), re.IGNORECASE):
        found += re.findall(r"\d{4,}\.\d+", match.group(1))
    return found


def wt35_cell_text(cell):
    """A cell as the sheet shows it: a date as 8/19/2026, a whole number without '.0', a number with
    the decimals its format shows; an Excel error (a picture in the cell gives '#VALUE!') is None."""
    value = cell.value
    if value is None:
        return None
    if isinstance(value, datetime):
        return f"{value.month}/{value.day}/{value.year}"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        places = re.search(r"0\.(0+)", str(cell.number_format or ""))
        if places:
            return f"{value:.{len(places.group(1))}f}"
        return f"{value:g}" if abs(value) < 1e15 else str(value)
    text = " ".join(str(value).split())
    return None if not text or text in WT35_EXCEL_ERRORS else text


def wt35_sheet_parts(path):
    """The workbook's first sheet's own parts, read from the file itself (openpyxl leaves these out):
    its form controls (VML), its pictures in cells and its floating pictures with where they sit."""
    import zipfile
    parts = {"checks": [], "cell_pictures": {}, "pictures": []}
    with zipfile.ZipFile(path) as book:
        names = set(book.namelist())

        def text(name):
            return book.read(name).decode("utf-8", "replace") if name in names else ""

        def rels(name):
            folder, base = name.rsplit("/", 1)
            found = {}
            for rel in re.finditer(r"<Relationship\b[^>]*>", text(f"{folder}/_rels/{base}.rels")):
                rid = re.search(r'\bId="([^"]+)"', rel.group(0))
                target = re.search(r'\bTarget="([^"]+)"', rel.group(0))
                if rid and target:
                    where = target.group(1)
                    found[rid.group(1)] = (where.lstrip("/") if where.startswith("/") else
                                           os.path.normpath(os.path.join(folder, where)).replace("\\", "/"))
            return found

        workbook_rels = rels("xl/workbook.xml")
        first = re.search(r'<sheet\b[^>]*r:id="([^"]+)"', text("xl/workbook.xml"))
        sheet_name = workbook_rels.get(first.group(1)) if first else "xl/worksheets/sheet1.xml"
        sheet_xml, sheet_rels = text(sheet_name), rels(sheet_name)
        # form controls: each check box's text, ticked or not, and its place (the VML anchor)
        for target in sheet_rels.values():
            if not target.endswith(".vml"):
                continue
            for shape in re.finditer(r"<v:shape\b.*?</v:shape>", text(target), re.S):
                body = shape.group(0)
                kind = re.search(r'ObjectType="(\w+)"', body)
                anchor = re.search(r"<x:Anchor>\s*([\d,\s]+)</x:Anchor>", body)
                if not kind or not anchor:
                    continue
                label = re.search(r"<v:textbox\b.*?</v:textbox>", body, re.S)
                label = " ".join(re.sub(r"<[^>]+>", " ", label.group(0)).split()) if label else ""
                label = label.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">")
                ticked = re.search(r"<x:Checked>\s*(\d)\s*</x:Checked>", body)
                parts["checks"].append({"kind": kind.group(1), "label": label,
                                        "ticked": bool(ticked and ticked.group(1) != "0"),
                                        "anchor": [int(n) for n in anchor.group(1).replace(" ", "").split(",")]})
        # pictures in cells (Excel 365 'Place in Cell'): cell vm="n" -> rich value n -> its picture
        values = re.findall(r"<rv\b[^>]*>(.*?)</rv>", text("xl/richData/rdrichvalue.xml"), re.S)
        rel_ids = re.findall(r'<rel\b[^>]*r:id="([^"]+)"', text("xl/richData/richValueRel.xml"))
        picture_rels = rels("xl/richData/richValueRel.xml")
        for cell in re.finditer(r'<c\b[^>]*\br="([A-Z]+\d+)"[^>]*\bvm="(\d+)"', sheet_xml):
            try:
                first_value = re.search(r"<v>(\d+)</v>", values[int(cell.group(2)) - 1]).group(1)
                media = picture_rels[rel_ids[int(first_value)]]
                parts["cell_pictures"][cell.group(1)] = (media, book.read(media))
            except (IndexError, KeyError, AttributeError, ValueError):
                continue
        # floating pictures (the logo, the pipe drawing, a photo dropped on the sheet)
        for target in sheet_rels.values():
            if "/drawings/" not in target or not target.endswith(".xml"):
                continue
            drawing, drawing_rels = text(target), rels(target)
            for anchor in re.finditer(r"<xdr:(twoCellAnchor|oneCellAnchor)\b.*?</xdr:\1>", drawing, re.S):
                body = anchor.group(0)

                def place(tag):
                    found = re.search(rf"<xdr:{tag}>(.*?)</xdr:{tag}>", body, re.S)
                    if not found:
                        return None
                    return [int(re.search(rf"<xdr:{n}>(-?\d+)</xdr:{n}>", found.group(1)).group(1))
                            for n in ("col", "colOff", "row", "rowOff")]

                def xfrm(text):                          # (x, y, cx, cy[, child x, child y, child cx, child cy])
                    numbers = []
                    for tag in ("off", "ext", "chOff", "chExt"):
                        found = re.search(rf'<a:{tag}\b[^>]*?(?:x|cx)="(-?\d+)"[^>]*?(?:y|cy)="(-?\d+)"', text)
                        if found:
                            numbers += [int(found.group(1)), int(found.group(2))]
                    return numbers
                ext = re.search(r'<xdr:ext\b[^>]*cx="(\d+)"[^>]*cy="(\d+)"', body)
                # a picture in a group (the logo with the Company boxes): the group's own frame says
                # where its pieces sit (child frame -> the anchor's place)
                group = re.search(r"<xdr:grpSpPr\b.*?</xdr:grpSpPr>", body, re.S)
                for picture in re.finditer(r"<xdr:pic>.*?</xdr:pic>", body, re.S):
                    embed = re.search(r'<a:blip\b[^>]*r:embed="([^"]+)"', picture.group(0))
                    if not embed or embed.group(1) not in drawing_rels:
                        continue
                    media = drawing_rels[embed.group(1)]
                    parts["pictures"].append({"media": media, "data": book.read(media), "from": place("from"),
                                              "to": place("to"), "ext": (int(ext.group(1)), int(ext.group(2)))
                                              if ext else None,
                                              "group": xfrm(group.group(0)) if group else None,
                                              "own": xfrm(picture.group(0)) if group else None})
    return parts


def wt35_picture(data, media):
    """A picture's bytes as a PIL picture; one PIL cannot open (a .wmf drawing outside Windows) is a
    grey stand-in saying so - still a picture on the page, so the Pages tab shows where it is."""
    try:
        picture = Image.open(io.BytesIO(data))
        picture.load()
        return picture.convert("RGB"), True
    except Exception:
        stand_in = Image.new("RGB", (400, 160), (200, 200, 200))
        ImageDraw.Draw(stand_in).text((12, 70), f"picture {os.path.basename(media)} - cannot be shown here",
                                      fill=(60, 60, 60))
        return stand_in, False


def wt35_read_workbook(path):
    """S320: a dropped workbook read as a 10000-35 wall thickness form - its sheet's layout (column
    and row sizes in points), its label / value pairs, its ticked boxes, its grid readings and its
    pictures. Raises ValueError when it is not that form (fewer than WT35_NEEDED_LABELS labels)."""
    try:
        import openpyxl
        from openpyxl.utils import get_column_letter, range_boundaries
    except ImportError:
        raise ValueError("reading Excel files needs: pip install openpyxl")
    import warnings
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")                  # 'wmf image format is not supported' ...
        book = openpyxl.load_workbook(path, data_only=True)
    sheet = book.worksheets[0]
    last_row, last_col = max(1, sheet.max_row), max(1, sheet.max_column)
    # where every column and row sits on the PDF page (points; Excel's width is in characters)
    widths = {}
    for dimension in sheet.column_dimensions.values():
        if dimension.width is not None and dimension.min:
            for column in range(dimension.min, (dimension.max or dimension.min) + 1):
                widths[column] = 0.0 if dimension.hidden else dimension.width
    default_width = sheet.sheet_format.defaultColWidth or 8.43
    xs = [WT35_MARGIN]
    for column in range(1, last_col + 1):
        characters = widths.get(column, default_width)
        xs.append(xs[-1] + (int(characters * 7 + 5) * 0.75 if characters > 0 else 0.0))
    default_height = sheet.sheet_format.defaultRowHeight or 15.0
    ys = [WT35_MARGIN + WT35_FILE_LINE]
    for row in range(1, last_row + 1):
        dimension = sheet.row_dimensions[row] if row in sheet.row_dimensions else None
        height = dimension.height if dimension is not None and dimension.height is not None else default_height
        ys.append(ys[-1] + (0.0 if dimension is not None and dimension.hidden else height))
    merged = {}
    for cell_range in sheet.merged_cells.ranges:
        c0, r0, c1, r1 = range_boundaries(str(cell_range))
        merged[(r0, c0)] = (r0, c0, r1, c1)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if (r, c) != (r0, c0):
                    merged[(r, c)] = None                 # covered by the range's first cell

    def rect(r0, c0, r1=None, c1=None):
        span = merged.get((r0, c0))
        if r1 is None and span:
            r0, c0, r1, c1 = span
        r1, c1 = r1 or r0, c1 or c0
        return (xs[c0 - 1], ys[r0 - 1], xs[min(c1, last_col)], ys[min(r1, last_row)])

    cells = {}
    for row in sheet.iter_rows(min_row=1, max_row=last_row, max_col=last_col):
        for cell in row:
            if merged.get((cell.row, cell.column), True) is None:
                continue
            shown = wt35_cell_text(cell)
            if shown is not None:
                cells[(cell.row, cell.column)] = {"text": shown, "ref": f"{get_column_letter(cell.column)}{cell.row}",
                                                  "rect": rect(cell.row, cell.column),
                                                  "size": float(cell.font.sz or 10) if cell.font else 10.0}
    # the grid: a row of letters A, B, C ... in a row (at least 5), its numbers 1, 2, 3 ... down the
    # column left of 'A'
    grid = None
    for (r, c), cell in sorted(cells.items()):
        if cell["text"] != "A":
            continue
        letters = {}
        while (r, c + len(letters)) in cells and cells[(r, c + len(letters))]["text"] == chr(65 + len(letters)):
            letters[chr(65 + len(letters))] = c + len(letters)
        if len(letters) >= 5:
            grid = {"row": r, "letters": letters, "numbers": {}}
            for below in range(r + 1, last_row + 1):
                number = (cells.get((below, c - 1)) or {}).get("text")
                if number and re.fullmatch(r"\d+", number):
                    grid["numbers"][int(number)] = below
            break
    top_of_grid = grid["row"] - 1 if grid else last_row + 1
    # labels (above the grid only - its 'Axial' / 'Circumferential' headings are not labels) and the
    # value right of each: the next filled cell in its row, before the next label
    found, label_columns = [], set()
    for (r, c), cell in sorted(cells.items()):
        if r >= top_of_grid:
            continue
        key = wt35_label_key(cell["text"].rstrip(":"))
        known = next((item for item in WT35_LABELS if re.fullmatch(item[0], key)), None)
        if known and not any(f["row"] == known[1] for f in found):
            found.append({"row": known[1], "field": known[2], "at": (r, c), "label": cell})
            label_columns.add(c)
    if len(found) < WT35_NEEDED_LABELS:
        raise ValueError(f"not a 10000-35 wall thickness form - only {len(found)} of its labels found "
                         f"(at least {WT35_NEEDED_LABELS} needed)")
    # S320: a label this program does not know, in a column the known labels are in, with a value
    # right of it, is read too (its own row) - a newer form with a line more still gives everything
    for (r, c), cell in sorted(cells.items()):
        if r < top_of_grid and c in label_columns and not any(f["at"] == (r, c) for f in found) \
                and re.search(r"[A-Za-z]{3}", cell["text"]) and not text_page_is_number(cell["text"]):
            found.append({"row": cell["text"].rstrip(":").strip(), "field": None, "at": (r, c), "label": cell})
    values, labelled = [], {f["at"] for f in found}
    for item in found:
        r, c = item["at"]
        value = None
        for column in range(c + 1, last_col + 1):
            if (r, column) in labelled:
                break
            if (r, column) in cells:
                value = cells[(r, column)]
                break
        if value is not None:
            values.append({"row": item["row"], "field": item["field"], "text": value["text"], "cell": value["ref"],
                           "rect": value["rect"], "from_text": True})
    units = next((v["text"] for v in values if v["row"] == "Units of Measurement"), None)
    # the ticked boxes: under the group box they are in ('Company'), else 'Ticked box'
    parts = wt35_sheet_parts(path)

    def control_rect(anchor):
        c0, x0, r0, y0, c1, x1, r1, y1 = (anchor + [0] * 8)[:8]
        return (xs[min(c0, last_col)] + x0 * 0.75, ys[min(r0, last_row)] + y0 * 0.75,
                xs[min(c1, last_col)] + x1 * 0.75, ys[min(r1, last_row)] + y1 * 0.75)

    checks = []
    groups = [(c["label"], control_rect(c["anchor"])) for c in parts["checks"] if c["kind"] == "GBox"]
    for control in parts["checks"]:
        if control["kind"].lower() != "checkbox":
            continue
        box = control_rect(control["anchor"])
        inside = next((name for name, g in groups if g[0] <= box[0] and box[2] <= g[2] + 2 and g[1] <= box[1]
                       and box[3] <= g[3] + 2), None)
        label = control["label"]
        if control["ticked"] and label.rstrip(":").strip().lower() == "other":
            # 'Other:' ticked - what is typed in the cell right of it
            r, c = control["anchor"][2] + 1, control["anchor"][4] + 1
            typed = next((cells[(r, column)]["text"] for column in range(c, min(last_col, c + 4) + 1)
                          if (r, column) in cells), "")
            label = f"Other: {typed}".strip()
        checks.append({"label": label, "ticked": control["ticked"], "rect": box,
                       "row": inside or "Ticked box"})
    for row_name in dict.fromkeys(c["row"] for c in checks if c["ticked"]):
        ticked = [c for c in checks if c["ticked"] and c["row"] == row_name]
        values.append({"row": row_name, "field": None, "text": ", ".join(c["label"] for c in ticked),
                       "cell": "ticked box", "rect": None, "checks": ticked, "from_text": True})
    # the grid's readings, one row per grid row: 'A 0.000" | B 0.093" | C 0.000"'
    readings = []
    if grid:
        for number, r in sorted(grid["numbers"].items()):
            line = []
            row_cells = [(letter, cells[(r, c)]) for letter, c in grid["letters"].items() if (r, c) in cells]
            # S343: a name written in the grid with its value in the next cell ('JT' | '24380') is a value of
            # its own - its own row 'JT' = '24380', no unit added - not two readings
            named = set()
            for (letter, cell), (next_letter, next_cell) in zip(row_cells, row_cells[1:]):
                if letter in named or not re.search(r"[A-Za-z]{2,}", cell["text"]) \
                        or not re.fullmatch(r"[-\d.,/+#]+", next_cell["text"].replace(" ", "")):
                    continue
                named |= {letter, next_letter}
                values.append({"row": cell["text"].rstrip(":#").strip(), "field": None,
                               "cell": f"{letter}{number}-{next_letter}{number}", "text": next_cell["text"],
                               "rect": next_cell["rect"], "from_text": True})
            for letter, cell in row_cells:
                if letter in named:
                    continue
                reading = cell["text"]
                plain = re.fullmatch(r"-?\d*\.?\d+", reading.replace(" ", ""))
                if plain and units:                   # no unit of its own: the form's Units of Measurement
                    reading = f"{reading} {units}"
                line.append((letter, reading, cell))
                readings.append((f"{letter}{number}", reading))
            if line:
                box = (min(c["rect"][0] for _l, _t, c in line), min(c["rect"][1] for _l, _t, c in line),
                       max(c["rect"][2] for _l, _t, c in line), max(c["rect"][3] for _l, _t, c in line))
                values.append({"row": f"Grid row {number}", "field": None, "cell": f"grid row {number}",
                               "text": " | ".join(f"{letter} {text}" for letter, text, _c in line),
                               "rect": box, "from_text": True})
    # pictures: in a cell (it fills its merged cells, its shape kept) or floating on the sheet
    pictures = []
    for ref, (media, data) in parts["cell_pictures"].items():
        picture, shown = wt35_picture(data, media)
        column = re.match(r"[A-Z]+", ref).group(0)
        number = int(ref[len(column):])
        index = 0
        for letter in column:
            index = index * 26 + ord(letter) - 64
        x0, y0, x1, y1 = rect(number, index)
        scale = min((x1 - x0) / picture.width, (y1 - y0) / picture.height)
        w, h = picture.width * scale, picture.height * scale
        place = (x0 + (x1 - x0 - w) / 2, y0 + (y1 - y0 - h) / 2, x0 + (x1 - x0 + w) / 2, y0 + (y1 - y0 + h) / 2)
        pictures.append({"image": picture, "rect": place, "name": f"picture in cell {ref}", "media": media,
                         "photo": shown and number > top_of_grid})
    for floating in parts["pictures"]:
        picture, shown = wt35_picture(floating["data"], floating["media"])
        start = floating["from"]
        if start is None:
            continue
        x0 = xs[min(start[0], last_col)] + start[1] / 12700.0
        y0 = ys[min(start[2], last_row)] + start[3] / 12700.0
        if floating["to"]:
            end = floating["to"]
            x1, y1 = xs[min(end[0], last_col)] + end[1] / 12700.0, ys[min(end[2], last_row)] + end[3] / 12700.0
        elif floating["ext"]:
            x1, y1 = x0 + floating["ext"][0] / 12700.0, y0 + floating["ext"][1] / 12700.0
        else:
            continue
        group, own = floating.get("group"), floating.get("own")
        if group and own and len(group) >= 8 and len(own) >= 4 and group[6] and group[7]:
            scale_x, scale_y = (x1 - x0) / group[6], (y1 - y0) / group[7]
            x0, y0 = x0 + (own[0] - group[4]) * scale_x, y0 + (own[1] - group[5]) * scale_y
            x1, y1 = x0 + own[2] * scale_x, y0 + own[3] * scale_y
        pictures.append({"image": picture, "rect": (x0, y0, x1, y1), "media": floating["media"],
                         "name": f"picture {os.path.basename(floating['media'])}",
                         "photo": shown and start[2] + 1 > top_of_grid})        # on the grid -> its photo
    # what joins it to the other documents
    name = os.path.basename(path)
    by_row = {v["row"]: v["text"] for v in values}
    remarks = by_row.get("Remarks", "")
    number = re.search(WT35_SIX_THOUSAND, name)
    defect = re.search(WT35_DEFECT, remarks, re.IGNORECASE)
    file_values = wt35_file_name_values(name)                                              # S323
    file_defect = next((text for field, _row, text in file_values if field == "Defect name"), None)
    return {"path": path, "name": name, "sheet": sheet.title, "cells": cells, "values": values, "checks": checks,
            "grid": grid, "readings": readings, "units": units, "pictures": pictures,
            "page": (xs[-1] + WT35_MARGIN, ys[-1] + WT35_MARGIN),
            "remark_wheels": wt35_wheel_numbers(remarks, WT35_WHEEL),                       # S321: all of them
            "file_wheels": wt35_wheel_numbers(os.path.splitext(name)[0], WT35_FILE_WHEEL),
            "cell_wheels": [(v, wt35_wheel_numbers(v["text"], WT35_WHEEL)) for v in values
                            if v["row"] != "Remarks" and wt35_wheel_numbers(v["text"], WT35_WHEEL)],
            "six_thousand": number.group(1) if number else None,
            "six_thousand_date": number.group(2) if number and number.group(2) else None,
            "file_values": file_values,
            "defect": f"{' '.join(defect.group(1).split()).title()} #{defect.group(2)}" if defect
            else file_defect}                            # S323: the file name's when the Remarks name none


def wt35_form_pdf(form):
    """S320: the form as a one-page PDF for the Verify and Pages tabs - the file name on top, every
    filled cell as real PDF text in its place (a box line around it), each check box as '[X] TGT' /
    '[ ] GSP', every picture as a picture. Each value gets its box: where its words are on the page."""
    out = input_pdf_path(form["path"], "_10000-35")
    width, height = form["page"]
    document = fitz.open()
    page = document.new_page(width=width, height=height)
    page.insert_text((WT35_MARGIN, WT35_MARGIN + 10), f"File: {form['name']}", fontsize=8, fontname="helv")
    for cell in form["cells"].values():
        box = fitz.Rect(cell["rect"])
        if box.is_empty:
            continue
        page.draw_rect(box, color=(0.75, 0.75, 0.75), width=0.4)
        for size in (min(cell["size"], 10.0), 8.0, 7.0, 6.0, 5.0, 4.0):
            if page.insert_textbox(box + (1.5, 0.5, -1.0, 0), cell["text"], fontsize=size, fontname="helv") >= 0:
                break
        else:                                            # fits nowhere (a long word in a narrow cell): one line
            page.insert_text((box.x0 + 1.5, box.y0 + 7), cell["text"], fontsize=6, fontname="helv")
    for check in form["checks"]:
        x0, y0, x1, y1 = check["rect"]
        page.insert_text((x0 + 1, (y0 + y1) / 2 + 3), f"[{'X' if check['ticked'] else ' '}] {check['label']}",
                         fontsize=7, fontname="helv")
    for picture in form["pictures"]:
        # S365: the picture's pixels handed straight to the PDF (no PNG made first) - the same pixels
        image = picture["image"]
        alpha = "A" in image.getbands()
        image = image.convert("RGBA" if alpha else "RGB")
        pixels = fitz.Pixmap(fitz.csRGB, image.width, image.height, image.tobytes(), alpha)
        page.insert_image(fitz.Rect(picture["rect"]), pixmap=pixels, keep_proportion=False)
    document.save(out)
    document.close()
    with fitz.open(out) as saved:                        # the words as the saved page has them
        words = saved[0].get_text("words")

    def words_box(area):
        area = fitz.Rect(area)
        inside = [w for w in words if fitz.Rect(w[:4]).intersects(area)
                  and fitz.Rect(w[:4]).intersect(area).get_area() >= 0.5 * fitz.Rect(w[:4]).get_area()]
        if not inside:
            return tuple(area)
        return (min(w[0] for w in inside), min(w[1] for w in inside), max(w[2] for w in inside),
                max(w[3] for w in inside))

    for value in form["values"]:
        if value.get("checks"):
            boxes = [words_box(c["rect"]) for c in value["checks"]]
            value["box"] = (min(b[0] for b in boxes), min(b[1] for b in boxes), max(b[2] for b in boxes),
                            max(b[3] for b in boxes))
        elif value.get("rect"):
            value["box"] = words_box(value["rect"])
    form["file_box"] = words_box((WT35_MARGIN, WT35_MARGIN, width - WT35_MARGIN, WT35_MARGIN + WT35_FILE_LINE))
    return out


def wt35_ocr_pieces(picture, scale):
    """EasyOCR's reads of a picture: [(box in the picture's own pixels, text, confidence)]."""
    pieces = []
    for box, text, confidence in easy_reader.readtext(np.array(picture), detail=1, paragraph=False):
        xs, ys = [p[0] / scale for p in box], [p[1] / scale for p in box]
        if str(text).strip():
            pieces.append(((min(xs), min(ys), max(xs), max(ys)), str(text).strip(), float(confidence)))
    return pieces


def wt35_lines(pieces):
    """Reads side by side made into lines (top to bottom, each left to right)."""
    lines = []
    for piece in sorted(pieces, key=lambda p: (p[0][1] + p[0][3]) / 2):
        middle, height = (piece[0][1] + piece[0][3]) / 2, piece[0][3] - piece[0][1]
        line = next((l for l in lines if abs(l["middle"] - middle) < 0.5 * max(height, l["height"])), None)
        if line is None:
            lines.append({"middle": middle, "height": height, "pieces": [piece]})
        else:
            line["pieces"].append(piece)
    for line in lines:
        line["pieces"].sort(key=lambda p: p[0][0])
    return lines


def wt35_typed_values(lines, patterns, where):
    """The values the typed-text lines give: [(row, field, value, box, how sure (S384: EasyOCR's least sure
    piece of it), S379: {'line', 'spans' (each read piece's place in the line's text), 'parts' (where the
    value's own characters are in it), 'unsure' (less than WT35_PHOTO_CONFIDENCE sure - kept or left out by
    wt35_font_check)})]."""
    kept, said = [], set()
    for line in lines:
        text, spans = "", []
        for piece in line["pieces"]:
            if text:
                text += " "
            spans.append((len(text), len(text) + len(piece[1]), piece))
            text += piece[1]
        for row, field, pattern, written in patterns:
            for match in re.finditer(pattern, text, re.IGNORECASE if field != "Line ID" else 0):
                touched = [p for start, end, p in spans if start < match.end() and end > match.start()]
                sure = min(p[2] for p in touched)
                box = (min(p[0][0] for p in touched), min(p[0][1] for p in touched),
                       max(p[0][2] for p in touched), max(p[0][3] for p in touched))
                parts = [match.span(g) for g in range(1, (match.lastindex or 0) + 1) if match.span(g)[0] >= 0] \
                    or [match.span()]
                # S384: a read EasyOCR is less sure of is not dropped here - the photo's font check decides
                kept.append((row, field, written(match), box, sure,
                             {"line": text, "spans": spans, "parts": parts, "where": where,
                              "unsure": sure < WT35_PHOTO_CONFIDENCE}))
    return kept


def wt35_white_text_areas(white):
    """S356: where the photo's white typed text is - [(x0, y0, x1, y1)] in the photo's pixels. The white
    marks shaped like letters (a letter's height: 1.2-7% of the photo's height, not much wider than tall,
    not a thin line) are joined into words / lines / blocks; a block with letters in it is one area (with a
    margin). Glare and the white paint's specks are not letter-shaped and are left out."""
    mask = white.astype(np.uint8)
    height, width = mask.shape
    low, high = max(4, int(height * 0.012)), max(8, int(height * 0.07))
    count, labels, stats, _centres = cv2.connectedComponentsWithStats(mask, 8)
    keep = np.zeros(count, bool)
    for index in range(1, count):
        _x, _y, w, h, area = stats[index]
        keep[index] = low <= h <= high and w <= 3 * h and area >= 0.12 * w * h and area >= low * low / 4
    letters = keep[labels].astype(np.uint8)
    reach = max(3, (low + high) // 4)
    joined = cv2.dilate(letters, cv2.getStructuringElement(cv2.MORPH_RECT, (2 * reach + 1, reach + 1)))
    count, _labels, stats, _centres = cv2.connectedComponentsWithStats(joined, 8)
    areas = []
    for index in range(1, count):
        x, y, w, h, _area = stats[index]
        if w < 3 * low or int(letters[y:y + h, x:x + w].sum()) < low * low:
            continue
        areas.append((int(max(0, x - reach)), int(max(0, y - reach)), int(min(width, x + w + reach)),
                      int(min(height, y + h + reach))))
    return areas


def wt35_white_text_pieces(only_white, areas):
    """S356: EasyOCR's reads of the white typed text - only the areas that hold it, stacked into one picture
    (white space between them) and read in one call at 2x size, instead of the whole photo at 2x (most of
    a photo is pipe, paint and ground). Each read is put back at its spot in the photo:
    [(box in the photo's pixels, text, confidence)]."""
    if not areas:
        return []
    gap = 40
    canvas = np.full((sum(y1 - y0 for _x0, y0, _x1, y1 in areas) + gap * (len(areas) + 1),
                      max(x1 - x0 for x0, _y0, x1, _y1 in areas) + 2 * gap), 255, np.uint8)
    slots, top = [], gap
    for x0, y0, x1, y1 in areas:
        canvas[top:top + y1 - y0, gap:gap + x1 - x0] = only_white[y0:y1, x0:x1]
        slots.append((top - gap / 2, top + y1 - y0 + gap / 2, x0 - gap, y0 - top))
        top += y1 - y0 + gap
    big = cv2.resize(canvas, None, fx=2, fy=2, interpolation=cv2.INTER_CUBIC)
    pieces = []
    for box, text, confidence in wt35_ocr_pieces(cv2.cvtColor(big, cv2.COLOR_GRAY2RGB), 2.0):
        middle = (box[1] + box[3]) / 2
        slot = next((s for s in slots if s[0] <= middle <= s[1]), None)
        if slot is not None:
            dx, dy = slot[2], slot[3]
            pieces.append(((box[0] + dx, box[1] + dy, box[2] + dx, box[3] + dy), text, confidence))
    return pieces


def wt35_photo_values(picture, known=()):
    """S320: only the TYPED text of the grid's photo - never handwriting:
    1. the camera app's text block: only the pure white, colourless pixels are kept (the paint
       marker on the pipe is red or black, the pipe itself never that white) and read;
    2. a label laid on the photo ('Gouge #1'): one flat grey (a photo never has 25 pixels of
       exactly one colour) with dark text in it - only what is inside is read.
    Returns [(row, field, value, box in the picture's pixels, how sure)]."""
    rgb = np.asarray(picture.convert("RGB"))
    channels = rgb.astype(np.int16)
    white = (channels.min(axis=2) > WT35_WHITE_MIN) & \
            ((channels.max(axis=2) - channels.min(axis=2)) < WT35_WHITE_CHROMA)
    only_white = np.where(white, 0, 255).astype(np.uint8)
    areas = wt35_white_text_areas(white)
    tesseract = wt35_tesseract_start(only_white, areas)                                        # S386
    lines = wt35_lines(wt35_white_text_pieces(only_white, areas))                              # S356
    found = wt35_typed_values(lines, WT35_PHOTO_PATTERNS, "white typed text")
    if tesseract is not None:
        tesseract()
        tesseract_lines = [line for area_lines in tesseract.per_area for line in area_lines]     # S388: per area
        def shown(lines):                               # lines it was not even half sure of: counted, not shown
            sure = [line for line in lines if min(p[2] for p in line["pieces"]) >= 0.5]
            return (" | ".join(f"'{' '.join(p[1] for p in line['pieces'])}' ({min(p[2] for p in line['pieces']):.0%})"
                               for line in sure) or "nothing readable") \
                + (f" (+{len(lines) - len(sure)} line(s) of noise)" if len(lines) > len(sure) else "")
        print(f"10000-35 PHOTO: Tesseract read {len(areas)} white-text area(s), each on its own, in "
              f"{tesseract.seconds:.1f} s: "
              + "; ".join(f"area {n} - {shown(area_lines)}" for n, area_lines in enumerate(tesseract.per_area, start=1))
              + " (S387/S388)")
        found = wt35_combine_reads(found, wt35_typed_values(tesseract_lines, WT35_PHOTO_PATTERNS,
                                                            "white typed text, Tesseract"))
    found = wt35_font_check(white, found, known)                                               # S379
    # the flat grey labels
    grey = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
    neutral = (np.abs(channels[:, :, 0] - channels[:, :, 1]) <= 2) & \
              (np.abs(channels[:, :, 1] - channels[:, :, 2]) <= 2)
    spread = cv2.dilate(grey, np.ones((5, 5), np.uint8)).astype(np.int16) - \
        cv2.erode(grey, np.ones((5, 5), np.uint8)).astype(np.int16)
    flat = (neutral & (spread <= WT35_TAG_FLAT)).astype(np.uint8)
    joined = cv2.morphologyEx(flat, cv2.MORPH_CLOSE, cv2.getStructuringElement(cv2.MORPH_RECT, (61, 15)))
    count, _labels, stats, _centres = cv2.connectedComponentsWithStats(joined, 8)
    for index in range(1, count):
        x, y, w, h, _area = stats[index]
        if h < 12 or w < 30 or not 1.5 <= w / h <= 15:
            continue
        inside = grey[y:y + h, x:x + w].astype(np.int16)
        fill = int(np.median(inside[flat[y:y + h, x:x + w] > 0])) if flat[y:y + h, x:x + w].any() else None
        if fill is None:
            continue
        exact = (np.abs(inside - fill) <= 4).mean()
        dark = (inside < 90).mean()
        covered = ((np.abs(inside - fill) <= 4) | (inside < fill - 4)).mean()
        if exact < WT35_TAG_MIN_FILL or covered < WT35_TAG_MIN_COVER or dark < 0.03:
            continue
        crop = Image.fromarray(rgb[y:y + h, x:x + w]).resize((w * 3, h * 3), Image.LANCZOS)
        pieces = [((x + b[0], y + b[1], x + b[2], y + b[3]), t, c) for b, t, c in wt35_ocr_pieces(crop, 3.0)]
        text = " ".join(p[1] for p in sorted(pieces, key=lambda p: p[0][0]))
        label = re.fullmatch(WT35_TAG_PATTERN, text.strip())
        if not pieces or not label:
            if pieces:
                print(f"10000-35 PHOTO: grey label '{text}' left out - not a defect label like 'Gouge #1' (S320)")
            continue
        sure = min(p[2] for p in pieces)
        if sure < WT35_PHOTO_CONFIDENCE:
            print(f"10000-35 PHOTO: grey label '{text}' left out - EasyOCR only {sure:.0%} sure of it (S320)")
            continue
        found.append(("Defect name", "Defect name", f"{' '.join(label.group(1).split()).title()} #{label.group(2)}",
                      (x, y, x + w, y + h), sure, None))
    return found


# ============================================================
# S386: TESSERACT - A SECOND READER FOR THE PHOTO'S TYPED TEXT. Once only the photo's pure white letters
# are kept, the camera app's text is clean printed text - what Tesseract reads best. It reads the same
# white-text areas (S388: each in a run of its own, on the processor, while EasyOCR reads them on the GPU;
# S389: only its letter-shaped marks - not the glare under a stamp in bright sun - at a size set by its
# letter height - photos' stamps differ in size).
# A value both read the same is sure, however unsure EasyOCR was; a value only Tesseract's read gives - or that the two read
# differently - is kept only when the form has it or the photos' font confirms it (S384).
# ============================================================
WT35_TESSERACT_LETTER_PX = 25        # S389: letters at least this tall are read at their own size (enlarging
WT35_TESSERACT_TARGET_PX = 30        # big ones blurred them into the glare); smaller ones are enlarged to this
WT35_TESSERACT_RUNS = 2              # S392: photo Tesseract runs at one time (the Dig Packets need the processor)


def wt35_tesseract_start(only_white, areas):
    """S386: Tesseract starts reading the photo's white-text areas on its own threads. S388: each area in a run of
    its own (a few at a time) - bright bits of pipe or glare taken for letters are areas too, and read together
    with the stamp in one picture they broke Tesseract's lines apart. Returns a function giving its reads
    [(box in the photo's pixels, text, how sure)] (also each area's lines, for the log), or None when Tesseract
    is not installed."""
    if not areas or not tesseract_program():
        return None
    import subprocess
    from concurrent.futures import ThreadPoolExecutor
    gap = 40

    low, high = max(4, int(only_white.shape[0] * 0.012)), max(8, int(only_white.shape[0] * 0.07))   # as S356

    def read_area(area, cleaned):
        x0, y0, x1, y1 = area
        count, labels, stats, _centres = cv2.connectedComponentsWithStats((only_white[y0:y1, x0:x1] == 0).astype(np.uint8), 8)
        keep = np.ones(count, bool)
        if cleaned:
            # S389: only the letter-shaped white marks (and the small ones a letter has - points, commas, dashes,
            # an i's dot); the glare a stamp sits on in bright sun is left out - it broke Tesseract's lines apart
            for index in range(1, count):
                _x, _y, w, h, size = stats[index]
                keep[index] = (low <= h <= high and w <= 3 * h and size >= 0.12 * w * h and size >= low * low / 4) or \
                              (h < low and w <= high and size >= 6 and size >= 0.3 * w * h)
        keep[0] = False
        canvas = np.full((y1 - y0 + 2 * gap, x1 - x0 + 2 * gap), 255, np.uint8)
        canvas[gap:gap + y1 - y0, gap:gap + x1 - x0] = np.where(keep[labels], 0, 255).astype(np.uint8)
        # S389: the area's letter height decides its size - big letters as they are, small ones enlarged
        heights = [stats[i, 3] for i in range(1, count)
                   if keep[i] and stats[i, 4] > 20 and stats[i, 3] > 8 and stats[i, 2] < 3 * stats[i, 3]]
        letter = float(np.median(heights)) if heights else WT35_TESSERACT_LETTER_PX
        scale = 1.0 if letter >= WT35_TESSERACT_LETTER_PX else min(3.0, WT35_TESSERACT_TARGET_PX / max(1.0, letter))
        big = Image.fromarray(canvas)
        if scale != 1.0:
            big = big.resize((round(canvas.shape[1] * scale), round(canvas.shape[0] * scale)), Image.LANCZOS)
        picture = io.BytesIO()
        big.save(picture, "PNG")
        done = subprocess.run([tesseract_program(), "stdin", "stdout", "--psm", "6", "tsv"], input=picture.getvalue(),
                              capture_output=True, timeout=TESSERACT_TIMEOUT_S, env=dict(os.environ, OMP_THREAD_LIMIT="1"),
                              creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        pieces = []
        for line in done.stdout.decode("utf-8", errors="replace").splitlines()[1:]:
            parts = line.split("\t")
            if len(parts) < 12 or parts[0] != "5" or not parts[11].strip():
                continue
            left, top, width, height = (int(v) / scale for v in parts[6:10])
            pieces.append(((left + x0 - gap, top + y0 - gap, left + width + x0 - gap, top + height + y0 - gap),
                           parts[11].strip(), max(0.0, float(parts[10])) / 100))
        return pieces

    started = time.perf_counter()

    def read_twice_if_text(area):
        """S390/S392: the area with only its letter-shaped marks (S389 - no glare); only when that finds real text
        (a line Tesseract is at least half sure of - the stamp) it is read again as it is, which keeps every
        point and comma (which of the two reads better changes from photo to photo)."""
        cleaned = read_area(area, True)
        if not any(min(p[2] for p in line["pieces"]) >= 0.5 for line in wt35_lines(cleaned)):
            return [cleaned]
        return [cleaned, read_area(area, False)]

    # S392: at most 2 runs at a time - the Dig Packets are read meanwhile and need the processor too
    pool = ThreadPoolExecutor(max_workers=min(WT35_TESSERACT_RUNS, len(areas)), thread_name_prefix="tesseract-photo")
    futures = [pool.submit(read_twice_if_text, area) for area in areas]
    pool.shutdown(wait=False)

    def result():
        pieces, per_area = [], []
        for future in futures:
            lines, seen = [], set()
            try:
                reads = future.result(timeout=2 * TESSERACT_TIMEOUT_S)
            except Exception as exc:
                print(f"10000-35 PHOTO: Tesseract could not read an area ({type(exc).__name__}: {exc}) (S386)")
                reads = []
            for found in reads:
                pieces += found
                for line in wt35_lines(found):          # a line both reads gave the same: once
                    text = " ".join(p[1] for p in line["pieces"])
                    if text not in seen:
                        seen.add(text)
                        lines.append(line)
            per_area.append(lines)
        result.per_area = per_area
        result.seconds = time.perf_counter() - started
        return pieces
    return result


def wt35_combine_reads(easy, tesseract):
    """S386: EasyOCR's and Tesseract's values of the photo's typed text, side by side. A value both read the
    same: sure. One only Tesseract has, or Tesseract's different read of one: added as an unsure read
    (wt35_font_check keeps it only when the form has it or the font confirms it)."""
    combined, used = [], set()
    for row, field, value, box, sure, place in easy:
        same = next((n for n, t in enumerate(tesseract) if n not in used and t[0] == row
                     and wt35_known_text(t[2]) == wt35_known_text(value)), None)
        if same is not None and place is not None:
            used.add(same)
            if place.get("unsure"):
                print(f"10000-35 PHOTO: {row} '{value}' - EasyOCR was only {sure:.0%} sure, Tesseract read it the "
                      f"same -> sure (S386)")
            place = dict(place, unsure=False, agreed=True)
        combined.append((row, field, value, box, sure, place))
    said = set()
    for n, (row, field, value, box, sure, place) in enumerate(tesseract):
        if n in used or place is None or (row, wt35_known_text(value)) in said:
            continue
        if any(t[0] == row and wt35_known_text(t[2]) == wt35_known_text(value) for k, t in enumerate(tesseract)
               if k in used):
            continue                                   # S390: its other read of the same line - already agreed
        said.add((row, wt35_known_text(value)))
        other = next((e for e in easy if e[0] == row), None)
        print(f"10000-35 PHOTO: {row} - Tesseract read '{value}'"
              + (f", EasyOCR '{other[2]}'" if other else ", EasyOCR did not") + " - checked like an unsure read (S386)")
        combined.append((row, field, value, box, sure, dict(place, unsure=True, tesseract=True)))
    return combined


# ============================================================
# S379: THE PHOTO'S FONT - the camera app's typed text is one font. Its read values the form itself also has
# (the date, PN, Line ID, OD, WT, wheel counts ...) show what each of its characters looks like - added up
# over every photo read in the run; a value only the photo has is then checked character by character
# against them, like the table's typed-text check (S375). One that passes is confirmed without being
# listed on the Verify tab.
# ============================================================
WT35_FONT_MIN_SAMPLES = 2            # each character of a value needs this many examples from the known values
WT35_TWO_MARKS = set('"“”')     # characters that are two marks side by side
WT35_FONT_SEEN = {}                  # character -> shapes learned from the photos read before in this run
WT35_FONT_AGREE = 0.8                # S384: a learned shape is kept only when it looks this much like the others


def wt35_consistent(group, shape_of=lambda item: item):
    """S384: a character's learned shapes, without the ones that do not look like the rest (a word whose marks
    were matched to the wrong letters - two letters touching while another one breaks in two). A character
    with fewer than two shapes that agree is not learned at all ([])."""
    if len(group) < 2:
        return list(group)
    shapes = [shape_of(item) for item in group]
    total = sum(shapes)
    kept = []
    for item, shape in zip(group, shapes):
        rest = total - shape
        if float((shape * rest).sum() / (np.sqrt((rest * rest).sum()) + 1e-9)) >= WT35_FONT_AGREE:
            kept.append(item)
    return kept if len(kept) >= 2 else []


def wt35_known_text(text):
    return re.sub(r"\s+", "", str(text or "").lower().replace("”", '"').replace("“", '"').replace("×", "x"))


def wt35_piece_glyphs(white, box, text):
    """S379: a read piece's characters cut out of the photo's white typed text - one column of ink per mark;
    [shape or None per character of `text` (None: a space or a two-mark character)], or None when the
    marks do not line up one-to-one with its characters."""
    x0, y0, x1, y1 = (int(round(v)) for v in box)
    ink = white[max(0, y0 - 2):y1 + 2, max(0, x0 - 2):x1 + 2]
    if not ink.any():
        return None
    rows = np.where(ink.any(axis=1))[0]
    ink = ink[rows.min():rows.max() + 1]
    height = ink.shape[0]
    segments, start = [], None
    for x, used in enumerate(list(ink.any(axis=0)) + [False]):
        if used and start is None:
            start = x
        elif not used and start is not None:
            segments.append(ink[:, start:x])
            start = None
    wanted = sum(2 if c in WT35_TWO_MARKS else 1 for c in text if not c.isspace())
    if len(segments) != wanted:
        return None
    shapes, marks = [], iter(segments)
    for character in text:
        if character.isspace():
            shapes.append(None)
            continue
        piece = next(marks)
        if character in WT35_TWO_MARKS:
            next(marks)
            shapes.append(None)
            continue
        used = np.where(piece.any(axis=1))[0]
        glyph = piece[used.min():used.max() + 1]
        side = max(height, glyph.shape[1])
        square = np.zeros((side, side), bool)
        top = min(used.min(), side - glyph.shape[0])
        left = (side - glyph.shape[1]) // 2
        square[top:top + glyph.shape[0], left:left + glyph.shape[1]] = glyph
        small = np.asarray(Image.fromarray((square * 255).astype("uint8")).resize((TYPED_SIZE, TYPED_SIZE),
                                                                                    Image.BILINEAR)).astype(float)
        small -= small.mean()
        shapes.append(small / (np.sqrt((small * small).sum()) + 1e-9))
    return shapes


def wt35_font_check(white, found, known):
    """S379: the photo's typed values the form also has teach the font (with what the photos read before in
    this run taught - the same camera app's font); each value only the photo has gets a verdict ('typed')
    from it. Returns the values as (row, field, value, box, how sure, verdict or None)."""
    known_texts = {wt35_known_text(k) for k in known if str(k or "").strip()}
    lines = {}
    for row, field, value, box, sure, place in found:
        if place is not None:
            lines.setdefault(place["line"], place["spans"])
    glyphs = {}                                         # (line, position in it) -> shape
    for line, spans in lines.items():
        for start, _end, piece in spans:
            shapes = wt35_piece_glyphs(white, piece[0], piece[1])
            for offset, shape in enumerate(shapes or []):
                if shape is not None:
                    glyphs[(line, start + offset)] = shape

    def is_known(value):
        return wt35_known_text(value) in known_texts or all(wt35_known_text(part) in known_texts
                                                            for part in re.split(r"\s+-\s+", str(value)))

    def first_samples(entries):
        found_samples = {}
        for row, field, value, box, sure, place in entries:
            if place is None or not is_known(value):
                continue
            for start, end in place["parts"]:
                for position in range(start, end):
                    character = place["line"][position]
                    if character.isalnum() and (place["line"], position) in glyphs:
                        found_samples.setdefault(character, []).append(glyphs[(place["line"], position)])
        return found_samples

    # S384: a read one letter off a value the form has ('Carthagc' / 'Carthage'): when that letter's mark looks
    # more like the form's letter than like the one read, the form's spelling is the read
    seen = first_samples(found)
    for character, shapes in WT35_FONT_SEEN.items():
        seen.setdefault(character, []).extend(shapes)
    seen = {character: wt35_consistent(shapes) for character, shapes in seen.items()}
    fixed = []
    for row, field, value, box, sure, place in found:
        if place is not None and not is_known(value) and len(place["parts"]) == 1:
            start, end = place["parts"][0]
            read = place["line"][start:end]
            for other in known:
                other = str(other or "").strip()
                wrong = [i for i in range(len(read)) if len(other) == len(read) and read[i] != other[i]]
                if len(other) != len(read) or len(wrong) != 1 or not read[wrong[0]].isalpha() \
                        or not other[wrong[0]].isalpha():
                    continue
                shape = glyphs.get((place["line"], start + wrong[0]))
                theirs, mine = seen.get(other[wrong[0]]), seen.get(read[wrong[0]])
                if shape is None or not theirs:
                    continue
                score = lambda group: float((shape * sum(group)).sum() / (np.sqrt((sum(group) ** 2).sum()) + 1e-9))
                if score(theirs) >= WT35_FONT_AGREE and score(theirs) - (score(mine) if mine else 0.0) >= TYPED_MARGIN:
                    print(f"10000-35 PHOTO FONT: {row} read '{read}' - its '{read[wrong[0]]}' looks like the "
                          f"'{other[wrong[0]]}' of the photos' font ({score(theirs):.2f}"
                          + (f" vs {score(mine):.2f}" if mine else "") + f") -> '{other}', as the form has it (S384)")
                    line = place["line"][:start] + other + place["line"][end:]
                    for key in [k for k in glyphs if k[0] == place["line"]]:
                        glyphs[(line, key[1])] = glyphs[key]
                    place = dict(place, line=line)
                    value = other
                    break
        fixed.append((row, field, value, box, sure, place))
    found = fixed

    samples = {}                                        # character -> [(line, position, shape)]
    taught = []
    for row, field, value, box, sure, place in found:
        if place is None or not is_known(value):
            continue
        taught.append(f"{row} '{value}'")
        for start, end in place["parts"]:
            for position in range(start, end):
                character = place["line"][position]
                if character.isalnum() and (place["line"], position) in glyphs:
                    samples.setdefault(character, []).append((place["line"], position, glyphs[(place["line"], position)]))
    if taught:
        print(f"10000-35 PHOTO FONT: learned from the value(s) the form also has - {', '.join(taught)} - "
              + ", ".join(f"'{c}' x{len(s)}" for c, s in sorted(samples.items()))
              + (f"; with the {sum(len(v) for v in WT35_FONT_SEEN.values())} learned from the photos read before"
                 if WT35_FONT_SEEN else "") + " (S379)")
    learned_here = {c: list(group) for c, group in samples.items()}
    for character, shapes in WT35_FONT_SEEN.items():     # the same camera app's font on the other photos too
        samples.setdefault(character, []).extend((None, n, shape) for n, shape in enumerate(shapes))
    samples = {c: wt35_consistent(group, lambda item: item[2]) for c, group in samples.items()}       # S384
    samples = {c: group for c, group in samples.items() if group}
    checked, from_tesseract = [], set()
    for row, field, value, box, sure, place in found:
        verdict = None
        how = ("only Tesseract read it this way" if place is not None and place.get("tesseract")      # S386
               else f"EasyOCR was only {sure:.0%} sure")
        if place is not None and place.get("unsure") and is_known(value):          # S384
            print(f"10000-35 PHOTO: {row} '{value}' kept although {how} - the form has the same value; its "
                  f"characters taught the photos' font (S384)")
        if place is not None and not is_known(value) and samples:
            why = None
            positions = [p for start, end in place["parts"] for p in range(start, end)
                         if place["line"][p].isalnum()]
            for position in positions:
                character = place["line"][position]
                shape = glyphs.get((place["line"], position))
                if shape is None:
                    why = "its characters could not be cut apart in the photo"
                    break
                own = [s for line, p, s in samples.get(character, []) if (line, p) != (place["line"], position)]
                if len(own) < WT35_FONT_MIN_SAMPLES:
                    why = f"too few examples of '{character}' in the values the form also has"
                    break
                templates = {c: sum(s for line, p, s in group if (line, p) != (place["line"], position))
                             for c, group in samples.items()}
                scores = {c: float((shape * t).sum() / (np.sqrt((t * t).sum()) + 1e-9))
                          for c, t in templates.items() if np.any(t)}
                rival = max((c for c in scores if c != character), key=scores.get, default=None)
                if rival is not None and scores[character] - scores[rival] < TYPED_MARGIN:
                    why = f"its '{character}' looks too much like '{rival}' ({scores[character]:.2f} vs {scores[rival]:.2f})"
                    break
            verdict = {"value": str(value).replace(" ", ""), "ok": why is None,
                       "why": "every character matches the photos' typed font (learned from their values the "
                              "forms also have)" if why is None else why}
            print(f"10000-35 PHOTO FONT: {row} '{value}' - "
                  + (verdict["why"] + " -> confirmed by the typed-text check" if why is None
                     else why + " -> not confirmed by it") + " (S379)")
        if place is not None and place.get("unsure") and not is_known(value) and not (verdict and verdict["ok"]):
            print(f"10000-35 PHOTO: {row} '{value}' ({place['where']}) left out - {how} (EasyOCR needs "
                  f"{WT35_PHOTO_CONFIDENCE:.0%}, or Tesseract the same read) and the photos' font does not confirm it "
                  f"(S320/S384/S386)")
            continue
        if place is not None and place.get("unsure") and verdict and verdict["ok"]:
            print(f"10000-35 PHOTO: {row} '{value}' kept although {how} - every character matches the photos' font "
                  f"(S384)")
        checked.append((row, field, value, box, sure, verdict))
        if place is not None and place.get("tesseract"):
            from_tesseract.add(id(checked[-1]))
    # S386: two different reads of one row (EasyOCR's and Tesseract's) - the one the form has, else the one the
    # font confirms, else EasyOCR's. S387: of two the form both has, the fuller one ('100553.07 - 100572.03'
    # over '100553.07')
    def rank(entry):
        return (is_known(entry[2]), bool(entry[5] and entry[5]["ok"]),
                len(wt35_known_text(entry[2])) if is_known(entry[2]) else 0, id(entry) not in from_tesseract)

    best = []
    for item in checked:
        rivals = [other for other in checked if other[0] == item[0] and other is not item]
        if not rivals:
            best.append(item)
        elif max(sorted(rivals + [item], key=lambda e: next(n for n, c in enumerate(checked) if c is e)),
                 key=rank) is item:                     # of equals, the first read (EasyOCR's) is kept
            best.append(item)
            print(f"10000-35 PHOTO: {item[0]} - '{item[2]}' kept over " + ", ".join(f"'{o[2]}'" for o in rivals)
                  + " (S386)")
    checked = best
    for character, group in learned_here.items():
        WT35_FONT_SEEN.setdefault(character, []).extend(shape for _line, _p, shape in group)
        WT35_FONT_SEEN[character] = wt35_consistent(WT35_FONT_SEEN[character]) or WT35_FONT_SEEN[character]
    return checked


def read_wt35_document(document, ocr=True):
    """S320: a 10000-35 wall thickness form's values: its cells exactly ('from_text'), and - when
    ocr - the typed text on its grid's photo (checked on the Verify tab like any picture read).
    Returns {'path' (its PDF), 'pages' (like an other document's), 'form'}."""
    form = document["wt35"]
    print()
    print("10000-35 WALL THICKNESS FORM:", document["original"])
    with timed("10000-35 form"):
        progress_step("Form cells")
        cell_values = []
        for value in form["values"]:
            cell_values.append({"field": value["field"], "label": value["row"], "text": value["text"],
                                "box": value.get("box"), "where": f"cell {value['cell']}"})
        if form["defect"]:
            remarks = next((v for v in form["values"] if v["row"] == "Remarks"), None)
            cell_values.append({"field": "Defect name", "label": "Defect name (from the Remarks)",
                                "text": form["defect"], "box": remarks.get("box") if remarks else None,
                                "where": f"cell {remarks['cell']} (Remarks)" if remarks else "Remarks"})
        # S321: every wheel count the form names - both of a range - each a Wheel Count value of its own
        remarks = next((v for v in form["values"] if v["row"] == "Remarks"), None)
        for wheel in form["remark_wheels"]:
            cell_values.append({"field": "Wheel Count", "label": "Wheel Count (from the Remarks)",
                                "text": wheel, "box": remarks.get("box") if remarks else None,
                                "where": f"cell {remarks['cell']} (Remarks)" if remarks else "Remarks"})
        for wheel in form["file_wheels"]:
            cell_values.append({"field": "Wheel Count", "label": "Wheel Count (from the file name)",
                                "text": wheel, "box": form.get("file_box"), "where": "file name"})
        for value, wheels in form["cell_wheels"]:
            for wheel in wheels:
                cell_values.append({"field": "Wheel Count", "label": f"Wheel Count (from {value['row']})",
                                    "text": wheel, "box": value.get("box"), "where": f"cell {value['cell']}"})
        if form["six_thousand"]:
            cell_values.append({"field": None, "label": "6000 form number (from the file name)",
                                "text": form["six_thousand"], "box": form.get("file_box"), "where": "file name"})
        for field, row, text in form.get("file_values") or []:                             # S323
            cell_values.append({"field": field, "label": row if field is None or row in WT35_SHARED_ROWS
                                else f"{row} (from the file name)", "text": text, "box": form.get("file_box"),
                                "where": "file name"})
        for value in cell_values:
            print(f"  10000-35 FORM: {value['label']} = {value['text']!r} ({value['where']}) (S320)")
        progress_step("Photo printed text (OCR)")
        photo_values = []
        photos = [p for p in form["pictures"] if p["photo"]]
        for picture in photos if ocr else []:
            x0, y0, x1, y1 = picture["rect"]
            scale_x, scale_y = (x1 - x0) / picture["image"].width, (y1 - y0) / picture["image"].height
            with timed(f"Photo typed text ({picture['name']})", 1):
                known = [v["text"] for v in cell_values] + [c["text"] for c in form["cells"].values()]     # S379
                for row, field, text, box, sure, typed in wt35_photo_values(picture["image"], known):
                    photo_values.append({"field": field, "label": row, "text": text,
                                         "box": (x0 + box[0] * scale_x, y0 + box[1] * scale_y,
                                                 x0 + box[2] * scale_x, y0 + box[3] * scale_y),
                                         "where": f"photo ({picture['name']}) typed text, {sure:.0%} sure",
                                         "typed": typed})
                    print(f"  10000-35 PHOTO: {row} = {text!r} ({picture['name']}, EasyOCR {sure:.0%} sure) (S320)")
        if photos and not ocr:
            print(f"10000-35 FORM: its photo was not read (the OCR models did not load) - the cells only (S320)")
        elif not photos:
            print("10000-35 FORM: no photo on its grid (S320)")
    # S321: the wheel counts this document names - the cells' and file name's, and the ones in the photo's
    # typed text that were kept (sure enough) - each once
    wheels, named_by = [], {}
    sources = [(v["text"], v["where"]) for v in cell_values if v["field"] == "Wheel Count"]
    sources += [(number, "photo") for v in photo_values if v["label"] == "Photo wheel counts"
                for number in re.findall(r"\d{4,}\.\d+", v["text"])]
    for text, where in sources:
        key = priority_ident(text)["wc"]
        if key is None:
            continue
        if key not in named_by:
            wheels.append(key)
        named_by.setdefault(key, []).append(where)
    print(f"10000-35 FORM: {len(cell_values)} value(s) from the cells, {len(photo_values)} from the photo's "
          f"typed text; {len(form['readings'])} grid reading(s)"
          + (f"; wheel count(s) named: " + ", ".join(f"{w} ({', '.join(dict.fromkeys(named_by[w]))})" for w in wheels)
             if wheels else "; no wheel count named")
          + (f"; names 6000 form {form['six_thousand']}" if form["six_thousand"] else "") + " (S320/S321)")
    pages = [{"page": 1, "wheel": wheels[0] if wheels else None, "values": cell_values, "from_text": True}]
    if photo_values:
        pages.append({"page": 1, "wheel": wheels[0] if wheels else None, "values": photo_values, "from_text": False})
    return {"path": document["path"], "pages": pages, "form": form, "wheels": wheels}


def wt35_six_thousand_link(document, label, forms, labels):
    """S320: the 6000 form the 10000-35 form's file name names ('..._6000-10-233-08192026') - when a
    6000 form with that number in its own file name was dropped in AND what they both give agrees:
    the same Project Number and Wheel Count (when both have them - one different and they are not
    joined), and at least 2 of Project Number, Wheel Count, Nominal OD, Nominal Wall Thickness, Class
    Location, MAOP and Operating Area the same, more the same than different. Returns that 6000 form
    or None. What was compared is said in the terminal whenever it changes."""
    form = document["result"]["form"]
    number = form.get("six_thousand")
    if not number:
        return None
    named = [six for six in forms if re.search(r"(?<![0-9])" + re.escape(number) + r"(?![0-9])",
                                               os.path.basename(six.get("original", six["path"])))]
    if form.get("six_thousand_date"):                    # the one with the same date first
        named.sort(key=lambda six: form["six_thousand_date"] not in os.path.basename(six.get("original", six["path"])))
    mine = {v["row"]: v["text"] for v in form["values"]}
    for six in named:
        extracted = six["result"][1]

        def theirs(field):
            return str((extracted.get(field) or {}).get("value") or "").strip()
        wheels = document["result"].get("wheels") or []
        their_wheel = theirs("Wheel Count")              # S321: the same as any wheel count the form names
        mine_wheel = next((w for w in wheels if wheel_same(wheel_text(w), wheel_text(their_wheel))),
                          " / ".join(wheels))                              # S438: exactly
        checks = [("Project Number", mine.get("Project Number"), theirs("Project Number"), 1e-6),
                  ("Wheel Count", mine_wheel, their_wheel, "wheel"),             # S438: exactly
                  ("Nominal OD", mine.get("Nominal OD"), theirs("Nominal OD (in)"), 1e-6),
                  ("Nominal Wall Thickness", mine.get("Nominal Wall Thickness"), theirs("Nominal Wall Thickness"), 1e-6),
                  ("Class Location", mine.get("Class Location"), theirs("Class Location"), 1e-6),
                  ("MAOP", mine.get("MAOP"), theirs("MAOP"), 1e-6),
                  ("Operating Area", mine.get("Operating Area"), theirs("Operating Area"), None)]
        agree, differ, said = [], [], []
        for name, a, b, tolerance in checks:
            if not a or not b:
                said.append(f"{name}: not on both")
                continue
            if tolerance is None:                        # words: the same, or one inside the other
                one, two = wt35_label_key(a), wt35_label_key(b)
                same = bool(one and two) and (one == two or one in two or two in one)
            elif tolerance == "wheel":
                same = wheel_same(wheel_text(a), wheel_text(b))
            else:
                same = cmp_same_number(a, b, tolerance)
            (agree if same else differ).append(name)
            said.append(f"{name} '{a}' {'=' if same else '≠'} '{b}'")
        key_differs = [name for name in ("Project Number", "Wheel Count") if name in differ]
        linked = not key_differs and len(agree) >= 2 and len(agree) > len(differ)
        why = (f"its {' and '.join(key_differs)} {'is' if len(key_differs) == 1 else 'are'} different" if key_differs
               else f"only {len(agree)} the same and {len(differ)} different")
        message = (f"10000-35 LINK: {label} names 6000 form {number}; {labels.get(id(six), six['name'])} has it in its "
                   f"file name - {'; '.join(said)} -> " + ("joined: its values go in that 6000 form's column"
                                                           if linked else f"NOT joined ({why})") + " (S320)")
        if WT35_LINK_SAID.get((id(document), id(six))) != message:
            WT35_LINK_SAID[(id(document), id(six))] = message
            print(message)
        if linked:
            return six
    if not named and WT35_LINK_SAID.get((id(document), number)) != "none":
        WT35_LINK_SAID[(id(document), number)] = "none"
        print(f"10000-35 LINK: {label} names 6000 form {number} - no 6000 form with that number in its file name "
              f"was dropped in; it goes by its own Wheel Count (S320)")
    return None


def wt35_detail_match(document, label, wheels, others):
    """S321: a form naming more than one wheel count ('WC: 100553.07 - 100572.03'): what it says about the
    pipe (OD, WT, SMYS, Class Location, defect name, Project Number, MAOP, Operating Area) next to what the
    other documents say at each of those wheel counts. When it matches EXACTLY at one wheel count (at
    least one thing compared, nothing different) and matches NOTHING at every other one (nothing the
    same - different, or no document there), it is that one's only; otherwise it is kept at every one
    of them, so nothing is left out. Returns the wheel counts its values go to."""
    form = document["result"]["form"]
    mine = {v["row"]: v["text"] for v in form["values"]}
    packets = {b.get("owner"): b for b in others if b.get("packet")}
    scores, said = {}, []
    for wheel in wheels:
        there = [b for b in others if (b.get("ident") or {}).get("wc") == wheel and not b.get("packet")]
        there += [packets[b.get("owner")] for b in list(there) if b.get("owner") in packets]
        same, different, lines = 0, 0, []
        for field, row, tolerance in WT35_DETAILS:
            ours = form.get("defect") if field == "Defect name" else mine.get(row)
            key = field if field in PRIORITY_FIELDS else priority_other_key(field)
            texts = [priority_entry_text(e) for b in there for e in b["fields"].get(key, [])]
            texts = list(dict.fromkeys(t for t in texts if t and t != "(not found in this text)"))
            if not ours or not texts:
                continue
            if tolerance is None:
                mine_key = wt35_label_key(ours)
                hit = any(wt35_label_key(t) and (wt35_label_key(t) in mine_key or mine_key in wt35_label_key(t))
                          for t in texts)
            else:
                hit = any(cmp_same_number(ours, t, tolerance) for t in texts)
            same, different = same + hit, different + (not hit)
            lines.append(f"{field} '{ours}' {'=' if hit else '≠'} '{texts[0]}'")
        scores[wheel] = (same, different)
        said.append(f"{wheel}: " + ("; ".join(lines) if lines else
                                    "no other document there" if not there else "nothing to compare"))
    exact = [w for w in wheels if scores[w][0] >= 1 and scores[w][1] == 0]
    chosen = (exact if len(exact) == 1 and all(scores[w][0] == 0 for w in wheels if w != exact[0])
              else list(wheels))
    message = (f"10000-35 WHEEL COUNTS: {label} names {' and '.join(wheels)} - {' | '.join(said)} -> "
               + (f"matches only {chosen[0]} - its values go there" if len(chosen) == 1
                  else "kept for every one of them (not one clear match)") + " (S321)")
    if WT35_WHEELS_SAID.get(id(document)) != message:
        WT35_WHEELS_SAID[id(document)] = message
        print(message)
    return chosen


def wt35_name_words(name):
    """S322: the words that say what kind of defect a name is - 'Gouge #3' -> {'gouge'},
    'External Metal Loss' -> {'external', 'metal', 'loss'} (numbers, '#' and filler words left out)."""
    return {w for w in re.findall(r"[a-z]{3,}", str(name or "").lower()) if w not in WT35_NAME_FILLER}


def wt35_like_names(one, two):
    """S322: names of the same kind - every word of one is in the other ('Gouge' / 'Gouge #3')."""
    a, b = wt35_name_words(one), wt35_name_words(two)
    return bool(a and b) and (a <= b or b <= a)


def wt35_inches(entry, text):
    """S322: a length value in inches (mils, ft, mm turned into inches); None for a %, or no unit known."""
    scale = VERIFY_UNIT_SCALE.get(verify_unit_key(entry, text) or "")
    number = cmp_first_number(text)
    return number * scale[1] if scale and scale[0] == "length" and number is not None else None


def wt35_place(ident):
    """S327: where a defect is - ('wc', its Wheel Count), else ('mp', its Mile Post), else None."""
    ident = ident or {}
    return ("wc", ident["wc"]) if ident.get("wc") else ("mp", ident["mp"]) if ident.get("mp") else None


def wt35_known_defects(others):
    """S322: every defect the other documents give - one per dig / per 6000 form defect section
    ('Section F, anomaly 1') with a defect name: {'key', 'wc', 'place', 'ident', 'names', 'depths' (inches),
    'documents', 'field', 'inspection'}. The same kind of name at the same place is one defect (a dig and
    its 6000 form). S327: a 6000 form's defect is what the crew found ('field'); a Dig Packet's own name is
    the inspection data's - when the two name a different kind of defect at the same place it is still ONE
    defect, named by the field, the inspection data's name kept with it ('inspection')."""
    records = []
    for block in others:
        if block.get("packet") or block.get("end_table_only"):
            continue
        parts = {}
        for field in ("Defect name", "Depth"):
            for entry in block["fields"].get(field, []):
                part = re.search(r"Section ([A-Z]), anomaly (\d+)", entry["source"])
                parts.setdefault(part.group(0) if part else "", {"Defect name": [], "Depth": []})[field].append(entry)
        for part, found in parts.items():
            names = [t for t in (priority_entry_text(e) for e in found["Defect name"])
                     if t != "(not found in this text)"]
            if not names:
                continue
            depths = [d for d in (wt35_inches(e, priority_entry_text(e)) for e in found["Depth"]) if d is not None]
            field_made = block.get("crew") or all(str(e["source"]).startswith("6000 ") for e in found["Defect name"])
            records.append({"wc": (block.get("ident") or {}).get("wc"), "ident": dict(block.get("ident") or {}),
                            "place": wt35_place(block.get("ident")), "names": list(dict.fromkeys(names)),
                            "depths": depths, "field": field_made, "inspection": [],
                            "documents": list(dict.fromkeys(verify_document_of(e["source"])
                                                            for e in found["Defect name"]))})
    defects = []
    for record in records:
        home = next((d for d in defects if d["place"] == record["place"]
                     and any(wt35_like_names(a, b) for a in d["names"] for b in record["names"])), None)
        if home is None:
            defects.append(dict(record, key=f"defect {len(defects) + 1}"))
        else:
            home["names"] = list(dict.fromkeys(home["names"] + record["names"]))
            home["depths"] += record["depths"]
            home["documents"] = list(dict.fromkeys(home["documents"] + record["documents"]))
            home["field"] = home["field"] or record["field"]
    # S327: an inspection-data-only defect at a place where the field names one: the same defect (the field
    # one, or - several field defects there - the one with the nearest depth)
    for defect in [d for d in defects if not d["field"] and d["place"]]:
        fields = [d for d in defects if d["field"] and d["place"] == defect["place"]]
        target = fields[0] if len(fields) == 1 else None
        if target is None and defect["depths"] and any(f["depths"] for f in fields):
            target = min((f for f in fields if f["depths"]),
                         key=lambda f: min(abs(a - b) for a in f["depths"] for b in defect["depths"]))
        if target is None:
            continue
        target["inspection"] = list(dict.fromkeys(target["inspection"] + defect["names"]))
        target["documents"] = list(dict.fromkeys(target["documents"] + defect["documents"]))
        defects.remove(defect)
        said = (f"DEFECTS: at {defect['place'][1]} the inspection data's '{' / '.join(defect['names'])}' "
                f"({', '.join(defect['documents'])}) is the field's '{target['names'][0]}' - one defect (S327)")
        if WT35_DEFECTS_SAID.get(("merged", defect["place"], tuple(defect["names"]))) != said:
            WT35_DEFECTS_SAID[("merged", defect["place"], tuple(defect["names"]))] = said
            print(said)
    return defects


def wt35_shared_wheels(documents, labels):
    """S324: a 10000-35 form naming no wheel count of its own takes the wheel counts of the other 10000-35
    forms that name the same 6000 form in their file names (e.g. 'Gouge Grid #3_6000-10-237-...' takes
    100553.07 and 100572.03 from '... WC 100553.07 - 100572.03_6000-10-237-...'). Returns {document id:
    [wheel counts]} for the forms that took some; the range / defect rules then place them as usual."""
    shared = {}
    for document in documents:
        form = document["result"]["form"]
        number = form.get("six_thousand")
        if document["result"].get("wheels") or not number:
            continue
        givers = [d for d in documents if d is not document and d["result"]["form"].get("six_thousand") == number
                  and d["result"].get("wheels")]
        wheels = list(dict.fromkeys(w for d in givers for w in d["result"]["wheels"]))
        message = (f"10000-35 WHEEL COUNTS: {labels[id(document)]} names no wheel count - "
                   + (f"takes {' and '.join(wheels)} from {', '.join(labels[id(d)] for d in givers)} (the same 6000 "
                      f"form {number})" if wheels else f"no other 10000-35 form of 6000 form {number} names one")
                   + " (S324)")
        if WT35_WHEELS_SAID.get(("shared", id(document))) != message:
            WT35_WHEELS_SAID[("shared", id(document))] = message
            print(message)
        if wheels:
            shared[id(document)] = wheels
    return shared


def wt35_defect_match(document, label, defects, wheels=None):
    """S322: which known defect a 10000-35 form is - the same kind of name ('Gouge #3' with 'Gouge'), the
    same wheel count when both have one, and one of its grid readings equal to that defect's depth
    (within WT35_DEPTH_TOLERANCE in). A defect with no depth known matches only when it is the only one
    with a like name and wheel count. Returns (that defect or None (a new defect / no defect name), how it
    was confirmed - S327, for the Defects row)."""
    result = document["result"]
    form = result["form"]
    name = form.get("defect")
    if not name:
        return None, None
    wheels = wheels if wheels is not None else result.get("wheels") or []        # S324: shared ones too
    readings = [d for d in (wt35_inches({}, text) for _at, text in form.get("readings") or []) if d is not None]
    like = [d for d in defects if any(wt35_like_names(name, n) for n in d["names"])
            and (not wheels or d["wc"] is None or d["wc"] in wheels)]
    by_depth = [d for d in like if d["depths"] and any(abs(r - depth) <= WT35_DEPTH_TOLERANCE
                                                       for r in readings for depth in d["depths"])]
    no_depth = [d for d in like if not d["depths"]]
    match, why, how = None, "", None
    if len(by_depth) == 1:
        match, why = by_depth[0], "a grid reading equals its depth"
        reading, depth = next((r, x) for r in readings for x in match["depths"] if abs(r - x) <= WT35_DEPTH_TOLERANCE)
        how = f'grid {reading:.3f}" = depth {depth:.3f}"'
    elif len(by_depth) > 1:
        why = f"{len(by_depth)} like defects have a depth equal to a grid reading - not one clear match"
    elif len(no_depth) == 1 and len(like) == 1:
        match, why = no_depth[0], "the only like defect there (no depth known to compare)"
        how = "by name and wheel count (no depth to compare)"
    elif like:
        why = "like names there, but no depth equal to a grid reading"
    else:
        why = "no defect with a like name" + (" at " + " / ".join(wheels) if wheels else "")
    readings_text = ", ".join(f'{r:.3f}"' for r in sorted(set(readings))) or "none"
    message = (f"10000-35 DEFECT: {label} '{name}' (grid readings {readings_text}) - "
               + "; ".join(f"{d['key']}: {' / '.join(d['names'])} at {d['wc'] or 'no wheel count'}"
                           + (f", depth {', '.join(f'{x:.3f}' for x in d['depths'])} in" if d["depths"] else "")
                           for d in like)
               + (" - " if like else "")
               + (f"-> the same defect as {match['key']} ({why}) - it goes to {match['wc'] or 'its column'}"
                  if match else f"-> a NEW defect ({why})") + " (S322)")
    if WT35_DEFECTS_SAID.get(id(document)) != message:
        WT35_DEFECTS_SAID[id(document)] = message
        print(message)
    return match, how


def wt35_defects_rows(defects, wt35_blocks, labels):
    """S322: a 'Defects' row in each anomaly column (S327: Wheel Count or Mile Post) - how many defects can
    be told apart there and the documents each comes from: the other documents' defects, the 10000-35
    forms that are one of them, and the forms that are new defects. S327: a defect a 10000-35 form
    confirmed takes the form's more exact name ('Gouge' -> 'Gouge #3') and says how it was confirmed; a
    defect the inspection data named differently says so. Returns blocks (end table only) holding the rows."""
    by_place = {}
    compared = {defect["place"] for defect in defects if defect["place"]}   # S323: '(new)' only where compared
    for defect in defects:
        if defect["place"]:
            by_place.setdefault(defect["place"], []).append(
                {"name": defect["names"][0], "documents": list(defect["documents"]), "key": defect["key"],
                 "inspection": [n for n in defect["inspection"] if not wt35_like_names(n, defect["names"][0])],
                 "confirmed": []})
    for block in wt35_blocks:
        place, name = wt35_place(block.get("ident")), block.get("defect_name")
        if not place or not name:
            continue
        found = by_place.setdefault(place, [])
        known = next((d for d in found if block.get("defect_key") and d["key"] == block["defect_key"]), None)
        if known is not None and block.get("defect_how"):
            if not known["confirmed"]:
                known["name"] = name                     # S327: the form's more exact name
            known["confirmed"].append(block["defect_how"])
        if known is None and not block.get("defect_key"):     # a new defect - one per name at a place
            known = next((d for d in found if d.get("new") and wt35_label_key(d["name"]) == wt35_label_key(name)),
                         None)
            if known is None:
                known = {"name": name, "documents": [], "key": None, "new": True, "inspection": [], "confirmed": []}
                found.append(known)
        if known is not None and block.get("owner") not in known["documents"]:
            known["documents"].append(block.get("owner"))
    rows = []
    for place, found in by_place.items():
        text = f"{len(found)} - " + "; ".join(
            f"{d['name']}{' (new)' if d.get('new') and place in compared else ''} ({', '.join(d['documents'])})"
            + (f" - confirmed: {'; '.join(dict.fromkeys(d['confirmed']))}" if d["confirmed"] else "")
            + (f" - inspection data called it {' / '.join(d['inspection'])}" if d["inspection"] else "")
            for d in found)
        block = priority_new_block(f"Defects at {place[1]}", show_missing=False)
        block["ident"] = priority_ident(place[1]) if place[0] == "wc" else priority_ident(None, place[1])
        block["end_table_only"] = True
        priority_add_other(block, "Defects", priority_entry("Defects - worked out from every document", None, text,
                                                            from_text=True))
        said = f"{place[1]}: {text}"
        if WT35_DEFECTS_SAID.get(("row", place)) != said:
            WT35_DEFECTS_SAID[("row", place)] = said
            print(f"DEFECTS: {'Wheel Count' if place[0] == 'wc' else 'Mile Post'} {said} (S322/S327)")
        rows.append(block)
    return rows


def priority_wt35_blocks(document, label, forms, labels, others, defects=(), shared=None):
    """S320: a 10000-35 wall thickness form's values as one block - in the column of its Wheel Count
    (Remarks / file name), or of the 6000 form its file name names when they agree. Its cells are
    exact (not on the Verify list); its photo's typed text is a picture read (on the Verify list).
    S321: a form naming several wheel counts (a range) goes to the one its details match (see
    wt35_detail_match), else to each of them - one block per wheel count, each with its own Wheel
    Count value; the photo reads are checked once on the Verify tab (the other copies are end table only)."""
    result = document["result"]
    path = result["path"]
    wheels = result.get("wheels") or list(shared or [])   # S324: none of its own -> its 6000 form's other forms'
    defect, defect_how = wt35_defect_match(document, label, defects, wheels)      # S322 / S327
    if defect is not None and defect["wc"]:
        chosen = [defect["wc"]]                          # S322: the known defect it is says where it goes
    elif defect is not None and any((defect.get("ident") or {}).values()):
        chosen = [None]                                  # S326: a defect with no wheel count (a 6000 form with only
    else:                                                # a Mile Post) - the form goes with it, into its column
        chosen = wt35_detail_match(document, label, wheels, others) if len(wheels) > 1 else wheels
    form = result["form"]
    tag = form.get("defect") or WT35_NO_DEFECT_TAG       # S322: its own rows carry this
    six = wt35_six_thousand_link(document, label, forms, labels)
    theirs = None
    if six is not None:
        extracted = six["result"][1]
        theirs = priority_ident((extracted.get("Wheel Count") or {}).get("value"),
                                (extracted.get("MP/Stationing") or {}).get("value"))
    entries = []
    for page in result["pages"]:
        for value in page["values"]:
            entry = priority_entry(f"{label} - {value['where']} - {value['label']}", None, value["text"],
                                   where=priority_where(path, 0, value["box"], "page"), from_text=page["from_text"])
            entry["typed"] = value.get("typed")         # S379: the photo's typed-font verdict
            entries.append((value, entry))
    blocks = []
    for number, wheel in enumerate(chosen or [None]):
        block = priority_new_block(f"{label} - 10000-35 wall thickness form"
                                   + (f" (Wheel Count {wheel})" if len(chosen) > 1 else ""),
                                   show_missing=False, owner=label)
        block["ident"] = priority_ident(wheel)
        if wheel is None and defect is not None and any((defect.get("ident") or {}).values()):
            block["ident"] = dict(defect["ident"])       # S326: where its matched defect is (e.g. its Mile Post)
        # S320 joined 6000 form: its Wheel Count / Mile Post go with the form. S326: a 6000 form with no Wheel
        # Count only joins a form that goes to ONE place - its Mile Post on every copy of a form kept at two
        # wheel counts glued those two columns into one (every value of both then needed a pick)
        if theirs is not None and ((theirs.get("wc") and wheel in (None, theirs["wc"]))
                                   or (not theirs.get("wc") and len(chosen or [None]) == 1)):
            block["ident"] = {key: theirs.get(key) or block["ident"].get(key) for key in block["ident"]}
        if number:
            block["end_table_only"] = True               # S321: checked once, on the first one's Verify items
        block["defect_name"] = form.get("defect")        # S322: for the Defects row
        block["defect_how"] = defect_how                 # S327: how it confirmed the defect
        block["wt35"] = True                             # S327: a field document (its names are the crew's)
        block["wt35_tag"] = tag                          # S330: its rows' group in the end table
        block["defect_key"] = defect["key"] if defect is not None else None
        # S322: a new defect sharing its column with other defects keeps its name in its own row
        others_there = [d for d in defects if d["wc"] == wheel and (defect is None or d is not defect)]
        for value, entry in entries:
            if value["field"] == "Wheel Count" and wheel is not None and priority_ident(value["text"])["wc"] != wheel:
                continue                                 # S321/S322: each column only its own wheel count
            if value["field"] == "Defect name" and defect is None and others_there:
                priority_add_other(block, f"{tag} - Defect name", entry)          # S330: the anomaly first
                continue
            if value["field"] is None and value["label"] not in WT35_SHARED_ROWS:
                # S322/S330: 'Gouge #3 - Grid row 1' - the anomaly first, so a form's rows sit together under
                # it (a '(...)' in a row name is dropped from its key - S202)
                priority_add_other(block, f"{tag} - {value['label']}", entry)
            elif value["field"] is None:
                priority_add_other(block, value["label"], entry)
            elif value["field"] == "notes":
                block["notes"].append(entry)
            else:
                block["fields"][value["field"]].append(entry)
        blocks.append(block)
    return blocks


def dt_number_shape(value):
    """Shape of a number: (minus sign?, digits after '.'), or None. The digits before
    the '.' are NOT part of it - 9.87 and 19.25 legitimately differ there."""
    match = re.fullmatch(r"(-?)(\d+)(?:\.(\d+))?", str(value or "").replace(" ", ""))
    if not match:
        return None
    return (match.group(1) == "-", len(match.group(3) or ""))


def dt_shape_text(shape):
    return ("-" if shape[0] else "") + "#" + ("." + "#" * shape[1] if shape[1] else "")


# ============================================================
# S354: TESSERACT - A SECOND READER FOR THE PRINTED TABLE
# ============================================================
# The inspection table is a clean screenshot of printed text. Tesseract (free, runs on the processor, not
# the GPU) reads every cell of the table rows being read - all of them in ONE picture, ONE run - while
# PaddleOCR reads the same cells on the GPU. PaddleOCR's reads are kept; when one of them fails its column's
# format check (a clock time, the column's number shape), Tesseract's read of that cell is tried first, and
# used if it has the right format. Every cell the two read differently is listed in the terminal. Without
# Tesseract installed the table is read as before.

TESSERACT_PATHS = [r"C:\Program Files\Tesseract-OCR\tesseract.exe",
                   r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
                   os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs", "Tesseract-OCR", "tesseract.exe")]
TESSERACT_SCALE = 3                  # each cell 3x its size (the table is a 96 dpi screenshot)
TESSERACT_GAP = (48, 24)             # white space between the cells (x, y) - Tesseract never joins two cells
TESSERACT_TIMEOUT_S = 60
TESSERACT = {"path": None, "looked": False, "pool": None}
# S393: a table page whose picture is exactly the same (every pixel) as one already read - the same table
# page printed in two Dig Packets - is not read again: its column headers, cell reads and Tesseract's reads are
# taken from the first reading. Kept only while the program is open (nothing is saved to a file).
TABLE_READS = {"pages": {}, "again": {}, "lock": threading.Lock()}   # pages: fingerprint -> readings; again:
                                                                     # S381 one-cell reads by cell picture


def table_page_fingerprint(image, grid):
    """S393: the table page picture's exact fingerprint - every pixel, its size and the grid found on it."""
    fingerprint = hashlib.md5(f"{image.mode} {image.size}".encode())
    fingerprint.update(image.tobytes())
    fingerprint.update(repr([[int(v) for v in grid.get("rows") or []], [int(v) for v in grid.get("columns") or []],
                             [int(v) for v in grid.get("header") or []]]).encode())
    return fingerprint.hexdigest()


def tesseract_program():
    """S354: tesseract.exe (on PATH or where its Windows installer puts it), or None."""
    if not TESSERACT["looked"]:
        TESSERACT["looked"] = True
        TESSERACT["path"] = shutil.which("tesseract") or next((p for p in TESSERACT_PATHS if os.path.isfile(p)),
                                                              None)
        print(f"TESSERACT: {TESSERACT['path']} - a second reader for the printed table (S354)" if TESSERACT["path"]
              else "TESSERACT: not installed - the printed table is read by PaddleOCR / EasyOCR only (S354)")
    return TESSERACT["path"]


def tesseract_table_cells(image, grid, rows):
    """S354: Tesseract's read of every cell of these table rows: {(row, column): text}. The cells are laid
    out in one picture as they are in the table (row by row, column by column), each 3x its size with white
    space around it, and read in one run (page segmentation 6: a block of text lines). Each word Tesseract
    finds goes to the cell it sits in."""
    import subprocess
    program = tesseract_program()
    row_lines, columns = grid["rows"], grid["columns"]
    gap_x, gap_y = TESSERACT_GAP
    widths = [max(1, (columns[c + 1] - columns[c] - 1) * TESSERACT_SCALE) for c in range(len(columns) - 1)]
    heights = [max(1, (row_lines[r + 1] - row_lines[r] - 1) * TESSERACT_SCALE) for r in rows]
    canvas = Image.new("L", (sum(widths) + gap_x * (len(widths) + 1), sum(heights) + gap_y * (len(rows) + 1)), 255)
    places, y = [], gap_y
    grey = image.convert("L")
    for r, height in zip(rows, heights):
        x = gap_x
        for c, width in enumerate(widths):
            cell = grey.crop((columns[c] + 1, row_lines[r] + 1, columns[c + 1], row_lines[r + 1]))
            canvas.paste(cell.resize((width, height), Image.LANCZOS), (x, y))
            places.append((r, c, x - gap_x / 2, y - gap_y / 2, x + width + gap_x / 2, y + height + gap_y / 2))
            x += width + gap_x
        y += height + gap_y
    picture = io.BytesIO()
    canvas.save(picture, "PNG")
    done = subprocess.run([program, "stdin", "stdout", "--psm", "6", "tsv"], input=picture.getvalue(),
                          capture_output=True, timeout=TESSERACT_TIMEOUT_S,
                          env=dict(os.environ, OMP_THREAD_LIMIT="1"),
                          creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    words = {}
    for line in done.stdout.decode("utf-8", errors="replace").splitlines()[1:]:
        parts = line.split("\t")
        if len(parts) < 12 or parts[0] != "5" or not parts[11].strip():
            continue
        left, top, width, height = (int(v) for v in parts[6:10])
        middle_x, middle_y = left + width / 2, top + height / 2
        spot = next((p for p in places if p[2] <= middle_x <= p[4] and p[3] <= middle_y <= p[5]), None)
        if spot is not None:
            words.setdefault((spot[0], spot[1]), []).append((left, parts[11].strip()))
    return {key: " ".join(text for _left, text in sorted(found)) for key, found in words.items()}


def tesseract_start(image, grid, rows, reads=None):
    """S354: Tesseract starts reading these table rows on its own thread (its work is a separate program on
    the processor). Returns a function (row, column) -> Tesseract's text for that cell (it waits for
    Tesseract the first time), or None when Tesseract is not installed. S393: reads - the table page's
    saved readings ({rows: cells}); the same rows of the same picture already read are not read again."""
    if not rows or not tesseract_program():
        return None
    wanted = tuple(rows)
    if reads is not None and wanted in reads:                       # S393: this picture's rows, read before
        saved = reads[wanted]

        def cell(row, column):
            return saved.get((row, column))
        cell.timing = {"reused": True}
        return cell
    if TESSERACT["pool"] is None:
        from concurrent.futures import ThreadPoolExecutor
        TESSERACT["pool"] = ThreadPoolExecutor(max_workers=1, thread_name_prefix="tesseract")
    timing = {}

    def run():
        started = time.perf_counter()
        try:
            cells = tesseract_table_cells(image, grid, list(wanted))
            if reads is not None:
                reads[wanted] = cells                               # S393: kept for the same picture again
            return cells
        finally:
            timing["seconds"] = time.perf_counter() - started      # S358: Tesseract's own run, start to end

    future = TESSERACT["pool"].submit(run)
    box = {}

    def cell(row, column):
        if "cells" not in box:
            try:
                box["cells"] = future.result(timeout=TESSERACT_TIMEOUT_S)
            except Exception as exc:
                print(f"TESSERACT: reading the table failed ({type(exc).__name__}: {exc}) - PaddleOCR / EasyOCR "
                      f"only (S354)")
                box["cells"] = {}
        return box["cells"].get((row, column))
    cell.timing = timing
    return cell


def tesseract_compare(page_number, items, tesseract):
    """S354: once Tesseract is done (on its own thread - nothing waits for it), every cell it read
    differently from the cell's value is listed; the value is kept (PaddleOCR's, or the format check's)."""
    if tesseract is None:
        return

    def work():
        same, differ = 0, []
        for item in items:
            for cell in item["cells"]:
                theirs, ours = tesseract(item["row"], cell["column"]), str(cell.get("value") or "")
                if not theirs or not ours:
                    continue
                if re.sub(r"\s+", "", theirs) == re.sub(r"\s+", "", ours):
                    same += 1
                else:
                    differ.append(f"    {item['title']} - {cell['name']}: kept '{ours}', Tesseract read '{theirs}'")
        took = tesseract.timing.get("seconds")
        print(f"TESSERACT CHECK: page {page_number} - {same} of {same + len(differ)} cell(s) read the same by "
              f"PaddleOCR and Tesseract"
              + (f" (Tesseract's run took {took:.1f} s - S358)" if took is not None else
                 " (Tesseract's reading of the same page picture reused - S393)" if tesseract.timing.get("reused")
                 else "")
              + (" - read differently (the kept value stays):" if differ else "") + " (S354)")
        for line in differ:
            print(line)
    threading.Thread(target=work, name="tesseract-check", daemon=True).start()


# ============================================================
# S375: TYPED-TEXT CHECK - a printed table value read from the table's picture is compared, character by
# character, with how that page's own printed digits look. The digits' shapes are learned from the cells of
# the rows being read that PaddleOCR and Tesseract read the same (each page its own font - a different
# vendor's table too). A value is never compared with shapes taken from its own cell. A value whose two
# reads agree, whose format check passed and whose every character looks most like the digit read (by a
# clear margin), with its points / colons / minus where they are read, is confirmed without being listed on
# the Verify tab - S376: also when another document gives a different value (the end table shows both).
# Anything less goes to the Verify tab as before.
# ============================================================
TYPED_SCALE = 3                      # each cell made this much larger before its characters are cut apart
TYPED_SIZE = 24                      # px - each digit compared at this size
TYPED_MIN_SAMPLES = 5                # each digit 0-9 needs this many examples on the page (not its own cell's)
TYPED_MARGIN = 0.05                  # the digit read must look this much more like itself than like any other
TYPED_VALUE = re.compile(r"-?\d[\d.:]*")    # the values checked: digits with points / colons, maybe a minus
TYPED_SAID = set()                   # (item id, value) whose verdict was printed - each once


def typed_glyphs(cell_image, text):
    """S375: the value's characters cut out of its cell's picture - one column of ink per character, in order,
    their count the same as the value's, the tall ones exactly where the digits are and the short ones where
    its points / colons / minus are. Returns [(digit, its shape)] for the digits, or (None, why)."""
    text = str(text or "").replace(" ", "")
    if not TYPED_VALUE.fullmatch(text):
        return None, "not a number made of digits, points, colons and a minus"
    grey = np.asarray(cell_image.convert("L").resize((cell_image.width * TYPED_SCALE, cell_image.height * TYPED_SCALE),
                                                     Image.LANCZOS)).astype(float)
    if grey.max() - grey.min() < 60:
        return None, "too little contrast in its cell"
    ink = grey < (grey.min() + grey.max()) / 2
    ys, xs = np.where(ink)
    ink = ink[ys.min():ys.max() + 1, xs.min():xs.max() + 1]
    height = ink.shape[0]
    columns, segments, start = ink.any(axis=0), [], None
    for x, used in enumerate(list(columns) + [False]):
        if used and start is None:
            start = x
        elif not used and start is not None:
            segments.append(ink[:, start:x])
            start = None
    if len(segments) != len(text):
        return None, f"its picture splits into {len(segments)} mark(s) for {len(text)} character(s)"
    shapes = []
    for character, piece in zip(text, segments):
        used = piece.any(axis=1)
        rows = np.where(used)[0]
        glyph = piece[rows.min():rows.max() + 1]
        runs = [(a, b) for a, b in zip(*[iter(np.flatnonzero(np.diff(np.r_[0, used.astype(int), 0])))] * 2)]
        dots = len(runs) == 2 and all(b - a < 0.35 * height for a, b in runs)     # ':' - two dots, one above
        kind = ":" if dots else "tall" if glyph.shape[0] > 0.6 * height else "short"
        wanted = ":" if character == ":" else "tall" if character.isdigit() else "short"
        if kind != wanted:
            return None, f"'{character}' is not where its picture has a {'colon' if wanted == ':' else wanted} mark"
        if kind == "tall":
            side = max(height, glyph.shape[1])
            square = np.zeros((side, side), bool)
            top = min(rows.min(), side - glyph.shape[0])                          # where it sits on the line
            left = (side - glyph.shape[1]) // 2
            square[top:top + glyph.shape[0], left:left + glyph.shape[1]] = glyph
            small = np.asarray(Image.fromarray((square * 255).astype("uint8")).resize((TYPED_SIZE, TYPED_SIZE),
                                                                                        Image.BILINEAR)).astype(float)
            small -= small.mean()
            shapes.append((character, small / (np.sqrt((small * small).sum()) + 1e-9)))
    return shapes, None


def cell_marks(cell_image):
    """S424: how many separate marks of ink a cell's picture has, left to right (columns of ink with paper between
    them, cut like typed_glyphs - in the cell made TYPED_SCALE times larger). None when the cell has too little
    contrast to tell ink from paper."""
    grey = np.asarray(cell_image.convert("L").resize((cell_image.width * TYPED_SCALE, cell_image.height * TYPED_SCALE),
                                                     Image.LANCZOS)).astype(float)
    if grey.max() - grey.min() < 60:
        return None
    used = (grey < (grey.min() + grey.max()) / 2).any(axis=0)
    return int(np.count_nonzero(np.diff(np.r_[0, used.astype(int)]) == 1))


CELL_TWO_MARK_CHARACTERS = '%"'      # S424: characters printed as two marks side by side


def cell_expected_marks(text):
    """S424: how many marks a value takes in its cell - one per character, two for % and \"."""
    return len(text) + sum(text.count(c) for c in CELL_TWO_MARK_CHARACTERS)


def cell_has_in_order(longer, shorter):
    """S424: every character of `shorter` is in `longer`, in the same order (the longer read only adds some)."""
    rest = iter(longer)
    return all(character in rest for character in shorter)


def cell_rest_check(page_number, items, tesseract):
    """S424: every read cell: the value read is found in its cell's picture and the REST of the cell is looked at
    for anything the read missed - the cell has more marks of ink than the value takes (cell_expected_marks).
    Then the other reads of that cell are asked - Tesseract's (the rows' picture, and the cell on its own for a
    number) and EasyOCR's: one that accounts for every mark and has the first read's characters in order (it
    only adds what was missed) is the cell's value. None does -> kept as read, said in the terminal. What was
    read first is kept as 'read_value'. (Marks that touch make fewer marks than characters - nothing is done.)
    S424b: the other reads are asked one at a time, cheapest first, until one accounts for every mark."""
    started = time.perf_counter()
    fixed, unexplained, asked = [], [], Counter()        # asked: how many reads each flagged cell needed
    for item in items:
        for cell in item["cells"]:
            value = str(cell.get("value") or "")
            plain = value.replace(" ", "")
            if not plain or cell.get("ocr_source") is None:
                continue
            # dataC (accuracy fix A4): a WORDS cell (e.g. "20' U/S MAIN ST") whose Tesseract read is PaddleOCR's
            # read plus small marks only - apostrophes, quotes, degree signs - takes Tesseract's: PaddleOCR drops
            # those small marks (letters touching each other hide the extra mark from the count below)
            # A free-text cell (letters AND digits, e.g. 'Bend 4.5° 12.0D') is also read by Tesseract on its
            # own: PaddleOCR can join two words; Tesseract's word spacing is kept when it has the same characters
            if tesseract and re.search(r"[A-Za-z]{2}", value):
                others = [str(tesseract(item["row"], cell.get("column")) or "").strip()]
                if re.search(r"\d", value) and re.search(r"[A-Za-z]", value):
                    others.append(tesseract_cell_text(cell["ocr_source"]))
                adopted = None
                for other in others:
                    if other and len(other) > len(value) and \
                            re.sub(r"['\"°’\s]", "", other) == re.sub(r"['\"°’\s]", "", value):
                        adopted = other
                        break
                if adopted is not None:
                    cell["read_value"], cell["value"] = value, adopted
                    fixed.append(f"{item['title']} - {cell['name']}: '{value}' -> '{adopted}' (Tesseract has the "
                                 f"same characters plus small marks / word spaces PaddleOCR dropped - dataC fix A4)")
                    continue
            marks = cell_marks(cell["ocr_source"])
            if marks is None or marks <= cell_expected_marks(plain):
                continue
            number = re.fullmatch(r"[-+]?[\d.:,%/]+", plain) is not None

            def easyocr_read(image=cell["ocr_source"]):
                try:
                    picture = dt_prepare_for_ocr(image, TABLE_OCR_UPSCALE)
                    reads = easy_reader.readtext(np.array(picture), detail=1, paragraph=False) if picture is not None else []
                except Exception:
                    return ""
                reads.sort(key=lambda r: min(p[0] for p in r[0]))
                return " ".join(str(r[1]).strip() for r in reads)
            # S424b: cheapest first, stopping at the first that accounts for every mark - Tesseract's read of the
            # rows' picture (already made), Tesseract on the cell alone (processor), EasyOCR last (GPU)
            readers = [("Tesseract (the rows' picture)",
                        lambda item=item, cell=cell: tesseract(item["row"], cell.get("column")) if tesseract else "")]
            if number:
                readers.append(("Tesseract (the cell on its own)", lambda cell=cell: tesseract_cell_number(cell["ocr_source"])))
            readers.append(("EasyOCR", easyocr_read))
            said = f"{item['title']} - {cell['name']}: '{value}' ({len(plain)} character(s), its cell has {marks} marks)"
            others, better = [], None
            for who, reader in readers:
                text = str(reader() or "")
                others.append((who, text))
                if text and cell_expected_marks(text.replace(" ", "")) == marks \
                        and cell_has_in_order(text.replace(" ", ""), plain):
                    better = (who, text)
                    break
            if better is not None:
                asked[len(others) - 1] += 1
            if better is None:
                unexplained.append(said + " - other reads: " + "; ".join(f"{who} '{text}'" for who, text in others))
                continue
            cell["read_value"], cell["value"] = value, better[1].strip()
            fixed.append(said + f" -> '{cell['value']}' ({better[0]} accounts for every mark)")
    if fixed:
        print(f"CELL REST CHECK: page {page_number} - {len(fixed)} cell(s) had something the read missed: "
              + "; ".join(fixed) + " (S424)")
    if unexplained:
        print(f"CELL REST CHECK: page {page_number} - {len(unexplained)} cell(s) have more marks than their read but "
              f"no other read accounts for them - kept as read: " + "; ".join(unexplained) + " (S424)")
    if fixed or unexplained:
        print(f"CELL REST CHECK: page {page_number} - {len(fixed) + len(unexplained)} cell(s) with more marks than their "
              f"read: settled by the 1st read asked {asked[0]}, the 2nd {asked[1]}, the 3rd {asked[2]}, none "
              f"{len(unexplained)} - "
              f"{time.perf_counter() - started:.2f} s (S424b)")


def tesseract_cell_text(cell_image):
    """dataC (fix A4): Tesseract reads ONE words cell on its own - black text on white (the cell's colour taken
    out the way the PaddleOCR read does), as a single line. Its text, or '' when it could not be run."""
    import subprocess
    program = tesseract_program()
    if not program:
        return ""
    prepared = dt_prepare_for_ocr(cell_image, TABLE_OCR_UPSCALE)
    if prepared is None:
        return ""
    picture = io.BytesIO()
    prepared.convert("L").save(picture, "PNG")
    try:
        done = subprocess.run([program, "stdin", "stdout", "--psm", "7"], input=picture.getvalue(),
                              capture_output=True, timeout=TESSERACT_TIMEOUT_S,
                              env=dict(os.environ, OMP_THREAD_LIMIT="1"),
                              creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    except Exception:
        return ""
    return " ".join(done.stdout.decode("utf-8", errors="replace").split())


def tesseract_cell_number(cell_image):
    """S381: Tesseract reads ONE number cell on its own - 3x its size with white space around it, as a single
    line (page segmentation 7), only digits, points, colons and a minus allowed. Its text, or '' when it
    could not be run."""
    import subprocess
    program = tesseract_program()
    if not program:
        return ""
    grey = cell_image.convert("L")
    key = hashlib.md5(repr(grey.size).encode() + grey.tobytes()).hexdigest()     # S393: the same cell picture
    if key in TABLE_READS["again"]:                                              # was read on its own before
        return TABLE_READS["again"][key]
    big = grey.resize((grey.width * TESSERACT_SCALE, grey.height * TESSERACT_SCALE), Image.LANCZOS)
    canvas = Image.new("L", (big.width + 2 * TESSERACT_GAP[0], big.height + 2 * TESSERACT_GAP[1]), 255)
    canvas.paste(big, TESSERACT_GAP)
    picture = io.BytesIO()
    canvas.save(picture, "PNG")
    try:
        done = subprocess.run([program, "stdin", "stdout", "--psm", "7", "-c", "tessedit_char_whitelist=0123456789.:-"],
                              input=picture.getvalue(), capture_output=True, timeout=TESSERACT_TIMEOUT_S,
                              env=dict(os.environ, OMP_THREAD_LIMIT="1"),
                              creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
    except Exception:
        return ""
    text = re.sub(r"\s+", "", done.stdout.decode("utf-8", errors="replace"))
    TABLE_READS["again"][key] = text
    return text


def typed_text_check(page_number, items, tesseract):
    """S375: every read cell of this page's rows gets cell['typed'] = {'value', 'ok', 'why'} - the typed-text
    verdict for the value it has now. Waits for Tesseract (it has been reading since the rows were found)."""
    if tesseract is None:
        return
    started = time.perf_counter()
    cells = []
    for item in items:
        for cell in item["cells"]:
            value = str(cell.get("value") or "").replace(" ", "")
            theirs = re.sub(r"\s+", "", tesseract(item["row"], cell.get("column")) or "")
            agree = bool(value) and theirs == value and not cell.get("note")       # the first read, kept
            if not agree and value and not cell.get("note") and TYPED_VALUE.fullmatch(value):
                # S381: Tesseract read this number cell differently in the rows' one picture (a short value
                # like '1.1' can come out as letters) - it reads the cell again on its own, digits only
                again = tesseract_cell_number(cell["ocr_source"])
                agree = again == value
                print(f"TESSERACT AGAIN: page {page_number} {item['title']} - {cell['name']}: PaddleOCR '{value}', "
                      f"Tesseract first '{theirs}', on its own (digits only) '{again}' -> "
                      + ("the same - they agree" if agree else "still different") + " (S381)")
                theirs = again or theirs
            shapes, why = typed_glyphs(cell["ocr_source"], value) if TYPED_VALUE.fullmatch(value) else (None, None)
            cells.append((cell, value, theirs, agree, shapes, why))
    sums, counts, own = {}, Counter(), {}
    for cell, _value, _theirs, agree, shapes, _why in cells:
        if agree and shapes:
            for digit, shape in shapes:
                sums[digit] = sums.get(digit, 0) + shape
                counts[digit] += 1
                own.setdefault(id(cell), []).append((digit, shape))
    missing = [d for d in "0123456789" if counts[d] < TYPED_MIN_SAMPLES + 1]
    confirmed = 0
    for cell, value, theirs, agree, shapes, why in cells:
        if not TYPED_VALUE.fullmatch(value):
            continue
        verdict = None
        if not agree:
            verdict = ("PaddleOCR and Tesseract read it differently" if theirs and theirs != value else
                       "Tesseract did not read it" if not theirs else "its first read was changed by a format check")
        elif cell.get("warning"):
            verdict = "its format check did not pass"
        elif shapes is None:
            verdict = why
        elif missing:
            verdict = f"too few examples on this page of the digit(s) {', '.join(missing)}"
        if verdict is None:
            mine = own.get(id(cell), [])                # its own shapes are taken out of the examples
            templates = {}
            for digit in "0123456789":
                total = sums[digit] - sum(s for d, s in mine if d == digit)
                templates[digit] = total / max(1, counts[digit] - sum(1 for d, _s in mine if d == digit))
            for position, (digit, shape) in enumerate(shapes):
                scores = {d: float((shape * t).sum() / (np.sqrt((t * t).sum()) + 1e-9)) for d, t in templates.items()}
                rival = max((d for d in scores if d != digit), key=scores.get)
                if scores[digit] - scores[rival] < TYPED_MARGIN:
                    verdict = (f"its digit {position + 1} ('{digit}') looks too much like '{rival}' "
                               f"({scores[digit]:.2f} vs {scores[rival]:.2f})")
                    break
        ok = verdict is None
        confirmed += ok
        cell["typed"] = {"value": value, "ok": ok,
                         "why": "PaddleOCR and Tesseract read it the same, its format check passed and every "
                                "character matches this page's typed digits" if ok else verdict}
    print(f"TYPED-TEXT CHECK: page {page_number} - digit shapes learned from "
          f"{len(own)} cell(s) read the same by PaddleOCR and Tesseract ("
          + ", ".join(f"{d}: {counts[d]}" for d in "0123456789") + ")"
          + (f"; too few examples of {', '.join(missing)} - nothing on this page is confirmed by it" if missing else
             f"; {confirmed} number cell(s) pass")
          + f" - {time.perf_counter() - started:.2f} s (S375)")


def dt_alternative_reads(cell_image, tesseract=None):
    """Other ways to read the same cell: S354: Tesseract's read first (from its one run over the table's
    rows), then raw cell (no tight crop), stronger contrast, and EasyOCR. Yields (text, how) one at a time,
    so the re-reads after the one that is used are not done."""
    if tesseract:
        yield tesseract.strip(), "Tesseract, the table's rows read in one picture"
    big = cell_image.resize((cell_image.width * 4, cell_image.height * 4), Image.LANCZOS)
    raw = Image.new("RGB", (big.width + 40, big.height + 40), (255, 255, 255))
    raw.paste(big, (20, 20))
    brightest = np.asarray(cell_image.convert("RGB")).astype(float).max(axis=2)
    strong = np.clip((brightest - 60) / (235 - 60) * 255, 0, 255).astype("uint8")
    strong = Image.fromarray(strong).resize((cell_image.width * 4, cell_image.height * 4), Image.LANCZOS)
    strong_padded = Image.new("L", (strong.width + 40, strong.height + 40), 255)
    strong_padded.paste(strong, (20, 20))
    strong_padded = strong_padded.convert("RGB")
    for how, picture in (("raw cell", raw), ("stronger contrast", strong_padded)):
        text, _conf = paddle_read_text_image(picture)
        yield str(text).strip(), f"Paddle, {how}"
        try:
            results = easy_reader.readtext(np.array(picture), detail=1, paragraph=False)
            results.sort(key=lambda r: min(p[0] for p in r[0]))
            easy = " ".join(str(r[1]).strip() for r in results).strip()
        except Exception:
            continue
        yield easy, f"EasyOCR, {how}"


def dt_known_coordinates(document):
    """Every latitude / longitude PRINTED as real text anywhere in the PDF (map notes,
    dig sheet, ...): {digits only: (the printed value, 'page N')}. A coordinate cell
    that lost its decimal point can be matched to one of these by its digits."""
    known = {}
    for page_index in range(len(document)):
        try:
            words = document[page_index].get_text("words")
        except Exception:
            continue
        for w in words:
            token = str(w[4]).strip().rstrip(",;:")
            if re.fullmatch(r"-?\d{2,3}\.\d{5,}", token):
                known.setdefault(re.sub(r"\D", "", token), (token, f"page {page_index + 1}"))
    return known


COORDINATE_SIGN_CLOSE_DEGREES = 0.01   # ~0.7 mile: a lost '-' is only added this close to the others


def dt_fix_coordinate_cells(items, known_coordinates):
    """Latitude / Longitude cells. A value already shaped '##.#####...' (or with '-')
    is kept. One that lost its decimal point (e.g. '2849771362') is fixed WITHOUT
    reading it again:
      1. the same digits found as a well-formed coordinate - in another table row, or
         printed as text in the PDF (dig sheet, map notes) -> that exact value
      2. otherwise the decimal point is put where the column's OTHER cells (the ones
         under the same Latitude / Longitude header that do have it) have it: the same
         number of digits before the point as most of them (2 when the column has none
         to learn from). The digits after it are checked against the column too; a
         different count gets a warning. A '-' that was read is kept; a '-' that is
         missing is added when EVERY other cell with a point in that column has one.
    known_coordinates: the coordinates printed in the PDF - a dict, or a function that
    makes it; the function is only called when a cell actually needs a lookup (a clean
    table never collects them). Printed coordinates win over the table's own, as before."""
    printed = {"made": not callable(known_coordinates),
               "pool": (known_coordinates or {}) if not callable(known_coordinates) else None}
    table_pool = {}                                  # the table's own well-formed coordinates

    class _Pool:
        def get(self, digits):
            if not printed["made"]:
                printed["pool"] = known_coordinates() or {}
                printed["made"] = True
            return printed["pool"].get(digits) or table_pool.get(digits)

        def setdefault(self, digits, value):
            return table_pool.setdefault(digits, value)

    pool = _Pool()
    # where the point sits in each column's well-formed cells: (digits before, digits after)
    column_shapes = defaultdict(Counter)
    column_signs = defaultdict(Counter)          # how many well-formed cells have / lack a '-' 
    for item in items:
        for cell in item["cells"]:
            name = re.sub(r"[^a-z]", "", cell["name"].lower())
            value = str(cell.get("value") or "").replace(" ", "")
            shaped = re.fullmatch(r"-?(\d{1,3})\.(\d{4,})", value)
            if re.match(r"(latitude|longitude)", name) and shaped:
                column_shapes[cell.get("column", name)][(len(shaped.group(1)), len(shaped.group(2)))] += 1
                column_signs[cell.get("column", name)][value.startswith("-")] += 1
    for item in items:
        for cell in item["cells"]:
            name = re.sub(r"[^a-z]", "", cell["name"].lower())
            value = str(cell.get("value") or "").replace(" ", "")
            if re.match(r"(latitude|longitude)", name) and re.fullmatch(r"-?\d{2,3}\.\d{4,}", value):
                pool.setdefault(re.sub(r"\D", "", value), (value, item["title"]))
    for item in items:
        for cell in item["cells"]:
            name = re.sub(r"[^a-z]", "", cell["name"].lower())
            if not re.match(r"(latitude|longitude)", name):
                continue
            first_read = str(cell.get("value") or "").replace(" ", "")
            if not first_read or re.fullmatch(r"-\d{2,3}\.\d{4,}", first_read):
                continue
            if re.fullmatch(r"\d{2,3}\.\d{4,}", first_read):
                # has its point but no '-': added when the column's cells WITH a '-' are
                # the majority AND this value is within COORDINATE_SIGN_CLOSE_DEGREES of
                # them (the same spot on the pipe, only the sign lost)
                column_key = cell.get("column", name)
                signs = column_signs.get(column_key, Counter())
                signed = [abs(float(c["value"])) for it in items for c in it["cells"]
                          if c.get("column", re.sub(r"[^a-z]", "", c["name"].lower())) == column_key
                          and re.fullmatch(r"-\d{1,3}\.\d{4,}", str(c.get("value") or "").replace(" ", ""))]
                if signed and signs[True] > signs[False] \
                        and max(abs(v - float(first_read)) for v in signed) <= COORDINATE_SIGN_CLOSE_DEGREES:
                    found = pool.get(re.sub(r"\D", "", first_read))
                    if found and found[0].startswith("-"):
                        cell["value"] = found[0]
                        cell["note"] = (f"first read '{first_read}' has no '-'; the same digits are "
                                        f"'{found[0]}' ({found[1]}) -> that is used")
                    else:
                        cell["value"] = "-" + first_read
                        cell["note"] = (f"first read '{first_read}' has no '-'; {signs[True]} of the column's "
                                        f"{signs[True] + signs[False]} cells with a point have one and all of them "
                                        f"are within {COORDINATE_SIGN_CLOSE_DEGREES}° of it (furthest "
                                        f"{max(abs(v - float(first_read)) for v in signed):.5f}°) -> '{cell['value']}'")
                    print(f"COORDINATE CHECK: {item['title']} - {cell['name']}: {cell['note']}")
                elif signed:
                    print(f"COORDINATE CHECK: {item['title']} - {cell['name']}: '{first_read}' has no '-' - left "
                          f"as read ({signs[True]} of {signs[True] + signs[False]} cells with a point have one; "
                          f"furthest of them {max(abs(v - float(first_read)) for v in signed):.5f}° away, "
                          f"'-' is only added within {COORDINATE_SIGN_CLOSE_DEGREES}° when they are the majority)")
                continue
            digits = re.sub(r"\D", "", first_read)
            if len(digits) < 6:
                continue
            found = pool.get(digits)
            if found:
                cell["value"] = found[0]
                cell["note"] = (f"first read '{first_read}' has no decimal point; the same digits are "
                                f"'{found[0]}' ({found[1]}) -> that is used")
            else:
                sign = "-" if first_read.startswith("-") else ""
                signs = column_signs.get(cell.get("column", name))
                sign_note = ""
                if not sign and signs and signs[True] and not signs[False]:
                    sign = "-"                     # every other cell in the column has a '-'
                    sign_note = f" '-' added (all {signs[True]} other cell(s) with a point have one);"
                shapes = column_shapes.get(cell.get("column", name))
                if shapes:
                    (before, after), count = shapes.most_common(1)[0]
                    learned = f"like {count} of the column's {sum(shapes.values())} other cell(s) with a point"
                else:
                    before, after, learned = 2, None, "the column has no cell with a point to learn from -> 2 digits"
                cell["value"] = f"{sign}{digits[:before]}.{digits[before:]}"
                shape_text = sign + "#" * before + "." + "#" * (after if after else max(1, len(digits) - before))
                cell["note"] = (f"first read '{first_read}' has no decimal point and no other coordinate has "
                                f"these digits ->{sign_note} point put after {before} digit(s), {learned} "
                                f"({shape_text}) -> '{cell['value']}'")
                if after is not None and len(digits) - before != after:
                    cell["warning"] = (f"⚠ '{cell['value']}' has {len(digits) - before} digit(s) after the point; "
                                       f"the column's others have {after} - check the snip")
                    cell["note"] += f"  {cell['warning']}"
            print(f"COORDINATE CHECK: {item['title']} - {cell['name']}: {cell['note']}")


NUMBER_CELL_CHARS = re.compile(r"[0-9.,:+\-\s]")


def dt_cell_ink(arr):
    """Ink pixels of a table cell picture: dark pixels or strongly coloured ones - not the
    paper (white) and not a yellow / green / blue row fill (light colours)."""
    value = arr.max(axis=2)
    spread = value - arr.min(axis=2)
    return (value < 150) | ((spread > 80) & (value < 200))


def dt_ink_blocks(cell_image):
    """The ink of a cell picture, its own grid lines left out (rows / columns that are
    ink almost all the way across), split into blocks at gaps of 2+ empty pixel
    columns. Returns (array, ink mask, [(x0, x1)])."""
    arr = np.array(cell_image.convert("RGB")).astype(np.int16)
    ink = dt_cell_ink(arr)
    ink[ink.mean(axis=1) > 0.6] = False              # horizontal grid lines of the cell
    ink[:, ink.mean(axis=0) > 0.8] = False           # vertical grid lines of the cell
    cols = np.where(ink.any(axis=0))[0]
    blocks = []
    if len(cols):
        start = cols[0]
        for x_a, x_b in zip(cols, cols[1:]):
            if x_b - x_a > 2:
                blocks.append((int(start), int(x_a)))
                start = x_b
        blocks.append((int(start), int(cols[-1])))
    return arr, ink, blocks


def dt_column_alignment(pictures):
    """How the values of a column sit in their cells, learned from its cleanly read
    cells: 'centred', 'left' or 'right', with the typical left / right margins (px)."""
    lefts, rights, widths = [], [], []
    for picture in pictures:
        _arr, _ink, blocks = dt_ink_blocks(picture)
        if not blocks:
            continue
        x0, x1 = blocks[0][0], blocks[-1][1]
        lefts.append(x0)
        rights.append(picture.width - 1 - x1)
        widths.append(picture.width)
    if len(lefts) < 2:
        return None
    left, right, width = float(np.median(lefts)), float(np.median(rights)), float(np.median(widths))
    tolerance = max(3.0, 0.08 * width)
    if abs(left - right) <= tolerance:
        kind = "centred"
    elif left < right:
        kind = "left"
    else:
        kind = "right"
    return {"kind": kind, "left": left, "right": right, "cells": len(lefts), "tolerance": tolerance}


def dt_clean_by_alignment(cell_image, alignment):
    """1st check: what the column's alignment allows. The value is the run of ink blocks
    that sits where this column's values sit (centred: its middle within a few px of the
    cell's middle; left / right aligned: starting / ending at the column's usual margin).
    Ink anywhere else is not possible for a value of this column and is painted over
    with the cell's background. Returns (picture or None, what was found)."""
    arr, ink, blocks = dt_ink_blocks(cell_image)
    w = arr.shape[1]
    if len(blocks) < 2:
        return None, "the ink is one block - nothing outside the value"
    tol = alignment["tolerance"]
    best = None
    for i in range(len(blocks)):
        for j in range(i, len(blocks)):
            x0, x1 = blocks[i][0], blocks[j][1]
            if alignment["kind"] == "centred":
                fits = abs((x0 + x1) / 2 - (w - 1) / 2) <= tol
            elif alignment["kind"] == "left":
                fits = abs(x0 - alignment["left"]) <= tol
            else:
                fits = abs((w - 1 - x1) - alignment["right"]) <= tol
            ink_count = int(ink[:, x0:x1 + 1].sum())
            if fits and (best is None or ink_count > best[2]):
                best = (i, j, ink_count)
    if best is None:
        return None, f"no part of the ink sits where a {alignment['kind']} value would"
    keep_x0, keep_x1 = blocks[best[0]][0], blocks[best[1]][1]
    # everything outside the value's x range is painted over - marks AND full-height
    # lines inside the cell (e.g. a selected neighbour's 1 px outline); only the cell's
    # own horizontal grid lines are kept
    all_ink = dt_cell_ink(arr)
    all_ink[all_ink.mean(axis=1) > 0.6] = False
    outside_mask = all_ink.copy()
    outside_mask[:, keep_x0:keep_x1 + 1] = False
    if not outside_mask.any():
        return None, "everything is inside the value"
    xs_out = np.where(outside_mask.any(axis=0))[0]
    runs, start = [], xs_out[0]
    for x_a, x_b in zip(xs_out, xs_out[1:]):
        if x_b - x_a > 1:
            runs.append((int(start), int(x_a)))
            start = x_b
    runs.append((int(start), int(xs_out[-1])))
    background = np.median(arr[~dt_cell_ink(arr)], axis=0) if (~dt_cell_ink(arr)).any() else np.array([255, 255, 255])
    arr[outside_mask] = background
    where = ", ".join(f"x={x0}-{x1}" for x0, x1 in runs)
    what = (f"values in this column are {alignment['kind']} (from {alignment['cells']} clean cells: margins "
            f"left ~{alignment['left']:.0f} px, right ~{alignment['right']:.0f} px); the value is ink x={keep_x0}-{keep_x1}, "
            f"so ink at {where} is outside where a value can be - left out")
    return Image.fromarray(arr.astype(np.uint8)), what


def dt_find_clicked_cell(table_image):
    """2nd check, only when something besides the number is STILL read: a selected
    ('clicked') cell in the table picture. Strongly coloured pixels in strokes 2+ px
    thick are grouped by colour (letters' smoothing edges come in several colours, an
    outline is ONE colour); a colour whose pixels form a rectangle outline (its top /
    bottom rows and left / right columns each mostly covered) and that is smaller than a
    quarter of the table is a selected cell. Returns ((x0, y0, x1, y1), colour) or None."""
    arr = np.asarray(table_image.convert("RGB")).astype(np.int16)
    value = arr.max(axis=2)
    spread = value - arr.min(axis=2)
    coloured = (spread > 80) & (value < 200)
    thick = coloured[:-1, :-1] & coloured[1:, :-1] & coloured[:-1, 1:] & coloured[1:, 1:]
    pixels = arr[:-1, :-1]
    found = pixels[thick]
    if len(found) < 20:
        return None
    bins = (found // 24) * 24
    keys, counts = np.unique(bins, axis=0, return_counts=True)
    for k in np.argsort(-counts):
        if counts[k] < 20:
            break
        centre = keys[k] + 12
        mask = thick & (np.abs(pixels - centre).sum(axis=2) < 90)
        if mask.sum() < 20:
            continue
        # horizontal lines of this colour: rows with 20+ of its pixels, grouped
        rows_hit = np.where(mask.sum(axis=1) >= 20)[0]
        lines = []
        for y in rows_hit:
            xs = np.where(mask[y])[0]
            if lines and y - lines[-1]["y1"] <= 2:
                lines[-1].update(y1=int(y), x0=min(lines[-1]["x0"], int(xs.min())), x1=max(lines[-1]["x1"], int(xs.max())))
            else:
                lines.append({"y0": int(y), "y1": int(y), "x0": int(xs.min()), "x1": int(xs.max())})
        # a top and a bottom line with the same x range, joined by this colour at both
        # ends (Excel also colours the selected cell's column letter and row number -
        # those are single lines, not a rectangle, so they do not count)
        for i, top in enumerate(lines):
            for bottom in lines[i + 1:]:
                if abs(top["x0"] - bottom["x0"]) > 6 or abs(top["x1"] - bottom["x1"]) > 6:
                    continue
                x0, x1 = min(top["x0"], bottom["x0"]), max(top["x1"], bottom["x1"])
                y0, y1 = top["y0"], bottom["y1"]
                if y1 - y0 < 6 or x1 - x0 < 6:
                    continue
                # the sides may be 1 px wide: colour only (the thick top / bottom lines are the size proof)
                side = coloured[:-1, :-1] & (np.abs(pixels - centre).sum(axis=2) < 90)
                left = side[y0:y1 + 1, max(0, x0 - 3):x0 + 4].any(axis=1).mean()
                right = side[y0:y1 + 1, max(0, x1 - 3):x1 + 5].any(axis=1).mean()
                if left >= 0.6 and right >= 0.6:
                    colour = tuple(int(c) for c in np.median(pixels[mask][:2000], axis=0))
                    return (x0, y0, x1 + 1, y1 + 1), colour
    return None


def dt_clean_by_clicked_cell(cell_image, cell_box, clicked):
    """Paints over, in this cell, the pixels that have the clicked cell's outline colour
    and lie within 6 px of that outline (its corner handle included)."""
    (x0, y0, x1, y1), colour = clicked
    arr = np.array(cell_image.convert("RGB")).astype(np.int16)
    h, w = arr.shape[:2]
    cx0, cy0 = cell_box[0], cell_box[1]
    yy, xx = np.mgrid[0:h, 0:w]
    px, py = xx + cx0, yy + cy0
    near = ((px >= x0 - 6) & (px <= x1 + 6) & (py >= y0 - 6) & (py <= y1 + 6) &
            ~((px > x0 + 6) & (px < x1 - 6) & (py > y0 + 6) & (py < y1 - 6)))
    same_colour = np.abs(arr - np.array(colour)).sum(axis=2) < 150
    mask = near & same_colour
    if not mask.any():
        return None, "none of its outline is in this cell"
    ink = dt_cell_ink(arr)
    background = np.median(arr[~ink], axis=0) if (~ink).any() else np.array([255, 255, 255])
    arr[mask] = background
    return Image.fromarray(arr.astype(np.uint8)), f"{int(mask.sum())} px of its outline are in this cell - left out"


def dt_fix_stray_marks(items, table_image=None, grid=None):
    """Number cells whose read has a character that cannot be in a number (e.g.
    '！211444.80'):
      1. the column's alignment is learned from its cleanly read cells (centred / left /
         right). Anything outside where a value of this column can be is ignored and
         the cell read again.
      2. only if something besides the number is STILL read: a clicked (selected) cell
         is searched for in the table picture - its outline colour near that cell is
         left out and the cell read again."""
    columns = defaultdict(list)
    for item in items:
        for cell in item["cells"]:
            if cell.get("column") is not None and cell.get("value"):
                columns[cell["column"]].append((item, cell))
    clicked = "not searched"
    for entries in columns.values():
        clean = [(i, c) for i, c in entries if re.fullmatch(r"-?[\d.,:]+", c["value"].replace(" ", ""))]
        if len(clean) < max(2, len(entries) / 2):
            continue                                 # not a number column
        suspects = [(i, c) for i, c in entries
                    if NUMBER_CELL_CHARS.sub("", c["value"]) and len(re.findall(r"\d", c["value"])) >= 3]
        if not suspects:
            continue
        alignment = dt_column_alignment([c["ocr_source"] for _, c in clean if c.get("ocr_source") is not None])
        for item, cell in suspects:
            first, now, picture, steps = cell["value"], cell["value"], cell.get("ocr_source"), []
            if picture is not None and alignment:
                cleaned, what = dt_clean_by_alignment(picture, alignment)
                if cleaned is not None:
                    now = dt_read_cells([cleaned])[0].strip() or now
                    picture = cleaned
                    what += f" -> read again '{now}'"
                steps.append(f"alignment check: {what}")
            elif picture is not None:
                steps.append("alignment check: fewer than 2 clean cells in this column to learn the alignment from")
            if NUMBER_CELL_CHARS.sub("", now) and picture is not None and table_image is not None and grid:
                if clicked == "not searched":
                    clicked = dt_find_clicked_cell(table_image)
                if clicked is None:
                    steps.append("clicked-cell check: no selected cell's outline found in the table")
                else:
                    (bx0, by0, bx1, by1), colour = clicked
                    rows, cols = grid["rows"], grid["columns"]
                    cell_box = (cols[cell["column"]] + 1, rows[item["row"]] + 1)
                    cleaned, what = dt_clean_by_clicked_cell(picture, cell_box, clicked)
                    if cleaned is not None:
                        now = dt_read_cells([cleaned])[0].strip() or now
                        what += f" -> read again '{now}'"
                    steps.append(f"clicked-cell check: a selected cell's outline rgb{colour} found at "
                                 f"x={bx0}-{bx1}, y={by0}-{by1} of the table; {what}")
            if now != first and not NUMBER_CELL_CHARS.sub("", now):
                cell["value"] = now.replace(" ", "")
                cell["note"] = f"first read '{first}' had a mark that is not a number; " + "; ".join(steps)
                print(f"STRAY MARK CHECK: {item['title']} - {cell['name']}: {cell['note']}")
            else:
                cell["warning"] = f"⚠ '{first}' has a mark that is not a number and it stayed - check the snip"
                print(f"STRAY MARK CHECK: {item['title']} - {cell['name']}: '{first}' - "
                      + "; ".join(steps) + " -> not fixed, kept as read (check the snip)")


def check_number_formats_by_column(items, known_coordinates=None, table_image=None, grid=None, tesseract=None):
    """Coloured rows only. In each column, numbers normally share one shape (e.g.
    longitude '-##.########'). A read with a different shape (lost '-', lost '.')
    is read again other ways; a re-read that has the column's shape is used and
    reported. If none has it, the cell keeps its read and gets a warning."""
    columns = defaultdict(list)
    for item in items:
        for cell in item["cells"]:
            if cell.get("column") is not None:
                columns[cell["column"]].append((item, cell))
    # marks that are not a number in a number cell: found in the picture and left out
    dt_fix_stray_marks(items, table_image, grid)
    # clock columns (Seam Position, o'clock): a value must read as h:mm
    for item in items:
        for cell in item["cells"]:
            name = re.sub(r"[^a-z]", "", cell["name"].lower())
            if not re.search(r"clock|seamposit", name) or not cell["value"]:
                continue
            if re.fullmatch(r"\d{1,2}:\d{2}", cell["value"].replace(" ", "")):
                continue
            first_read = cell["value"]
            theirs = tesseract(item["row"], cell.get("column")) if tesseract else None   # S354
            for text, how in dt_alternative_reads(cell["ocr_source"], theirs):
                if re.fullmatch(r"\d{1,2}:\d{2}", text.replace(" ", "")):
                    cell["value"] = text.replace(" ", "")
                    cell["note"] = (f"first read '{first_read}' is not a clock time (h:mm); "
                                    f"read again ({how}) -> '{cell['value']}'")
                    break
            else:
                cell["warning"] = f"⚠ '{first_read}' is not a clock time (h:mm) - check the snip"
            print(f"CLOCK CHECK: {item['title']} - {cell['name']}: " + (cell.get("note") or cell.get("warning")))
    # latitude / longitude: fixed by matching digits or by their known shape (no re-reads)
    dt_fix_coordinate_cells(items, known_coordinates)
    for column, entries in columns.items():
        if any(re.search(r"clock|seamposit", re.sub(r"[^a-z]", "", c["name"].lower())) for _, c in entries):
            continue
        if any(re.match(r"(latitude|longitude)", re.sub(r"[^a-z]", "", c["name"].lower())) for _, c in entries):
            continue                                   # done above
        shapes = Counter(dt_number_shape(cell["value"]) for _, cell in entries)
        shapes.pop(None, None)
        if not shapes:
            continue
        shape, count = shapes.most_common(1)[0]
        if count < 2 or count <= sum(shapes.values()) / 2:
            continue                                   # no clear shape for this column
        for item, cell in entries:
            own = dt_number_shape(cell["value"])
            if own is None or own == shape:
                continue
            first_read = cell["value"]
            theirs = tesseract(item["row"], cell.get("column")) if tesseract else None   # S354
            for text, how in dt_alternative_reads(cell["ocr_source"], theirs):
                if dt_number_shape(text) == shape:
                    cell["value"] = text.replace(" ", "")
                    cell["note"] = (f"first read '{first_read}' did not look like this column's other rows "
                                    f"({dt_shape_text(shape)}); read again ({how}) -> '{cell['value']}'")
                    break
            else:
                cell["warning"] = (f"⚠ '{first_read}' does not look like this column's other coloured rows "
                                   f"({dt_shape_text(shape)}) - check the snip")
            print(f"NUMBER SHAPE CHECK: {item['title']} - {cell['name']}: "
                  + (cell.get("note") or cell.get("warning")))
    for item in items:
        item["value"] = "\n".join(f"{c['name']}: {c['value']}" for c in item["cells"])


def map_note_wheel_digits(map_pages):
    """The Wheel Counts printed in the yellow map notes, as digits only ('211442.45' ->
    '21144245'), so a table read with a lost point or a gap ('211442 45') still matches."""
    found = set()
    for map_page in map_pages or []:
        for note in map_page.get("notes", []):
            wheel = re.search(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)", str(note.get("value") or ""), re.IGNORECASE)
            if wheel:
                found.add(re.sub(r"\D", "", wheel.group(1)))
    return found


def extract_table_highlights(document, skip_pages, map_wheel_digits=frozenset()):
    """Every table page with coloured rows / cells -> overall row snips + one snip per cell.
    A white row whose Odometer is the Wheel Count of a map note also gets the cells
    that note can be compared with read (Latitude, Longitude, Int/Ext). S355: the PDF is used (its turn
    taken) only to get the table pictures and the printed coordinates - the OCR of the tables runs after
    that, so a document that needs the PDF meanwhile (a 6000 form, a Pages tab) does not wait for it."""
    pages = []
    print()
    print("Scanning Dig Packet for table pages with highlighted rows / cells...")
    _t = lap_timer(2)
    pictures = []
    with pdf_turn("Dig Packet: table pages"):
        for page_index in range(len(document)):
            page_number = page_index + 1
            if page_number in skip_pages:
                continue
            ready = pdf_prefetched("tables", document, page_index)
            if ready is not None:
                image, grid = ready["image"], ready["grid"]
            else:
                image = dt_page_table_image(document, document[page_index])
                grid = dt_find_grid(image)
            if grid:
                pictures.append((page_number, image, grid))
        printed_coordinates = dt_known_coordinates(document) if pictures else {}
    packet_name = os.path.splitext(os.path.basename(getattr(document, "name", "") or ""))[0] or "this Dig Packet"
    for page_number, image, grid in pictures:
        pixels = np.asarray(image.convert("RGB")).astype(int)
        rows, columns = grid["rows"], grid["columns"]
        found = []                                    # (row, [cols], colour, whole_row)
        for r in range(len(rows) - 1):
            colours = [dt_cell_colour(pixels, columns[c], rows[r], columns[c + 1], rows[r + 1])
                       for c in range(len(columns) - 1)]
            coloured = [c for c, v in enumerate(colours) if v]
            if not coloured:
                continue
            names = [dt_colour_name(colours[c]) for c in coloured]
            main = max(set(names), key=names.count)
            # any coloured cell -> the whole row's info is read (like a fully coloured row)
            whole = names.count(main) >= TABLE_ROW_COLOURED_SHARE * len(colours)
            found.append((r, coloured, main, whole))
        if not found:
            print(f"Page {page_number}: table found, no highlighted rows / cells.")
            continue
        # white rows between a yellow row and the next coloured row (any colour but
        # white) above it and below it are read too. Going up / down stops at the
        # first coloured row; if none comes, it stops at the table's first / last row.
        coloured_rows = {entry[0] for entry in found}
        between = {}                                  # row -> {"above", "below"}
        for r, _cols, colour, _whole in found:
            if colour != "yellow":
                continue
            for step, side in ((-1, "above"), (+1, "below")):
                k = r + step
                while 0 <= k < len(rows) - 1 and k not in coloured_rows:
                    between.setdefault(k, set()).add(side)
                    k += step
                if not 0 <= k < len(rows) - 1:
                    print(f"Page {page_number}: going {'up' if step < 0 else 'down'} from the yellow row "
                          f"reached the table's {'first' if step < 0 else 'last'} row without a coloured row")
        found = sorted(found + [(k, [], "white", True) for k in between], key=lambda entry: entry[0])
        _t(f"Pages up to {page_number}: render + find table grid + coloured rows")
        # S393: the same picture read before (the same table page in another Dig Packet) - its readings are reused
        fingerprint = table_page_fingerprint(image, grid)
        with TABLE_READS["lock"]:
            seen = TABLE_READS["pages"].get(fingerprint)
            if seen is None:
                seen = TABLE_READS["pages"][fingerprint] = {"from": f"page {page_number} of {packet_name}",
                                                            "headers": None, "cells": {}, "tesseract": {}}
        if seen["headers"] is not None:
            print(f"TABLE PAGE: page {page_number} of {packet_name} is the same picture as {seen['from']} - its "
                  f"reading is reused (column headers, cell reads, Tesseract's reads) (S393)")
        # S354: Tesseract reads every cell of these rows on the processor while PaddleOCR reads them on the GPU
        tesseract = tesseract_start(image, grid, sorted(entry[0] for entry in found), seen["tesseract"])
        if seen["headers"] is not None:
            headers = list(seen["headers"])
            _t(f"Page {page_number}: column headers (reused - S393)")
        else:
            with easy_stretch("its table headers"):      # S401/S403b: the whole header step, headings included
                headers = dt_read_headers(image, grid)
            seen["headers"] = list(headers)
            _t(f"Page {page_number}: column headers")
            start_labels_ahead()      # S402/S403a: after ALL the header reads (its headings' EasyOCR reads too)

        def read_cells(jobs):
            """The cells' texts - S393: a cell of this picture read before is not read again."""
            todo = [job for job in jobs if job not in seen["cells"]]
            if todo:
                seen["cells"].update(zip(todo, dt_read_cells(
                    [image.crop((columns[c] + 1, rows[r] + 1, columns[c + 1], rows[r + 1])) for r, c in todo])))
            return {job: seen["cells"][job] for job in jobs}
        event_col = dt_find_column(headers, "event")
        feature_col = dt_find_column(headers, "feature")
        odometer_col = dt_find_column(headers, "odometer")
        seam_position_col = dt_find_column(headers, "seamposit", "position")
        print(f"Page {page_number}: TABLE PAGE - {len(found) - len(between)} highlight(s) "
              f"+ {len(between)} white row(s) between yellow and coloured rows "
              f"| {len(rows) - 1} rows x {len(columns) - 1} columns")
        items = []
        # every cell this page will read, read in batches up front (same reads as before)
        cell_jobs = []
        for r, cols, colour, whole in found:
            needed = {0, feature_col, odometer_col}
            if colour == "white":
                needed |= {event_col}
            else:
                needed |= {seam_position_col, event_col} | set(range(1, len(columns) - 1))
            for c in sorted(c for c in needed if c is not None and 0 <= c < len(columns) - 1):
                cell_jobs.append((r, c))
        reused = sum(job in seen["cells"] for job in cell_jobs)
        cell_texts = read_cells(cell_jobs)
        # a white row whose Odometer is a map note's Wheel Count: the cells the note can be
        # compared with are read too (Latitude, Longitude, Int/Ext), so the comparison
        # after the map / table reading has every value it can compare
        compare_cols = [c for c in (dt_find_column(headers, "latitude"), dt_find_column(headers, "longitude"),
                                    dt_find_column(headers, "intext"))
                        if c is not None and 0 <= c < len(columns) - 1]
        map_rows = set()
        if map_wheel_digits and odometer_col is not None and compare_cols:
            map_rows = {r for r, _cols, colour, _whole in found if colour == "white"
                        and re.sub(r"\D", "", cell_texts.get((r, odometer_col), "")) in map_wheel_digits}
        if map_rows:
            extra_jobs = [(r, c) for r in sorted(map_rows) for c in compare_cols]
            reused += sum(job in seen["cells"] for job in extra_jobs)
            cell_texts.update(read_cells(extra_jobs))
            compare_names = ", ".join(headers[c] or f"column {c + 1}" for c in compare_cols)
            for r in sorted(map_rows):
                feature_text = cell_texts.get((r, feature_col), "") if feature_col is not None else ""
                print(f"MAP NOTE ROW: page {page_number} white row {feature_text} - Odometer "
                      f"{cell_texts.get((r, odometer_col), '')} is the Wheel Count of a map note -> "
                      f"{compare_names} read too, to compare with the note")
        _t(f"Page {page_number}: cell reads ({len(cell_jobs)} cells, batched"
           + (f"; + {len(map_rows) * len(compare_cols)} for {len(map_rows)} white row(s) on a map note" if map_rows else "")
           + (f"; {reused} reused from {seen['from']} - S393" if reused else "")
           + ")")
        for r, cols, colour, whole in found:
            y0, y1 = rows[r], rows[r + 1]

            def read(c, r=r, y0=y0, y1=y1):
                if (r, c) in cell_texts:
                    return cell_texts[(r, c)]
                if (r, c) not in seen["cells"]:                       # S393: kept for the same picture again
                    seen["cells"][(r, c)] = dt_read_cell(image.crop((columns[c] + 1, y0 + 1, columns[c + 1], y1)))
                return seen["cells"][(r, c)]

            # dataC (accuracy fix A5): specks read next to the x ('：×') do not hide it
            defect = re.sub(r"[\s:：;；.,，'`|_\-]+", "", read(0)).lower() in {"x", "×"}
            feature = read(feature_col) if feature_col is not None else ""
            odometer = read(odometer_col) if odometer_col is not None else ""   # = wheel count
            if colour == "white":
                # white rows between yellow and coloured rows: only the Event name and the
                # Wheel Count (Odometer) are read - no other cells, no full-width row snip
                seam_position = ""
                wanted = [c for c in (event_col, odometer_col) if c is not None]
                if r in map_rows:
                    wanted += compare_cols
            else:
                seam_position = read(seam_position_col) if seam_position_col is not None else ""
                wanted = ([event_col] if event_col is not None else []) + \
                         [c for c in range(1, len(columns) - 1) if c != event_col]
            if colour == "white":
                sides = between.get(r, set())
                what = ("white row between yellow rows" if sides == {"above", "below"} else
                        f"white row {'above' if 'above' in sides else 'below'} the yellow row")
            elif whole:
                what = f"{colour} row"
            else:
                coloured_names = ", ".join(headers[c] or f"column {c + 1}" for c in cols)
                what = f"{colour} {coloured_names} cell" + ("s" if len(cols) > 1 else "")
            title = f"Row{(' ' + feature) if feature else ''} ({what}{', x = defect' if defect else ''})"
            white = colour == "white"
            overview = None if white else dt_row_snip(image, grid, r)   # (header, row) real snips
            cells = []
            for c in wanted:
                if c == feature_col and feature:
                    value = feature
                elif white and c == odometer_col:
                    value = odometer                   # already read above - not read twice
                else:
                    value = read(c)
                if not value:
                    continue                           # empty cells of a row are not shown
                name = headers[c] or f"Column {c + 1}"
                header_snip, cell_snip = dt_cell_snip(image, grid, r, c)
                cells.append({"name": name, "value": value, "image": cell_snip,
                              "header_image": None if white else header_snip,
                              "column": c, "ocr_source": image.crop((columns[c] + 1, y0 + 1, columns[c + 1], y1)),
                              "grid_box": (int(columns[c]), int(y0), int(columns[c + 1]), int(y1)),     # S175
                              "for_map_compare": white and c in compare_cols})
            if white:                                  # one short terminal line per white row
                print(f"    {title}: " + " | ".join(c["value"] for c in cells))
            else:
                # coloured rows: one short line here too (Event | Odometer) - every cell is
                # listed once, in the DIG PACKET summary at the end
                short = [c["value"] for c in cells
                         if re.match(r"(event|odometer)", re.sub(r"[^a-z]", "", c["name"].lower()))]
                print(f"    {title}: " + " | ".join(short or [c["value"] for c in cells[:2]]))
            items.append({"title": title, "overview": overview, "cells": cells, "row": r, "odometer": odometer,
                          "seam_position": seam_position,
                          "whole_row": whole, "colour": colour, "defect": defect, "feature": feature,
                          "between_yellow": colour == "white",
                          "value": "\n".join(f"{c['name']}: {c['value']}" for c in cells)})
        _t(f"Page {page_number}: rows + row / cell snips")
        cell_rest_check(page_number, items, tesseract)             # S424: anything the read missed in its cell
        _t(f"Page {page_number}: cell rest check (S424b)")
        dt_check_code_units(headers, items)
        check_number_formats_by_column(items, known_coordinates=lambda: printed_coordinates,
                                       table_image=image, grid=grid, tesseract=tesseract)
        tesseract_compare(page_number, items, tesseract)
        typed_text_check(page_number, items, tesseract)            # S375
        _t(f"Page {page_number}: clock / coordinate / number shape checks + typed-text check")

        # white rows in runs (next to each other): one REAL snip per run of the Event +
        # Odometer columns - header band and rows band, two separate crops - including
        # the coloured row just above and just below the run, like a cut-out of the table
        white_runs = []
        run = []
        for r in sorted(between) + [None]:
            if run and (r is None or r != run[-1] + 1):
                first, last = run[0], run[-1]
                top_row = first - 1 if first - 1 in coloured_rows else first
                bottom_row = last + 1 if last + 1 in coloured_rows else last
                snip_cols = [c for c in (event_col, odometer_col) if c is not None]
                header_snip = rows_snip = None
                if snip_cols:
                    x0, x1 = columns[min(snip_cols)], columns[max(snip_cols) + 1] + 1
                    header_band = grid.get("header")
                    header_snip = image.crop((x0, header_band[0], x1, header_band[1] + 1)) if header_band else None
                    rows_snip = image.crop((x0, rows[top_row], x1, rows[bottom_row + 1] + 1))
                white_runs.append({
                    "rows": list(run),
                    "features": [i.get("feature") for i in items if i["row"] in run],
                    "with_above": top_row != first, "with_below": bottom_row != last,
                    "header_snip": header_snip, "rows_snip": rows_snip,
                })
                run = []
            if r is not None:
                run.append(r)
        pages.append({"page_number": page_number, "items": items, "white_runs": white_runs})
        _t(f"Page {page_number}: white-row run snips")
    if not pages:
        print("No table page with highlighted rows / cells.")
    return pages


def dm_red_text_notes(page, page_image, yellow_mask, zoom):
    """Red text written on the map outside the yellow callout boxes (e.g. 'Note: Dresser
    220 Sleeve Installed ...'), read exactly from the PDF's text layer - no OCR.
    Red = the text colour's red channel >= 150 with green and blue <= 90. Text whose
    centre sits on the yellow callout surface is skipped (it belongs to a callout box).
    Lines of one note (stacked, overlapping left-right) are joined into one note.
    A map that is only a picture (no text layer) gives no red notes."""
    lines = []
    try:
        data = page.get_text("dict")
    except Exception as exc:
        print(f"  Red map notes: text layer not readable ({exc})")
        return []
    for block in data.get("blocks", []):
        for line in block.get("lines", []):
            red_spans = []
            for span in line.get("spans", []):
                colour = int(span.get("color", 0))
                r, g, b = (colour >> 16) & 255, (colour >> 8) & 255, colour & 255
                if r >= 150 and g <= 90 and b <= 90 and span.get("text", "").strip():
                    red_spans.append(span)
            if not red_spans:
                continue
            x0 = min(sp["bbox"][0] for sp in red_spans); y0 = min(sp["bbox"][1] for sp in red_spans)
            x1 = max(sp["bbox"][2] for sp in red_spans); y1 = max(sp["bbox"][3] for sp in red_spans)
            if yellow_mask is not None:
                region = yellow_mask[max(0, int(y0 * zoom)):int(y1 * zoom) + 1,
                                     max(0, int(x0 * zoom)):int(x1 * zoom) + 1]
                if region.size and (region > 0).mean() >= 0.30:
                    continue                               # on a yellow callout box
            lines.append({"text": " ".join(sp["text"].strip() for sp in red_spans),
                          "bbox": [x0, y0, x1, y1]})
    lines.sort(key=lambda l: (l["bbox"][1], l["bbox"][0]))
    groups = []
    for line in lines:
        height = line["bbox"][3] - line["bbox"][1]
        last = groups[-1] if groups else None
        if (last and -height * 0.6 <= line["bbox"][1] - last["bbox"][3] <= height * 1.2
                and line["bbox"][0] < last["bbox"][2] and line["bbox"][2] > last["bbox"][0]):
            last["lines"].append(line["text"])
            last["bbox"] = [min(last["bbox"][0], line["bbox"][0]), last["bbox"][1],
                            max(last["bbox"][2], line["bbox"][2]), line["bbox"][3]]
        else:
            groups.append({"lines": [line["text"]], "bbox": list(line["bbox"])})
    notes = []
    for index, group in enumerate(groups, start=1):
        x0, y0, x1, y1 = group["bbox"]
        pad = 12
        snip = page_image.crop((max(0, int(x0 * zoom) - pad), max(0, int(y0 * zoom) - pad),
                                min(page_image.width, int(x1 * zoom) + pad),
                                min(page_image.height, int(y1 * zoom) + pad)))   # real crop
        notes.append({"index": index, "value": "\n".join(group["lines"]), "image": snip,
                      "page_box": (max(0, int(x0 * zoom) - pad), max(0, int(y0 * zoom) - pad),        # S175
                                   min(page_image.width, int(x1 * zoom) + pad),
                                   min(page_image.height, int(y1 * zoom) + pad))})
        print(f"  Red map note {index}: " + " ".join(group["lines"]))
    return notes


MAP_ROAD_WORDS = (r"\b(road|rd|street|st|highway|hwy|lane|ln|drive|dr|avenue|ave|boulevard|blvd|parkway|pkwy|"
                  r"route|rte|interstate|freeway|trail|way)\b|\b(cr|fm|sh|us|i)[- ]?\d+\b")   # S249: a road's name
MAP_TEXT_SAME_DIRECTION = 0.08      # S246: letters this close in writing direction belong to one rotated label
MAP_TEXT_LETTER_REACH = 2.6         # S246: ... and whose centres are within this many letter sizes
MAP_TEXT_WORD_GAP = 0.2             # S246: a gap this much (x letter size) wider than the usual one is a space


def dm_other_map_text(page, page_image, holders, zoom):
    """S246: the map's other printed text, read exactly from the PDF's text layer - road names
    in any direction ('Santa Fe Road 77+2017' written upwards, 'Springridge Texas Line Road'
    on a slant - maps place such labels letter by letter, so the letters are joined along their
    writing direction, with a space where the gap is wider than the usual letter gap) and the
    title block ('2026 ILI Carthage to Red River / SHC 20-1 / Caddo Parish, LA'). Left out: text
    inside a yellow note, a pipeline data block or a red note (holders - map page pixel boxes),
    the scale bar (numbers, 'Feet'), compass letters, lone symbols and the imagery credit
    ('Source: Esri ...' and its next line). Returns ([{'index', 'value', 'page_box', 'image'}] (pixels;
    S247: 'image' = its snip), what was left out and why - for the terminal)."""
    left_out = Counter()                      # S247: why text was left out - shown in the terminal
    try:
        data = page.get_text("rawdict")
    except Exception as exc:
        print(f"  Other map text: text layer not readable ({exc})")
        return [], left_out

    def held(x0, y0, x1, y1):
        cx, cy = (x0 + x1) / 2 * zoom, (y0 + y1) / 2 * zoom
        return any(h and h[0] - 4 <= cx <= h[2] + 4 and h[1] - 4 <= cy <= h[3] + 4 for h in holders)

    flat, letters = [], []                 # straight lines; letters of slanted / upright labels
    for block in data.get("blocks", []):
        for line in block.get("lines", []):
            dx, dy = line.get("dir", (1, 0))
            chars = [(ch, span["size"]) for span in line.get("spans", []) for ch in span.get("chars", [])]
            if abs(dy) < 0.05:
                text = "".join(ch["c"] for ch, _s in chars).strip()
                x0, y0, x1, y1 = line["bbox"]
                if text and held(x0, y0, x1, y1):
                    left_out["in a note / data block / red note"] += 1
                elif text:
                    flat.append({"text": " ".join(text.split()), "box": [x0, y0, x1, y1],
                                 "size": max([s for _c, s in chars] or [0])})
                continue
            for ch, size in chars:
                x0, y0, x1, y1 = ch["bbox"]
                if ch["c"].strip() and held(x0, y0, x1, y1):
                    left_out["letter in a note / data block / red note"] += 1
                elif ch["c"].strip():
                    letters.append({"c": ch["c"], "cx": (x0 + x1) / 2, "cy": (y0 + y1) / 2, "dx": dx, "dy": dy,
                                    "size": size, "w": x1 - x0, "h": y1 - y0, "box": [x0, y0, x1, y1]})
    found = []
    # straight lines: the imagery credit and its next line out; lines stacked on one centre = one block
    flat.sort(key=lambda l: (l["box"][1], l["box"][0]))
    # S249: the imagery credit ('Source: Esri ...') and the lines of the same small size right under it
    # or beside it ('Community') - a bigger line under it (the title block) is not the credit
    credits = [l for l in flat if re.match(r"source\s*:", l["text"], re.IGNORECASE)]
    for line in flat:
        x0, y0, x1, y1 = line["box"]
        if line in credits or any(
                abs(line["size"] - c["size"]) <= 1.0 and -(c["box"][3] - c["box"][1]) <= y0 - c["box"][3]
                <= (c["box"][3] - c["box"][1]) * 1.5 and x0 < c["box"][2] + 20 and x1 > c["box"][0] - 20
                for c in credits):
            left_out["imagery credit"] += 1
            continue
        if re.fullmatch(r"[NSEW]|[\d\s.,]+|feet|[^A-Za-z0-9]+", line["text"], re.IGNORECASE):
            left_out["scale / compass / symbol"] += 1
            continue
        last = found[-1] if found and found[-1].get("flat") else None
        lx0, _ly0, lx1, ly1 = last["box"] if last else (0, 0, 0, 0)
        aligned = last and min(abs((x0 + x1) / 2 - (lx0 + lx1) / 2), abs(x0 - lx0), abs(x1 - lx1)) <= 10  # S249
        if aligned and 0 <= y0 - ly1 <= (y1 - y0) * 1.6:
            last["lines"].append(line["text"])
            last["box"] = [min(last["box"][0], x0), last["box"][1], max(last["box"][2], x1), y1]
        else:
            found.append({"flat": True, "lines": [line["text"]], "box": [x0, y0, x1, y1]})
    # rotated labels: letters of one direction chained by distance, read along the direction
    groups = []
    for letter in letters:
        home = next((g for g in groups if abs(g["dx"] - letter["dx"]) < MAP_TEXT_SAME_DIRECTION
                     and abs(g["dy"] - letter["dy"]) < MAP_TEXT_SAME_DIRECTION
                     and any(math.hypot(q["cx"] - letter["cx"], q["cy"] - letter["cy"])
                             < MAP_TEXT_LETTER_REACH * max(q["size"], letter["size"]) for q in g["items"])), None)
        if home is None:
            groups.append({"dx": letter["dx"], "dy": letter["dy"], "items": [letter]})
        else:
            home["items"].append(letter)
    for group in groups:
        items = sorted(group["items"], key=lambda q: q["cx"] * group["dx"] + q["cy"] * group["dy"])
        extent = lambda q: abs(q["w"] * group["dx"]) + abs(q["h"] * group["dy"])
        gaps = [(q["cx"] - p["cx"]) * group["dx"] + (q["cy"] - p["cy"]) * group["dy"] - (extent(p) + extent(q)) / 2
                for p, q in zip(items, items[1:])]
        usual = sorted(gaps)[len(gaps) // 2] if gaps else 0
        text = items[0]["c"]
        for gap, p, q in zip(gaps, items, items[1:]):
            text += (" " if gap - usual > MAP_TEXT_WORD_GAP * max(p["size"], q["size"]) else "") + q["c"]
        if len(re.findall(r"[A-Za-z0-9]", text)) < 2 or re.fullmatch(r"[\d\s.,]+|[^A-Za-z0-9 ]+", text):
            continue
        boxes = [q["box"] for q in items]
        found.append({"lines": [text], "box": [min(b[0] for b in boxes), min(b[1] for b in boxes),
                                               max(b[2] for b in boxes), max(b[3] for b in boxes)]})
    result = []
    for item in found:
        x0, y0, x1, y1 = item["box"]
        pad = 12
        box = (max(0, int(x0 * zoom) - pad), max(0, int(y0 * zoom) - pad),
               min(page_image.width, int(x1 * zoom) + pad), min(page_image.height, int(y1 * zoom) + pad))
        result.append({"index": len(result) + 1, "value": "\n".join(item["lines"]), "page_box": box,
                       "image": page_image.crop(box)})                                    # S247: its snip
        print(f"  Other map text {len(result)}: " + " / ".join(item["lines"]))
    return result, left_out


def dm_text_layer_blocks(page_words, zoom):
    """The page's straight text lines (PDF text layer) grouped into blocks: lines that
    start at the same left edge (within 3 pt) and follow each other at about one line
    spacing. Returns [{'lines': [(text, box_px)], 'box': (x0, y0, x1, y1) px}]."""
    lines = dm_text_layer_lines(page_words, (0, 0, 1e9, 1e9), zoom)
    blocks = []
    for text, box in lines:                            # already top to bottom
        height = box[3] - box[1]
        home, best = None, None
        for block in blocks:
            last_text, last = block["lines"][-1]
            # the next line of a block: same left edge, same size, and its top one line
            # spacing below the last line's top (line boxes may overlap - the step from
            # top to top is what counts, not the gap between the boxes)
            step = box[1] - last[1]
            if abs(box[0] - last[0]) <= 3 * zoom and 0.5 * height <= step <= 1.9 * height \
                    and abs(height - (last[3] - last[1])) <= 0.35 * height:
                if best is None or step < best:
                    home, best = block, step
        if home is None:
            blocks.append({"lines": [(text, box)]})
            continue
        else:
            home["lines"].append((text, box))
    for block in blocks:
        xs0, ys0, xs1, ys1 = zip(*(b for _t, b in block["lines"]))
        block["box"] = (min(xs0), min(ys0), max(xs1), max(ys1))
    return blocks


def dm_text_colour_name(colour):
    """0xRRGGBB -> 'red' (the same rule as the red map notes), 'black', or 'rgb(r, g, b)'."""
    r, g, b = (colour >> 16) & 255, (colour >> 8) & 255, colour & 255
    if r >= 150 and g <= 90 and b <= 90:
        return "red"
    if max(r, g, b) <= 80:
        return "black"
    return f"rgb({r}, {g}, {b})"


def dm_text_colour_in_box(page_words, box, zoom):
    """The colour most of the text inside a page-image box is printed in (counted by
    letters), as a name - or None when the words carry no colour."""
    bx0, by0, bx1, by1 = (v / zoom for v in box)
    counts = {}
    for w in page_words or []:
        if len(w) < 9:
            return None
        cx, cy = (w[0] + w[2]) / 2.0, (w[1] + w[3]) / 2.0
        if bx0 <= cx <= bx1 and by0 <= cy <= by1:
            counts[w[8]] = counts.get(w[8], 0) + len(str(w[4]))
    if not counts:
        return None
    return dm_text_colour_name(max(counts, key=counts.get))


def dm_map_page_from_text_layer(page_image, page_words, zoom):
    """A map page read from its text layer only - no picture box-finding and no OCR:
      - the text is grouped into blocks (dm_text_layer_blocks)
      - a block standing on the yellow callout surface (>= half of its area) is a
        yellow NOTE; its picture is the real page crop around it
      - a block that is not on yellow, has >= 5 lines and >= 2 pipeline words
        (O.D., W.T., GRADE, MAOP, HCA ...) is a PIPELINE DATA BLOCK
    Everything else (title, map labels, the red notes) is left to the other steps.
    Returns (note_boxes, pipeline_blocks, yellow_surface) - note_boxes is [] when no
    note is found this way (then the picture path is used)."""
    _raw, yellow = dm_reconstruct_yellow_surface(page_image)
    notes, pipeline = [], []
    for block in dm_text_layer_blocks(page_words, zoom):
        x0, y0, x1, y1 = (int(v) for v in block["box"])
        region = yellow[max(0, y0):y1 + 1, max(0, x0):x1 + 1]
        on_yellow = region.size and (region > 0).mean() >= 0.5
        texts = [re.sub(r"\s+", " ", t).strip() for t, _b in block["lines"]]
        pad = dm_V20_BLOCK_PADDING
        bx0, by0 = max(0, x0 - pad), max(0, y0 - pad)
        bx1, by1 = min(page_image.width, x1 + pad), min(page_image.height, y1 + pad)
        crop = page_image.crop((bx0, by0, bx1, by1))
        lines = [{"text": t, "confidence": 1.0, "x0": int(b[0]), "y0": int(b[1]), "x1": int(b[2]),
                  "y1": int(b[3]), "source": "PDF text layer"} for t, (_t0, b) in zip(texts, block["lines"])]
        if on_yellow:
            normalized = dm_normalize_yellow_lat_long_lines(texts)
            for line, text in zip(lines, normalized):
                line["text"] = text
            value = "\n".join(normalized).strip()
            readable, _reason = dm_note_text_is_readable(value, lines)
            if readable:
                notes.append({"x0": bx0, "y0": by0, "x1": bx1, "y1": by1, "image": crop, "value": value,
                              "lines": lines, "detected_index": len(notes) + 1, "yellow_fraction": 1.0,
                              "source": "PDF text layer",
                              "text_colour": dm_text_colour_in_box(page_words, (x0, y0, x1, y1), zoom)})
            continue
        hits = sum(1 for pattern in dm_MAP_PARAMETER_KEYWORDS if re.search(pattern, " ".join(texts).upper()))
        if len(texts) >= dm_V10_PIPELINE_MIN_LINES and hits >= dm_MAP_PARAMETER_BLOCK_MIN_HITS:
            pipeline.append({"x0": bx0, "y0": by0, "x1": bx1, "y1": by1, "image": crop,
                             "original_map_image": crop, "clean_image": crop, "lines": lines,
                             "value": "\n".join(texts), "source": "PDF text layer"})
    notes.sort(key=lambda n: (n["y0"], n["x0"]))
    pipeline.sort(key=lambda b: (b["y0"], b["x0"]))
    return notes, pipeline, yellow


def extract_all_map_pages_v23(document):
    """Every page with yellow callouts: note boxes + pipeline data blocks."""
    map_pages = []
    print()
    print("Scanning entire Dig Packet with embedded DIGMAP v23 engine...")
    for page_index in range(len(document)):
        page = document[page_index]
        page_number = page_index + 1
        screened = pdf_prefetched("screen", document, page_index)
        if screened is None:
            screened = dm_screen_for_map_page(page)
        if not screened:
            print(f"Page {page_number}: ignored for map extraction (no characteristic yellow note box).")
            continue

        print()
        print(f"Page {page_number}: MAP PAGE - DIGMAP v23")
        page_started = time.perf_counter()
        _lap = lap_timer(3)
        page_image = dm_render_page(page, dm_MAP_PAGE_RENDER_ZOOM)
        _lap("Render page")
        page_words = dm_horizontal_page_words(page)     # the PDF's own straight text (empty when scanned)
        # a page with a text layer: find the notes and the pipeline block from the text
        # alone - the picture steps (yellow / black pages, mark scan) and the block
        # discovery OCR are skipped. No note found this way -> the picture path below.
        text_notes, text_blocks, text_yellow = ([], [], None)
        if len(page_words) >= 20:
            text_notes, text_blocks, text_yellow = dm_map_page_from_text_layer(
                page_image, page_words, dm_MAP_PAGE_RENDER_ZOOM)
        if text_notes:
            print(f"MAP PAGE {page_number}: read from the PDF text layer only - {len(text_notes)} yellow note(s), "
                  f"{len(text_blocks)} pipeline block(s); picture box-finding and block OCR skipped")
            for index, box in enumerate(text_notes, start=1):
                colour = box.get("text_colour")
                print(f"  Note text block {index}:", (box["x0"], box["y0"], box["x1"], box["y1"]),
                      "(PDF text layer" + (f", {colour} text" if colour and colour != "black" else "") + ")")
                print(box["value"])
            for index, block in enumerate(text_blocks, start=1):
                print(f"  Pipeline block {index}: {len(block['lines'])} row(s) (PDF text layer)")
            yellow_isolation_page, note_boxes, reconstructed_yellow = None, text_notes, text_yellow
            _lap(f"Yellow note boxes + pipeline blocks from the text layer ({len(note_boxes)} + {len(text_blocks)})")
        else:
            yellow_isolation_page, note_boxes, reconstructed_yellow = dm_build_full_page_yellow_isolation(
                page_image, page_words, dm_MAP_PAGE_RENDER_ZOOM)
            _lap(f"Yellow note boxes ({len(note_boxes)})")
        if not note_boxes:
            print(
                f"Page {page_number}: yellow colour found but no readable callout "
                "text -> not an alignment sheet (screenshot / imagery). Page skipped."
            )
            record_timing(f"Page {page_number} (checked, not a map)", time.perf_counter() - page_started, 2)
            continue
        if text_notes:
            pipeline_detection_page, blocks = None, text_blocks
        else:
            pipeline_detection_page = dm_build_full_page_pipeline_isolation(
                page_image, note_boxes, reconstructed_yellow=reconstructed_yellow,
            )
            _lap("Pipeline page build")
            blocks = dm_find_pipeline_blocks(
                page_image, note_boxes,
                reconstructed_yellow=reconstructed_yellow,
                detection_page=pipeline_detection_page,
                page_words=page_words, zoom=dm_MAP_PAGE_RENDER_ZOOM,
            )
            _lap(f"Pipeline blocks ({len(blocks)}) incl. head/tail recovery")

        notes = []
        for note_index, note in enumerate(note_boxes, start=1):
            converted = dict(note)
            converted["index"] = note_index
            notes.append(converted)
        red_notes = dm_red_text_notes(page, page_image, reconstructed_yellow, dm_MAP_PAGE_RENDER_ZOOM)
        _lap(f"Red map notes ({len(red_notes)})")
        other_text, other_left_out = dm_other_map_text(                        # S246: roads, title ...
            page, page_image, [priority_holder_box(n) for n in note_boxes] + [priority_holder_box(b) for b in blocks]
            + [r.get("page_box") for r in red_notes], dm_MAP_PAGE_RENDER_ZOOM)
        _lap(f"Other map text ({len(other_text)})")
        parameter_blocks = []
        for block_index, block in enumerate(blocks, start=1):
            converted = dict(block)
            converted["index"] = block_index
            converted.setdefault("ocr_ready_image", converted.get("clean_image", converted.get("image")))
            parameter_blocks.append(converted)

        map_pages.append({
            "page_number": page_number,
            "image": page_image,
            "notes": notes,
            "parameter_blocks": parameter_blocks,
            "red_notes": red_notes,
            "other_text": other_text,                 # S246
            "other_text_left_out": dict(other_left_out),   # S247: for the terminal
            "yellow_isolation_page": yellow_isolation_page,
            "pipeline_detection_page": pipeline_detection_page,
            "map_engine": "DIGMAP v23",
        })
        record_timing(f"Map page {page_number}", time.perf_counter() - page_started, 2)

    print()
    print("Map/alignment pages extracted by DIGMAP v23:", len(map_pages))
    return map_pages


# ============================================================
# EXTRACT DIG PACKET
# ============================================================

PAGE1_LABEL_WORDS = ("Latitude", "Longitude", "Notes", "Pipeline", "Wheel", "station")


def report_page1_text_layer(page):
    """S17 check (log only): does page 1 carry real PDF text? If its printed labels are
    in the text layer, they could be found exactly and instantly instead of by the
    EasyOCR search over the whole page. Nothing is changed by this - it only reports."""
    try:
        words = page.get_text("words")
    except Exception as exc:
        print(f"PAGE 1 TEXT LAYER: not readable ({exc})")
        return
    found = [label for label in PAGE1_LABEL_WORDS
             if any(label.lower() in str(w[4]).lower() for w in words)]
    if found:
        print(f"PAGE 1 TEXT LAYER: {len(words)} word(s); printed labels found in it: {', '.join(found)} "
              f"-> the labels could be taken from the text layer instead of EasyOCR")
    else:
        print(f"PAGE 1 TEXT LAYER: {len(words)} word(s), none of them a printed label "
              f"({', '.join(PAGE1_LABEL_WORDS)}) -> page 1 is a picture; the EasyOCR label search is needed")


# ------------------------------------------------------------
# S40: PDF-only work done in a second process while the OCR models load
# ------------------------------------------------------------
# Page 1's picture, the map-page screening of every page and the table picture +
# grid of every page need no OCR. A second Python process (its own copy of the PDF -
# PyMuPDF must not be shared between threads) does them while this process loads
# the models; the steps later take the finished results instead of doing the work
# again. Same functions, same PDF, same settings -> the same results. Anything
# missing or failed is simply done the normal way.
PDF_PREFETCHES = {}      # S84: one entry per PDF (its full path) - every queued Dig Packet keeps its own
PDF_HELPERS = 2          # S487: the PDF helper processes shared by every queued PDF - this many work at once
PDF_HELPER_POOL = {"pool": None, "lock": threading.Lock()}   # S487: made at the first PDF, closed with the program
PDF_HELPER_RUN_LIMIT_S = 120   # how long one PDF's helper work may run once it has started


def pdf_helper_pool():
    """S487: the shared pool of PDF_HELPERS processes. The PDFs are handed to it in the order they are queued and
    it works on PDF_HELPERS of them at a time (S84 started a new process for every queued PDF, all at once). A pool
    that broke (a helper ended abruptly) is replaced for the PDFs queued after it."""
    with PDF_HELPER_POOL["lock"]:
        pool = PDF_HELPER_POOL["pool"]
        if pool is None or getattr(pool, "_broken", False):
            import atexit
            import multiprocessing
            from concurrent.futures import ProcessPoolExecutor
            spawn_from_compiled_copy()                           # S360
            pool = ProcessPoolExecutor(max_workers=PDF_HELPERS, mp_context=multiprocessing.get_context("spawn"))
            if PDF_HELPER_POOL["pool"] is None:
                atexit.register(lambda: PDF_HELPER_POOL["pool"] is not None
                                and PDF_HELPER_POOL["pool"].shutdown(wait=False, cancel_futures=True))
            PDF_HELPER_POOL["pool"] = pool
        return pool


def pdf_helper_result(future):
    """S487: a PDF's helper result. Time waiting in line behind other PDFs does not count - only
    PDF_HELPER_RUN_LIMIT_S from when its own work started."""
    from concurrent.futures import TimeoutError as FutureTimeout
    running_since = None
    while True:
        try:
            return future.result(timeout=0.5)
        except FutureTimeout:
            if future.running():
                running_since = running_since or time.perf_counter()
                if time.perf_counter() - running_since > PDF_HELPER_RUN_LIMIT_S:
                    raise


def _pdf_prefetch_worker(pdf_path, page_zoom):
    """Runs in the second process. Returns plain picklable results."""
    import io as _io
    import contextlib
    started = time.perf_counter()
    out = {"page1": None, "screen": {}, "tables": {}, "error": None, "early": None}
    try:
        with contextlib.redirect_stdout(_io.StringIO()), contextlib.redirect_stderr(_io.StringIO()):
            # S353: the PDF text first (map pages, dig sheet) - what the packet's reading needs first; it is
            # only kept when it can be sent back to the window's process
            try:
                import pickle
                early = read_text_while_models_load(pdf_path)
                pickle.dumps(early)
                out["early"] = early
            except Exception as exc:
                out["early_error"] = f"{type(exc).__name__}: {exc}"
            document = fitz.open(pdf_path)
            try:
                if len(document):
                    out["page1"] = render_page(document[0], page_zoom)
                for index in range(len(document)):
                    out["screen"][index] = bool(dm_screen_for_map_page(document[index]))
                # table pictures + grids: ordinary pages first, possible map pages last
                order = sorted(range(1, len(document)), key=lambda i: out["screen"].get(i, False))
                for index in order:
                    image = dt_page_table_image(document, document[index])
                    grid = dt_find_grid(image)
                    out["tables"][index] = {"image": image if grid else None, "grid": grid}
            finally:
                document.close()
    except Exception as exc:
        out["error"] = f"{type(exc).__name__}: {exc}"
    out["seconds"] = time.perf_counter() - started
    return out


def start_pdf_prefetch(pdf_path, while_what="while the OCR models load"):
    """Starts the second process for this PDF (if it can be started) - for a Dig Packet
    that has to wait anyway: for the OCR models, or (S84) for another Dig Packet to be
    read first. Each PDF keeps its own result until its reading has used it."""
    if not pdf_path:
        return
    entry = {"future": None, "data": None, "waited": False, "while": while_what,
             "lock": threading.Lock()}                                   # S353: one waiter at a time
    PDF_PREFETCHES[os.path.abspath(pdf_path)] = entry
    try:
        entry["future"] = pdf_helper_pool().submit(_pdf_prefetch_worker, pdf_path, PAGE_RENDER_ZOOM)   # S487
        print(f"PDF work for {os.path.basename(pdf_path)} (page 1 picture, map-page screening, table grids) "
              f"handed to the PDF helpers ({PDF_HELPERS} at a time, in queue order - S487) {while_what}")
    except Exception as exc:
        print(f"PDF work in a second process could not start ({exc}) - done the normal way")
        entry["future"] = None


def forget_pdf_prefetch(pdf_path):
    """S84: a PDF's second-process result is let go once its reading is over (or it was removed)."""
    entry = PDF_PREFETCHES.pop(os.path.abspath(pdf_path), None) if pdf_path else None
    if entry and entry.get("future") is not None:
        entry["future"].cancel()                  # S487: not started yet -> taken out of the helpers' line


def pdf_prefetched(kind, document_or_path, index=None):
    """The second process's result for this PDF: kind 'page1' / 'screen' / 'tables' / 'early' (S353: its
    PDF text read - map pages, dig sheet). None = not available (then the caller does the work itself)."""
    path = document_or_path if isinstance(document_or_path, str) else getattr(document_or_path, "name", "")
    PDF_PREFETCH = PDF_PREFETCHES.get(os.path.abspath(path)) if path else None
    if PDF_PREFETCH is None or PDF_PREFETCH.get("future") is None:
        return None
    with PDF_PREFETCH["lock"]:                       # S353: the early-text thread and the reading may both ask
        return _pdf_prefetched(PDF_PREFETCH, kind, index)


def _pdf_prefetched(PDF_PREFETCH, kind, index):
    future = PDF_PREFETCH["future"]
    if future is None:
        return None
    if PDF_PREFETCH["data"] is None and not PDF_PREFETCH["waited"]:
        PDF_PREFETCH["waited"] = True
        wait_started = time.perf_counter()
        try:
            data = pdf_helper_result(future)                     # S487
        except Exception as exc:
            data = {"error": f"{type(exc).__name__}: {exc}"}
        waited = time.perf_counter() - wait_started
        if data.get("error"):
            print(f"PDF WORK FROM THE SECOND PROCESS: failed ({data['error']}) - done the normal way")
            PDF_PREFETCH["future"] = None
            return None
        PDF_PREFETCH["data"] = data
        grids = sum(1 for t in data.get("tables", {}).values() if t.get("grid"))
        text_read = ("PDF text read (S353)" if data.get("early") is not None
                     else f"PDF text not read ({data.get('early_error')}) (S353)")
        print(f"PDF WORK FROM THE SECOND PROCESS: {text_read}, page 1 picture, {len(data.get('screen', {}))} "
              f"page(s) screened for map notes, {len(data.get('tables', {}))} page(s) checked for a table grid "
              f"({grids} found) - took {data.get('seconds', 0):.1f} s {PDF_PREFETCH.get('while', '')}"
              + (f"; waited {waited:.1f} s for it here" if waited >= 0.05 else "; ready when needed"))
    data = PDF_PREFETCH["data"]
    if data is None:
        return None
    if kind in ("page1", "early"):
        return data.get(kind)
    return data.get(kind, {}).get(index)


# S402: the next Dig Packet's page-1 labels are looked for while the one before it is still being read - its page 1
# picture is made ahead already (second process), and EasyOCR is mostly free once the packet being read is past
# its table headers. Its calls go after the packet being read's (priority 0.5) and before the photos'.
LABELS_AHEAD = {}                     # full path -> {"done", "labels", "image", "output", "seconds", "error", "while"}
DIG_AHEAD = {"next": None}            # set by the window: (path being read) -> paths of the Dig Packets waiting
LABELS_AHEAD_PRIORITY = 0.5


def start_labels_ahead(current_path=None):
    """S402: starts looking for the next waiting Dig Packet's page-1 labels on a thread of its own (once per
    packet). current_path - the packet being read (default: this thread's document)."""
    if DIG_AHEAD["next"] is None or not ocr_process_used():     # models in this process: one reader at a time
        return
    if current_path is None:
        current_path = (getattr(PROGRESS, "document", None) or {}).get("path")
    try:
        waiting = DIG_AHEAD["next"](current_path)
    except Exception:
        return
    for path in waiting[:1]:                          # only the very next one - one at a time
        key = os.path.abspath(path)
        if key in LABELS_AHEAD:
            return
        entry = {"done": threading.Event(), "labels": None, "image": None, "output": "", "seconds": 0.0,
                 "error": None, "while": os.path.splitext(os.path.basename(current_path or ""))[0] or "a Dig Packet"}
        LABELS_AHEAD[key] = entry
        threading.Thread(target=_labels_ahead_job, args=(path, entry), name="labels-ahead", daemon=True).start()


def _labels_ahead_job(path, entry):
    """S402 (its own thread): the label search on the waiting packet's page 1 picture; what it prints is kept and
    printed when that packet is read."""
    OCR_CALL.priority = LABELS_AHEAD_PRIORITY
    output, started = [], time.perf_counter()
    try:
        with held_output(output):
            image = pdf_prefetched("page1", path)
            if image is None:
                raise RuntimeError("its page 1 picture was not made ahead")
            print(f"LABELS AHEAD: {os.path.basename(path)} - page 1's printed labels looked for while "
                  f"{entry['while']} is read (S402)")
            labels = page1_label_search(image, lap_timer(2))
        entry.update(labels=labels, image=image)
    except Exception as exc:
        entry["error"] = f"{type(exc).__name__}: {exc}"
    finally:
        entry["output"], entry["seconds"] = "".join(output), time.perf_counter() - started
        entry["done"].set()


def take_labels_ahead(pdf_path, page_image):
    """S402: the labels found ahead for this packet (waits if that search is still running) - or None, and the
    reading looks for them itself (none were looked for, it failed, or page 1 is a different picture)."""
    entry = LABELS_AHEAD.pop(os.path.abspath(pdf_path), None)
    if entry is None:
        return None
    started = time.perf_counter()
    if not entry["done"].wait(timeout=120):
        print(f"LABELS AHEAD: {os.path.basename(pdf_path)} - the search ahead did not finish - looked for now (S402)")
        return None
    sys.stdout.write(entry["output"])
    if entry["labels"] is None or entry["image"] is not page_image:
        print(f"LABELS AHEAD: {os.path.basename(pdf_path)} - not used ("
              + (entry["error"] or "page 1 is a different picture now") + ") - looked for now (S402)")
        return None
    print(f"LABELS AHEAD: {os.path.basename(pdf_path)} - its labels were found while {entry['while']} was read "
          f"({entry['seconds']:.1f} s then); waited {time.perf_counter() - started:.1f} s for them now (S402)")
    return entry["labels"]


def page1_label_search(page_image, _p1):
    """The six printed labels of page 1 found with EasyOCR (S138: a half-size copy first, then each label read
    again at full size around it). S402: a function of its own, so the next Dig Packet's labels can be found
    while the one before it is still being read (start_labels_ahead). Returns the six labels."""
    def find_all_labels(label_results):
        return (find_label(label_results, "Latitude"), find_label(label_results, "Longitude"),
                find_label(label_results, "Notes"), find_pipeline_name_label(label_results),
                find_label_phrase(label_results, ["wheelcount"], "Wheel count/station"),
                find_label_phrase(label_results, ["milepost", "stationofanomaly", "approximatemile"],
                                  "Approximate mile post/station"))

    # S138: a half-size copy first to know WHERE the labels are; then each one is read
    # again at full size on a small crop around it (exact positions, as the whole-page
    # read gives); a label not found on the copy is looked for at full size only in the
    # band where it belongs (between the labels found above and below it); only if it
    # is still missing is the whole page read
    names = ["Latitude", "Longitude", "Notes", "Pipeline name", "Wheel count/station", "Mile post/station"]
    labels = None
    if LABEL_SEARCH_SCALE < 1:
        with quiet_this_thread():                          # its 'found as' lines only if it is used
            small_labels = find_all_labels(get_easy_page_results(page_image, LABEL_SEARCH_SCALE))
        _p1(f"EasyOCR over page 1 at {LABEL_SEARCH_SCALE:.0%} size - {sum(1 for x in small_labels if x)} of 6 "
            f"labels found there")
        exact_results = []
        for label in small_labels:
            if label:
                exact_results += read_labels_around(page_image, label)
        # labels missing on the copy: their band only (vertical order on the form)
        order = ["Latitude", "Longitude", "Pipeline name", "Wheel count/station", "Mile post/station", "Notes"]
        by_name = dict(zip(names, small_labels))
        for name in order:
            if by_name[name]:
                continue
            above = [by_name[n] for n in order[:order.index(name)] if by_name[n]]
            below = [by_name[n] for n in order[order.index(name) + 1:] if by_name[n]]
            top = int(max(l["y1"] for l in above)) if above else 0
            bottom = int(min(l["y0"] for l in below)) if below else page_image.height
            if bottom - top > 10:
                print(f"LABELS: '{name}' not found on the {LABEL_SEARCH_SCALE:.0%} copy - looked for at full size "
                      f"between y={top} and y={bottom} only")
                exact_results += read_labels_in_box(page_image, (0, top, page_image.width, bottom))
        with quiet_this_thread():
            exact = find_all_labels(exact_results)
        if all(exact):
            labels = exact
            _p1(f"Labels re-read at full size around each one ({len(exact_results)} text boxes) - all 6 "
                f"positions exact")
        else:
            missing = [n for n, found in zip(names, exact) if not found]
            _p1(f"Labels at full size around each one - not found: {', '.join(missing)} - the whole page is read")
    if labels is None:
        label_results = get_easy_page_results(page_image)
        _p1("EasyOCR over the whole page (printed labels)")
        labels = find_all_labels(label_results)
    else:
        for name, label in zip(["Latitude", "Longitude", "Notes", "Pipeline name", "Wheel count/station",
                                "Approximate mile post/station"], labels):
            print(f'{name} found as "{label.get("text", "")}" (full-size read around it - S138)')
    return labels


def extract_dig_packet(pdf_path, early=None):
    """Reads one Dig Packet. S64: only the steps that use the PDF itself (PyMuPDF:
    opening, page 1 picture + text layer, map pages, tables, dig sheet) take a turn at
    the PDF (pdf_turn); the page-1 values and the Notes - most of the time - are read
    from page 1's picture without it. A document dropped in meanwhile is checked /
    read in between, and both keep going."""
    if early is None:                    # S353: the second process's PDF text read, if it read it (waits for it)
        early = pdf_prefetched("early", pdf_path)
    progress_step("Open the PDF")
    with pdf_turn("Dig Packet: open"):
        document = fitz.open(pdf_path)
        if len(document) == 0:
            document.close()
            return {"Latitude": None, "Longitude": None, "Notes": None, "Map Pages": []}

    # S102: the printed text first - map notes, table rows, dig sheet - so the
    # handwriting reads below know which values exist in this packet
    results = {}
    progress_step("Map pages")
    if early and early.get("Map Pages") is not None:
        results["Map Pages"] = early["Map Pages"]
        print(f"MAP PAGES: already read from the PDF text while the OCR models loaded "
              f"({len(results['Map Pages'])} map page(s)) - S107")
        for map_page in results["Map Pages"]:                  # S247: its other text, said here too
            others = map_page.get("other_text") or []
            left_out = map_page.get("other_text_left_out") or {}
            print(f"MAP PAGE {map_page['page_number']}: other map text - {len(others)} found"
                  + "".join(f"; {' / '.join(o['value'].splitlines())}" for o in others)
                  + (" | left out: " + ", ".join(f"{n} {why}" for why, n in left_out.items()) if left_out else "")
                  + " (S246)")
    else:
        with timed("Map pages (all pages scanned)", 1), pdf_turn("Dig Packet: map pages"):
            results["Map Pages"] = extract_all_map_pages_v23(document)
    progress_step("Dig sheet")
    if early and early.get("Dig Sheets") is not None:
        results["Dig Sheets"] = early["Dig Sheets"]
        results["Text Pages"] = early.get("Text Pages") or []
        print("DIG SHEET: already read from the PDF text while the OCR models loaded - S107")
    else:
        with timed("Dig sheet (text)", 1), pdf_turn("Dig Packet: dig sheet"):
            results["Dig Sheets"] = read_dig_sheets(document)
            results["Text Pages"] = read_text_page_values(document)          # S194
    # dataC (accuracy fix A6): a vendor dig sheet whose letters are drawn as outlines (no PDF text layer, no
    # picture) is read with OCR and goes through the same dig sheet / text page readers
    with pdf_turn("Dig Packet: dig sheet pages without a text layer"):
        outline_pages = outline_text_pages(document, {1} | {m.get("page_number") for m in results["Map Pages"] or []})
    if outline_pages:
        with timed(f"Dig sheet pages drawn without a text layer, read by OCR ({len(outline_pages)}) - dataC fix A6", 1):
            sheets, text_pages = list(results["Dig Sheets"] or []), list(results["Text Pages"] or [])
            for index in outline_pages:
                with pdf_turn("Dig Packet: dig sheet page picture"):
                    words = ocr_page_words(document[index])
                sheet = dig_sheet_from_words(words, index)
                if sheet is not None:
                    sheets.append(sheet)
                record = text_page_record(words, index + 1, OUTLINE_TEXT_KIND)
                if record:
                    text_pages.append(record)
            results["Dig Sheets"] = sorted(sheets, key=lambda s: s["page"])
            results["Text Pages"] = sorted(text_pages, key=lambda p: p["page"])
    remember_dig_sheets(pdf_path, results["Text Pages"])             # S478: for the family's other packets
    if not (early and early.get("Map Pages") is not None):    # S171 (read early: shown then already)
        publish_priority_stage(pdf_path, results, 1)
    print()
    print("Rendering Dig Packet Page 1...")
    progress_step("Page 1 picture + text layer")
    with timed("Page 1 render + find labels", 1):
        _p1 = lap_timer(2, measure=True)                                # S406
        page_image = pdf_prefetched("page1", pdf_path)
        if page_image is None:
            with pdf_turn("Dig Packet: page 1 picture"):
                page_image = render_page(document[0], PAGE_RENDER_ZOOM)
        _p1("Render page 1")
        set_page_background(page_image)
        _p1("Find the paper colour")
        with pdf_turn("Dig Packet: page 1 text layer"):
            report_page1_text_layer(document[0])
        progress_step("Find the printed labels (EasyOCR)")
        with easy_stretch("its page-1 label search"):                  # S401
            labels = take_labels_ahead(pdf_path, page_image)           # S402: found while the last packet was read
            if labels is None:
                labels = page1_label_search(page_image, _p1)
        (latitude_label, longitude_label, notes_label, pipeline_name_label, wheel_count_label,
         station_label) = labels
    # S116: the colour map (CPU only) is made on its own thread while the table pages
    # are read (OCR) - they share nothing; its terminal lines are printed after the tables
    colour_map_labels = [("Latitude", latitude_label), ("Longitude", longitude_label), ("Notes", notes_label),
                         ("Pipeline name", pipeline_name_label), ("Wheel count/station", wheel_count_label),
                         ("Mile post/station", station_label)]
    colour_map_timing = {}

    def colour_map_job():
        """S400: the colour map, timed - its own time from start to end and its processor work in that time."""
        colour_map_timing["started"], cpu = time.perf_counter(), time.thread_time()
        try:
            build_page_colour_map(page_image, colour_map_labels)
        finally:
            colour_map_timing["seconds"] = time.perf_counter() - colour_map_timing["started"]
            colour_map_timing["cpu"] = time.thread_time() - cpu
    colour_map_done = run_alongside(colour_map_job)
    progress_step("Table pages")
    with timed("Table highlights (the page-1 colour map was made alongside)", 1):    # S355: its own PDF turn
        skip = {1} | {m.get("page_number") for m in results["Map Pages"] or []}
        results["Table Highlights"] = extract_table_highlights(document, skip,
                                                               map_note_wheel_digits(results["Map Pages"]))
    tables_done = time.perf_counter()
    start_labels_ahead(pdf_path)                       # S402 (already started at the table headers, if any)
    start_notes_detector_load()            # S159: after the tables (it used to slow them down)
    # S125: the checks between the map notes and the table rows need only these two, so
    # they run now - the table rows are then final and the window can build their tabs
    # while page 1 and the Notes are still being read
    fix_table_coordinate_signs(results)                       # S423: before the map notes are compared with the rows
    link_coloured_map_notes_to_table(results)
    map_note_coordinates_vs_table(results)
    EARLY_TABLES[pdf_path] = {"results": results, "path": pdf_path}
    publish_priority_stage(pdf_path, results, 2)               # S171: + the table rows
    colour_map_done()
    # S400: its real time (it used to show a fixed 1.0 s) - and how much of it was its own processor work; the
    # rest it waited for its turn at Python while the other reading threads ran
    seconds, cpu = colour_map_timing.get("seconds", 0.0), colour_map_timing.get("cpu", 0.0)
    record_timing(f"Page 1 colour map + stray marks - made alongside the table reads ({cpu:.1f} s of processor work, "
                  f"{max(0.0, seconds - cpu):.1f} s waiting its turn); waited {time.perf_counter() - tables_done:.1f} s "
                  f"for it after the tables (S400)", seconds, 1)
    build_text_first(results)
    build_expected_rows(results)                                   # S151

    PAGE1_BULLET_HINT["count"] = None                # S115: nothing read yet on this packet

    # S151: Wheel Count first - its exact printed numbers tie the bullets to the packet's
    # anomalies, so every line after it knows what it should say
    progress_step("Wheel count/station")
    with timed("Wheel count/station", 1, measure=True):          # S405
        results["Wheel Count"] = extract_coordinate(page_image, wheel_count_label, "Wheel Count",
                                                    width_fraction=0.50)
    PAGE1_BULLET_HINT["count"] = page1_bullet_count(results)
    progress_step("Latitude")
    with timed("Latitude", 1, measure=True):          # S405
        results["Latitude"] = extract_coordinate(page_image, latitude_label, "Latitude")
    PAGE1_BULLET_HINT["count"] = page1_bullet_count(results)
    progress_step("Longitude")
    with timed("Longitude", 1, measure=True):          # S405
        results["Longitude"] = extract_coordinate(page_image, longitude_label, "Longitude")
    progress_step("Pipeline name")
    with timed("Pipeline name", 1, measure=True):          # S405
        results["Pipeline Name"] = extract_pipeline_name(page_image, pipeline_name_label)
    PAGE1_BULLET_HINT["count"] = page1_bullet_count(results)
    progress_step("Mile post/station")
    with timed("Approximate mile post/station", 1, measure=True):          # S405
        results["Mile Post/Station"] = extract_coordinate(page_image, station_label, "Mile Post/Station")
    PAGE1_BULLET_HINT["count"] = None                # the bullet count's own re-cuts measure their windows
    apply_page1_bullet_count(results)
    for field in EXPECTED_FIELDS:                       # S151: lines the bullet count changed
        apply_expected_values(field, results.get(field))
    with timed("Guided re-reads of page-1 values (S100)", 1):
        guided_page1_reread(results)
    remember_page1_letters(results)
    progress_step("Find the Notes lines")
    with timed("Notes", 1, measure=True):          # S405
        NOTES_PRINTED_CONTEXT.update(results=results, path=pdf_path)   # S484: what is printed, for each line
        try:
            results["Notes"] = extract_notes(page_image, notes_label, page1_bullet_count(results))
        finally:
            NOTES_PRINTED_CONTEXT.clear()
    publish_priority_stage(pdf_path, results, 3)               # S171: + the page-1 handwriting
    with timed("Pipeline name check (dig sheet, map red notes) + map notes vs table + page 1", 1,
               measure=True):                                                                       # S406
        with pdf_turn("Dig Packet: pipeline name on the dig sheet"):
            confirm_pipeline_name_on_dig_sheet(document, results.get("Pipeline Name"), results.get("Dig Sheets"))
        confirm_pipeline_name_on_map_red_notes(results.get("Pipeline Name"), results.get("Map Pages"))
        if guided_pipeline_name_reread(results.get("Pipeline Name"), page_image):        # S101
            with pdf_turn("Dig Packet: pipeline name on the dig sheet"):
                confirm_pipeline_name_on_dig_sheet(document, results.get("Pipeline Name"),
                                                   results.get("Dig Sheets"))
            confirm_pipeline_name_on_map_red_notes(results.get("Pipeline Name"), results.get("Map Pages"))
        page1_values_vs_map_notes(results)
        for field in EXPECTED_FIELDS:                               # S151: what still does not fit
            apply_expected_values(field, results.get(field), final=True)
        notes_bullets_tidied(results)                                # S483: '(A)' written the same way on every line
        notes_vs_table_rows(results, pdf_path)
        fit_snips_to_values(results)                # S97: every snip holds its (final) value
    with pdf_turn("Dig Packet: close"):
        document.close()
    return results


# ============================================================
# DIG PACKET DEBUG SUMMARY IMAGE
# ============================================================

def get_font(size, bold=False):
    candidates = (
        ["arialbd.ttf", "segoeuib.ttf", "DejaVuSans-Bold.ttf"]
        if bold else
        ["arial.ttf", "segoeui.ttf", "DejaVuSans.ttf"]
    )
    for name in candidates:
        try:
            return ImageFont.truetype(name, size)
        except Exception:
            continue
    return ImageFont.load_default()


def wrap_text(draw, text, font, maximum_width):
    output = []
    for paragraph in str(text).split("\n"):
        words = paragraph.split(" ")
        current = ""
        for word in words:
            proposal = (current + " " + word).strip()
            if draw.textlength(proposal, font=font) <= maximum_width or not current:
                current = proposal
            else:
                output.append(current)
                current = word
        output.append(current)
    return output


class DebugCanvas:
    """Collects text lines and images top-to-bottom, then renders one PNG."""

    def __init__(self, width=1500, margin=30):
        self.width = width
        self.margin = margin
        self.items = []
        self.measure = ImageDraw.Draw(Image.new("RGB", (10, 10), "white"))

    def text(self, value, size=18, bold=False, color=(0, 0, 0), gap=4):
        font = get_font(size, bold)
        for line in wrap_text(self.measure, value, font, self.width - self.margin * 2):
            self.items.append(("text", line, font, color, size + gap))

    def image(self, image, maximum_width=None, gap=10):
        if image is None:
            return
        maximum_width = min(maximum_width or self.width, self.width - self.margin * 2)
        fitted = fit_image_width(image.convert("RGB"), maximum_width)
        self.items.append(("image", fitted, None, None, fitted.height + gap))

    def space(self, pixels=12):
        self.items.append(("space", None, None, None, pixels))

    def rule(self):
        self.items.append(("rule", None, None, None, 16))

    def render(self):
        height = self.margin * 2 + sum(item[4] for item in self.items)
        output = Image.new("RGB", (self.width, max(height, 50)), "white")
        draw = ImageDraw.Draw(output)
        y = self.margin
        for kind, value, font, color, advance in self.items:
            if kind == "text":
                draw.text((self.margin, y), value, font=font, fill=color)
            elif kind == "image":
                output.paste(value, (self.margin, y))
                draw.rectangle(
                    (self.margin - 1, y - 1, self.margin + value.width, y + value.height),
                    outline=(170, 170, 170),
                )
            elif kind == "rule":
                draw.line(
                    (self.margin, y + 7, self.width - self.margin, y + 7),
                    fill=(150, 150, 150), width=2,
                )
            y += advance
        return output


def create_debug_summary_image(results):
    canvas = DebugCanvas()
    canvas.text("DIG PACKET OCR DEBUG SUMMARY", size=30, bold=True, gap=10)
    canvas.text("Pipeline version: " + CHARACTER_LOCK_PIPELINE_VERSION, size=16, color=(80, 80, 80))
    canvas.rule()

    # ---------------- Latitude / Longitude ----------------
    for field in ["Latitude", "Longitude"]:
        result = results.get(field)
        canvas.text(field.upper(), size=24, bold=True, gap=8)
        if result is None:
            canvas.text("Label not found.", color=(180, 0, 0))
            canvas.rule()
            continue
        canvas.image(result.get("image"), maximum_width=900)
        canvas.text(
            f'OCR attempts: {result.get("attempt_count", 0)} | '
            f'physical groups: {result.get("physical_group_count", 1)} | '
            f'coordinates accepted: {len(result.get("items", []))}',
            size=16,
        )
        for item in result.get("items", []):
            marker = f'({item["marker"]}) ' if item.get("marker") else f'#{item.get("index", 1)} '
            canvas.text(
                f'{marker}{item["value"]}   whole-row votes={item.get("whole_row_votes", 0)}  '
                f'physical votes={item.get("physical_votes", 0)}  '
                f'avg conf={item.get("average_confidence", 0.0):.3f}',
                size=18, bold=True, color=(0, 90, 0),
            )
        if not result.get("items"):
            canvas.text("No valid coordinate found.", color=(180, 0, 0))
        canvas.rule()

    # ---------------- Notes ----------------
    notes = results.get("Notes")
    map_pages = results.get("Map Pages") or []
    show_notes_detail = notes is not None and (
        DEBUG_SHOW_NORMAL_NOTES_WHEN_MAP_PAGES_EXIST or not map_pages
    )

    canvas.text("NOTES", size=24, bold=True, gap=8)
    if notes is None:
        canvas.text("Notes label not found.", color=(180, 0, 0))
    else:
        canvas.text("Final Notes:", size=18, bold=True)
        canvas.text(notes.get("value") or "(empty)", size=18, color=(0, 90, 0))
        if not show_notes_detail:
            canvas.text(
                "(Per-line Notes detail hidden because map pages exist. Set "
                "DEBUG_SHOW_NORMAL_NOTES_WHEN_MAP_PAGES_EXIST = True to show it.)",
                size=14, color=(100, 100, 100),
            )
    if show_notes_detail:
        for line_number, line in enumerate(notes.get("lines", []), start=1):
            canvas.space(8)
            canvas.text(f"Notes line {line_number}", size=20, bold=True)
            canvas.image(line.get("image"), maximum_width=1100)
            canvas.text("Detector: " + str(line.get("detector_text", "")), size=15)
            for attempt in line.get("whole_attempts", [])[:8]:
                canvas.text(
                    f'  {attempt.get("source", "")}: {attempt.get("text", "")} '
                    f'({safe_float(attempt.get("confidence", 0.0)):.3f})',
                    size=14, color=(70, 70, 70),
                )
            for profile in line.get("character_profiles", []):
                if not profile.get("reference"):
                    continue
                pattern = "".join(
                    (item.get("character") or "?") if item.get("locked") else "?"
                    for item in profile.get("characters", [])
                )
                canvas.text(
                    f'  Token {profile.get("token", "")}: N={profile.get("length", 0)} '
                    f'locks={pattern or "-"}',
                    size=14, color=(0, 0, 140),
                )
            for decision in line.get("decisions", []):
                canvas.text(
                    f'  Decision: {decision.get("text", "")}   [{decision.get("source", "")}]',
                    size=14,
                )
                for correction in decision.get("english_word_corrections", []) or []:
                    if not correction.get("changed"):
                        continue
                    canvas.text(
                        f'     English: {correction.get("before", "")} -> {correction.get("after", "")}',
                        size=14, color=(150, 80, 0),
                    )
            for sanity in line.get("sentence_sanity", []):
                for change in sanity.get("changes", []):
                    canvas.text(
                        f'  Sentence pass {sanity.get("pass")}: '
                        f'{change.get("before")} -> {change.get("after")}',
                        size=14, color=(150, 80, 0),
                    )
            canvas.text("Final: " + str(line.get("text", "")), size=17, bold=True, color=(0, 90, 0))
    canvas.rule()

    # ---------------- Map pages ----------------
    canvas.text("MAP / ALIGNMENT PAGES", size=24, bold=True, gap=8)
    if not map_pages:
        canvas.text("No map pages detected.")
    for map_page in map_pages:
        canvas.space(8)
        canvas.text(f'Page {map_page["page_number"]} ({map_page.get("map_engine", "")})', size=21, bold=True)
        canvas.image(map_page.get("image"), maximum_width=1100)
        for note in map_page.get("notes", []):
            canvas.text(f'Yellow note box {note["index"]}:', size=17, bold=True)
            canvas.image(note.get("image"), maximum_width=900)
            canvas.text(note.get("value") or "(no text)", size=16, color=(0, 90, 0))
        for block in map_page.get("parameter_blocks", []):
            canvas.text(f'Pipeline data block {block["index"]}:', size=17, bold=True)
            canvas.image(block.get("image"), maximum_width=900)
            for line in block.get("lines", []):
                canvas.text(
                    f'  {line.get("text", "")}   '
                    f'[winner: {line.get("winner", "")} | '
                    f'Easy: {line.get("easy_text", "")} ({safe_float(line.get("easy_conf", 0.0)):.2f}) | '
                    f'Paddle: {line.get("paddle_text", "")} ({safe_float(line.get("paddle_conf", 0.0)):.2f})]',
                    size=14,
                )
                if DEBUG_MAP_SHOW_INDIVIDUAL_CLEAN_LINE_IMAGES:
                    canvas.image(line.get("clean_image"), maximum_width=700)
    return canvas.render()


def split_debug_image_into_two(image):
    """Very tall images are split in two so image viewers can open them."""
    if image.height <= 30000:
        return [image]
    middle = image.height // 2
    return [
        image.crop((0, 0, image.width, middle)),
        image.crop((0, middle, image.width, image.height)),
    ]


def save_debug_images(results):
    if not SAVE_DEBUG_IMAGES:
        print("Debug images not saved (SAVE_DEBUG_IMAGES = False).")
        return []
    try:
        summary = create_debug_summary_image(results)
    except Exception as exc:
        print("Could not create debug summary image:", exc)
        return []
    parts = split_debug_image_into_two(summary)
    paths = [DEBUG_IMAGE_PATH] if len(parts) == 1 else [DEBUG_IMAGE_PATH_1, DEBUG_IMAGE_PATH_2]
    saved = []
    for part, path in zip(parts, paths):
        try:
            part.save(path)
            saved.append(path)
            print("Saved debug image:", path)
        except Exception as exc:
            print("Could not save debug image", path, ":", exc)
    return saved


