# WINDOWS CLIPBOARD (copy a debug image)
# ============================================================

def copy_image_to_clipboard(image_path):
    """Copy an image to the Windows clipboard as a DIB."""
    try:
        image = Image.open(image_path).convert("RGB")
        output = io.BytesIO()
        image.save(output, "BMP")
        data = output.getvalue()[14:]      # strip BMP file header -> DIB
        output.close()

        CF_DIB = 8
        GMEM_MOVEABLE = 0x0002
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        kernel32.GlobalAlloc.restype = wintypes.HGLOBAL
        kernel32.GlobalAlloc.argtypes = [wintypes.UINT, ctypes.c_size_t]
        kernel32.GlobalLock.restype = wintypes.LPVOID
        kernel32.GlobalLock.argtypes = [wintypes.HGLOBAL]
        kernel32.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
        user32.SetClipboardData.argtypes = [wintypes.UINT, wintypes.HANDLE]
        user32.SetClipboardData.restype = wintypes.HANDLE

        if not user32.OpenClipboard(None):
            return False
        try:
            user32.EmptyClipboard()
            handle = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(data))
            if not handle:
                return False
            pointer = kernel32.GlobalLock(handle)
            ctypes.memmove(pointer, data, len(data))
            kernel32.GlobalUnlock(handle)
            if not user32.SetClipboardData(CF_DIB, handle):
                return False
        finally:
            user32.CloseClipboard()
        return True
    except Exception as exc:
        print("Clipboard copy failed:", exc)
        return False


# ============================================================
# PIL IMAGE -> PNG BYTES (for the verification window)
# ============================================================

class WindowPicture:
    """A picture on its way to the window (S16): the fitted PIL image itself. Tk gets
    its pixels directly (PIL.ImageTk) - no PNG made and decoded again. Same pixels as
    before (PNG was lossless)."""
    __slots__ = ("image",)

    def __init__(self, image):
        self.image = image


def window_fit(image, maximum_width):
    """S87: the picture in RGB, fitted to maximum_width - made once per picture and width
    and kept on the picture itself, so building the tabs again (or the reading thread
    having made it already, prepare_window_pictures) does not repeat the work."""
    key = maximum_width if image.width > maximum_width else "full"
    fits = image.__dict__.get("_window_fits")
    if fits is not None and key in fits:
        return fits[key]
    fitted = fit_image_width(image.convert("RGB"), maximum_width)
    try:
        if fits is None:
            fits = image.__dict__.setdefault("_window_fits", {})
        fits[key] = fitted
    except Exception:
        pass
    return fitted


def window_picture(image, maximum_width=DISPLAY_MAX_WIDTH):
    """The picture fitted to the width the window shows it at, ready for make_tk_photo."""
    if image is None:
        return None
    return WindowPicture(window_fit(image, maximum_width))


def prepare_window_pictures(dig_results):
    """S87: run in the reading thread right after a Dig Packet is read - its card and
    cell pictures are converted and fitted for the window here, so building its tabs
    (on the window's thread, which freezes the window) only has to turn them into
    window pictures. Returns how many were prepared."""
    jobs = []
    for field in ("Latitude", "Longitude", "Wheel Count", "Mile Post/Station"):
        result = dig_results.get(field) or {}
        jobs.append((result.get("image"), DIG_CARD_IMAGE_WIDTH))
        jobs += [(item.get("image"), DIG_CARD_IMAGE_WIDTH) for item in result.get("items") or []]
    jobs.append(((dig_results.get("Pipeline Name") or {}).get("image"), DISPLAY_MAX_WIDTH))
    jobs.append(((dig_results.get("Notes") or {}).get("image"), DISPLAY_MAX_WIDTH))
    for map_page in dig_results.get("Map Pages") or []:
        jobs += [(n.get("image"), DIG_CARD_IMAGE_WIDTH) for n in map_page.get("notes") or []]
        jobs += [(n.get("image"), DIG_CARD_IMAGE_WIDTH) for n in map_page.get("red_notes") or []]
        jobs += [(n.get("image"), DIG_CARD_IMAGE_WIDTH) for n in map_page.get("other_text") or []]   # S247
        jobs += [(b.get("original_map_image", b.get("image")), DIG_CARD_IMAGE_WIDTH)
                 for b in map_page.get("parameter_blocks") or []]
    for table_page in dig_results.get("Table Highlights") or []:
        for item in table_page.get("items") or []:
            for cell in item.get("cells") or []:
                jobs.append((cell.get("image"), 10_000))
                jobs.append((cell.get("header_image"), 10_000))
    count = 0
    for image, width in jobs:
        if image is not None and hasattr(image, "convert"):
            try:
                window_fit(image, width)
                count += 1
            except Exception:
                pass
    return count


def make_tk_photo(data):
    """A Tk photo for the window from a WindowPicture (pixels handed over directly) or
    from PNG bytes (the 6000-form and quote screenshots). The exact picture shown is also
    kept as a PIL image, so 'Copy whole tab as one picture' can paste it."""
    if isinstance(data, WindowPicture):
        from PIL import ImageTk
        photo = ImageTk.PhotoImage(data.image)
        STEP_TAB_PICTURES[str(photo)] = data.image
        return photo
    photo = tk.PhotoImage(data=data)
    remember_tab_picture(photo, data)
    return photo


# ============================================================
# DIG PACKET CONSOLE OUTPUT
# ============================================================

def coordinate_display_items(field, result):
    """[(key, value)] for every coordinate found for Latitude/Longitude."""
    if result is None:
        return [(field, None)]
    items = result.get("items", [])
    if not items:
        return [(field, None)]
    if len(items) == 1:
        return [(field, items[0]["value"])]
    output = []
    for item in items:
        marker = item.get("marker") or str(item.get("index", len(output) + 1))
        output.append((f"{field} ({marker})", item["value"]))
    return output


# ============================================================
# GOOGLE MAPS LINK FROM LATITUDE / LONGITUDE
# ============================================================
# Same link layout as the Boardwalk example; only the coordinate spots change:
#   /place/<lat>,<lon>/@<lat>,<lon>,952m/...!3d<lat>!4d<lon>...
# The /place/ part holds the EXACT decimal coordinates: Google places the pin
# from that part, and a degrees-minutes-seconds name (rounded to 0.1") would
# move the pin to the rounded spot.

GOOGLE_MAPS_LINK_TEMPLATE = (
    "https://www.google.com/maps/place/{lat},{lon}/@{lat},{lon},952m/"
    "data=!3m2!1e3!4b1!4m4!3m3!8m2!3d{lat}!4d{lon}!5m1!1e1"
    "?entry=ttu&g_ep=EgoyMDI2MDkyMy4wIKXMDSoASAFQAw%3D%3D"
)


def clean_coordinate_text(value):
    text = re.sub(r"[^0-9.\-]", "", str(value or ""))
    try:
        float(text)
    except ValueError:
        return None
    return text


def google_maps_link(latitude, longitude):
    """Latitude first, then longitude (as on the Dig Packet). None if unreadable."""
    lat = clean_coordinate_text(latitude)
    lon = clean_coordinate_text(longitude)
    if lat is None or lon is None:
        return None
    if not (-90 <= float(lat) <= 90 and -180 <= float(lon) <= 180):
        return None
    return GOOGLE_MAPS_LINK_TEMPLATE.format(lat=lat, lon=lon)


def pair_latitudes_with_longitudes(named_values):
    """
    named_values: [(name, value)] containing 'Latitude...' and 'Longitude...' names.
    Pairs 'Latitude (A)' with 'Longitude (A)'; otherwise pairs them in order.
    Returns [(label, latitude, longitude)].
    """
    lats = [(n, v) for n, v in named_values if "Latitude" in n]
    lons = [(n, v) for n, v in named_values if "Longitude" in n]
    suffix = lambda name: name.split("Latitude")[-1].split("Longitude")[-1].strip()
    lon_by_suffix = {suffix(n): v for n, v in lons}
    pairs = []
    if lats and all(suffix(n) in lon_by_suffix for n, _ in lats):
        for n, v in lats:
            pairs.append((suffix(n), v, lon_by_suffix[suffix(n)]))
    else:
        for index, ((_, lat), (_, lon)) in enumerate(zip(lats, lons)):
            pairs.append((f"#{index + 1}" if len(lats) > 1 else "", lat, lon))
    return pairs


# Distance helper (used by the map-note coordinate check)
def miles_between(lat1, lon1, lat2, lon2):
    """Great-circle distance in miles."""
    lat1, lon1, lat2, lon2 = (math.radians(float(v)) for v in (lat1, lon1, lat2, lon2))
    a = (math.sin((lat2 - lat1) / 2) ** 2
         + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2)
    return 3958.8 * 2 * math.asin(math.sqrt(a))



MAP_NOTE_MATCH_TOLERANCE = 2e-6


def map_note_coordinates(map_pages):
    """Yellow map notes that list a Latitude + Longitude (e.g. 'Wheel Count 100553.07')."""
    found = []
    for map_page in map_pages or []:
        for note in map_page.get("notes", []):
            text = note.get("value") or ""
            lat = re.search(r"Lat(?:itude)?\.?\s*(-?\d{1,2}\.\d+)", text, re.IGNORECASE)
            lon = re.search(r"Long(?:itude)?\.?\s*(-?\d{1,3}\.\d+)", text, re.IGNORECASE)
            if not (lat and lon):
                continue
            first_line = next((line.strip() for line in text.splitlines() if line.strip()), "")
            wheel = re.search(r"Wheel\s*Count\s*([0-9.]+)", text, re.IGNORECASE)
            found.append({
                "lat": float(lat.group(1)), "lon": float(lon.group(1)),
                "lat_text": lat.group(1), "lon_text": lon.group(1),
                "label": f"Wheel Count {wheel.group(1)}" if wheel else first_line,
                "page": map_page.get("page_number"),
            })
    return found


def map_note_check(latitude, longitude, map_pages):
    """'✓ matches map note: Wheel Count 100553.07 (page 2)' / warning / None."""
    notes = map_note_coordinates(map_pages)
    if not notes:
        return None
    lat = clean_coordinate_text(latitude)
    lon = clean_coordinate_text(longitude)
    if lat is None or lon is None:
        return None
    note = nearest_map_note(notes, float(lat), float(lon))         # S481: the closest, not the first nearby
    if note is not None:
        same_digits = (note["lat_text"] == lat and note["lon_text"] == lon)
        extra = "" if same_digits else f" - map says {note['lat_text']}, {note['lon_text']}"
        return f"✓ matches map note: {note['label']} (page {note['page']}){extra}"
    nearest = min(notes, key=lambda n: miles_between(lat, lon, n["lat"], n["lon"]))
    feet = miles_between(lat, lon, nearest["lat"], nearest["lon"]) * 5280
    return (f"⚠ no map note has these exact coordinates "
            f"(closest: {nearest['label']}, ~{feet:.0f} ft away)")


