# ############################################################
# ############################################################
#
#          PART 4 - OMEGAWRAP QUOTE REQUEST (mode Q)
#
# ############################################################
# ############################################################
# Reads ONLY the two-column table (label | value). Logos, footer
# notes and the address line are ignored.

QUOTE_SECTION_HEADERS = [
    ("PIPELINE OPERATOR DETAILS", "Operator"),
    ("CONTRACTOR DETAILS", "Contractor"),
    ("QUOTE DETAILS", "Quote"),
    ("COMPLETED BY", "Completed"),       # green sign-off rows
]
QUOTE_SCREENSHOT_ZOOM = 1.5


def group_words_into_lines(words, tolerance=5):
    """Group words whose vertical centres are within `tolerance` points."""
    lines = []
    for word in sorted(words, key=lambda w: (w["y0"] + w["y1"]) / 2):
        center = (word["y0"] + word["y1"]) / 2
        if lines and abs(center - lines[-1]["center"]) <= tolerance:
            line = lines[-1]
            line["words"].append(word)
            line["center"] = sum((w["y0"] + w["y1"]) / 2 for w in line["words"]) / len(line["words"])
        else:
            lines.append({"center": center, "words": [word]})
    return [sorted(line["words"], key=lambda w: w["x0"]) for line in lines]


def quote_section_starts(words):
    """[(y_top, short_name)] for each section header / sign-off bar, top to bottom."""
    starts = []
    for line_words in group_words_into_lines(words):
        text = " ".join(w["text"] for w in line_words).upper()
        for header, short in QUOTE_SECTION_HEADERS:
            if header in text:
                starts.append((min(w["y0"] for w in line_words), short))
    starts.sort()
    return starts


def quote_section_for(y_top, starts):
    name = "Quote Request"
    for start_y, short in starts:
        if y_top >= start_y - 8:
            name = short
    return name


def extract_quote_rows(words, fields, page_width):
    """
    Pure table logic (no PDF library), top-down coordinates.
      words : [{"text","x0","y0","x1","y1"}]
      fields: [{"name","value","x0","y0","x1","y1"}]  fillable-form boxes
    Returns [{"section","label","value","y0","y1"}] in table order.
    """
    starts = quote_section_starts(words)
    rows = []

    if fields:
        # Fillable form: each value box is a row; its label is the text
        # to the LEFT of the box on the same row (may wrap to 2 lines).
        for field in sorted(fields, key=lambda f: (f["y0"], f["x0"])):
            label_words = [
                w for w in words
                if w["x1"] <= field["x0"] + 2
                and field["y0"] - 2 <= (w["y0"] + w["y1"]) / 2 <= field["y1"] + 2
            ]
            label_words.sort(key=lambda w: (round(w["y0"]), w["x0"]))
            label = " ".join(w["text"] for w in label_words).strip().rstrip(":").strip()
            rows.append({
                "section": quote_section_for(field["y0"], starts),
                "label": label or field["name"],
                "value": "" if field["value"] is None else str(field["value"]).strip(),
                "y0": field["y0"], "y1": field["y1"],
                "vx0": field["x0"], "vx1": field["x1"],             # S172: where the value box is
            })
        return rows

    # Flattened PDF (no form fields): split each text line at the column
    # divider = the shared right edge of the right-aligned labels.
    left_edges = Counter(round(w["x1"]) for w in words if w["x1"] < page_width * 0.5)
    if not left_edges:
        return rows
    divider = left_edges.most_common(1)[0][0]
    header_names = [header for header, _ in QUOTE_SECTION_HEADERS[:3]]

    in_table = False
    for line_words in group_words_into_lines(words):
        left = " ".join(w["text"] for w in line_words if w["x1"] <= divider + 3).strip()
        right_words = [w for w in line_words if w["x0"] >= divider + 3]
        right = " ".join(w["text"] for w in right_words).strip()
        if any(header in left.upper() for header in header_names):
            in_table = True
            continue
        if not in_table or not left:
            continue
        y0 = min(w["y0"] for w in line_words)
        y1 = max(w["y1"] for w in line_words)
        if left.startswith("(") and rows:            # wrapped label, e.g. "(Dent, Gouge...)"
            rows[-1]["label"] += " " + left
            rows[-1]["y1"] = y1
            if right:
                rows[-1]["value"] = (rows[-1]["value"] + " " + right).strip()
                rows[-1]["vx0"] = min(([rows[-1]["vx0"]] if rows[-1].get("vx0") is not None else [])
                                      + [w["x0"] for w in right_words])
                rows[-1]["vx1"] = max(([rows[-1]["vx1"]] if rows[-1].get("vx1") is not None else [])
                                      + [w["x1"] for w in right_words])
            continue
        rows.append({
            "section": quote_section_for(y0, starts),
            "label": left.rstrip(":").strip(),
            "value": right,
            "y0": y0, "y1": y1,
            "vx0": min(w["x0"] for w in right_words) if right_words else None,      # S172: where the value is
            "vx1": max(w["x1"] for w in right_words) if right_words else None,
        })
        if left.upper().startswith("DATE"):          # last row of the table
            break
    return rows


def extract_quote_request(pdf_path):
    """Read the quote table with fitz and attach a screenshot of each row."""
    document = fitz.open(pdf_path)
    all_rows = []
    for page_index in range(len(document)):
        page = document[page_index]
        words = [
            {"text": w[4], "x0": w[0], "y0": w[1], "x1": w[2], "y1": w[3]}
            for w in page.get_text("words")
        ]
        fields = []
        for widget in page.widgets() or []:
            value = widget.field_value
            if widget.field_type == fitz.PDF_WIDGET_TYPE_CHECKBOX:
                value = "Yes" if value not in (None, "", "Off", False) else "No"
            rect = widget.rect
            fields.append({
                "name": widget.field_name, "value": value,
                "x0": rect.x0, "y0": rect.y0, "x1": rect.x1, "y1": rect.y1,
            })
        rows = extract_quote_rows(words, fields, page.rect.width)
        for row in rows:
            clip = fitz.Rect(30, row["y0"] - 4, page.rect.width - 30, row["y1"] + 4)
            pix = page.get_pixmap(
                matrix=fitz.Matrix(QUOTE_SCREENSHOT_ZOOM, QUOTE_SCREENSHOT_ZOOM),
                clip=clip,
            )
            row["image"] = pix.tobytes("png")
            row["value_box"] = ((row["vx0"], row["y0"], row["vx1"], row["y1"])                # S175
                                if row.get("vx0") is not None and row.get("vx1") is not None
                                else (30, row["y0"], page.rect.width - 30, row["y1"]))
            row["page"] = page_index + 1
        all_rows.extend(rows)
    document.close()
    return all_rows


def add_quote_section(scroll_frame, pdf_path, rows, image_references):
    """The quote table in its own tab of the documents window (same correction boxes)."""
    ttk.Label(scroll_frame, text="QUOTE REQUEST", font=("Segoe UI", 16, "bold")).pack(pady=(15, 2))
    ttk.Label(scroll_frame, text=os.path.basename(pdf_path)).pack(pady=(0, 10))

    if not rows:
        ttk.Label(
            scroll_frame, text="No table rows were found in this PDF.",
            foreground=ORANGE, font=("Segoe UI", 11),
        ).pack(pady=20)

    section = None
    grid = None
    for row in rows:
        if row["section"] != section:
            section = row["section"]
            ttk.Label(
                scroll_frame, text=section,
                font=("Segoe UI", 13, "bold", "underline"),
            ).pack(pady=(18, 4))
            grid = WrapGrid(scroll_frame)
        grid.add(make_card(
            grid.frame, row["label"], row.get("image"), row["value"],
            row.get("page"), image_references,
            key=f"{row['section']} — {row['label']}",
        ))


# ============================================================
# S63: DOCUMENTS WINDOW - drop PDFs in; each is read and its tabs appear
# ============================================================
# The window opens straight away with a "Documents" tab. PDFs dragged onto it
# (from File Explorer) are recognised from their contents (6000 form / Dig Packet /
# OmegaWrap quote request), read in the background, and their tabs - and the
# comparison tabs between them - are built as soon as they are read. More PDFs can
# be dropped in at any time; the X next to a document removes it and everything
# read from it, and the tabs are built again without it.
#   - The OCR models load in the background the moment the window opens (once
#     per program run), so a Dig Packet does not wait for them unless it is dropped
#     in during the first ~20 s.
#   - Any number of documents of any kind (S73). Dig Packets are read one after the
#     other; each keeps its own page-1 pictures; every value key starts with its
#     document's name; a 6000 form is paired with the Dig Packet holding its Wheel
#     Count; the Verify tab's end table shows them side by side.
#   - PyMuPDF must not read two PDFs at the same time, so every PyMuPDF step takes a
#     turn (pdf_turn). A Dig Packet takes its turns step by step and reads its
#     page-1 values and Notes from the page-1 picture without one, so a document
#     dropped in meanwhile is recognised and read in between - both keep going.
try:
    from tkinterdnd2 import TkinterDnD, DND_FILES
except ImportError:                      # drag-and-drop needs: pip install tkinterdnd2
    TkinterDnD, DND_FILES = None, None

DOCUMENT_KIND_NAMES = {"6000": "6000 form", "dig": "Dig Packet", "quote": "OmegaWrap quote request",
                       "other": "other document", "scan": "scanned PDF (looked at with OCR)",  # S213
                       "wt35": "10000-35 wall thickness form",                                   # S320
                       "report24": "24-hour field report"}                                       # S419
PDF_READ_LOCK = threading.Lock()


# S67: step progress. Each worker thread knows which document it is working on
# (PROGRESS.document); the reading code says when a step starts (progress_step) and
# the Documents list shows "42% - step 9/16: Notes line 1".
PROGRESS = threading.local()
DOCUMENT_STEPS = {        # steps before the reading steps are known in detail
    "6000": ["Recognise the PDF", "Fields", "Additional Notes", "Defect sections C-G", "Build the tabs"],
    "quote": ["Recognise the PDF", "Quote table", "Build the tabs"],
    "report24": ["Recognise the PDF", "Report tables", "Build the tabs"],                               # S419
    "other": ["Recognise the PDF", "Text pages", "Picture pages (OCR)", "Build the tabs"],      # S213
    "scan": ["Recognise the PDF", "Look at page 1 (OCR)", "Text pages", "Picture pages (OCR)", "Build the tabs"],
    "wt35": ["Recognise the PDF", "Form cells", "Photo printed text (OCR)", "Build the tabs"],         # S320
    # Dig Packet: recognise, [wait for the OCR models], page 1 picture, labels, 5 page-1 values,
    # find the Notes lines, one step per Notes line (1 until counted), map pages, table pages,
    # dig sheet + comparisons, build the tabs
}
DIG_STEPS_WITHOUT_NOTES_LINES = 14    # S102: + 'Open the PDF' (the printed text is read before page 1)


class DocumentRemoved(Exception):
    """S76: the document being read was removed with X - its reading stops at the next step."""


def progress_step(name):
    """A new step starts for the document this thread is working on. If that document
    was removed with X meanwhile, its reading stops here (S76)."""
    document = getattr(PROGRESS, "document", None)
    if document is None:
        return
    if document.get("removed"):
        raise DocumentRemoved(document["name"])
    document["step"] = min(document.get("step", 0) + 1, document.get("total", 1))
    document["step_name"] = name
    print(f"STEP {document['step']}/{document['total']}: {name} ({document['name']})")


def progress_add_steps(count):
    """More steps than assumed (e.g. the real number of Notes lines)."""
    document = getattr(PROGRESS, "document", None)
    if document is not None and count:
        document["total"] = document.get("total", 1) + count


# S406 (measuring only): who holds the one PDF turn, for how long, and who waited behind whom
PDF_TURN_USE = {"holder": None, "held": Counter(), "waits": Counter()}


def pdf_turn_group(who):
    """S406: a PDF turn's user in short - the part before ':' ('Verify tab', 'Dig Packet', ...)."""
    return str(who).split(":")[0].strip() or str(who)


def pdf_turn_summary():
    """S406: the end of the run - how long each kind of PDF work held the PDF turn, and the waits behind it."""
    held, waits = PDF_TURN_USE["held"], PDF_TURN_USE["waits"]
    if not held:
        return
    waited_by = Counter()
    for (waiter, _holder), seconds in waits.items():
        waited_by[waiter] += seconds
    print("PDF TURN USE: held - " + ", ".join(f"{who} {sec:.1f} s" for who, sec in held.most_common())
          + ("; waited - " + "; ".join(
              f"{waiter} {total:.1f} s (behind " + ", ".join(f"{h} {sec:.1f} s" for (w, h), sec in waits.most_common()
                                                           if w == waiter) + ")"
              for waiter, total in waited_by.most_common()) if waited_by else "; nobody waited") + " (S406)")


@contextmanager
def pdf_turn(who):
    """S64: one PyMuPDF user at a time. Whoever has to wait for the other document's
    PDF step says how long (only when it was noticeable) - in the log, and in the
    Documents list while it waits (S67)."""
    started = time.perf_counter()
    holder = PDF_TURN_USE["holder"]                     # S406: who has the PDF right now (if anyone)
    document = getattr(PROGRESS, "document", None)
    if document is not None:
        document["waiting"] = not PDF_READ_LOCK.acquire(blocking=False)
        if not document["waiting"]:
            PDF_READ_LOCK.release()
    with PDF_READ_LOCK:
        if document is not None:
            document["waiting"] = False
        waited = time.perf_counter() - started
        if waited >= 0.05:
            print(f"PDF TURN: {who} waited {waited:.1f} s while another document's PDF step finished"
                  + (f" ({holder} had it when the wait began - S406)" if holder else ""))
            PDF_TURN_USE["waits"][(pdf_turn_group(who), pdf_turn_group(holder or "?"))] += waited
        PDF_TURN_USE["holder"], held_from = who, time.perf_counter()
        try:
            yield
        finally:
            PDF_TURN_USE["held"][pdf_turn_group(who)] += time.perf_counter() - held_from
            PDF_TURN_USE["holder"] = None
SIX_THOUSAND_MARKERS = ["FACILITY/PIPELINE/INDEX", "DISTANCE TO COMPRESSOR STATION", "LONG SEAM TYPE",
                        "DESCRIBE COATING CONDITION", "PROJECT NUMBER"]


def classify_pdf(path, facts=None):
    """Which kind of document a dropped PDF is, from its text: an OmegaWrap quote
    request (page 1 says QUOTE REQUEST), a 24-hour field report (S419: page 1 says so), a 6000 form (at least 3 of its printed
    headings, e.g. 'Facility/Pipeline/Index #'), otherwise a Dig Packet (its page 1
    is a picture). Returns (kind, why). S468: `facts` (a dict), when given, gets the PDF's text as 'text' - for
    the queue order (queue_facts), so the PDF is not opened twice."""
    with fitz.open(path) as document:
        if not len(document):
            return None, "the PDF has no pages"
        first = document[0].get_text().upper()
        text = " ".join(page.get_text() for page in document).upper()
    if facts is not None:
        facts["text"] = text
    if "QUOTE REQUEST" in first:
        return "quote", "page 1 says QUOTE REQUEST"
    if re.search(re.escape(REPORT24_TITLE).replace(r"\ ", r"\s+"), first):            # S419
        return "report24", "page 1 says 24-Hour Field Report"
    found = [marker for marker in SIX_THOUSAND_MARKERS if marker in re.sub(r"\s+", " ", text)]
    if len(found) >= 3:
        return "6000", f"{len(found)} of the 6000 form's printed headings found"
    # S213: a Dig Packet says so somewhere in its text (map notes, dig sheet) - anything else is
    # another document, read with what it has
    marker = next((m for m in DIG_PACKET_MARKERS if m in text), None)
    if marker:
        return "dig", f"its text has '{marker.title()}'" + (" (page 1 is a picture)" if not first.strip() else "")
    if not text.strip():                          # all pictures: page 1 is looked at with OCR first
        return "scan", "no PDF text at all - page 1 is read with OCR to see whether it is a Dig Packet"
    return "other", "no quote / 6000 form / Dig Packet signs - read with what it has"


# S468: THE QUEUE ORDER OF A DROP. Whatever order the documents are dropped in (and whatever they are named), the
# Dig Packets are read dig by dig: the packets of one dig (sharing a wheel count - a packet's own one, or the ones its
# map notes list) one after another, the digs that a dropped 6000 form is about first, and the digs of one pipeline
# (its Line ID, e.g. 'SHC 20-1') next to each other, in wheel count order. Everything is found in the PDF's own text
# (no OCR - the quick look every PDF gets anyway); wheel counts are only compared as written (wheel_same) - never
# worked out. S469: the same facts say which still-loading document could still add to a dig (dig_settled).
QUEUE_WHEEL_COUNT = re.compile(r"WHEEL\s*COUNT\W{0,3}(\d{2,7}\.\d{2,3})(?!\d)")       # map notes, 6000 form
QUEUE_LOG_DIST = re.compile(r"LOG\s*DIST\.?\s*:?\s*(\d{2,7}\.\d{2,3})(?!\d)")        # the ROSEN dig sheet
QUEUE_NAME_NUMBER = re.compile(r"(?<![\w.])(\d{2,7}\.\d{2,3})(?![\d.])")             # '121278.84_2.pdf'
QUEUE_FORM_NUMBER = re.compile(r"(?<!\d)(6000-\d{2}-\d{3})(?!\d)")                    # S474: '..._6000-10-237-08202026'
QUEUE_LINE_ID = re.compile(r"\b([A-Z]{2,5}) ?(\d{1,3}-\d{1,3})")                       # 'SHC 20-1', 'BAE 36-1'


def queue_facts(text, name, kind):
    """S468: what a dropped document's own text (and file name) says about which dig it belongs to:
    {'own': its own wheel count(s), 'wheels': every wheel count it names (its own + the ones its map notes list),
    'line': its Line ID or None, 'form': the 6000 form number in its file name or None (S474)}. A Dig Packet's own wheel count: its dig sheet's Log Dist., else the map wheel count
    its file name holds ('14413528DigPacket_2' -> 144135.28), else the number in its file name. A map lists the
    neighbouring lines' IDs too, so a Dig Packet's Line ID is the one its text names at least twice. Wheel counts as
    written (wheel_text) - nothing worked out. Empty lists when nothing is found (a scan: no PDF text)."""
    text = (text or "").upper()
    stem = os.path.splitext(os.path.basename(name or ""))[0]
    keep = lambda values: list(dict.fromkeys(w for w in (wheel_text(v) for v in values) if w))
    family = keep(QUEUE_WHEEL_COUNT.findall(text))
    own = keep(QUEUE_LOG_DIST.findall(text))
    digits = re.sub(r"\D", "", stem)
    if not own and kind in ("dig", "scan"):
        own = [w for w in family if w.replace(".", "") in digits]
    if not own and kind not in ("dig", "scan"):
        own = family                                   # a 6000 form / report names its own wheel count
    if not own:                                        # not a time in it ('..._20260821T132243.089_GMT')
        own = keep(QUEUE_NAME_NUMBER.findall(stem.replace("_", " ")))
    lines = Counter(f"{a} {b}" for a, b in QUEUE_LINE_ID.findall(text))
    line = next((l for l, n in lines.most_common(1) if n >= (2 if kind in ("dig", "scan") else 1)), None)
    form = QUEUE_FORM_NUMBER.search(stem)
    return {"own": own, "wheels": list(dict.fromkeys(own + family)), "line": line,
            "form": form.group(1) if form else None}


def line_id_key(value):
    """S477: a Line ID to compare pipelines by - its 'SHC 20-1' part when it has one ('SHC 20-1TT - Sharon-Carthage
    20"' -> 'SHC 20-1'), else the text in capitals; None when there is none."""
    text = re.sub(r"\s+", " ", str(value or "")).strip().upper()
    if not text or text == "-":
        return None
    found = QUEUE_LINE_ID.search(text)
    return f"{found.group(1)} {found.group(2)}" if found else text


def queue_rank(document):
    """S468: a document's place in the reading queue - set for each drop by light_worker; else the drop order."""
    return document.get("queue_rank", document["id"])


def queue_wheels_meet(first, second):
    """S468: two lists of wheel counts share one, as written (wheel_same)."""
    return any(wheel_same(a, b) for a in first for b in second)


def dig_queue_order(digs, forms):
    """S468: the Dig Packets of a drop in the order they are read, and a line per dig for the terminal. Packets
    sharing a wheel count are one dig; a dig a 6000 form is about (it shares the form's wheel count) goes first, in the
    order the forms were dropped; the digs of one Line ID are kept together (the Line ID with a 6000 form's dig first),
    and within a Line ID by wheel count; a packet whose text gives no wheel count goes last, in the order it was
    dropped. Inside a dig: by its own wheel count."""
    facts = lambda d: d.get("queue_facts") or {"own": [], "wheels": [], "line": None}
    groups = []                                        # [{'digs', 'wheels', 'line'}]
    unknown = []
    for dig in sorted(digs, key=lambda d: d["id"]):
        mine = facts(dig)
        if not mine["wheels"]:
            unknown.append(dig)
            continue
        joined = [g for g in groups if queue_wheels_meet(mine["wheels"], g["wheels"])
                  and not (mine["line"] and g["line"] and mine["line"] != g["line"])]
        group = {"digs": [dig], "wheels": list(mine["wheels"]), "line": mine["line"]}
        for other in joined:                           # one packet can join two digs into one
            groups.remove(other)
            group["digs"] += other["digs"]
            group["wheels"] += other["wheels"]
            group["line"] = group["line"] or other["line"]
        groups.append(group)
    forms = sorted(forms, key=lambda d: d["id"])
    for group in groups:
        group["form"] = next((n for n, form in enumerate(forms)
                              if queue_wheels_meet(facts(form)["own"], group["wheels"])), None)
        group["first"] = min(d["id"] for d in group["digs"])
        group["low"] = min((wheel_decimal(w) for w in group["wheels"]), default=None)
        group["digs"].sort(key=lambda d: (min((wheel_decimal(w) for w in facts(d)["own"] or facts(d)["wheels"]),
                                              default=Decimal(0)), d["id"]))
    line_rank = {}
    for group in sorted(groups, key=lambda g: (g["form"] is None, g["form"] or 0, g["first"])):
        line_rank.setdefault(group["line"] or ("", group["first"]), len(line_rank))
    groups.sort(key=lambda g: (line_rank[g["line"] or ("", g["first"])], g["form"] is None, g["form"] or 0,
                               g["low"], g["first"]))
    ordered = [d for g in groups for d in g["digs"]] + unknown
    said = [f"{g['line'] or 'Line ID not in its text'}"
            + (f" (6000 form {forms[g['form']]['name']})" if g["form"] is not None else "")
            + ": " + ", ".join(d["name"] for d in g["digs"]) for g in groups]
    if unknown:
        said.append("no wheel count in the PDF text (read last, as dropped): " + ", ".join(d["name"] for d in unknown))
    return ordered, said


def read_6000_document(path):
    print()
    print("6000 FORM:", path)
    with timed("6000 form"):
        # dataC: the PDF is opened once for all three steps, so each page's drawings and styled text are
        # read once (page_drawings / page_text_dict) instead of up to three times
        document = fitz.open(path)
        try:
            progress_step("Fields")
            with timed("Fields", 1):
                extracted = extract_fields_from_document(document)
            progress_step("Additional Notes")
            with timed("Additional Notes", 1):
                notes = extract_additional_notes_from_document(document)
            progress_step("Defect sections C-G")
            with timed("Defect sections C-G", 1):
                defects = extract_defect_sections_from_document(document, notes)
        finally:
            document.close()
    return path, extracted, notes, defects


def read_quote_document(path):
    print()
    print("QUOTE REQUEST:", path)
    progress_step("Quote table")
    with timed("Quote request table"):
        rows = extract_quote_request(path)
    return path, rows


# S419: A BOARDWALK 24-HOUR FIELD REPORT (Integrity Specialists' 'Field Report for Metal Loss Defects', made in
# Excel): its PDF text is exact, so it is read from the text layer - no OCR, and its photos are not read. Page 1:
# Location Information and Pipe Data ('Label:  value' pairs, two per line in Pipe Data), the Tool Call /
# Anomaly Information table (one row per feature: the tool call, what the crew found, each wrinkle) and the
# Summary. The other pages: one page per feature (its values again, with the depth / height in % too) and the
# photo pages (their printed captions). Everything is found by where the words sit, not by fixed positions.
REPORT24_TITLE = "24-HOUR FIELD REPORT"
REPORT24_RGW = re.compile(r"^[+-]?\d+(?:\.\d+)?'$")          # a table row's distance from the girth weld: +27.84'
REPORT24_FOOTER = re.compile(r"^Page\s+\d+\s+of\s+\d+$|All\s+Contents\s+Copyright", re.IGNORECASE)


def report24_lines(words, tolerance=4.0):
    """S419: words (x0, y0, x1, y1, text) into lines - words whose middles are within `tolerance` points up or
    down are one line (a value printed a point lower than its label is on the label's line). Each line:
    {'words' (left to right), 'text', 'box', 'y' (its middle)}, top to bottom."""
    lines = []
    for word in sorted(words, key=lambda w: ((w[1] + w[3]) / 2, w[0])):
        middle = (word[1] + word[3]) / 2
        line = next((l for l in lines if abs(l["y"] - middle) <= tolerance), None)
        if line is None:
            lines.append({"y": middle, "words": [word]})
        else:
            line["words"].append(word)
    for line in lines:
        line["words"].sort(key=lambda w: w[0])
        line["text"] = " ".join(w[4] for w in line["words"])
        line["box"] = report24_box(line["words"])
    return sorted(lines, key=lambda l: l["y"])


def report24_box(words):
    return (min(w[0] for w in words), min(w[1] for w in words), max(w[2] for w in words), max(w[3] for w in words))


def report24_clusters(words, gap):
    """S419: a line's words cut where the space between two words is wider than `gap` points:
    [{'text', 'box', 'words'}] left to right."""
    clusters = []
    for word in sorted(words, key=lambda w: w[0]):
        if clusters and word[0] - clusters[-1]["words"][-1][2] <= gap:
            clusters[-1]["words"].append(word)
        else:
            clusters.append({"words": [word]})
    for cluster in clusters:
        cluster["text"] = " ".join(w[4] for w in cluster["words"])
        cluster["box"] = report24_box(cluster["words"])
    return clusters


def report24_line_index(lines, pattern, start=0):
    return next((i for i in range(start, len(lines)) if re.search(pattern, lines[i]["text"], re.IGNORECASE)), None)


def report24_pairs(lines, page):
    """S419: page 1's 'Label:  value' pairs (Location Information, Pipe Data). A label is a piece of a line that
    ends with ':' - or (S419: 'Current (psi)' has no ':') one whose right edge is where the labels' right edges
    are (they are right-aligned in their column). A label's value is the line's next pieces up to the next
    label. [{'section', 'label', 'value', 'page', 'box'}] - a label with nothing after it is left out."""
    clustered = [(line, report24_clusters(line["words"], 8)) for line in lines]
    edges = []
    for _line, clusters in clustered:
        for cluster in clusters:
            if cluster["text"].endswith(":") and all(abs(cluster["box"][2] - e) > 3 for e in edges):
                edges.append(cluster["box"][2])
    pairs, section = [], None
    for line, clusters in clustered:
        if len(clusters) == 1 and not clusters[0]["text"].endswith(":"):
            section = clusters[0]["text"]                     # a section heading: 'Location Information'
            continue
        label = None
        for cluster in clusters:
            if cluster["text"].endswith(":") or any(abs(cluster["box"][2] - e) <= 3 for e in edges):
                label = {"section": section, "label": cluster["text"].rstrip(":").strip(), "parts": [],
                         "page": page}
                pairs.append(label)
            elif label is not None:
                label["parts"].append(cluster)
    for pair in pairs:
        parts = pair.pop("parts")
        pair["value"] = " ".join(p["text"] for p in parts)
        pair["box"] = report24_box([w for p in parts for w in p["words"]]) if parts else None
    return [p for p in pairs if p["value"]]


def report24_table(lines, words, start, end, page):
    """S419: the Tool Call / Anomaly Information table between line `start` (its heading) and line `end`
    (Summary). Its first row is the first line with a girth weld distance (+27.84'); the words between the
    heading and that row are the column headings - a column is every heading word that overlaps it left to
    right ('RGW' over '(+/-) ft'), or only a word space from it ('Feature Name:'). Each row's words go in the column they sit in (else the nearest one).
    Returns (column names, [{'cells': {name: {'text', 'box'}}, 'page', 'box'}])."""
    first = next((i for i in range(start + 1, end) if any(REPORT24_RGW.match(w[4]) for w in lines[i]["words"])),
                 None)
    if first is None:
        return [], []
    top, bottom = lines[start]["box"][3], lines[first]["y"] - 5
    heading = [w for w in words if w[1] >= top - 0.5 and (w[1] + w[3]) / 2 < bottom]
    spans = []
    for word in sorted(heading, key=lambda w: w[0]):
        if spans and word[0] <= spans[-1]["x1"] + 4:          # overlapping, or a word space ('FID #')
            spans[-1]["words"].append(word)
            spans[-1]["x1"] = max(spans[-1]["x1"], word[2])
        else:
            spans.append({"x0": word[0], "x1": word[2], "words": [word]})
    for span in spans:
        span["name"] = " ".join(l["text"] for l in report24_lines(span["words"], 3)).rstrip(":").strip()
    names = [s["name"] for s in spans]
    rows = []
    for line in lines[first:end]:
        cells = {}
        for word in line["words"]:
            middle = (word[0] + word[2]) / 2
            span = next((s for s in spans if s["x0"] - 4 <= middle <= s["x1"] + 4), None) or \
                min(spans, key=lambda s: min(abs(middle - s["x0"]), abs(middle - s["x1"])))
            cells.setdefault(span["name"], []).append(word)
        rows.append({"cells": {name: {"text": " ".join(w[4] for w in found), "box": report24_box(found), "page": page}
                               for name, found in cells.items()}, "page": page, "box": line["box"]})
    return names, rows


def report24_detail(lines, page, title_index):
    """S419: a feature's own page: its title line ('FID 7095 / Wrinkle 1') and its 'label  value' lines (the
    label left, the value far right; a label with no value is left out)."""
    title = lines[title_index]
    pairs = []
    for line in lines[title_index + 1:]:
        if REPORT24_FOOTER.search(line["text"]):
            break
        clusters = report24_clusters(line["words"], 20)
        if len(clusters) < 2:
            continue
        values = [w for c in clusters[1:] for w in c["words"]]
        pairs.append({"label": clusters[0]["text"].rstrip(":").strip(), "value": " ".join(w[4] for w in values),
                      "page": page, "box": report24_box(values)})
    return {"page": page, "title": title["text"], "title_box": title["box"], "pairs": pairs}


def report24_parse(pages):
    """S419: a 24-hour field report from its pages' words [[(x0, y0, x1, y1, text), ...], ...] (PDF points).
    Returns {'title', 'pairs', 'columns', 'rows', 'summary', 'details', 'captions'}; each row has 'kind' -
    'tool call' (its feature page's title says Tool Call), 'wrinkle' (its name says Wrinkle) or 'field' (what
    the crew found) - and 'detail' (its feature page, matched by its name and girth weld distance) or None."""
    report = {"title": None, "pairs": [], "columns": [], "rows": [], "summary": None, "details": [], "captions": []}
    for number, words in enumerate(pages, start=1):
        lines = report24_lines(words)
        title_at = report24_line_index(lines, re.escape(REPORT24_TITLE).replace(r"\ ", r"\s+"))
        if title_at is None:
            continue
        if report["title"] is None:
            report["title"] = {"text": lines[title_at]["text"], "page": number, "box": lines[title_at]["box"]}
        table_at = report24_line_index(lines, r"Anomaly\s+Information", title_at)
        if number == 1 and table_at is not None:
            report["pairs"] = report24_pairs(lines[title_at + 1:table_at], number)
            summary_at = report24_line_index(lines, r"^Summary\s*:", table_at)
            end = summary_at if summary_at is not None else len(lines)
            report["columns"], report["rows"] = report24_table(lines, words, table_at, end, number)
            if summary_at is not None:
                body = []
                for line in lines[summary_at:]:
                    if REPORT24_FOOTER.search(line["text"]):
                        break
                    body.append(line)
                text = " ".join(l["text"] for l in body)
                report["summary"] = {"text": re.sub(r"^Summary\s*:\s*", "", text, flags=re.IGNORECASE),
                                     "page": number, "box": report24_box([w for l in body for w in l["words"]])}
            continue
        feature_at = report24_line_index(lines, r"^Feature\s+Name\s*:", title_at)
        if feature_at is not None and feature_at > title_at + 1:
            report["details"].append(report24_detail(lines, number, title_at + 1))
            continue
        for line in lines[title_at + 1:]:                  # a photo page: its printed captions
            if not REPORT24_FOOTER.search(line["text"]):
                report["captions"].append({"text": line["text"], "page": number, "box": line["box"],
                                           "detail": len(report["details"]) - 1 if report["details"] else None})
    name_column = next((c for c in report["columns"] if report24_column_role(c)[0] == "name"), None)
    for row in report["rows"]:
        name = " ".join(str((row["cells"].get(name_column) or {}).get("text") or "").split())
        rgw = report24_number((row["cells"].get(report24_rgw_column(report["columns"])) or {}).get("text"))
        row["name"] = name
        row["detail"] = next((i for i, d in enumerate(report["details"])
                              if " ".join(report24_detail_value(d, "name").split()) == name
                              and report24_number(report24_detail_value(d, "rgw")) == rgw), None)
        title = report["details"][row["detail"]]["title"] if row["detail"] is not None else ""
        row["kind"] = ("tool call" if re.match(r"\s*Tool\s+Call\b", title, re.IGNORECASE) else
                       "wrinkle" if re.search(r"\bwrinkle", name, re.IGNORECASE) else "field")
    return report


def report24_column_role(name):
    """S419: what a table column / feature page label holds: ('name',) the feature name; ('field', priority
    field) Length / Width / Clock Position (TDC hh:mm); ('depth',) the depth (metal loss) or height (wrinkle);
    ('rgw',) the distance from the girth weld; ('other',) the rest (FID #, Joint #, longest lengths)."""
    text = " ".join(str(name or "").lower().split())
    if text.startswith("feature"):
        return ("name", None)
    if "interconnect" in text or "longest" in text:
        return ("other", None)
    if re.match(r"rgw\b", text):
        return ("rgw", None)
    if re.match(r"tdc\b", text) or "clock" in text:
        return ("field", "Clock Position")
    if re.match(r"(depth|height)\b", text):
        return ("depth", None)
    if re.match(r"length\b", text):
        return ("field", "Length")
    if re.match(r"width\b", text):
        return ("field", "Width")
    return ("other", None)


def report24_rgw_column(columns):
    return next((c for c in columns if report24_column_role(c)[0] == "rgw"), None)


def report24_detail_value(detail, role):
    return next((p["value"] for p in detail["pairs"] if report24_column_role(p["label"])[0] == role), None)


def report24_number(text):
    """S419: the first number in a report value, with its sign ('+27.84'' -> 27.84, '-3.10'' -> -3.1)."""
    match = re.search(r"[+-]?\d+(?:\.\d+)?", str(text or "").replace(",", ""))
    return float(match.group(0)) if match else None


def report24_differences(report, row):
    """S419: a feature page's values that differ from its table row on page 1 (the same column: by what it
    holds, or by its name - 'Joint #'): [(feature page pair, table column)]. Numbers are compared as numbers
    (+27.84' = 27.84), the rest as written."""
    if row["detail"] is None:
        return []
    found = []
    for pair in report["details"][row["detail"]]["pairs"]:
        role = report24_column_role(pair["label"])
        if role[0] == "name":
            continue
        column = next((c for c in report["columns"] if report24_column_role(c) == role
                       and (role[0] != "other" or report24_plain(c) == report24_plain(pair["label"]))), None)
        cell = (row["cells"].get(column) or {}).get("text") if column else None
        if column is None or cell is None:
            continue
        a, b = report24_number(pair["value"]), report24_number(cell)
        same = (a == b) if a is not None and b is not None else report24_plain(pair["value"]) == report24_plain(cell)
        if not same:
            found.append((pair, column))
    return found


def report24_plain(text):
    return re.sub(r"[^a-z0-9]+", " ", str(text or "").lower()).strip()


def read_report24_document(path):
    """S419: a 24-hour field report - its PDF text (no OCR; its photos are not read)."""
    print()
    print("24-HOUR FIELD REPORT:", path)
    progress_step("Report tables")
    with timed("24-hour field report"):
        with fitz.open(path) as document:
            pages = [[tuple(w[:5]) for w in page.get_text("words")] for page in document]
        report = report24_parse(pages)
    report24_print(report)
    return {"path": path, "report": report}


def report24_print(report):
    """S419: what was read from a 24-hour field report - so a report laid out differently shows what was missed."""
    print(f"24-HOUR REPORT: title {report['title']['text']!r}" if report["title"] else "24-HOUR REPORT: no title found")
    for pair in report["pairs"]:
        print(f"24-HOUR REPORT: page {pair['page']} {pair['section']} - {pair['label']}: {pair['value']}")
    print(f"24-HOUR REPORT: table columns: {' | '.join(report['columns']) or '(no table found)'}")
    for row in report["rows"]:
        detail = report["details"][row["detail"]] if row["detail"] is not None else None
        print(f"24-HOUR REPORT: row '{row['name']}' ({row['kind']}): "
              + "; ".join(f"{name} {cell['text']}" for name, cell in row["cells"].items())
              + (f" - its page {detail['page']} '{detail['title']}'" if detail else
                 " - no feature page with its name and girth weld distance (so it counts as "
                 + ("a wrinkle" if row["kind"] == "wrinkle" else "found in the field") + ")"))
        for pair, column in report24_differences(report, row):
            print(f"24-HOUR REPORT CHECK: '{row['name']}' - page {pair['page']} says {pair['label']} "
                  f"{pair['value']}, the page-1 table says {column} {row['cells'][column]['text']} - both kept")
    if report["summary"]:
        print(f"24-HOUR REPORT: Summary ({len(report['summary']['text'])} characters): {report['summary']['text']}")
    for caption in report["captions"]:
        print(f"24-HOUR REPORT: photo page {caption['page']} caption: {caption['text']}")
    print(f"24-HOUR REPORT: {len(report['pairs'])} location / pipe values, {len(report['rows'])} table rows, "
          f"{len(report['details'])} feature pages, {len(report['captions'])} photo captions (photos not read) (S419)")


@contextmanager
def quiet_this_thread():
    """Holds back what THIS thread prints (other threads keep printing) and drops it."""
    thread = threading.get_ident()
    stack = OUTPUT_CAPTURES.setdefault(thread, [])
    stack.append([])
    try:
        yield
    finally:
        if stack:
            stack.pop()
        if not stack:
            OUTPUT_CAPTURES.pop(thread, None)


def read_text_while_models_load(path):
    """S107: what a Dig Packet can read before the OCR models are ready - its map pages
    (only when every page that looks like a map page has a PDF text layer, so nothing
    needs OCR) and its dig sheet (PDF text). Returns {'Map Pages': ..., 'Dig Sheets': ...}
    with whatever could be read; the rest is read the normal way later."""
    early = {}
    with fitz.open(path) as document:
        map_like = [i for i in range(len(document)) if dm_screen_for_map_page(document[i])]
        if all(len(document[i].get_text().split()) >= 20 for i in map_like):
            try:
                with quiet_this_thread():
                    early["Map Pages"] = extract_all_map_pages_v23(document)
            except Exception:
                pass                                   # read the normal way later
        try:
            with quiet_this_thread():
                early["Dig Sheets"] = read_dig_sheets(document)
                early["Text Pages"] = read_text_page_values(document)          # S194
        except Exception:
            pass
    return early


def read_dig_document(path, early=None):
    print()
    print("DIG PACKET:", path)
    try:
        with timed("Read Dig Packet"):
            dig_results = extract_dig_packet(path, early)
    finally:
        forget_pdf_prefetch(path)                 # S84: its second-process result is used up
    with timed("Save debug image"):
        debug_paths = save_debug_images(dig_results)
    started = time.perf_counter()
    prepared = prepare_window_pictures(dig_results)
    record_timing(f"Window pictures prepared in the reading thread ({prepared})", time.perf_counter() - started)
    return {"path": path, "method": "Dropped in the window", "results": dig_results,
            "debug_paths": debug_paths, "warning": None,
            "page_map": dict(PAGE_MAP, background=dict(PAGE_BACKGROUND))}   # S73: its own page-1 state


def document_labels(documents):
    """S73: a short, unique name per document (its file name without .pdf, at most 28
    characters) - used in tab names and in front of its value keys."""
    labels, used = {}, set()
    for document in documents:
        label = os.path.splitext(document["name"])[0]
        label = label if len(label) <= 28 else label[:27] + "…"
        base, number = label, 2
        while label in used:
            label = f"{base} #{number}"
            number += 1
        used.add(label)
        labels[id(document)] = label
    return labels


def wheel_count_in_dig(wheel, dig_results):
    """S73: True when the Dig Packet has this Wheel Count anywhere: page 1, a map note,
    or a table row's Odometer (S438: written the same)."""
    target = re.sub(r"[^0-9.]", "", str(wheel or ""))           # S438: as written
    if wheel_decimal(target) is None:
        return False
    found = []
    for _key, value in coordinate_display_items("Wheel Count", (dig_results or {}).get("Wheel Count")):
        found.append(value)
    for map_page in (dig_results or {}).get("Map Pages") or []:
        for note in map_page.get("notes", []):
            found += re.findall(r"Wheel\s*Count\s*([0-9]+(?:\.[0-9]+)?)", str(note.get("value") or ""), re.IGNORECASE)
    for table_page in (dig_results or {}).get("Table Highlights") or []:
        for item in table_page.get("items", []):
            found.append(cmp_table_cell(item, r"odometer") or item.get("odometer") or "")
    for value in found:
        try:
            if wheel_same(re.sub(r"[^0-9.]", "", str(value)), target):      # S438: exactly
                return True
        except ValueError:
            continue
    return False


# ============================================================
