    ("Clock Position", r"clock\s*position|o.?\s*clock|orientation", r"seam"),       # S223 (a seam's clock is the pipe's)
    ("Stress Concentrator", r"stress\s*concentrat", None),                                          # S240
    ("Line ID", r"line\s*(id|name|no\.?|number|#)|pipeline\s*(name|id|no)|facility|index\s*#", None),   # S173
