# S452: wheel counts on a different pipe are never one repair (each calculator has one cell for each): the Outside
# Diameter / Wall Thickness compared as the calculator takes them, Pipe Grade / Class Location as written (one not
# known does not keep them apart)
REPAIR_SAME_PIPE_ROWS = ("Outside Diameter", "Wall Thickness", "Pipe Grade", "Class Location")

# S456: the calculator's Pipe Grade dropdown (Corrosion E7 and Mechanical E7) takes only these, written exactly so;
# a document's Pipe Grade (its 'Pipe Grade' row - never SMYS / Yield Strength) given as its SMYS (psi) is read by
# this table (API 5L grade: SMYS) - '42100' or '42,100' -> 'X42'
PIPE_GRADE_CELLS = {"Corrosion": "E7", "Mechanical": "E7"}
PIPE_GRADES = ["24,000", "A25", "A", "B", "X42", "X46", "X52", "X56", "X60", "X65", "X70"]
PIPE_GRADE_SMYS = {"24,000": 24000, "A25": 25000, "A": 30500, "B": 35500, "X42": 42100, "X46": 46400, "X52": 52200,
                   "X56": 56600, "X60": 60200, "X65": 65300, "X70": 70300, "X80": 80500}


# S457: the calculator's Class Location dropdown (Corrosion E10 and Mechanical E10) takes only 40 / 50 / 60 / 72:
# class 4 -> 40, class 3 -> 50, class 2 -> 60, class 1 -> 72; class 1 (72) is assumed when no document says
CLASS_LOCATION_CELLS = {"Corrosion": "E10", "Mechanical": "E10"}
CLASS_LOCATION_VALUES = {1: 72, 2: 60, 3: 50, 4: 40}
CLASS_LOCATION_ROMAN = {"I": 1, "II": 2, "III": 3, "IV": 4}


def class_location_number(text):
    """S457: the class (1 - 4) one Class Location value says ('Class 3', '3', 'Class III'), or None."""
    raw = " ".join(str(text or "").split()).upper()
    if not raw or raw in ("-", VERIFY_PICK_PROMPT.upper()):
        return None
    digit = re.search(r"\b([1-4])\b", raw)
    if digit:
        return int(digit.group(1))
    roman = re.search(r"\b(IV|III|II|I)\b", raw.replace("CLASS", " "))
    return CLASS_LOCATION_ROMAN[roman.group(1)] if roman else None


def pipe_grade_for_calculator(text):
    """S456: (grade as the calculator takes it or None, what was read) for one Pipe Grade value as written -
    'X-52', 'API 5L X52', 'Gr. B', 'B', 'A25', '52,200' (its SMYS) ... A grade the calculator does not list (X80)
    gives None."""
    raw = " ".join(str(text or "").split())
    if not raw or raw in ("-", VERIFY_PICK_PROMPT):
        return None, "no Pipe Grade"
    upper = raw.upper().replace("API 5L", " ").replace("API5L", " ")
    found = None
    number = re.search(r"\b(\d{2},?\d{3})\b", upper)
    if number:                                       # its SMYS in psi (24,000 is a grade of its own)
        psi = int(number.group(1).replace(",", ""))
        found = next((g for g, v in PIPE_GRADE_SMYS.items() if v == psi), None)
        if found is None:
            return None, f"'{raw}' - {psi:,} psi is not an SMYS in the grade table"
    else:
        grade = re.search(r"\bX\s*-?\s*(\d{2})\b", upper)
        if grade:
            found = f"X{grade.group(1)}"
        elif re.search(r"\bA\s*-?\s*25\b", upper):
            found = "A25"
        else:
            letter = re.search(r"(?:\bGR(?:ADE)?\.?\s*|^\s*)([AB])\s*$", upper)
            found = letter.group(1) if letter else None
    if found is None:
        return None, f"'{raw}' - not a pipe grade"
    if found not in PIPE_GRADES:
        return None, f"'{raw}' = {found} - not one the calculator lists"
    return found, f"'{raw}' = {found}"


def repair_pipe_key(pipe, name):
    """S452: one pipe value made comparable - a number in inches for OD / WT, the words for the others; None when
    not known."""
    text = str((pipe or {}).get(name) or "").strip()
    if not text or text in ("-", VERIFY_PICK_PROMPT):
        return None
    if name in ("Outside Diameter", "Wall Thickness"):
        return calculator_inches(text)
    if name == "Pipe Grade":                     # S456: 'X52' = '52,200' = 'API 5L X-52'
        grade = pipe_grade_for_calculator(text)[0]
        if grade:
            return grade
    if name == "Class Location":                 # S457: 'Class 3' = '3' = 'Class III'
        number = class_location_number(text)
        if number:
            return number
    return " ".join(re.findall(r"[a-z0-9]+", text.lower())) or None


def repair_pipe_differs(pipes, one, two):
    """S452: what differs between two sets of wheel counts' pipes ({header: pipe}) - [] when they can be one repair."""
    differs = []
    for name in REPAIR_SAME_PIPE_ROWS:
        a = {repair_pipe_key(pipes.get(m), name) for m in one} - {None}
        b = {repair_pipe_key(pipes.get(m), name) for m in two} - {None}
        if a and b and a != b:
            differs.append(f"{name} {' / '.join(sorted(map(str, a)))} vs {' / '.join(sorted(map(str, b)))}")
    return differs


def repair_grade(pipes, members):
    """S456/S458: (the Pipe Grade for a repair's calculator or None, what was found) - its anomalies' Pipe Grade rows
    (one repair is on one pipe - S452)."""
    read = [(m, *pipe_grade_for_calculator((pipes.get(m) or {}).get("Pipe Grade"))) for m in members]
    grades = sorted({g for _m, g, _why in read if g})
    notes = "; ".join(f"{m}: {why}" for m, _g, why in read)
    if len(grades) == 1:
        return grades[0], f"{grades[0]} ({notes})"
    if grades:
        return None, f"different grades in one repair, none set ({notes})"
    return None, f"none set ({notes})"


def repair_class(pipes, members):
    """S457/S458: (40 / 50 / 60 / 72 for a repair's calculator or None, what was found) - class 1 (72) when no
    anomaly in it says."""
    read = [(m, (pipes.get(m) or {}).get("Class Location")) for m in members]
    classes = sorted({c for c in (class_location_number(t) for _m, t in read) if c})
    notes = "; ".join(f"{m}: '{t}'" if str(t or "").strip() not in ("", "-") else f"{m}: none" for m, t in read)
    if len(classes) > 1:
        return None, f"different classes in one repair ({notes}) - none set"
    number = classes[0] if classes else 1
    return (CLASS_LOCATION_VALUES[number],
            f"class {number} -> {CLASS_LOCATION_VALUES[number]}" + ("" if classes else " (class 1 assumed)")
            + f" ({notes})")


def repair_largest(pipes, members, field):
    """S452/S458: (the largest Depth / Width of a repair's anomalies in inches - as E13 / E16 take it - or None, the
    wheel count it is from) - compared only."""
    found = [(calculator_inches((pipes.get(m) or {}).get(field)), m) for m in members]
    found = [(v, m) for v, m in found if v is not None]
    return max(found) if found else (None, None)


# S458: the Wheel Count Calculator sheet's check of one repair - its first and last wheel count (D2 / D3, feet) with
# their defect lengths (D9 / D10, inches) and the nearest separate physical feature on each side (D7 / D8 - not a
# girth weld, not a defect; e.g. a sleeve); D5 (Linear Length of Wrap) and D6 (L_over) the calculator works out
# from the other sheets; read back: C13:D41 (each output's name and wheel count, least to greatest)
WRAP_CHECK_CELLS = {"wc1": "D2", "wc2": "D3", "wrap": "D5", "l_over": "D6", "left": "D7", "right": "D8",
                    "length1": "D9", "length2": "D10"}
WRAP_CHECK_ROWS = range(13, 42)
# S462: the check's rows that are lengths (inches) - every other one is a wheel count (feet)
WRAP_CHECK_LENGTH_ROWS = {"Defect Length 1 (in)", "Defect Length 2 (in)", "Linear Length of Wrap (calculator)",
                          "L_over (calculator)"}
# S458: what a picked repair also puts into the calculator before it is worked out (as the Group calculator has it)
REPAIR_EXTRA_SHEET_CELLS = ("E7", "E10", "E13", "E16")


# S455: Main sheet dropdown - exactly 'Corrosion' or 'Mechanical' (one per calculator): 'Corrosion' only when every
# anomaly in the repair is pure corrosion / metal loss (the same rule as E-Glass), else 'Mechanical'
REPAIR_KIND_CELL = "C15"
GROUP_DATE_CELL = "H4"               # S466: Main sheet date of the Group calculator - mm/dd/yyyy, the day Group is clicked
GROUP_COVERS_CELL = "C11"            # S447: Main sheet comment of a combined repair's calculator - 'One wrap covers WC ...'


def fabric_for_type(text):
    """S443: ('E-Glass' or 'Carbon', why) for one anomaly type as written."""
    words = set(re.findall(r"[a-z]+", str(text or "").lower())) - FABRIC_QUALIFIER_WORDS
    if not words:
        return "Carbon", "no anomaly type found - Carbon"
    if words <= FABRIC_CORROSION_WORDS:
        return "E-Glass", f"'{text}' is only corrosion / metal loss - E-Glass"
    if words & FABRIC_CORROSION_WORDS:
        return "Carbon", f"'{text}' is corrosion with something else - Carbon"
    return "Carbon", f"'{text}' is not corrosion / metal loss - Carbon"


def combined_values(repairs, members):
    """S439: what goes to the calculator for these wheel counts as one repair - None when one has no repair worked
    out. No arithmetic here: every wheel count with its own defect length, smallest first (CO4:DR4 / CO5:DR5), the
    first one's Outside Diameter and Wall Thickness."""
    given = [(repairs.get(m) or {}).get("inputs") for m in members]
    if not all(given):
        return None
    pairs = [(float(m), g["Length"]) for m, g in zip(members, given)]
    return {"Outside Diameter": given[0]["Outside Diameter"], "Wall Thickness": given[0]["Wall Thickness"],
            "members": pairs}


def repair_length_inputs(headers, rows):
    """S296: every wheel count (anomaly column) whose Outside Diameter, Wall Thickness and defect Length
    are all known, in inches (no unit -> taken as inches): {header: {'Outside Diameter': 20.0, ...}}.
    S300: and those waiting for a pick - one of the three differs between documents and is not picked
    on Verify yet: {header: [what differs]}. Returns (ready, waiting)."""
    by_label = {row[0]: row for row in rows}
    found, waiting = {}, {}
    for header in dict.fromkeys(document_name_header(h) for h in headers[1:]):
        if not header or not re.fullmatch(r"\d+(\.\d+)?", header):
            continue
        texts = {name: end_table_value(headers, by_label, header, name, keep_prompt=True) for name in REPAIR_INPUT_CELLS}
        unpicked = [name for name, text in texts.items() if text == VERIFY_PICK_PROMPT]
        values = {name: calculator_inches(text) for name, text in texts.items() if text != VERIFY_PICK_PROMPT}
        missing = [n for n in REPAIR_INPUT_CELLS if n not in unpicked and values.get(n) is None]
        if unpicked:
            waiting[header] = [f"pick the {n}" for n in unpicked] + [f"no {n}" for n in missing]
        elif missing:
            waiting[header] = [f"no {n}" for n in missing]       # S301: said, not left out
        else:
            found[header] = values
    return found, waiting


EXTRA_PAGES_DESCRIPTION = (                              # S301: what a Pages tab shows
    "Pages: every page of this PDF as it is, each with a marked copy under it showing how it was read - "
    "BLUE boxes = words that are real PDF text (read exactly), ORANGE = pictures (scans, photos, handwriting - "
    "read by OCR), PURPLE = a priority value taken from the PDF text, YELLOW with a red border and its name = "
    "a priority value read from a picture. A line per page says how much of it is text / pictures.")


def extra_group_description(form, dig):
    """S301: what a document's tabs in the Extra list are, in words."""
    parts = []
    if form is not None:
        parts.append("6000 form: every field and defect section (C-G) read from the 6000 form's PDF text, each "
                     "with its snip of the page and a correction box (a correction typed there is used everywhere)")
    if dig is not None:
        parts.append(("the Dig Packet in the same tab" if form is not None else "Dig Packet") +
                     ": page 1's handwritten values with their snips, the map notes, red notes and other map "
                     "text, the dig sheet and the table rows found - each with its snip and a correction box")
        parts.append("Table rows: every coloured (yellow / blue / green) row of the Dig Packet's table pages, "
                     "cell by cell with each cell's snip")
        parts.append("Page 1 snip steps: how each page-1 handwritten line was cut into its (A) / (B) values - "
                     "the cuts tried and the reads of each piece (for checking a bad read)")
        parts.append("Page 1 full page: page 1 as a whole picture, with the paper colour taken out")
        parts.append("Dig Packet wheel counts: every wheel count in the packet side by side (map notes, table, "
                     "page 1)")
    return "  •  ".join(parts) + ("." if parts else "")


class RepairLengthExcel:
    """S296: a temporary copy of the calculator kept open in Excel (unseen, macros off, calculation manual)
    for the 'Linear Length of Repair': for each wheel count its OD, WT and defect length go into E4 / E5 /
    E15 of the Corrosion and Mechanical sheets, those two sheets are worked out and C27 (Corrosion) /
    C26 (Mechanical) are read. It stays open so new values are worked out at once; the copy is closed
    without saving and deleted when the window closes. All Excel work happens on its own thread."""

    def __init__(self, template):
        self.jobs = queue.Queue()
        self.working = False                    # S463: True while a job is being worked out
        self.thread = threading.Thread(target=self._run, args=(template,), daemon=True)
        self.thread.start()

    def busy(self):
        """S463: a job waiting or being worked out."""
        return self.working or not self.jobs.empty()

    def submit_distances(self, pairs, done):
        """S307: [(feet, feet)] -> {(a, b): (T22 in, T23 ft)} from the Wheel Count Calculator sheet (R3 / V3,
        lengths 0 in R5 / V5); done(answer or error) on this object's thread."""
        self.jobs.put(("distances", pairs, done))

    def submit(self, inputs, done):
        """inputs = {header: values}; done(results or an error) is called on this object's thread."""
        self.jobs.put((inputs, done))

    def submit_pair_distances(self, pairs, done):
        """S433: [(feet 1, defect length 1 in, feet 2, defect length 2 in)] -> {pair: (T22, T23, T27, T28)} from the
        Wheel Count Calculator sheet (R3 / V3, R5 / V5) - the distances of the combined repairs' table."""
        self.jobs.put(("pair distances", pairs, done))

    def submit_combined(self, inputs, done):
        """S429/S439: like submit, for combined repairs (overlapping wraps worked out as one): inputs = {name: values}
        with 'members' = its [(wheel count, defect length)] smallest first. Never dropped for a newer job."""
        self.jobs.put(("combined", inputs, done))

    def submit_picked(self, inputs, done):
        """S444: the picked repairs, each with its 'fabric' set on its sheet first: {name: values} - a single wheel
        count's values like submit's, a combined one's with 'members' like submit_combined's. Never dropped."""
        self.jobs.put(("picked", inputs, done))

    def stop(self):
        self.jobs.put(None)
        self.thread.join(timeout=30)

    def _run(self, template):
        folder = excel = book = None
        sheets, error, full = {}, None, None
        try:
            import pythoncom
            import win32com.client
            pythoncom.CoInitialize()
            started = time.perf_counter()
            folder = tempfile.mkdtemp(prefix="repair_lengths_")
            copy = os.path.join(folder, os.path.basename(template))
            shutil.copy2(template, copy)
            excel = win32com.client.DispatchEx("Excel.Application")
            excel.Visible = False
            excel.DisplayAlerts = False
            excel.AutomationSecurity = 3
            excel.ScreenUpdating = False
            excel.EnableEvents = False
            book = excel.Workbooks.Open(copy, UpdateLinks=0, ReadOnly=False)
            excel.Calculation = -4135                 # manual - a write no longer recalculates the workbook
            sheets = {name: book.Worksheets(name) for name in REPAIR_OUTPUT_CELLS}
            # S444: the fabric each sheet has in the calculator file - put back whenever no fabric is picked
            file_fabric = {name: sheets[name].Range(FABRIC_CELLS[name]).Value for name in sheets}
            wrap_sheet = book.Worksheets(WC_SHEET)      # S302: where the wrap starts and ends
            # S458: the cells a picked repair also fills - what the calculator file has, put back for every other job
            main_sheet = book.Worksheets("Main")
            file_cells = {(name, cell): sheets[name].Range(cell).Value
                          for name in sheets for cell in REPAIR_EXTRA_SHEET_CELLS}
            file_cells[("Main", REPAIR_KIND_CELL)] = main_sheet.Range(REPAIR_KIND_CELL).Value
            print(f"REPAIR LENGTHS: Excel ready with a copy of the calculator in {time.perf_counter() - started:.1f} s (S296)")
        except Exception as exc:
            error = exc
        def compute(inputs):
            """The Linear Lengths of Repair and their wraps for {header: values} (S429: shared by both kinds of job)."""
            nonlocal full
            results = {}
            for header, values in inputs.items():
                for sheet in sheets.values():
                    for name, cell in REPAIR_INPUT_CELLS.items():
                        sheet.Range(cell).Value = values[name]
                fabric = values.get("fabric")             # S444/S454: a picked repair's fabric on both sheets
                for name, sheet in sheets.items():
                    sheet.Range(FABRIC_CELLS[name]).Value = fabric or file_fabric[name]
                # S458: a picked repair's Pipe Grade (E7), Class Location (E10), largest depth / width (E13 / E16) on
                # both sheets and Corrosion / Mechanical (Main C15) - like the Group calculator; else the file's
                extra = values.get("extra") or {}
                for name, sheet in sheets.items():
                    for cell in REPAIR_EXTRA_SHEET_CELLS:
                        sheet.Range(cell).Value = extra[cell] if extra.get(cell) is not None else file_cells[(name, cell)]
                main_sheet.Range(REPAIR_KIND_CELL).Value = extra.get("C15") or file_cells[("Main", REPAIR_KIND_CELL)]
                if extra and not full:
                    main_sheet.Calculate()
                for sheet in sheets.values():
                    sheet.Calculate()             # only these two sheets
                read = {name: sheets[name].Range(cell).Value for name, cell in REPAIR_OUTPUT_CELLS.items()}
                if full is None:                  # first time: does a whole-workbook recalculation agree?
                    excel.Calculate()
                    again = {name: sheets[name].Range(cell).Value for name, cell in REPAIR_OUTPUT_CELLS.items()}
                    full = again != read
                    print(f"REPAIR LENGTHS: the two sheets alone give the same as the whole workbook - "
                          f"{'no, the whole workbook is worked out each time' if full else 'yes'} (S296)")
                    read = again
                elif full:
                    excel.Calculate()
                    read = {name: sheets[name].Range(cell).Value for name, cell in REPAIR_OUTPUT_CELLS.items()}
                # S302: each Linear Length of Repair -> the Wheel Count Calculator sheet: the wheel count
                # in K3 (feet), S436: the full repair length in M6 (the sheet halves it), 0 in M5 and M7; J3 = the wrap's start, L3 its end
                wraps, seen, pluses = {}, {}, {}
                middle = values["middle"] if "middle" in values else float(header)   # S439: a combined one's - CO17
                for name, value in read.items():
                    if not isinstance(value, (int, float)):
                        continue
                    # S437: the + 12 length from the calculator - the length in G2, read H2
                    wrap_sheet.Range(PLUS_CELLS["length"]).Value = value
                    if full:
                        excel.Calculate()
                    else:
                        wrap_sheet.Calculate()
                    plus = wrap_sheet.Range(PLUS_CELLS["plus"]).Value
                    lengths = [(name, value)]
                    if isinstance(plus, (int, float)):
                        pluses[name] = plus
                        lengths.append((f"{name} {PLUS_LABEL}", plus))
                    else:
                        pluses[name] = f"no + 12 length from {PLUS_CELLS['plus']} ({plus})"
                        print(f"REPAIR LENGTHS: {header} {name}: {PLUS_CELLS['length']} = {value} gave "
                              f"{PLUS_CELLS['plus']} = {plus!r} - no {PLUS_LABEL} wrap (S437)")
                    for key, repair in lengths:                      # S316: the length and the + 12 one
                        if repair not in seen:
                            wrap_sheet.Range(WRAP_CELLS["wheel"]).Value = middle
                            wrap_sheet.Range(WRAP_CELLS["repair"]).Value = repair        # S436: the full length
                            wrap_sheet.Range(WRAP_CELLS["zero"]).Value = 0
                            wrap_sheet.Range(WRAP_CELLS["zero2"]).Value = 0             # S436: M7 = 0
                            if full:
                                excel.Calculate()
                            else:
                                wrap_sheet.Calculate()
                            seen[repair] = (wrap_sheet.Range(WRAP_CELLS["start"]).Value,
                                            wrap_sheet.Range(WRAP_CELLS["end"]).Value)
                        wraps[key] = seen[repair]
                results[header] = dict(read, wraps=wraps, plus=pluses)
                if values.get("check"):                   # S458: the Wheel Count Calculator sheet's check
                    def wrap_check(check):
                        for cell, value in (("wc1", check["first"][0]), ("wc2", check["last"][0]),
                                            ("length1", check["first"][1]), ("length2", check["last"][1]),
                                            ("left", check["left"]), ("right", check["right"])):
                            wrap_sheet.Range(WRAP_CHECK_CELLS[cell]).Value = value
                        excel.Calculate()                 # D5 / D6 come from the other sheets
                        rows = []
                        for row in WRAP_CHECK_ROWS:
                            label, value = wrap_sheet.Range(f"C{row}").Value, wrap_sheet.Range(f"D{row}").Value
                            if label not in (None, "") or value not in (None, ""):
                                rows.append((row, label, value))
                        return {"wrap": wrap_sheet.Range(WRAP_CHECK_CELLS["wrap"]).Value,
                                "l_over": wrap_sheet.Range(WRAP_CHECK_CELLS["l_over"]).Value, "rows": rows,
                                "given": check}
                    results[header]["check"] = wrap_check(values["check"])     # its first and last wheel count
                    if "members" in values and "middle" in values:
                        # S459: a combined repair again as ONE defect - its middle (CO17) in D2 and D3, its total
                        # defect length (CO13) in D9 and D10, the same limits - all as the calculator gave them
                        whole = (values["middle"], float(values["Length"]))
                        results[header]["check_whole"] = wrap_check(dict(values["check"], first=whole, last=whole))
            return results

        def compute_combined(inputs):
            """S439: combined repairs, all by the calculator: its wheel counts smallest first in CO4:DR4 and their
            defect lengths in CO5:DR5 (the slots left over 0) -> CO13 = its total defect length, CO15 = its middle
            without the defects, CO17 = its middle with them; then CO13 in E15 like a single wheel count's
            (compute), its wraps placed at CO17."""
            results = {}
            for name, values in inputs.items():
                members = values["members"]
                if len(members) > COMBINED_SLOTS:
                    results[name] = (f"{len(members)} wheel counts - the calculator has room for {COMBINED_SLOTS} "
                                     f"({COMBINED_CELLS['wheels']})")
                    print(f"COMBINED REPAIR: {name}: {results[name]} - not worked out (S439)")
                    continue
                spare = [0] * (COMBINED_SLOTS - len(members))
                wrap_sheet.Range(COMBINED_CELLS["wheels"]).Value = (tuple([m[0] for m in members] + spare),)
                wrap_sheet.Range(COMBINED_CELLS["lengths"]).Value = (tuple([m[1] for m in members] + spare),)
                if full:
                    excel.Calculate()
                else:
                    wrap_sheet.Calculate()
                got = {key: wrap_sheet.Range(COMBINED_CELLS[key]).Value for key in ("length", "plain", "middle")}
                bad = [COMBINED_CELLS[key] for key in ("length", "middle") if not isinstance(got[key], (int, float))]
                if bad:
                    results[name] = "no number from " + " / ".join(f"{c} ({got[k]})" for k, c in
                                                                    (("length", COMBINED_CELLS["length"]),
                                                                     ("middle", COMBINED_CELLS["middle"]))
                                                                    if c in bad)
                    continue
                results[name] = dict(compute({name: dict(values, Length=got["length"], middle=got["middle"])})[name],
                                     full_length=got["length"], middle_plain=got["plain"], middle=got["middle"])
            return results

        try:
            while True:
                self.working = False                                 # S463: waiting for a job
                job = self.jobs.get()
                self.working = job is not None
                if job is not None and job[0] == "distances":        # S307: distances between table rows
                    _kind, pairs, done = job
                    if error is not None:
                        done(error)
                        continue
                    try:
                        answer = {}
                        for a, b in pairs:
                            wrap_sheet.Range(WC_CELLS["wc1"]).Value = a
                            wrap_sheet.Range(WC_CELLS["wc2"]).Value = b
                            wrap_sheet.Range(WC_CELLS["length1"]).Value = 0
                            wrap_sheet.Range(WC_CELLS["length2"]).Value = 0
                            wrap_sheet.Range(WC_CELLS["zero1"]).Value = 0             # S442: R6 = 0
                            wrap_sheet.Range(WC_CELLS["zero2"]).Value = 0             # S442: V6 = 0
                            wrap_sheet.Calculate()
                            answer[(a, b)] = (wrap_sheet.Range(WC_CELLS["distance"]).Value,
                                              wrap_sheet.Range(WC_CELLS["distance_ft"]).Value)
                        done(answer)
                    except Exception as exc:
                        done(exc)
                    continue
                if job is not None and job[0] == "pair distances":   # S433: with defect lengths
                    _kind, pairs, done = job
                    if error is not None:
                        done(error)
                        continue
                    try:
                        answer = {}
                        for pair in pairs:
                            for cell, value in zip(("wc1", "length1", "wc2", "length2"), pair):
                                wrap_sheet.Range(WC_CELLS[cell]).Value = value
                            wrap_sheet.Range(WC_CELLS["zero1"]).Value = 0             # S442: R6 = 0
                            wrap_sheet.Range(WC_CELLS["zero2"]).Value = 0             # S442: V6 = 0
                            if full:
                                excel.Calculate()
                            else:
                                wrap_sheet.Calculate()
                            answer[pair] = tuple(wrap_sheet.Range(WC_CELLS[n]).Value
                                                 for n in ("distance", "distance_ft", "apart", "apart_ft"))
                        done(answer)
                    except Exception as exc:
                        done(exc)
                    continue
                if job is not None and job[0] == "combined":         # S429: combined repairs
                    _kind, inputs, done = job
                    try:
                        done(error if error is not None else compute_combined(inputs))
                    except Exception as exc:
                        done(exc)
                    continue
                if job is not None and job[0] == "picked":           # S444: the picked repairs, with fabric
                    _kind, inputs, done = job
                    try:
                        if error is not None:
                            done(error)
                            continue
                        started_list = ", ".join(f"{n} ({v.get('fabric')})" for n, v in inputs.items())
                        print(f"PICKED JOB: started - {started_list} (S445)")
                        answer = {}
                        for n, v in inputs.items():           # S445: one at a time, each timed
                            begun = time.perf_counter()
                            got = (compute_combined if "members" in v else compute)({n: v})
                            answer.update(got)
                            out = got.get(n)
                            print(f"PICKED JOB: {n} ({v.get('fabric')} in "
                                  f"{FABRIC_BOTH}) worked out in "
                                  f"{time.perf_counter() - begun:.1f} s - "
                                  + (f"C27 = {out.get('Corrosion')!r}, C26 = {out.get('Mechanical')!r}, "
                                     f"wraps: {', '.join(sorted((out.get('wraps') or {})))}" if isinstance(out, dict)
                                     else repr(out))
                                  + (f"; check D5 = {out['check']['wrap']!r}, D6 = {out['check']['l_over']!r}, "
                                     f"{len(out['check']['rows'])} output row(s) (S458)"
                                     if isinstance(out, dict) and out.get("check") else "")
                                  + (f"; check as one defect (CO17 / CO13) D5 = {out['check_whole']['wrap']!r}, "
                                     f"D6 = {out['check_whole']['l_over']!r} (S459)"
                                     if isinstance(out, dict) and out.get("check_whole") else "") + " (S445)")
                        done(answer)
                    except Exception as exc:
                        print(f"PICKED JOB: failed - {exc!r} (S445)")
                        done(exc)
                    continue
                while job is not None and not self.jobs.empty():     # only the newest job matters
                    nxt = self.jobs.get()
                    if nxt is not None and nxt[0] in ("distances", "combined", "pair distances", "picked"):
                        self.jobs.put(nxt)              # S307: a distances job is never dropped (S429: nor combined)
                        break
                    job = nxt
                if job is None:
                    break
                inputs, done = job
                if error is not None:
                    done(error)
                    continue
                try:
                    results = compute(inputs)
                    done(results)
                except Exception as exc:
                    done(exc)
        finally:
            try:
                if book is not None:
                    book.Close(SaveChanges=False)
                if excel is not None:
                    excel.Quit()
            except Exception:
                pass
            if folder:
                shutil.rmtree(folder, ignore_errors=True)


WC_RESULT_KEYS = ("distance", "apart", "distance_ft", "apart_ft")      # S475: what the calculator gives a pair


def wc_pair_inputs(first, second):
    """S475: everything a wheel count pair puts into the calculator (R3 / V3 feet, R5 / V5 lengths; R6 / V6 are
    always 0) - the same inputs give the same outputs, so a pair is worked out once per run."""
    return (first["feet"], first["length"], second["feet"], second["length"])


def clock_pair_inputs(first, second):
    """S475: everything a clock pair puts into the Clock Calculator sheet (D7-F7, D8-F8 and the diameter in D11)."""
    return (first["hour"], first["minute"], first["width"], second["hour"], second["minute"], second["width"],
            first["diameter"])


class WheelCountExcel:
    """S273/S289: the calculator in Excel, for the wheel count distances. Started as soon as a document is
    dropped in, so Excel starts and opens a temporary copy of the calculator (unseen, its macros kept off,
    calculation manual - S288) while the documents are read; when the pairs are known, run() hands them to
    it: each pair's wheel counts go in R3 / V3 (feet), their defect lengths in R5 / V5 (inches, 0 when none
    is known), only the Wheel Count Calculator sheet is worked out, T22 / T23 / T27 / T28 are read. After
    that one job the copy is closed without saving and deleted, and Excel quits. Everything Excel does
    happens on this object's own thread (Excel's objects belong to the thread that made them).
    Needs Excel and the free 'pywin32' (pip install pywin32)."""

    def __init__(self, template):
        self.jobs = queue.Queue()
        self.started = time.perf_counter()
        self.thread = threading.Thread(target=self._run, args=(template,), daemon=True)
        self.thread.start()

    def run(self, pairs, clocks=()):
        """The pairs' results, worked out by the calculator - waits for Excel if it is still opening. S425: and
        the clock pairs' on its Clock Calculator sheet, in the same visit: {'distances', 'clock', 'clock_problem'}."""
        reply = queue.Queue()
        self.jobs.put((pairs, clocks, reply))
        answer = reply.get()
        if isinstance(answer, BaseException):
            raise answer
        return answer

    def stop(self):
        """No job after all (or the window was closed) - the copy is closed and deleted, Excel quits."""
        self.jobs.put(None)
        self.thread.join(timeout=30)

    def _run(self, template):
        folder = excel = book = sheet = None
        opened_error = None
        try:
            import pythoncom
            import win32com.client
            pythoncom.CoInitialize()
        except ImportError as exc:
            opened_error = exc
        if opened_error is None:
            try:
                folder = tempfile.mkdtemp(prefix="wc_distances_")
                copy = os.path.join(folder, os.path.basename(template))
                shutil.copy2(template, copy)
                excel = win32com.client.DispatchEx("Excel.Application")
                excel.Visible = False
                excel.DisplayAlerts = False
                excel.AutomationSecurity = 3             # its macros do not run while it is used here
                excel.ScreenUpdating = False              # S288: nothing drawn, no events
                excel.EnableEvents = False
                book = excel.Workbooks.Open(copy, UpdateLinks=0, ReadOnly=False)
                excel.Calculation = -4135                 # S288: xlCalculationManual
                sheet = book.Worksheets(WC_SHEET)
                print(f"WC DISTANCES: Excel ready with a copy of the calculator {time.perf_counter() - self.started:.1f} s "
                      f"after it was started - while the documents are read (S289)")
            except Exception as exc:
                opened_error = exc
        job = self.jobs.get()                             # wait for the pairs (or None: not needed)
        try:
            if job is not None:
                pairs, clocks, reply = job
                if opened_error is not None:
                    reply.put(opened_error)
                else:
                    try:
                        results = []
                        for first, second in pairs:
                            sheet.Range(WC_CELLS["wc1"]).Value = first["feet"]            # S276: feet
                            sheet.Range(WC_CELLS["wc2"]).Value = second["feet"]
                            sheet.Range(WC_CELLS["length1"]).Value = first["length"]      # S275: 0 when none
                            sheet.Range(WC_CELLS["length2"]).Value = second["length"]
                            sheet.Range(WC_CELLS["zero1"]).Value = 0                    # S442: R6 = 0
                            sheet.Range(WC_CELLS["zero2"]).Value = 0                    # S442: V6 = 0
                            sheet.Calculate()                     # S288: only this sheet
                            results.append({"first": first, "second": second,
                                            "distance": sheet.Range(WC_CELLS["distance"]).Value,
                                            "apart": sheet.Range(WC_CELLS["apart"]).Value,
                                            "distance_ft": sheet.Range(WC_CELLS["distance_ft"]).Value,   # S277
                                            "apart_ft": sheet.Range(WC_CELLS["apart_ft"]).Value})
                        clock_results, clock_problem = [], None
                        if clocks:                                # S425: the Clock Calculator sheet
                            try:
                                clock_sheet = book.Worksheets(CLOCK_SHEET)
                            except Exception:
                                clock_sheet, clock_problem = None, f"the calculator has no '{CLOCK_SHEET}' sheet"
                            for first, second in (clocks if clock_sheet is not None else []):
                                for side, item in (("1", first), ("2", second)):
                                    clock_sheet.Range(CLOCK_CELLS["hour" + side]).Value = item["hour"]
                                    clock_sheet.Range(CLOCK_CELLS["minute" + side]).Value = item["minute"]
                                    clock_sheet.Range(CLOCK_CELLS["width" + side]).Value = item["width"]
                                clock_sheet.Range(CLOCK_CELLS["diameter"]).Value = first["diameter"]
                                clock_sheet.Calculate()
                                warnings = [str(v).strip() for v in (clock_sheet.Range(c).Value for c in CLOCK_WARNING_CELLS)
                                            if v not in (None, "") and str(v).strip()]
                                clock_results.append({"first": first, "second": second, "warnings": warnings,
                                                      "apart": clock_sheet.Range(CLOCK_CELLS["apart"]).Value})
                        reply.put({"distances": results, "clock": clock_results, "clock_problem": clock_problem})
                    except Exception as exc:
                        reply.put(exc)
        finally:
            try:
                if book is not None:
                    book.Close(SaveChanges=False)
                if excel is not None:
                    excel.Quit()
            except Exception:
                pass
            if opened_error is None or folder is not None:
                try:
                    import pythoncom
                    pythoncom.CoUninitialize()
                except Exception:
                    pass
            if folder:
                shutil.rmtree(folder, ignore_errors=True)  # the copy is deleted when all pairs are done


def document_name_header(header):
    """S252: an end-table column header -> its anomaly ('100553.07 Final' / '100553.07 - found in' ->
    '100553.07'); '' for the columns that are not an anomaly's."""
    header = re.sub(r"\s+(Final|- found in)$", "", str(header or "")).strip()
    return "" if header in ("Looked for", "Notes", "Same", "Different") else header   # S283/S284: not an anomaly's


def calculator_diameter(value):
    """S268: the diameter as the calculator's Main!C3 writes it - inches with the inch mark ('20"'),
    any other unit after the number ('508mm'); S269: no unit when none is written ('20'); '' when there
    is no number."""
    number = verify_number(value)
    if not number:
        return ""
    unit = priority_unit_from_value(value)
    return f'{verify_short_number(float(number))}' + ('"' if unit == "in" else unit or "")


def document_name_diameter(value):
    """S252: '20 in' / '20" O.D.' -> '20in' - the number and its unit, no spaces."""
    number = verify_number(value)
    if not number:
        return ""
    unit = priority_unit_from_value(value) or "in"
    return f"{verify_short_number(float(number))}{unit}"


def document_project_number(value):
    """S256: a project number as the document name writes it - 'PN <value>': '17636' -> 'PN 17636',
    'PN17636' / 'pn 17636' -> 'PN 17636'; '' stays ''."""
    value = re.sub(r"^\s*(project\s*(number|no\.?|#|num)\s*:?|pn)\s*[:#-]?\s*", "", str(value or ""),
                   flags=re.IGNORECASE).strip()
    return f"PN {value}" if value else ""


# S347: the city and state Google Maps gives for a spot - read by Microsoft Edge (or Chrome) running with no
# window: it opens Google Maps at the coordinates, lets the page load, and hands the page back; the address
# Google shows ('12046 Santa Fe Rd, Keithville, LA 71047') is in it. Free, nothing to install.
MAPS_BROWSERS = [r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
                 r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
                 r"C:\Program Files\Google\Chrome\Application\chrome.exe",
                 r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe"]
MAPS_WAIT_MS = 15000                # how long the browser lets Google Maps load
MAPS_TIMEOUT_S = 90                 # a lookup that takes longer than this is given up
MAPS_AT_ONCE = 3                    # lookups run side by side
MAPS_ADDRESS = re.compile(r"(\d{1,6}[A-Za-z0-9 .'#&/-]{2,60}?),\s*([A-Za-z][A-Za-z .'-]{1,40}?),\s*([A-Z]{2})\s+(\d{5})")
MAPS_CITY_STATE = re.compile(r"([A-Z][A-Za-z .'-]{1,40}?),\s*([A-Z]{2})\s+(\d{5})")


def maps_browser():
    """S347: Edge (or Chrome) on this PC, or None."""
    return next((path for path in MAPS_BROWSERS if os.path.isfile(path)), None) or shutil.which("msedge")


MAPS_LIVE = {"thread": None, "loop": None, "playwright": None, "browser": None, "context": None,
             "ready": threading.Event(), "error": None}             # S357: the Edge kept open for the lookups
MAPS_LIVE_START_WAIT_S = 30           # a lookup waits at most this long for that Edge to finish opening


def maps_live_start():
    """S357: opens Edge (with no window, its own throw-away profile - an open Edge window is not touched)
    through Playwright as soon as the program starts, on its own thread, and keeps it open: every Google
    Maps lookup is then a new tab in it instead of a new Edge started for each one. Pictures, fonts and
    videos are not loaded (the address is text). Without Playwright (pip install playwright - it uses the
    Edge already on this PC, nothing else to download), each lookup starts Edge on its own, as before."""
    if MAPS_LIVE["thread"] is not None:
        return

    def run():
        import asyncio
        try:
            from playwright.async_api import async_playwright
        except ImportError:
            MAPS_LIVE["error"] = "Playwright is not installed (pip install playwright)"
            print(f"GOOGLE MAPS: {MAPS_LIVE['error']} - each lookup starts Edge on its own, as before (S357)")
            MAPS_LIVE["ready"].set()
            return
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

        async def open_edge():
            playwright = await async_playwright().start()
            browser = await playwright.chromium.launch(channel="msedge", headless=True, args=["--lang=en-US"])
            context = await browser.new_context(locale="en-US", viewport={"width": 1600, "height": 1200})

            async def leave_out(route):
                if route.request.resource_type in ("image", "font", "media"):
                    await route.abort()
                else:
                    await route.continue_()
            await context.route("**/*", leave_out)
            return playwright, browser, context

        started = time.perf_counter()
        try:
            MAPS_LIVE["playwright"], MAPS_LIVE["browser"], MAPS_LIVE["context"] = loop.run_until_complete(open_edge())
        except Exception as exc:
            MAPS_LIVE["error"] = f"{type(exc).__name__}: {exc}"
            print(f"GOOGLE MAPS: Edge could not be opened through Playwright ({MAPS_LIVE['error']}) - each lookup "
                  f"starts Edge on its own, as before (S357)")
            MAPS_LIVE["ready"].set()
            return
        MAPS_LIVE["loop"] = loop
        print(f"GOOGLE MAPS: Edge open in the background for the lookups ({time.perf_counter() - started:.1f} s "
              f"to open) (S357)")
        MAPS_LIVE["ready"].set()
        loop.run_forever()

    def close():
        loop = MAPS_LIVE["loop"]
        if loop is None:
            return
        import asyncio

        async def shut():
            await MAPS_LIVE["browser"].close()
            await MAPS_LIVE["playwright"].stop()
        try:
            asyncio.run_coroutine_threadsafe(shut(), loop).result(timeout=5)
        except Exception:
            pass

    import atexit
    atexit.register(close)
    MAPS_LIVE["thread"] = threading.Thread(target=run, name="google-maps-edge", daemon=True)
    MAPS_LIVE["thread"].start()


async def maps_live_lookup(latitude, longitude):
    """S357: one lookup in the open Edge - a new tab on the route page; its contents are checked every
    quarter second until the address is in them (at most MAPS_WAIT_MS), then the tab is closed."""
    import asyncio
    url = f"https://www.google.com/maps/dir/{latitude},{longitude}/"
    started = time.perf_counter()
    page = await MAPS_LIVE["context"].new_page()
    try:
        await page.goto(url, wait_until="domcontentloaded", timeout=MAPS_TIMEOUT_S * 1000)
        seen = None
        while True:
            # the page's contents read the same way as the old one-Edge-per-lookup way; an address is taken
            # once two checks in a row (a quarter second apart) find the same one - not while it is changing
            try:
                found = maps_address_from_page(await page.content(), started)
                if (seen is not None and found["address"] == seen["address"]) \
                        or time.perf_counter() - started > MAPS_WAIT_MS / 1000:
                    return found
                seen = found
            except RuntimeError as exc:
                if "cookie / robot" in str(exc) or time.perf_counter() - started > MAPS_WAIT_MS / 1000:
                    raise
            await asyncio.sleep(0.25)
    finally:
        await page.close()


def google_maps_address(latitude, longitude):
    """S347: the address Google Maps shows at these coordinates: {'address', 'city', 'state', 'seconds'}.
    S357: looked up in the Edge kept open (maps_live_start); without it, Edge is started for this lookup -
    with no window and a throw-away profile (an open Edge window is not touched).
    Raises RuntimeError saying why when there is no answer."""
    import subprocess
    if MAPS_LIVE["thread"] is None:
        maps_live_start()
    MAPS_LIVE["ready"].wait(MAPS_LIVE_START_WAIT_S)
    if MAPS_LIVE["loop"] is not None:
        import asyncio
        import concurrent.futures
        try:
            return asyncio.run_coroutine_threadsafe(maps_live_lookup(latitude, longitude),
                                                    MAPS_LIVE["loop"]).result(timeout=MAPS_TIMEOUT_S)
        except concurrent.futures.TimeoutError:
            raise RuntimeError(f"Google Maps did not answer within {MAPS_TIMEOUT_S} s")
        except RuntimeError:
            raise
        except Exception as exc:
            print(f"GOOGLE MAPS: the open Edge failed this lookup ({type(exc).__name__}: {exc}) - Edge is started "
                  f"for it on its own (S357)")
    browser = maps_browser()
    if not browser:
        raise RuntimeError("Edge / Chrome not found")
    url = f"https://www.google.com/maps/dir/{latitude},{longitude}/"
    started = time.perf_counter()
    with tempfile.TemporaryDirectory() as profile:
        try:
            done = subprocess.run([browser, "--headless=new", "--disable-gpu", "--no-first-run",
                                   "--no-default-browser-check", "--lang=en-US", f"--user-data-dir={profile}",
                                   f"--virtual-time-budget={MAPS_WAIT_MS}", "--window-size=1600,1200",
                                   "--dump-dom", url], capture_output=True, timeout=MAPS_TIMEOUT_S,
                                  creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        except subprocess.TimeoutExpired:
            raise RuntimeError(f"Google Maps did not answer within {MAPS_TIMEOUT_S} s")
    return maps_address_from_page(done.stdout.decode("utf-8", errors="replace"), started)


def maps_address_from_page(page, started):
    """S347/S357: the address in a Google Maps page's contents (its text and every aria-label / value /
    title): {'address', 'city', 'state', 'seconds'}. Raises RuntimeError saying why when there is none."""
    import html as html_module
    if re.search(r"Before you continue|consent\.google|unusual traffic|not a robot", page, re.IGNORECASE):
        raise RuntimeError("Google showed a cookie / robot page instead of the map")
    labels = re.findall(r'(?:aria-label|value|title)="([^"]{4,300})"', page)
    text = (html_module.unescape(re.sub(r"<[^>]+>", "\n", page)) + "\n"
            + "\n".join(html_module.unescape(label) for label in labels))
    full = MAPS_ADDRESS.search(text)
    place = MAPS_CITY_STATE.search(text)
    if not place:
        raise RuntimeError("no address in the page Google Maps gave back")
    return {"address": (", ".join(full.groups()[:3]) + f" {full.group(4)}") if full else
            f"{place.group(1).strip()}, {place.group(2)} {place.group(3)}",
            "city": place.group(1).strip(), "state": place.group(2),
            "seconds": time.perf_counter() - started}


def document_place(text):
    """S252: a place pasted from Google Maps without its plus code - 'FWXF+3QJ McFaddin, Texas' ->
    'McFaddin, Texas'."""
    return re.sub(r"^\s*[23456789CFGHJMPQRVWX]{2,8}\+[23456789CFGHJMPQRVWX]{0,3}\s*", "",
                  str(text or ""), flags=re.IGNORECASE).strip()


CALCULATOR_PREFIX = "AE_Composite_Calculator"      # S465: any Excel file whose name starts with this is the calculator
CALCULATOR_EXTENSIONS = (".xlsm", ".xlsx", ".xlsb", ".xls")
CALCULATOR_FOLDERS = [os.path.dirname(os.path.abspath(__file__)), r"C:\Users\MaximDessiatov\python"]  # next to data.py, else here
CALCULATOR_SHOWN = {"path": False}                  # S465: the one last printed - printed again only when it changes


def find_calculator():
    """S465: the calculator to use - an Excel file named 'AE_Composite_Calculator' plus anything after it
    ('AE_Composite_Calculator.xlsm', 'AE_Composite_Calculator_v2.06_072926 NO TimeWarp (2).xlsm', ...), in the folder
    next to data.py first, else C:\\Users\\MaximDessiatov\\python. Excel's own '~$' lock files are skipped. More than
    one in a folder - the most recently saved one. None when there is none."""
    path, others = None, []
    for folder in dict.fromkeys(CALCULATOR_FOLDERS):
        try:
            names = os.listdir(folder)
        except OSError:
            continue
        found = [os.path.join(folder, n) for n in names
                 if n.lower().startswith(CALCULATOR_PREFIX.lower()) and n.lower().endswith(CALCULATOR_EXTENSIONS)
                 and os.path.isfile(os.path.join(folder, n))]
        if found:
            found.sort(key=os.path.getmtime, reverse=True)
            path, others = found[0], found[1:]
            break
