US_PLACES = {"nominatim": None, "lock": threading.Lock()}   # S253: pgeocode's US place list, loaded once


US_TOWNS_URL = "https://download.geonames.org/export/dump/US.zip"     # S255: every named US place (free)
US_TOWNS_FILE = os.path.join(os.path.expanduser("~"), ".dig_reader", "us_towns.tsv")   # its towns, kept


def xlsx_cell_sort(reference):
    """S267: 'C3' -> (3, 3) - row, column - to keep a sheet's cells in Excel's order."""
    letters, digits = re.match(r"([A-Z]+)(\d+)", reference).groups()
    column = 0
    for letter in letters:
        column = column * 26 + ord(letter) - 64
    return int(digits), column


def xlsx_set_cells(path, sheet_name, values):
    """S267: write text into cells of an Excel workbook (.xlsx / .xlsm) by editing only those cells in
    its XML - the rest of the file (macros, buttons, pictures, charts, formatting, other sheets) is
    copied byte for byte, which openpyxl cannot promise for a macro workbook with controls. Each cell
    keeps its style; Excel is told to work every formula out again when the file is opened.
    values = {'C3': 'text', 'E4': 20.0, ...} - S278: numbers are written as numbers."""
    import zipfile
    from xml.sax.saxutils import escape
    with zipfile.ZipFile(path) as book:
        parts = {info.filename: (info, book.read(info.filename)) for info in book.infolist()}
    workbook = parts["xl/workbook.xml"][1].decode("utf-8")
    sheet = re.search(r'<sheet\b[^>]*\bname="' + re.escape(escape(sheet_name, {'"': "&quot;"})) + r'"[^>]*/>', workbook)
    if not sheet:
        raise ValueError(f"no sheet named '{sheet_name}'")
    rel_id = re.search(r'\br:id="([^"]+)"', sheet.group(0)).group(1)
    rels = parts["xl/_rels/workbook.xml.rels"][1].decode("utf-8")
    target = re.search(r'<Relationship\b[^>]*\bId="' + re.escape(rel_id) + r'"[^>]*/>', rels).group(0)
    target = re.search(r'\bTarget="([^"]+)"', target).group(1)
    sheet_path = target.lstrip("/") if target.startswith("/") else "xl/" + target
    xml = parts[sheet_path][1].decode("utf-8")
    for reference, text in values.items():
        row_number = xlsx_cell_sort(reference)[0]
        if isinstance(text, (int, float)) and not isinstance(text, bool):       # S278: a number stays a number
            new_cell_body = f'><v>{repr(float(text)) if isinstance(text, float) else text}</v></c>'
        else:
            new_cell_body = f't="inlineStr"><is><t xml:space="preserve">{escape(str(text))}</t></is></c>'
        row = re.search(r'<row\b[^>]*\br="' + str(row_number) + r'"[^>]*?(/>|>.*?</row>)', xml, re.S)
        if row is None:                          # no such row yet: a new one, in row order
            new_row = f'<row r="{row_number}"><c r="{reference}" {new_cell_body}</row>'
            later = next((m for m in re.finditer(r'<row\b[^>]*\br="(\d+)"', xml) if int(m.group(1)) > row_number), None)
            if later:
                xml = xml[:later.start()] + new_row + xml[later.start():]
            elif "<sheetData/>" in xml:
                xml = xml.replace("<sheetData/>", f"<sheetData>{new_row}</sheetData>")
            else:
                xml = xml.replace("</sheetData>", new_row + "</sheetData>")
            continue
        row_xml = row.group(0)
        if row_xml.endswith("/>"):
            row_xml = row_xml[:-2] + "></row>"
        cell = re.search(r'<c\b[^>]*\br="' + reference + r'"[^>]*?(/>|>.*?</c>)', row_xml, re.S)
        if cell:
            style = re.search(r'\bs="\d+"', cell.group(0))
            new_cell = f'<c r="{reference}"' + (f" {style.group(0)}" if style else "") + f' {new_cell_body}'
            row_xml = row_xml[:cell.start()] + new_cell + row_xml[cell.end():]
        else:                                    # the row is there, the cell not: put it in column order
            new_cell = f'<c r="{reference}" {new_cell_body}'
            later = next((m for m in re.finditer(r'<c\b[^>]*\br="([A-Z]+\d+)"', row_xml)
                          if xlsx_cell_sort(m.group(1))[1] > xlsx_cell_sort(reference)[1]), None)
            at = later.start() if later else row_xml.rindex("</row>")
            row_xml = row_xml[:at] + new_cell + row_xml[at:]
        xml = xml[:row.start()] + row_xml + xml[row.end():]
    parts[sheet_path] = (parts[sheet_path][0], xml.encode("utf-8"))
    if "<calcPr" in workbook:                    # formulas worked out again when Excel opens it
        workbook = re.sub(r"<calcPr\b(?![^>]*fullCalcOnLoad)", '<calcPr fullCalcOnLoad="1"', workbook, count=1)
    else:
        workbook = workbook.replace("</workbook>", '<calcPr fullCalcOnLoad="1"/></workbook>')
    parts["xl/workbook.xml"] = (parts["xl/workbook.xml"][0], workbook.encode("utf-8"))
    temporary = path + ".part"
    with zipfile.ZipFile(temporary, "w") as out:
        for info, data in parts.values():
            out.writestr(info, data, compress_type=info.compress_type)
    os.replace(temporary, path)


def us_place_key(name):
    """S255: a place name to look it up by - letters and digits only, lower case
    ('Spring Ridge' = 'Springridge' = 'spring-ridge')."""
    return re.sub(r"[^a-z0-9]", "", str(name or "").lower())


def us_towns():
    """S255: every populated place in the US (GeoNames' full US list - cities, towns, villages and
    unincorporated communities like Spring Ridge, LA, which the postal list does not have) ->
    {place key: {state abbreviations}}. Downloaded once (about 30 MB, free), only the towns kept
    in a small file in the user's folder; read from there afterwards."""
    with US_PLACES["lock"]:
        if US_PLACES.get("towns") is not None:
            return US_PLACES["towns"]
        if not os.path.exists(US_TOWNS_FILE):
            import urllib.request
            import zipfile
            print(f"US TOWNS: downloading GeoNames' US place list once ({US_TOWNS_URL}) - S255")
            os.makedirs(os.path.dirname(US_TOWNS_FILE), exist_ok=True)
            with tempfile.TemporaryDirectory() as folder:
                archive = os.path.join(folder, "US.zip")
                urllib.request.urlretrieve(US_TOWNS_URL, archive)
                kept = 0
                with zipfile.ZipFile(archive) as zipped, zipped.open("US.txt") as raw, \
                        open(US_TOWNS_FILE + ".part", "w", encoding="utf-8") as out:
                    for line in io.TextIOWrapper(raw, encoding="utf-8"):
                        parts = line.rstrip("\n").split("\t")
                        if len(parts) > 10 and parts[6] == "P" and parts[10]:     # a populated place, its state
                            out.write(f"{parts[1]}\t{parts[2]}\t{parts[10]}\n")
                            kept += 1
            os.replace(US_TOWNS_FILE + ".part", US_TOWNS_FILE)
            print(f"US TOWNS: {kept} US towns kept in {US_TOWNS_FILE} - S255")
        towns = defaultdict(set)
        with open(US_TOWNS_FILE, encoding="utf-8") as kept_file:
            for line in kept_file:
                name, ascii_name, code = (line.rstrip("\n").split("\t") + ["", "", ""])[:3]
                for key in {us_place_key(name), us_place_key(ascii_name)} - {""}:
                    towns[key].add(code)
        US_PLACES["towns"] = towns
        return towns


def us_abbreviation(state):
    """S256: the pasted state's abbreviation from 'us' - filled in even when the town is not
    confirmed in it (None when 'us' is missing or does not know the state)."""
    try:
        import us
    except ImportError:
        return None
    found = us.states.lookup(str(state or "").strip()) if str(state or "").strip() else None
    return found.abbr if found is not None else None


def us_place_check(city, state):
    """S253: is this town a US place in this state? Looked up in GeoNames' US postal-place list
    through the free 'pgeocode' package (pip install pgeocode; its data - about 2 MB - is
    downloaded the first time and kept). state = a full name ('Texas') or an abbreviation ('TX').
    S254: once confirmed, the abbreviation comes from the free 'us' package (pip install us).
    S255: a town the postal list does not have (an unincorporated community - Spring Ridge, LA)
    is looked up in GeoNames' full US place list too (us_towns); names match without spaces or
    punctuation ('Spring Ridge' = 'Springridge').
    Returns (state abbreviation or None, the line to show, whether it is confirmed)."""
    try:
        import pgeocode
    except ImportError:
        return None, "town not checked - needs: pip install pgeocode", False
    city, state = str(city or "").strip(), str(state or "").strip()
    if not city:
        return None, "", False
    try:
        with US_PLACES["lock"]:
            if US_PLACES["nominatim"] is None:
                US_PLACES["nominatim"] = pgeocode.Nominatim("us")
            nominatim = US_PLACES["nominatim"]
            places = getattr(nominatim, "_data", None)          # every postal place (one row per place name)
            if places is None:
                places = nominatim._data_frame
    except Exception as exc:
        return None, f"town not checked - US place list could not be loaded ({exc})", False
    names = {str(code): str(name) for code, name in zip(places["state_code"], places["state_name"])}
    try:                                         # S255: a state's name from 'us' when the postal list lacks it
        import us
        for known in us.states.STATES_AND_TERRITORIES:
            names.setdefault(known.abbr, known.name)
    except (ImportError, AttributeError):
        pass
    key = us_place_key(city)
    found = places[places["place_name"].astype(str).map(us_place_key) == key]
    states = {(str(r.state_code), str(r.state_name)) for r in found.itertuples()}
    wanted = state.lower()
    if not any(wanted in (code.lower(), name.lower()) for code, name in states):
        try:                                     # S255: not a postal place there - the full US place list
            states |= {(code, names.get(code, code)) for code in us_towns().get(key, set())}
        except Exception as exc:
            print(f"US TOWNS: the full US place list could not be used ({exc}) - S255")
    if not states:
        return us_abbreviation(state), f"✗ {city} is not a US place in the list", False
    match = next((name for code, name in sorted(states) if wanted and wanted in (code.lower(), name.lower())), None)
    if match:                                   # S254: the town is confirmed - 'us' gives the abbreviation
        try:
            import us
        except ImportError:
            return None, f"✓ {city} is in {match} - abbreviation needs: pip install us", True
        found_state = us.states.lookup(match)
        if found_state is None:
            return None, f"✓ {city} is in {match} - 'us' does not know this state", True
        return found_state.abbr, f"✓ {city} is in {found_state.name} ({found_state.abbr})", True
    where = ", ".join(f"{name} ({code})" for code, name in sorted(states))
    return us_abbreviation(state), f"✗ {city} is not in {state or '?'} - it is in: {where}", False


def folder_name(parts):
    """S259: a folder name - the parts joined with ' - ', empty ones left out, characters a folder
    name cannot have taken out."""
    cleaned = [re.sub(r'[\\/:*?"<>|]+', "", str(p)).strip() for p in parts]
    return " - ".join(p for p in cleaned if p)


def document_name(parts):
    """S252: the parts joined with '_' - empty ones left out, characters a file name cannot have
    taken out."""
    cleaned = [re.sub(r'[\\/:*?"<>|]+', "", str(p)).strip() for p in parts]
    return "_".join(p for p in cleaned if p)


# S332: the rows a pick can change something in - the Document names (OD, Line ID, Project Number, Defect
# name, Wheel Count / Mile Post, coordinates), the calculator's cells (Main C3 / C9 / H9 / H10, Corrosion and
# Mechanical OD / WT / Depth / Length / Width) and WC Distances (wheel counts, OD / WT / Length). Only these
# are picked; every other row shows all its different values together.
VERIFY_PICK_FIELDS = {"Outside Diameter", "Wall Thickness", "Defect name", "Depth", "Length", "Width", "Line ID",
                      "Coordinates", "Wheel Count", "Mile Post"}


def verify_row_is_used(field, name):
    """S332: is this end-table row one whose value is used (a pick there changes something)?"""
    return field in VERIFY_PICK_FIELDS or bool(re.search(VERIFY_FIRST_OTHER_ROWS[0], str(name), re.IGNORECASE))


def verify_defect_headers(names, rows):
    """S333: the table of everything headed by each anomaly's defect name instead of its Wheel Count / Mile
    Post ('100553.07' -> 'Gouge #1', '100553.07 Final' -> 'Gouge #1 Final', '... - found in' too) - only how
    it is shown: the anomaly stays its Wheel Count everywhere else (Document names, WC Distances, picks,
    Group). Its defect name is the Defect name row's value in its own (or its Final) column; a column with
    none (or one still to pick) keeps its header; the same name twice gets ' (2)', ' (3)' ..."""
    row = next((r for r in rows if str(r[0]).startswith("Defect name")), None)
    if row is None:
        return names

    def base(header):
        return re.sub(r"( Final| - found in)$", "", str(header))
    found = {}
    for c, header in enumerate(names):
        if c and header not in ("Looked for", "Notes", "Same", "Different") and not header.endswith(" - found in"):
            value = str(row[c]).split("\n")[0].strip() if c < len(row) else ""
            if value and value != "-" and value != VERIFY_PICK_PROMPT:
                found[base(header)] = value             # the last one: the main part (its Final) wins
    shown, used = {}, Counter()
    for header in dict.fromkeys(base(h) for h in names):
        if header in found:
            used[found[header]] += 1
            shown[header] = found[header] + (f" ({used[found[header]]})" if used[found[header]] > 1 else "")
    return [shown[base(h)] + h[len(base(h)):] if base(h) in shown and h not in ("Looked for", "Notes", "Same",
                                                                                 "Different") else h for h in names]


# S334: where a value was written - the Additional notes rows (and S335 any other row with different values
# that nothing uses) are split into one row per kind of place, in this order, so like information lines up
VERIFY_NOTE_KINDS = [" - Dig Packet page 1 Notes", " - Dig Packet map notes", " - Dig Packet table",
                     " - Dig Packet pages", " - 6000 form", " - 10000-35 form", " - other documents"]


VERIFY_NOTE_FILLER = {"wc", "pn", "dig", "digs", "actual", "grid", "to", "the", "of", "and", "at", "on", "in", "a",
                      "is", "was", "ft", "in."}       # S336: words that say nothing of their own in a note
VERIFY_NOTES_SAID = set()           # S336: what the terminal was told about note lines not shown again


def verify_note_tokens(text):
    """S336: the parts of a note line / a value to compare: words and numbers ('20-1', '100553.07', '#1' -> '1')."""
    return re.findall(r"[a-z]+|\d+(?:[.\-]\d+)*", str(text or "").lower())


VERIFY_ROW_FILLER = {"data", "item", "target", "joint", "with", "from", "name", "number", "type", "other"}


def verify_row_words(name):
    """S337: what a row is about - the first 5 letters of each word of 4+ letters in its name ('Install Year',
    'Installed', 'Year of Installation' all have 'insta')."""
    return {w[:5] for w in re.findall(r"[a-z]{4,}", str(name).lower()) if w not in VERIFY_ROW_FILLER}


def verify_same_information(value):
    """S337: a value written so two that say the same compare equal ('324.270 ft' = '324.27 ft'); None for a
    value too short to be information of its own ('No', '1', '0.72', 'E', 'FW' - many rows say those)."""
    tokens = verify_note_tokens(value)
    informative = any(len(t) >= 3 and t.isalpha() for t in tokens) or \
        any(len(re.sub(r"\D", "", t).lstrip("0")) >= 3 for t in tokens if t[0].isdigit())
    if not informative:
        return None
    return tuple(str(float(t)) if re.fullmatch(r"\d+(\.\d+)?", t) else t for t in tokens)


def verify_note_kind(source):
    """S334: which kind of place a value was written in (its 'found in' place, its [status] left out)."""
    source = re.sub(r"\s*\[[^\]]*\]\s*$", "", str(source))
    if " - 24-hour report " in source:                   # S419
        return " - 24-hour field report"
    if source.startswith("6000 "):
        return " - 6000 form"
    if "page 1 Notes" in source:
        return " - Dig Packet page 1 Notes"
    if "map page" in source:
        return " - Dig Packet map notes"
    if "Table page" in source:
        return " - Dig Packet table"
    if re.search(r" - cell [A-Z]+\d+| - file name - | - photo \(|\(Remarks\)", source):
        return " - 10000-35 form"
    if re.search(r" - page \d+", source):
        return " - Dig Packet pages"
    return " - other documents"


def verify_packet_rows(columns, packets, found, names, keys, state, agreed_ids):
    """S341: a Dig Packet's notes that are about the whole packet ('NOTE: 2 DIGS IN THIS PACKET', its title
    block) are not repeated in each dig's column: they are rows of their own, named for the packet by its
    digs' defect names ('Dig Packet for Gouge #1 and Gouge #2 - map notes'), shown once - in its first dig's
    column. A note whose every part is already in the digs' columns (its Line ID, location, project) is not
    shown. Adds to found / names / keys; returns {packet name: {row key: its short name}} (its group)."""
    groups = {}
    for owner, packet in packets.items():
        digs = packet.get("digs") or []
        if not digs or not packet["notes"]:
            continue
        homes = []                                      # (dig's place in the order, column)
        for j, (_header, column_blocks) in enumerate(columns):
            for block in column_blocks:
                wheel = (block.get("ident") or {}).get("wc")
                if block.get("owner") == owner and not block.get("packet") and wheel in digs:
                    homes.append((digs.index(wheel), j))
                    break
        if not homes:
            continue
        homes.sort()

        def defect(j):
            values = (found.get("Defect name", [{}] * len(columns))[j].get("") or {}).get("values") or []
            return values[0][0] if len(values) == 1 else columns[j][0]
        named = [defect(j) for _n, j in homes]
        packet_name = "Dig Packet for " + (" and ".join(named) if len(named) < 3
                                           else ", ".join(named[:-1]) + " and " + named[-1])
        known = set()
        for _n, j in homes:
            for field, cells_of_columns in found.items():
                if field != PRIORITY_NOTES:
                    for cell in cells_of_columns[j].values():
                        for value, _unit, _where in cell["values"]:
                            known |= set(verify_note_tokens(value))
        cells = verify_column_rows(PRIORITY_NOTES, [dict(packet, packet=False)], {}, set(), state, agreed_ids)
        first = homes[0][1]
        for part, cell in cells.items():
            texts = [t for t in cell.get("texts") or [] if not set(verify_note_tokens(t)) <= known | VERIFY_NOTE_FILLER]
            if not texts:
                continue
            short = str(part).replace(" - Dig Packet ", " - ").strip(" -") or "notes"
            key = priority_other_key(f"{packet_name} - {short}")
            names[key] = f"{packet_name} - {short}"
            found[key] = [{} for _ in columns]
            found[key][first] = {"": dict(cell, values=[("\n".join(texts), "", "")], texts=texts)}
            keys.append(key)
            groups.setdefault(packet_name, {})[key] = short
    return groups


ROUTE_STOPS_PER_LINK = 10           # S346: a Google Maps directions link holds a start + 9 stops


def verify_route_links(headers, by_label, columns):
    """S346: Google Maps directions links through every anomaly with coordinates, in wheel count order (the
    way along the pipe), the same spot once: [(link, [the anomalies it goes through])]. More than
    ROUTE_STOPS_PER_LINK spots -> several links, each starting where the one before ended."""
    def wheel(header):
        try:
            return (0, float(header))
        except ValueError:
            return (1, 0.0)
    points = []
    for header in sorted(columns, key=wheel):
        def cell(label):
            return end_table_value(headers, by_label, header, label)
        latitude = verify_number(cell("Coordinates - Latitude") or cell("Coordinates"))
        longitude = verify_number(cell("Coordinates - Longitude"))
        if latitude and longitude and all(p[0] != (latitude, longitude) for p in points):
            points.append(((latitude, longitude), header))
    if len(points) < 2:
        return []
    links, start = [], 0
    while True:
        part = points[start:start + ROUTE_STOPS_PER_LINK]
        links.append(("https://www.google.com/maps/dir/" + "/".join(f"{lat},{lon}" for (lat, lon), _h in part) + "/",
                      [h for _p, h in part]))
        if start + ROUTE_STOPS_PER_LINK >= len(points):
            return links
        start += ROUTE_STOPS_PER_LINK - 1          # the next link starts at this one's last stop


def verify_end_table_blocks(blocks):
    """The blocks as the end table uses them: S193 notes naming their own Wheel Count split off, S209
    unnamed values placed."""
    return verify_place_unnamed(verify_split_noted_anomalies(blocks))


def verify_column_files(blocks, header, label_files):
    """S262: the files dropped in that an anomaly column's values came from - the documents its
    'found in' places name ('6000 6000-10-…', '100553.07'), as files."""
    blocks = verify_end_table_blocks(blocks)
    column = next((column_blocks for name, column_blocks in verify_table_columns(blocks) if name == header), [])
    named = set()
    for block in column:
        for entries in list(block["fields"].values()) + [block["notes"]]:
            for entry in entries:
                named.add(re.sub(r"^6000\s+", "", verify_document_of(entry["source"])))
        named.add(str(block.get("owner") or ""))
    return [path for label, path in label_files.items() if label in named]


def verify_focus_columns(blocks, columns):
    """S349: the anomaly columns the documents are about - the ones that get a Document name. An anomaly is
    kept when a document is about it: a Dig Packet dig (page 1), a 6000 form, a 10000-35 form, a quote
    request, or a Dig Packet table row marked x = defect - or when two or more documents name it outside a
    Dig Packet's table and map notes. A girth weld / AGM / other reference listed only in a packet's table
    or map notes (even in several packets) is extra and is left out. Returns ([kept], {left out: why})."""
    by_header = dict(verify_table_columns(verify_end_table_blocks(blocks)))
    kept, left = [], {}
    for header in columns:
        reasons, documents, seen_in = set(), set(), set()
        for block in by_header.get(header, []):
            title = str(block.get("title") or "")
            if block.get("wt35"):
                reasons.add("10000-35 form")
            if block.get("dig") and not block.get("packet") and not block.get("end_table_only"):
                reasons.add("Dig Packet dig")
            if "x = defect" in title:
                reasons.add("Dig Packet table row marked x = defect")
            if title.endswith(" - quote request"):
                reasons.add("quote request")
            if block.get("report24"):                                    # S419
                reasons.add("24-hour field report")
            for entries in list(block["fields"].values()) + [block["notes"]]:
                for entry in entries:
                    source = str(entry.get("source") or "")
                    kind = verify_note_kind(source)
                    if kind == " - 6000 form":
                        reasons.add("6000 form")
                    if kind in (" - Dig Packet table", " - Dig Packet map notes"):
                        seen_in.add(kind.strip(" -"))
                    else:
                        documents.add(verify_document_of(source))
        if len(documents) >= 2:
            reasons.add(f"named in {len(documents)} documents")
        if reasons:
            kept.append(header)
        else:
            left[header] = "only in " + (" and ".join(sorted(seen_in)) if seen_in else "one document")
    if not kept:                                   # nothing looks like the focus - every anomaly stays
        return list(columns), {}
    return kept, left


def verify_ready_headers(blocks):
    """S236: the end table's anomaly columns (by header) whose values all come from documents that
    have been read - none from a Dig Packet still being read (its blocks carry a reading stage)."""
    blocks = verify_end_table_blocks(blocks)
    return {header for header, column_blocks in verify_table_columns(blocks)
            if all(block.get("status") is None for block in column_blocks)}


def verify_summary_table(blocks, state, agreed, finals):
    """S183/S184/S187/S188: the table shown when every value has been checked. ONE value
    per cell: a row per thing looked for (split where it has to be: latitude / longitude,
    a % and an inch depth), a column per anomaly (verify_table_columns - not per document:
    the same Wheel Count / Mile Post / coordinates in several documents is one column).
    Values that say the same are one value (the automatic-confirmation rules); the one
    shown first is the PDF-text one when there is one, else a typed / confirmed one.
    S188: when an anomaly has two (or more) different values for one thing, its column
    is doubled - the same header twice, every other value in both - and the cells of the
    rows that differ are yellow. S190: each of those columns has a 'found in' column to
    its right, saying - in yellow, on the rows that differ - where that value was found.
    Every value carries its unit (S208: no 'Units' column), 'Notes' the values marked X and
    values not checked (S205: no '?' column - the 'found in' columns say it).
    S191: every differing value has a ✓ (picks: {(row, column): (header, row name,
    value)}); the value picked - finals {(header, row name): value} - turns green, and a
    doubled anomaly gets a '<header> Final' column after its columns: the one value of
    each row, the picked one on the rows that differ ('pick one with ✓', in yellow,
    until one is). Returns (headers, rows, cell colours, picks).
    Returns (headers, rows, yellow cells)."""
    agreed_ids = {item["id"]: item["auto"][0] if text is None else "same as the PDF text"      # S375 / S380
                  if text.get("from_text") else "same as a typed-checked value"                  # S382
                  for item, text in agreed}
    blocks = verify_end_table_blocks(blocks)        # S193 notes split off, S209 unnamed placed
    packets = {block.get("owner"): block for block in blocks if block.get("packet")}
    owners_with_digs = {b.get("owner") for b in blocks if b.get("ident") and b.get("owner") and not b.get("packet")}
    columns = verify_table_columns(blocks)
    # S202: under the priority rows, everything else found - a row per name, in the order found
    names = {}
    for block in blocks:
        for key, name in (block.get("other_labels") or {}).items():
            names.setdefault(key, name)
    for inspection_key, crew_field in VERIFY_INSPECTION_ROWS.items():  # S329/S331: the inspection data's values
        if any(verify_column_entries(inspection_key, column_blocks, packets, owners_with_digs)
               for _header, column_blocks in columns):
            names.setdefault(inspection_key, VERIFY_CREW_FIELDS[crew_field])
    keys = PRIORITY_FIELDS + [PRIORITY_NOTES] + list(names)
    # S250: per row, the unit most of its values are written in - every cell of the row uses it
    preferred = {}
    for field in keys:
        if field in VERIFY_NUMBER_FIELDS and field != "Coordinates":
            units = Counter(u for _header, column_blocks in columns
                            for _b, e in verify_column_entries(field, column_blocks, packets, owners_with_digs)
                            for u in [verify_unit_key(e, priority_entry_text(e))] if u and u != "%")
            preferred[field] = units.most_common(1)[0][0] if units else None
    found = {field: [verify_column_rows(field, column_blocks, packets, owners_with_digs, state, agreed_ids,
                                        preferred=preferred.get(field))
                     for _header, column_blocks in columns]
             for field in keys}
    packet_groups = verify_packet_rows(columns, packets, found, names, keys, state, agreed_ids)     # S341
    # S336: a note line whose every part is already in the column's other rows (the 10000-35 Remarks 'WC: 100553.07
    # PN 17748 SHC 20-1 Digs Red River to Sharon Actual Gouge Grid #1' = its Wheel Count, Project Number, Line
    # ID, Route and Defect name) is not shown again; a line with anything new in it stays as it is
    for j in range(len(columns)):
        known = set()
        for other_field, cells_of_columns in found.items():
            if other_field != PRIORITY_NOTES:
                for cell in cells_of_columns[j].values():
                    for value, _unit, _where in cell["values"]:
                        known |= set(verify_note_tokens(value))
        for part, cell in list(found[PRIORITY_NOTES][j].items()):
            # S338: a whole note at a time - a note with anything new in it is shown whole ('AGM 13 / 20'
            # Upstream of / Santa Fe Road' stays together even though 'AGM 13' and 'Santa Fe Road' are known)
            texts = cell.get("texts") or [cell["values"][0][0]]
            kept = [t for t in texts if not set(verify_note_tokens(t)) <= known | VERIFY_NOTE_FILLER]
            if len(kept) != len(texts):
                said = (columns[j][0], part, tuple(texts))
                if said not in VERIFY_NOTES_SAID:
                    VERIFY_NOTES_SAID.add(said)
                    print(f"END TABLE: {columns[j][0]} - Additional notes{part}: "
                          f"{len(texts) - len(kept)} note(s) not shown again - every part of them is "
                          f"in the column's other rows (S336/S338)")
            if kept:
                found[PRIORITY_NOTES][j][part] = dict(cell, values=[("\n".join(kept), "", "")])
            else:
                del found[PRIORITY_NOTES][j][part]
    # S332: a row nothing uses (not a document name, calculator cell or WC Distances value) is never a pick.
    # S335: when its values differ, the row is split - one row per kind of place they were written in
    # ('Inspection data depth - Dig Packet pages' 34.0%, '... - Dig Packet table' 0.085 in), in every column,
    # so they line up; two values still left in one cell (the same kind of place) go side by side with
    # where each was found in Notes
    for field, cells_of_columns in found.items():
        if field == PRIORITY_NOTES or verify_row_is_used(field, names.get(field, field)):
            continue
        if any(len(cell["values"]) > 1 for cells in cells_of_columns for cell in cells.values()):
            for j, cells in enumerate(cells_of_columns):
                split = {}
                for part, cell in cells.items():
                    for value in cell["values"]:
                        kind = verify_note_kind(next((w for w in str(value[2]).splitlines() if w), ""))
                        key = f"{part or ''}{kind}"           # (a measurement row's part may be None)
                        home = split.get(key)
                        if home is None:
                            home = split[key] = {"values": [], "notes": [] if split else cell["notes"],
                                                         "unchecked": [] if split else cell["unchecked"]}
                        home["values"].append(value)
                cells_of_columns[j] = dict(sorted(split.items(), key=lambda item: next(
                    (n for n, kind in enumerate(VERIFY_NOTE_KINDS) if item[0].endswith(kind)), len(VERIFY_NOTE_KINDS))))
        for cells in cells_of_columns:
            for cell in cells.values():
                if len(cell["values"]) > 1:
                    shown = [verify_with_unit(value, unit).split("\n")[0] for value, unit, _where in cell["values"]]
                    cell["notes"] = cell["notes"] + [f"{text} - from {'; '.join(w for w in where.splitlines() if w)}"
                                                     for text, (_v, _u, where) in zip(shown, cell["values"])]
                    cell["values"] = [(" | ".join(shown), "", "")]
    # S337: no information twice in a column - a row saying the same as an earlier row of the same kind
    # ('Installed' / 'Year of Installation' 1950 after 'Install Year' 1950; 'Gouge #1 - 6000 form date' after
    # 'Gouge #1 - Date') is left empty in that column; a row empty in every column is not shown
    order = [(field, part) for field in keys for part in dict.fromkeys(p for cells in found[field] for p in cells)]
    for j in range(len(columns)):
        seen = []                                       # (words of its row name, its value, name) of the rows kept
        for field, part in order:
            cell = found[field][j].get(part)
            if field == PRIORITY_NOTES or cell is None or len(cell["values"]) != 1:
                continue
            value = verify_with_unit(*cell["values"][0][:2]).split("\n")[0]
            row_name = f"{names.get(field) or field}{part if isinstance(part, str) else ''}"
            words, numbered = verify_row_words(row_name), re.sub(r"\d+", "#", row_name)
            same = verify_same_information(value)
            if same is None:
                continue
            # rows that differ only by a number ('Grid row 6' / 'Grid row 9') are places, not the same thing
            earlier = next((name for name, kept, place in seen if kept == same and name & words and place != numbered),
                           None)
            if earlier is not None and field not in VERIFY_PICK_FIELDS:
                del found[field][j][part]
                said = (columns[j][0], field, part, value)
                if said not in VERIFY_NOTES_SAID:
                    VERIFY_NOTES_SAID.add(said)
                    print(f"END TABLE: {columns[j][0]} - {names.get(field) or field}{part if isinstance(part, str) else ''}"
                          f" '{value}' left empty - an earlier row of the same kind says the same (S337)")
                continue
            seen.append((words, same, numbered))
    widths = [max([len(cell["values"]) for field in found for cell in found[field][j].values()] or [1])
              for j in range(len(columns))]
    # S218: Wheel Count columns that need comparing (doubled) first, in number order; then the
    # Wheel Count columns that do not, in number order; then the rest as they were
    def place(j):
        header = columns[j][0]
        try:
            number = float(header)
        except ValueError:
            return (2, j)
        return (0 if widths[j] > 1 else 1, number)

    ordered = sorted(range(len(columns)), key=place)
    columns, widths = [columns[j] for j in ordered], [widths[j] for j in ordered]
    found = {field: [cells[j] for j in ordered] for field, cells in found.items()}
    # S224: the compared versions (with 'found in') of each doubled column come first; then one
    # cell per anomaly - its Final when doubled, else its value - the Wheel Count ones in number
    # order (a Final among them in its place), then the rest as they were
    compare_order = [j for j in range(len(columns)) if widths[j] > 1]
    def wheel(j):
        try:
            return float(columns[j][0])
        except ValueError:
            return None

    main_order = sorted(range(len(columns)), key=lambda j: (wheel(j) is None, wheel(j) if wheel(j) is not None else j))
    # S210: everything else found, grouped by kind (pipe, pressure, anomaly, location, regulatory,
    # survey, other) - each group under its own heading row, its rows in name order
    others = [key for key in names if any(found[key])]
    # S220/S221/S222: the first rows under EVERYTHING ELSE FOUND, before the groups, in this
    # order: project number, MAOP, operating stress, safety factor
    first = [key for pattern in VERIFY_FIRST_OTHER_ROWS for key in others
             if re.search(pattern, names[key], re.IGNORECASE)]
    inspection_first = [key for key in VERIFY_INSPECTION_ROWS if key in others]   # S329/S331: first of all
    first = inspection_first + [key for key in first if key not in inspection_first]
    # S279: the documents' questions ('...?') and 'describe / explain ...' prompts - their own rows,
    # right before the Pipe group
    # S280: and every row answered yes / no
    asked = [key for key in others if key not in first and (
        re.search(VERIFY_QUESTION, names[key], re.IGNORECASE)
        or any(re.fullmatch(r"\s*(yes|no|y|n)\s*[.!]?\s*", priority_entry_text(e) or "", re.IGNORECASE)
               for block in blocks for e in block["fields"].get(key, [])))]
    # S330: a 10000-35 form's own rows ('Gouge #1 - Grid row 2') - a group per anomaly, after the others
    tagged = {}
    for block in blocks:
        tag = block.get("wt35_tag")
        for key, name in (block.get("other_labels") or {}).items():
            if tag and name.startswith(f"{tag} - ") and key in others and key not in first and key not in asked:
                tagged.setdefault(tag, {})[key] = name[len(tag) + 3:]

    def natural(text):                                  # 'Grid row 2' before 'Grid row 12'
        return [int(part) if part.isdigit() else part.lower() for part in re.split(r"(\d+)", text)]
    for packet_name, rows_of in packet_groups.items():  # S341: a Dig Packet's own rows - a group of their own
        tagged[packet_name] = {key: label for key, label in rows_of.items() if key in others}
    in_tagged = {key for rows_of in tagged.values() for key in rows_of}
    grouped = sorted((key for key in others if key not in first and key not in asked and key not in in_tagged),
                     key=lambda key: (verify_other_group(names[key], [
        priority_entry_text(e) for block in blocks for e in block["fields"].get(key, [])]), names[key].lower()))
    sequence = [(None, field) for field in PRIORITY_FIELDS + [PRIORITY_NOTES]]
    if others:
        sequence.append(("EVERYTHING ELSE FOUND", None))
    sequence += [(None, key) for key in first]
    if asked:                                           # S279
        sequence.append(("   Questions and descriptions", None))
        sequence += [(None, key) for key in asked]
    group = None
    for key in grouped:
        kind = verify_other_group(names[key], [priority_entry_text(e) for block in blocks
                                               for e in block["fields"].get(key, [])])
        if kind != group:
            group = kind
            sequence.append((f"   {VERIFY_OTHER_GROUPS[kind][0]}", None))
        sequence.append((None, key))
    for tag in sorted(tagged, key=natural):             # S330: 'Gouge #1', 'Gouge #2' ... 'WT readings'
        sequence.append((f"   {tag}", None))
        sequence += [(None, key) for key in sorted(tagged[tag], key=lambda k: natural(tagged[tag][k]))]
    # S230: a second 'Looked for' column between the compared versions and the anomaly columns
    middle = VERIFY_TABLE_LEAD + sum(2 * widths[j] for j in compare_order) if compare_order else None
    width_all = (VERIFY_TABLE_LEAD + sum(2 * w + 1 if w > 1 else 1 for w in widths) + 1 + (1 if compare_order else 0)
                 + 2)                                    # S283 / S284: the Same and Different columns
    rows, colours, picks = [], {}, {}
    for heading, field in sequence:
        if heading:                                     # S202 / S210: a heading row
            colours.update(((len(rows), c), TABLE_HEADER_ROW_COLOUR if heading == "EVERYTHING ELSE FOUND"
                            else TABLE_GROUP_ROW_COLOUR) for c in range(width_all))
            row = [heading] + [""] * (width_all - 1)
            if middle is not None:
                row[middle] = heading
            rows.append(row)
            continue
        parts = list(dict.fromkeys(part for cells in found[field] for part in cells))
        if field == PRIORITY_NOTES:                     # S334: the kinds of notes in a fixed order
            parts.sort(key=lambda part: VERIFY_NOTE_KINDS.index(part) if part in VERIFY_NOTE_KINDS else len(VERIFY_NOTE_KINDS))
        for part in parts:
            units = [cells[part]["values"][0][1] for cells in found[field] if part in cells and cells[part]["values"][0][1]]
            unit = units[0] if units else ""
            label = names.get(field) or field + (part if field in ("Coordinates", PRIORITY_NOTES) else
                                                  f" ({unit})" if field in VERIFY_NUMBER_FIELDS and len(parts) > 1
                                                  and unit else "")
            kind = next((k for k in VERIFY_NOTE_KINDS if str(part).endswith(k)), None)
            if kind and field not in ("Coordinates", PRIORITY_NOTES):
                label += kind                           # S335: a split row says where its values were written
            compare, main, notes = {}, {}, []           # S224: per column - its compared versions, its main cell
            for j, ((header, _blocks), cells, width) in enumerate(zip(columns, found[field], widths)):
                cell = cells.get(part)
                final = finals.get((header, label))
                if cell is None:
                    compare[j] = [("-", None, None)] * (2 * width) if width > 1 else []
                    main[j] = ("-", None, None)
                    continue
                values = cell["values"]
                compare[j] = []
                for n in range(width if width > 1 else 0):
                    value, value_unit, where = values[n] if n < len(values) else values[0]
                    text = verify_with_unit(value, value_unit)                      # S208: its unit with it
                    differs = len(values) > 1
                    colour = ((TABLE_CHOSEN_COLOUR if final == text.split("\n")[0].strip() else TABLE_CHANGED_COLOUR)
                              if differs else None)                                   # S263: Final = the value only
                    compare[j] += [(text, colour, (header, label, text) if differs and n < len(values) else None),
                                   (where if differs else "", colour, None)]     # S190: where it was found
                if width > 1 and len(values) > 1:       # S191: '<header> Final' - the value to use
                    main[j] = (final or VERIFY_PICK_PROMPT, None if final else TABLE_CHANGED_COLOUR, None)
                else:
                    main[j] = (verify_with_unit(values[0][0], values[0][1]), None, None)
                notes += [f"{header}: {note}" for note in cell["notes"]]
                notes += [f"{header}: not checked - {m['entry']['source']}" for m in cell["unchecked"]]
            # S281/S282: any row whose every anomaly column holds exactly the same value - that value in its name
            answers = [main[j][0] for j in main_order if not columns[j][0].startswith("Info ")]
            same = ""                                   # S283: also in the Same column at the end
            if answers and "-" not in answers and VERIFY_PICK_PROMPT not in answers and len(set(answers)) == 1:
                label = f"{label} ({answers[0].splitlines()[0]})"
                same = answers[0]
            # S284: how many different values the anomaly columns hold (a doubled column's versions counted
            # until one is picked); S285: only when the row is not Same - one or the other - and a column
            # with nothing found ('-') counts as one more different value next to the ones found
            seen = set()
            for j in main_order:
                if columns[j][0].startswith("Info "):
                    continue
                if main[j][0] == VERIFY_PICK_PROMPT:
                    seen |= {text.splitlines()[0] for text, _c, pick in compare[j] if pick}
                else:
                    seen.add(main[j][0].splitlines()[0])
            found_values = seen - {"-"}
            different = str(len(seen)) if found_values and not same else ""
            line = []
            for j in compare_order:
                for text, colour, pick in compare[j]:
                    if colour:
                        colours[(len(rows), VERIFY_TABLE_LEAD + len(line))] = colour
                    if pick:
                        picks[(len(rows), VERIFY_TABLE_LEAD + len(line))] = pick
                    line.append(text)
            if compare_order:
                line.append(label)                      # S230: the row's name again, before the anomalies
            for j in main_order:
                text, colour, _pick = main[j]
                if colour:
                    colours[(len(rows), VERIFY_TABLE_LEAD + len(line))] = colour
                line.append(text)
            rows.append([label] + line + ["\n".join(notes) or "-", same, different])
    headers = ["Looked for"]               # S208: no Units column - each value has its unit; S209: no All Rows
    for j in compare_order:
        headers += [columns[j][0], f"{columns[j][0]} - found in"] * widths[j]
    headers += ["Looked for"] if compare_order else []
    headers += [f"{columns[j][0]} Final" if widths[j] > 1 else columns[j][0] for j in main_order]
    return headers + ["Notes", "Same", "Different"], rows, colours, picks    # S205; S283 Same; S284 Different


def verify_typed_ok(entry):
    """S382: a value read from a picture that passed the typed-text check (S375 table / S379 photo font) as
    it reads now - known, like PDF text, when other reads are compared with it. Never handwriting."""
    typed = entry.get("typed")
    return bool(typed and typed["ok"] and not entry.get("handwriting")
                and typed["value"] == priority_entry_text(entry).replace(" ", ""))


VERIFY_PIPE_FIELDS = {"Outside Diameter", "Wall Thickness", "Pipe Grade", "Yield Strength", "SMYS", "Line ID"}   # S377
VERIFY_LINE_LEFTOVER = re.compile(r"[\s@*.,:;()\-–]+")      # S380: what may be left of a line besides its values


def verify_items_from_blocks(blocks, done_paths):
    """The values to verify, in order: field by field (the priority list's order), each
    place it was found. Only read documents; a value without a known place in its PDF
    is counted, not listed. S179: only values read from a picture (handwriting, the
    table pictures, map notes read by OCR) - a value read from the PDF's own text is
    exact and is counted, not listed. S180: a value read from a picture that is the same
    as its section's text value is confirmed without being listed; one that differs is
    listed as 'differs' with the text value(s) it differs from. S375/S376: a printed table value that passes the
    typed-text check is confirmed without being listed too - also when it differs from another document's
    value (the end table shows both). S382: values that passed the typed-text check count as known too, like
    PDF text (and a table row's Depth [%] when it has the depth in inches). S377: a pipe value (OD, WT, grade,
    yield / SMYS, Line ID) is compared - S390: also with every document on the same pipeline (same Line ID) -
    with the PDF text of every document of the same anomaly, not only its own. S380: handwriting the PDF
    text says the same of is confirmed too (it was always listed - S198); a page-1 Notes line whose every
    value is confirmed and that says nothing else (its letter, '@') is confirmed with them.
    Returns (items, unplaced, from text, confirmed [(item, text entry - None: item['auto'] = (how, why))])."""
    items, unplaced, exact, agreed = [], 0, 0, []
    blocks = [block for block in blocks if not block.get("end_table_only")]          # S201: the end table's only
    packets = {block.get("owner"): block for block in blocks if block.get("packet")}
    column_of = {id(member): members for _header, members in verify_table_columns(blocks) for member in members}

    def known(entry):                                  # S382: PDF text, or a typed value that passed its check
        return entry.get("from_text") or verify_typed_ok(entry)

    # S390: the pipeline each block is on - its Line ID(s) known (with its packet's); a pipe value is the same
    # all along one pipeline, so it is compared with every document on the same pipeline too
    def lines_of(block):
        holders = [block, packets.get(block.get("owner"))]
        return [priority_entry_text(e) for holder in holders if holder is not None
                for e in holder["fields"]["Line ID"] if known(e)]

    pipeline_lines = {id(block): lines_of(block) for block in blocks}

    pipeline_pairs = {}

    def same_pipeline(a, b):
        key = (id(a), id(b)) if id(a) < id(b) else (id(b), id(a))
        if key not in pipeline_pairs:
            pipeline_pairs[key] = any(verify_same("Line ID", {}, x, {}, y)
                                      for x in pipeline_lines[id(a)] for y in pipeline_lines[id(b)])
        return pipeline_pairs[key]

    for field in PRIORITY_FIELDS + [PRIORITY_NOTES]:
        for block in blocks:
            entries = block["notes"] if field == PRIORITY_NOTES else block["fields"][field]
            pool = [e for e in entries if known(e)]
            packet = packets.get(block.get("owner"))
            if field != PRIORITY_NOTES and packet is not None and packet is not block:
                pool += [e for e in packet["fields"][field] if known(e)]
            pool += [e for name, e in block.get("known") or [] if name == field and known(e)]     # S382
            if field in VERIFY_PIPE_FIELDS:            # S377: every document of the same anomaly (and its packet)
                # S390: and every document on the same pipeline (the same Line ID)
                on_line = [other for other in blocks if other is not block and same_pipeline(block, other)]
                for other in column_of.get(id(block), []) + on_line:
                    for holder in (other, packets.get(other.get("owner"))):
                        if holder is not None and holder is not block and holder is not packet:
                            pool += [e for e in holder["fields"][field] if known(e) and e not in pool]
            for entry in entries:
                where = entry.get("where")
                if entry.get("from_text"):
                    exact += 1 if block.get("status") is None else 0
                    continue
                if not where or where["path"] not in done_paths:
                    unplaced += 1 if where is None and block.get("status") is None else 0
                    continue
                item = {"id": verify_item_id(field, entry), "field": field, "followers": [],
                        "block": block["title"], "entry": entry, "kind": "check", "texts": []}
                read = priority_entry_text(entry)
                verdicts = [(text_entry, verify_same(field, entry, read, text_entry, priority_entry_text(text_entry)))
                            for text_entry in pool if text_entry is not entry]
                same = next((text_entry for text_entry, verdict in verdicts if verdict), None)
                written = next((text_entry for text_entry, verdict in verdicts                   # S248
                                if verdict and verify_written_in(read, priority_entry_text(text_entry))), None)
                if written is not None:                  # S248: written exactly as the PDF text has it - confirmed
                    agreed.append((item, written))
                    continue
                if same is not None:
                    agreed.append((item, same))
                    continue
                differs = [text_entry for text_entry, verdict in verdicts if verdict is False]
                typed = entry.get("typed")              # S375: one more thing to compare with first
                if typed and typed["value"] == read.replace(" ", "") and not entry.get("handwriting"):
                    said = (item["id"], typed["value"], typed["ok"], bool(differs))
                    if said not in TYPED_SAID:
                        TYPED_SAID.add(said)
                        # S376: read exactly as printed - confirmed even when another document says something
                        # else; that difference still shows in the end table, both values side by side
                        print(f"TYPED-TEXT CHECK: {field} | {entry['source']}: '{read}' - "
                              + (f"{typed['why']} -> confirmed, not on the Verify tab"
                                 + (" (it differs from " + "; ".join(f"'{priority_entry_text(t)}' - {t['source']}"
                                                                      for t in differs)
                                    + " - the end table shows both - S376)" if differs else "")
                                 if typed["ok"] else f"{typed['why']} -> on the Verify tab") + " (S375)")
                    if typed["ok"]:
                        item["auto"] = ("typed-text check", typed["why"])
                        agreed.append((item, None))
                        continue
                if differs:
                    item.update(kind="differs", texts=differs)
                elif field != PRIORITY_NOTES:           # S181: shown next to it, to compare by eye (not notes)
                    # S186: only text values of the same kind - the same axis, the same kind of unit
                    # (a % is never shown next to mils / inches: different measurements)
                    axis = verify_axis(entry, read) if field == "Coordinates" else None
                    family = verify_unit_family(entry, read)
                    item["texts"] = [text_entry for text_entry in pool
                                     if (not axis or verify_axis(text_entry, priority_entry_text(text_entry)) in (axis, None))
                                     and (family is None or verify_unit_family(text_entry, priority_entry_text(text_entry))
                                          in (family, None))]
                items.append(item)
    # S380: a Notes line whose values are all confirmed (none of them left to check) and that says nothing else
    listed_lines = Counter(item["entry"].get("line") for item in items if item["entry"].get("line"))
    for item in [i for i in items if i["field"] == PRIORITY_NOTES and i["entry"].get("line")]:
        line = item["entry"]["line"]
        parts = [part for part, _text in agreed if part["entry"].get("line") == line]
        if listed_lines[line] > 1 or not parts:
            continue                                   # a value of it still to check, or nothing confirmed in it
        rest = priority_entry_text(item["entry"])
        for part in parts:
            value = priority_entry_text(part["entry"])
            rest = re.sub(re.escape(value), " ", rest, count=1, flags=re.IGNORECASE)
        rest = VERIFY_LINE_LEFTOVER.sub("", re.sub(r"^\s*\(?[A-Z]\)", "", rest.strip()))
        if rest:
            continue                                   # it says more than its values - still checked
        item["auto"] = ("its values match the PDF text",
                        "every value in it (" + ", ".join(f"{p['field']} '{priority_entry_text(p['entry'])}'" for p in parts)
                        + ") is the same as the PDF text (or a typed-checked value - S382) and it says nothing else")
        if (item["id"], "line") not in TYPED_SAID:
            TYPED_SAID.add((item["id"], "line"))
            print(f"VERIFY: {item['entry']['source']}: '{priority_entry_text(item['entry'])}' - {item['auto'][1]} -> "
                  f"confirmed, not on the Verify tab (S380)")
        items.remove(item)
        agreed.append((item, None))
    # S383: the packet's footnote ('NOTE: 2 DIGS IN THIS PACKET') - read from the reads (S130), its number the
    # same as page 1's bullets and the packet's digs - confirmed, not on the Verify tab
    for item in [i for i in items if i["field"] == PRIORITY_NOTES and i["entry"].get("footnote")]:
        item["auto"] = ("the packet footnote", item["entry"]["footnote"]["why"])
        if (item["id"], "footnote") not in TYPED_SAID:
            TYPED_SAID.add((item["id"], "footnote"))
            print(f"VERIFY: {item['entry']['source']}: '{priority_entry_text(item['entry'])}' - {item['auto'][1]} -> "
                  f"confirmed, not on the Verify tab (S383)")
        items.remove(item)
        agreed.append((item, None))
    # S192: values taken out of one read line (a page-1 Notes line's depth and defect name)
    # are checked with that whole line - once, where the first of them would have come
    leaders = {item["entry"]["line"]: item for item in items
               if item["entry"].get("line") and item["field"] == PRIORITY_NOTES}
    ordered, placed = [], set()
    for item in items:
        leader = leaders.get(item["entry"].get("line"))
        if leader is None:
            ordered.append(item)
            continue
        if leader["entry"]["line"] not in placed:
            placed.add(leader["entry"]["line"])
            ordered.append(leader)
        if item is not leader:
            leader["followers"].append(item)
    # S480: the printed table values first (read more surely than handwriting) - what you check there can then
    # take away the handwriting that says the same (verify_take_away); otherwise the order stays as it was
    ordered.sort(key=lambda item: 0 if verify_is_table_entry(item["entry"]) else 1)
    return ordered, unplaced, exact, agreed


def verify_is_table_entry(entry):
    """S480: a value read from a Dig Packet's table page (a printed table cell)."""
    return bool(re.search(r" - Table page \d+", str(entry.get("source") or "")))


def verify_push_correction(key, text):
    """A value typed on the Verify tab goes into that value's own correction box too, so
    every other tab, the counter and Finish use it. False when it has no box of its own."""
    for check in CONFIRM_STATE["checks"]:
        if check.key == key and check.text_widget is not None:
            if isinstance(check.text_widget, tk.Text):
                check.text_widget.delete("1.0", "end")
                check.text_widget.insert("1.0", text)
            else:
                check.text_widget.delete(0, "end")
                check.text_widget.insert(0, text)
            check._refresh()
            return True
    return False


VERIFY_STATUS_TEXT = {"confirmed": "confirmed",
                      "rejected": "X bad read - not needed"}


def print_verify_summary(items, state, agreed=()):
    """At Finish: every value of the Verify tab - confirmed, corrected, '?', 'X' or not
    checked - and (S180) those confirmed because the PDF text says the same."""
    if not items and not agreed:
        return
    items = [i for leader in items for i in [leader] + leader["followers"]]      # S192
    checked = sum(1 for item in items if item["id"] in state)
    print()
    print("=" * 60)
    autos = Counter(item["auto"][0] if text_entry is None else "the PDF text" if text_entry.get("from_text")
                    else "the same as a typed-checked value" for item, text_entry in agreed)      # S375 / S380 / S382
    pdf_text = autos.pop("the PDF text", 0)
    print(f"VERIFIED PRIORITY VALUES (S175): {checked} of {len(items)} checked"
          + (f", {pdf_text} the same as the PDF text (S180)" if pdf_text else "")
          + "".join(f", {count} confirmed by: {how}" for how, count in autos.items()))
    print("=" * 60)
    for item, text_entry in agreed:
        if text_entry is None:                          # S375 / S380
            print(f"{item['field']} | {item['entry']['source']}: {priority_entry_text(item['entry'])}  "
                  f"[{item['auto'][0]}: {item['auto'][1]}]")
            continue
        print(f"{item['field']} | {item['entry']['source']}: {priority_entry_text(item['entry'])}  "
              f"[the same as {'the PDF text' if text_entry.get('from_text') else 'a typed-checked value (S382)'}: "
              f"{priority_entry_text(text_entry)} - {text_entry['source']}]")
    for item in items:
        done = state.get(item["id"])
        read = priority_entry_text(item["entry"])
        where = f"{item['field']} | {item['entry']['source']}"
        if not done:
            print(f"{where}: {read}  [not checked]")
        elif done["status"] == "corrected":
            print(f"{where}: {done['value']}  [corrected - read as '{done['read']}']")
        else:
            print(f"{where}: {done['value']}  [{VERIFY_STATUS_TEXT[done['status']]}]")
    print("=" * 60)


class StackTab:
    """S216: one tab holding several parts one under the other on a scrolling canvas, each
    part its own frame - so a tab with every coloured table row of a Dig Packet stays one tab,
    however many rows: no single frame grows past Windows' ~32,767 px drawing limit (the
    reason the rows used to be split 3 to a tab)."""

    def __init__(self, canvas):
        self.canvas, self.parts = canvas, []
        canvas.bind("<Configure>", lambda _event: self.layout(), add="+")

    def add(self):
        """A new part at the bottom - a frame to build into."""
        frame = ttk.Frame(self.canvas)
        self.parts.append((self.canvas.create_window(0, 0, window=frame, anchor="nw"), frame))
        frame.bind("<Configure>", lambda _event: self.layout(), add="+")
        return frame

    def layout(self):
        y, width = 0, max(1, self.canvas.winfo_width())
        for item, frame in self.parts:
            self.canvas.coords(item, 0, y)
            self.canvas.itemconfig(item, width=width)
            y += frame.winfo_reqheight()
        self.canvas.configure(scrollregion=(0, 0, width, y))


def repair_defect_length(entry):
    """S434: a repair's defect length - a wheel count's own, or a combined repair's full one from the calculator (T27)."""
    out = entry.get("out")
    return (entry.get("inputs") or {}).get("Length", out.get("full_length") if isinstance(out, dict) else None)


WRAP_BARRIER = r"\b(bend|elbow|tee|valve|flange|fitting|reducer|sleeve|casing)\b"   # S430: never combined across


class DocumentsWindow:
    """The program's window: a Documents tab to drop PDFs on, the tabs of every
    document read, a counter + Finish bar at the bottom."""

    def __init__(self):
        self.root = TkinterDnD.Tk() if TkinterDnD else tk.Tk()
        self.root.title("6000 form / Dig Packet / Quote request reader")
        self.root.geometry("1300x850")
        self.documents = []                   # dicts, in the order they were dropped in
        self.events = queue.Queue()           # worker threads -> window
        self.light_jobs = queue.Queue()       # recognise + read 6000 forms / quotes
        self.heavy_jobs = queue.PriorityQueue()   # OCR models + Dig Packets (S352: before 10000-35 photos)
        self.models = {"state": "loading", "started": time.perf_counter(), "seconds": None, "error": None}
        self.groups = {}                      # S86: document group -> its tabs, values, pictures
        self.building = None                  # S86: tabs of the group being built go here
        self.canvas_of = {}                   # tab frame -> its scroll canvas
        self.sideways_canvases = set()        # S431: the tabs that also scroll left / right
        self.extra_on = {}                    # S298: Extra tab switches - ('group' / 'pages', paths) -> shown
        self.image_references = []
        self.next_id = 1
        CONFIRM_STATE.update({"checks": [], "on_change": None, "refreshers": []})

        bottom_bar = ttk.Frame(self.root, padding=(15, 8))
        bottom_bar.pack(side="bottom", fill="x")
        ttk.Separator(self.root, orient="horizontal").pack(side="bottom", fill="x")
        self.counter_label = tk.Label(bottom_bar, font=("Segoe UI", 11, "bold"))
        self.counter_label.pack(side="left")
        ttk.Button(bottom_bar, text="Finish", command=self.finish).pack(side="right")
        self.sent_label = tk.Label(bottom_bar, fg=GREEN, font=("Segoe UI", 10))
        self.sent_label.pack(side="right", padx=10)

        self.notebook = ttk.Notebook(self.root)
        self.notebook.pack(fill="both", expand=True)
        self.root.bind_all("<MouseWheel>", self.mousewheel)
        self.build_documents_tab()
        self.update_counter()

        self.photo_jobs = queue.Queue()       # S364: 10000-35 forms' photos - read alongside the Dig Packets
        self.models_done = threading.Event()  # S364: set when the OCR models have loaded (or failed)
        self.models_ok = False
        DIG_AHEAD["next"] = self.dig_paths_waiting                        # S402
        threading.Thread(target=self.heavy_worker, daemon=True).start()
        threading.Thread(target=self.photo_worker, name="photo-reader", daemon=True).start()
        threading.Thread(target=self.light_worker, daemon=True).start()
        self.root.after(250, self.poll)
        self.root.after(300, self.update_tab_locks)                    # S463: tabs open only once ready
        print("DOCUMENTS WINDOW: open - drop PDF files on the Documents tab; the OCR models are loading in "
              "the background")

    # ---------- tabs ----------
    def add_scroll_tab(self, title, removable=True, sideways=False):
        """A tab that scrolls up and down. S431: sideways=True - also left and right (a bar at the bottom, Shift +
        mouse wheel), for tables wider than the window; its content keeps its own width then."""
        outer = ttk.Frame(self.notebook)
        self.notebook.add(outer, text=title)
        tab_canvas = tk.Canvas(outer)
        bar = ttk.Scrollbar(outer, orient="vertical", command=tab_canvas.yview)
        inner = ttk.Frame(tab_canvas)
        window_id = tab_canvas.create_window((0, 0), window=inner, anchor="nw")

        def fit(_event=None, c=tab_canvas, w=window_id, i=inner):
            """As wide as the window - S431: or as wide as its content, when that is wider (then it scrolls)."""
            c.itemconfig(w, width=max(c.winfo_width(), i.winfo_reqwidth()) if sideways else c.winfo_width())
            c.configure(scrollregion=c.bbox("all"))
        inner.bind("<Configure>", lambda event, c=tab_canvas: c.configure(scrollregion=c.bbox("all")))
        tab_canvas.configure(yscrollcommand=bar.set)
        if sideways:
            inner.bind("<Configure>", fit)              # S431: content got wider -> the frame too
            across = ttk.Scrollbar(outer, orient="horizontal", command=tab_canvas.xview)
            tab_canvas.configure(xscrollcommand=across.set)
            across.pack(side="bottom", fill="x")
            self.sideways_canvases.add(str(outer))
        tab_canvas.pack(side="left", fill="both", expand=True)
        bar.pack(side="right", fill="y")
        tab_canvas.bind("<Configure>", fit)
        self.canvas_of[str(outer)] = tab_canvas
        if removable and self.__dict__.get("building") is not None:
            self.building.append(outer)               # S86: the tab belongs to the group being built
        add_copy_tab_button(inner, title)          # every tab: 'Copy whole tab as one picture'
        return inner

    def add_stack_tab(self, title, show=True):
        """S216: a tab whose parts are stacked on one canvas (StackTab). show=False: built now,
        shown when its document is done (self.last_hidden_tab), like add_scroll_tab."""
        outer = ttk.Frame(self.notebook)
        if show:
            self.notebook.add(outer, text=title)
        else:
            self.last_hidden_tab = outer
        tab_canvas = tk.Canvas(outer, highlightthickness=0)
        bar = ttk.Scrollbar(outer, orient="vertical", command=tab_canvas.yview)
        tab_canvas.configure(yscrollcommand=bar.set)
        tab_canvas.pack(side="left", fill="both", expand=True)
        bar.pack(side="right", fill="y")
        self.canvas_of[str(outer)] = tab_canvas
        if show and self.__dict__.get("building") is not None:
            self.building.append(outer)               # the tab belongs to the group being built
        return StackTab(tab_canvas)

    def mousewheel(self, event):
        selected = self.notebook.select()
        tab_canvas = self.canvas_of.get(str(selected)) if selected else None
        if tab_canvas is not None:
            if event.state & 0x0001 and str(selected) in self.sideways_canvases:     # S431: Shift = left / right
                tab_canvas.xview_scroll(int(-1 * (event.delta / 120)), "units")
            else:
                tab_canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")

    def build_documents_tab(self):
        frame = self.add_scroll_tab("Documents", removable=False)
        section_heading(frame, "DOCUMENTS", size=16, pady=(20, 4))
        drop = tk.Label(frame, text="Drag files here\n(6000 form, Dig Packet, OmegaWrap quote request, 10000-35 "
                                    "wall thickness form (.xlsx) - or any other PDF, picture or email)",   # S214 / S320
                        font=("Segoe UI", 13), fg="#1f4e9c", bg="#eef3fb", relief="ridge", borderwidth=2,
                        padx=40, pady=40)
        drop.pack(fill="x", padx=40, pady=(8, 6))
        if TkinterDnD is None:
            drop.configure(text="Drag-and-drop is not available: run  pip install tkinterdnd2  and start "
                                "the program again.", fg=ORANGE)
        else:
            for widget in (drop, self.root):
                widget.drop_target_register(DND_FILES)
                widget.dnd_bind("<<Drop>>", self.on_drop)
        self.models_label = ttk.Label(frame, text="", foreground="#555555")
        self.models_label.pack(pady=(2, 2))
        self.message_label = tk.Label(frame, text="", fg=ORANGE, wraplength=900, font=("Segoe UI", 10))
        self.message_label.pack(pady=(2, 8))
        self.list_frame = tk.Frame(frame)
        self.list_frame.pack(fill="x", padx=40)
        self.refresh_list()
        self.build_verify_tab()                             # S175 (S212: the Priority values / snips tabs are gone)
        self.refresh_extra_tab([])                          # S298: the Extra tab from the start
        self.build_priority_values([], {})

    def build_priority_values(self, done, labels):
        if self.__dict__.get("verify_hold") and self.verify_view == "compare":
            self.verify_due = (done, labels)            # S317: done once the choosing is finished
            return
        self._build_priority_values(done, labels)

    def _build_priority_values(self, done, labels):
        """S170: the priority values, worked out again from every read document - S212: in the
        background only (no tab of their own): they feed the Verify tab (its list and its end
        table) and the Pages tabs. S171: a Dig Packet still being read gives what its reading
        has found so far (PRIORITY_STAGES), in its place in the drop order."""
        reading = {d["path"]: d for d in self.documents if d.get("kind") == "dig" and not d["removed"]
                   and d["state"] in ("waiting", "reading")}
        stages = {path: stage for path, stage in list(PRIORITY_STAGES.items()) if path in reading}
        partial = {id(reading[path]): {"kind": "dig", "name": reading[path]["name"], "partial": stage["stage"],
                                       "result": {"results": stage["results"],
                                                  "path": path}}
                   for path, stage in stages.items()}
        done_ids = {id(d) for d in done}
        # S262: each read document's label -> the file that was dropped in (for the Group button)
        self.verify_label_files = {labels[id(d)]: d.get("original", d["path"]) for d in done if id(d) in labels}
        shown = [partial.get(id(d)) or d for d in self.documents if id(d) in done_ids or id(d) in partial]
        labels = dict(labels)
        partial_ids = {id(p) for p in partial.values()}
        labels.update({key: label for key, label in document_labels(shown).items() if key in partial_ids})
        self.priority_seen = {path: stage["seq"] for path, stage in stages.items()}
        blocks = priority_value_blocks(shown, labels)
        done_paths = {d["path"] for d in done}
        # S182: a Dig Packet still being read is on the Verify tab too, with what is found so far
        self.verify_reading = [reading[path]["name"] for path in stages]
        self.refresh_verify_items(blocks, done_paths | set(stages))       # S175

    # ---------- S175: Verify tab ----------
    def build_verify_tab(self):
        """The Verify tab: a header (which value, how far along, zoom, Back / Skip) over the
        PDF that holds the value, all its pages stacked on one canvas."""
        outer = ttk.Frame(self.notebook)
        self.notebook.add(outer, text="Verify")
        self.verify_tab = self.notebook.tabs()[-1]
        self.verify_items, self.verify_unplaced, self.verify_exact, self.verify_index = [], 0, 0, 0
        self.verify_agreed = []                      # S180: (item, text entry) confirmed by the PDF text
        self.verify_blocks = []                      # S183: the priority blocks, for the table at the end
        self.verify_finals = {}                      # S191: (anomaly header, row name) -> the value picked
        self.verify_view = None                      # S234: 'compare' / 'item' / 'table' - what the tab shows
        self.verify_table_cache = None               # S235: (what it was made from, the end table)
        self.verify_state = {}                       # item id -> {"status", "value", "read"}
        self.verify_zoom = VERIFY_ZOOM_START
        self.verify_pages = {}                       # (path, zoom) -> its pages' places (S374: page_info, no pictures)
        self.verify_images = {}                      # S374: (path, zoom, page) -> its picture (PIL), the last made
        self.verify_page_photos = {}                 # S374: page -> (window picture, canvas item) - pages near the view
        self.verify_render_jobs, self.verify_render_asked = queue.PriorityQueue(), {}   # S374: pages to make
        self.verify_render_count, self.verify_images_new, self.verify_fill_due = 0, False, False
        self.verify_value_page = None                # S374: the page the value being checked is on
        self.merged = None                           # S374: the merged PDF - {'path', 'segments', 'number', ...}
        self.merged_signature, self.merged_count, self.merge_jobs = None, 0, queue.Queue()
        threading.Thread(target=self.verify_render_worker, name="verify-pages", daemon=True).start()
        threading.Thread(target=self.merge_worker, name="merged-pdf", daemon=True).start()
        self.verify_shown_key, self.verify_offsets = None, []
        header = tk.Frame(outer, padx=14, pady=8)
        header.pack(fill="x")
        buttons = tk.Frame(header)
        buttons.pack(side="right", anchor="n")
        ttk.Button(buttons, text="−", width=3, command=lambda: self.verify_change_zoom(-1)).pack(side="left")
        self.verify_zoom_label = tk.Label(buttons, width=11, font=("Segoe UI", 10))
        self.verify_zoom_label.pack(side="left")
        ttk.Button(buttons, text="+", width=3, command=lambda: self.verify_change_zoom(1)).pack(side="left",
                                                                                           padx=(0, 14))
        ttk.Button(buttons, text="◀ Back", command=lambda: self.verify_step(-1)).pack(side="left", padx=2)
        ttk.Button(buttons, text="Skip ▶", command=lambda: self.verify_step(1)).pack(side="left", padx=2)
        self.verify_title = tk.Label(header, font=("Segoe UI", 15, "bold"), anchor="w")
        self.verify_title.pack(fill="x")
        self.verify_title_colour = self.verify_title.cget("fg")     # S395: back to this after a waiting screen
        self.verify_detail = tk.Label(header, fg="#1f4e9c", font=("Segoe UI", 10), anchor="w", justify="left",
                                      wraplength=1000)
        self.verify_detail.pack(fill="x")
        self.verify_progress = tk.Label(header, fg="#555555", font=("Segoe UI", 10), anchor="w")
        self.verify_progress.pack(fill="x")
        self.verify_hint = tk.Label(header, fg="#555555", font=("Segoe UI", 9), anchor="w",
                                    text="Right: ✓ (or Enter).   X = bad read, not needed.   Wrong: type the right "
                                         "value in the box, then ✓ / Enter.")
        self.verify_hint.pack(fill="x")
        ttk.Separator(outer, orient="horizontal").pack(fill="x")
        body = tk.Frame(outer)
        body.pack(fill="both", expand=True)
        self.verify_canvas = tk.Canvas(body, bg="#808080", highlightthickness=0)
        down = ttk.Scrollbar(body, orient="vertical", command=self.verify_canvas.yview)
        across = ttk.Scrollbar(body, orient="horizontal", command=self.verify_canvas.xview)
        # S374: whenever the view moves, the pages coming into view get their pictures
        self.verify_canvas.configure(yscrollcommand=lambda *view: (down.set(*view), self.verify_schedule_fill()),
                                     xscrollcommand=across.set)
        self.verify_canvas.bind("<Configure>", lambda _event: self.verify_schedule_fill(), add="+")
        down.pack(side="right", fill="y")
        across.pack(side="bottom", fill="x")
        self.verify_canvas.pack(side="left", fill="both", expand=True)
        self.canvas_of[str(outer)] = self.verify_canvas           # the mouse wheel scrolls the PDF
        self.notebook.bind("<<NotebookTabChanged>>", lambda _event: self.show_verify_item(), add="+")
        self.notebook.bind("<<NotebookTabChanged>>", lambda _event: self.wc_tab_opened(), add="+")    # S370
        self.root.after(100, self.verify_image_poll)    # S374
        self.show_verify_item()

    def refresh_verify_items(self, blocks, paths):
        """The list follows the priority values (new documents, removed ones, S182: a packet
        still being read, stage by stage); the value being looked at stays the same one when
        it is still in the list. S182: a value whose read changed after it was checked (the
        reading's last checks) is to be checked again; the pages of every PDF with values
        to check are made in the background straight away, so they are ready on the tab."""
        current = self.verify_items[self.verify_index]["id"] if self.verify_index < len(self.verify_items) else None
        self.verify_blocks = blocks                                 # S183: for the table at the end
        (self.verify_items, self.verify_unplaced, self.verify_exact,
         self.verify_agreed) = verify_items_from_blocks(blocks, paths)
        for item in [i for leader in self.verify_items for i in [leader] + leader["followers"]]:
            before = self.verify_state.get(item["id"])
            read = priority_entry_text(item["entry"])
            if before and before["read"] != read:
                self.verify_state.pop(item["id"])
                print(f"VERIFY: {item['field']} | {item['entry']['source']}: read changed from '{before['read']}' to "
                      f"'{read}' after it was checked - to be checked again (S182)")
        if VERIFY_WAIT["appeared"] is None and any(not self.verify_state.get(i["id"]) for i in self.verify_items):
            first = next(i for i in self.verify_items if not self.verify_state.get(i["id"]))
            VERIFY_WAIT.update(appeared=time.perf_counter(), field=f"{first['field']} | {first['entry']['source']}",
                               dropped=min((d["dropped"] for d in self.documents if d.get("dropped")), default=None))
            print(f"VERIFY WAIT: the first value to check came up {VERIFY_WAIT['appeared'] - PROGRAM_START:.1f} s after "
                  f"the program started" + (f" ({VERIFY_WAIT['appeared'] - VERIFY_WAIT['dropped']:.1f} s after the first "
                                            f"document was dropped in)" if VERIFY_WAIT["dropped"] else "")
                  + f" - {VERIFY_WAIT['field']} (S409)")
        ids = [item["id"] for item in self.verify_items]
        if current in ids:
            self.verify_index = ids.index(current)
        else:                                            # S238: the first value not checked yet, else the end
            self.verify_index = next((n for n, item in enumerate(self.verify_items)
                                      if not self.verify_state.get(item["id"])), len(self.verify_items))
        self.verify_places_changed()

    def verify_places_changed(self):
        """S374: the values' places (in the merged PDF, or their own PDF until it is in it) - the pages of PDFs
        no longer shown are forgotten, the shown ones placed in the background, the next values' page pictures
        made ahead, and the value shown again."""
        paths = {self.verify_place(item["entry"]["where"])["path"] for item in self.verify_items}
        for key in [k for k in self.verify_pages if k[0] not in paths]:
            self.verify_pages.pop(key, None)
        for key in [k for k in list(self.verify_images) if k[0] not in paths]:
            self.verify_images.pop(key, None)
        if self.verify_shown_key and self.verify_shown_key[0] not in paths:
            self.verify_shown_key = None
        for path in paths:
            self.verify_start_render((path, self.verify_zoom))
        self.verify_prefetch()
        self.show_verify_item()

    def verify_place(self, where):
        """S374: a value's place -> its place in the merged PDF (the same box, its page moved along by the
        pages before its document); its own place while its document is not in the merged PDF (yet)."""
        merged = self.__dict__.get("merged")
        segment = merged["segments"].get(where["path"]) if merged else None
        if segment is None or where["page"] >= segment["count"]:
            return where
        return dict(where, path=merged["path"], page=segment["start"] + where["page"])

    def verify_start_render(self, key):
        """S182: places the pages of one PDF at one zoom in the background, once (S374: their sizes only - the
        pictures are made page by page)."""
        if key in self.verify_pages:
            return
        self.verify_pages[key] = "rendering"

        def render(key=key):
            try:
                self.verify_pages[key] = verify_page_infos(*key)
            except Exception as exc:
                self.verify_pages[key] = f"the pages could not be shown ({exc})"

        threading.Thread(target=render, daemon=True).start()

    def verify_want_page(self, key, number, priority):
        """S374: a page's picture is wanted - made in the background (priority 0 = the value's own page, 1 = in
        view, 2 = made ahead) unless it is made or asked for at that priority already."""
        image_key = (key[0], key[1], number)
        if image_key in self.verify_images or self.verify_render_asked.get(image_key, 99) <= priority:
            return
        self.verify_render_asked[image_key] = priority
        self.verify_render_count += 1
        self.verify_render_jobs.put((priority, self.verify_render_count, image_key))

    def verify_prefetch(self):
        """S374: the pages of the value shown and the next VERIFY_PREFETCH_ITEMS values not checked yet are made
        ahead (S182: so they are ready on the tab)."""
        ahead = [item for n, item in enumerate(self.verify_items)
                 if n >= self.verify_index and not self.verify_state.get(item["id"])][:VERIFY_PREFETCH_ITEMS + 1]
        for item in ahead:
            place = self.verify_place(item["entry"]["where"])
            self.verify_want_page((place["path"], self.verify_zoom), place["page"], 2)

    def verify_render_worker(self):
        """S374: makes the asked-for page pictures, the most wanted first; only the last VERIFY_KEEP_PAGES made
        are kept (one used again is made again)."""
        while True:
            _priority, _count, image_key = self.verify_render_jobs.get()
            if image_key in self.verify_images or not os.path.isfile(image_key[0]):
                self.verify_render_asked.pop(image_key, None)
                continue
            try:
                image = verify_page_picture(*image_key)
            except Exception as exc:
                print(f"VERIFY: page {image_key[2] + 1} of {os.path.basename(image_key[0])} could not be drawn ({exc})")
                self.verify_render_asked.pop(image_key, None)
                continue
            self.verify_images[image_key] = image
            self.verify_render_asked.pop(image_key, None)
            while len(self.verify_images) > VERIFY_KEEP_PAGES:
                try:
                    self.verify_images.pop(next(iter(self.verify_images)), None)     # the one used longest ago
                except (RuntimeError, StopIteration):    # changed by the window at that moment - next time
                    break
            self.verify_images_new = True

    def verify_image_poll(self):
        """S374: page pictures made in the background are put on the canvas."""
        if self.verify_images_new:
            self.verify_images_new = False
            self.verify_fill_pages()
        self.root.after(60, self.verify_image_poll)

    def verify_schedule_fill(self):
        if not self.verify_fill_due:
            self.verify_fill_due = True
            self.root.after_idle(self.verify_fill_pages)

    def verify_fill_pages(self):
        """S374: the pages in view (and a screen's height above and below) get their pictures - made ones at
        once, the others asked for; pages far from the view give theirs up (the window pictures of a long
        merged PDF would not fit in memory all at once)."""
        self.verify_fill_due = False
        key = self.verify_shown_key
        pages = self.verify_pages.get(key) if key else None
        if not isinstance(pages, list):
            return
        canvas = self.verify_canvas
        height = max(1, canvas.winfo_height())
        top = canvas.canvasy(0)
        near = [n for n, (_x, y) in enumerate(self.verify_offsets)
                if y < top + 2 * height and y + pages[n]["size"][1] > top - height]
        for number in [n for n in self.verify_page_photos if n not in near]:
            canvas.delete(self.verify_page_photos.pop(number)[1])
        from PIL import ImageTk
        for number in near:
            if number in self.verify_page_photos:
                continue
            image = self.verify_images.get((key[0], key[1], number))
            if image is None:
                self.verify_want_page(key, number, 1)
                continue
            self.verify_images[(key[0], key[1], number)] = self.verify_images.pop((key[0], key[1], number))  # used
            photo = ImageTk.PhotoImage(image)
            x, y = self.verify_offsets[number]
            item = canvas.create_image(x, y, image=photo, anchor="nw", tags="pages")
            canvas.tag_raise(item, f"page_place_{number}")      # over its place, under the value's box and panel
            self.verify_page_photos[number] = (photo, item)
            if number == self.verify_value_page:
                self.click_wait_done("page")             # S372: the value's page picture is on screen

    def verify_next_unchecked(self):
        """S263: after ✓ / X / a correction - the next value not checked yet (after this one, else the
        first one before it), else the end. Back still goes one by one."""
        unchecked = [n for n, item in enumerate(self.verify_items) if not self.verify_state.get(item["id"])]
        self.verify_index = next((n for n in unchecked if n > self.verify_index),
                                 unchecked[0] if unchecked else len(self.verify_items))
        self.show_verify_item()

    def click_wait(self, what):
        """S369/S372: how long the window kept you waiting after a click - from the moment the click is handled
        until everything it set off is done: the click's own work, Tk drawing what changed (done at once with
        update_idletasks so it is in the time), and on the Verify tab the value's second scroll (S177 - 0.06 s
        after, on purpose), the pages of its PDF being placed when they were not yet, and (S374) its page's
        picture when it was not made yet. Printed as one CLICK WAIT line. (A click made while the window is
        still busy is only handled once it is free - that earlier wait is not in the number.)"""
        old = self.__dict__.get("click_measure")
        if old is not None:
            self.click_wait_print(old)
        if VERIFY_WAIT["appeared"] is not None and VERIFY_WAIT["clicked"] is None:     # S409: your first click
            VERIFY_WAIT.update(clicked=time.perf_counter(), click=what)
            print("VERIFY WAIT: " + verify_wait_text())
        measure = self.click_measure = {"what": what, "started": time.perf_counter(), "drawn": None,
                                        "waits": set(), "at": {}}
        self.root.after(0, lambda: self.click_wait_drawn(measure))

    def click_wait_drawn(self, measure):
        """S372: the click's own work is done (and anything queued before it) - Tk draws what changed now."""
        if self.__dict__.get("click_measure") is not measure:
            return
        self.root.update_idletasks()
        measure["drawn"] = time.perf_counter() - measure["started"]
        if not measure["waits"]:
            self.click_wait_print(measure)

    def click_wait_expect(self, part):
        """S372: the click is not finished yet - 'pages' (its PDF's pages are still being placed), 'page'
        (S374: the value's page picture is still being made) or 'scroll' (the value's second scroll is due)."""
        measure = self.__dict__.get("click_measure")
        if measure is not None:
            measure["waits"].add(part)

    def click_wait_done(self, part):
        measure = self.__dict__.get("click_measure")
        if measure is None or part not in measure["waits"]:
            return
        measure["waits"].discard(part)
        measure["at"][part] = time.perf_counter() - measure["started"]
        if not measure["waits"] and measure["drawn"] is not None:
            self.click_wait_print(measure)

    def click_wait_print(self, measure):
        self.click_measure = None
        what, drawn, at = measure["what"], measure["drawn"], measure["at"]
        if measure["waits"] or drawn is None:          # the next click came first
            waiting = {"pages": "its PDF's pages", "page": "its page picture", "scroll": "the second scroll"}
            print(f"CLICK WAIT: {what} - not finished when the next click came "
                  f"{time.perf_counter() - measure['started']:.2f} s after it (still waiting for "
                  f"{', '.join(waiting[w] for w in sorted(measure['waits'])) or 'the drawing'}) (S372)")
            return
        extra = ""
        if "pages" in at:
            extra += f" - its PDF's pages were still being placed: placed {at['pages']:.2f} s after the click"
        if "page" in at:
            extra += f" - its page picture was still being made: on screen {at['page']:.2f} s after the click"
        ready = max([drawn] + list(at.values()))
        if "scroll" in at:
            print(f"CLICK WAIT: {what} - drawn {drawn:.2f} s after the click, ready again {ready:.2f} s "
                  f"(with the second scroll, which waits 0.06 s on purpose){extra} (S372)")
        else:
            print(f"CLICK WAIT: {what} - the window was ready again {ready:.2f} s after the click (drawn){extra} (S372)")

    def verify_step(self, step):
        self.click_wait("Back" if step < 0 else "Skip")                  # S369
        self.verify_index = max(0, min(len(self.verify_items), self.verify_index + step))
        if self.__dict__.get("verify_hold"):            # S317: leaving the choosing (Back) - what waited comes in
            self.release_verify_hold()
            return
        self.show_verify_item()

    def verify_change_zoom(self, step):
        """S178: − / + : the pages are drawn again at the next smaller / larger zoom."""
        index = VERIFY_ZOOMS.index(self.verify_zoom) if self.verify_zoom in VERIFY_ZOOMS else 0
        self.verify_zoom = VERIFY_ZOOMS[max(0, min(len(VERIFY_ZOOMS) - 1, index + step))]
        for key in [k for k in self.verify_pages if k[1] != self.verify_zoom and self.verify_pages[k] != "rendering"]:
            self.verify_pages.pop(key, None)
        for key in [k for k in list(self.verify_images) if k[1] != self.verify_zoom]:
            self.verify_images.pop(key, None)
        if self.verify_shown_key and self.verify_shown_key[1] != self.verify_zoom:
            self.verify_shown_key = None
        self.verify_places_changed()

    def verify_progress_text(self):
        state = [self.verify_state.get(item["id"]) for item in self.verify_items]
        counts = Counter(s["status"] for s in state if s)
        text = (f"{min(self.verify_index + 1, len(self.verify_items))} of {len(self.verify_items)}  -  "
                f"{counts['confirmed']} confirmed, {counts['corrected']} corrected"
                + (f", {counts['rejected']} marked X" if counts["rejected"] else "")
                + f", {len(state) - sum(counts.values())} not checked yet")
        autos = Counter(item["auto"][0] if text_entry is None else "the PDF text" if text_entry.get("from_text")
                        else "the same as a typed-checked value" for item, text_entry in self.verify_agreed)
        pdf_text = autos.pop("the PDF text", 0)                                       # S375 / S380 / S382
        if pdf_text:
            text += f"   ({pdf_text} the same as the PDF text - confirmed, not listed)"
        for how, count in autos.items():
            text += f"   ({count} confirmed by: {how}, not listed)"
        if self.__dict__.get("verify_reading"):
            text += f"   - still being read: {', '.join(self.verify_reading)} (more values to come)"
        if self.verify_exact:
            text += f"   ({self.verify_exact} value(s) read from the PDFs' own text are exact - not listed here)"
        if self.verify_unplaced:
            text += (f"   ({self.verify_unplaced} value(s) without a known place in their PDF are only in the "
                     f"end table)")
        return text

    def show_verify_item(self):
        """Shows the current value: its PDF (pages made in the background the first time at
        this zoom), a box around the value, and right under it a one-line panel - the read
        value, ✓ and a correction box. Only while the Verify tab is the one being looked at."""
        if self.notebook.select() != self.verify_tab:
            return
        canvas = self.verify_canvas
        canvas.delete("overlay")
        self.verify_title.configure(fg=self.verify_title_colour)   # S395: orange only while waiting for documents
        # S176: the last value's panel goes too - deleting its canvas item alone leaves the
        # panel itself drawn (Tk keeps an embedded window's widget until it is destroyed)
        old_panel = self.__dict__.get("verify_panel_widget")
        if old_panel is not None and old_panel.winfo_exists():
            old_panel.destroy()
        self.verify_panel_widget = None
        canvas.configure(bg="#808080")                  # S215: the table drew on a white canvas
        names_frame = self.__dict__.get("verify_names_frame")     # S252: the document names' boxes
        if names_frame is not None and names_frame.winfo_exists():
            names_frame.destroy()
        self.verify_zoom_label.configure(text=f"Zoom {int(self.verify_zoom * 100 / 1.33 + 0.5)}%")
        # S234/S235: the handwriting / picture reads one by one first; when they are all done, the
        # comparisons to choose (only while some are not picked); then the table of everything
        if self.verify_items and self.verify_index >= len(self.verify_items):
            # S238: at the end with values never checked (the list changed under the place being looked
            # at - a packet's next stage arrived, a value was read again): back to the first of them
            missed = [n for n, item in enumerate(self.verify_items) if not self.verify_state.get(item["id"])]
            if missed:
                print(f"VERIFY: {len(missed)} value(s) not checked yet were passed while the list changed - "
                      f"back to them: {', '.join(self.verify_items[n]['field'] for n in missed)} (S238)")
                self.verify_index = missed[0]
        at_end = not self.verify_items or self.verify_index >= len(self.verify_items)
        table = self.verify_table() if at_end else None
        # S236: a comparison is chosen once every document that gives it is read - per anomaly
        # column: none of its values comes from a document still being read. The columns that are
        # ready are chosen while the next documents load; the others wait for them.
        ready = self.verify_settled_headers() if at_end else set()       # S470: per dig - nothing more to come
        picks = table[3] if at_end else {}
        compared = sorted({r for (r, _c), (header, _l, _t) in picks.items() if header in ready})
        waiting = sorted({r for (r, _c), (header, label, _t) in picks.items()
                          if header in ready and (header, label) not in self.verify_finals})
        later = sorted({header for (_r, _c), (header, label, _t) in picks.items()
                        if header not in ready and (header, label) not in self.verify_finals})
        loading = [d["name"] for d in self.documents if not d["removed"] and d["state"] in ("waiting", "reading")]
        if not waiting and later and loading:             # only comparisons whose documents are still being read
            self.verify_view = "loading"
            self.verify_clear_canvas()
            self.verify_shown_key = None
            canvas.configure(bg="white", scrollregion=(0, 0, 1, 1))
            message = canvas.create_text(
                VERIFY_PAGE_GAP + 20, VERIFY_PAGE_GAP + 20, anchor="nw", width=1000, font=("Segoe UI", 12), tags="loading",
                fill="#555555", text=f"Values differ for {', '.join(later)} - the choosing for them starts when the "
                                     f"documents they come from have been read, so the comparisons are complete:\n\n"
                                     f"still being read: {', '.join(loading)}")
            # S239: underneath, what differs so far - each value with where it was found (nothing to pick yet)
            # S241: only what differs and the documents that disagree - the values come with the choosing
            differs = {}
            for (r, c), (header, label, _text) in picks.items():
                if header not in ready and (header, label) not in self.verify_finals:
                    found = str(table[1][r][c + 1]).split("\n") if c + 1 < len(table[1][r]) else []
                    documents = differs.setdefault((header, label), [])
                    for place in found:
                        document = verify_document_of(place)
                        if document and document not in documents:
                            documents.append(document)
            lines = [f"{header}  -  {label}:   " + ("  vs  ".join(documents) if len(documents) > 1 else
                                                     f"{documents[0] if documents else '?'} (two places in it)")
                     for (header, label), documents in differs.items()]
            canvas.create_text(VERIFY_PAGE_GAP + 20, canvas.bbox(message)[3] + 24, anchor="nw", width=1600, tags="loading",
                               font=("Segoe UI", 11), fill="#222222",
                               text="What differs so far:\n\n" + "\n".join(lines))
            canvas.configure(scrollregion=(0, 0, VERIFY_PAGE_GAP + 1700, canvas.bbox("loading")[3] + VERIFY_PAGE_GAP))
            self.verify_title.configure(text=f"Nothing to check right now - {verify_names_text(loading)} "
                                             f"{'is' if len(loading) == 1 else 'are'} still being read",
                                        fg=VERIFY_WAIT_COLOUR)                                   # S395
            self.verify_detail.configure(text="You are not missing anything - the values that differ come up here "
                                              "by themselves to choose from as soon as every document they come from "
                                              "is read. No click needed meanwhile (S236 / S395).")
            self.verify_progress.configure(text=self.verify_progress_text())
            self.verify_hint.configure(text="")
            return
        if waiting:
            self.verify_view = "compare"
            self.verify_hold = True                     # S317: the background waits until all are picked
            self.verify_show_table(table, rows=compared,
                                   heading=f"Choose the right value - {len(waiting)} row(s) to pick"
                                           + (f" (more once {', '.join(loading)} is read)" if later and loading else ""))
            self.verify_title.configure(text="Choose first - the values that differ")
            self.verify_detail.configure(
                text="Each yellow row has two or more versions of one value: click ✓ on the right one (it goes "
                     "into the anomaly's Final column). When every one is picked, the table of everything "
                     "follows. Back goes to the last value.")
            self.verify_progress.configure(text=f"{len(compared) - len(waiting)} of {len(compared)} comparison(s) picked")
            self.verify_hint.configure(text="✓ on a yellow value picks it (green).")
            return
        if at_end:
            self.verify_view = "table"
            self.verify_show_table(table)
            done = bool(self.verify_items)
            anything = any(block["notes"] or any(block["fields"].values()) for block in self.verify_blocks)
            reading = list(dict.fromkeys(list(self.__dict__.get("verify_reading") or []) + loading))   # S395
            if reading:
                # S395: more values are coming - said plainly, so a finished list is not mistaken for the end
                self.verify_title.configure(text=f"Nothing to check right now - {verify_names_text(reading)} "
                                                 f"{'is' if len(reading) == 1 else 'are'} still being read",
                                            fg=VERIFY_WAIT_COLOUR)
                self.verify_detail.configure(
                    text=(f"Every value found so far is checked ({len(self.verify_items)}). " if done else "")
                    + f"The values of {verify_names_text(reading)} come up here by themselves when "
                    + ("it is" if len(reading) == 1 else "they are") + " done - no click needed meanwhile. "
                    + "The table below has everything found so far" + (" - Back goes to the last value" if done else "")
                    + " (S182 / S395).")
            else:
                self.verify_title.configure(text="Every value has been checked - the table of everything is below"
                                            if done else "Nothing needs checking - the table of everything is below"
                                            if anything else "Nothing to verify yet")
                self.verify_detail.configure(
                    text="Back goes to the last value. Finish sends everything to the terminal." if done else
                    "Every value found so far was read from the PDFs' own text - exact, nothing to check (S179)."
                    if self.verify_exact else "The values appear here once a document has been read.")
            self.verify_progress.configure(text=self.verify_progress_text() if done else "")
            return
        self.verify_view = "item"
        item = self.verify_items[self.verify_index]
        entry, where = item["entry"], item["entry"]["where"]
        if self.verify_index == len(self.verify_items) - 1:    # S235: the last value - the table is worked
            self.root.after(300, lambda: self.verify_prepare_table(item))   # out ahead, as if it is ✓'d
        self.verify_title.configure(
            text=(f"Notes line - the whole line (its {', '.join(f['field'] for f in item['followers'])} too)"
                  if item["followers"] else item["field"])
            + ("  -  differs from the PDF text" if item["kind"] == "differs" else ""))
        place = self.verify_place(where)              # S374: its place in the merged PDF
        merged = self.__dict__.get("merged")
        self.verify_detail.configure(text=f"{item['block']}\n{entry['source']}  -  page {where['page'] + 1}"
                                          + (f"   (page {place['page'] + 1} of the merged PDF, {merged['pages']} pages)"
                                             if merged and place["path"] == merged["path"] else ""))
        self.verify_progress.configure(text=self.verify_progress_text())
        key = (place["path"], self.verify_zoom)
        self.verify_start_render(key)                           # S182: normally made already
        pages = self.verify_pages.get(key)
        if pages == "rendering" or isinstance(pages, str):
            self.verify_clear_canvas()
            self.verify_shown_key = None
            canvas.create_text(20, 20, anchor="nw", fill="white", font=("Segoe UI", 12), tags="overlay",
                               text=(f"Showing the pages of {os.path.basename(place['path'])} ..."
                                     if pages == "rendering" else pages))
            if pages == "rendering":
                self.click_wait_expect("pages")         # S372
                self.root.after(150, self.show_verify_item)
            return
        self.click_wait_done("pages")                   # S372: placed (when the click waited for it)
        if self.verify_shown_key != key:
            self.verify_draw_pages(key, pages)
        if place["page"] >= len(pages):
            canvas.create_text(20, 20, anchor="nw", fill="white", font=("Segoe UI", 12), tags="overlay",
                               text=f"This PDF has no page {place['page'] + 1}")
            return
        self.verify_value_page = place["page"]
        self.verify_want_page(key, place["page"], 0)    # S374: its page's picture first
        if place["page"] not in self.verify_page_photos and (key[0], key[1], place["page"]) not in self.verify_images:
            self.click_wait_expect("page")              # S372: the click waits for that picture being made too
        self.verify_prefetch()
        x0, y0, x1, y1 = verify_display_box(place, pages[place["page"]])
        left, top = self.verify_offsets[place["page"]]
        x0, x1, y0, y1 = x0 + left, x1 + left, y0 + top, y1 + top
        canvas.create_rectangle(x0 - 3, y0 - 3, x1 + 3, y1 + 3, outline=ORANGE, width=3, tags="overlay")
        panel = self.verify_panel_widget = self.verify_panel(item)
        if place.get("anchor"):                       # S241: under its own value on the line (A / B ...)
            panel_x = verify_display_box(dict(place, box=place["anchor"]), pages[place["page"]])[0] + left
        else:
            panel_x = x0
        canvas.create_window(panel_x - 3, y1 + 6, window=panel, anchor="nw", tags="overlay")
        panel.update_idletasks()
        self.verify_entry_box.focus_set()
        # S177: scroll to the value's page so its box and panel are in view - now, and once
        # more after Tk has laid the tab and the panel out (a scroll made before that, e.g.
        # right after the pages were drawn or the tab was opened, could be left behind)
        area = (x0 - 3, y0 - 3, max(x1 + 3, x0 - 3 + panel.winfo_reqwidth()), y1 + 6 + panel.winfo_reqheight())
        self.verify_scroll_to(area)
        self.click_wait_expect("scroll")                # S372: the click is finished after this second scroll
        self.root.after(60, lambda: (self.verify_scroll_to(area), self.click_wait_done("scroll")))

    def verify_table_key(self, state):
        """S235: what the end table is made from - it is made again only when this changes."""
        return (id(self.verify_blocks), tuple(sorted((k, repr(v)) for k, v in state.items())),
                tuple(sorted(self.verify_finals.items())), tuple(item["id"] for item, _t in self.verify_agreed),
                tuple((c.key, c.final_value) for c in CONFIRM_STATE["checks"] if c.corrected))

    def verify_table(self, state=None):
        """S235: the end table (verify_summary_table), kept until what it is made from changes."""
        state = self.verify_state if state is None else state
        key = self.verify_table_key(state)
        cached = self.__dict__.get("verify_table_cache")
        if cached and cached[0] == key:
            if state is self.verify_state:              # S300: also when it was worked out ahead (a ✓ guessed)
                self.root.after(0, lambda t=cached[1]: self.start_repair_lengths(t))
            return cached[1]
        started = time.perf_counter()
        table = verify_summary_table(self.verify_blocks, state, self.verify_agreed, self.verify_finals)
        self.verify_table_cache = (key, table)
        print(f"VERIFY: end table worked out ({len(table[1])} rows, {len(table[0])} columns) in "
              f"{time.perf_counter() - started:.1f} s (S235)")
        if state is self.verify_state:                  # S296: new OD / WT / lengths -> repair lengths at once
            self.root.after(0, lambda t=table: self.start_repair_lengths(t))
        return table

    def verify_prepare_table(self, item):
        """S235: while the last value is on screen, the end table is worked out as if it gets its ✓
        (the usual answer) - so the comparisons / table come up at once after it."""
        if self.verify_view != "item" or not self.verify_items or self.verify_items[-1] is not item \
                or self.verify_index != len(self.verify_items) - 1:
            return
        state = dict(self.verify_state)
        read = priority_entry_text(item["entry"])
        state[item["id"]] = {"status": "confirmed", "value": read, "read": read}
        for follower in item["followers"]:
            follower_read = priority_entry_text(follower["entry"])
            state[follower["id"]] = {"status": "confirmed", "value": follower_read, "read": follower_read}
        self.verify_table(state)

    def verify_show_table(self, table, rows=None, heading=None):
        self.verify_canvas.pick_cells = {}              # S317: filled as the table is drawn
        """S183: once every value is checked (or there is nothing to check), the PDF makes
        way for the table of everything that was looked for: every document's values -
        PDF text and checked ones together - with their notes and what is left to look at.
        S234: rows = only these rows of it (the comparisons to choose first), under heading."""
        if not any(block["notes"] or any(block["fields"].values()) for block in self.verify_blocks):
            return
        canvas = self.verify_canvas
        self.verify_clear_canvas()
        self.verify_shown_key = None
        names, all_rows, colours, picks = table
        if rows is not None:                            # S234: only these rows, renumbered
            place = {r: n for n, r in enumerate(rows)}
            colours = {(place[r], c): v for (r, c), v in colours.items() if r in place}
            picks = {(place[r], c): v for (r, c), v in picks.items() if r in place}
            all_rows = [all_rows[r] for r in rows]
        rows = all_rows
        left, top = VERIFY_PAGE_GAP + 20, VERIFY_PAGE_GAP + 10
        canvas.configure(bg="white")
        title = canvas.create_text(left, top, anchor="nw", font=("Segoe UI", 13, "bold"), tags="table",
                                   text=heading or "Everything looked for - PDF text and checked values together")
        legend = canvas.create_text(left, canvas.bbox(title)[3] + 4, anchor="nw", fill="#555555",
                                    font=("Segoe UI", 9), width=1200, tags="table",
                                    text="One column per anomaly - headed by "
                      + ("its defect name (its Wheel Count, else Mile Post, else coordinates, else Info 1, 2 ... "
                         "when it has none)" if heading is None else
                         "its Wheel Count (else Mile Post, else coordinates, else Info 1, 2 ...)")   # S333
                      + "; the same anomaly in several documents is one column.  One value per cell - "
                      "every place it was found said the same.  When an anomaly has two different values for one "
                      "thing its column is doubled (same header twice): both values shown, the cells that differ in "
                      "yellow, with where each was found in the 'found in' column to its right.  "
                      "✓ next to a yellow value picks it: it turns green and goes into the "
                      "anomaly's 'Final' column.  "
                      "The PDF-text value comes first when there is one.  X = bad read, left out (in Notes).")
        table_top = canvas.bbox(legend)[3] + 10
        if heading is None:                             # S252: the document names, above the table of everything
            names_frame = self.verify_document_names(names, rows)
            if names_frame is not None:
                canvas.create_window(left, table_top, window=names_frame, anchor="nw", tags="table")
                names_frame.update_idletasks()
                table_top += names_frame.winfo_reqheight() + 14
            names = verify_defect_headers(names, rows)  # S333: shown headed by defect name (after the names above)
        # S286: the comparisons (the doubled columns with their 'found in') are a table of their own: before
        # picking, only that table; after, the table with the Final columns and the others first and the
        # comparisons moved down under it
        split = names.index("Looked for", 1) if "Looked for" in names[1:] else None
        shown = []                                      # S325: what is drawn, for 'Copy table as text'

        def draw(canvas, left, top, headers, table_rows, *rest):
            shown.append((headers, table_rows))
            return draw_canvas_table(canvas, left, top, headers, table_rows, *rest)
        if split is None:
            draw(canvas, left, table_top, names, rows, colours, picks, lambda pick: self.verify_pick_final(*pick))
        else:
            def part(columns_from, columns_to, only_compared):
                keep = [c for c in range(len(names)) if c == 0 or columns_from <= c < columns_to]
                place = {c: n for n, c in enumerate(keep)}
                with_pick = {r for (r, c) in picks if c in place}      # the comparisons: only rows to choose in
                chosen = [r for r in range(len(rows)) if not only_compared or r in with_pick]
                at = {r: n for n, r in enumerate(chosen)}
                return ([names[c] for c in keep], [[rows[r][c] for c in keep] for r in chosen],
                        {(at[r], place[c]): v for (r, c), v in colours.items() if r in at and c in place},
                        {(at[r], place[c]): v for (r, c), v in picks.items() if r in at and c in place})
            compared = part(1, split, True)
            if heading is None:                         # after picking: everything first, the comparisons below
                main_names, main_rows, main_colours, main_picks = part(split + 1, len(names), False)
                bottom = draw(canvas, left, table_top, main_names, main_rows, main_colours, main_picks,
                              lambda pick: self.verify_pick_final(*pick))
                note = canvas.create_text(left, bottom + 30, anchor="nw", font=("Segoe UI", 12, "bold"), tags="table",
                                          text="Comparisons - the values that differed and where each was found "
                                               "(✓ still changes a pick)")
                table_top = canvas.bbox(note)[3] + 8
            draw(canvas, left, table_top, *compared, lambda pick: self.verify_pick_final(*pick))
        # S325: the table as text - tab between cells, a line per row (pastes into Excel as cells, or as text
        # anywhere); a cell with lines or tabs in it is put in "..." so it stays one cell
        def cell_text(value):
            text = str(value)
            return '"' + text.replace('"', '""') + '"' if any(ch in text for ch in '\t\n"') else text

        def copy_table():
            text = "\n\n".join("\n".join("\t".join(cell_text(v) for v in line) for line in [headers] + table_rows)
                                for headers, table_rows in shown)
            self.root.clipboard_clear()
            self.root.clipboard_append(canvas.itemcget(title, "text") + "\n\n" + text)
            copy_button.configure(text="Copied ✓")
            self.root.after(2000, lambda: copy_button.winfo_exists() and copy_button.configure(text="Copy table as text"))
            print(f"VERIFY: table copied as text - {sum(len(r) for _h, r in shown)} row(s) in {len(shown)} table(s) "
                  f"(S325)")
        old_button = self.__dict__.get("verify_copy_button")
        if old_button is not None and old_button.winfo_exists():
            old_button.destroy()                         # the table is drawn again - one button, not one per drawing
        copy_button = self.verify_copy_button = tk.Button(canvas, text="Copy table as text", command=copy_table,
                                                          font=("Segoe UI", 9))
        canvas.create_window(canvas.bbox(title)[2] + 16, top, anchor="nw", window=copy_button, tags="table")
        right, bottom = canvas.bbox("table")[2:]
        canvas.configure(scrollregion=(0, 0, right + VERIFY_PAGE_GAP, bottom + VERIFY_PAGE_GAP))
        canvas.xview_moveto(0)
        canvas.yview_moveto(0)

    def maps_place_lookup(self, header, latitude, longitude, keep):
        """S347: the anomaly's city and state from Google Maps (google_maps_address), in the background, once
        per spot; when it comes, its place box gets 'Keithville, LA' - and the town check and the State box
        follow, as for a pasted place - unless you typed in that box."""
        lookups = self.__dict__.setdefault("maps_lookups", {})       # (lat, lon) -> {'state', 'result', 'why'}
        spot = (latitude, longitude)
        found = lookups.get(spot)
        if found is not None:
            found["headers"].add(header)                 # anomalies at the same spot share one lookup
        if found is None:
            if not maps_browser():
                if not self.__dict__.get("maps_no_browser_said"):
                    self.maps_no_browser_said = True
                    print("GOOGLE MAPS: Edge / Chrome not found - the places are not looked up; paste them (S347)")
                return
            found = lookups[spot] = {"state": "running", "headers": {header}}
            if self.__dict__.get("maps_pool") is None:
                from concurrent.futures import ThreadPoolExecutor
                self.maps_pool = ThreadPoolExecutor(max_workers=MAPS_AT_ONCE)

            def work():
                try:
                    found.update(state="done", result=google_maps_address(latitude, longitude))
                    result = found["result"]
                    print(f"GOOGLE MAPS: {header} at {latitude},{longitude} -> {result['address']} "
                          f"({result['seconds']:.1f} s) (S347)")
                except Exception as exc:
                    found.update(state="failed", why=str(exc))
                    print(f"GOOGLE MAPS: {header} at {latitude},{longitude} - no place: {exc} - paste it (S347)")
                self.root.after(0, lambda: [self.maps_place_fill(h, spot) for h in sorted(found["headers"])])
            self.maps_pool.submit(work)
        elif found["state"] == "done":
            self.maps_place_fill(header, spot, keep)

    def maps_place_fill(self, header, spot, keep=None):
        """S347: put a Google Maps place in an anomaly's place box (only an empty one, or one still holding
        the place filled in before - never one you typed in) and run its town check."""
        found = (self.__dict__.get("maps_lookups") or {}).get(spot) or {}
        if found.get("state") != "done":
            return
        keep = keep if keep is not None else (self.__dict__.get("verify_names_typed") or {}).get(header)
        if keep is None:
            return
        place = f"{found['result']['city']}, {found['result']['state']}"
        if keep.get("place_typed") or keep["place"] not in ("", keep.get("place_auto")):
            return
        keep["place"], keep["place_auto"] = place, place
        widgets = (self.__dict__.get("verify_place_widgets") or {}).get(header)
        if widgets and widgets[0].winfo_exists() and widgets[0].get() != place:
            widgets[0].delete(0, "end")
            widgets[0].insert(0, place)
            widgets[1]()                                 # its town check, State box and names

    def verify_guess_companies(self, header, keep, company_cell):
        """S344: the Document names' company boxes filled in when the documents say: an anomaly whose
        documents include a Boardwalk one (a Dig Packet, a 6000 form, a 10000-35 form - the documents in its
        column are about it) is Boardwalk's -> 'Overall company' = Boardwalk; the sub company is the 10000-35
        form's ticked Company box (its Company row, e.g. TGT) -> 'Company name'. Only an empty box, or one
        still holding what was filled in before, is filled - never one you typed in."""
        files = verify_column_files(self.verify_blocks, header, self.__dict__.get("verify_label_files", {}))
        kinds = {d["kind"] for d in self.documents if not d["removed"]
                 and os.path.abspath(d.get("original", d["path"])) in {os.path.abspath(f) for f in files}}
        boardwalk = sorted(kinds & COMPANY_BOARDWALK_KINDS)
        sub = str(company_cell or "").strip()
        sub = sub if sub and sub != "-" and sub != VERIFY_PICK_PROMPT else ""
        guesses = {"overall": COMPANY_BOARDWALK if boardwalk else "", "company": sub}
        filled = []
        for field, guess in guesses.items():
            if guess and not keep.get(field + "_typed") and keep[field] in ("", keep.get(field + "_auto")):
                if keep[field] != guess:
                    filled.append(f"{'Overall company' if field == 'overall' else 'Company name'} '{guess}'")
                keep[field], keep[field + "_auto"] = guess, guess
        if filled:
            print(f"DOCUMENT NAMES: {header} - " + "; ".join(filled) + " filled in ("
                  + (f"its documents include Boardwalk's: {', '.join(DOCUMENT_KIND_NAMES[k] for k in boardwalk)}"
                     if boardwalk else "") + ("; " if boardwalk and sub else "")
                  + (f"its Company row says {sub} - the 10000-35 form's ticked box" if sub else "") + ") (S344)")

    def verify_document_names(self, headers, rows):
        """S252: above the table of everything, for every anomaly column: its document name
        Composite_Calc_<Company Name (S258, typed in its box)>_<diameter>_<Line ID>_<Project Number>_<Anomaly Name>,
        a Google Maps link
        for its coordinates, a box to paste the place in ('FWXF+3QJ McFaddin, Texas' -> 'McFaddin,
        Texas'), a box for the state's abbreviation, and the full name with _<City>_<State>.
        What is typed is kept while the table is drawn again. None when there is no anomaly column."""
        old = self.__dict__.get("verify_names_frame")
        if old is not None and old.winfo_exists():
            old.destroy()
        typed = self.__dict__.setdefault("verify_names_typed", {})       # header -> {'place', 'state'}
        by_label = {row[0]: row for row in rows}
        self.verify_end_table = (headers, by_label)      # S447: for the Group calculator's Main!C11
        columns = [h for h in dict.fromkeys(document_name_header(h) for h in headers[1:])
                   if h and not h.startswith("Info ") and h not in ("Looked for", "Notes")]
        if not columns:
            return None
        frame = self.verify_names_frame = tk.Frame(self.verify_canvas, bg="white")
        top = tk.Frame(frame, bg="white")
        top.grid(row=0, column=0, columnspan=12, sticky="w", pady=(0, 4))
        tk.Label(top, text="Document names", bg="white", font=("Segoe UI", 12, "bold")).pack(side="left")
        # S346: one Google Maps route through every anomaly's coordinates, in wheel count order
        route_links = verify_route_links(headers, by_label, columns)
        for number, (link, stops) in enumerate(route_links, start=1):
            label = "Google Maps - all anomalies" + (f" ({number} of {len(route_links)})" if len(route_links) > 1 else "")
            tk.Button(top, text=label, fg="#1a0dab", relief="flat", bg="white", cursor="hand2",
                      command=lambda l=link: webbrowser.open(l)).pack(side="left", padx=(16, 4))
            link_box = ttk.Entry(top, width=min(120, len(link) + 2))
            link_box.insert(0, link)
            link_box.configure(state="readonly")
            link_box.pack(side="left")
            said = ("route", link)
            if said not in VERIFY_NOTES_SAID:
                VERIFY_NOTES_SAID.add(said)
                print(f"DOCUMENT NAMES: Google Maps route {number} of {len(route_links)} through "
                      f"{', '.join(stops)} - {link} (S346)")
        for c, text in enumerate(["Anomaly", "Document name", "Right?", "Overall company (if any)", "Company name",
                                  "Map", "Paste the place from Google Maps", "City, State", "State",
                                  "Folder name", ""]):            # S348: the Document name holds the place
            tk.Label(frame, text=text, bg="white", fg="#555555", font=("Segoe UI", 9, "bold")).grid(
                row=1, column=c, sticky="w", padx=4)
        # S349: only the anomalies the documents are about get a Document name (extras - a girth weld or AGM
        # only listed in a Dig Packet's table / map notes - are left out; the route above still goes through them)
        columns, left_out = verify_focus_columns(self.verify_blocks, columns)
        if left_out:
            said = ("names left out", tuple(sorted(left_out.items())))
            if said not in VERIFY_NOTES_SAID:
                VERIFY_NOTES_SAID.add(said)
                print("DOCUMENT NAMES: left out (extra - not what the documents are about): "
                      + "; ".join(f"{end_table_value(headers, by_label, h, 'Defect name') or h} ({h}) - {why}"
                                  for h, why in left_out.items()) + " (S349)")
        anomaly_names, used = {}, Counter()             # S345: each anomaly by its defect name ('Gouge #1')
        for header in columns:
            name = end_table_value(headers, by_label, header, "Defect name")
            name = name if name and name != "-" and name != VERIFY_PICK_PROMPT else header
            used[name] += 1
            anomaly_names[header] = name + (f" ({used[name]})" if used[name] > 1 else "")
        # S449: one row (one Group folder, one calculator) per picked repair (WC Distances, 'The repair it picks'),
        # named after its bold main wheel count (on the Dig Packet's page 1 / the 6000 form) - else its first
        # anomaly; an anomaly in no picked repair gets no row
        pick = self.__dict__.get("wrap_pick") or {}
        bold = wheel_count_on_forms(self.verify_blocks)
        repair_rows = []
        for repair in sorted(pick.get("fabrics") or {}, key=lambda n: float(n.split(" & ")[0])):
            members = repair.split(" & ")
            shown = [m for m in members if m in columns]
            if shown:
                repair_rows.append((next((m for m in shown if m in bold), shown[0]), members, repair))
        self.verify_repair_members = {main: members for main, members, _repair in repair_rows}
        no_repair = [h for h in columns if not any(h in members for _m, members, _r in repair_rows)]
        said = ("names no repair", tuple(no_repair), bool(pick))
        if no_repair and said not in VERIFY_NOTES_SAID:
            VERIFY_NOTES_SAID.add(said)
            print("DOCUMENT NAMES: no row (in no picked repair" + ("" if pick else " - WC Distances not worked out yet")
                  + "): " + ", ".join(f"{anomaly_names[h]} ({h})" for h in no_repair) + " (S449)")
        if not repair_rows:
            tk.Label(frame, text="No repairs yet - a row comes for each repair once WC Distances has worked out "
                                 "'The repair it picks'.", bg="white", fg="#555555").grid(
                row=2, column=0, columnspan=11, sticky="w", padx=4, pady=4)
        for r, (header, members, _repair) in enumerate(repair_rows, start=2):
            def cell(label):
                """The value the table shows for this anomaly in that row (its Final when it was picked)."""
                return end_table_value(headers, by_label, header, label)
            project = next((cell(label) for label in by_label
                            if re.search(VERIFY_FIRST_OTHER_ROWS[0], label, re.IGNORECASE) and cell(label)), "")
            project = document_project_number(project)                    # S256: 'PN 17636'
            # S259: the anomaly's Wheel Count - else its station (Mile Post) - in the names too
            wheel = header if re.fullmatch(r"\d+(\.\d+)?", header) else cell("Wheel Count")
            wheel = re.sub(r"\s*ft$", "", wheel).strip()
            wheel = f"WC {wheel}" if wheel else cell("Mile Post")         # S260: 'WC 100553.07' (a station as it is)
            diameter = document_name_diameter(cell("Outside Diameter"))
            rest = [diameter, cell("Line ID"), project, cell("Defect name"), wheel]
            folder_rest = [cell("Line ID"), project, cell("Defect name"), wheel]
            self.__dict__.setdefault("verify_name_parts", {})[header] = {        # S267: the calculator's Main!C3
                "C3": [calculator_diameter(cell("Outside Diameter")), wheel, cell("Line ID"), project],
                "H10": cell("Defect name"),                                          # S271: the defect name
                "inches": {name: next((cell(label) for label in labels if cell(label)), "")      # S278
                           for name, labels in CALC_MEASUREMENT_ROWS.items()},
                "H9": ", ".join(p for p in (verify_number(cell("Coordinates - Latitude") or cell("Coordinates")) or "",
                                            verify_number(cell("Coordinates - Longitude")) or "") if p)}   # S272
            latitude = verify_number(cell("Coordinates - Latitude") or cell("Coordinates"))
            longitude = verify_number(cell("Coordinates - Longitude"))
            keep = typed.setdefault(header, {"place": "", "state": "", "ticked": False, "company": "",
                                             "overall": ""})   # S258 / S259
            self.verify_guess_companies(header, keep, cell("Company"))              # S344
            named = tk.Frame(frame, bg="white")          # S449: the anomaly it is named after (bold), then the
            named.grid(row=r, column=0, sticky="w", padx=4)  # repair's other anomalies under it
            tk.Label(named, text=anomaly_names[header], bg="white", font=("Segoe UI", 10, "bold")).pack(anchor="w")
            others = [anomaly_names.get(m) or (self.__dict__.get("repair_names") or {}).get(m, m)
                      for m in members if m != header]
            if others:
                tk.Label(named, text="also in this repair: " + ", ".join(others), bg="white", fg="#555555",
                         font=("Segoe UI", 9), wraplength=260, justify="left").pack(anchor="w")
            name_box = ttk.Entry(frame, width=60)        # S449: yours to retype - what you type is kept
            name_box.grid(row=r, column=1, sticky="w", padx=4, pady=2)
            # S257: a tick to say the name's information is right - only then the rest of the line shows
            ticked = tk.BooleanVar(value=keep["ticked"])
            later = []                                   # the row's widgets shown once it is ticked
            overall_box = ttk.Entry(frame, width=20)     # S259: the overall company - for the folder name, may stay blank
            overall_box.insert(0, keep["overall"])
            later.append((overall_box, 3))
            company_box = ttk.Entry(frame, width=24)     # S258: the company name - typed first, right of the tick
            company_box.insert(0, keep["company"])
            later.append((company_box, 4))
            if latitude and longitude:
                link = f"https://www.google.com/maps/search/?api=1&query={latitude},{longitude}"
                later.append((tk.Button(frame, text="Google Maps", fg="#1a0dab", relief="flat", bg="white",
                                        cursor="hand2", command=lambda l=link: webbrowser.open(l)), 5))
            else:
                later.append((tk.Label(frame, text="(no coordinates)", bg="white", fg="#888888"), 5))
            place_box = ttk.Entry(frame, width=32)
            place_box.insert(0, keep["place"])
            later.append((place_box, 6))
            place_shown = tk.Label(frame, text="", bg="white", font=("Segoe UI", 10), anchor="w",
                                   justify="left", wraplength=420)               # S255: the whole line shown
            later.append((place_shown, 7))
            state_box = ttk.Entry(frame, width=5)
            state_box.insert(0, keep["state"])
            later.append((state_box, 8))
            folder_box = ttk.Entry(frame, width=80)      # S259: the folder name, once the name is complete
            later.append((folder_box, 9))
            group_button = tk.Button(frame, text="Group", bg=GREEN, fg="white", activebackground=GREEN,
                                     font=("Segoe UI", 9, "bold"), padx=8)          # S262
            group_button.configure(command=lambda h=header, f=folder_box, d=name_box, b=group_button:
                                   self.verify_group(h, f.get(), d.get(), b))
            later.append((group_button, 10))
            self.__dict__.setdefault("group_buttons", []).append(group_button)     # S464: locked till the tabs are done
            self.lock_group_button(group_button, self.__dict__.get("group_wait", "WC Distances, Clock Distances"))

            def show_place(keep=keep, ticked=ticked, later=later, r=r):
                keep["ticked"] = ticked.get()
                for widget, column in later:
                    if keep["ticked"]:
                        widget.grid(row=r, column=column, sticky="w", padx=4)
                    else:
                        widget.grid_remove()

            tk.Checkbutton(frame, variable=ticked, bg="white", activebackground="white",
                           command=lambda s=show_place, n=anomaly_names[header]: (
                               self.click_wait(f"Right? tick - {n}"), s())).grid(row=r, column=2, padx=4)   # S369
            show_place()

            def show_name(keep=keep, rest=rest, place_box=place_box, state_box=state_box,
                          name_box=name_box, company_box=company_box, overall_box=overall_box,
                          folder_box=folder_box, diameter=diameter, folder_rest=folder_rest):
                keep["place"], keep["state"] = place_box.get(), state_box.get()
                keep["company"], keep["overall"] = company_box.get().strip(), overall_box.get().strip()
                base = document_name(["Composite_Calc", keep["company"]] + rest)     # S258
                city = document_place(keep["place"]).split(",")[0].strip()
                state = keep["state"].strip().upper()
                # S259: '<Overall company> - <Company> <OD> - <Line ID> - <Project number> - <Anomaly name> -
                # <Wheel Count / station> - <City>, <State>'
                # S261: filled like the document name - whatever is not known yet is just left out
                folder = folder_name([keep["overall"], " ".join(p for p in (keep["company"], diameter) if p)]
                                     + folder_rest + [", ".join(p for p in (city, state) if p)])
                # S348: the Document name is the whole name - its company, city and state in it as soon as
                # they are known (filled in or typed); a change in a box changes it at once
                # S449: the Document name box is yours to retype - once you do, yours stays
                keep["name_auto"] = document_name([base, city, state])
                name_text = keep["name"] if keep.get("name_typed") else keep["name_auto"]
                for box, text, locked in ((name_box, name_text, False), (folder_box, folder, True)):
                    box.configure(state="normal", width=max(20, len(text) + 2))   # S345: never cut off
                    box.delete(0, "end")
                    box.insert(0, text)
                    if locked:
                        box.configure(state="readonly")

            def name_typed(_event=None, keep=keep, name_box=name_box):       # S449
                keep["name"] = name_box.get()
                keep["name_typed"] = keep["name"].strip() != (keep.get("name_auto") or "")
            name_box.bind("<KeyRelease>", name_typed)
            name_box.bind("<<Paste>>", lambda _e, t=name_typed: self.root.after(10, t))

            for box, field in ((company_box, "company"), (overall_box, "overall")):          # S258 / S259

                def typed_in(_event=None, box=box, field=field, keep=keep, show_name=show_name):
                    # S344: what you type is kept - a box you changed is never filled in again
                    keep[field + "_typed"] = box.get().strip() != keep.get(field + "_auto")
                    show_name()
                box.bind("<KeyRelease>", typed_in)
                box.bind("<<Paste>>", lambda _e, t=typed_in: self.root.after(10, t))

            def check_place(_event=None, keep=keep, place_box=place_box, state_box=state_box,
                            place_shown=place_shown, show_name=show_name):
                """S253: the pasted place, checked to be a US town in that state (in the background - the
                first check may download the place list); confirmed -> the State box is filled."""
                keep["place"] = place_box.get()
                place = document_place(keep["place"])
                city, _comma, state = place.partition(",")
                place_shown.configure(text=place + ("   checking ..." if city.strip() else ""), fg="black")
                show_name()
                asked = keep["place"]

                def work():
                    code, line, ok = us_place_check(city, state)

                    def shown():
                        if not place_shown.winfo_exists() or place_box.get() != asked:
                            return                       # a newer paste is being checked
                        place_shown.configure(text=f"{place}   {line}", fg=GREEN if ok else "#b00020")
                        if code:                         # S254/S256: the abbreviation 'us' gives, confirmed or not
                            state_box.delete(0, "end")
                            state_box.insert(0, code)
                        show_name()
                    self.root.after(0, shown)

                threading.Thread(target=work, daemon=True).start()

            def place_typed(_event=None, keep=keep, place_box=place_box, check_place=check_place):
                # S347: what you type or paste is kept - a box you changed is never filled from Google Maps again
                keep["place_typed"] = place_box.get().strip() != keep.get("place_auto")
                check_place()
            place_box.bind("<KeyRelease>", place_typed)
            place_box.bind("<<Paste>>", lambda _e, t=place_typed: self.root.after(10, t))
            self.__dict__.setdefault("verify_place_widgets", {})[header] = (place_box, check_place)   # S347
            state_box.bind("<KeyRelease>", lambda _e, s=show_name: s())
            if latitude and longitude:                  # S347: its city and state from Google Maps
                self.maps_place_lookup(header, latitude, longitude, keep)
            if keep["place"]:
                check_place()
            else:
                show_name()
        return frame

    def refresh_extra_tab(self, extras):
        """S298: the Extra tab - every other tab (each document group's tabs, each document's Pages tab)
        with ✓ (shown) and X (not shown). A tab not shown is not made at all - nothing is worked out for it
        until its ✓ is clicked."""
        if self.__dict__.get("extra_tab") is None:
            self.extra_frame = ttk.Frame(self.add_scroll_tab("Extra", removable=False))
            self.extra_frame.pack(fill="x")
            self.extra_tab = self.notebook.tabs()[-1]
        for child in self.extra_frame.winfo_children():
            child.destroy()
        ttk.Label(self.extra_frame, text="Extra tabs", font=("Segoe UI", 12, "bold", "underline")).pack(pady=(16, 4))
        ttk.Label(self.extra_frame, foreground="#555555", wraplength=900, justify="center",
                  text="✓ shows a document's extra tab(s) - they are made then; X takes them away (nothing is "
                       "worked out for them while they are off). Documents, Verify, WC Distances and Warnings are "
                       "always shown. Under each name: what its tab(s) show.").pack(pady=(0, 8))
        if not extras:
            ttk.Label(self.extra_frame, text="No documents read yet.", foreground="#555555").pack(pady=4)
            return
        table = tk.Frame(self.extra_frame)
        table.pack(padx=20, pady=4)
        for row, (switch, name, about) in enumerate(extras):
            on = bool(self.extra_on.get(switch))
            tk.Button(table, text="✓", width=3, font=("Segoe UI", 10, "bold"),
                      bg=GREEN if on else "#e8e8e8", fg="white" if on else "#555555",
                      command=lambda s=switch: self.set_extra(s, True)).grid(row=row, column=0, padx=2, pady=6,
                                                                             sticky="n")
            tk.Button(table, text="X", width=3, font=("Segoe UI", 10, "bold"),
                      bg="#b00020" if not on else "#e8e8e8", fg="white" if not on else "#555555",
                      command=lambda s=switch: self.set_extra(s, False)).grid(row=row, column=1, padx=2, pady=6,
                                                                              sticky="n")
            words = tk.Frame(table)                     # S301: its name, and what the tab(s) show
            words.grid(row=row, column=2, sticky="w", padx=(10, 0), pady=(4, 8))
            tk.Label(words, text=name, font=("Segoe UI", 10, "bold"), fg=GREEN if on else "black",
                     anchor="w").pack(anchor="w")
            tk.Label(words, text=about, font=("Segoe UI", 9), fg="#444444", anchor="w", justify="left",
                     wraplength=820).pack(anchor="w")

    def main_wheel_counts_frame(self):
        """S313: the 'Main Wheel Counts' tab's frame, emptied - made when switched on in Extra; None (and the
        tab taken away) when switched off."""
        tab = self.__dict__.get("main_wc_tab")
        if not self.extra_on.get(("mainwc",)):
            if tab is not None:
                self.canvas_of.pop(str(tab), None)
                self.notebook.nametowidget(tab).destroy()
                self.main_wc_tab = None
            return None
        if tab is None:
            self.main_wc_frame = ttk.Frame(self.add_scroll_tab("Main Wheel Counts", removable=False))
            self.main_wc_frame.pack(fill="x")
            self.main_wc_tab = self.notebook.tabs()[-1]
            if self.__dict__.get("extra_tab"):          # right after the Extra tab
                self.notebook.insert(self.notebook.index(self.extra_tab) + 1, self.main_wc_tab)
        for child in self.main_wc_frame.winfo_children():
            child.destroy()
        return self.main_wc_frame

    def set_extra(self, switch, on):
        """S298: an Extra tab's ✓ / X - the tabs are built (or taken away) now."""
        if bool(self.extra_on.get(switch)) == on:
            return
        self.extra_on[switch] = on
        print(f"EXTRA: {' / '.join(os.path.basename(p) for p in switch[1:])} {switch[0]} tabs "
              f"{'shown - made now' if on else 'taken away'} (S298)")
        self.rebuild_tabs()
        if switch == ("mainwc",):                       # S313: drawn with the WC Distances tab
            self.refresh_wc_tab()

    def refresh_warnings_tab(self, done, labels):
        """S297: one Warnings tab for every document read - each warning headed by the document it is in;
        no tab at all when there are no warnings."""
        self.warnings_args = (done, labels)             # S318: so a wrap overlap can add itself later
        records = [{"where": "WC Distances - wrap start and end", "text": text, "pictures": [], "values": []}
                   for text in self.__dict__.get("wrap_overlap_warnings") or []]                    # S318
        for document in done:
            result = document.get("result")
            if document["kind"] != "dig" or not isinstance(result, dict) or not result.get("results"):
                continue
            name = labels.get(id(document), os.path.basename(document["path"]))
            records += [dict(r, where=f"{name} - {r['where']}") for r in collect_warnings(result)]
        old = self.__dict__.get("warnings_tab")
        if old is not None:
            try:
                self.canvas_of.pop(str(old), None)
                self.notebook.nametowidget(old).destroy()
            except Exception:
                pass
            self.warnings_tab = None
        print(f"WARNINGS TAB: {len(records)} warning(s) in all documents"
              + (" - " + "; ".join(r["where"] for r in records) if records else " - no Warnings tab") + " (S297)")
        if not records:
            return
        self.warnings_pictures = []
        title = f"Warnings ({len(records)})"
        self.warnings_title = title                     # S463: its name while it is locked (the tab shows a picture)
        add_warnings_section(self.add_scroll_tab(title, removable=False), records, self.warnings_pictures)
        self.warnings_tab = self.notebook.tabs()[-1]
        # S314: the tab itself is red - its title drawn white on red (a ttk tab cannot have a colour of its own)
        font = get_font(14, bold=True)
        left, top, right, bottom = ImageDraw.Draw(Image.new("RGB", (1, 1))).textbbox((0, 0), title, font=font)
        badge = Image.new("RGB", (right - left + 16, bottom - top + 8), (200, 0, 32))
        ImageDraw.Draw(badge).text((8 - left, 4 - top), title, font=font, fill="white")
        from PIL import ImageTk
        self.warnings_tab_picture = ImageTk.PhotoImage(badge)
        self.notebook.tab(self.warnings_tab, text="", image=self.warnings_tab_picture, compound="center")

    def start_repair_lengths(self, table):
        if self.__dict__.get("verify_hold") and self.verify_view == "compare":
            return                                      # S317: after the choosing (release_verify_hold)
        self._start_repair_lengths(table)

    def _start_repair_lengths(self, table):
        """S296: each wheel count whose OD, WT and defect length are all known gets its 'Linear Length of
        Repair' from the calculator (Corrosion C27, Mechanical C26) - as soon as those values are found;
        only new or changed ones are sent to Excel. Shown at the top of the WC Distances tab."""
        headers, rows = table[0], table[1]
        inputs, waiting = repair_length_inputs(headers, rows)
        results = self.__dict__.setdefault("repair_results", {})
        found_wheels = wheel_counts_found(headers, rows)
        self.repair_names = {w["header"]: w["shown"] for w in found_wheels}
        self.repair_types = {w["header"]: w["name"] for w in found_wheels}          # S443: for the fabric pick
        # S452: what decides whether wheel counts can be one repair (one calculator) - its pipe - and its depth /
        # width (inches, as E13 / E16 take them) for the largest of a repair's
        self.repair_pipe = {w["header"]: {name: end_table_value(headers, {r[0]: r for r in rows}, w["header"], name)
                                          for name in REPAIR_SAME_PIPE_ROWS + ("Depth", "Width")}
                            for w in found_wheels}
        status = (tuple(sorted((h, tuple(v.values())) for h, v in inputs.items())),
                  tuple(sorted((h, tuple(v)) for h, v in waiting.items())))
        if status != self.__dict__.get("repair_status"):             # S300: said whenever it changes
            self.repair_status = status
            print(f"REPAIR LENGTHS: {len(inputs)} wheel count(s) with OD, WT and length known"
                  + (" (" + ", ".join(inputs) + ")" if inputs else "")
                  + (f"; not yet: " + "; ".join(f"{h} ({', '.join(w)})" for h, w in waiting.items())
                     if waiting else "")
                  + " (S300)")
        changed = False
        for header in [h for h in results if h not in inputs and h not in waiting]:
            del results[header]                         # no longer has all three
            changed = True
        for header, what in waiting.items():            # S300: shown as waiting, not left out
            text = ", ".join(what) + (" (on Verify)" if any(w.startswith("pick") for w in what) else "")
            if (results.get(header) or {}).get("out") != text:
                results[header] = {"inputs": None, "out": text}
                changed = True
        todo = {h: v for h, v in inputs.items() if (results.get(h) or {}).get("inputs") != v}
        if not todo:
            if changed:
                self.refresh_wc_tab()
            return
        template = find_calculator()
        for header, values in todo.items():
            results[header] = {"inputs": values, "out": None if template else "calculator not found"}
        submitted = {h: v for h, v in inputs.items() if (results.get(h) or {}).get("out") is None}   # new + still waiting
        self.refresh_wc_tab()
        if template is None:
            return
        if self.__dict__.get("repair_excel") is None:
            self.repair_excel = RepairLengthExcel(template)
        started = time.perf_counter()

        def done(answer):
            def shown():
                for header, values in submitted.items():
                    entry = results.get(header)
                    if entry is None or entry["inputs"] != values:
                        continue                        # changed again meanwhile - a newer job is on its way
                    entry["out"] = (f"Excel: {answer}" if isinstance(answer, BaseException)
                                    else answer.get(header) if isinstance(answer, dict) else None)
                if isinstance(answer, BaseException):
                    print(f"REPAIR LENGTHS: could not be worked out - "
                          f"{'needs: pip install pywin32' if isinstance(answer, ImportError) else answer} (S296)")
                else:
                    for header, out in answer.items():
                        print(f"REPAIR LENGTHS: {header}: OD {submitted[header]['Outside Diameter']} in, WT "
                              f"{submitted[header]['Wall Thickness']} in, length {submitted[header]['Length']} in -> "
                              f"Corrosion C27 = {out['Corrosion']} in, Mechanical C26 = {out['Mechanical']} in (S296)")
                        for name, (start, end) in (out.get("wraps") or {}).items():
                            print(f"REPAIR LENGTHS: {header}: {name} wrap -> J3 start {start}, L3 end {end} (S302)")
                    print(f"REPAIR LENGTHS: {len(answer)} wheel count(s) worked out in "
                          f"{time.perf_counter() - started:.1f} s (S296)")
                self.refresh_wc_tab()
            self.root.after(0, shown)

        self.repair_excel.submit(submitted, done)

    def draw_repair_table(self, repairs, names, what="wheel count(s)"):
        """S296/S301: the Linear Length of Repair table - each repair (a wheel count, or S432 a combined one 'A & B')
        with its OD / WT / defect length and Corrosion C27 / Mechanical C26 (and + 12), in wheel count order."""
        done_count = sum(1 for e in repairs.values() if isinstance(e["out"], dict))
        ready_count = sum(1 for e in repairs.values() if e["inputs"])
        ttk.Label(self.wc_frame, font=("Segoe UI", 10, "bold"),
                  text=(f"{done_count} of {len(repairs)} {what} worked out - {ready_count} have all three values"
                        if repairs else "No wheel counts found yet.")).pack(pady=(0, 4))   # S301
        number = lambda v: verify_short_number(v) if isinstance(v, (int, float)) else ("-" if v is None else str(v))
        lines = []
        for header in sorted(repairs, key=lambda h: float(h.split(" & ")[0])):
            entry = repairs[header]
            out = entry["out"]
            cells = (["calculating ..."] * 4 if out is None else [out] * 4 if isinstance(out, str)
                     else [number(out.get("Corrosion")), number((out.get("plus") or {}).get("Corrosion")),
                           number(out.get("Mechanical")), number((out.get("plus") or {}).get("Mechanical"))])
            given = dict(entry["inputs"] or {}, Length=repair_defect_length(entry))
            lines.append([names.get(header, header)] + [number(given.get(n)) for n in REPAIR_INPUT_CELLS] + cells)
        if lines:
            add_simple_table(self.wc_frame, ["Wheel count", "Outside Diameter E4 (in)", "Wall Thickness E5 (in)",
                                             "Defect Length E15 (in)", "Linear Length of Repair - Corrosion C27 (in)",
                                             f"Corrosion {PLUS_LABEL} {PLUS_CELLS['plus']} (in)",               # S437
                                             "Linear Length of Repair - Mechanical C26 (in)",
                                             f"Mechanical {PLUS_LABEL} {PLUS_CELLS['plus']} (in)"], lines, wraplength=200)

    def draw_combined_repair_table(self):
        """S432: at the bottom of the WC Distances tab - the Linear Length of Repair table again, for the second wrap
        table's repairs: the combined ones and every wheel count not in one, with their new wrap lengths. S433: and
        the wheel count distances table again for them, under it."""
        second = self.__dict__.get("wrap_second")
        if not second or not second[1]:
            return
        combined, groups, names = second
        ttk.Label(self.wc_frame, text="Linear Length of Repair with the overlapping wheel counts as one repair "
                                      "(worked out by the calculator)",
                  font=("Segoe UI", 12, "bold", "underline")).pack(pady=(24, 4))
        ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                  text="The repairs of the second wrap table: each combined one (its total defect length from "
                       f"{COMBINED_CELLS['length']}, the first one's Outside Diameter and Wall Thickness) and every wheel count "
                       "not in one - into E4 / E5 / "
                       "E15 of the Corrosion and Mechanical sheets; read back: Corrosion C27 and Mechanical C26 "
                       "(inches).").pack(pady=(0, 6))
        self.draw_repair_table(combined, names, what="repair(s)")
        self.draw_combined_distance_table(combined, names)

    def draw_combined_distance_table(self, combined, names, title=None, every_wrap=False):
        """S433: under it - the wheel count distances table again for those repairs: each with the one next to it,
        into R3 / V3 and R5 / V5 of the Wheel Count Calculator sheet; read back T22 / T23 / T27 / T28. Asked of
        Excel once per pair of values. S441: a combined repair goes in as itself - its middle (CO17) and its total
        defect length (CO13), as the calculator gave them - and only once it has them; a wheel count (a bend, a
        girth weld ...) inside a combined repair's regular wrap (J3 / L3) is left out - it is not beside it.
        S443: title = another heading; every_wrap=True - inside any of its wraps shown (the picked ones)."""
        def place(header):           # S441: (feet, inches) as it goes in - None while the calculator has not answered
            entry = combined[header]
            if " & " in header:
                out = entry.get("out")
                if isinstance(out, dict) and all(isinstance(out.get(k), (int, float)) for k in ("middle", "full_length")):
                    return out["middle"], float(out["full_length"])
                return None
            return float(header), float((entry.get("inputs") or {}).get("Length") or 0)
        spans = {}                   # S441: each combined repair's regular wraps, from the first start to the last end
        for header, entry in combined.items():
            out = entry.get("out")
            if " & " in header and isinstance(out, dict):
                ends = [v for k, v in (out.get("wraps") or {}).items() if (every_wrap or k in REPAIR_OUTPUT_CELLS)
                        and all(isinstance(x, (int, float)) for x in v)]
                if ends:
                    spans[header] = (min(e[0] for e in ends), max(e[1] for e in ends))
        inside = {h: next(c for c, (low, high) in spans.items() if low <= float(h) <= high)
                  for h in combined if " & " not in h and any(low <= float(h) <= high for low, high in spans.values())}
        waiting = [h for h in combined if " & " in h and place(h) is None]
        order = sorted((h for h in combined if h not in inside and place(h) is not None), key=lambda h: place(h)[0])
        pairs = [(a, b) for a, b in zip(order, order[1:])]
        keys = [place(a) + place(b) for a, b in pairs]
        found = self.__dict__.setdefault("combined_distances", {})
        asked = self.__dict__.setdefault("combined_distances_asked", set())
        new = [k for k in keys if k not in found and k not in asked]
        if new and self.__dict__.get("repair_excel") is not None:
            asked.update(new)

            def done(answer, new=new):
                def shown():
                    if isinstance(answer, BaseException):
                        print(f"COMBINED DISTANCES: could not be worked out - {answer} (S433)")
                        found.update({k: (f"Excel: {answer}",) * 4 for k in new})
                    else:
                        found.update(answer)
                        print(f"COMBINED DISTANCES: {len(answer)} distance(s) worked out (S433)")
                    self.refresh_wc_tab()
                self.root.after(0, shown)
            self.repair_excel.submit_pair_distances(new, done)
        ttk.Label(self.wc_frame, text=title or "Wheel count distances with the overlapping wheel counts as one "
                                               "repair (worked out by the calculator)",
                  font=("Segoe UI", 12, "bold", "underline")).pack(pady=(24, 4))
        ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                  text=f"Each repair with the one next to it - a combined one as its middle ({COMBINED_CELLS['middle']}) "
                       f"with its total defect length ({COMBINED_CELLS['length']}). Into the '{WC_SHEET}' sheet: "
                       f"{WC_CELLS['wc1']} / {WC_CELLS['wc2']} (feet), "
                       f"{WC_CELLS['length1']} / {WC_CELLS['length2']} (inches, 0 when none is known), 0 in "
                       f"{WC_CELLS['zero1']} / {WC_CELLS['zero2']}; read back: "
                       f"{WC_CELLS['distance']} / {WC_CELLS['apart']} (inches) and {WC_CELLS['distance_ft']} / "
                       f"{WC_CELLS['apart_ft']} (feet)."
                       + "".join(f" Left out: {names.get(h, h)} - inside the wrap of {c}." for h, c in inside.items())
                       + "".join(f" {names.get(h, h)}: waiting for the calculator." for h in waiting)
                  ).pack(pady=(0, 6))
        show = lambda v: "-" if v is None else (verify_short_number(v) if isinstance(v, (int, float)) else str(v))
        rows = []
        for (a, b), key in zip(pairs, keys):
            got = found.get(key) or ("calculating ...",) * 4
            rows.append([names.get(a, a), names.get(b, b), show(key[0]), show(key[2]), show(key[1]), show(key[3]),
                         show(got[0]), show(got[1]), show(got[2]), show(got[3])])
        if rows:
            add_simple_table(self.wc_frame, ["Wheel count 1", "Wheel count 2", f"{WC_CELLS['wc1']} (ft)",
                                             f"{WC_CELLS['wc2']} (ft)", f"Defect length 1 {WC_CELLS['length1']} (in)",
                                             f"Defect length 2 {WC_CELLS['length2']} (in)",
                                             f"Distance {WC_CELLS['distance']} (in)",
                                             f"Distance {WC_CELLS['distance_ft']} (ft)",
                                             f"Total defect length apart {WC_CELLS['apart']} (in)",
                                             f"Total defect length apart {WC_CELLS['apart_ft']} (ft)"], rows, wraplength=200)

    def show_wrap_table(self, repairs, draw=True):
        """S302: every wheel count with its defect length and Linear Length of Repair, and between them, in
        number order, where each repair's wrap starts and ends (the Wheel Count Calculator sheet's J3 / L3
        for that wheel count in K3 and its repair length in M5, M6 = 0). S370: draw=False - the distances
        are still asked of Excel and the overlap warnings still made, nothing is drawn.
        S429: under it the same table with the wheel counts whose regular wraps overlap worked out as ONE repair
        (wrap_combined_repairs)."""
        if not repairs:
            return
        names = self.__dict__.get("repair_names") or {}
        first = self.wrap_table_rows(repairs, names, warn=True)
        combined, groups = self.wrap_combined_repairs(repairs, first["regular"], names)
        combined_names = dict(names, **{g: g + " (combined)" for g in groups})
        self.wrap_second = (combined, groups, combined_names)                 # S432: for the table at the bottom
        self.wrap_pick = self.pick_repairs(repairs, names)                    # S443: the picked repair, last
        grouping = tuple(sorted(self.wrap_pick["fabrics"]))                   # S449: Document names follow it
        if grouping != self.__dict__.get("pick_grouping") and self.__dict__.get("verify_tab") is not None:
            self.pick_grouping = grouping
            self.root.after(0, self.show_verify_item)
        second = self.wrap_table_rows(combined, combined_names, warn=False) if groups else None
        if not draw:                                    # S370: the tab is not on show
            return
        columns = ["Start and End", "Overlap (Regular)", f"Overlap ({PLUS_LABEL})",
                   "Overlap (Combined)", "Wheel count",                                                  # S428
                   f"Distance {WC_CELLS['distance']} ({WC_CELLS['distance_ft']})",                         # S307/S308
                   f"Distance inside a wrap {WC_CELLS['distance']} ({WC_CELLS['distance_ft']})",           # S309
                   "Defect Length (in)", "Linear Length of Repair - Corrosion",
                   f"Linear Length of Repair - Corrosion {PLUS_LABEL} ({PLUS_CELLS['plus']})",           # S437
                   "Linear Length of Repair - Mechanical",
                   f"Linear Length of Repair - Mechanical {PLUS_LABEL} ({PLUS_CELLS['plus']})"]
        ttk.Label(self.wc_frame, text="Wrap start and end among the wheel counts (worked out by the calculator)",
                  font=("Segoe UI", 12, "bold", "underline")).pack(pady=(24, 4))
        ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                  text=f"Each Linear Length of Repair goes into the '{WC_SHEET}' sheet: the wheel count in "
                       f"{WRAP_CELLS['wheel']}, the full repair length in {WRAP_CELLS['repair']}, 0 in {WRAP_CELLS['zero']} and "
                       f"{WRAP_CELLS['zero2']}; "
                       f"read back: the wrap's start ({WRAP_CELLS['start']}) and end ({WRAP_CELLS['end']}). All in "
                       f"number order.").pack(pady=(0, 6))
        add_simple_table(self.wc_frame, columns, first["rows"], wraplength=240, colours=first["colours"])
        if second is None:
            return
        ttk.Label(self.wc_frame, text="Wrap start and end with the overlapping wheel counts as one repair "
                                      "(worked out by the calculator)",
                  font=("Segoe UI", 12, "bold", "underline")).pack(pady=(24, 4))
        ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                  text="The wheel counts whose regular wraps overlap (Overlap (Regular) above) worked out as one "
                       "repair, all by the calculator: its wheel counts smallest first in "
                       f"{COMBINED_CELLS['wheels']} and their defect lengths in {COMBINED_CELLS['lengths']} (the rest 0) "
                       f"-> {COMBINED_CELLS['length']} = its total defect length (into E15, with the first one's Outside "
                       f"Diameter and Wall Thickness), {COMBINED_CELLS['plain']} = its middle without the defects, "
                       f"{COMBINED_CELLS['middle']} = its middle with them, into {WRAP_CELLS['wheel']} for every wrap "
                       "start / end as above. "
                       + "; ".join(f"{g}: {info}" + self.combined_middles_text(g) for g, info in groups.items())
                  ).pack(pady=(0, 6))
        add_simple_table(self.wc_frame, columns, second["rows"], wraplength=240, colours=second["colours"])

    def pick_view(self, entry, fabric):
        """S443: a repair as the picked fabric shows it - only that fabric's lengths and wraps (E-Glass: Corrosion
        C27, no isolation wrap; Carbon: the carbon wrap Mechanical C26 and the isolation wrap C26 + 12 (H2))."""
        out = entry.get("out")
        if not isinstance(out, dict):
            return entry
        pick = FABRIC_PICKS[fabric]
        other = "Corrosion" if pick["length"] == "Mechanical" else "Mechanical"
        view = dict(out, **{other: f"not used ({fabric})"})
        plus = dict(out.get("plus") or {}, **{other: f"not used ({fabric})"})
        if fabric == "E-Glass":
            plus[pick["length"]] = "none (E-Glass)"
        view["plus"] = plus
        view["wraps"] = {k: w for k, w in (out.get("wraps") or {}).items() if k in (pick["length"], pick["reach"])}
        return {"inputs": entry.get("inputs"), "out": view}

    def pick_repairs(self, repairs, names):
        """S443: the repair the program picks: each wheel count's fabric from its anomaly type (fabric_for_type),
        a set of them E-Glass only when every one is; repairs whose picked wraps reach over each other (E-Glass:
        its Corrosion wrap; Carbon: its isolation wrap, C26 + 12) are one repair - worked out by the calculator like
        the combined ones (CO4:DR4 / CO5:DR5 -> CO13 / CO17), and again while that makes new overlaps. Not across a
        bend (WRAP_BARRIER) between them, unless one's reach covers the other's (as S440). Compared only - no
        wheel count arithmetic. Returns what draw_pick_section shows."""
        types = self.__dict__.get("repair_types") or {}
        results = self.__dict__.setdefault("pick_results", {})     # S444: its own - worked out with the fabric set
        fabric_of = {h: fabric_for_type(types.get(h)) for h, e in repairs.items() if e.get("inputs")}
        todo = {}
        barrier_names = {float(h): names.get(h, h) for h in repairs if re.search(WRAP_BARRIER, str(names.get(h, "")), re.I)}
        parent = {}

        def root(x):
            while parent.setdefault(x, x) != x:
                x = parent[x]
            return x

        def units():
            sets = {}
            for header in fabric_of:
                if header in parent:
                    sets.setdefault(root(header), []).append(header)
            found = [sorted(m, key=float) for m in sets.values()]
            inside = {h for m in found for h in m}
            return found + [[h] for h in fabric_of if h not in inside]

        def fabric(members):
            return "E-Glass" if all(fabric_of[m][0] == "E-Glass" for m in members) else "Carbon"

        pipes = self.__dict__.get("repair_pipe") or {}
        # S458: a repair's limits - the nearest separate physical feature each side (a sleeve, a bend, a valve ... -
        # never a girth weld, never an anomaly)
        limits = sorted(float(h) for h in repairs if h not in fabric_of and re.search(WRAP_BARRIER, str(names.get(h, "")), re.I)
                        and not re.search(r"wrinkle|girth", str(names.get(h, "")), re.I))

        def entry(members):
            """S444: this repair worked out with its fabric set - asked of the calculator when new. S458: with all it
            puts into the calculator (Pipe Grade, Class Location, largest depth / width, Corrosion / Mechanical) and
            its Wheel Count Calculator check (first / last wheel count with their lengths, limits)."""
            name = " & ".join(members)
            values = (dict(repairs[name]["inputs"]) if len(members) == 1 else combined_values(repairs, members))
            if values is None:
                return {"inputs": None, "out": None}
            values["fabric"] = fabric(members)
            values["extra"] = {"E7": repair_grade(pipes, members)[0], "E10": repair_class(pipes, members)[0],
                               "E13": repair_largest(pipes, members, "Depth")[0],
                               "E16": repair_largest(pipes, members, "Width")[0],
                               "C15": "Corrosion" if values["fabric"] == "E-Glass" else "Mechanical"}
            low, high = float(members[0]), float(members[-1])
            values["check"] = {"first": (low, float(repairs[members[0]]["inputs"]["Length"])),
                               "last": (high, float(repairs[members[-1]]["inputs"]["Length"])),
                               "left": max((x for x in limits if x < low), default=None),
                               "right": min((x for x in limits if x > high), default=None)}
            if (results.get(name) or {}).get("inputs") != values:
                results[name] = {"inputs": values, "out": None}
                todo[name] = values
            return results[name]

        def reach(members):
            out = entry(members).get("out")
            ends = ((out.get("wraps") or {}).get(FABRIC_PICKS[fabric(members)]["reach"])
                    if isinstance(out, dict) else None)
            return ends if ends and all(isinstance(v, (int, float)) for v in ends) else None

        joined = []
        while True:                                     # every pair that reaches over each other, all at once
            now = units()
            found = []
            for i, a in enumerate(now):
                ra = reach(a)
                for b in now[i + 1:] if ra else []:
                    rb = reach(b)
                    if not rb or ra[0] > rb[1] or rb[0] > ra[1]:
                        continue                        # do not reach over each other
                    covers = (ra[0] <= rb[0] and ra[1] >= rb[1]) or (rb[0] <= ra[0] and rb[1] >= ra[1])
                    low, high = sorted((a, b), key=lambda m: float(m[0]))
                    gap = (float(low[-1]), float(high[0]))
                    crossed = [barrier_names[x] for x in barrier_names if gap[0] < x < gap[1]]
                    if crossed and not covers:
                        continue                        # a bend between them, neither covers the other
                    differs = repair_pipe_differs(self.__dict__.get("repair_pipe") or {}, a, b)
                    if differs:                         # S452: a different pipe - never one repair (one calculator)
                        said = self.__dict__.setdefault("pick_pipe_said", set())
                        if (tuple(a), tuple(b)) not in said:
                            said.add((tuple(a), tuple(b)))
                            print(f"PICKED REPAIR: {' & '.join(a)} and {' & '.join(b)} reach over each other but are "
                                  f"on a different pipe ({'; '.join(differs)}) - kept as separate repairs (S452)")
                        continue
                    found.append((a, b, f"{' & '.join(a)} ({fabric(a)}) and {' & '.join(b)} ({fabric(b)}) reach over "
                                        f"each other" + (f" - one covers the other, joined across "
                                                         f"{', '.join(crossed)}" if crossed else "")))
            merged = False
            for a, b, why in found:
                if root(a[0]) == root(b[0]):
                    continue
                for x in a + b:
                    root(x)
                parent[root(b[0])] = root(a[0])
                merged = True
                joined.append((set(a + b), why))
                said = self.__dict__.setdefault("pick_joined_said", set())
                if why not in said:
                    said.add(why)
                    print(f"PICKED REPAIR: {why} - one repair (S443)")
            if not merged:
                break
        final, groups, fabrics = {}, {}, {}
        for members in units():
            name = " & ".join(members)
            fabrics[name] = fabric(members)
            if len(members) > 1:
                values = combined_values(repairs, members)
                if values is None:
                    continue
                groups[name] = ", ".join(f"{m} ({verify_short_number(length)} in, {fabric_of[m][0]})"
                                         for m, (_w, length) in zip(members, values["members"]))
                groups[name] += "".join(f" ({why})" for every, why in joined if every <= set(members))
            final[name] = self.pick_view(entry(members), fabrics[name])
        inside = {m for name in groups for m in name.split(" & ")}
        for header, item in repairs.items():
            if header not in inside and header not in final:
                final[header] = item                   # a girth weld, a bend ... - no repair of its own
        singles = {h: (self.pick_view(entry([h]), fabric_of[h][0]) if h in fabric_of else e)
                   for h, e in repairs.items()}
        self.ask_combined(todo, groups, store="pick_results", picked=True)
        return {"fabric_of": fabric_of, "singles": singles, "final": final, "groups": groups, "fabrics": fabrics}

    def draw_pick_section(self):
        """S443: at the very bottom of the WC Distances tab - the repair the program picks (Carbon or E-Glass) and
        every table it took to get there: the fabric of each wheel count, their picked wraps, the picked repairs
        (overlapping ones as one), what each repair is, and the distances between them."""
        pick = self.__dict__.get("wrap_pick")
        if not pick or not pick["fabric_of"]:
            return
        names = self.__dict__.get("repair_names") or {}
        types = self.__dict__.get("repair_types") or {}
        number = lambda v: verify_short_number(v) if isinstance(v, (int, float)) else ("-" if v is None else str(v))
        heading = lambda text: ttk.Label(self.wc_frame, text=text, font=("Segoe UI", 12, "bold", "underline"))
        note = lambda text: ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center", text=text)
        ttk.Label(self.wc_frame, text="The repair it picks - Carbon or E-Glass",
                  font=("Segoe UI", 14, "bold")).pack(pady=(36, 2))
        note("By the anomaly type: only corrosion / metal loss (External / Internal) -> E-Glass, its Linear Length of "
             "Repair = Corrosion C27 and nothing under it; anything else, corrosion with something else, or no type "
             "found -> Carbon: the carbon wrap = Mechanical C26 with the isolation wrap under it = C26 + 12 (H2), "
             "which is how far it reaches. A repair made of several wheel counts is E-Glass only when every one is. "
             "Repairs that reach over each other are one repair (not across a bend unless one covers the other) - "
             "all lengths, middles and wrap ends from the calculator, each repair worked out with its fabric set "
             f"(in {FABRIC_BOTH}). "
             "The Group button puts this repair's calculator in the folder.").pack(pady=(0, 6))
        heading("Fabric for each wheel count").pack(pady=(16, 4))
        rows = []
        for header in sorted(pick["fabric_of"], key=float):
            fabric, why = pick["fabric_of"][header]
            out = (pick["singles"].get(header) or {}).get("out")
            spec = FABRIC_PICKS[fabric]
            wrap = out.get(spec["length"]) if isinstance(out, dict) else out
            under = (out.get("plus") or {}).get(spec["length"]) if isinstance(out, dict) else out
            rows.append([names.get(header, header), types.get(header) or "-", fabric, why,
                         f"{number(wrap)} in ({'C26' if spec['length'] == 'Mechanical' else 'C27'})"
                         if isinstance(wrap, (int, float)) else number(wrap),
                         f"{number(under)} in (H2)" if isinstance(under, (int, float)) else number(under)])
        add_simple_table(self.wc_frame, ["Wheel count", "Anomaly type", "Fabric", "Why", "Wrap (in)",
                                         "Isolation wrap under it (in)"], rows, wraplength=320)
        columns = ["Start and End", "Overlap (Regular)", f"Overlap ({PLUS_LABEL})", "Overlap (Combined)",
                   "Wheel count", f"Distance {WC_CELLS['distance']} ({WC_CELLS['distance_ft']})",
                   f"Distance inside a wrap {WC_CELLS['distance']} ({WC_CELLS['distance_ft']})",
                   "Defect Length (in)", "Linear Length of Repair - Corrosion (E-Glass)",
                   f"Corrosion {PLUS_LABEL} ({PLUS_CELLS['plus']})",
                   "Linear Length of Repair - Mechanical (Carbon)",
                   f"Mechanical {PLUS_LABEL} ({PLUS_CELLS['plus']}) - isolation wrap (Carbon)"]
        heading("Wrap start and end of each wheel count with its picked fabric").pack(pady=(24, 4))
        note("Each wheel count's wraps for its fabric only (E-Glass: the Corrosion wrap; Carbon: the carbon wrap and "
             "the isolation wrap under it, '+12'), placed by the calculator as above (K3 / M6 -> J3 / L3).").pack(pady=(0, 6))
        first = self.wrap_table_rows(pick["singles"], names, warn=False)
        add_simple_table(self.wc_frame, columns, first["rows"], wraplength=240, colours=first["colours"])
        final_names = dict(names, **{g: f"{g} (one repair)" for g in pick["groups"]})
        heading("Wrap start and end of the picked repairs").pack(pady=(24, 4))
        note("The repairs that reach over each other worked out as one by the calculator (CO4:DR4 / CO5:DR5 -> CO13 "
             "total defect length into E15, CO17 middle into K3). "
             + "; ".join(f"{g}: {info}" + self.combined_middles_text(g, "pick_results")
                         for g, info in pick["groups"].items())
             ).pack(pady=(0, 6))
        second = self.wrap_table_rows(pick["final"], final_names, warn=False)
        add_simple_table(self.wc_frame, columns, second["rows"], wraplength=240, colours=second["colours"])
        heading("The picked repairs").pack(pady=(24, 4))
        rows = []
        for name, item in sorted(pick["final"].items(), key=lambda kv: float(kv[0].split(" & ")[0])):
            if name not in pick["fabrics"]:
                continue                                # a girth weld, a bend ... - no repair
            fabric = pick["fabrics"][name]
            spec = FABRIC_PICKS[fabric]
            out = item.get("out")
            if not isinstance(out, dict):
                rows.append([final_names.get(name, name), fabric, number(out)] + ["-"] * 5)
                continue
            reach = (out.get("wraps") or {}).get(spec["reach"]) or (None, None)
            under = (out.get("plus") or {}).get(spec["length"])
            rows.append([final_names.get(name, name), fabric, number(repair_defect_length(item)),
                         f"{number(out.get(spec['length']))} in ({'C26' if spec['length'] == 'Mechanical' else 'C27'})",
                         f"{number(under)} in (H2)" if isinstance(under, (int, float)) else number(under),
                         number(reach[0]), number(reach[1]),
                         number(out.get("middle")) if " & " in name else name])
        add_simple_table(self.wc_frame, ["Repair", "Fabric", "Defect Length (in)", "Wrap (in)",
                                         "Isolation wrap under it (in)", "Reaches from (J3)", "Reaches to (L3)",
                                         "Middle (K3)"], rows, wraplength=320)
        self.draw_wrap_check_table(pick, final_names)                        # S458
        self.draw_combined_distance_table(pick["final"], final_names, every_wrap=True,
                                          title="Wheel count distances with the picked repairs "
                                                "(worked out by the calculator)")

    def draw_wrap_check_table(self, pick, final_names):
        """S458/S462: under 'The picked repairs' - each picked repair's check on the Wheel Count Calculator sheet, as
        two tables: by its first and last wheel count (every repair), and as one defect (the combined ones). Each row:
        what went in / came out, next to what the other calculations found (S461); red: past a limit, or different."""
        number = lambda v: verify_short_number(v) if isinstance(v, (int, float)) else ("-" if v in (None, "") else str(v))
        common = (f"Into the '{WC_SHEET}' sheet once the repair's calculator is filled in (as the Group calculator is), "
                  f"with the nearest separate physical feature each side (not a girth weld or a defect - e.g. a sleeve) "
                  f"in {WRAP_CHECK_CELLS['left']} / {WRAP_CHECK_CELLS['right']} (blank when there is none); read back "
                  f"{WRAP_CHECK_CELLS['wrap']} / {WRAP_CHECK_CELLS['l_over']} and C{WRAP_CHECK_ROWS[0]}:"
                  f"D{WRAP_CHECK_ROWS[-1]}. Next to each: what the other calculations found - the wrap's start / end "
                  f"(J3 / L3), middle (CO17 / K3) and length (C26 / C27). Red: past a limit, or different.")
        tables = [("Wrap check - first and last wheel count (worked out by the calculator)", "check",
                   f"Each picked repair's first and last wheel count in {WRAP_CHECK_CELLS['wc1']} / "
                   f"{WRAP_CHECK_CELLS['wc2']} (one anomaly: both the same) with their own defect lengths in "
                   f"{WRAP_CHECK_CELLS['length1']} / {WRAP_CHECK_CELLS['length2']}. "),
                  ("Wrap check - combined repairs as one defect (worked out by the calculator)", "check_whole",
                   f"Each combined repair as one defect: its middle (CO17) in both {WRAP_CHECK_CELLS['wc1']} / "
                   f"{WRAP_CHECK_CELLS['wc2']} and its total defect length (CO13) in both {WRAP_CHECK_CELLS['length1']} / "
                   f"{WRAP_CHECK_CELLS['length2']}. ")]
        for title, key, about in tables:
            rows, colours = [], {}
            for name, item in sorted(pick["final"].items(), key=lambda kv: float(kv[0].split(" & ")[0])):
                if name not in pick["fabrics"] or (key == "check_whole" and " & " not in name):
                    continue
                out = item.get("out")
                check = out.get(key) if isinstance(out, dict) else None
                label = final_names.get(name, name)
                if not check:
                    rows.append([label, "", "calculating ..." if not isinstance(out, dict) else "-", "", "", "", "", ""])
                    continue
                other = self.wrap_check_other(name, out, pick["fabrics"][name])
                for cell, what, value, past in self.wrap_check_rows(check).values():
                    found = next((v for words, v in other if all(w in what.lower() for w in words)), None)
                    compared = ""
                    if isinstance(value, (int, float)) and isinstance(found, (int, float)):
                        compared = "✔ same" if abs(value - found) < 1e-6 else "different"   # float noise only
                    # S462: a length (inches) and a wheel count (feet) never in one column
                    length = what in WRAP_CHECK_LENGTH_ROWS
                    if past:
                        colours[(len(rows), 4 if length else 3)] = "#c62828"
                    if compared == "different":
                        colours[(len(rows), 7)] = "#c62828"
                    shown, other_shown = number(value), number(found) if found is not None else ""
                    rows.append([label, cell, what + (f" - {past}" if past else ""),
                                 "" if length else shown, shown if length else "",
                                 "" if length else other_shown, other_shown if length else "", compared])
                    label = ""
            if not rows:
                continue                                # no combined repair - no second table
            ttk.Label(self.wc_frame, text=title, font=("Segoe UI", 12, "bold", "underline")).pack(pady=(24, 4))
            ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                      text=about + common).pack(pady=(0, 6))
            add_simple_table(self.wc_frame, ["Repair", "Cell", "What", "Wheel count (ft)", "Length (in)",
                                             "Other calculations - wheel count (ft)", "Other calculations - length (in)",
                                             "Compared"], rows, wraplength=360, colours=colours)

    def wrap_check_other(self, name, out, fabric):
        """S461: what the program's other calculations found for this picked repair, to set next to the check's
        rows - [(words its row name has, value)]: its wrap's start / end (J3 / L3) and length (C26 Carbon / C27
        E-Glass), its middle (CO17 - a single wheel count: itself, K3)."""
        length = FABRIC_PICKS[fabric]["length"]
        ends = (out.get("wraps") or {}).get(length) or (None, None)
        middle = out.get("middle") if " & " in name else float(name)
        return [(("start", "wrap"), ends[0]), (("end", "wrap"), ends[1]), (("middle",), middle),
                (("linear length of wrap",), out.get(length))]

    def wrap_check_rows(self, check):
        """S458/S460: one run of the wrap check by row name - {name: (cell, name, value, 'past the left / right
        limit' or '')}: what went in (D2 / D3 / D9 / D10 / D7 / D8), D5 / D6, then C13:D41 (red when past a limit -
        compared only)."""
        given = check["given"]
        found = {}
        for cell, what, value in ((WRAP_CHECK_CELLS["wc1"], "1st WC", given["first"][0]),
                                  (WRAP_CHECK_CELLS["wc2"], "2nd WC", given["last"][0]),
                                  (WRAP_CHECK_CELLS["length1"], "Defect Length 1 (in)", given["first"][1]),
                                  (WRAP_CHECK_CELLS["length2"], "Defect Length 2 (in)", given["last"][1]),
                                  (WRAP_CHECK_CELLS["left"], "Left Limit", given["left"]),
                                  (WRAP_CHECK_CELLS["right"], "Right Limit", given["right"]),
                                  (WRAP_CHECK_CELLS["wrap"], "Linear Length of Wrap (calculator)", check["wrap"]),
                                  (WRAP_CHECK_CELLS["l_over"], "L_over (calculator)", check["l_over"])):
            found[what] = (cell, what, value, "")
        for row, what, value in check["rows"]:
            past = ""
            if isinstance(value, (int, float)) and "limit" not in str(what).lower():
                if given["left"] is not None and value < given["left"]:
                    past = "past the left limit"
                elif given["right"] is not None and value > given["right"]:
                    past = "past the right limit"
            key = " ".join(str(what or f"row {row}").split())
            found[key] = (f"D{row}", key, value, past)
        return found

    def combined_middles_text(self, name, store="combined_results"):
        """S439: ' -> total ... in, middle ... (no defects ...)' of a combined repair, as the calculator gave them."""
        out = ((self.__dict__.get(store) or {}).get(name) or {}).get("out")
        if not isinstance(out, dict):
            return ""
        number = lambda v: verify_short_number(v) if isinstance(v, (int, float)) else ("-" if v is None else str(v))
        return (f" -> total defect length {number(out.get('full_length'))} in ({COMBINED_CELLS['length']}), middle "
                f"{number(out.get('middle'))} ({COMBINED_CELLS['middle']}; without the defects "
                f"{number(out.get('middle_plain'))}, {COMBINED_CELLS['plain']})")

    def wrap_table_rows(self, repairs, names, warn):
        """S302-S319/S428/S429: the rows of a wrap table for these repairs ({name: {'inputs', 'out'}}; a name is a
        wheel count, or a combined repair's 'A & B', placed at its middle CO17 - S439): its rows, their cell
        colours and the overlaps of two regular wraps ([(name, name)]). The distances between its rows are asked
        of Excel when new; warn=True: the overlaps are the wrap overlap warnings."""
        number = lambda v: verify_short_number(v) if isinstance(v, (int, float)) else ("-" if v is None else str(v))
        # S434: a combined one at its first wheel count; S439: at its middle (CO17) once the calculator gave it
        where = lambda header, entry: (entry["out"]["middle"] if isinstance(entry.get("out"), dict)
                                       and isinstance(entry["out"].get("middle"), (int, float))
                                       else float(header.split(" & ")[0]))
        lines = []                                      # (sort value, row)
        owners = {}                                     # S441: id(row) -> the wheel count / repair the row is
        for header, entry in repairs.items():
            out = entry["out"]
            keys = [k for n in REPAIR_OUTPUT_CELLS for k in wrap_keys(n)]   # S316: + 12 columns too
            if isinstance(out, dict):
                llr = {}
                for n in REPAIR_OUTPUT_CELLS:          # S437: the + 12 length as the calculator gave it (H2)
                    for k, v in zip(wrap_keys(n), (out.get(n), (out.get("plus") or {}).get(n))):
                        llr[k] = f"{number(v)} in" if isinstance(v, (int, float)) else number(v)   # S305: '12 in'
            else:
                llr = {k: ("calculating ..." if out is None else out) for k in keys}
            length = repair_defect_length(entry)
            lines.append((where(header, entry), ["", names.get(header, header),
                                                 number(length) if length is not None else "-"] + [llr[k] for k in keys]))
            owners[id(lines[-1][1])] = header
            wraps = (out.get("wraps") or {}) if isinstance(out, dict) else {}
            for which, at in (("start", 0), ("end", 1)):
                by_value = {}
                for name, ends in wraps.items():
                    if isinstance(ends[at], (int, float)):
                        by_value.setdefault(ends[at], []).append(name)
                for value, kinds in by_value.items():
                    for plus in sorted({k.partition(" ")[2] for k in kinds}):          # S316: '' or '+12'
                        mine = [k for k in kinds if k.partition(" ")[2] == plus]
                        cells = [llr[k] if k in mine else "" for k in keys]          # S305: just its length
                        label = f"{header} {plus} {which}" if plus else f"{header} {which}"
                        lines.append((float(value), [label, number(value), "-"] + cells))   # S303/S304
                        owners[id(lines[-1][1])] = header
        lines.sort(key=lambda line: line[0])
        # S307: the distance from the row above (T22 in / T23 ft) - worked out by the calculator
        found = self.__dict__.setdefault("wrap_distances", {})
        asked = self.__dict__.setdefault("wrap_distances_asked", set())
        pairs = [(a, b) for (a, _r), (b, _s) in zip(lines, lines[1:])]      # S435: as the calculator gave them
        new = [p for p in pairs if p not in found and p not in asked]
        if new and self.__dict__.get("repair_excel") is not None:
            asked.update(new)

            def done(answer, new=new):
                def shown():
                    if isinstance(answer, BaseException):
                        print(f"WRAP DISTANCES: could not be worked out - {answer} (S307)")
                        for p in new:
                            found[p] = ("Excel: " + str(answer),) * 2
                    else:
                        found.update(answer)
                        print(f"WRAP DISTANCES: {len(answer)} distance(s) between the table's rows worked out (S307)")
                    self.refresh_wc_tab()
                self.root.after(0, shown)
            self.repair_excel.submit_distances(new, done)
        # S318: wraps of different wheel counts that overlap - every row inside the overlap is marked, and it is
        # a warning; S319: any kind with any kind (12 in with 12 + 12 in too) - only the same wheel count is skipped
        spans = {}
        for value, row in lines:
            label = re.match(r"^(.*?)(?: (\+\S+))? (start|end)$", str(row[0]))   # S429: 'A & B +12 start' too
            if label:
                key = (label.group(1), label.group(2) or "")            # (wheel count / 'A & B', '' or '+12')
                low, high = spans.get(key, (value, value))
                spans[key] = (min(low, value), max(high, value))
        overlaps = []                                   # (low, high, text, kind)
        keys = sorted(spans)
        for i, a in enumerate(keys):
            for b in keys[i + 1:]:
                if a[0] != b[0]:                        # S319: any wraps of two different wheel counts
                    low, high = max(spans[a][0], spans[b][0]), min(spans[a][1], spans[b][1])
                    if low <= high:
                        # '100553.07 +12'; S430b: a combined repair's name in brackets - '(A & B) +12'
                        one, two = (" ".join(k for k in ((f"({key[0]})" if " & " in key[0] else key[0]), key[1]) if k)
                                    for key in (a, b))
                        # S428: which column it goes in - both regular wraps, both + 12 wraps, or one of each
                        kind = "regular" if not a[1] and not b[1] else "plus" if a[1] and b[1] else "mixed"
                        overlaps.append((low, high, f"{one} & {two}", kind, (a[0], b[0]), {a: one, b: two}))
        # S428: three Overlap columns - Regular (both wraps without + 12), + 12 (both with + 12), Combined (every
        # overlap, the one column there was before)
        overlap_kinds = (("regular",), ("plus",), ("regular", "plus", "mixed"))
        # S441: each cell names only the OTHER wraps in those overlaps (each once), not every pair
        def other_wraps(value, row, kinds):
            mine = owners.get(id(row))
            shown = {}
            for low, high, _t, kind, _w, wraps in overlaps:
                if low <= value <= high and kind in kinds:
                    for key, text in wraps.items():
                        if key[0] != mine:
                            shown.setdefault(key, text)
            return " / ".join(shown[k] for k in sorted(shown, key=lambda k: (float(k[0].split(" & ")[0]), k[1])))
        overlap_cells = [[other_wraps(value, row, kinds) for kinds in overlap_kinds] for value, row in lines]
        if warn:
            warnings = [f"The wraps of {t} overlap between {verify_short_number(low)} and "
                        f"{verify_short_number(high)}" for low, high, t, _kind, _w, _k in overlaps]
            if warnings != self.__dict__.get("wrap_overlap_warnings"):
                self.wrap_overlap_warnings = warnings
                print("WRAP OVERLAP: " + ("; ".join(warnings) if warnings else "no wraps overlap") + " (S318)")
                if self.__dict__.get("warnings_args"):
                    self.root.after(0, lambda: self.refresh_warnings_tab(*self.warnings_args))
        cell_colours = {}
        table_rows = []                                 # S307: a distance row of its own between every two rows
        open_wraps = 0                                  # S309: wraps started above and not ended yet
        for n, (_v, row) in enumerate(lines):
            if n:                                       # S308: one column 'T22 in (T23 ft)', before Defect Length
                got = found.get(pairs[n - 1])
                apart = (f"{number(got[0])} in ({number(got[1])} ft)" if got and isinstance(got[0], (int, float))
                         else got[0] if got else "calculating ...")
                # S309: between a wrap's start and end -> its own column, else the first one
                both = [bool(overlap_cells[n - 1][c] and overlap_cells[n][c]) for c in range(3)]   # S318/S428
                for c in range(3):
                    if both[c]:
                        cell_colours[(len(table_rows), 1 + c)] = "#c62828"
                table_rows.append(["distance"] + ["" for _b in both] + [""]          # S428: red, no word
                                  + (["", apart] if open_wraps > 0 else [apart, ""]) + [""] * (len(row) - 2))
            if row[0].endswith(" start"):
                open_wraps += 1
            elif row[0].endswith(" end"):
                open_wraps = max(0, open_wraps - 1)
            for c in range(3):
                if overlap_cells[n][c]:
                    cell_colours[(len(table_rows), 1 + c)] = "#c62828"
            table_rows.append(row[:1] + overlap_cells[n] + row[1:2] + ["", ""] + row[2:])
        return {"rows": table_rows, "colours": cell_colours,
                "regular": [w for _l, _h, _t, kind, w, _k in overlaps if kind == "regular"]}

    def wrap_combined_repairs(self, repairs, regular, names=None):
        """S429: the wheel counts whose regular wraps overlap (directly or through another one) as one repair each
        - 'A & B': S439: every wheel count and its defect length to the calculator (CO4:DR4 / CO5:DR5), which
        gives its total defect length (CO13) and its middle (CO17, for K3), with the first one's Outside Diameter
        and Wall Thickness; its Linear Length of Repair and wraps worked out by the calculator (asked once per set
        of values). Returns (the repairs for the second table: the combined ones and every wheel
        count not in one, {combined name: how it was made}). S430: never across a bend (or a fitting like it,
        WRAP_BARRIER) between them - the two sides stay apart, and their overlap shows in the second table.
        S440: except when one repair's regular wraps (as the calculator gave them, J3 / L3) cover another's
        completely - then the two are one repair, across a bend too (compared only, no arithmetic)."""
        barrier_names = {float(h): (names or {}).get(h, h) for h in repairs
                         if re.search(WRAP_BARRIER, str((names or {}).get(h, "")), re.I)}
        barriers = sorted(barrier_names)
        parent = {}
        results = self.__dict__.setdefault("combined_results", {})

        def root(x):
            while parent.setdefault(x, x) != x:
                x = parent[x]
            return x
        pipes = self.__dict__.get("repair_pipe") or {}
        for a, b in regular:
            low, high = sorted((float(a), float(b)))
            if any(low < x < high for x in barriers):    # S430: a bend between them - not one repair
                continue
            ra, rb = root(a), root(b)
            if repair_pipe_differs(pipes, [x for x in list(parent) if root(x) == ra],
                                   [x for x in list(parent) if root(x) == rb]):
                continue                                # S452: a different pipe - not one repair
            parent[root(a)] = root(b)

        def units():
            """The repairs as they stand: each set of joined wheel counts, and every other wheel count with a
            repair worked out, each smallest first."""
            sets = {}
            for header in repairs:
                if header in parent:
                    sets.setdefault(root(header), []).append(header)
            found = [sorted(m, key=float) for m in sets.values()]
            inside = {h for m in found for h in m}
            return found + [[h] for h in repairs if h not in inside and repairs[h].get("inputs")]

        def regular_wraps(members):
            """S440: a repair's regular wraps {'Corrosion': (start, end), ...} as the calculator gave them (J3 / L3),
            or None while not worked out."""
            if len(members) == 1:
                out = repairs[members[0]].get("out")
            else:
                entry = results.get(" & ".join(members)) or {}
                out = entry.get("out") if entry.get("inputs") == combined_values(repairs, members) else None
            wraps = (out.get("wraps") or {}) if isinstance(out, dict) else {}
            got = {k: wraps[k] for k in REPAIR_OUTPUT_CELLS
                   if k in wraps and all(isinstance(v, (int, float)) for v in wraps[k])}
            return got or None

        def covers(big, small):
            common = [k for k in big if k in small]
            return bool(common) and all(big[k][0] <= small[k][0] and big[k][1] >= small[k][1] for k in common)

        joined = []                                     # S440: (all their wheel counts, why) - for the notes
        while True:                                     # S440: join a repair whose wraps another one's cover
            now = units()
            found = None
            for i, a in enumerate(now):
                wraps_a = regular_wraps(a)
                for b in now[i + 1:] if wraps_a else []:
                    wraps_b = regular_wraps(b)
                    if wraps_b and (covers(wraps_a, wraps_b) or covers(wraps_b, wraps_a)) \
                            and not repair_pipe_differs(pipes, a, b):          # S452: same pipe only
                        found = (a, b) if covers(wraps_a, wraps_b) else (b, a)
                        break
                if found:
                    break
            if not found:
                break
            big, small = found
            for x in big + small:
                root(x)
            parent[root(small[0])] = root(big[0])
            every = big + small
            low, high = min(float(x) for x in every), max(float(x) for x in every)
            crossed = [barrier_names[x] for x in barriers if low < x < high]
            why = (f"{' & '.join(small)}'s wraps are inside {' & '.join(big)}'s"
                   + (f" - joined across {', '.join(crossed)}" if crossed else " - joined"))
            joined.append((set(every), why))
            said = self.__dict__.setdefault("wrap_joined_said", set())
            if why not in said:
                said.add(why)
                print(f"COMBINED REPAIR: {why} (S440)")
        combined, groups = {}, {}
        todo = {}
        for members in units():
            if len(members) < 2:
                continue
            values = combined_values(repairs, members)
            if values is None:
                continue                                # one of them has no repair worked out - not combined
            name = " & ".join(members)
            pairs = values["members"]
            groups[name] = ", ".join(f"{m} ({verify_short_number(length)} in)" for m, (_w, length) in zip(members, pairs))
            groups[name] += "".join(f" ({why})" for every, why in joined if every <= set(members))   # S440
            if (results.get(name) or {}).get("inputs") != values:
                results[name] = {"inputs": values, "out": None}
                todo[name] = values
            combined[name] = results[name]
        inside = {m for name in groups for m in name.split(" & ")}
        for header, entry in repairs.items():
            if header not in inside:
                combined[header] = entry
        self.ask_combined(todo, groups)
        return combined, groups

    def ask_combined(self, todo, groups, store="combined_results", picked=False):
        """S429/S443: the calculator asked for these combined repairs ({name: values}) - the tab drawn again when
        it answers. S444: picked=True - the picked repairs (each with its fabric), kept in their own store."""
        results = self.__dict__.setdefault(store, {})
        if todo and self.__dict__.get("repair_excel") is None:
            # S446: no calculator copy open yet - not marked as asked, so the next time the tab is worked out
            # (once Excel is ready) they are asked; before, they were kept as 'asked' and never sent
            for name in todo:
                results.pop(name, None)
            said = ("not yet", store, tuple(sorted(todo)))
            if said not in self.__dict__.setdefault("ask_not_yet_said", set()):
                self.ask_not_yet_said.add(said)
                print(f"{'PICKED' if picked else 'COMBINED'} REPAIR: the calculator is not open yet - "
                      f"{', '.join(todo)} asked once it is (S446)")
            return
        if todo and picked:                                                       # S445: what is asked, and when
            asked = self.__dict__.setdefault("pick_asked", {})
            for name, values in todo.items():
                before = asked.get(name)
                asked[name] = (values, time.perf_counter())
                print(f"PICKED REPAIR: asking the calculator for {name} ({values.get('fabric')})"
                      + (f" AGAIN - last asked {time.perf_counter() - before[1]:.1f} s ago"
                         + (" with the same values" if before[0] == values else " with other values")
                         if before else "")
                      + f" - {self.repair_excel.jobs.qsize()} calculator job(s) waiting ahead (S445)")
        if todo and self.__dict__.get("repair_excel") is not None:
            def done(answer, todo=dict(todo)):
                def shown():
                    for name, values in todo.items():
                        entry = results.get(name)
                        if entry is None or entry["inputs"] != values:
                            continue
                        entry["out"] = (f"Excel: {answer}" if isinstance(answer, BaseException)
                                        else (answer.get(name) if isinstance(answer, dict) else None))
                    for name, values in todo.items():
                        out = (results.get(name) or {}).get("out")
                        if picked:                         # S444
                            print(f"PICKED REPAIR: {name} ({values.get('fabric')} in "
                                  f"{FABRIC_BOTH}) -> "
                                  + (f"total defect length {out.get('full_length', values.get('Length'))} in, Corrosion "
                                     f"C27 = {out.get('Corrosion')} in, Mechanical C26 = {out.get('Mechanical')} in, "
                                     f"+12 (H2) = {(out.get('plus') or {}).get('Mechanical')} in"
                                     if isinstance(out, dict) else str(out)) + " (S444)")
                            continue
                        print(f"COMBINED REPAIR: {name}: {groups.get(name, '')} -> "
                              + (f"{COMBINED_CELLS['length']} total defect length = {out.get('full_length')} in, "
                                 f"{COMBINED_CELLS['plain']} middle without the defects = {out.get('middle_plain')}, "
                                 f"{COMBINED_CELLS['middle']} middle with them = {out.get('middle')} -> Corrosion C27 = "
                                 f"{out.get('Corrosion')} in, Mechanical C26 = {out.get('Mechanical')} in"
                                 if isinstance(out, dict) else str(out)) + " (S429/S439)")
                    self.refresh_wc_tab()
                self.root.after(0, shown)
            (self.repair_excel.submit_picked if picked else self.repair_excel.submit_combined)(todo, done)

    def wc_tab_opened(self):
        """S370: WC Distances / Main Wheel Counts opened - drawn now if something changed while it was not on
        show."""
        if not self.__dict__.get("wc_stale") or self.__dict__.get("wc_tab") is None:
            return
        if self.notebook.select() in (str(self.wc_tab), str(self.__dict__.get("main_wc_tab") or "")):
            started = time.perf_counter()
            self.refresh_wc_tab()
            print(f"WC DISTANCES: tab drawn as it was opened in {time.perf_counter() - started:.2f} s (S370)")

    def refresh_wc_tab(self):
        """S296: the WC Distances tab drawn again with what it showed last (or, before the distances are
        worked out, with the repair lengths only)."""
        self.show_wheel_count_distances(*self.__dict__.get(
            "wc_shown", ([], "The wheel count distances come once every document is read.")))

    def prepare_wheel_count_excel(self):
        """S289: a document was dropped in - Excel starts and opens the calculator copy now, while the
        documents are read, so the distances are ready soon after the reading ends."""
        if self.__dict__.get("wc_excel") is not None:
            return
        template = find_calculator()
        if template is not None:
            self.wc_excel = WheelCountExcel(template)

    def stop_wheel_count_excel(self):
        """S289: an Excel started early that has no job (or the window closes) is closed - its copy deleted."""
        excel, self.wc_excel = self.__dict__.get("wc_excel"), None
        if excel is not None:
            threading.Thread(target=excel.stop, daemon=True).start()

    def start_wheel_count_distances(self):
        if self.__dict__.get("verify_hold") and self.verify_view == "compare":
            return                                      # S317: after the choosing (release_verify_hold)
        self._start_wheel_count_distances()

    def _start_wheel_count_distances(self):
        """S273: the wheel counts found are paired with the one next to
        them and each pair's distance is worked out by the calculator in Excel (in the background); the
        results go on the 'WC Distances' tab. Done again only when the pairs change. S469: no longer only once
        every document is read - while documents are still being read, the anomalies of every dig whose documents
        are all read (dig_settled) are worked out, and each dig that finishes is added; one Excel job at a time (a
        change meanwhile is worked out right after the job)."""
        if self.__dict__.get("wc_jobs_running", 0) > 0:
            self.wc_rerun = True                          # S469: right after the job running now
            return
        loading = self.loading_documents()
        if loading:
            # S473: the end table is worked out again only when another dig's documents are all read - not after
            # every document (2-3 s each time, on the window's thread, while the next packet is read)
            ready = verify_ready_headers(self.verify_blocks)
            settled = {h for h in ready if self.dig_settled(h, ready) is None}
            if not settled or settled == self.__dict__.get("wc_settled_last"):
                return
            self.wc_settled_last = settled
        headers, rows, _colours, _picks = self.verify_table()
        found = wheel_counts_found(headers, rows)
        if loading:                                       # S469: only the digs whose documents are all read
            held = {w["header"]: self.dig_settled(w["header"], ready) for w in found}
            found = [w for w in found if held[w["header"]] is None]
            if found != self.__dict__.get("wc_said_found"):
                print(f"WC DISTANCES: worked out now for {', '.join(w['header'] for w in found) or 'nothing yet'} - "
                      f"still waiting: " + "; ".join(f"{h} ({why})" for h, why in held.items() if why) + " (S469)")
            self.wc_said_found = found
        if loading and not found:
            return                                        # S469: no dig is complete yet - nothing to work out
        neighbours = wheel_count_neighbours(found)
        # S287: the main wheel counts - those mentioned in more than one place in the documents - each with
        # every other wheel count; run in the same Excel visit (the smaller wheel count in R3)
        mentions = wheel_count_mentions(self.verify_blocks)
        for w in found:
            w["mentions"] = mentions.get(w["header"], 0)
        on_forms = wheel_count_on_forms(self.verify_blocks)               # S294: page 1 / the 6000 - main too
        for w in found:
            w["form"] = w["header"] in on_forms
        mains = [w for w in found if w["mentions"] > 1 or w["form"]]
        # S477: a main wheel count is paired only with the wheel counts of its own pipeline (the end table's Line ID,
        # e.g. 'SHC 20-1'); when either Line ID is not known they are still paired, as before
        by_label = {row[0]: row for row in rows}
        line_of = {w["header"]: line_id_key(end_table_value(headers, by_label, w["header"], "Line ID")) for w in found}
        main_pairs = [(m, o) for m in mains for o in found if o is not m
                      and (not line_of[m["header"]] or not line_of[o["header"]]
                           or line_of[m["header"]] == line_of[o["header"]])]
        left_out = sum(1 for m in mains for o in found if o is not m) - len(main_pairs)
        if left_out and left_out != self.__dict__.get("wc_lines_said"):
            print(f"WC DISTANCES: main wheel counts paired only within their own Line ID - {len(main_pairs)} pair(s) "
                  f"kept, {left_out} with a wheel count on another pipeline left out (S477)")
        self.wc_lines_said = left_out
        pairs = list({tuple(sorted((a["header"], b["header"]))): tuple(sorted((a, b), key=lambda w: w["feet"]))
                      for a, b in neighbours + main_pairs}.values())
        focus, _left = verify_focus_columns(self.verify_blocks, [w["header"] for w in found])   # S427: the anomalies
        clocks_in = clock_inputs(headers, rows, found, set(focus))     # S425: the Clock Calculator sheet's pairs
        clocks = clock_pairs(clocks_in)
        key = (tuple((a["header"], a["feet"], a["length"], b["header"], b["feet"], b["length"]) for a, b in pairs),
               tuple(m["header"] for m in mains),
               tuple((i["name"], i["hour"], i["minute"], i["width"], i["diameter"]) for i in clocks_in))
        if key == self.__dict__.get("wc_key"):
            if not loading:
                self.stop_wheel_count_excel()             # S289: nothing new to work out (S469: kept while reading)
            last = self.__dict__.get("wc_last")
            names = {w["header"]: w["shown"] for w in found}
            if last and any(w["shown"] != names.get(w["header"], w["shown"]) for w in last[3]):
                # S291: only a name changed (a pick) - the same distances, shown with the new names; no Excel
                shown, problem, mains_shown, old_found = last
                for w in old_found + [x for r in shown for x in (r["first"], r["second"])] + \
                        [x for others in mains_shown.values() for r in others.values() for x in (r["first"], r["second"])]:
                    w["shown"] = names.get(w["header"], w["shown"])
                    w["name"] = {x["header"]: x["name"] for x in found}.get(w["header"], w.get("name"))   # S292
                print("WC DISTANCES: names updated after a pick - distances unchanged, Excel not needed (S291)")
                self.show_wheel_count_distances(shown, problem, mains_shown, old_found)
                clock_last = self.__dict__.get("clock_last")             # S425: the same, with the new names
                if clock_last:
                    self.show_clock_distances(*clock_last)
            return
        self.wc_key = key
        template = find_calculator()
        if not pairs:
            if not loading:
                self.stop_wheel_count_excel()             # S289: opened early for nothing (S469: kept while reading)
            self.show_wheel_count_distances([], "Fewer than two wheel counts found - no distances to work out.")
            self.show_clock_distances([], "Fewer than two wheel counts found - no clock distances to work out.",
                                      clocks_in)
            return
        if template is None:
            self.stop_wheel_count_excel()
            self.show_wheel_count_distances([], f"The calculator was not found ({calculator_missing_text()}).")
            self.show_clock_distances([], f"The calculator was not found ({calculator_missing_text()}).",
                                      clocks_in)
            return
        last = self.__dict__.get("wc_last")
        if last:
            # S295: the values shown stay while Excel works - only what changes says 'recalculating'
            old = {w["header"]: (w["feet"], w["length"]) for w in last[3]}
            new = {w["header"]: (w["feet"], w["length"]) for w in found}
            changed = {h for h in set(old) | set(new) if old.get(h) != new.get(h)}
            moved = {h for h in set(old) | set(new) if (old.get(h) or (None,))[0] != (new.get(h) or (None,))[0]}
            pending = {k for r in last[0] + [r for others in last[2].values() for r in others.values()]
                       for k in [tuple(sorted((r["first"]["header"], r["second"]["header"])))] if set(k) & changed}
            pending_mains = {m for m, others in last[2].items() if moved & (set(others) | {m})}
            if {m["header"] for m in mains} != set(last[2]):
                pending_mains |= set(last[2])           # the main wheel counts themselves changed
            self.show_wheel_count_distances(last[0], f"Recalculating {len(pending) or len(pairs)} distance(s) in Excel ...",
                                            last[2], last[3], pending=pending, pending_mains=pending_mains)
        else:
            self.show_wheel_count_distances([], f"Working out {len(pairs)} distance(s) in Excel ...")
        self.show_clock_distances([], f"Working out {len(clocks)} clock distance(s) in Excel ..." if clocks else
                                  "No anomaly has a clock position, a width and an outside diameter to pair.",
                                  clocks_in)
        # S475: a pair the calculator already worked out in this run with the same inputs (the same wheel counts and
        # defect lengths; for a clock pair the same hours, minutes, widths and diameter) is not sent again - its
        # outputs are the calculator's own from then; only new or changed pairs go to Excel
        cache = self.__dict__.setdefault("wc_pair_cache", {})
        clock_cache = self.__dict__.setdefault("clock_pair_cache", {})
        todo = [(a, b) for a, b in pairs if wc_pair_inputs(a, b) not in cache]
        clock_todo = [(a, b) for a, b in clocks if clock_pair_inputs(a, b) not in clock_cache]
        if todo or clock_todo:
            excel = self.__dict__.get("wc_excel") or WheelCountExcel(template)     # S289: opened early if it could
            self.wc_excel = None                                                  # this job uses it up
        else:
            excel = None                                  # S475: every pair already worked out - no Excel
            if not loading:
                self.stop_wheel_count_excel()
        self.wc_jobs_running = self.__dict__.get("wc_jobs_running", 0) + 1     # S463: WC / Clock tabs wait
        neighbour_keys = [(a["header"], b["header"]) for a, b in neighbours]
        main_rows = [(m["header"], tuple(sorted((m["header"], o["header"]))))
                     for m, o in main_pairs]

        def work():
            started = time.perf_counter()
            fresh, clock_fresh, problem, clock_problem = [], [], None, None
            if excel is not None:
                try:
                    answer = excel.run(todo, clock_todo)
                    fresh, clock_fresh, clock_problem = answer["distances"], answer["clock"], answer["clock_problem"]
                except ImportError:
                    problem = "needs: pip install pywin32"
                except Exception as exc:
                    problem = f"Excel could not work them out ({exc})"
            for r in fresh:                               # S475: kept for the rest of the run
                cache[wc_pair_inputs(r["first"], r["second"])] = {k: r[k] for k in WC_RESULT_KEYS}
            for r in clock_fresh:
                clock_cache[clock_pair_inputs(r["first"], r["second"])] = {"apart": r["apart"],
                                                                             "warnings": list(r["warnings"])}
            results = [dict(cache[k], first=a, second=b) for a, b in pairs for k in [wc_pair_inputs(a, b)]
                       if k in cache]
            clock_results = [dict(clock_cache[k], first=a, second=b, warnings=list(clock_cache[k]["warnings"]))
                             for a, b in clocks for k in [clock_pair_inputs(a, b)] if k in clock_cache]
            clock_problem = clock_problem or (problem if clock_todo else None)
            print(f"CLOCK DISTANCES: {len(clock_results)} of {len(clocks)} pair(s) from the calculator's "
                  f"'{CLOCK_SHEET}' sheet - {len(clock_fresh)} worked out now, {len(clock_results) - len(clock_fresh)} "
                  f"the same as worked out earlier in this run (S475)" + (f" - {clock_problem}" if clock_problem else "")
                  + (f"; not paired (missing a value): " + "; ".join(f"{i['name']} ({', '.join(i['missing'])})"
                                                                    for i in clocks_in if i["missing"])
                     if any(i["missing"] for i in clocks_in) else "") + " (S425)")
            for r in clock_fresh:                         # S475: only the ones worked out now
                print(f"CLOCK DISTANCES: {r['first']['name']} ({r['first']['clock']}, {verify_short_number(r['first']['width'])} in) "
                      f"<-> {r['second']['name']} ({r['second']['clock']}, {verify_short_number(r['second']['width'])} in), "
                      f"OD {verify_short_number(r['first']['diameter'])} in: {CLOCK_CELLS['apart']} = {r['apart']} in"
                      + (f" - WARNING: {' | '.join(r['warnings'])}" if r["warnings"] else "") + " (S425)")
            print(f"WC DISTANCES: {len(results)} of {len(pairs)} pair(s) from the calculator - {len(fresh)} worked out "
                  f"now in {time.perf_counter() - started:.1f} s, {len(results) - len(fresh)} the same as worked out "
                  f"earlier in this run (same wheel counts and defect lengths - not sent again)"
                  + (f" - {problem}" if problem else "") + " (S273/S475)")
            for r in fresh:                               # S475: only the ones worked out now
                print(f"WC DISTANCES: {r['first']['header']} -> {r['second']['header']}: T22 = {r['distance']} in "
                      f"(T23 = {r['distance_ft']} ft), T27 = {r['apart']} in (T28 = {r['apart_ft']} ft) (S273/S277)")
            if self.wc_key == key:                      # not replaced by newer pairs meanwhile
                by_pair = {tuple(sorted((r["first"]["header"], r["second"]["header"]))): r for r in results}
                shown = [by_pair[tuple(sorted(k))] for k in neighbour_keys if tuple(sorted(k)) in by_pair]
                mains_shown = {}                         # main wheel count -> {other wheel count: its result}
                for main, k in main_rows:
                    if k in by_pair:
                        mains_shown.setdefault(main, {})[k[0] if k[1] == main else k[1]] = by_pair[k]
                self.wc_last = (shown, problem, mains_shown, found)          # S291: for a names-only refresh
                self.root.after(0, lambda: self.show_wheel_count_distances(shown, problem, mains_shown, found))
                self.clock_last = (clock_results, clock_problem, clocks_in)  # S425
                self.root.after(0, lambda: self.show_clock_distances(clock_results, clock_problem, clocks_in))

        def job_done():
            """S469: the job is over - a change that came meanwhile is worked out now; while documents are still
            being read, Excel opens the next copy of the calculator for the next dig that finishes."""
            self.wc_jobs_running = max(0, self.__dict__.get("wc_jobs_running", 1) - 1)
            if self.__dict__.get("wc_rerun"):
                self.wc_rerun = False
                self.start_wheel_count_distances()
            if self.loading_documents() and not self.__dict__.get("wc_jobs_running"):
                self.prepare_wheel_count_excel()          # S475: not when a job just started (it opened its own)

        def run_work():                                 # S463: the job counted as running until it is shown
            try:
                work()
            finally:
                self.root.after(0, job_done)

        threading.Thread(target=run_work, daemon=True).start()

    def show_clock_distances(self, results, message, inputs):
        """S425: the 'Clock Distances' tab - every pair of anomalies with a clock position, a width and an outside
        diameter (S427: by anomaly name; and every anomaly with every long seam), through the calculator's Clock Calculator sheet: hour / minutes / width of each in D7-F7 and
        D8-F8, the diameter in D11; read back: the distance apart in L14 (inches - S425b: the shorter of the two ways
        round the pipe, D14 and H14) and F17-F22 - any text there means the two overlap, shown as it is written."""
        if self.__dict__.get("clock_tab") is None:
            self.clock_frame = ttk.Frame(self.add_scroll_tab("Clock Distances", removable=False))
            self.clock_frame.pack(fill="x")
            self.clock_tab = self.notebook.tabs()[-1]
            after = self.__dict__.get("wc_tab")
            self.notebook.insert(self.notebook.index(after) + 1 if after else 2, self.clock_tab)
        for child in self.clock_frame.winfo_children():
            child.destroy()
        show = lambda v: "-" if v is None else (verify_short_number(v) if isinstance(v, (int, float)) else str(v))
        ttk.Label(self.clock_frame, text="Clock position distances (worked out by the calculator)",
                  font=("Segoe UI", 12, "bold", "underline")).pack(pady=(16, 4))
        ttk.Label(self.clock_frame, foreground="#555555", wraplength=1100, justify="center",
                  text=f"Every pair of anomalies, and every anomaly with every long seam found (a seam's width is 0 "
                       f"unless a seam width is found; it takes the anomaly's diameter). Into the calculator's "
                       f"'{CLOCK_SHEET}' sheet: clock hour / minutes "
                       f"/ width (inches) of the first in {CLOCK_CELLS['hour1']} / {CLOCK_CELLS['minute1']} / "
                       f"{CLOCK_CELLS['width1']}, of the second in {CLOCK_CELLS['hour2']} / {CLOCK_CELLS['minute2']} / "
                       f"{CLOCK_CELLS['width2']}, the outside diameter (inches) in {CLOCK_CELLS['diameter']}; read "
                       f"back: the distance apart in {CLOCK_CELLS['apart']} (inches - the shorter way round the pipe) and the warnings in "
                       f"{CLOCK_WARNING_CELLS[0]}-{CLOCK_WARNING_CELLS[-1]} (any warning = they overlap).").pack(pady=(0, 6))
        if message:
            quiet = ("Working",)
            ttk.Label(self.clock_frame, text=message, foreground="#555555" if any(q in message for q in quiet)
                      else "#b00020").pack(pady=4)
        if inputs:
            ttk.Label(self.clock_frame, text="What each anomaly and long seam gives (from the end table)",
                      font=("Segoe UI", 10, "bold")).pack(pady=(10, 2))
            add_simple_table(self.clock_frame, ["Anomaly / long seam", "Clock Position (row)", "Hour", "Minutes",
                                                "Width (in)", "Outside Diameter (in)", "Missing", "Where"],
                             [[i["name"], f"{i['clock'] or '-'}" + (f" ({i['clock_row']})" if i["clock_row"] else ""),
                               show(i["hour"]), show(i["minute"]),
                               show(i["width"]) + (" (no seam width found)" if i["kind"] == "seam"
                                                   and not i.get("width_row") else ""),
                               show(i["diameter"]) if i["kind"] == "anomaly" else "the anomaly's",
                               ", ".join(i["missing"]) or "-", i["found_in"]] for i in inputs], wraplength=240)
        # S427b: two tables - anomaly with anomaly, then anomaly with long seam; S427c: then each anomaly with only
        # the long seam it actually interacts with (the seam of its own joint) - the same results, no extra Excel work
        tables = (("Anomaly vs anomaly", "Anomaly 1", "Anomaly 2", [r for r in results if r["second"]["kind"] == "anomaly"]),
                  ("Anomaly vs long seam", "Anomaly", "Long seam", [r for r in results if r["second"]["kind"] == "seam"]),
                  ("Anomaly vs the long seam it interacts with (its own joint's)", "Anomaly", "Its long seam",
                   [r for r in results if r["second"]["kind"] == "seam"
                    and r["first"].get("own_seam") == r["second"]["name"]]))
        for number, (title, first_name, second_name, part) in enumerate(tables):
            if not part:
                continue
            own = number == 2
            warned = [n for n, r in enumerate(part) if r["warnings"]]
            ttk.Label(self.clock_frame, font=("Segoe UI", 11, "bold", "underline"),
                      text=f"{title} - {len(part)} pair(s), {len(warned)} with a warning (they overlap)").pack(pady=(16, 2))
            add_simple_table(self.clock_frame,
                             [first_name, f"Clock {CLOCK_CELLS['hour1']}:{CLOCK_CELLS['minute1']}",
                              f"Width {CLOCK_CELLS['width1']} (in)", second_name,
                              f"Clock {CLOCK_CELLS['hour2']}:{CLOCK_CELLS['minute2']}",
                              f"Width {CLOCK_CELLS['width2']} (in)", f"Diameter {CLOCK_CELLS['diameter']} (in)",
                              f"Distance apart {CLOCK_CELLS['apart']} (in)",
                              f"Warnings {CLOCK_WARNING_CELLS[0]}-{CLOCK_WARNING_CELLS[-1]}"]
                             + (["Why this seam"] if own else []),
                             [[r["first"]["name"], r["first"]["clock"], show(r["first"]["width"]),
                               r["second"]["name"], r["second"]["clock"], show(r["second"]["width"]),
                               show(r["first"]["diameter"]), show(r["apart"]), "\n".join(r["warnings"]) or "-"]
                              + ([r["first"]["own_why"]] if own else []) for r in part], wraplength=260,
                             colours={(n, 8): ORANGE for n in warned})
        lost = [i for i in (inputs or []) if i["kind"] == "anomaly" and not i["missing"] and not i.get("own_seam")]
        if lost and results:
            ttk.Label(self.clock_frame, foreground="#555555", text="No long seam found for its joint: "
                      + "; ".join(f"{i['name']} ({i['own_why']})" for i in lost)).pack(pady=(2, 4))

    def show_wheel_count_distances(self, results, message, main_results=None, found=(), pending=(), pending_mains=()):
        """S273: the 'WC Distances' tab - each pair of neighbouring wheel counts with what the calculator
        gave: the distance (T22) and, when a defect length went in, the total defect length apart (T27).
        S296: at the top, each wheel count's Linear Length of Repair."""
        self.wc_shown = (results, message, main_results, found, pending, pending_mains)
        if self.__dict__.get("wc_tab") is None:
            self.wc_frame = ttk.Frame(self.add_scroll_tab("WC Distances", removable=False, sideways=True))   # S431
            self.wc_frame.pack(fill="x")
            self.wc_tab = self.notebook.tabs()[-1]
            self.notebook.insert(2, self.wc_tab)
        repairs = self.__dict__.get("repair_results") or {}
        # S370: drawn only while WC Distances (or Main Wheel Counts) is the tab on show - otherwise it is drawn
        # when opened; the wrap distances still go to Excel and the wrap overlap warnings still come now
        if self.notebook.select() not in (str(self.wc_tab), str(self.__dict__.get("main_wc_tab") or "")):
            self.wc_stale = True
            self.main_wheel_counts_frame()              # the Main Wheel Counts tab made / taken away (Extra)
            self.show_wrap_table(repairs, draw=False)
            return
        self.wc_stale = False
        for child in self.wc_frame.winfo_children():
            child.destroy()
        if True:                                        # S296/S301: the repair lengths, always at the top
            ttk.Label(self.wc_frame, text="Linear Length of Repair (worked out by the calculator)",
                      font=("Segoe UI", 12, "bold", "underline")).pack(pady=(16, 4))
            ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                      text="Each wheel count with its Outside Diameter, Wall Thickness and defect Length all known "
                           "(inches) - into E4 / E5 / E15 of the calculator's Corrosion and Mechanical sheets; read "
                           "back: Corrosion C27 and Mechanical C26 (inches).").pack(pady=(0, 6))
            self.draw_repair_table(repairs, self.__dict__.get("repair_names") or {})
        ttk.Label(self.wc_frame, text="Wheel count distances (worked out by the calculator)",
                  font=("Segoe UI", 12, "bold", "underline")).pack(pady=(16, 4))
        ttk.Label(self.wc_frame, foreground="#555555", wraplength=1100, justify="center",
                  text=f"Each wheel count with the one next to it. Into the calculator's '{WC_SHEET}' sheet: "
                       f"wheel counts in feet in {WC_CELLS['wc1']} / {WC_CELLS['wc2']} (as written; no unit -> taken "
                       f"as feet), defect lengths in inches in {WC_CELLS['length1']} / {WC_CELLS['length2']} "
                       f"(0 when none is known), 0 in {WC_CELLS['zero1']} / {WC_CELLS['zero2']}; "
                       f"read back: {WC_CELLS['distance']} / {WC_CELLS['apart']} (inches) and "
                       f"{WC_CELLS['distance_ft']} / {WC_CELLS['apart_ft']} (feet)."
                  ).pack(pady=(0, 6))
        if message:
            quiet = ("Working", "Recalculating", "once every document")          # S296: not a problem
            ttk.Label(self.wc_frame, text=message, foreground="#b00020" if results == [] and
                      not any(q in message for q in quiet) else "#555555").pack(pady=4)
        waiting = "recalculating ..."                   # S295: what a cell being worked out again says
        due = lambda r: tuple(sorted((r["first"]["header"], r["second"]["header"]))) in pending
        if results:
            show = lambda v: "-" if v is None else (verify_short_number(v) if isinstance(v, (int, float)) else str(v))
            bold = {w["shown"] for w in found if w.get("form")}     # S294: on the Dig Packet's page 1 / the 6000 - bold
            add_simple_table(self.wc_frame, ["Wheel count 1", "Wheel count 2", f"{WC_CELLS['wc1']} (ft)",
                                             f"{WC_CELLS['wc2']} (ft)", f"Defect length 1 {WC_CELLS['length1']} (in)",
                                             f"Defect length 2 {WC_CELLS['length2']} (in)",
                                             f"Distance {WC_CELLS['distance']} (in)",                     # S274
                                             f"Distance {WC_CELLS['distance_ft']} (ft)",                  # S277
                                             f"Total defect length apart {WC_CELLS['apart']} (in)",
                                             f"Total defect length apart {WC_CELLS['apart_ft']} (ft)"],
                             [[r["first"]["shown"], r["second"]["shown"], show(r["first"]["feet"]),
                               show(r["second"]["feet"]), show(r["first"]["length"]), show(r["second"]["length"])]
                              + ([waiting] * 4 if due(r) else
                                 [show(r["distance"]), show(r["distance_ft"]), show(r["apart"]), show(r["apart_ft"])])
                              for r in results], wraplength=200, bold=bold)
            self.show_wrap_table(repairs)   # S310: after the wheel count distances, before the main wheel counts
            # S287: under it - one table per main wheel count (mentioned in more than one place): the wheel
            # counts before it (nearest first) and after it, each with the distance apart (T22 in / T23 ft)
            mains = sorted((w for w in found if (main_results or {}).get(w["header"])),     # S311: most places first
                           key=lambda w: (-w.get("mentions", 0), w["feet"]))
            apart = lambda r: ((waiting if due(r) else f"{show(r['distance'])} in ({show(r['distance_ft'])} ft)")
                               if r else "")

            def draw_main(main, parent):
                others = main_results[main["header"]]
                before = sorted((w for w in found if w["header"] in others and w["feet"] < main["feet"]),
                                key=lambda w: w["feet"])
                after = sorted((w for w in found if w["header"] in others and w["feet"] > main["feet"]),
                               key=lambda w: w["feet"])
                ttk.Label(parent, text=f"Main wheel count {main['shown']} - in {main.get('mentions', 0)} places"
                          + (" (on the Dig Packet's page 1 / the 6000 form)" if main.get("form") else ""),
                          font=("Segoe UI", 10, "bold")).pack(pady=(14, 2))
                lines = []
                for previous, following in wheel_count_rows(before, after):     # S292/S293
                    if main["header"] in pending_mains:          # S295: its rows may move - all being worked out
                        lines.append([waiting, waiting, main["shown"], waiting, waiting])
                        continue
                    lines.append([previous["shown"] if previous else "",
                                  apart(others.get(previous["header"])) if previous else "",
                                  main["shown"],
                                  apart(others.get(following["header"])) if following else "",
                                  following["shown"] if following else ""])
                add_simple_table(parent, ["Previous wheel count", "Distance apart", "Main wheel count",
                                          "Distance apart", "Next wheel count"], lines, wraplength=220, bold=bold)

            bold_mains = [m for m in mains if m.get("form")]      # S312: only the bold ones, first
            if bold_mains:
                ttk.Label(self.wc_frame, text="Main Bold Wheel Counts (on the Dig Packet's page 1 / the 6000 form)",
                          font=("Segoe UI", 12, "bold", "underline")).pack(pady=(24, 4))
                for main in bold_mains:
                    draw_main(main, self.wc_frame)
            # S313: every main wheel count - its own tab 'Main Wheel Counts', made only when switched on in Extra
            parent = self.main_wheel_counts_frame()
            if parent is not None:
                ttk.Label(parent, text="Main wheel counts (mentioned in more than one place, or on the Dig "
                                       "Packet's page 1 / the 6000 form - those in bold)",
                          font=("Segoe UI", 12, "bold", "underline")).pack(pady=(16, 4))
                if not mains:
                    ttk.Label(parent, text="No main wheel counts yet.", foreground="#555555").pack(pady=4)
                for main in mains:
                    draw_main(main, parent)
        if not results:                     # S310: no distances yet - the wrap table still shows, last
            self.show_wrap_table(repairs)
        self.draw_combined_repair_table()   # S432: the combined repairs' lengths - at the very bottom
        self.draw_pick_section()            # S443: under them - the repair it picks (Carbon or E-Glass)

    def group_picked_repair(self, header, numbers):
        """S444: the picked repair (WC Distances, 'The repair it picks') this anomaly is in - its fabric, and for a
        combined one its first wheel count's Outside Diameter / Wall Thickness and the total defect length the
        calculator gave (CO13) put into numbers (E4 / E5 / E15) for the calculator copy. Returns (fabric or None,
        what was done - for the terminal, S447: the Main!C11 comment for a combined one or None)."""
        pick = self.__dict__.get("wrap_pick") or {}
        key = document_name_header(header) or header
        name = next((n for n in pick.get("fabrics") or {} if key in n.split(" & ")), None)
        if name is None:
            return None, (f"{key} is in no picked repair (not worked out yet on WC Distances, or no repair of its "
                          f"own) - no fabric set, its own values as before"), None
        fabric = pick["fabrics"][name]
        if " & " not in name:
            return fabric, f"{key}: picked repair {name} - {fabric} set, its own values", None
        covers = self.group_covers_text(name.split(" & "))                  # S447
        entry = (self.__dict__.get("pick_results") or {}).get(name) or {}
        out, values = entry.get("out"), entry.get("inputs") or {}
        if not isinstance(out, dict) or not isinstance(out.get("full_length"), (int, float)):
            return fabric, (f"{key}: picked repair {name} ({fabric}) - its total defect length is not worked out "
                            f"yet, so this anomaly's own values went in"), covers
        numbers.update({CALC_MEASUREMENT_CELLS["Outside Diameter"]: values["Outside Diameter"],
                        CALC_MEASUREMENT_CELLS["Wall Thickness"]: values["Wall Thickness"],
                        CALC_MEASUREMENT_CELLS["Length"]: out["full_length"]})
        # S452: the whole wrap's largest depth and largest width (in inches, as E13 / E16 take them) - compared only
        pipes = self.__dict__.get("repair_pipe") or {}
        largest = {}
        for field in ("Depth", "Width"):
            value, member = repair_largest(pipes, name.split(" & "), field)
            if value is not None:
                numbers[CALC_MEASUREMENT_CELLS[field]] = value
                largest[field] = f"{verify_short_number(value)} in ({member})"
        return fabric, (f"{key}: picked repair {name} ({fabric}) - "
                        + "".join(f"largest {f.lower()} {t}, " for f, t in largest.items()) + "E4 / E5 = its first wheel count's "
                        f"{verify_short_number(values['Outside Diameter'])} / {verify_short_number(values['Wall Thickness'])} "
                        f"in, E15 = its total defect length {verify_short_number(out['full_length'])} in "
                        f"({COMBINED_CELLS['length']}), {fabric} in {FABRIC_BOTH}"), covers

    def group_pipe_grade(self, header):
        """S456: (the Pipe Grade for the repair's calculator or None, what was found) - from the Pipe Grade row of
        the anomalies in the repair (one repair is on one pipe - S452)."""
        members = (self.__dict__.get("verify_repair_members") or {}).get(header, [header])
        return repair_grade(self.__dict__.get("repair_pipe") or {}, members)

    def group_class_location(self, header):
        """S457: (40 / 50 / 60 / 72 for the repair's calculator or None, what was found) - from the Class Location
        row of the anomalies in the repair; class 1 (72) when none says."""
        members = (self.__dict__.get("verify_repair_members") or {}).get(header, [header])
        return repair_class(self.__dict__.get("repair_pipe") or {}, members)

    def group_covers_text(self, members):
        """S447/S450/S453: Main!C11 of a combined repair's calculator - 'One wrap covers WC 121271.75 Wrinkle 1, WC
        121278.84 External Metal Loss L 208 in, W 10 in, D 61 mils, ...' (S450: L / W / D only for one with a depth). Before:
        'One wrap covers WC 121271.75 L 4.35 in, W 2 in, D 0.05
        in, WC 121273.52 L ...' - each wheel count with its Length, Width and Depth as the end table shows them
        ('-' when it has none). S448: only the anomalies - a wheel count with a Depth above 0, or one a 6000 form
        names, or (a 6000 form having a Wrinkle section) any wrinkle; None when none of them is one."""
        headers, by_label = self.__dict__.get("verify_end_table") or ([], {})
        def value(member, field):
            text = next((end_table_value(headers, by_label, member, label)
                         for label in CALC_MEASUREMENT_ROWS.get(field, [field])
                         if headers and end_table_value(headers, by_label, member, label)), "")
            return str(text).strip() or "-"
        blocks = self.__dict__.get("verify_blocks") or []
        columns = dict(verify_table_columns(verify_end_table_blocks(blocks))) if blocks else {}
        wrinkle_section = any(re.search(r"6000 form Section .* - Wrinkle", str(b.get("title") or "")) for b in blocks)

        def anomaly(member):                            # S448: why it is one, or None
            depth = verify_number(value(member, "Depth"))
            if depth is not None and float(depth) > 0:
                return "depth"
            if any(str(e.get("source") or "").startswith("6000 ") for block in columns.get(member, [])
                   for entries in block["fields"].values() for e in entries):
                return "on a 6000 form"
            if wrinkle_section and "wrinkle" in value(member, "Defect name").lower():
                return "a wrinkle (the 6000 form has a Wrinkle section)"
            return None
        why = {m: anomaly(m) for m in members}
        print("GROUP: Main!C11 anomalies - " + "; ".join(f"{m}: {why[m] or 'not an anomaly - left out'}"
                                                         for m in members) + " (S448)")
        kept = [m for m in members if why[m]]
        if not kept:
            return None

        def described(member):
            """S450/S453: 'WC <wheel count> <anomaly name>' and, only when it has a depth (above 0), ' L .., W .., D ..'."""
            name = value(member, "Defect name")
            parts = [f"WC {member}"] if re.fullmatch(r"\d+(\.\d+)?", member) else []   # S453: the WC first
            if name not in ("-", VERIFY_PICK_PROMPT):
                parts.append(name)
            depth = verify_number(value(member, "Depth"))
            text = " ".join(parts) or member
            if depth is not None and float(depth) > 0:
                text += f" L {value(member, 'Length')}, W {value(member, 'Width')}, D {value(member, 'Depth')}"
            return text
        return "One wrap covers " + ", ".join(described(m) for m in kept)

    def verify_group(self, header, folder, document, button):
        """S262: the Group button - a folder in Downloads named as the folder name, holding (S266) a copy
        of the composite calculator named as the document name, and a copy of every document the
        anomaly's values came from;
        S265: and those PDFs merged into one, 'Composite_Supporting Docs_...'."""
        self.click_wait(f"Group - {header}")                              # S369
        wait = self.group_wait_reason(self.tab_busy_reasons())             # S464: never before both tabs are done
        if wait:
            self.lock_group_button(button, wait)
            print(f"GROUP: {header} not grouped - waiting for {wait} (S464)")
            return
        # S398: the whole run's time, the moment Group is clicked - from the program's start to this click;
        # S399: printed at the very end, under the PROFILE line, when the window is closed
        FINAL_TIMES.append((header, time.perf_counter() - PROGRAM_START, datetime.now()))
        if not folder or not document:
            button.configure(text="Group - name missing", bg=ORANGE, activebackground=ORANGE)
            return
        downloads = os.path.join(os.path.expanduser("~"), "Downloads")
        target, copy_number = os.path.join(downloads, folder), 1
        while os.path.exists(target):                   # S264: a folder of that name stays as it is -
            copy_number += 1                            # this group gets 'name (2)', 'name (3)' ...
            target = os.path.join(downloads, f"{folder} ({copy_number})")
        try:
            os.makedirs(target)
            PROFILE_STATE["folders"].append(target)     # S366: this run's profile.svg is copied in at the end
            # S266: a copy of the composite calculator, named as the document name (it replaces the
            # placeholder text file) - a plain file copy, so its macros, buttons and formatting stay
            calculator = find_calculator()
            calc_name = document + os.path.splitext(calculator or ".xlsm")[1]
            if calculator:
                shutil.copy2(calculator, os.path.join(target, calc_name))
                # S267/S268: Main!C3 - '<Diameter>, <WC value or station>, <Line ID>, <Project Number>'
                main_c3 = ", ".join(p for p in self.__dict__.get("verify_name_parts", {}).get(header, {}).get("C3", []) if p)
                # S270: Main!C9 - '<City>, <State abbreviation>' from the pasted place and the State box
                typed = self.__dict__.get("verify_names_typed", {}).get(header, {})
                city = document_place(typed.get("place", "")).split(",")[0].strip()
                main_c9 = ", ".join(p for p in (city, typed.get("state", "").strip().upper()) if p)
                cells = {"C3": main_c3}
                if main_c9:
                    cells["C9"] = main_c9
                main_h10 = self.__dict__.get("verify_name_parts", {}).get(header, {}).get("H10", "")   # S271
                if main_h10:
                    cells["H10"] = main_h10
                main_h9 = self.__dict__.get("verify_name_parts", {}).get(header, {}).get("H9", "")     # S272
                if main_h9:
                    cells["H9"] = main_h9
                main_date = datetime.now().strftime("%m/%d/%Y")    # S466: the day Group is clicked, mm/dd/yyyy
                cells[GROUP_DATE_CELL] = main_date
                xlsx_set_cells(os.path.join(target, calc_name), "Main", cells)
                print(f"GROUP: Main!{GROUP_DATE_CELL} = '{main_date}' (S466)")
                # S278: the Corrosion and Mechanical sheets - OD, WT, depth, length, width in inches
                measured = self.__dict__.get("verify_name_parts", {}).get(header, {}).get("inches", {})
                numbers = {CALC_MEASUREMENT_CELLS[name]: calculator_inches(text) for name, text in measured.items()}
                numbers = {cell_ref: value for cell_ref, value in numbers.items() if value is not None}
                fabric, picked_note, covers = self.group_picked_repair(header, numbers)     # S444 / S447
                if numbers:
                    for sheet_name in CALC_MEASUREMENT_SHEETS:
                        try:
                            xlsx_set_cells(os.path.join(target, calc_name), sheet_name, numbers)
                        except ValueError as exc:            # a calculator version without that sheet
                            print(f"GROUP: {sheet_name} sheet not filled - {exc} (S278)")
                if fabric:                                       # S454: the fabric on both sheets
                    for fabric_sheet, fabric_cell in FABRIC_CELLS.items():
                        try:
                            xlsx_set_cells(os.path.join(target, calc_name), fabric_sheet, {fabric_cell: fabric})
                        except ValueError as exc:
                            print(f"GROUP: the fabric was not set on {fabric_sheet} - {exc} (S454)")
                print(f"GROUP: {picked_note} (S444)")
                if fabric is None:                               # S455: its own type when in no picked repair
                    fabric = fabric_for_type((self.__dict__.get("repair_types") or {}).get(
                        document_name_header(header) or header))[0]
                kind = "Corrosion" if fabric == "E-Glass" else "Mechanical"
                xlsx_set_cells(os.path.join(target, calc_name), "Main", {REPAIR_KIND_CELL: kind})
                print(f"GROUP: Main!{REPAIR_KIND_CELL} = '{kind}' - "
                      + ("every anomaly in it is pure corrosion / metal loss" if kind == "Corrosion"
                         else "not pure corrosion / metal loss") + " (S455)")
                grade, grade_note = self.group_pipe_grade(header)          # S456: Corrosion / Mechanical E7
                if grade:
                    for grade_sheet, grade_cell in PIPE_GRADE_CELLS.items():
                        try:
                            xlsx_set_cells(os.path.join(target, calc_name), grade_sheet, {grade_cell: grade})
                        except ValueError as exc:
                            print(f"GROUP: the Pipe Grade was not set on {grade_sheet} - {exc} (S456)")
                print(f"GROUP: Pipe Grade (Corrosion / Mechanical E7) - {grade_note} (S456)")
                location, location_note = self.group_class_location(header)  # S457: Corrosion / Mechanical E10
                if location:
                    for location_sheet, location_cell in CLASS_LOCATION_CELLS.items():
                        try:
                            xlsx_set_cells(os.path.join(target, calc_name), location_sheet, {location_cell: location})
                        except ValueError as exc:
                            print(f"GROUP: the Class Location was not set on {location_sheet} - {exc} (S457)")
                print(f"GROUP: Class Location (Corrosion / Mechanical E10) - {location_note} (S457)")
                if covers:                                       # S447: a combined repair - Main!C11 comment
                    xlsx_set_cells(os.path.join(target, calc_name), "Main", {GROUP_COVERS_CELL: covers})
                    print(f"GROUP: Main!{GROUP_COVERS_CELL} = '{covers}' (S447)")
                measured_line = ", ".join(f"{ref} = {verify_short_number(v)}" for ref, v in numbers.items())
            else:
                print(f"GROUP: the calculator was not found ({calculator_missing_text()}) - "
                      f"no calculator copy in the folder (S266)")
            # S449: every document of every anomaly in the repair, each once
            files = list(dict.fromkeys(
                f for member in (self.__dict__.get("verify_repair_members") or {}).get(header, [header])
                for f in verify_column_files(self.verify_blocks, member, self.__dict__.get("verify_label_files", {}))))
            copied = []
            for path in files:
                if os.path.isfile(path):
                    shutil.copy2(path, os.path.join(target, os.path.basename(path)))
                    copied.append(os.path.basename(path))
            # S265: every PDF of the group merged into one, named as the document name with
            # 'Supporting Docs' for 'Calc' (Composite_Supporting Docs_...)
            pdfs = [path for path in files if os.path.isfile(path) and path.lower().endswith(".pdf")]
            merged_name = document.replace("Composite_Calc", "Composite_Supporting Docs", 1) + ".pdf"
            if pdfs:
                with pdf_turn(f"Group: merging {len(pdfs)} PDF(s)"):
                    merged = fitz.open()
                    for path in pdfs:
                        with fitz.open(path) as part:
                            merged.insert_pdf(part)
                    merged.save(os.path.join(target, merged_name))
                    pages = merged.page_count
                    merged.close()
            everything = self.__dict__.get("merged")          # S374: the whole merged PDF too
            if everything is not None and os.path.isfile(everything["path"]):
                shutil.copy2(everything["path"], os.path.join(target, MERGED_GROUP_NAME))
        except Exception as exc:
            print(f"GROUP: {header} - could not make {target} ({exc}) (S262)")
            button.configure(text="Group - failed", bg="#b00020", activebackground="#b00020")
            return
        print(f"GROUP: {header} -> {target}: " + (f"{calc_name} (calculator copy, Main!C3 = '{main_c3}' - S267"
                                                  f", Main!C9 = '{main_c9}' - S270, Main!H9 = '{main_h9}' - S272"
                                                  f", Main!H10 = '{main_h10}' - S271; Corrosion + Mechanical: "
                                                  f"{measured_line or 'nothing in inches found'} - S278)"
                                                  if calculator else "no calculator")
              + f" + {len(copied)} document(s): {', '.join(copied)} (S262)"
              + (f" + {merged_name} ({len(pdfs)} PDF(s) merged, {pages} pages - S265)" if pdfs else "")
              + (f" + {MERGED_GROUP_NAME} (every document, {everything['pages']} pages - S374)"
                 if everything is not None and os.path.isfile(everything["path"]) else "")
              + (f" - a folder named '{folder}' was already there, so this one is '({copy_number})' (S264)"
                 if copy_number > 1 else ""))
        button.configure(text=f"Grouped ✓ ({len(copied)} doc)", bg=GREEN, activebackground=GREEN)

    # ---------- S195: a Pages tab per document ----------
    def refresh_page_tabs(self, done, labels):
        """One 'Pages' tab per read document (after every other tab): made when it is read,
        taken away when it is removed, its name following the document's; the marked
        pages are drawn again when the priority values found on them change."""
        tabs = self.__dict__.setdefault("page_tabs", {})
        paths = {document["path"]: document for document in done
                 if self.extra_on.get(("pages", document["path"]))}          # S298: only when switched on
        for path in [p for p in tabs if p not in paths]:
            tab = tabs.pop(path)
            self.canvas_of.pop(str(tab["outer"]), None)
            self.notebook.forget(tab["outer"])
            tab["outer"].destroy()
        for path, document in paths.items():
            title = f"{labels[id(document)]} - Pages"
            if path in tabs:
                self.notebook.tab(tabs[path]["outer"], text=title)
            else:
                outer = ttk.Frame(self.notebook)
                self.notebook.add(outer, text=title)
                canvas = tk.Canvas(outer, bg="#808080", highlightthickness=0)
                bar = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
                canvas.configure(yscrollcommand=bar.set)
                bar.pack(side="right", fill="y")
                canvas.pack(side="left", fill="both", expand=True)
                self.canvas_of[str(outer)] = canvas            # the mouse wheel scrolls it
                tab = tabs[path] = {"outer": outer, "canvas": canvas, "pages": "rendering", "drawn": None,
                                    "photos": [], "name": document["name"]}

                def render(tab=tab, path=path):
                    try:
                        tab["pages"] = document_page_layers(path)
                    except Exception as exc:
                        tab["pages"] = f"The pages could not be shown ({exc})"

                threading.Thread(target=render, daemon=True).start()
                canvas.create_text(20, 20, anchor="nw", fill="white", font=("Segoe UI", 12),
                                   text=f"Showing the pages of {document['name']} ...")
            self.draw_page_tab(path)

    def draw_page_tab(self, path):
        """A Pages tab: every page as it is, the marked copy beneath it (PDF text blue,
        pictures orange, priority values yellow with their name); a line per page says how
        much of it is text / pictures and which priority values are on it."""
        tab = self.__dict__.get("page_tabs", {}).get(path)
        if tab is None or not tab["outer"].winfo_exists():
            return
        if tab["pages"] == "rendering":
            self.root.after(200, lambda: self.draw_page_tab(path))
            return
        canvas = tab["canvas"]
        if isinstance(tab["pages"], str):
            canvas.delete("all")
            canvas.create_text(20, 20, anchor="nw", fill="white", font=("Segoe UI", 12), text=tab["pages"])
            return
        found = {}                                       # page -> [(box, name, PDF text?)] of the priority values on it
        for block in self.verify_blocks:
            for field in PRIORITY_FIELDS + [PRIORITY_NOTES]:
                for entry in (block["notes"] if field == PRIORITY_NOTES else block["fields"][field]):
                    where = entry.get("where")
                    if where and where["path"] == path and where["page"] < len(tab["pages"]):
                        box = tuple(round(v) for v in verify_display_box(where, tab["pages"][where["page"]]))
                        found.setdefault(where["page"], [])
                        mark = (box, field, bool(entry.get("from_text")))      # S226: PDF text -> purple
                        if mark not in found[where["page"]]:
                            found[where["page"]].append(mark)
        drawn = tuple(sorted((page, tuple(sorted(boxes))) for page, boxes in found.items()))
        if drawn == tab["drawn"]:
            return
        tab["drawn"] = drawn
        from PIL import ImageTk
        canvas.delete("all")
        tab["photos"] = []
        y = 14
        canvas.create_text(14, y, anchor="nw", fill="white", font=("Segoe UI", 13, "bold"),
                           text=f"{tab['name']} - every page as it is, and beneath it the same page marked")
        y += 26
        canvas.create_text(14, y, anchor="nw", fill="white", font=("Segoe UI", 10),
                           text="Blue = PDF text (read exactly).   Orange = a picture (read by OCR, if at all).   "
                                "Purple = a priority value that is PDF text.   Yellow with a red border = a "
                                "priority value read from a picture, with its name.")
        y += 30
        for number, page in enumerate(tab["pages"]):
            priority = found.get(number, [])
            share = sum((b[2] - b[0]) * (b[3] - b[1]) for b in page["pictures"]) / max(
                1, page["image"].width * page["image"].height)
            canvas.create_text(14, y, anchor="nw", fill="white", font=("Segoe UI", 11, "bold"),
                               text=f"Page {number + 1}:  {len(page['words'])} PDF text word(s),  "
                                    f"{len(page['pictures'])} picture(s) covering {min(100, round(share * 100))}% "
                                    f"of it" + (f",  priority values: {', '.join(dict.fromkeys(n for _b, n, _t in priority))}"
                                                if priority else ",  no priority values"))
            y += 24
            for label, picture in (("as it is", page["image"]), ("marked", document_page_marked(page, priority))):
                canvas.create_text(14, y, anchor="nw", fill="#dddddd", font=("Segoe UI", 9), text=label)
                y += 16
                photo = ImageTk.PhotoImage(picture)
                tab["photos"].append(photo)
                canvas.create_image(14, y, anchor="nw", image=photo)
                y += photo.height() + 10
            y += 24
        canvas.configure(scrollregion=(0, 0, PAGES_TAB_WIDTH + 60, y))

    def verify_pick_final(self, header, row, value):
        """S191: ✓ next to a yellow value: that value is the right one for that row of that
        anomaly - it goes into the '<header> Final' column; the table is drawn again where
        it was scrolled to."""
        value = str(value).split("\n")[0].strip()          # S263: the value only - not its sum lines
        self.click_wait(f"pick - {header} {row} '{value}'")              # S369
        self.verify_finals[(header, row)] = value
        print(f"VERIFY: {header} - {row}: '{value}' picked as the final value (S191)")
        cells = getattr(self.verify_canvas, "pick_cells", {}) or {}
        if self.verify_view == "compare" and (header, row) in cells:
            # S317: while choosing, a ✓ only turns its cells green (the others of that row yellow) - nothing
            # is worked out again until the last one is picked; a misclick is fixed with the other ✓
            for boxes, text in cells[(header, row)]:
                colour = TABLE_CHOSEN_COLOUR if text == value else TABLE_CHANGED_COLOUR
                for box in boxes:
                    self.verify_canvas.itemconfigure(box, fill=colour)
            left_to_pick = [key for key in cells if key not in self.verify_finals]
            self.verify_progress.configure(text=f"{len(cells) - len(left_to_pick)} of {len(cells)} comparison(s) "
                                                f"picked")
            if left_to_pick:
                return
            print(f"VERIFY: all {len(cells)} comparison(s) picked - the table and everything after it are worked "
                  f"out now (S317)")
            self.release_verify_hold()
            return
        top, left = self.verify_canvas.yview()[0], self.verify_canvas.xview()[0]
        self.show_verify_item()
        self.verify_canvas.update_idletasks()
        self.verify_canvas.yview_moveto(top)
        self.verify_canvas.xview_moveto(left)
        self.start_wheel_count_distances()          # S291: picked names / lengths into the WC Distances tab

    def release_verify_hold(self):
        """S317: the choosing is finished - what arrived meanwhile (new values, the WC Distances, the repair
        lengths) is worked out now, once, and the tab shows the table of everything."""
        self.verify_hold = False
        due = self.__dict__.get("verify_due")
        self.verify_due = None
        if due is not None:
            self.build_priority_values(*due)          # also draws the tab again
        else:
            self.show_verify_item()
        self.start_wheel_count_distances()
        self.start_repair_lengths(self.verify_table())

    def verify_scroll_to(self, area):
        """S177/S178: scrolls the PDF so the boxed value sits about a third of the way down
        the view with its panel fully in view, and (S178, pages wider than the window)
        across so the box and panel are in view, starting a little left of the box."""
        canvas = self.verify_canvas
        if not canvas.winfo_exists():
            return
        canvas.update_idletasks()
        left, top, right, bottom = area
        region = [float(v) for v in str(canvas.cget("scrollregion") or "0 0 1 1").split()]
        width, height = max(1.0, region[2] - region[0]), max(1.0, region[3] - region[1])
        view_w, view_h = max(1, canvas.winfo_width()), max(1, canvas.winfo_height())
        start_y = top - view_h * 0.3
        if bottom - start_y > view_h - 10:                 # keep the whole panel in view
            start_y = min(top - 10, bottom - view_h + 10)
        start_x = left - min(view_w * 0.25, 300)
        if right - start_x > view_w - 10:
            start_x = min(left - 10, right - view_w + 10)
        canvas.yview_moveto(max(0.0, min(1.0, start_y / height)))
        canvas.xview_moveto(max(0.0, min(1.0, start_x / width)))

    def verify_draw_pages(self, key, pages):
        """The pages of one PDF at one zoom, stacked (S374: the merged PDF). Each page's place is drawn at once
        (white, 'page n - being drawn'); its picture goes over it when it is near the view (verify_fill_pages)."""
        canvas = self.verify_canvas
        self.verify_clear_canvas()
        self.verify_offsets, y = [], VERIFY_PAGE_GAP
        for number, page in enumerate(pages):
            width, height = page["size"]
            canvas.create_rectangle(VERIFY_PAGE_GAP, y, VERIFY_PAGE_GAP + width, y + height, fill="white", outline="",
                                    tags=("pages", f"page_place_{number}"))
            canvas.create_text(VERIFY_PAGE_GAP + 20, y + 20, anchor="nw", fill="#999999", font=("Segoe UI", 12),
                               text=f"page {number + 1} of {len(pages)} - being drawn ...",
                               tags=("pages", f"page_place_{number}"))
            self.verify_offsets.append((VERIFY_PAGE_GAP, y))
            y += height + VERIFY_PAGE_GAP
        widest = max((page["size"][0] for page in pages), default=0)
        canvas.configure(scrollregion=(0, 0, widest + 2 * VERIFY_PAGE_GAP, y))
        self.verify_shown_key = key
        self.verify_schedule_fill()

    def verify_clear_canvas(self):
        """Everything on the Verify canvas goes - S374: with the pages' window pictures."""
        self.verify_canvas.delete("all")
        self.verify_page_photos = {}

    def verify_panel(self, item):
        """S178/S227: a small panel right under the boxed value - 'Read as' the value (and its unit),
        what was decided before, the buttons, and the box to type the right value in - so
        it covers as little of the page as it can. S180: a value that differs from its
        section's PDF text also shows what the text says (in red). S189: every value has the
        same ✓ / X / box - no '?': a differing value kept with ✓ shows up yellow in the
        end table, next to the text value."""
        entry = item["entry"]
        differs = item["kind"] == "differs"
        panel = tk.Frame(self.verify_canvas, bg="#fff8e1", highlightbackground=ORANGE, highlightthickness=2,
                         padx=6, pady=3)
        # S227: stacked down, not across - the read value, each PDF-text comparison on its own line,
        # then the buttons and the box - so the panel stays narrow and its ✓ in view
        top = tk.Frame(panel, bg="#fff8e1")
        top.pack(anchor="w")
        marker = entry.get("marker")                     # S241: which bullet of the line it is
        tk.Label(top, text=f"({marker})  Read as:" if marker else "Read as:", bg="#fff8e1",
                 fg="#b00020" if marker else "#555555",
                 font=("Segoe UI", 10, "bold") if marker else ("Segoe UI", 9)).pack(side="left")
        priority_value_row(top, entry, with_unit=item["field"] != PRIORITY_NOTES, side="left")
        for shown in [item] + item["followers"]:  # S181: the PDF-text value(s), to compare by eye (S192: per part)
            if not shown["texts"]:
                continue
            said = " / ".join(dict.fromkeys(verify_text_with_unit(e) for e in shown["texts"]))
            name = f"{shown['field']} " if shown is not item else ""
            verb = {"differs": "says"}.get(shown["kind"], "has")
            tk.Label(panel, text=f"{name}PDF text {verb}: {said}", bg="#fff8e1",
                     fg={"differs": "#b00020"}.get(shown["kind"], "#1f4e9c"),
                     font=("Segoe UI", 10, "bold")).pack(anchor="w")
        before = self.verify_state.get(item["id"])
        if before:
            tk.Label(top, bg="#fff8e1", font=("Segoe UI", 9, "bold"),
                     fg=GREEN if before["status"] == "confirmed" else ORANGE,
                     text={"confirmed": "✓ confirmed", "corrected": "corrected",
                           "rejected": "marked X"}[before["status"]]).pack(side="left", padx=(8, 0))
        controls = tk.Frame(panel, bg="#fff8e1")
        controls.pack(anchor="w", pady=(3, 0))
        tk.Button(controls, text="✓", font=("Segoe UI", 11, "bold"), fg="white", bg=GREEN, activebackground=GREEN,
                  width=2, pady=0, command=lambda: self.verify_accept(item)).pack(side="left")
        tk.Button(controls, text="X", font=("Segoe UI", 11, "bold"), fg="white", bg="#b00020",        # S186
                  activebackground="#b00020", width=2, pady=0,
                  command=lambda: self.verify_accept(item, "rejected")).pack(side="left", padx=(4, 0))
        self.verify_entry_box = ttk.Entry(controls, width=24, font=("Segoe UI", 10))
        self.verify_entry_box.pack(side="left", padx=(6, 0))
        if before and before["status"] == "corrected":
            self.verify_entry_box.insert(0, before["value"])
        self.verify_entry_box.bind("<Return>", lambda _event: self.verify_accept(item))
        self.verify_hint.configure(
            text=("Differs from the PDF text (red):  ✓ keeps this read - the end table shows both, in yellow.   "
                  if differs else "Right: ✓ (or Enter).   ")
            + "X = bad read, not needed.   Wrong: type the right value in the box, then ✓ / Enter.")
        return panel

    def verify_accept(self, item, choice=None):
        """✓ / Enter: the read value - or the typed one - is kept, and the next value is
        shown. 'X' (choice 'rejected') = bad read, not needed."""
        entry = item["entry"]
        read = priority_entry_text(entry)
        typed = self.verify_entry_box.get().strip()
        self.click_wait(("X" if choice == "rejected" else "typed correction" if typed and typed != read else "✓")
                        + f" - {item['field']}")                          # S369
        if typed and typed != read and choice != "rejected":
            self.verify_state[item["id"]] = {"status": "corrected", "value": typed, "read": read}
            pushed = entry["extract"] is None and entry["key"] and verify_push_correction(entry["key"], typed)
            print(f"VERIFY: {item['field']} | {entry['source']}: corrected '{read}' -> '{typed}'"
                  + (" (also in its correction box)" if pushed else "") + " (S175)")
        elif choice == "rejected":
            self.verify_state[item["id"]] = {"status": "rejected", "value": read, "read": read}
            print(f"VERIFY: {item['field']} | {entry['source']}: '{read}' marked X - bad read, not needed (S186)")
        else:
            self.verify_state[item["id"]] = {"status": "confirmed", "value": read, "read": read}
            print(f"VERIFY: {item['field']} | {entry['source']}: confirmed '{read}' (S175)")
        decided = self.verify_state[item["id"]]
        for follower in item["followers"]:          # S192: the values taken out of the line go with it
            follower_read = priority_entry_text(follower["entry"])
            part = follower["entry"].get("line_part")
            value = part(decided["value"]) if decided["status"] == "corrected" and part else None
            if decided["status"] == "rejected":
                state = {"status": "rejected", "value": follower_read, "read": follower_read}
            elif value and value != follower_read:
                state = {"status": "corrected", "value": value, "read": follower_read}
            else:
                state = {"status": "confirmed", "value": follower_read, "read": follower_read}
            self.verify_state[follower["id"]] = state
            print(f"VERIFY:   with the line - {follower['field']}: {state['status']} '{state['value']}' (S192)")
        if verify_is_table_entry(entry) and decided["status"] in ("confirmed", "corrected"):
            self.verify_take_away(item, decided["value"])      # S480
        self.verify_next_unchecked()                    # S263: on to a value not checked yet

    def verify_take_away(self, table_item, value):
        """S480: a table value you just checked (✓ or typed) confirms every value still to check of the same thing
        for the same anomaly (its end-table column) that says the same - handwriting, a map note read by OCR - so
        they are not asked again. A Notes line goes only when every value taken out of it is confirmed this way and
        it says nothing else (its letter and the @ aside)."""
        columns = verify_table_columns(verify_end_table_blocks(self.verify_blocks))
        column_of = {block.get("title"): header for header, column in columns for block in column}
        header = column_of.get(table_item["block"])
        if header is None:
            return
        field, table_entry = table_item["field"], table_item["entry"]

        def same(item):
            if item["field"] != field or column_of.get(item["block"]) != header or verify_is_table_entry(item["entry"]):
                return False
            return verify_same(field, item["entry"], priority_entry_text(item["entry"]), table_entry, value) is True

        for item in self.verify_items:
            if self.verify_state.get(item["id"]):
                continue
            parts = [item] if not item["followers"] else item["followers"]
            matched = [p for p in parts if same(p) or self.verify_state.get(p["id"], {}).get("status") == "confirmed"]
            if not item["followers"] and matched:
                read = priority_entry_text(item["entry"])
                self.verify_state[item["id"]] = {"status": "confirmed", "value": read, "read": read}
                print(f"VERIFY: {field} | {item['entry']['source']}: '{read}' - the same as the table value you checked "
                      f"('{value}', {table_entry['source']}) -> confirmed, taken off the Verify tab (S480)")
            elif item["followers"]:
                for part in parts:
                    if same(part) and not self.verify_state.get(part["id"]):
                        part_read = priority_entry_text(part["entry"])
                        self.verify_state[part["id"]] = {"status": "confirmed", "value": part_read, "read": part_read}
                read = priority_entry_text(item["entry"])
                leftover = read.upper()
                for part in parts:
                    leftover = leftover.replace(priority_entry_text(part["entry"]).upper(), " ")
                leftover = re.sub(r"\(\s*[A-Z]\s*\)|@|[^A-Z0-9]", "", leftover)   # its letter, the @, spacing
                if len(matched) == len(parts) and parts and not leftover:
                    self.verify_state[item["id"]] = {"status": "confirmed", "value": read, "read": read}
                    print(f"VERIFY: {item['field']} | {item['entry']['source']}: '{read}' - every value in it is the same "
                          f"as table values you checked -> confirmed, taken off the Verify tab (S480)")

    def show_priority_stages(self):
        """S171: a Dig Packet's reading found more priority values (or one being read was
        removed) -> the priority values are built again, at once."""
        reading = {d["path"]: d for d in self.documents if d.get("kind") == "dig" and not d["removed"]
                   and d["state"] in ("waiting", "reading")}
        for path in [p for p in list(PRIORITY_STAGES) if p not in reading]:
            PRIORITY_STAGES.pop(path, None)
        seen = self.__dict__.get("priority_seen") or {}
        stages = dict(PRIORITY_STAGES)
        if {p: s["seq"] for p, s in stages.items()} == seen:
            return
        started = time.perf_counter()
        done = [d for d in self.documents if d["state"] == "done" and not d["removed"]]
        self.build_priority_values(done, document_labels(done))
        for path, stage in stages.items():
            if seen.get(path) != stage["seq"]:
                print(f"PRIORITY VALUES: {reading[path]['name']} - {PRIORITY_STAGE_NAMES[stage['stage']]} on the Verify tab "
                      f"{format_duration(time.perf_counter() - reading[path]['dropped'])} after it was dropped in "
                      f"(S171)")
        record_timing("Priority values worked out again (while reading)", time.perf_counter() - started, 1)

    # ---------- dropping / removing ----------
    def on_drop(self, event):
        messages = [m for m in (self.add_document(path) for path in self.root.tk.splitlist(event.data)) if m]
        self.message_label.configure(text="\n".join(messages))
        self.refresh_list()
        return event.action

    def add_document(self, path, came_with=None):
        """A dropped file (S214: a PDF, a picture or an email - or an email's attachment,
        came_with = the email; S320: or a 10000-35 wall thickness form workbook) goes on the list to be
        read. Returns a message when it is left out."""
        self.prepare_wheel_count_excel()                  # S289: Excel opens the calculator meanwhile
        if not path.lower().endswith((".pdf",) + IMAGE_INPUTS + EMAIL_INPUTS + WORKBOOK_INPUTS):
            return f"{os.path.basename(path)}: not a PDF, picture, email or 10000-35 form workbook - left out"
        if any(os.path.abspath(d.get("original", d["path"])) == os.path.abspath(path) for d in self.documents):
            return f"{os.path.basename(path)}: already in the list"
        document = {"id": self.next_id, "path": path, "original": path, "name": os.path.basename(path), "kind": None,
                    "status": "checking what it is...", "state": "waiting", "dropped": time.perf_counter(),
                    "seconds": None, "result": None, "removed": False,
                    "step": 0, "total": 3, "step_name": "", "waiting": False}
        self.next_id += 1
        self.documents.append(document)
        print(f"DOCUMENT ADDED: {document['name']}" + (f" (attached to {came_with})" if came_with else ""))
        self.light_jobs.put(document)
        return None

    def remove(self, document):
        document["removed"] = True
        if document.get("path"):
            FAMILY_DIG_SHEETS.pop(os.path.abspath(document["path"]), None)     # S478: its dig sheet no longer used
        if document in self.documents:
            self.documents.remove(document)
        if document["kind"] == "dig" and document["state"] != "reading":
            forget_pdf_prefetch(document["path"])     # S84: its prepared PDF work is not needed
        print(f"DOCUMENT REMOVED: {document['name']}" + (" (its reading stops at its next step)"
                                                         if document["state"] == "reading" else ""))
        if document["state"] == "done":
            self.rebuild_tabs()
        self.refresh_list()

    # ---------- background work ----------
    def light_worker(self):
        """Recognises every dropped PDF (S214: pictures and emails are made into PDFs first,
        an email's attachments added as documents); reads 6000 forms and quote requests; hands
        Dig Packets to the heavy worker. S352: what was dropped together is looked at first (a quick look at
        each PDF's text) and then read in this order: 6000 forms and quote requests (read in a moment, no
        OCR), then Dig Packets and the other documents (handed to the OCR), then 10000-35 form workbooks
        (they go in last anyway) - each group in the order it was dropped."""
        while True:
            batch = [self.light_jobs.get()]
            time.sleep(0.15)                                  # S352: the rest of a drop of several files
            while True:
                try:
                    batch.append(self.light_jobs.get_nowait())
                except queue.Empty:
                    break
            batch = [d for d in batch if not d["removed"]]
            for document in batch:
                facts = {}
                if os.path.splitext(document["original"])[1].lower() == ".pdf":
                    try:
                        with pdf_turn(f"recognising {document['name']}"):
                            document["recognised"] = classify_pdf(document["path"], facts)
                    except Exception:
                        document["recognised"] = None            # looked at again (and its error said) below
                # S468: which dig it belongs to, from its text (or its file name) - for the order below and S469
                document["queue_facts"] = queue_facts(facts.get("text"), document["original"],
                                                      (document.get("recognised") or (None, None))[0])

            def order(document):
                kind = (document.get("recognised") or (None, None))[0]
                if kind in ("6000", "quote", "report24"):          # S419: + 24-hour field reports
                    return 0
                return 2 if os.path.splitext(document["original"])[1].lower() in WORKBOOK_INPUTS else 1
            batch.sort(key=lambda d: (order(d), d["id"]))
            # S468: the Dig Packets dig by dig (dig_queue_order) - the 6000 forms dropped now or before say which first
            is_dig = lambda d: order(d) == 1 and (d.get("recognised") or (None, None))[0] in ("dig", "scan")
            forms = [d for d in batch if (d.get("recognised") or (None, None))[0] == "6000"] + [
                d for d in self.documents if d["kind"] == "6000" and not d["removed"] and all(d is not b for b in batch)]
            digs, said = dig_queue_order([d for d in batch if is_dig(d)], forms)
            ids = sorted(d["id"] for d in batch)
            batch = ([d for d in batch if order(d) == 0] + digs + [d for d in batch if order(d) == 1 and not is_dig(d)]
                     + [d for d in batch if order(d) == 2])
            for document, rank in zip(batch, ids):
                document["queue_rank"] = rank              # S468: its place in the OCR queue (heavy_put)
            if len(digs) > 1:
                print("DIG QUEUE: read dig by dig - " + " | ".join(said) + " (S468)")
            if len(batch) > 1:
                print("DOCUMENTS: read in this order - " + ", ".join(d["name"] for d in batch)
                      + " (6000 forms / quotes / 24-hour reports first, then Dig Packets dig by dig and other documents, "
                        "then 10000-35 forms - S352 / S468)")
            for document in batch:
                if not document["removed"]:
                    self.light_read(document)

    def light_read(self, document):
        """One document on the light worker (see light_worker)."""
        PROGRESS.document = document
        try:
            progress_step("Recognise the PDF")
            ending = os.path.splitext(document["original"])[1].lower()
            if ending in WORKBOOK_INPUTS:                 # S320: a 10000-35 wall thickness form
                try:
                    form = wt35_read_workbook(document["original"])
                    with pdf_turn(f"making {document['name']}'s PDF"):
                        document["path"] = wt35_form_pdf(form)
                except ValueError as exc:
                    self.events.put(("failed", document, f"not read: {exc}"))
                    return
                document["wt35"], document["kind"] = form, "wt35"
                document["total"] = len(DOCUMENT_STEPS["wt35"])
                self.events.put(("kind", document, "wt35", WT35_KIND_WHY + f" (sheet '{form['sheet']}')"))
                if any(p["photo"] for p in form["pictures"]) and self.models["state"] != "failed":
                    print(f"DOCUMENT {document['name']}: its grid has a photo - its typed text is read with "
                          f"OCR once the models are ready, alongside the Dig Packets (S320/S364)")
                    self.heavy_put(document)
                    return
                self.events.put(("status", document, "reading..."))
                self.events.put(("done", document, read_wt35_document(document, ocr=False)))
                return
            if ending in IMAGE_INPUTS:                    # S214: a picture -> a PDF of picture pages
                document["path"] = image_to_pdf(document["original"])
                print(f"DOCUMENT {document['name']}: a picture - read like a scanned PDF (S214)")
            elif ending in EMAIL_INPUTS:                  # S214: an email -> a text PDF + its attachments
                document["path"], attached = email_to_pdf(document["original"])
                print(f"DOCUMENT {document['name']}: an email - its text read like a text page"
                      + (f"; {len(attached)} attachment(s) added as documents" if attached else "") + " (S214)")
                for path in attached:
                    self.events.put(("add", path, document["name"]))
            recognised = document.pop("recognised", None)    # S352: already looked at with the rest of its drop
            if recognised is None:
                with pdf_turn(f"recognising {document['name']}"):
                    recognised = classify_pdf(document["path"])
            kind, why = recognised
            if ending in EMAIL_INPUTS and kind is not None:    # its text is read as it is, whatever it says
                kind, why = "other", "an email - its text read as it is"
            if kind is None:
                self.events.put(("failed", document, f"not read: {why}"))
                return
            document["kind"] = kind                     # set here: the next drop's check sees it
            will_wait = self.models["state"] == "loading" or any(
                d is not document and d["kind"] == "dig" and not d["removed"]
                and d["state"] in ("waiting", "reading") and queue_rank(d) < queue_rank(document)
                for d in self.documents)
            document["total"] = (DIG_STEPS_WITHOUT_NOTES_LINES + 1     # + 1 Notes line until counted
                                 + (1 if will_wait else 0)              # waiting (models / another packet)
                                 if kind == "dig" else len(DOCUMENT_STEPS[kind]))
            self.events.put(("kind", document, kind, why))
            if kind == "dig":
                # S84: a Dig Packet that has to wait - for the OCR models or for another Dig
                # Packet (they are read one at a time) - has its PDF work done meanwhile
                queue_ahead = sorted((d for d in self.documents if d is not document and d["kind"] == "dig"
                                      and not d["removed"] and d["state"] in ("waiting", "reading")
                                      and queue_rank(d) < queue_rank(document)), key=queue_rank)   # S468
                waiting_for = None
                if queue_ahead:
                    ahead = queue_ahead[-1]                   # the one read just before this one
                    start_pdf_prefetch(document["path"], f"while {queue_ahead[0]['name']} is read")
                    waiting_for = (f"Waiting for {ahead['name']} to finish ({len(queue_ahead)} Dig Packet(s) "
                                   f"ahead - they are read one at a time) - page 1 picture, map-page screening "
                                   f"and table grids")
                    progress_step(f"{waiting_for} prepared meanwhile")
                elif self.models["state"] == "loading":
                    start_pdf_prefetch(document["path"])     # PDF work alongside the model loading
                    waiting_for = "Wait for the OCR models - page 1 picture, map screening and table grids"
                    progress_step(f"{waiting_for} being prepared meanwhile")
                if waiting_for:
                    # S107 / S127: the PDF text needs no OCR - read while it waits. S353: in the second process
                    # (with the page 1 picture and the table grids), so this worker goes straight on to the next
                    # document and the PDF is not held from the packet being read
                    threading.Thread(target=self.take_early_read, args=(document, waiting_for),
                                     name="early-text-read", daemon=True).start()
                self.heavy_put(document)
                return
            if kind == "scan":                            # S213: decided after an OCR look, with the OCR models
                self.heavy_put(document)
                return
            if kind == "other":                           # S213: read with what it has
                with pdf_turn(f"looking at {document['name']}'s pages"):
                    _text_pages, picture_pages = other_document_pages(document["path"])
                if picture_pages:                         # its pictures need OCR: read after the models
                    print(f"DOCUMENT {document['name']}: {len(picture_pages)} picture page(s) - read with "
                          f"OCR once the models are ready, after any Dig Packet ahead (S213)")
                    self.heavy_put(document)
                    return
                self.events.put(("status", document, "reading..."))
                self.events.put(("done", document, read_other_document(document["path"], ocr=False)))
                return
            self.events.put(("status", document, "reading..."))
            with pdf_turn(f"reading {document['name']}"):
                result = {"6000": read_6000_document, "report24": read_report24_document}.get(   # S419
                    kind, read_quote_document)(document["path"])
            self.events.put(("done", document, result))
        except DocumentRemoved:
            print(f"DOCUMENT {document['name']}: reading stopped - it was removed with X")
        except Exception as exc:
            traceback.print_exc()
            self.events.put(("failed", document, f"reading failed: {exc}"))

    def take_early_read(self, document, waiting_for):
        """S353: a waiting Dig Packet's PDF text (map pages, dig sheet), read by the second process - taken in
        when it is ready and shown on the Verify tab straight away (S171). If it fails, the packet's reading
        reads it the normal way."""
        early = pdf_prefetched("early", document["path"])
        if document["removed"]:
            return
        if early is None:
            if document["state"] == "waiting":
                print(f"DOCUMENT {document['name']}: PDF text could not be read early - read the normal way")
            return
        document["early"] = early
        remember_dig_sheets(document["path"], early.get("Text Pages"))  # S478: for the family's other packets
        got = [k for k in ("Map Pages", "Dig Sheets") if k in early]
        if document["state"] == "waiting":
            document["step_name"] = (f"{waiting_for} prepared meanwhile"
                                     + (f"; {' and '.join(n.lower() for n in got)} already read" if got else ""))
        print(f"DOCUMENT {document['name']}: read while it waits: "
              f"{', '.join(got) or 'nothing (its map pages need OCR)'} (in the second process - S353)")
        if "Map Pages" in early:                              # S171: shown straight away
            publish_priority_stage(document["path"], early, 1)

    def heavy_put(self, document):
        """S352: a document for the OCR (heavy) worker - Dig Packets and other documents first. S364: a 10000-35
        form's photo goes to the photo reader (read alongside the Dig Packets)."""
        if document["kind"] == "wt35":
            self.photo_jobs.put(document)
            return
        self.heavy_jobs.put((0, queue_rank(document), document))       # S468: dig by dig (light_worker)

    def photo_worker(self):
        """S364: reads the 10000-35 forms' photos WHILE the Dig Packets are read, instead of after them: the
        GPU has gaps whenever the Dig Packet reading does its own work, and the photo reads fill them. In the
        OCR process a Dig Packet's call always goes before a photo's. The forms still go in last (S328). Each
        form's terminal lines are printed together when it is done. When the models are in this process (the
        OCR process could not start), the photos are read after the Dig Packets, as before (S352)."""
        self.models_done.wait()
        if not self.models_ok:
            return                                   # the window reads the forms' cells without OCR (poll)
        OCR_CALL.priority = 1
        while True:
            document = self.photo_jobs.get()
            if document["removed"]:
                continue
            if not ocr_process_used():
                self.heavy_jobs.put((1, document["id"], document))
                continue
            PROGRESS.document = document
            self.events.put(("status", document, "reading..."))
            output = []
            try:
                with held_output(output):
                    result = read_wt35_document(document)
                self.events.put(("done", document, result))
            except DocumentRemoved:
                output.append(f"DOCUMENT {document['name']}: reading stopped - it was removed with X\n")
            except Exception as exc:
                output.append(traceback.format_exc())
                self.events.put(("failed", document, f"reading failed: {exc}"))
            finally:
                sys.stdout.write("".join(output))

    def dig_paths_waiting(self, current_path):
        """S402: the Dig Packets waiting to be read (not the one being read), in the order they were dropped."""
        current = os.path.abspath(current_path) if current_path else None
        return [d["path"] for d in sorted(list(self.documents), key=queue_rank)       # S468: in the order read
                if not d["removed"] and d["kind"] == "dig" and d["state"] == "waiting" and d.get("path")
                and os.path.abspath(d["path"]) != current]

    def recognition_pending(self):
        """S352: a dropped document (not a 10000-35 workbook) still being looked at by the light worker - it may
        be a Dig Packet, which goes before a 10000-35 form's photo."""
        return any(not d["removed"] and d["kind"] is None and d["state"] == "waiting"
                   and os.path.splitext(d["original"])[1].lower() not in WORKBOOK_INPUTS for d in self.documents)

    def heavy_worker(self):
        """Loads the OCR models once, then reads Dig Packets (and S213 other documents with
        picture pages) one at a time."""
        started = time.perf_counter()
        try:
            with timed("Load OCR models"):
                load_ocr_models()
            self.events.put(("models", "ready", time.perf_counter() - started, None))
            self.models_ok = True
        except Exception as exc:
            traceback.print_exc()
            self.events.put(("models", "failed", time.perf_counter() - started, str(exc)))
            return
        finally:
            self.models_done.set()                   # S364: the photo reader can start (or stop)
        while True:
            priority, number, document = self.heavy_jobs.get()
            if document["removed"]:
                continue
            if document["kind"] == "wt35" and self.recognition_pending():
                time.sleep(0.25)                     # S352: a document still being looked at may be a Dig Packet
                self.heavy_jobs.put((priority, number, document))
                continue
            PROGRESS.document = document
            self.events.put(("status", document, "reading..."))
            try:
                if document["kind"] == "scan":               # S213: a Dig Packet, or another document?
                    progress_step("Look at page 1 (OCR)")
                    is_dig, marker = scan_is_dig_packet(document["path"])
                    document["kind"] = "dig" if is_dig else "other"
                    if is_dig:
                        document["total"] = DIG_STEPS_WITHOUT_NOTES_LINES + 1 + document["step"]
                    why = (f"page 1 read with OCR shows '{marker.title()}'" if is_dig else
                           "page 1 read with OCR shows no Dig Packet signs - read with what it has")
                    self.events.put(("kind", document, document["kind"], why))
                result = (read_dig_document(document["path"], document.get("early"))  # S64 / S107
                          if document["kind"] == "dig" else read_wt35_document(document)          # S320
                          if document["kind"] == "wt35" else read_other_document(document["path"]))   # S213
                self.events.put(("done", document, result))
            except DocumentRemoved:
                print(f"DOCUMENT {document['name']}: reading stopped - it was removed with X")
            except Exception as exc:
                traceback.print_exc()
                self.events.put(("failed", document, f"reading failed: {exc}"))

    # ---------- window side ----------
    def poll(self):
        rebuild = []
        while True:
            try:
                event = self.events.get_nowait()
            except queue.Empty:
                break
            kind = event[0]
            if kind == "models":
                _, state, seconds, error = event
                self.models.update({"state": state, "seconds": seconds, "error": error})
                print(f"OCR MODELS: {state} after {seconds:.1f} s" + (f" ({error})" if error else ""))
                continue
            if kind == "add":                                # S214: an email's attachment
                message = self.add_document(event[1], came_with=event[2])
                if message:
                    print(f"DOCUMENT {message}")
                continue
            if kind == "merged":                             # S374: a new merged PDF
                self.use_merged(event[1])
                continue
            document = event[1]
            if kind == "kind":
                document["kind"] = event[2]
                if document["state"] != "reading":     # S213: a scan decided while it is read keeps its status
                    document["status"] = (f"waiting for the OCR models" if event[2] in ("dig", "scan")
                                          and self.models["state"] == "loading" else "waiting to be read")
                print(f"DOCUMENT {document['name']}: {DOCUMENT_KIND_NAMES[event[2]]} ({event[3]})")
            elif kind == "status":
                document["status"], document["state"] = event[2], "reading"
            elif kind == "failed":
                document["status"], document["state"] = event[2], "failed"
                print(f"DOCUMENT {document['name']}: {event[2]}")
            elif kind == "done" and not document["removed"] and document["kind"] == "wt35" \
                    and self.wt35_waits_for(document):
                # S328: a 10000-35 form goes in LAST - its values wait until every 6000 form and Dig Packet is
                # read, so it is checked against all of them and nothing of it comes up to pick before
                # S471: of its own dig (wt35_waits_for)
                document["held"], document["state"] = event[2], "held"
                document["status"] = self.wt35_held_status(document)
                print(f"DOCUMENT {document['name']}: read - held until "
                      f"{', '.join(d['name'] for d in self.wt35_waits_for(document))} finish(es) (S328)")
            elif kind == "done" and not document["removed"]:
                document["result"], document["state"] = event[2], "done"
                rebuild.append(document)
        for document in self.documents:                # S328: every other document read -> the held forms go in
            if document["state"] == "held" and not document["removed"] and self.wt35_waits_for(document):
                document["status"] = self.wt35_held_status(document)      # S471: what is left, as it gets shorter
            elif document["state"] == "held" and not document["removed"]:
                document["result"], document["state"] = document.pop("held"), "done"
                rebuild.append(document)
                print(f"DOCUMENT {document['name']}: the 6000 forms and Dig Packets of its dig are read - it goes in now "
                      f"(S328/S471)")
        self.build_early_table_tabs()                  # S125
        if self.models["state"] == "failed":
            for document in self.documents:
                if document["kind"] == "wt35" and document["state"] == "waiting":   # S320: its cells still
                    document["state"] = "reading"
                    self.events.put(("done", document, read_wt35_document(document, ocr=False)))
                elif document["kind"] in ("dig", "scan", "other") and document["state"] == "waiting":   # S213
                    document["status"], document["state"] = "not read: the OCR models did not load", "failed"
        if rebuild:
            for document in rebuild:
                document["step"], document["step_name"], document["waiting"] = (
                    document["total"], "Build the tabs", False)
                document["status"] = (f"{int(100 * (document['total'] - 1) / document['total'])}%  -  step "
                                      f"{document['total']}/{document['total']}: Build the tabs")
                print(f"STEP {document['total']}/{document['total']}: Build the tabs ({document['name']})")
            self.refresh_list()
            self.root.update_idletasks()             # show 'Build the tabs' before the window is busy
            self.rebuild_tabs()
            for document in rebuild:
                document["seconds"] = time.perf_counter() - document["dropped"]
                document["status"] = f"read - tabs ready in {format_duration(document['seconds'])}"
                print("=" * 60)
                record_timing(f"DOCUMENT READY - {document['name']} ({DOCUMENT_KIND_NAMES[document['kind']]}): "
                              f"from dropping it in to its tabs ({time.perf_counter() - PROGRAM_START:.1f} s after "
                              f"the program started - S400)", document["seconds"])
                print("=" * 60)
                print_console_stats()
        self.show_priority_stages()                    # S171: after any tabs built in this update
        self.check_merged()                            # S374
        self.refresh_list()
        self.root.after(250, self.poll)

    # ---------- S374: one merged PDF of every document ----------
    def check_merged(self):
        """S374: the documents to merge changed (one recognised, removed or failed)
        -> the merged PDF is made again in the background. Not while a dropped document is still being
        recognised - so a drop of several files is merged once, not once per file (until then the Verify tab
        shows each document's own PDF)."""
        live = [d for d in self.documents if not d["removed"] and d["state"] != "failed"]
        if any(d.get("kind") is None for d in live):
            return
        documents = sorted((d for d in live if str(d.get("path", "")).lower().endswith(".pdf")), key=merged_order)
        parts = [(d["path"], f"{DOCUMENT_KIND_NAMES[d['kind']]} - {d['name']}") for d in documents]
        signature = tuple(path for path, _title in parts)
        if signature == self.merged_signature:
            return
        self.merged_signature = signature
        self.merged_count += 1
        self.merge_jobs.put((self.merged_count, parts))

    def merge_worker(self):
        """S374: makes the merged PDF - only the latest list when several are waiting."""
        while True:
            job = self.merge_jobs.get()
            while not self.merge_jobs.empty():
                job = self.merge_jobs.get_nowait()
            number, parts = job
            if not parts:
                self.events.put(("merged", None))
                continue
            os.makedirs(INPUT_FOLDER, exist_ok=True)
            out = os.path.join(INPUT_FOLDER, f"all_documents_{os.getpid()}_{number}.pdf")
            started = time.perf_counter()
            try:
                segments = build_merged_pdf(parts, out)
            except Exception as exc:
                print(f"MERGED PDF: could not be made ({exc}) - the Verify tab shows each document's own PDF (S374)")
                continue
            self.events.put(("merged", {"path": out, "segments": segments, "number": number,
                                        "pages": sum(s["count"] for s in segments.values()),
                                        "seconds": time.perf_counter() - started}))

    def use_merged(self, merged):
        """S374: the Verify tab changes over to the new merged PDF; the one before is deleted."""
        old = self.__dict__.get("merged")
        if merged is not None and old is not None and merged["number"] < old["number"]:
            return
        self.merged = merged
        if merged is not None:
            threading.Thread(target=layout_helper_ask, args=(merged["path"],), name="layout-ask",
                             daemon=True).start()       # S408: its page layout worked out ahead, in the helper
            print(f"MERGED PDF: {len(merged['segments'])} document(s), {merged['pages']} page(s) in one PDF, made in "
                  f"{merged['seconds']:.1f} s - the Verify tab shows this PDF (S374)")
        self.verify_places_changed()
        if old is not None:
            try:
                os.remove(old["path"])
            except OSError:
                pass                                   # still open somewhere - deleted when the window closes

    def wt35_held_status(self, document):
        """S471: a held 10000-35 form's status - the documents of its dig it still waits for."""
        names = [d["name"] for d in self.wt35_waits_for(document)]
        return ("read - waits for its dig's documents to finish: " + ", ".join(names[:3])
                + (f" and {len(names) - 3} more" if len(names) > 3 else "") + " (S471)")

    def wt35_waits_for(self, document):
        """S328: the documents a read 10000-35 form still waits for - every other document (not a 10000-35
        form) not yet read (a document still being recognised too). S471: only those of its own dig - sharing a
        wheel count with its file name (S468 queue_facts, as written: wheel_same), or with no wheel count known
        (it could be of any dig); a form whose name has no wheel count waits for every one, as before. So it
        joins its dig as soon as that dig is read, and the dig's WC / Clock Distances are worked out (S469)."""
        mine = self.document_wheels(document)                  # S474: or those of its 6000 form number
        return [d for d in self.documents if d is not document and not d["removed"] and d["kind"] != "wt35"
                and d["state"] in ("waiting", "reading")
                and (not mine or not self.document_wheels(d) or queue_wheels_meet(mine, self.document_wheels(d)))]

    def build_early_table_tabs(self):
        """S125 + S128: a Dig Packet whose table rows are final (the reading thread put it
        in EARLY_TABLES) gets its table-page tabs built by the window WHILE it is still being
        read - one tab per window update (every 0.25 s), and only when the reading spent at
        least half of the last moment waiting on OCR (the GPU). When the reading is busy
        with its own Python work (vote counting, snip logic, the Notes consensus) the tab
        waits for the next moment: both would only take turns. So it adapts, moment by
        moment, within the one document. The tabs stay hidden until the document is done;
        whatever was not built by then is built the usual way. A removed / failed
        document's early tabs are thrown away."""
        early = self.__dict__.setdefault("early_table_tabs", {})
        now, busy = time.perf_counter(), OCR_ACTIVITY["busy"]
        last = self.__dict__.get("ocr_tick") or (now - 0.25, busy)
        self.ocr_tick = (now, busy)
        share = (busy - last[1]) / max(1e-3, now - last[0])
        for document in self.documents:
            path = document.get("path")
            if (document.get("removed") or document.get("state") == "failed") and path in early:
                outer = early.pop(path)["outer"]
                if outer is not None:
                    self.canvas_of.pop(str(outer), None)
                    outer.destroy()
            if document.get("kind") != "dig" or document.get("removed") or path in early or path not in EARLY_TABLES:
                continue
            if document.get("state") == "done" or not any(
                    s[0] == "group" and path in s[1:] and on for s, on in self.extra_on.items()):
                if document.get("state") == "done":
                    EARLY_TABLES.pop(path, None)          # read already - its tabs are built the usual way
                continue                                  # S298: its tabs are not shown - nothing built early
            dig = EARLY_TABLES.pop(path)
            label = document_labels([d for d in self.documents if not d.get("removed")]).get(id(document), "")
            early[path] = {"prefix": f"{label}: ", "groups": table_highlight_tab_groups(dig), "built": [],
                           "stack": None, "outer": None,
                           "pictures": [], "checks": [], "refreshers": [], "waited": 0, "seconds": 0.0}
        for path, entry in early.items():
            if len(entry["built"]) >= len(entry["groups"]):
                continue
            if share < EARLY_TAB_OCR_SHARE:
                entry["waited"] += 1                      # the reading is busy itself - not now
                continue
            started = time.perf_counter()
            saved_checks, saved_refreshers = CONFIRM_STATE["checks"], CONFIRM_STATE["refreshers"]
            CONFIRM_STATE["checks"], CONFIRM_STATE["refreshers"] = entry["checks"], entry["refreshers"]
            CHECK_SCOPE["prefix"] = entry["prefix"]
            title, table_page, items, kind = entry["groups"][len(entry["built"])]
            try:
                if entry["stack"] is None:                # S216: one hidden tab, a part per group
                    entry["stack"] = self.add_stack_tab(TABLE_ROWS_TAB, show=False)
                    entry["outer"] = self.last_hidden_tab
                part = entry["stack"].add()
                if kind == "white":
                    add_white_rows_section(part, table_page, items, entry["pictures"])
                else:
                    add_table_highlights_section(part, table_page, items, entry["pictures"])
                entry["built"].append(title)
            finally:
                CONFIRM_STATE["checks"], CONFIRM_STATE["refreshers"] = saved_checks, saved_refreshers
                CHECK_SCOPE["prefix"] = ""
            entry["seconds"] += time.perf_counter() - started
            break                                         # one part per window update

    def take_early_table_tabs(self, path, wanted, dig_prefix, tab_prefix):
        """S125 + S128: shows the Table rows tab built early (S216: one tab, its first n
        parts, in order) and makes it part of the group being built; returns (n, its
        StackTab) - (0, None) when there is none or the document's names changed meanwhile
        (then it is thrown away)."""
        early = self.__dict__.get("early_table_tabs", {}).pop(path, None)
        if not early or early["outer"] is None:
            return 0, None
        built = early["built"]
        if early["prefix"] != dig_prefix or built != wanted[:len(built)]:
            self.canvas_of.pop(str(early["outer"]), None)
            early["outer"].destroy()
            print("TABLE TABS: built early, but the document's names changed meanwhile - built again")
            return 0, None
        self.notebook.add(early["outer"], text=tab_prefix + TABLE_ROWS_TAB)
        if self.__dict__.get("building") is not None:
            self.building.append(early["outer"])
        self.image_references.extend(early["pictures"])
        CONFIRM_STATE["checks"].extend(early["checks"])
        CONFIRM_STATE["refreshers"].extend(early["refreshers"])
        print(f"TABLE TABS: {len(built)} of {len(wanted)} part(s) of the {TABLE_ROWS_TAB} tab built while the Dig "
              f"Packet was still being read ({early['seconds']:.1f} s of window work, done only while the reading was "
              f"waiting on OCR; {early['waited']} moment(s) skipped because the reading was busy with its own work)"
              + (f" - the other {len(wanted) - len(built)} built now" if len(built) < len(wanted) else ""))
        return len(built), early["stack"]

    def refresh_list(self):
        models = self.models
        if models["state"] == "loading":
            text = f"OCR models: loading in the background ({format_duration(time.perf_counter() - models['started'])})"
        elif models["state"] == "ready":
            text = f"OCR models: ready (loaded in {format_duration(models['seconds'])})"
        else:
            text = f"OCR models: failed to load ({models['error']}) - Dig Packets cannot be read"
        self.models_label.configure(text=text)
        # S76: each document's row (and its X button) is made once and only its texts are
        # updated here - rows used to be destroyed and made again every 0.25 s, so a click on
        # X could land on a button that no longer existed when the mouse was released.
        rows = self.__dict__.setdefault("list_rows", {})
        present = {id(document) for document in self.documents}
        for key in [key for key in rows if key not in present]:
            rows.pop(key)["frame"].destroy()
        empty = self.__dict__.get("empty_label")
        if not self.documents:
            if empty is None or not empty.winfo_exists():
                self.empty_label = ttk.Label(self.list_frame, text="No documents yet.", foreground="#555555")
                self.empty_label.pack(pady=6)
            return
        if empty is not None and empty.winfo_exists():
            empty.destroy()
        for document in self.documents:
            row = rows.get(id(document))
            if row is None:
                frame = tk.Frame(self.list_frame, highlightbackground=BORDER_GRAY, highlightthickness=1, padx=8, pady=6)
                frame.pack(fill="x", pady=3)
                ttk.Button(frame, text="X", width=3, command=lambda d=document: self.remove(d)).pack(side="right")
                kind_label = tk.Label(frame, width=22, anchor="w", font=("Segoe UI", 10, "bold"))
                kind_label.pack(side="left")
                tk.Label(frame, text=document["name"], anchor="w", font=("Segoe UI", 10)).pack(side="left", padx=(0, 12))
                status_label = tk.Label(frame, anchor="w", wraplength=520, justify="left", font=("Segoe UI", 10))
                status_label.pack(side="left", fill="x", expand=True)
                row = rows[id(document)] = {"frame": frame, "kind": kind_label, "status": status_label}
            row["kind"].configure(text=DOCUMENT_KIND_NAMES.get(document["kind"], "?"))
            status = document["status"]
            if document["state"] in ("waiting", "reading") and document.get("step"):
                done = max(0, document["step"] - 1)
                status = (f"{int(100 * done / max(1, document['total']))}%  -  step {document['step']}/"
                          f"{document['total']}: {document['step_name']}"
                          + ("  - waiting for the other document" if document.get("waiting") else ""))
            if document["state"] in ("waiting", "reading"):
                status += f"  ({format_duration(time.perf_counter() - document['dropped'])})"
            colour = {"done": GREEN, "failed": ORANGE}.get(document["state"], "#1f4e9c")
            row["status"].configure(text=status, fg=colour)

    TAB_QUIET_SECONDS = 1.0                    # S463: nothing worked out for this long - the tab is ready

    def tab_busy_reasons(self):
        """S463: {tab id: why it is not ready ('loading' / 'waiting for Verify picks')} - a tab not in it is ready.
        Documents, each document's own tabs and Pages are made only once read - always ready."""
        reasons = {}
        reading = any(d["state"] in ("waiting", "reading", "held") for d in self.documents if not d["removed"])
        excel = self.__dict__.get("repair_excel")
        pending = any(entry.get("out") is None and entry.get("inputs")
                      for store in ("repair_results", "combined_results", "pick_results")
                      for entry in (self.__dict__.get(store) or {}).values())
        pending = pending or bool(set(self.__dict__.get("wrap_distances_asked") or ())
                                  - set(self.__dict__.get("wrap_distances") or {}))
        pending = pending or bool(set(self.__dict__.get("combined_distances_asked") or ())
                                  - set(self.__dict__.get("combined_distances") or {}))
        wc_job = self.__dict__.get("wc_jobs_running", 0) > 0
        working = wc_job or pending or bool(excel is not None and excel.busy())
        now = time.perf_counter()
        if working:
            self.tabs_quiet_since = None
        elif self.__dict__.get("tabs_quiet_since") is None:
            self.tabs_quiet_since = now
        calculating = working or now - self.tabs_quiet_since < self.TAB_QUIET_SECONDS
        picks = (self.__dict__.get("verify_hold") and self.__dict__.get("verify_view") == "compare") or any(
            "(on Verify)" in str(entry.get("out") or "") for entry in (self.__dict__.get("repair_results") or {}).values())
        # S469: every tab stays locked until every document is read (WC / Clock Distances are worked out dig by dig
        # in the background meanwhile) and the calculator is done
        if reading and self.__dict__.get("verify_tab"):
            reasons[str(self.verify_tab)] = "loading"
        for name in ("wc_tab", "main_wc_tab"):
            tab = self.__dict__.get(name)
            if tab:
                if reading or calculating:
                    reasons[str(tab)] = "loading"
                elif picks:
                    reasons[str(tab)] = "waiting for Verify picks"
        if self.__dict__.get("clock_tab") and (reading or wc_job):
            reasons[str(self.clock_tab)] = "loading"
        if self.__dict__.get("warnings_tab") and (reading or calculating):
            reasons[str(self.warnings_tab)] = "loading"
        return reasons

    def group_wait_reason(self, reasons):
        """S464: the tabs Group waits for - '' once WC Distances and Clock Distances are both made and ready. S469:
        and every document read - Group only at the very end, though WC / Clock Distances fill in dig by dig."""
        waiting = (["every document to be read"] if self.loading_documents() else []) + [
            title for name, title in (("wc_tab", "WC Distances"), ("clock_tab", "Clock Distances"))
            if not self.__dict__.get(name) or str(self.__dict__.get(name)) in reasons]
        return ", ".join(waiting)

    def lock_group_button(self, button, wait):
        """S464: a Group button greyed out (it cannot be clicked) saying what it waits for; back as it was once ready."""
        saved = self.__dict__.setdefault("group_saved", {})              # button name -> (text, colour)
        key = str(button)
        if wait:
            if key not in saved:
                saved[key] = (button.cget("text"), button.cget("bg"))
            text = f"Group (waiting for {wait})"
            if button.cget("text") != text:
                button.configure(text=text, state="disabled", bg="#9e9e9e", activebackground="#9e9e9e",
                                 disabledforeground="white")
        elif key in saved:
            text, colour = saved.pop(key)
            button.configure(text=text, state="normal", bg=colour, activebackground=colour)

    def loading_documents(self):
        """S469: the documents not read yet (waiting, being read, or held for another one)."""
        return [d for d in self.documents if not d["removed"] and d["state"] in ("waiting", "reading", "held")]

    def verify_settled_headers(self):
        """S470: the anomaly columns whose comparisons can be chosen on Verify now: every value read
        (verify_ready_headers) and, while documents are still loading, nothing more to come for its dig (dig_settled:
        no loading document names its wheel count; one whose text gave no wheel count makes every dig wait). A column
        not headed by a wheel count (a Mile Post, coordinates, Info) waits for every document."""
        ready = verify_ready_headers(self.verify_blocks)
        if not self.loading_documents():
            return ready
        return {h for h in ready if re.fullmatch(r"\d+(\.\d+)?", h) and self.dig_settled(h, ready) is None}

    def document_wheels(self, document):
        """S474: the wheel counts a document belongs to (S468 queue_facts). One with none of its own takes those of the
        other dropped documents whose file names have the same 6000 form number ('Gouge Grid #3_6000-10-237-...' gets
        100553.07 / 100572.03 from '...WC 100553.07 - 100572.03_6000-10-237-...') - matched as written, nothing
        guessed; [] when no other document shares its number (it could then be of any dig)."""
        facts = document.get("queue_facts") or {}
        if facts.get("wheels") or not facts.get("form"):
            return facts.get("wheels") or []
        sharing = [d for d in self.documents if d is not document and not d["removed"]
                   and (d.get("queue_facts") or {}).get("form") == facts["form"] and d["queue_facts"].get("wheels")]
        wheels = list(dict.fromkeys(w for d in sharing for w in d["queue_facts"]["wheels"]))
        said = self.__dict__.setdefault("wheels_borrowed_said", set())
        if wheels and (document["name"], tuple(wheels)) not in said:
            said.add((document["name"], tuple(wheels)))
            print(f"DOCUMENT {document['name']}: no wheel count in its name or text - its 6000 form number "
                  f"{facts['form']} is also on {', '.join(d['name'] for d in sharing)} - so it belongs with "
                  f"{', '.join(wheels)} (S474)")
        return wheels

    def dig_settled(self, header, ready=None):
        """S469: None when every document that can add to this anomaly (its column header, a wheel count) is read -
        else why not. Still to come: its own values from a document being read (verify_ready_headers), any
        document still loading that names this wheel count (its own, a map note's, a 6000 form's - S468
        queue_facts, as written: wheel_same), and any still loading whose text gave no wheel count at all (it
        could be about any dig, so every dig waits for it). `ready`: verify_ready_headers, when already worked out."""
        loading = self.loading_documents()
        if not loading:
            return None
        if header not in (verify_ready_headers(self.verify_blocks) if ready is None else ready):
            return "its values are still being read"
        unknown = [d["name"] for d in loading if not self.document_wheels(d)]
        naming = [d["name"] for d in loading if queue_wheels_meet([header], self.document_wheels(d))]
        names = list(dict.fromkeys(naming + unknown))
        if not names:
            return None
        return verify_names_text(names[:2]) + (f" +{len(names) - 2} more" if len(names) > 2 else "") + " to be read"

    def update_group_locks(self, reasons):
        """S464: every Group button on the Document names locked until WC Distances and Clock Distances are done
        (S469: and every document is read)."""
        wait = self.group_wait_reason(reasons)
        if wait != self.__dict__.get("group_wait"):
            print(f"GROUP: waiting for {wait} (S464/S469)" if wait else "GROUP: every document read, WC Distances and "
                  "Clock Distances done - Group can be clicked (S464/S469)")
        self.group_wait = wait
        buttons = [b for b in self.__dict__.get("group_buttons", []) if b.winfo_exists()]
        self.group_buttons = buttons                    # rows made again - their old buttons are gone
        alive = {str(b) for b in buttons}
        for key in list(self.__dict__.get("group_saved", {})):
            if key not in alive:
                self.group_saved.pop(key)
        for button in buttons:
            self.lock_group_button(button, wait)

    def update_tab_locks(self):
        """S463: every few tenths of a second - a tab still being worked out is greyed out (it cannot be opened) and
        its title says '(loading)' or '(waiting for Verify picks)'; it opens again, with its own title, once ready.
        The tab on show when it is locked goes back to Documents."""
        reasons = None
        try:
            reasons = self.tab_busy_reasons()
            saved = self.__dict__.setdefault("tab_lock_saved", {})        # tab id -> (title, picture)
            tabs = set(self.notebook.tabs())
            for tab in list(saved):
                if tab not in tabs:
                    saved.pop(tab)                      # a tab made again (Warnings) - its new one is checked anew
            for tab in tabs:
                why = reasons.get(tab)
                if why:
                    if tab not in saved:
                        saved[tab] = (self.notebook.tab(tab, "text"), self.notebook.tab(tab, "image"))
                        print(f"TABS: '{saved[tab][0] or self.__dict__.get('warnings_title', 'Warnings')}' "
                              f"locked - {why} (S463)")
                    base = saved[tab][0] or self.__dict__.get("warnings_title", "Warnings")
                    if self.notebook.tab(tab, "text") != f"{base} ({why})":
                        self.notebook.tab(tab, text=f"{base} ({why})", image="", state="disabled")
                    if self.notebook.select() == tab:
                        self.notebook.select(self.notebook.tabs()[0])
                elif tab in saved:
                    title, picture = saved.pop(tab)
                    self.notebook.tab(tab, text=title, state="normal")
                    if picture:
                        self.notebook.tab(tab, image=picture, compound="center")
                    print(f"TABS: '{title or self.__dict__.get('warnings_title', 'Warnings')}' ready (S463)")
        except Exception as exc:                        # never stops the window
            print(f"TABS: could not check which tabs are ready - {exc!r} (S463)")
        try:
            if reasons is not None:                     # S464: not worked out - the Group buttons stay as they are
                self.update_group_locks(reasons)
        except Exception as exc:
            print(f"GROUP: could not check if Group can be clicked - {exc!r} (S464)")
        self.root.after(300, self.update_tab_locks)

    def rebuild_tabs(self):
        """S86: after a document is added or removed, only the tabs that change are built
        again: the tabs of every document group (a 6000 form + its Dig Packet, a Dig
        Packet alone, a 6000 form alone, a quote) that is new or whose documents / names
        changed. Every other group keeps its
        tabs as they are - scroll position, typed corrections and all. Typed corrections
        of a group that is built again are put back for every value still shown."""
        started = time.perf_counter()
        selected = self.notebook.tab(self.notebook.select(), "text") if self.notebook.select() else None
        groups = self.__dict__.setdefault("groups", {})        # key -> its tabs, checks, refreshers, pictures

        done = [d for d in self.documents if d["state"] == "done" and not d["removed"]]
        labels = document_labels(done)
        several = len(done) > 1
        forms = [d for d in done if d["kind"] == "6000"]
        digs = [d for d in done if d["kind"] == "dig"]
        # a 6000 form goes with the Dig Packet that holds its Wheel Count (S73)
        pairs, paired_digs = [], set()
        for form in forms:
            wheel = (form["result"][1].get("Wheel Count") or {}).get("value")
            dig = next((d for d in digs if id(d) not in paired_digs
                        and wheel_count_in_dig(wheel, (d["result"] or {}).get("results"))), None)
            if dig is not None:
                paired_digs.add(id(dig))
            pairs.append((form, dig))
        pairs += [(None, d) for d in digs if id(d) not in paired_digs]
        pairs.sort(key=lambda pair: min(done.index(d) for d in pair if d is not None))
        wanted = []                                             # (key, build) in tab order
        extras = []                                             # S298: (switch key, name) for the Extra tab
        for form, dig in pairs:
            key = ("pair", id(form) if form else None, id(dig) if dig else None, several,
                   labels.get(id(form)) if form else None, labels.get(id(dig)) if dig else None)
            if dig is not None:                                 # S298: worked out here - not only with the tabs
                dig["result"]["warning"] = wheel_count_mismatch_warning(
                    dig["result"]["path"], ((form["result"][1] if form else {}).get("Wheel Count") or {}).get("value"))
            switch = ("group",) + tuple(d["path"] for d in (form, dig) if d is not None)
            extras.append((switch, " + ".join(labels[id(d)] for d in (form, dig) if d is not None)
                           + " - document tabs", extra_group_description(form, dig)))          # S301
            if not self.extra_on.get(switch):
                continue                                        # S298: not shown -> not built at all

            def build(form=form, dig=dig):
                pdf_path, extracted, notes, defects = form["result"] if form else (None, {}, [], [])
                dig_dict = dig["result"] if dig else None
                group_label = labels[id(dig)] if dig else labels[id(form)]
                show_results(pdf_path, extracted, notes, defects, dig=dig_dict, host=self,
                             tab_prefix=f"{group_label} - " if several else "",
                             form_prefix=f"{labels[id(form)]}: " if form else "",
                             dig_prefix=f"{labels[id(dig)]}: " if dig else "")
            wanted.append((key, build))
        for quote in (d for d in done if d["kind"] == "quote"):
            key = ("quote", id(quote), several, labels.get(id(quote)))
            switch = ("group", quote["path"])
            extras.append((switch, f"{labels[id(quote)]} - quote request tab",
                           "Quote request: every value read from the OmegaWrap quote request, each with its snip "
                           "of the page and a correction box."))                                 # S301
            if not self.extra_on.get(switch):
                continue

            def build(quote=quote):
                CHECK_SCOPE["prefix"] = f"{labels[id(quote)]}: "
                add_quote_section(self.add_scroll_tab((f"{labels[id(quote)]} - " if several else "")
                                                      + "Quote request"),
                                  quote["result"][0], quote["result"][1], self.image_references)
                CHECK_SCOPE["prefix"] = ""
            wanted.append((key, build))
        wanted_keys = {key for key, _build in wanted}

        CONFIRM_STATE["on_change"] = None
        typed = {}

        def drop(group):
            gone = {id(c) for c in group["checks"]}
            typed.update({c.key: c.typed_text() for c in group["checks"] if c.corrected})
            CONFIRM_STATE["checks"] = [c for c in CONFIRM_STATE["checks"] if id(c) not in gone]
            CONFIRM_STATE["refreshers"] = [r for r in CONFIRM_STATE["refreshers"] if r not in group["refreshers"]]
            for outer in group["tabs"]:
                self.canvas_of.pop(str(outer), None)
                self.notebook.forget(outer)
                outer.destroy()

        removed = [key for key in groups if key not in wanted_keys]
        for key in removed:
            drop(groups.pop(key))

        def build_group(build):
            checks_before = len(CONFIRM_STATE["checks"])
            refreshers_before = len(CONFIRM_STATE["refreshers"])
            self.building, self.image_references = [], []
            try:
                build()
            finally:
                group = {"tabs": self.building, "checks": CONFIRM_STATE["checks"][checks_before:],
                         "refreshers": CONFIRM_STATE["refreshers"][refreshers_before:],
                         "pictures": self.image_references}
                self.building = None
            return group

        built = 0
        for key, build in wanted:
            if key not in groups:
                groups[key] = build_group(build)
                built += 1
        if self.loading_documents():                   # S472: the Warnings tab is locked while documents load -
            self.warnings_args = None                   # made once, when the last one is read (not after each one:
            #                                             each time it made every warning's pictures again)
        else:
            self.refresh_warnings_tab(done, labels)       # S297: one Warnings tab for all documents
        extras += [(("pages", d["path"]), f"{labels[id(d)]} - Pages", EXTRA_PAGES_DESCRIPTION)
                   for d in done]                                                                 # S298 / S301
        if done:                                        # S313: the main wheel count tables, a tab of their own
            extras.insert(0, (("mainwc",), "Main Wheel Counts",
                              "Main Wheel Counts: one table per main wheel count (named in more than one place, or on "
                              "the Dig Packet's page 1 / the 6000 form) - the wheel counts before and after it with the "
                              "distance apart worked out by the calculator. The bold ones also stay on WC Distances."))
        self.refresh_extra_tab(extras)
        # tab order: Documents, Verify (S175), WC Distances, Warnings, Extra (S298), then the tabs switched on
        order = [self.verify_tab] + ([self.wc_tab] if self.__dict__.get("wc_tab") else [])   # S273: WC Distances
        order += [self.clock_tab] if self.__dict__.get("clock_tab") else []                  # S425: Clock Distances
        order += [self.warnings_tab] if self.__dict__.get("warnings_tab") else []            # S297
        order += [self.extra_tab]                                                             # S298
        order += [self.main_wc_tab] if self.__dict__.get("main_wc_tab") else []               # S313
        for key, _build in wanted:
            order += groups[key]["tabs"]
        new_groups = {key: groups[key] for key, _build in wanted}
        groups.clear()
        groups.update(new_groups)
        for position, outer in enumerate(order, start=1):
            self.notebook.insert(position, outer)

        restored = 0
        for check in CONFIRM_STATE["checks"]:
            text = typed.get(check.key)
            if text and check.text_widget is not None and not check.corrected:
                if isinstance(check.text_widget, tk.Text):
                    check.text_widget.insert("1.0", text)
                else:
                    check.text_widget.insert(0, text)
                check._refresh()
                restored += 1
        with timed("Priority values worked out again (Verify list + end table)", 1):
            self.build_priority_values(done, labels)       # S170
        self.refresh_page_tabs(done, labels)                # S195
        self.start_wheel_count_distances()                  # S273
        CONFIRM_STATE["on_change"] = lambda: notify_value_changed(self.update_counter)
        self.update_counter()                # S65: the comparison tables were just built - no redraw
        for tab_id in self.notebook.tabs():
            if self.notebook.tab(tab_id, "text") == selected:
                self.notebook.select(tab_id)
                break
        record_timing(f"Tabs built again: {built} document group(s) built, {len(wanted) - built} kept as they "
                      f"were, {len(removed)} removed"
                      + (f", {restored} typed correction(s) put back" if restored else ""),
                      time.perf_counter() - started)

    def update_counter(self):
        checks = CONFIRM_STATE["checks"]
        fixed = sum(1 for c in checks if c.corrected)
        self.counter_label.config(text=f"{len(checks)} values — {fixed} corrected by hand",
                                  fg=ORANGE if fixed else GREEN)

    def finish(self):
        final_results = [{"name": c.key, "value": c.final_value, "python_read": c.original,
                          "source": c.source, "page": c.page} for c in CONFIRM_STATE["checks"]]
        print_final_values(final_results)
        print_verify_summary(self.verify_items, self.verify_state, self.verify_agreed)     # S175 / S180
        self.sent_label.config(text=f"Sent to terminal at {datetime.now().strftime('%I:%M:%S %p')}")


PROFILE_RUN = True                 # S363: False = no py-spy recording of the run
PROFILE_FILE = os.path.join(os.path.expanduser("~"), "Downloads", "profile.svg")
PROFILE_STATE = {"process": None, "folders": []}     # S366: py-spy, and the Group folders made this run
PROFILE_STOP_WAIT_S = 20           # S366: how long the closing program waits for py-spy to write the profile


# S409 (measuring only): how long you waited on the Verify tab - when the first value to check came up, and your
# first click after it
VERIFY_WAIT = {"appeared": None, "field": None, "dropped": None, "clicked": None, "click": None}


def verify_wait_text():
    """S409: the wait for the first value to check and your first click, in one line."""
    appeared, clicked, dropped = VERIFY_WAIT["appeared"], VERIFY_WAIT["clicked"], VERIFY_WAIT["dropped"]
    return (f"first click ({VERIFY_WAIT['click']}) {clicked - PROGRAM_START:.1f} s after the program started"
            + (f" - {clicked - dropped:.1f} s after the first document was dropped in: {appeared - dropped:.1f} s "
               f"until the first value to check came up ({VERIFY_WAIT['field']}), then {clicked - appeared:.1f} s to "
               f"your click" if dropped else f" - {clicked - appeared:.1f} s after the first value came up")
            + " (S409)")


def gpu_memory_summary():
    """S414 (measuring only): the GPU's memory at the end - in all (nvidia-smi, comes with the NVIDIA driver) and
    each OCR process's own share now and at its highest (as its library counts it)."""
    import subprocess
    try:
        done = subprocess.run(["nvidia-smi", "--query-gpu=name,memory.used,memory.total", "--format=csv,noheader,nounits"],
                              capture_output=True, text=True, timeout=10,
                              creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        for line in done.stdout.strip().splitlines():
            name, used, total = [part.strip() for part in line.split(",")]
            print(f"GPU MEMORY: {name} - {used} of {total} MiB in use now (all programs) (S414)")
    except Exception as exc:
        print(f"GPU MEMORY: nvidia-smi could not be asked ({type(exc).__name__}: {exc}) (S414)")
    parts = []
    for role, state in OCR_PROCESSES.items():
        if state["process"] is None or state["stopped"] or not state["ready"].is_set() or state["failed"]:
            continue
        try:
            memory = ocr_process_call("mem", "report", _state=state)
        except Exception as exc:
            parts.append(f"{OCR_ROLE_NAMES[role]} could not say ({exc})")
            continue
        parts.append(f"{OCR_ROLE_NAMES[role]} - its library could not say" if memory is None else
                     f"{OCR_ROLE_NAMES[role]} {memory['now']:.0f} MiB now, {memory['peak']:.0f} MiB at most")
    if parts:
        print("GPU MEMORY per OCR process (its own library's count; the driver adds a few hundred MiB each): "
              + "; ".join(parts) + " (S414)")


FINAL_TIMES = []                   # S398/S399: (anomaly, seconds from the program's start, clock) per Group click


def print_final_times():
    """S399: the last lines of the run - each Group click's time from the program's start."""
    for header, seconds, clock in FINAL_TIMES:
        record_timing(f"FINAL TIME: program start -> Group clicked ({header}) at {clock:%I:%M:%S %p} (S398)", seconds)
    if not FINAL_TIMES:
        print("FINAL TIME: Group was not clicked this run (S398)")
    if VERIFY_WAIT["clicked"] is not None:                # S409
        print("VERIFY WAIT: " + verify_wait_text())
    elif VERIFY_WAIT["appeared"] is not None:
        print(f"VERIFY WAIT: the first value to check came up {VERIFY_WAIT['appeared'] - PROGRAM_START:.1f} s after "
              f"the program started; no click after it (S409)")
    ocr_run_summary()                                     # S400
    pdf_turn_summary()                                    # S406
    gpu_memory_summary()                                  # S414


def finish_profile():
    """S366: when the window closes - py-spy is asked to stop (as Ctrl+C would) while the program is still
    running, so it writes profile.svg now; it is then copied into every Group folder made this run (the one
    in Downloads stays). py-spy cannot be asked from a helper started at the end: with --subprocesses it
    would follow that helper too and wait for it. If py-spy does not stop in time, it writes the profile by
    itself once the program has closed - in Downloads only."""
    process = PROFILE_STATE["process"]
    if process is None:
        return
    import signal
    try:
        if os.name == "nt":
            os.kill(process.pid, signal.CTRL_BREAK_EVENT)        # its own process group (see the start)
        else:
            process.send_signal(signal.SIGINT)
        process.wait(timeout=PROFILE_STOP_WAIT_S)
    except Exception as exc:
        print(f"PROFILE: py-spy did not stop when asked ({type(exc).__name__}: {exc}) - it writes {PROFILE_FILE} by "
              f"itself once the program has closed; not copied into the Group folders (S366)")
        return
    if not os.path.isfile(PROFILE_FILE):
        print(f"PROFILE: py-spy stopped but {PROFILE_FILE} was not written (S366)")
        return
    folders = [f for f in dict.fromkeys(PROFILE_STATE["folders"]) if os.path.isdir(f)]
    for folder in folders:
        shutil.copy2(PROFILE_FILE, os.path.join(folder, "profile.svg"))
    print(f"PROFILE: {PROFILE_FILE} written" + (f" and copied into {len(folders)} Group folder(s)" if folders else "")
          + " (S366)")


def start_profile_recording():
    """S363: py-spy records this run by itself - started here, it follows this program (and the OCR / PDF
    helper processes it starts) and writes PROFILE_FILE (Downloads\\profile.svg, the last run's replaced) when
    the window is closed. Only `python data.py` is needed. Without py-spy installed, the run goes on as
    usual."""
    if not PROFILE_RUN:
        return
    import subprocess
    import sysconfig
    candidates = [shutil.which("py-spy")]
    for scheme in (f"{os.name}_user", None):           # pip's user Scripts folder (not on PATH), then the main one
        try:
            folder = sysconfig.get_path("scripts", scheme) if scheme else sysconfig.get_path("scripts")
        except KeyError:
            continue
        candidates.append(os.path.join(folder, "py-spy.exe" if os.name == "nt" else "py-spy"))
    program = next((c for c in candidates if c and os.path.isfile(c)), None)
    if program is None:
        print("PROFILE: py-spy not found (pip install py-spy) - this run is not recorded (S363)")
        return
    try:
        # S366: in its own process group, so the closing program can ask it (alone) to stop and write
        PROFILE_STATE["process"] = subprocess.Popen(
            [program, "record", "-o", PROFILE_FILE, "--subprocesses", "--pid", str(os.getpid())],
            creationflags=getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        print(f"PROFILE: py-spy is recording this run - {PROFILE_FILE} is written when the window is closed, and "
              f"copied into any Group folder made (S363/S366)")
    except Exception as exc:
        print(f"PROFILE: py-spy could not be started ({type(exc).__name__}: {exc}) - this run is not recorded "
              f"(S363)")


# S470: WHEN THE PROGRAM IS CLOSED BY A CRASH. A crash inside one of the compiled libraries (PDF, OpenCV, Tk, OCR) or
# Windows running out of memory ends the program with no Python error, so the terminal shows nothing. Python's own
# crash reporter (faulthandler) then writes where the crashing thread was (S489) to crash_log.txt next to data.py;
# and every MEMORY_LOG_SECONDS a line says how much memory the program and Windows have - in the terminal and in
# crash_log.txt (the terminal's last few seconds of text can be lost in a crash; that file is written at once).
CRASH_LOG_NAME = "crash_log.txt"
MEMORY_LOG_SECONDS = 30
CRASH_LOG = {"file": None}


class ProcessMemoryCounters(ctypes.Structure):
    """S470: Windows' PROCESS_MEMORY_COUNTERS (K32GetProcessMemoryInfo)."""
    _fields_ = [("cb", wintypes.DWORD), ("PageFaultCount", wintypes.DWORD),
                ("PeakWorkingSetSize", ctypes.c_size_t), ("WorkingSetSize", ctypes.c_size_t),
                ("QuotaPeakPagedPoolUsage", ctypes.c_size_t), ("QuotaPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t), ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                ("PagefileUsage", ctypes.c_size_t), ("PeakPagefileUsage", ctypes.c_size_t)]


class MemoryStatusEx(ctypes.Structure):
    """S470: Windows' MEMORYSTATUSEX (GlobalMemoryStatusEx)."""
    _fields_ = [("dwLength", wintypes.DWORD), ("dwMemoryLoad", wintypes.DWORD),
                ("ullTotalPhys", ctypes.c_ulonglong), ("ullAvailPhys", ctypes.c_ulonglong),
                ("ullTotalPageFile", ctypes.c_ulonglong), ("ullAvailPageFile", ctypes.c_ulonglong),
                ("ullTotalVirtual", ctypes.c_ulonglong), ("ullAvailVirtual", ctypes.c_ulonglong),
                ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]


def crash_log_write(text):
    """S470: a line into crash_log.txt, written to the disk at once (it survives a crash)."""
    log = CRASH_LOG["file"]
    if log is not None:
        try:
            log.write(text + "\n")
            log.flush()
        except (OSError, ValueError):
            pass


def start_crash_log():
    """S470: Python's crash reporter on, writing into crash_log.txt next to data.py (each run adds to the end)."""
    import faulthandler
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), CRASH_LOG_NAME)
    try:
        CRASH_LOG["file"] = open(path, "a", encoding="utf-8")
        crash_log_write(f"\n===== run started {datetime.now():%m/%d/%Y %H:%M:%S} (process {os.getpid()}) =====")
        # S489: only the thread the error happened in - on Windows every handled error Excel sends back (e.g. 'busy,
        # try again') is reported here too, and walking the other threads while they keep running crashed the program
        faulthandler.enable(file=CRASH_LOG["file"], all_threads=False)
        print(f"CRASH LOG: if a crash closes the program, where it happened is written to {path} (S470/S489)")
    except OSError as exc:
        print(f"CRASH LOG: {path} could not be opened ({exc}) - a crash would not be written down (S470)")


def memory_line():
    """S470: the memory line - this program (its private memory: what Windows has promised it, and RAM it uses now /
    at most so far) and Windows (RAM free; commit left - when that reaches 0, programs crash). None off Windows."""
    try:
        process = ProcessMemoryCounters()
        process.cb = ctypes.sizeof(process)
        kernel32 = ctypes.windll.kernel32
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE
        kernel32.K32GetProcessMemoryInfo.argtypes = [wintypes.HANDLE, ctypes.POINTER(ProcessMemoryCounters),
                                                     wintypes.DWORD]
        if not kernel32.K32GetProcessMemoryInfo(kernel32.GetCurrentProcess(), ctypes.byref(process), process.cb):
            return None
        status = MemoryStatusEx()
        status.dwLength = ctypes.sizeof(status)
        if not kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
            return None
    except (AttributeError, OSError):
        return None
    gb = lambda value: f"{value / 1024 ** 3:.1f} GB"
    return (f"MEMORY: this program {gb(process.PagefileUsage)} private, {gb(process.WorkingSetSize)} in RAM (most so "
            f"far {gb(process.PeakWorkingSetSize)}) | Windows: {gb(status.ullAvailPhys)} of {gb(status.ullTotalPhys)} "
            f"RAM free, {gb(status.ullAvailPageFile)} of {gb(status.ullTotalPageFile)} commit left "
            f"({status.dwMemoryLoad}% of RAM in use) (S470)")


def start_memory_log():
    """S470: the memory line every MEMORY_LOG_SECONDS, from the start to the end of the run."""
    def loop():
        while True:
            line = memory_line()
            if line is None:
                return
            print(line)
            crash_log_write(f"{datetime.now():%H:%M:%S} {line}")
            time.sleep(MEMORY_LOG_SECONDS)

    threading.Thread(target=loop, name="memory-log", daemon=True).start()


def main():
    start_buffered_console()
    start_crash_log()                                     # S470: a crash's place written down
    start_memory_log()                                    # S470: memory every 30 s
    start_profile_recording()                             # S363: py-spy follows this run by itself
    maps_live_start()                                     # S357: Edge for the Google Maps lookups, opened now
    window = DocumentsWindow()
    window.root.mainloop()
    excel = window.__dict__.get("wc_excel")               # S289: Excel opened early and never used - closed
    if excel is not None:
        excel.stop()
    repair_excel = window.__dict__.get("repair_excel")    # S296: the repair lengths' copy closed and deleted
    if repair_excel is not None:
        repair_excel.stop()
    for name in os.listdir(INPUT_FOLDER) if os.path.isdir(INPUT_FOLDER) else []:    # S374: the merged PDFs
        if name.startswith(f"all_documents_{os.getpid()}_"):
            try:
                os.remove(os.path.join(INPUT_FOLDER, name))
            except OSError:
                pass
    finish_profile()                                      # S366: py-spy writes now; copied into the Group folders
    print_final_times()                                   # S399: the whole run's time, last - under PROFILE


if __name__ == "__main__":
    main()